window.ATLAS = {"milestones": [{"year": -209, "label": "Mete"}, {"year": 552, "label": "Göktürk"}, {"year": 630, "label": "Batı Göktürk"}, {"year": 744, "label": "Uygur"}, {"year": 840, "label": "Karahanlı"}, {"year": 963, "label": "Gazneli"}, {"year": 1040, "label": "Selçuklu"}, {"year": 1071, "label": "Malazgirt"}, {"year": 1096, "label": "Haçlı"}, {"year": 1206, "label": "Moğol"}, {"year": 1243, "label": "Kösedağ"}, {"year": 1299, "label": "Osmanlı"}, {"year": 1402, "label": "Ankara"}, {"year": 1453, "label": "İstanbul"}, {"year": 1514, "label": "Çaldıran"}, {"year": 1517, "label": "Mısır"}, {"year": 1526, "label": "Babür"}, {"year": 1571, "label": "İnebahtı"}, {"year": 1683, "label": "Viyana"}, {"year": 1699, "label": "Karlofça"}, {"year": 1774, "label": "Küçük Kaynarca"}, {"year": 1839, "label": "Tanzimat"}, {"year": 1911, "label": "Trablusgarp"}, {"year": 1922, "label": "Saltanat"}], "states": [{"id": "okuma", "name": "Bu atlas nasıl okunur", "short": "Okuma", "region": "giris", "start": -280, "end": -120, "capital": "", "religion": "", "confidence": "kayit", "summary": "Yakınlaştırmak ayrıntıyı açar, sürüklemek gezdirir. Sayfa kaymaz.", "essay": ["Bu tuval, geleneksel anlatıda ilk Türk hükümdarı sayılan Teoman’dan son Osmanlı padişahı VI. Mehmed Vahdeddin’e kadar kurulan ve dağılan siyasi yapıları tek yüzeyde toplar.", "Türk devleti burada, hanedanı Türk diline veya Türk siyasal geleneğine bağlanan yapılar için kullanılır. Halk, dil ve hanedan her zaman örtüşmez. Hunların ve Avrupa Avarlarının dili akademik olarak kapanmamıştır: Türkçe, İranî, Moğolca ve Yenisey dilleri önerilmiştir. 2025’te yayımlanan bir çalışma, Xiongnu ve Avrupa Hun çekirdeği için Yenisey ailesinden eski bir Arin dili önermiştir. Bu iddia tartışmayı kapatmaz. O devletler haritada durur ve tartışmalı aidiyet damgası taşır. Dili kendi yazıtlarıyla sabit olan ilk büyük kağanlık Göktürk Kağanlığı’dır (552).", "Oğuz Kağan ve Ergenekon destandır, devlet değildir. Rivayet kutusu, Sima Qian gibi eski anlatılar ile sonradan eklenen ders kitabı cümlelerini ayırır. Mete’ye mal edilen “Toprak milletindir” sözü Çin kaynağındaki cümle değildir.", "Kayıt suskunsa isim uydurulmaz. Eş, çocuk ve savaş listeleri adı geçenlerin listesidir. Tarihçilerin çatıştığı yıl kartta iki ihtimal olarak durur. 1299, Osmanlı beyliğinin simgesel kuruluş yılıdır. Halil İnalcık, bağımsız hanedan eşiğini 27 Temmuz 1302 Bapheus zaferine bağlar.", "İlhanlılar Moğol hanedanıdır, son döneminde Türkleşmiştir. Safevî ve Babür hanedanları Türk kökenlidir; yönetim dilleri Farsça ve Hint dünyasıyla iç içedir. Memlüklerde Bahri dönem Kıpçak Türk, Burci dönem Çerkestir.", "Eski ders kitaplarındaki duraklama-gerileme-dağılma merdiveni burada dönem adı olarak kullanılmaz. Kaynak omurgası TDV İslâm Ansiklopedisi ve çelişki halinde ayrıca gösterilen literatürdür."], "sources": [{"title": "TDV, Osman I", "url": "https://islamansiklopedisi.org.tr/osman-i"}, {"title": "Britannica, Xiongnu", "url": "https://www.britannica.com/topic/Xiongnu"}], "rulers": []}, {"id": "asya-hun", "name": "Asya Hun Devleti", "short": "Asya Hun", "aliases": ["Büyük Hun Devleti", "Xiongnu", "Hsiung-nu", "Asya Hun İmparatorluğu"], "region": "bozkir", "start": -220, "end": 216, "startNote": "Teoman'ın MÖ 220 civarında tahta çıktığı kabulü Türk tarih yazımının geleneksel başlangıcıdır. Çin kayıtları Touman'ı MÖ 3. yüzyılın sonuna yerleştirir.", "endNote": "MS 48'de kuzey ve güney olarak ikiye ayrıldı. Kuzey kolu 2. yüzyılda dağıldı; güney kolu Han vasalı olarak sürdü ve 216 yılında Cao Cao tarafından şanyülük makamı kaldırılarak beş idari bölgeye bağlandı.", "capital": "Orhun ve Selenge havzası, mevsimlik yaylak ve kışlaklar; dinî merkez Longcheng (Ejder Kenti)", "religion": "Gök Tanrı inancı, atalar kültü, kamlık", "confidence": "tartismali", "confidenceNote": "Siyasi varlığı Çin ve bozkır arkeolojisiyle kesindir. Yönetici hanedanın ve tebaanın konuştuğu dil konusunda Türk, Yenisey, İrani veya çok dilli karma yapı tezleri tartışmalıdır.", "summary": "MÖ 3. yüzyıl sonunda Moğolistan bozkırında boylar konfederasyonu olarak kurulan ve Mete döneminde Çin'e denk bir imparatorluğa dönüşen ilk büyük bozkır devleti. MÖ 200 Baideng kuşatmasıyla Han hanedanını vergiye bağladılar; onlu askerî teşkilat ve şanyü idaresi Avrasya göçebe devletlerine model oldu. İç taht kavgaları, iklim felaketleri ve Han baskısıyla önce MÖ 54'te doğu-batı, MS 48'de ise kuzey-güney olarak parçalandılar.", "legacy": "Onlu askerî teşkilat, şanyü unvanı, ıslıklı ok ve Çin ile heqin (barış ve akrabalık) antlaşması modeli bozkır devlet geleneğinin temelini oluşturdu. Göktürkler ve sonraki Türk devletleri kendilerini bu siyasi mirasın devamı saydı.", "essay": ["Asya Hun Devleti (Xiongnu), İç Asya bozkırlarında merkezi bir konfederasyon halinde ortaya çıkan ve Çin kaynaklarında ayrıntılı biçimde belgelenen ilk büyük göçebe imparatorluktur. MÖ 3. yüzyıl sonlarında Sarı Irmak kıvrımındaki (Ordos) kışlaklar ile Moğolistan'ın kuzeyindeki yaylaklar arasında hareket eden boylar, Qin hanedanı generali Meng Tian'ın MÖ 215 seferiyle kuzeye püskürtülmüştü. Bu dış baskı, dağınık bozkır kabilelerinin şanyü Teoman etrafında toplanmasını hızlandırdı.", "Teoman'ın ardından MÖ 209'da tahta geçen oğlu Mete (Modu), doğudaki Donghu (Doğu Hu) birliğini imha edip güneydeki Yüeçileri Kansu'dan batıya sürdü. Baykal gölünden Tibet yaylalarına, Mançurya'dan Aral gölüne kadar uzanan sahada yirmi altı kavim ve şehir devletini tek bir çatı altında topladı. MÖ 200'de Baideng Muharebesi'nde Han imparatoru Gaozu'yu kuşatan Mete, Çin'i doğrudan ilhak etmek yerine ipek, tahıl, altın ve prenses karşılığında vergiye bağlayan 'heqin' (barış ve akrabalık) sistemini kurdu. Bu diplomatik düzenleme sonraki yüzyıllarda bozkır ile yerleşik dünya arasındaki temel ilişki biçimi haline geldi.", "Hun idari yapısı boylar konfederasyonunun hiyerarşik bir askeri teşkilata dönüştürülmesine dayanıyordu. Şanyü (Chengli Gutu Chanyu / Göğün Oğlu Ulu Hükümdar) en üst otoriteydi; ülke Sol (Doğu) ve Sağ (Batı) olmak üzere ikili teşkilatla yönetilirdi. Sol ve Sağ Bilge Krallar (Tuki / Tuqi) genellikle şanyünün en büyük oğulları veya kardeşleri arasından seçilir, Sol Bilge Kral veliaht sayılırdı. Ordu tümen, bin, yüz ve on sistemine göre teşkilatlandırılmıştı. Her yılın ilk, beşinci ve dokuzuncu aylarında Longcheng'de (Ejder Kenti) toplanan kurultaylarda boy beyleri sayım yapar, kurbanlar sunar ve savaş kararları alırdı.", "MÖ 2. yüzyılın ikinci yarısında Han hanedanı imparatoru Wu (Wu Di), savunma siyasetini terk ederek Hunlara karşı kapsamlı bir taarruz başlattı. MÖ 119'daki Mobei Muharebesi'nde Çin orduları Gobi çölünü geçerek Hun merkezini sarstı. Savaşlar, salgın hastalıklar ve süregelen kuraklıklar konfederasyonun ekonomik omurgasını zayıflattı. MÖ 60'larda başlayan taht mücadeleleri sonucunda imparatorluk MÖ 54 civarında ikiye bölündü: Çin'e tabi olmayı savunan Huhanye güneye indi; bağımsızlığı savunan ağabeyi Çi-çi (Zhizhi) ise batıya, Isık Göl ve Talas boylarına çekilerek burada müstahkem bir şehir kurdu. Çi-çi'nin MÖ 36'da Çin ordusunca kuşatılarak öldürülmesiyle Hunlar yeniden Huhanye soyunda birleşti.", "MS 1. yüzyılın başlarında Wang Mang'ın Çin tahtını gasp etmesi ve Hun unvanlarını düşürmeye çalışmasıyla ilişkiler yeniden savaşa dönüştü. Huduershidaogao döneminde Hunlar Çin iç savaşından faydalanarak kuzey sınırlarını yeniden yağmaladılar. Ancak 46 yılındaki şiddetli kuraklık, çekirge istilası ve sürü ölümleri devleti derinden sarstı. Veraset kavgasında dışlanan Bi'nin (Sutuhu) sekiz güney boyunu alarak 48'de Han hanedanına sığınmasıyla imparatorluk kesin ve kalıcı olarak Kuzey Hunları ve Güney Hunları olmak üzere ikiye parçalandı."], "sources": [{"title": "TDV İslâm Ansiklopedisi, TÜRK", "url": "https://islamansiklopedisi.org.tr/turk"}, {"title": "TDV İslâm Ansiklopedisi, HAN", "url": "https://islamansiklopedisi.org.tr/han--hukumdar"}, {"title": "Britannica, Xiongnu", "url": "https://www.britannica.com/topic/Xiongnu"}, {"title": "Wikipedia, Chanyu", "url": "https://en.wikipedia.org/wiki/Chanyu"}, {"title": "Wikipedia, Han–Xiongnu Wars", "url": "https://en.wikipedia.org/wiki/Han%E2%80%93Xiongnu_wars"}], "rulers": [{"id": "asya-hun-teoman", "name": "Teoman", "aliases": ["Touman", "T'ou-man"], "title": "Şanyü (Tanhu)", "birth": null, "birthNote": "Doğum yılı Çin kayıtlarında yok", "death": -209, "deathNote": "Oğlu Mete'nin (Modu) emriyle öldürüldü", "reign": [-220, -209], "reignNote": "MÖ 220 geleneksel yıldır. Çin kaynakları MÖ 3. yüzyıl sonunu işaret eder.", "summary": "Çin kaynaklarındaki Touman, Xiongnu konfederasyonunun bilinen ilk şanyüsüdür. Doğu Hu ve Yüeçi baskısı altındaki boyları bir arada tuttu. Veliahtı Mete'yi Yüeçilere rehin verip ardından tahtı diğer eşinin oğluna bırakmak istemesi darbeyle sonuçlandı.", "traits": ["Konfederasyonu derleyip toplayan ilk bilinen şanyü"], "contribution": "Dağınık boyları tek şanyü otoritesi altında anılan siyasi bir gövdeye çevirdi.", "harm": "Veliaht krizini oğlunun darbesine kadar büyüttü. Rehine siyaseti hanedan içi kanlı tasfiyeyle bitti.", "wives": [{"name": "Adı Çin kayıtlarında geçmeyen bir eş", "note": "Mete'den olmayan küçük oğlunu veliaht yapmak istediği söylenir.", "certainty": "olasi"}], "children": [{"name": "Mete (Modu)", "mother": "", "note": "Veliahtken babasını devirip tahtı ele geçirdi.", "certainty": "kesin"}, {"name": "Adı geçmeyen küçük oğul", "mother": "", "note": "Veliaht yapılmak istendiği anlatılır, MÖ 209 darbesinde öldürüldü.", "certainty": "olasi"}], "wars": [{"name": "Yüeçi ve Doğu Hu baskısı", "when": "MÖ 3. yüzyıl sonu", "foe": "Yüeçiler, Donghu", "result": "belirsiz", "note": "Teoman'ın bu komşular karşısında gerilediği ve Ordos'tan çekildiği ima edilir."}], "legends": ["Türk ders kitaplarındaki 'Çin Seddi Teoman'dan korunmak için yapıldı' cümlesi aşırı sadedir. Qin surları MÖ 3. yüzyılda, Xiongnu baskısıyla birlikte ama daha geniş bir sınır siyasetinin parçası olarak birleştirilmiştir.", "Bazı popüler metinler Teoman'ı Oğuz Kağan'ın babası Kara Han ile bir tutar. Bu özdeşleştirme destansıdır, tarih kaydı değildir."], "sources": [{"title": "TDV İslâm Ansiklopedisi, TÜRK", "url": "https://islamansiklopedisi.org.tr/turk"}, {"title": "Britannica, Xiongnu", "url": "https://www.britannica.com/topic/Xiongnu"}]}, {"id": "asya-hun-mete", "name": "Mete", "aliases": ["Modu", "Mao-tun", "Mòdú Chānyú", "Batur"], "title": "Şanyü", "birth": null, "birthNote": "Yaklaşık MÖ 234 önerilir, kesin değildir", "death": -174, "deathNote": "Britannica saltanatı yaklaşık MÖ 209-174 verir", "reign": [-209, -174], "reignNote": "MÖ 209'da babasını devirerek tahta çıktı.", "summary": "Modu, babasını öldürterek şanyü oldu. Doğu Hu'yu dağıttı, Yüeçileri batıya sürdü, Dingling ve diğer 26 boyu bağladı. MÖ 200'de Baideng'de Han imparatoru Gaozu'yu kuşattı. Ardından heqin antlaşmasıyla Çin, Hunlara yıllık vergi ve prenses gönderdi.", "traits": ["Onlu teşkilat kurucusu olarak anılır", "Merkezi bozkır otoritesini fiilen kuran hükümdar"], "contribution": "Xiongnu'yu Çin'e denk bir imparatorluk haline getirdi. Onlu birlik düzeni bozkır ordularının klasik modeli oldu.", "harm": "Babasını ve üvey kardeşini öldürterek taht aldı. Çin'e kesintisiz akın, sınır boylarında sürekli tahribat yarattı.", "wives": [], "children": [{"name": "Laoshang (Jiyu / Ki-ok)", "mother": "", "note": "Halefi.", "certainty": "kesin"}], "wars": [{"name": "Doğu Hu seferi", "when": "MÖ 209 civarı", "foe": "Donghu", "result": "zafer", "note": "Shiji anlatır; Donghu konfederasyonu tamamen ezildi."}, {"name": "Yüeçi seferi", "when": "MÖ 209-177 arası", "foe": "Yüeçiler", "result": "zafer", "note": "Yüeçiler Kansu bölgesinden batıya çekilmek zorunda kaldı."}, {"name": "Baideng kuşatması", "when": "MÖ 200", "foe": "Han imparatoru Gaozu", "result": "zafer", "note": "İmparator yedi gün kuşatıldı, ardından heqin antlaşması yapıldı."}], "legends": ["Islık çalan ok talimi Sima Qian'ın Shiji eserindedir. Önce atını, sonra karısını, sonra babasının atını vurmayanları öldürdüğü sahne öğretici bir kurgu gibi okunmalıdır. Çekirdek, mutlak itaatle darbeyi anlattığı için tamamen atılmaz ama ayrıntı rivayettir.", "“Toprak milletindir, onu kimse veremez” cümlesi modern Türkçe ders anlatısıdır. Shiji'de Modu, Doğu Hu elçisine toprak talebini reddederken toprağın devletin temeli olduğunu söyler. Ders kitabındaki vecize birebir alıntı değildir.", "Türk Kara Kuvvetleri'nin kuruluşunu MÖ 209'a bağlamak modern bir simgedir, o yıl kurulmuş bir kurum kaydı değildir.", "Modu ile destandaki Oğuz Kağan arasında kurulan özdeşlik, hayat hikâyelerinin benzerliğinden türetilmiş bir yorumdur, kanıtlanmış kimlik değildir."], "sources": [{"title": "TDV İslâm Ansiklopedisi, TÜRK", "url": "https://islamansiklopedisi.org.tr/turk"}, {"title": "Britannica, Xiongnu", "url": "https://www.britannica.com/topic/Xiongnu"}]}, {"id": "asya-hun-laoshang", "name": "Laoshang", "aliases": ["Jiyu", "Ki-ok", "Kiyok", "Lao-shang", "Chi-yü"], "title": "Şanyü", "birth": null, "birthNote": "kayıtlarda yok", "death": -161, "deathNote": "MÖ 161'de öldü.", "reign": [-174, -161], "reignNote": "Mete'nin ardından tahta geçti.", "summary": "Mete'nin oğlu ve halefidir. Yüeçileri kesin hezimete uğratıp krallarının kafatasından kadeh yaptırmış, Kansu ve Tarım havzasını tamamen Hun kontrolüne almıştır. Çin ile heqin antlaşmasını yenilemiş, Çin sarayından gelen hadım Zhonghang Yue'nin danışmanlığında Hun geleneklerini korumaya çalışmıştır.", "traits": ["Yüeçilere karşı kesin zafer", "Gelenekçi bozkır siyaseti"], "contribution": "Tarım havzasını ve İpek Yolu güzergâhını Hun hâkimiyetine aldı.", "harm": "MÖ 166 ve 165'te Han başkenti Chang'an yakınlarına kadar uzanan yıkıcı akınlar açtı.", "wives": [{"name": "Çin imparatorluk prensesi", "note": "Han İmparatoru Wen tarafından gönderilen gelin.", "certainty": "kesin"}], "children": [{"name": "Junchen", "mother": "", "note": "Halefi.", "certainty": "kesin"}], "wars": [{"name": "Yüeçi kesin imha seferi", "when": "MÖ 174-162 arası", "foe": "Yüeçiler", "result": "zafer", "note": "Yüeçi kralı öldürüldü, kafatası kadeh yapıldı; Yüeçiler Baktriya'ya sürüldü."}, {"name": "Chang'an akınları", "when": "MÖ 166-165", "foe": "Han hanedanı (İmparator Wen)", "result": "zafer", "note": "Hun süvarileri başkente birkaç mil mesafeye kadar indi, saray yazlıklarını yaktı."}], "legends": ["Yüeçi kralının kafatasından kadeh yapılması Shiji'de yer alan ve sonraki Çin heyetlerince teyit edilen bozkır ritüelidir."], "sources": [{"title": "TDV İslâm Ansiklopedisi, TÜRK", "url": "https://islamansiklopedisi.org.tr/turk"}, {"title": "Britannica, Xiongnu", "url": "https://www.britannica.com/topic/Xiongnu"}, {"title": "Wikipedia, Laoshang Chanyu", "url": "https://en.wikipedia.org/wiki/Laoshang_Chanyu"}]}, {"id": "asya-hun-junchen", "name": "Junchen", "aliases": ["Chün-ch'en", "Kün-çin", "Jun-chen"], "title": "Şanyü", "birth": null, "birthNote": "kayıtlarda yok", "death": -126, "deathNote": "MÖ 126'da öldü.", "reign": [-161, -126], "reignNote": "Laoshang'ın ardından tahta geçti.", "summary": "Laoshang'ın oğlu. 35 yılı aşan saltanatında Han İmparatorları Wen, Jing ve Wu dönemlerini gördü. Başlangıçta heqin barışı sürse de Han İmparatoru Wu'nun MÖ 133'te Mayi'de kurduğu 300.000 kişilik tuzaktan kurtulmasının ardından Han-Hun savaşları fiilen yeniden başladı.", "traits": ["Uzun saltanat", "Mayi pususunu fark eden dikkat"], "contribution": "Mayi tuzağını zamanında anlayıp ordusunu imhadan kurtardı.", "harm": "MÖ 129'dan itibaren Wei Qing komutasındaki Han ordularının Ordos ve Longcheng akınları Hun kayıplarını başlattı.", "wives": [], "children": [{"name": "Yudan", "mother": "", "note": "Sol Bilge Kral iken amcası Yizhixie tarafından tahttan uzaklaştırıldı, Çin'e sığındı.", "certainty": "kesin"}], "wars": [{"name": "Mayi tuzağı", "when": "MÖ 133", "foe": "Han hanedanı", "result": "zafer", "note": "Junchen yakalanan bir Han muhafızından pusuyu öğrenip ordusunu geri çekti."}, {"name": "Ordos ve sınır muharebeleri", "when": "MÖ 129-127", "foe": "Han generali Wei Qing", "result": "yenilgi", "note": "Han ordusu Ordos bölgesindeki Loufan ve Bayan boylarını sürdü."}], "legends": [], "sources": [{"title": "TDV İslâm Ansiklopedisi, TÜRK", "url": "https://islamansiklopedisi.org.tr/turk"}, {"title": "Wikipedia, Junchen Chanyu", "url": "https://en.wikipedia.org/wiki/Junchen_Chanyu"}]}, {"id": "asya-hun-yizhixie", "name": "Yizhixie", "aliases": ["İ-çih-sie", "Ichisye"], "title": "Şanyü", "birth": null, "birthNote": "kayıtlarda yok", "death": -114, "deathNote": "MÖ 114'te öldü.", "reign": [-126, -114], "reignNote": "Junchen'in kardeşi. Yeğeni Yudan'ı devre dışı bırakarak tahta çıktı.", "summary": "Junchen'in kardeşi. Han İmparatoru Wu'nun en sert askeri taarruzları döneminde hükümdarlık yaptı. MÖ 119'daki Mobei Muharebesi'nde Wei Qing ve Huo Qubing ordularına karşı büyük bir meydan savaşı verdi; ağır kayıplar üzerine Hun merkezini Gobi çölünün kuzeyine taşımak zorunda kaldı.", "traits": ["Savaşçı direnç", "Çöl ötesi çekilme stratejisi"], "contribution": "MÖ 119 Mobei hezimetine rağmen ordusunun çekirdeğini kurtarıp devleti ayakta tuttu.", "harm": "Mobei'de on binlerce savaşçı ve yüz binlerce binek hayvanı kaybedildi; Gobi'nin güneyi tamamen elden çıktı.", "wives": [], "children": [{"name": "Wuwei", "mother": "", "note": "Halefi.", "certainty": "kesin"}, {"name": "Xulihu", "mother": "", "note": "Sonraki şanyü.", "certainty": "kesin"}, {"name": "Qiedihou", "mother": "", "note": "Sonraki şanyü.", "certainty": "kesin"}], "wars": [{"name": "Mobei Muharebesi", "when": "MÖ 119", "foe": "Han generalleri Wei Qing ve Huo Qubing", "result": "yenilgi", "note": "Hun ordusu kuşatmayı yarıp kaçtı ancak Gobi güneyindeki hâkimiyet çöktü."}], "legends": [], "sources": [{"title": "Wikipedia, Yizhixie Chanyu", "url": "https://en.wikipedia.org/wiki/Yizhixie_Chanyu"}, {"title": "Wikipedia, Battle of Mobei", "url": "https://en.wikipedia.org/wiki/Battle_of_Mobei"}]}, {"id": "asya-hun-wuwei", "name": "Wuwei", "aliases": ["Wu-wei"], "title": "Şanyü", "birth": null, "birthNote": "kayıtlarda yok", "death": -105, "deathNote": "MÖ 105'te öldü.", "reign": [-114, -105], "reignNote": "Yizhixie'nin ardından tahta geçti.", "summary": "Yizhixie'nin oğlu. Han sarayının tabi olma ve veliaht gönderme baskılarını kararlılıkla reddetti. MÖ 119 sonrasının yorgunluğu nedeniyle iki taraf da büyük bir meydan savaşına girmese de sınır boylarında yıpratma akınları sürdü.", "traits": ["Bağımsızlıkta ısrar"], "contribution": "Çin'in vasallık şartlarını reddederek egemenliği korudu.", "harm": "Ticaret yollarının kapalı kalması ekonomik sıkıntıları artırdı.", "wives": [], "children": [{"name": "Er (Wushilu)", "mother": "", "note": "Halefi.", "certainty": "kesin"}], "wars": [{"name": "Sınır yıpratma çatışmaları", "when": "MÖ 112-107", "foe": "Han hanedanı", "result": "belirsiz", "note": "İki taraf da büyük çaplı harekâttan kaçındı."}], "sources": [{"title": "Wikipedia, Chanyu", "url": "https://en.wikipedia.org/wiki/Chanyu"}]}, {"id": "asya-hun-er", "name": "Er", "aliases": ["Wushilu", "Çocuk Şanyü"], "title": "Şanyü", "birth": null, "birthNote": "kayıtlarda yok", "death": -102, "deathNote": "Genç yaşta hastalıktan öldü.", "reign": [-105, -102], "reignNote": "Çocuk yaşta tahta çıktığı için Çin yıllıklarında Er (Çocuk) Şanyü olarak kaydedilmiştir.", "summary": "Wuwei'nin oğlu. Küçük yaşta tahta geçti. Han generali Zhao Ponu'nun inşa ettiği Shouxiang Kalesi üzerine yürüdü ve MÖ 103'te Zhao Ponu'nun 20.000 kişilik kuvvetini kuşatarak generali esir aldı. Erken ölümü tahtı amcalarına geçirdi.", "traits": ["Genç yaşta atılganlık"], "contribution": "MÖ 103'te Han ordusunu kuşatarak kumandanını esir aldı.", "harm": "Erken ölümü hanedan içi taht kaymalarına yol açtı.", "wives": [], "children": [], "wars": [{"name": "Shouxiang Kalesi Kuşatması", "when": "MÖ 103", "foe": "Han generali Zhao Ponu", "result": "zafer", "note": "Zhao Ponu esir alındı, Han ordusu dağıtıldı."}], "sources": [{"title": "Wikipedia, Chanyu", "url": "https://en.wikipedia.org/wiki/Chanyu"}]}, {"id": "asya-hun-xulihu", "name": "Xulihu", "aliases": ["Goulihu"], "title": "Şanyü", "birth": null, "birthNote": "kayıtlarda yok", "death": -101, "deathNote": "MÖ 101'de hastalıktan öldü.", "reign": [-102, -101], "reignNote": "Er Şanyü'nün amcası, Wuwei'nin kardeşi.", "summary": "Er Şanyü'nün amcası. Tahta geçtikten sonra Han sınır kalelerine taarruz etti, ancak bir yıl içinde hastalanarak hayatını kaybetti.", "traits": [], "contribution": "Han sınır tahkimatlarını yıprattı.", "harm": "Çok kısa saltanatı istikrar sağlamaya yetmedi.", "wives": [], "children": [], "wars": [{"name": "Dingxiang akını", "when": "MÖ 102", "foe": "Han hanedanı", "result": "zafer", "note": "Sınır garnizonları tahrip edildi."}], "sources": [{"title": "Wikipedia, Chanyu", "url": "https://en.wikipedia.org/wiki/Chanyu"}]}, {"id": "asya-hun-qiedihou", "name": "Qiedihou", "aliases": ["Chedihou"], "title": "Şanyü", "birth": null, "birthNote": "kayıtlarda yok", "death": -96, "deathNote": "MÖ 96'da öldü.", "reign": [-101, -96], "reignNote": "Xulihu'nun kardeşi.", "summary": "Xulihu'nun kardeşi. Han elçisi Su Wu'yu Hun geleneklerine uymadığı ve saray darbesi tertibine karıştığı gerekçesiyle Baykal gölü civarında gözaltında tuttu. MÖ 99'da Han generali Li Ling'in 5.000 kişilik seçkin piyade birliğini Tanrı Dağları eteklerinde imha etti ve teslim olan Li Ling'i kızlarından biriyle evlendirip hizmetine aldı.", "traits": ["Diplomatik kararlılık", "Düşman komutanlarını bünyesine katma"], "contribution": "MÖ 99'da Li Ling ordusunu imha etti ve Çin'in sınır baskısını hafifletti.", "harm": "Su Wu'nun alıkonulması Han ile diplomatik köprüleri uzun süre kopardı.", "wives": [], "children": [{"name": "Hulugu", "mother": "", "note": "Halefi.", "certainty": "kesin"}], "wars": [{"name": "Tian Shan (Tanrı Dağları) Muharebesi", "when": "MÖ 99", "foe": "Han generali Li Ling", "result": "zafer", "note": "Okları tükenen Li Ling teslim oldu ve Hun hizmetine girdi."}], "legends": ["Su Wu'nun Baykal gölünde koyun güderken 19 yıl boyunca imparatorluk asasını bırakmaması Çin edebiyatında sadakat simgesi olmuştur."], "sources": [{"title": "Wikipedia, Chanyu", "url": "https://en.wikipedia.org/wiki/Chanyu"}]}, {"id": "asya-hun-hulugu", "name": "Hulugu", "aliases": ["Hu-lu-ku"], "title": "Şanyü", "birth": null, "birthNote": "kayıtlarda yok", "death": -85, "deathNote": "MÖ 85'te öldü.", "reign": [-96, -85], "reignNote": "Qiedihou'nun oğlu.", "summary": "Qiedihou'nun oğlu. MÖ 90'da 70.000 kişilik ordusuyla saldıran ünlü Han başkumandanı Li Guangli'yi (İmparator Wu'nun kayınbiraderi) tuzağa düşürerek esir aldı. Saraydaki entrikalar ve şaman kehanetleri sonucunda Li Guangli'yi kurban ettirdi.", "traits": ["Büyük meydan zaferi", "Şamanik inançlara bağlılık"], "contribution": "Li Guangli'nin 70.000 kişilik ordusunu imha ederek Han hanedanına ağır bir darbe vurdu.", "harm": "Li Guangli'nin kurban edilmesi Hun sarayında huzursuzluğa yol açtı.", "wives": [], "children": [{"name": "Huyandi", "mother": "", "note": "Halefi.", "certainty": "kesin"}, {"name": "Xulüquanqu", "mother": "", "note": "Sonraki şanyü.", "certainty": "kesin"}], "wars": [{"name": "Yanzhishan Muharebesi", "when": "MÖ 90", "foe": "Han başkumandanı Li Guangli", "result": "zafer", "note": "Li Guangli teslim oldu, 70.000 kişilik ordu imha edildi."}], "sources": [{"title": "Wikipedia, Chanyu", "url": "https://en.wikipedia.org/wiki/Chanyu"}]}, {"id": "asya-hun-huyandi", "name": "Huyandi", "aliases": ["Hu-yen-ti"], "title": "Şanyü", "birth": null, "birthNote": "kayıtlarda yok", "death": -68, "deathNote": "MÖ 68'de öldü.", "reign": [-85, -68], "reignNote": "Hulugu'nun ardından tahta geçti.", "summary": "Hulugu'nun oğlu. Han hanedanının Usunlar ile kurduğu ittifak karşısında zorlandı. MÖ 71'de Han ve Usun müşterek ordusunun saldırısına uğradı; ardından gelen şiddetli kış ve tipi sonucu nüfusunun ve sürülerinin önemli bir kısmını kaybetti.", "traits": [], "contribution": "Han diplomasisine karşı direnmeye çalıştı.", "harm": "MÖ 71-70 afetleri ve Usun yenilgisi Hun ekonomik gücünü çökertti, boylar isyana başladı.", "wives": [], "children": [], "wars": [{"name": "Usun ve Han ortak taarruzu", "when": "MÖ 71", "foe": "Usunlar ve Han ordusu", "result": "yenilgi", "note": "Hunlar 40.000 esir ve 700.000 baş hayvan kaybetti."}], "sources": [{"title": "Wikipedia, Chanyu", "url": "https://en.wikipedia.org/wiki/Chanyu"}]}, {"id": "asya-hun-xuluquanqu", "name": "Xulüquanqu", "aliases": ["Hsu-lü-ch'üan-ch'ü"], "title": "Şanyü", "birth": null, "birthNote": "kayıtlarda yok", "death": -60, "deathNote": "MÖ 60'ta hastalıktan öldü.", "reign": [-68, -60], "reignNote": "Huyandi'nin kardeşi.", "summary": "Huyandi'nin kardeşi. Çin ile bozulan ilişkileri onarmak ve barış yapmak istedi, ancak resmi anlaşma sağlanamadan hastalanarak öldü. Ölümü boy beyleri arasında iktidar kavgasını tetikledi.", "traits": ["Barışçı diplomasi arayışı"], "contribution": "Bozkırda iç çekişmeleri yatıştırmaya çalıştı.", "harm": "Veraseti netleştiremeden ölmesi iç savaşı başlattı.", "wives": [{"name": "Zhuanqu Yanzhi", "note": "Kocasının ölümünden sonra sevgilisi Tuqitang'ı (Woyanqudi) tahta çıkardı.", "certainty": "kesin"}], "children": [{"name": "Huhanye (Jihoushan)", "mother": "", "note": "Sonraki şanyü.", "certainty": "kesin"}, {"name": "Zhizhi (Hutuwusi)", "mother": "", "note": "Sonraki şanyü.", "certainty": "kesin"}], "wars": [], "sources": [{"title": "Wikipedia, Chanyu", "url": "https://en.wikipedia.org/wiki/Chanyu"}]}, {"id": "asya-hun-woyanqudi", "name": "Woyanqudi", "aliases": ["Tuqitang"], "title": "Şanyü", "birth": null, "birthNote": "kayıtlarda yok", "death": -58, "deathNote": "MÖ 58'de yenilgi üzerine intihar etti.", "reign": [-60, -58], "reignNote": "Yizhixie'nin torun çocuğu. Saray darbesiyle tahta geçti.", "summary": "Xulüquanqu'nun dul eşinin desteğiyle usulsüz biçimde tahta geçti. Eski şanyünün yakınlarını ve soylu beyleri idam ettirerek terör estirdi. Wushanmu ve boy beylerinin desteğini alan Jihoushan (Huhanye) karşısında yenilerek intihar etti.", "traits": ["Baskıcı ve zalim yönetim"], "contribution": "", "harm": "Hanedan içi tasfiyeleriyle boyları isyana sürükledi, Hun birliğini paramparça etti.", "wives": [], "children": [], "wars": [{"name": "Huhanye ayaklanması", "when": "MÖ 58", "foe": "Huhanye ve Wushanmu", "result": "yenilgi", "note": "Ordusu dağıldı, Woyanqudi intihar etti."}], "sources": [{"title": "Wikipedia, Chanyu", "url": "https://en.wikipedia.org/wiki/Chanyu"}]}, {"id": "asya-hun-huhanye", "name": "Huhanye", "aliases": ["Ho-han-ye", "Jihoushan", "I. Huhanye"], "title": "Şanyü", "birth": null, "birthNote": "kayıtlarda yok", "death": -31, "deathNote": "MÖ 31'de öldü.", "reign": [-58, -31], "reignNote": "MÖ 58'de Woyanqudi'yi devirdi; MÖ 54'ten sonra güneyde Han himayesinde hüküm sürdü.", "summary": "Woyanqudi'yi devirerek tahta çıktı ancak kardeşi Çi-çi ile taht kavgasına girdi. Yenilince güneye inerek MÖ 53'te Han İmparatoru Xuan'a tabi oldu. Çin desteğiyle toparlanıp MÖ 43'te tekrar kuzeye döndü. MÖ 33'te Chang'an'ı ziyaret ederek ünlü saray nedimesi Wang Zhaojun ile evlendi.", "traits": ["Çin diplomasisiyle tahtı koruma", "Pragmatizm"], "contribution": "Çin yardımı ve heqin bağıyla halkını kıtlıktan kurtardı, parçalanmış güney boylarını toparladı.", "harm": "Bozkır bağımsızlık geleneğini terk edip Han hanedanına vassallık sundu; kardeşiyle çatışması ülkeyi böldü.", "wives": [{"name": "Wang Zhaojun (Ninghu Yanzhi)", "note": "Çin'in 'Dört Güzeli'nden biri; imparatorun sarayından gönderilen nedime.", "certainty": "kesin"}, {"name": "Da Yanzhi", "note": "Fuzhulei ve Souxie'nin annesi.", "certainty": "kesin"}, {"name": "Zhuanqu Yanzhi", "note": "Juya ve Wuzhuliu'nun annesi.", "certainty": "kesin"}, {"name": "Diwu Yanzhi", "note": "Huduershidaogao'nun annesi.", "certainty": "kesin"}], "children": [{"name": "Fuzhulei Ruodi", "mother": "Da Yanzhi", "note": "Halefi.", "certainty": "kesin"}, {"name": "Souxie", "mother": "Da Yanzhi", "note": "Sonraki şanyü.", "certainty": "kesin"}, {"name": "Juya", "mother": "Zhuanqu Yanzhi", "note": "Sonraki şanyü.", "certainty": "kesin"}, {"name": "Wuzhuliu", "mother": "Zhuanqu Yanzhi", "note": "Sonraki şanyü.", "certainty": "kesin"}, {"name": "Wulei", "mother": "Da Yanzhi", "note": "Sonraki şanyü.", "certainty": "kesin"}, {"name": "Huduershidaogao", "mother": "Diwu Yanzhi", "note": "Sonraki şanyü.", "certainty": "kesin"}, {"name": "Yituzhiyashi", "mother": "Wang Zhaojun", "note": "Wang Zhaojun'dan doğan oğlu.", "certainty": "kesin"}], "wars": [{"name": "Hun İç Savaşı (Çi-çi ile mücadele)", "when": "MÖ 56-51", "foe": "Çi-çi (Zhizhi)", "result": "yenilgi", "note": "Huhanye yenilerek güneye çekildi ve Han'a tabi oldu."}], "legends": ["Wang Zhaojun'un saray ressamı Mao Yanshou'ya rüşvet vermediği için çirkin çizildiği ve bu yüzden Hun hükümdarına gönderildiği hikâyesi Çin edebiyatında yaygın bir anlatıdır."], "sources": [{"title": "TDV İslâm Ansiklopedisi, TÜRK", "url": "https://islamansiklopedisi.org.tr/turk"}, {"title": "Wikipedia, Huhanye", "url": "https://en.wikipedia.org/wiki/Huhanye"}]}, {"id": "asya-hun-zhizhi", "name": "Çi-çi", "aliases": ["Zhizhi", "Chih-chih", "Hutuwusi"], "title": "Şanyü", "birth": null, "birthNote": "kayıtlarda yok", "death": -36, "deathNote": "MÖ 36'da Han ordusunca kuşatıldığı Talas'taki kalesinde öldürüldü.", "reign": [-56, -36], "reignNote": "Huhanye'ye rakip şanyü; bağımsızlığı savunup batıya çekildi.", "claim": true, "summary": "Huhanye'nin ağabeyi; kardeşinin Çin'e tabi olmasına karşı çıkarak bağımsızlık bayrağını açtı. Dingling ve Yenisey Kırgızlarını (Jiankun) bağladı, ardından Kangju (Kanglı) hükümdarıyla ittifak yaparak Talas havzasına göç etti. Burada kurduğu tahkimli şehir MÖ 36'da Han generali Chen Tang tarafından kuşatıldı; savaşarak öldü.", "traits": ["Tavizsiz bağımsızlık anlayışı", "Batıya göç stratejisi", "Müstahkem kale savunması"], "contribution": "Bozkır egemenliğini ve bağımsızlık bilincini Orta Asya içlerine taşıdı; Kırgızları ve Dinglingleri bağladı.", "harm": "Kangju ile arasını bozup müttefiklerini kaybetti; göçebe hareketliliğini terk edip surlu kalede kuşatılmaya düşerek hayatını ve ordusunu kaybetti.", "wives": [{"name": "Kangju prensesi", "note": "Kangju kralının kızı.", "certainty": "kesin"}], "children": [{"name": "Juqu Liushou", "mother": "", "note": "Çin'e rehin gönderilmiş, MÖ 44'te geri verilmişti.", "certainty": "kesin"}], "wars": [{"name": "Kuzey seferleri (Dingling ve Kırgız)", "when": "MÖ 49-48", "foe": "Dinglingler, Usunlar, Jiankun (Kırgızlar)", "result": "zafer", "note": "Tüm bu boyları kendine bağladı ve merkezini Kırgız yurduna taşıdı."}, {"name": "Zhizhi Muharebesi (Talas Kuşatması)", "when": "MÖ 36", "foe": "Han generalleri Chen Tang ve Gan Yanshou", "result": "yenilgi", "note": "Surlarla çevrili kale düşürüldü, Çi-çi başı kesilerek öldürüldü."}], "legends": ["Çi-çi'nin kalesini savunan askerlerin 'balık pulu şeklinde kalkan düzeni' kullanması sebebiyle bunların Carrhae Muharebesi'nden kaçan Romalı lejyonerler olduğu tezi ileri sürülmüş, ancak bu iddia tarihçiler arasında tartışmalı kalmıştır."], "sources": [{"title": "TDV İslâm Ansiklopedisi, TÜRK", "url": "https://islamansiklopedisi.org.tr/turk"}, {"title": "Wikipedia, Zhizhi Chanyu", "url": "https://en.wikipedia.org/wiki/Zhizhi_Chanyu"}]}, {"id": "asya-hun-fuzhulei", "name": "Fuzhulei Ruodi", "aliases": ["Diaotaomogao", "Fu-chu-lei"], "title": "Şanyü", "birth": null, "birthNote": "kayıtlarda yok", "death": -20, "deathNote": "MÖ 20'de öldü.", "reign": [-31, -20], "reignNote": "Huhanye'nin ardından tahta geçti.", "summary": "Huhanye'nin oğlu. Bozkır levirat geleneği gereği üvey annesi Wang Zhaojun ile evlendi. Han hanedanı ile barış ve ticaret ilişkilerini devam ettirdi.", "traits": ["Barışçı politika"], "contribution": "Çin ile barış ve sınır pazarlarını koruyarak refah sağladı.", "harm": "", "wives": [{"name": "Wang Zhaojun", "note": "Babasının dul eşi; levirat geleneğiyle evlendi.", "certainty": "kesin"}], "children": [{"name": "Yun (Prenses Yimuo)", "mother": "Wang Zhaojun", "note": "Sonraki dönemde Hun-Çin diplomasisinde etkili oldu.", "certainty": "kesin"}, {"name": "Dangyu", "mother": "Wang Zhaojun", "note": "Kızı.", "certainty": "kesin"}], "wars": [], "sources": [{"title": "Wikipedia, Chanyu", "url": "https://en.wikipedia.org/wiki/Chanyu"}, {"title": "Wikipedia, Wang Zhaojun", "url": "https://en.wikipedia.org/wiki/Wang_Zhaojun"}]}, {"id": "asya-hun-souxie", "name": "Souxie", "aliases": ["Jumixu"], "title": "Şanyü", "birth": null, "birthNote": "kayıtlarda yok", "death": -12, "deathNote": "MÖ 12'de hastalıktan öldü.", "reign": [-20, -12], "reignNote": "Fuzhulei'nin kardeşi.", "summary": "Fuzhulei'nin kardeşi. Han sarayına elçi gönderip dostluğu sürdürdü. Chang'an'a giderken yolda hastalanarak öldü.", "traits": [], "contribution": "Han ile barışı korudu.", "harm": "", "wives": [], "children": [], "wars": [], "sources": [{"title": "Wikipedia, Chanyu", "url": "https://en.wikipedia.org/wiki/Chanyu"}]}, {"id": "asya-hun-juya", "name": "Juya", "aliases": ["Jumoju"], "title": "Şanyü", "birth": null, "birthNote": "kayıtlarda yok", "death": -8, "deathNote": "MÖ 8'de öldü.", "reign": [-12, -8], "reignNote": "Souxie'nin kardeşi.", "summary": "Souxie'nin kardeşi. Dört yıllık saltanatında barışçıl ilişkiler devam etti.", "traits": [], "contribution": "Sınır sükûnetini sürdürdü.", "harm": "", "wives": [], "children": [], "wars": [], "sources": [{"title": "Wikipedia, Chanyu", "url": "https://en.wikipedia.org/wiki/Chanyu"}]}, {"id": "asya-hun-wuzhuliu", "name": "Wuzhuliu", "aliases": ["Nangzhiyasi", "Wu-chu-liu"], "title": "Şanyü", "birth": null, "birthNote": "kayıtlarda yok", "death": 13, "deathNote": "MS 13'te öldü.", "reign": [-8, 13], "reignNote": "Huhanye'nin oğlu, Juya'nın kardeşi.", "summary": "Huhanye'nin oğlu. 21 yıl hüküm sürdü. MS 9'da Çin tahtını gasp eden Wang Mang'ın Hun mührünü değiştirmesi ve devleti 15 şanyüye bölme girişimleri üzerine ilişkileri kesti. Kuzey Çin'e büyük akınlar düzenleyerek Wang Mang ordularını hezimete uğrattı.", "traits": ["Milli haysiyete bağlılık", "Askerî karşılık"], "contribution": "Wang Mang'ın Hunları 15 küçük parçaya bölme tuzağını boşa çıkardı ve askeri üstünlüğü yeniden kurdu.", "harm": "Uzun süren sınır savaşları kuzey halklarını yıprattı.", "wives": [], "children": [{"name": "Sutuhu (Bi)", "mother": "", "note": "Güney Hun Devleti'nin kurucusu.", "certainty": "kesin"}, {"name": "Mo (Qiufu Youdi)", "mother": "", "note": "Sonraki Güney şanyüsü.", "certainty": "kesin"}], "wars": [{"name": "Wang Mang sınır savaşları", "when": "MS 10-13", "foe": "Xin hanedanı (Wang Mang)", "result": "zafer", "note": "Kuzey Çin garnizonları tahrip edildi, Wang Mang barış aramak zorunda kaldı."}], "sources": [{"title": "TDV İslâm Ansiklopedisi, TÜRK", "url": "https://islamansiklopedisi.org.tr/turk"}, {"title": "Wikipedia, Chanyu", "url": "https://en.wikipedia.org/wiki/Chanyu"}]}, {"id": "asya-hun-wulei", "name": "Wulei", "aliases": ["Xian", "Wu-lei"], "title": "Şanyü", "birth": null, "birthNote": "kayıtlarda yok", "death": 18, "deathNote": "MS 18'de öldü.", "reign": [13, 18], "reignNote": "Wuzhuliu'nun kardeşi.", "summary": "Wuzhuliu'nun kardeşi. Wang Mang ile diplomatik manevralar yaptı ancak sınır çatışmaları durmadı. Beş yıl hüküm sürdükten sonra öldü.", "traits": [], "contribution": "Wang Mang'a karşı denge siyaseti güttü.", "harm": "", "wives": [], "children": [], "wars": [], "sources": [{"title": "Wikipedia, Chanyu", "url": "https://en.wikipedia.org/wiki/Chanyu"}]}, {"id": "asya-hun-huduershi", "name": "Huduershidaogao", "aliases": ["Yu", "Hu-du-er-şi"], "title": "Şanyü", "birth": -34, "birthNote": "Yaklaşık MÖ 34 doğumlu olduğu tahmin edilir.", "death": 46, "deathNote": "MS 46'da yaklaşık 80 yaşında öldü.", "reign": [18, 46], "reignNote": "Wulei'nin ardından tahta geçti.", "summary": "28 yıl süren saltanatında Çin'deki iç savaştan faydalanarak Hun askeri gücünü en üst noktaya çıkardı. Sarı Irmak kıyılarını ve Kuzey Çin eyaletlerini yağmaladı. Doğu Han imparatoru Guangwu'ya denk hükümdar muamelesi dayattı. Ölümüne yakın veliahtlığı kendi oğullarına geçirerek Bi'yi dışladı.", "traits": ["Otoriter ve saldırgan yönetim", "Hanedan verasetini değiştirme"], "contribution": "Hun askeri üstünlüğünü ve bağımsızlığını Çin'e yeniden kabul ettirdi.", "harm": "Ağabeylerinin oğullarını verasetten dışlayarak MS 48'deki büyük bölünmenin tohumlarını attı.", "wives": [], "children": [{"name": "Wudadihou", "mother": "", "note": "Halefi.", "certainty": "kesin"}, {"name": "Punu", "mother": "", "note": "Kuzey Hun şanyüsü.", "certainty": "kesin"}], "wars": [{"name": "Kuzey Çin akınları", "when": "MS 28-45", "foe": "Doğu Han hanedanı (İmparator Guangwu)", "result": "zafer", "note": "Han ordusu sınır komutanlıklarından çekilmek zorunda kaldı."}], "sources": [{"title": "TDV İslâm Ansiklopedisi, TÜRK", "url": "https://islamansiklopedisi.org.tr/turk"}, {"title": "Wikipedia, Huduershidaogao Chanyu", "url": "https://en.wikipedia.org/wiki/Huduershidaogao_Chanyu"}]}, {"id": "asya-hun-wudadihou", "name": "Wudadihou", "aliases": ["Wu-da-ti-hou"], "title": "Şanyü", "birth": null, "birthNote": "kayıtlarda yok", "death": 46, "deathNote": "MS 46'da tahta çıktıktan birkaç ay sonra öldü.", "reign": [46, 46], "reignNote": "Huduershidaogao'nun oğlu.", "summary": "Huduershidaogao'nun oğlu. Tahta çıktıktan birkaç ay sonra öldü. Yerine kardeşi Punu geçti.", "traits": [], "contribution": "", "harm": "", "wives": [], "children": [], "wars": [], "sources": [{"title": "Wikipedia, Chanyu", "url": "https://en.wikipedia.org/wiki/Chanyu"}]}, {"id": "asya-hun-punu", "name": "Punu", "aliases": ["P'u-nu"], "title": "Şanyü", "birth": null, "birthNote": "kayıtlarda yok", "death": 75, "deathNote": "Ölüm yılı yaklaşık MS 75 olarak tahmin edilir.", "reign": [46, 48], "reignNote": "MS 46'da birleşik devletin başına geçti; MS 48'de bölünmeden sonra Kuzey Hun şanyüsü olarak devam etti.", "summary": "Wudadihou'nun kardeşi. Saltanatının başında bozkırda büyük bir kuraklık ve çekirge afeti baş gösterdi, hayvanların çoğu kırıldı. Yeğeni/kuzeni Bi'nin Çin ile yakınlaşmasını cezalandırmak istedi ancak Bi 48'de sekiz güney boyuyla ayrılarak Güney Hun Devleti'ni kurdu.", "traits": [], "contribution": "Kuzey bozkırındaki boyların bağımsızlığını korumaya çalıştı.", "harm": "Kriz yönetiminde başarısız kalarak imparatorluğun bölünmesini engelleyemedi.", "wives": [], "children": [], "wars": [{"name": "Bi ile taht çekişmesi", "when": "MS 47-48", "foe": "Bi (Sutuhu)", "result": "yenilgi", "note": "Punu'nun gönderdiği birlikler Bi'nin ordusu karşısında çekildi; devlet ikiye bölündü."}], "sources": [{"title": "TDV İslâm Ansiklopedisi, TÜRK", "url": "https://islamansiklopedisi.org.tr/turk"}, {"title": "Wikipedia, Punu Chanyu", "url": "https://en.wikipedia.org/wiki/Punu_Chanyu"}]}]}, {"id": "guney-hun", "name": "Güney Hun Devleti", "short": "Güney Hun", "aliases": ["Güney Hiung-nu", "Nan Xiongnu", "Güneyli Hunlar", "Güney Hunları"], "region": "bozkir", "start": 48, "end": 216, "startNote": "MS 48'de sekiz güney boyunun reisleri Bi'yi (Sutuhu) şanyü ilan edip Han hanedanına sığındı.", "endNote": "216'da Cao Cao, son şanyü Huchuquan'ı Ye şehrinde alıkoyup şanyülük makamını resmen lağvetti; Hunları beş kola (Wu Bu) ayırdı.", "capital": "Meiji (Xihe bölgesi, bugünkü İç Moğolistan ve Shanxi sınırı)", "religion": "Gök Tanrı inancı, atalar kültü; zamanla Çin kültürel ve dinî etkileri", "confidence": "kayit", "confidenceNote": "Doğu Han ve Üç Krallık dönemi Çin yıllıklarıyla (Hou Hanshu, Sanguozhi) teyit edilmiştir.", "summary": "MS 48'de taht çekişmesi ve kıtlık sonucu Han hanedanına bağlanan sekiz boyun kurduğu güney birliğidir. Çin Seddi boyunca tampon güç ve sınır muhafızı olarak yerleştirildiler. Kuzey Hunlarına karşı Han ordusuyla birlikte seferlere katıldılar; 216 yılında Cao Cao tarafından şanyülük unvanı kaldırılarak beş idari bölgeye bölündüler.", "legacy": "Çin içine yerleşen Güney Hun zümreleri, IV. yüzyıldaki 'Beş Barbar' (Wu Hu) ayaklanmasında Liu Yuan önderliğinde Han-Zhao (Önceki Zhao) devletini kurarak Çin tarihinde kalıcı iz bıraktı.", "essay": ["Güney Hun Devleti, Asya Hun İmparatorluğu'nun MS 48'deki nihai bölünmesiyle ortaya çıktı. Huduershidaogao'nun veraset sırasını bozarak tahtı kendi oğullarına bırakması ve ardından bozkırı kasıp kavuran ağır kuraklık, boylar arasındaki çatlağı büyüttü. Wuzhuliu'nun oğlu olan ve güney sınır boylarını yöneten Bi (Sutuhu), sekiz boyun desteğiyle büyük dedesi Huhanye'nin unvanını (II. Huhanye) alarak kendini şanyü ilan etti ve Doğu Han imparatoru Guangwu'ya bağlandı.", "Han sarayı, Güney Hunlarını Ordos bozkırı ile Çin Seddi arasındaki Xihe bölgesine (Meiji merkezli) yerleştirdi. Bu yerleşimle Hunlar hem Çin'in tahıl ve ipek yardımlarıyla geçinen bir sınır muhafızı hem de Kuzey Hunlarına karşı ileri bir askerî tampon haline geldiler. Çin sarayı şanyünün yanına bir 'şanyü koruyucusu' (Da Sima / Wu-huan Xiaowei) atayarak bozkır aristokrasisini sıkı bir bürokratik gözetim altında tuttu.", "Güney Hun orduları, Han generalleriyle birlikte Kuzey Hunlarına karşı düzenlenen büyük seferlerde öncü süvari gücü olarak savaştı. Özellikle 89 yılındaki İh Bayan (Altay Dağları) Seferi'nde şanyü Tuntuhe, Han generali Dou Xian ile birlikte Kuzey Hunlarını ezerek kuzeydeki siyasi birliğin çökmesinde belirleyici rol oynadı.", "Ancak Çin'in artan idari tahakkümü, zorunlu asker toplama talepleri ve yerel Çinli memurların suiistimalleri zaman zaman büyük isyanlara yol açtı. 94'te Anguo'nun isyanı, 140'ta Juqu Wusi ayaklanması ve şanyü Xiuli'nin intiharı, ardından 188'de Xiuchuge boyunun isyanı bu gerilimlerin sonucuydu. 188'de şanyü Qiangqu'nun öldürülmesi üzerine tahta çıkan oğlu Yufuluo, kabile isyancılarınca kovularak Çin'in merkez ovalarında savaş ağaları (Cao Cao, Yuan Shao) arasındaki mücadeleye süvari birliğiyle katıldı.", "216 yılında dönemin Çin naibi ve fiili yöneticisi Cao Cao, son şanyü Huchuquan'ı Ye şehrinde nezaret altında tuttu ve şanyülük makamını resmen lağvetti. Güney Hunları sol, sağ, güney, kuzey ve orta olmak üzere beş tümenliğe (Wu Bu) ayrılarak Çinli sivil memurların ve soylu Hun beylerinin (Shuai) ortak yönetimine bağlandı. Böylece bağımsız Hun hükümdarlık çizgisi kapandı, ancak bu kabileler IV. yüzyılın başlarında Çin'de Han-Zhao devletini kuracak olan Liu Yuan gibi liderleri yetiştirdi."], "sources": [{"title": "TDV İslâm Ansiklopedisi, TÜRK", "url": "https://islamansiklopedisi.org.tr/turk"}, {"title": "Britannica, Xiongnu", "url": "https://www.britannica.com/topic/Xiongnu"}, {"title": "Wikipedia, Southern Xiongnu", "url": "https://en.wikipedia.org/wiki/Southern_Xiongnu"}, {"title": "Wikipedia, Battle of the Altai Mountains", "url": "https://en.wikipedia.org/wiki/Battle_of_the_Altai_Mountains"}], "rulers": [{"id": "guney-hun-bi", "name": "Bi", "aliases": ["Sutuhu", "II. Huhanye", "Huhanxie II"], "title": "şanyü", "birth": null, "birthNote": "kayıtlarda yok", "death": 56, "deathNote": "MS 56'da öldü.", "reign": [48, 56], "reignNote": "MS 48'de sekiz güney boyunun desteğiyle şanyü ilan edildi.", "summary": "Wuzhuliu'nun oğlu. Huduershi'nin veraset düzenini bozması üzerine güney boylarının desteğiyle ayrıldı. 48'de dedesi Huhanye'nin unvanını alarak şanyü oldu; 50'de Doğu Han imparatoru Guangwu'ya resmen tabi olarak Güney Hun Devleti'ni kurdu. Xihe bölgesindeki Meiji'ye yerleşti.", "traits": ["Pragmatik diplomasi", "Han vasallığını kabul"], "contribution": "Güney boylarını açlık ve kırımdan kurtararak Çin Seddi boyunca güvenli bir yurt sağladı.", "harm": "Hun birliğini kalıcı olarak parçaladı ve Han kontrolüne girdi.", "wives": [], "children": [{"name": "Xitong", "mother": "", "note": "Sonraki şanyü.", "certainty": "kesin"}, {"name": "Huxie", "mother": "", "note": "Sonraki şanyü.", "certainty": "kesin"}], "wars": [{"name": "Kuzey Hunlarına karşı ilk taarruz", "when": "49", "foe": "Kuzey Hunları (Punu)", "result": "zafer", "note": "Kardeşi Mo komutasındaki birlikler Punu'nun kardeşini esir aldı, binlerce hayvan ele geçirdi."}], "sources": [{"title": "TDV İslâm Ansiklopedisi, TÜRK", "url": "https://islamansiklopedisi.org.tr/turk"}, {"title": "Wikipedia, Sutuhu", "url": "https://en.wikipedia.org/wiki/Sutuhu"}]}, {"id": "guney-hun-qiufu-youdi", "name": "Qiufu Youdi", "aliases": ["Mo"], "title": "şanyü", "birth": null, "birthNote": "kayıtlarda yok", "death": 57, "deathNote": "MS 57'de öldü.", "reign": [56, 57], "reignNote": "Bi'nin kardeşi.", "summary": "Bi'nin kardeşi. Tahta geçtikten yaklaşık bir yıl sonra öldü. Kısa saltanatında Han ile uyumlu ilişkiler sürdü.", "traits": [], "contribution": "Han himayesindeki güney düzenini korudu.", "harm": "", "wives": [], "children": [{"name": "Qiuchu", "mother": "", "note": "Sonraki şanyü.", "certainty": "kesin"}], "wars": [], "sources": [{"title": "Wikipedia, Qiufu Youdi", "url": "https://en.wikipedia.org/wiki/Qiufu_Youdi"}]}, {"id": "guney-hun-yifa-yuluti", "name": "Yifa Yulüti", "aliases": ["Han"], "title": "şanyü", "birth": null, "birthNote": "kayıtlarda yok", "death": 59, "deathNote": "MS 59'da öldü.", "reign": [57, 59], "reignNote": "Qiufu Youdi'nin kardeşi.", "summary": "Qiufu Youdi'nin kardeşi. Kuzey Hunlarının sınır akınlarına karşı Han kuvvetleriyle ortak savunma tedbirleri aldı.", "traits": [], "contribution": "Sınır savunmasını güçlendirdi.", "harm": "", "wives": [], "children": [{"name": "Yitu", "mother": "", "note": "Sonraki şanyü.", "certainty": "kesin"}], "wars": [{"name": "Kuzey Hun sınır savunması", "when": "58", "foe": "Kuzey Hunları", "result": "zafer", "note": "Kuzeyden gelen yağma akınları püskürtüldü."}], "sources": [{"title": "Wikipedia, Chanyu", "url": "https://en.wikipedia.org/wiki/Chanyu"}]}, {"id": "guney-hun-xitong", "name": "Xitong Shizhu Houti", "aliases": ["Shi"], "title": "şanyü", "birth": null, "birthNote": "kayıtlarda yok", "death": 63, "deathNote": "MS 63'te öldü.", "reign": [59, 63], "reignNote": "Bi'nin oğlu.", "summary": "Bi'nin oğlu. Dört yıl süren saltanatında Han hanedanına bağlılık sürdürüldü; sınır boylarına yeni Hun göçmenleri yerleştirildi.", "traits": [], "contribution": "Güney Hun nüfusunu Han sınırında konsolide etti.", "harm": "", "wives": [], "children": [], "wars": [], "sources": [{"title": "Wikipedia, Chanyu", "url": "https://en.wikipedia.org/wiki/Chanyu"}]}, {"id": "guney-hun-qiuchu", "name": "Qiuchu Julinti", "aliases": ["Su"], "title": "şanyü", "birth": null, "birthNote": "kayıtlarda yok", "death": 63, "deathNote": "MS 63'te tahta çıktıktan birkaç ay sonra öldü.", "reign": [63, 63], "reignNote": "Qiufu Youdi'nin oğlu.", "summary": "Qiufu Youdi'nin oğlu. 63 yılında tahta çıktı ve birkaç ay içinde öldü.", "traits": [], "contribution": "", "harm": "", "wives": [], "children": [], "wars": [], "sources": [{"title": "Wikipedia, Chanyu", "url": "https://en.wikipedia.org/wiki/Chanyu"}]}, {"id": "guney-hun-huxie", "name": "Huxie Shizhu Houti", "aliases": ["Zhang"], "title": "şanyü", "birth": null, "birthNote": "kayıtlarda yok", "death": 85, "deathNote": "MS 85'te öldü.", "reign": [63, 85], "reignNote": "Bi'nin oğlu.", "summary": "Bi'nin oğlu. 22 yıllık uzun saltanatında Güney Hunlarını istikrarlı bir sınır gücü haline getirdi. 73 yılında Han generali Dou Gu'nun Kuzey Hunlarına karşı düzenlediği büyük sefere süvari birlikleriyle katıldı.", "traits": ["Uzun ve istikrarlı idare", "Han ile askerî iş birliği"], "contribution": "Güney Hun boylarının Çin Seddi boyunca kurumsallaşmasını sağladı.", "harm": "", "wives": [], "children": [{"name": "Tuntuhe", "mother": "", "note": "Halefi.", "certainty": "kesin"}, {"name": "Anguo", "mother": "", "note": "Sonraki şanyü.", "certainty": "kesin"}, {"name": "Wanshishizhudi", "mother": "", "note": "Sonraki şanyü.", "certainty": "kesin"}], "wars": [{"name": "Yiwu (Hami) Seferi", "when": "73", "foe": "Kuzey Hunları", "result": "zafer", "note": "Han generali Dou Gu ve Güney Hun süvarileri Yiwu vahasını ele geçirdi."}], "sources": [{"title": "Wikipedia, Chanyu", "url": "https://en.wikipedia.org/wiki/Chanyu"}]}, {"id": "guney-hun-yitu", "name": "Yitu Yulüti", "aliases": ["Xuan"], "title": "şanyü", "birth": null, "birthNote": "kayıtlarda yok", "death": 88, "deathNote": "MS 88'de öldü.", "reign": [85, 88], "reignNote": "Yifa Yulüti'nin oğlu.", "summary": "Yifa Yulüti'nin oğlu. Üç yıllık hükümdarlığında Kuzey Hunlarına karşı taarruz siyasetini savundu; kuzeydeki kıtlık ve iç karışıklıkları yakından izledi.", "traits": [], "contribution": "Kuzey Hunlarına nihai darbenin hazırlık zeminini oluşturdu.", "harm": "", "wives": [], "children": [{"name": "Shizi", "mother": "", "note": "Sonraki şanyü.", "certainty": "kesin"}], "wars": [], "sources": [{"title": "Wikipedia, Chanyu", "url": "https://en.wikipedia.org/wiki/Chanyu"}]}, {"id": "guney-hun-tuntuhe", "name": "Tuntuhe", "aliases": ["Xiulan Shizhu Houti", "Shulan"], "title": "şanyü", "birth": null, "birthNote": "kayıtlarda yok", "death": 93, "deathNote": "MS 93'te öldü.", "reign": [88, 93], "reignNote": "Huxie'nin oğlu.", "summary": "Huxie'nin oğlu. Han başkumandanı Dou Xian ile birlikte Kuzey Hunlarını ezmek üzere büyük bir sefer başlattı. 89'da İh Bayan (Altay Dağları) Muharebesi'nde Kuzey Hun ordusunu imha etti, 200.000 kuzeyliyi teslim aldı. Bu zaferle Kuzey Hun gücü kalıcı olarak kırıldı.", "traits": ["Büyük askeri liderlik", "Stratejik ittifak kurma"], "contribution": "89 zaferiyle Kuzey Hun tehdidini ortadan kaldırdı, on binlerce boydaşını güneye kattı.", "harm": "Kuzey Hunlarının yıkılmasıyla doğudan Siyenpilerin yükselmesine zemin hazırladı.", "wives": [], "children": [{"name": "Feng-hou", "mother": "", "note": "Sonradan Han'a isyan eden prens.", "certainty": "kesin"}], "wars": [{"name": "İh Bayan (Altay Dağları) Muharebesi", "when": "89", "foe": "Kuzey Hunları", "result": "zafer", "note": "Dou Xian ve Tuntuhe komutasındaki ordu 13.000 Kuzey Hun askerini öldürdü, 81 kabile teslim oldu."}], "sources": [{"title": "Wikipedia, Battle of the Altai Mountains", "url": "https://en.wikipedia.org/wiki/Battle_of_the_Altai_Mountains"}, {"title": "TDV İslâm Ansiklopedisi, TÜRK", "url": "https://islamansiklopedisi.org.tr/turk"}]}, {"id": "guney-hun-anguo", "name": "Anguo", "title": "şanyü", "birth": null, "birthNote": "kayıtlarda yok", "death": 94, "deathNote": "94 yılında Han ordusunun müdahalesi sırasında öldürüldü.", "reign": [93, 94], "reignNote": "Tuntuhe'nin kardeşi.", "summary": "Tuntuhe'nin kardeşi. Tahta çıktığında Çin yanlısı yeğeni Sol Bilge Kral Shizi'yi kıskandı ve ortadan kaldırmak istedi. Han sarayı Shizi'yi destekleyince Anguo isyan başlattı; Han birliklerinin müdahalesiyle öldürüldü.", "traits": ["Çin nüfuzuna tepkili", "İhtiraslı"], "contribution": "", "harm": "Güney Hun sarayında kanlı bir iç çatışma çıkardı.", "wives": [], "children": [], "wars": [{"name": "Anguo İsyanı", "when": "94", "foe": "Han hanedanı ve Shizi", "result": "yenilgi", "note": "İsyan bastırıldı, Anguo öldürüldü."}], "sources": [{"title": "Wikipedia, Southern Xiongnu", "url": "https://en.wikipedia.org/wiki/Southern_Xiongnu"}]}, {"id": "guney-hun-shizi", "name": "Shizi", "aliases": ["Tingdu Shizhu Houti"], "title": "şanyü", "birth": null, "birthNote": "kayıtlarda yok", "death": 98, "deathNote": "MS 98'de öldü.", "reign": [94, 98], "reignNote": "Yitu'nun oğlu.", "summary": "Yitu'nun oğlu. Anguo'nun tasfiyesinden sonra Han sarayının desteğiyle tahta geçti. 94'te Anguo taraftarlarının ve prens Feng-hou'nun 200.000 kişiyle kuzeye kaçarak başlattığı büyük ayaklanmayla mücadele etti.", "traits": ["Han yanlısı sadakat"], "contribution": "Han desteğiyle tahtı korudu.", "harm": "Feng-hou'nun 200.000 kişilik kitleyle kuzeye kopmasını engelleyemedi.", "wives": [], "children": [], "wars": [{"name": "Feng-hou isyanı bastırma harekâtı", "when": "94-96", "foe": "Feng-hou ve isyancı Hunlar", "result": "belirsiz", "note": "İsyancılar kuzeye kaçtı ancak sınır boylarındaki hâkimiyet korundu."}], "sources": [{"title": "Wikipedia, Southern Xiongnu", "url": "https://en.wikipedia.org/wiki/Southern_Xiongnu"}]}, {"id": "guney-hun-wanshishizhudi", "name": "Wanshishizhudi", "aliases": ["Tan"], "title": "şanyü", "birth": null, "birthNote": "kayıtlarda yok", "death": 124, "deathNote": "MS 124'te öldü.", "reign": [98, 124], "reignNote": "Huxie'nin oğlu.", "summary": "Huxie'nin oğlu. 26 yıl tahtta kaldı. Kuzeyde direnen Feng-hou kuvvetlerinin yıpranmasını Han ordusuyla birlikte takip etti. 118'de Feng-hou'nun teslim olmasıyla güneyin üstünlüğü pekişti.", "traits": ["Uzun saltanat", "İstikrar"], "contribution": "Feng-hou isyanının nihai olarak sönümlenmesinde rol oynadı.", "harm": "", "wives": [], "children": [], "wars": [], "sources": [{"title": "Wikipedia, Southern Xiongnu", "url": "https://en.wikipedia.org/wiki/Southern_Xiongnu"}]}, {"id": "guney-hun-wujihoushizhudi", "name": "Wujihoushizhudi", "aliases": ["Ba"], "title": "şanyü", "birth": null, "birthNote": "kayıtlarda yok", "death": 128, "deathNote": "MS 128'de öldü.", "reign": [124, 128], "reignNote": "Wanshishizhudi'nin kardeşi.", "summary": "Wanshishizhudi'nin kardeşi. Dört yıllık hükümdarlığı sakin geçti.", "traits": [], "contribution": "", "harm": "", "wives": [], "children": [], "wars": [], "sources": [{"title": "Wikipedia, Southern Xiongnu", "url": "https://en.wikipedia.org/wiki/Southern_Xiongnu"}]}, {"id": "guney-hun-xiuli", "name": "Xiuli", "aliases": ["Qute Ruoshi Zhujiu"], "title": "şanyü", "birth": null, "birthNote": "kayıtlarda yok", "death": 140, "deathNote": "Han müfettişinin baskısı üzerine intihar etti.", "reign": [128, 140], "reignNote": "Wujihoushizhudi'nin kardeşi.", "summary": "Wujihoushizhudi'nin kardeşi. 140 yılında bazı Güney Hun beylerinin (Juqu Wusi) Han yönetimine karşı isyan etmesi üzerine Han müfettişi Chen Gui tarafından suçlandı. Ağır hakaret ve tehditler karşısında kardeşiyle birlikte intihar etti.", "traits": ["Çin baskısı altında ezilen hükümdar"], "contribution": "", "harm": "İntiharı güney boylarında derin bir öfkeye ve üç yıl süren büyük bir kaosa yol açtı.", "wives": [], "children": [], "wars": [{"name": "140 Güney Hun İsyanı", "when": "140", "foe": "İsyancı Hun beyleri (Juqu Wusi)", "result": "yenilgi", "note": "İsyanı bastıramayınca Han sarayının baskısıyla intihar etti."}], "sources": [{"title": "Wikipedia, Southern Xiongnu", "url": "https://en.wikipedia.org/wiki/Southern_Xiongnu"}]}, {"id": "guney-hun-cheniu", "name": "Cheniu", "title": "şanyü", "birth": null, "birthNote": "kayıtlarda yok", "death": 143, "deathNote": "143'te Han ordusuna teslim olduktan sonra akıbeti meçhuldür.", "reign": [140, 143], "reignNote": "İsyancı boylar tarafından Han'dan bağımsız olarak şanyü seçildi.", "claim": true, "summary": "Xiuli'nin intiharından sonra ayaklanan Hun kabileleri ve Qiang müttefikleri tarafından şanyü seçildi. Çin sınır kasabalarını yağmaladı. 143'te Han generali Ma Rong ve Dou Yong tarafından mağlup edilince teslim oldu.", "traits": ["İsyancı lider"], "contribution": "Han tahakkümüne karşı bozkır direnişini canlandırdı.", "harm": "Yenilgiyle sonuçlanan isyan Güney Hunlarının askeri gücünü daha da kırdı.", "wives": [], "children": [], "wars": [{"name": "Cheniu İsyanı Muharebeleri", "when": "140-143", "foe": "Han hanedanı (Ma Rong)", "result": "yenilgi", "note": "Ağır kayıplar veren Cheniu teslim olmak zorunda kaldı."}], "sources": [{"title": "Wikipedia, Southern Xiongnu", "url": "https://en.wikipedia.org/wiki/Southern_Xiongnu"}]}, {"id": "guney-hun-toulouchu", "name": "Toulouchu", "aliases": ["Hulan Ruoshi Zhujiu"], "title": "şanyü", "birth": null, "birthNote": "kayıtlarda yok", "death": 147, "deathNote": "MS 147'de öldü.", "reign": [143, 147], "reignNote": "Han sarayı tarafından kukla hükümdar olarak atandı.", "summary": "Hanedanın uzak bir kolundan gelip Luoyang'da yaşayan bir prensti. Cheniu isyanının bastırılmasının ardından Han sarayı tarafından şanyü ilan edilip Meiji'ye gönderildi.", "traits": ["Çin sarayına tam bağımlılık"], "contribution": "İsyan sonrası asayişin yeniden kurulmasına aracılık etti.", "harm": "", "wives": [], "children": [], "wars": [], "sources": [{"title": "Wikipedia, Southern Xiongnu", "url": "https://en.wikipedia.org/wiki/Southern_Xiongnu"}]}, {"id": "guney-hun-jucheer", "name": "Jucheer", "aliases": ["Yiling Ruoshi Zhujiu"], "title": "şanyü", "birth": null, "birthNote": "kayıtlarda yok", "death": 172, "deathNote": "158'de hapsedildikten sonra 172'de öldü.", "reign": [147, 158], "reignNote": "Han sarayınca atandı; 158'de azledilip hapsedildi.", "summary": "Toulouchu'nun ardından Han sarayı tarafından atandı. Zamanla Çin memurlarının aşırı baskısından rahatsız olarak bağımsız hareket etmeye çalıştı. 158'de Han generali Zhang Huan tarafından tutuklanarak hapse atıldı ve unvanı elinden alındı.", "traits": [], "contribution": "", "harm": "Çin generalleriyle anlaşmazlığı makamından olmasına yol açtı.", "wives": [], "children": [], "wars": [], "sources": [{"title": "Wikipedia, Southern Xiongnu", "url": "https://en.wikipedia.org/wiki/Southern_Xiongnu"}]}, {"id": "guney-hun-tute", "name": "Tute Ruoshi Zhujiu", "title": "şanyü", "birth": null, "birthNote": "kayıtlarda yok", "death": 178, "deathNote": "MS 178'de öldü.", "reign": [158, 178], "reignNote": "Jucheer'in hapsedilmesinin ardından fiilen başa geçti; 172'de Han sarayı tarafından resmiyete bağlandı.", "summary": "158'den itibaren fiilen yönetti, 172'de Han sarayınca resmi şanyü olarak onaylandı. Siyenpi lideri Tanshihuai'nin bozkırda yükseldiği dönemde Han sınırlarını korumaya çalıştı.", "traits": [], "contribution": "Siyenpi akınlarına karşı Han sınırında savunma sağladı.", "harm": "", "wives": [], "children": [{"name": "Huzheng", "mother": "", "note": "Halefi.", "certainty": "kesin"}], "wars": [], "sources": [{"title": "Wikipedia, Southern Xiongnu", "url": "https://en.wikipedia.org/wiki/Southern_Xiongnu"}]}, {"id": "guney-hun-huzheng", "name": "Huzheng", "title": "şanyü", "birth": null, "birthNote": "kayıtlarda yok", "death": 179, "deathNote": "Han müfettişi Zang Min tarafından yetkisizce idam edildi.", "reign": [178, 179], "reignNote": "Tute'nin oğlu.", "summary": "Tute'nin oğlu. 179 yılında Han müfettişi Zang Min ile anlaşmazlığa düştü; Zang Min imparatordan izin almaksızın Huzheng'i öldürttü. Olay üzerine Han sarayı Zang Min'i cezalandırdı ve Qiangqu'yu şanyü yaptı.", "traits": [], "contribution": "", "harm": "Öldürülmesi Hun kabilelerinde Han memurlarına karşı nefreti derinleştirdi.", "wives": [], "children": [], "wars": [], "sources": [{"title": "Wikipedia, Southern Xiongnu", "url": "https://en.wikipedia.org/wiki/Southern_Xiongnu"}]}, {"id": "guney-hun-qiangqu", "name": "Qiangqu", "aliases": ["Jiangqu"], "title": "şanyü", "birth": null, "birthNote": "kayıtlarda yok", "death": 188, "deathNote": "188'de ayaklanan Xiuchuge klanı tarafından öldürüldü.", "reign": [179, 188], "reignNote": "Huzheng'in öldürülmesinin ardından Han sarayınca atandı.", "summary": "Han hanedanına sadık bir hükümdardı. Sarı Sarıklılar İsyanı ve Zhang Chun ayaklanmasını bastırmak üzere Han ordusuna Hun süvarisi gönderdi. Sürekli savaşa sürülmekten bıkan Xiuchuge boyunun isyanı sırasında 188'de öldürüldü.", "traits": ["Han sarayına bağlılık"], "contribution": "Çin'deki kargaşada sınır garnizonlarının korunmasına destek verdi.", "harm": "Kendi boylarının çıkarlarını gözetmeyip sürekli savaşa sürmesi kanlı bir isyanla canına mal oldu.", "wives": [], "children": [{"name": "Yufuluo", "mother": "", "note": "Halefi.", "certainty": "kesin"}, {"name": "Huchuquan", "mother": "", "note": "Son şanyü.", "certainty": "kesin"}], "wars": [{"name": "Xiuchuge İsyanı", "when": "188", "foe": "Xiuchuge Hun boyu", "result": "yenilgi", "note": "İsyancılar şanyü ordugâhını basarak Qiangqu'yu öldürdü."}], "sources": [{"title": "Wikipedia, Southern Xiongnu", "url": "https://en.wikipedia.org/wiki/Southern_Xiongnu"}]}, {"id": "guney-hun-yufuluo", "name": "Yufuluo", "aliases": ["Chizhi Shizhu Houti"], "title": "şanyü", "birth": 150, "birthNote": "Yaklaşık 150 doğumlu.", "death": 195, "deathNote": "MS 195'te öldü.", "reign": [188, 195], "reignNote": "Babasının öldürülmesinden sonra tahta çıktı ancak kendi yurdundan kovuldu.", "summary": "Qiangqu'nun oğlu. Tahta çıktığında isyancı Xiuchuge boyu onu tanımadı ve Ordos'tan kovdu. Luoyang'a sığındı. Han hanedanının çöküşü sırasında süvarileriyle Yuan Shao ve Cao Cao gibi savaş ağalarıyla ittifaklar kurup Merkez Ovalarında savaştı. Yurduna dönemeden Pingyang'da (Shanxi) öldü.", "traits": ["Sürgünde mücadele", "Bozkır süvarisi kumandanı"], "contribution": "Çin iç savaşında Hun askeri varlığını güçlü bir aktör olarak korudu.", "harm": "Kendi topraklarına hâkim olamayarak sürgünde bir kabile reisine dönüştü.", "wives": [], "children": [{"name": "Liu Bao", "mother": "", "note": "Sol Bilge Kral; Han-Zhao kurucusu Liu Yuan'ın babası.", "certainty": "kesin"}], "wars": [{"name": "Merkez Ovaları Savaş Ağaları Çarpışmaları", "when": "188-195", "foe": "Çeşitli Çin savaş ağaları", "result": "belirsiz", "note": "Yuan Shao ve Cao Cao ile birlikte veya onlara karşı savaştı."}], "sources": [{"title": "Wikipedia, Southern Xiongnu", "url": "https://en.wikipedia.org/wiki/Southern_Xiongnu"}, {"title": "Wikipedia, Yufuluo", "url": "https://en.wikipedia.org/wiki/Yufuluo"}]}, {"id": "guney-hun-xubu-guduhou", "name": "Xubu Gudu Hou", "title": "şanyü", "birth": null, "birthNote": "kayıtlarda yok", "death": 189, "deathNote": "MS 189'da öldü.", "reign": [188, 189], "reignNote": "İsyancılar tarafından Ordos'ta tahta çıkarıldı.", "claim": true, "summary": "Qiangqu'yu öldürüp Yufuluo'yu kovan Xiuchuge isyancıları tarafından şanyü ilan edildi. Bir yıl sonra öldü. Ölümünden sonra isyancılar yeni bir şanyü seçmeyip boy beyleri idaresini sürdürdü.", "traits": ["İsyancı aristokrat"], "contribution": "", "harm": "Şanyülük makamının meşruiyetini aşındırdı.", "wives": [], "children": [], "wars": [], "sources": [{"title": "Wikipedia, Southern Xiongnu", "url": "https://en.wikipedia.org/wiki/Southern_Xiongnu"}]}, {"id": "guney-hun-huchuquan", "name": "Huchuquan", "aliases": ["Hu-ch'u-ch'üan"], "title": "şanyü", "birth": null, "birthNote": "kayıtlarda yok", "death": 216, "deathNote": "216'da unvanı kaldırılıp Ye şehrinde alıkonuldu; ölüm yılı kesin değildir.", "reign": [195, 216], "reignNote": "Yufuluo'nun ardından Pingyang'da şanyü oldu; 216'da Cao Cao makamı lağvetti.", "summary": "Yufuluo'nun kardeşi. Ağabeyinin ardından Shanxi bölgesindeki Hunların başına geçti. 216'da Wei prensi Cao Cao'nun sarayına gittiğinde Ye şehrinde gözaltında tutuldu. Cao Cao şanyülük makamını resmen kaldırdı ve Güney Hunlarını beş idari bölgeye ayırdı.", "traits": ["Son resmi şanyü"], "contribution": "Güney Hun boylarının Shanxi'de yerleşik düzene geçişini yönetti.", "harm": "Şanyülük unvanının ve bağımsız siyasi kimliğin tasfiyesine engel olamadı.", "wives": [], "children": [], "wars": [], "sources": [{"title": "TDV İslâm Ansiklopedisi, TÜRK", "url": "https://islamansiklopedisi.org.tr/turk"}, {"title": "Wikipedia, Huchuquan", "url": "https://en.wikipedia.org/wiki/Huchuquan"}, {"title": "Wikipedia, Southern Xiongnu", "url": "https://en.wikipedia.org/wiki/Southern_Xiongnu"}]}]}, {"id": "kuzey-hun", "name": "Kuzey Hun Devleti", "short": "Kuzey Hun", "aliases": ["Kuzey Hiung-nu", "Bei Xiongnu", "Kuzeyli Hunlar", "Kuzey Hunları"], "region": "bozkir", "start": 48, "end": 155, "startNote": "MS 48'de şanyü Bi'nin güneye ayrılmasıyla Punu yönetiminde Moğolistan bozkırında kalan bağımsız Hun birliği.", "endNote": "89 ve 91'deki ağır yenilgilerin ardından 93'te Yuchujian'ın ölümüyle siyasi birlik çöktü; 155 civarında Siyenpilerin (Xianbei) önderi Tanshihuai son Hun kalıntılarını Moğolistan'dan tamamen sürdü.", "capital": "Orhun-Selenge havzası, Hangay ve Altay dağları etekleri", "religion": "Gök Tanrı inancı, kamlık, atalar kültü", "confidence": "kayit", "confidenceNote": "Hou Hanshu ve 2017'de Moğolistan'da Dundgovi ilinde keşfedilen Yanran Yazıtı ile belgelenmiştir.", "summary": "MS 48 bölünmesinden sonra Moğolistan bozkırında bağımsızlığını sürdüren Hun koludur. Çin'in heqin antlaşması vermemesi, ağır kuraklıklar, çekirge istilaları ve güneyden Han-Güney Hun, doğudan Siyenpi, batıdan Dingling ve Usun saldırılarıyla kuşatıldılar. 89 İh Bayan (Altay) ve 91 Tanrı Dağları muharebelerinde ağır darbeler alarak batıya Cungarya ve Kazakistan bozkırlarına çekildiler; 155'te Siyenpi lideri Tanşihoay tarafından Moğolistan'daki varlıkları tamamen tasfiye edildi.", "legacy": "Kuzey Hunlarının batıya (Cungarya, Yedisu ve Aral-Hazar ötesine) göç eden kitlelerinin, yüzyıllar sonra ortaya çıkan Avrupa Hunlarının ve Ak Hunların (Eftalitler) etnogenezinde rol oynadığı kabul edilir veya tartışılır.", "essay": ["Kuzey Hun Devleti, MS 48'de sekiz güney boyunun Bi önderliğinde Çin Seddi'ne inerek Doğu Han hanedanına tabi olmasıyla, Moğolistan platosunda kalan boyların bağımsız çizgisidir. Punu'nun şanyülüğünde devam eden bu kuzey kolu, atalarının 'bağımsız bozkır egemenliği' mirasını sürdürmeyi hedefledi. Ancak güneyin kopuşu, konfederasyonu en verimli kışlaklarından, zengin nüfus kaynağından ve Çin ile yapılan kârlı sınır ticaretinden mahrum bıraktı.", "Kuzey Hunları ekonomik açıdan ağır bir krize girdi. 46 yılında başlayan ve aralıklarla süren kuraklıklar, çekirge sürüleri ve hayvan kırımları bozkır ekonomisini felç etti. Han sarayına elçiler göndererek heqin antlaşması ve sınır pazarları talep ettiler; ancak Han hanedanı Güney Hunlarını korumak amacıyla bu talepleri reddetti. Bu tecrit karşısında Kuzey Hunları yeniden akın siyasetine yöneldi, ancak çevrelerindeki güç dengesi aleyhlerine dönmüştü.", "Doğuda güçlenen Moğol kökenli Siyenpiler (Xianbei), batıda Dinglingler ve Usunlar, güneyde ise Han ve Güney Hun müşterek orduları Kuzey Hunlarını dört taraftan kuşattı. 87 yılında Siyenpiler kuzey ordugâhına baskın düzenleyerek şanyü Youliu'yu öldürdüler ve cesedinin derisini yüzdüler. Bu dehşet verici darbe Kuzey Hunları arasında büyük bir panik ve çözülme başlattı.", "Nihai askerî darbe 89 yılında geldi. Han generali Dou Xian ve Güney Hun şanyüsü Tuntuhe komutasındaki birleşik ordu, Altay Dağları eteklerinde gerçekleşen İh Bayan Muharebesi'nde Kuzey Hun ordusunu darmadağın etti. 13.000 kuzey askeri öldürüldü, 81 kabileden 200.000 kişi teslim oldu. Dou Xian, Hangay Dağları'nda meşhur Yanran Yazıtı'nı kazıtarak zaferini ilan etti. 91 yılında Tanrı Dağları Muharebesi'nde ikinci bir darbe alan Kuzey Şanyüsü bilinmeyen bir yöne (Cungarya ve İli havzasına) kaçtı.", "93 yılında son şanyü Yuchujian'ın ölümüyle merkezi şanyülük kurumu kuzeyde fiilen çöktü. 94-118 arasında güneyden kaçan Feng-hou'nun çevresinde toplanan son direnç odakları da açlık ve Siyenpi baskısıyla tükendi. 155 civarında büyük Siyenpi kağanı Tanşihoay (Tanshihuai), Moğolistan'daki son Hun bakiyelerini tamamen sürdü; kalan yüz bin çadır Siyenpi adını benimseyerek eridi. Batıya çekilen Kuzey Hun kitleleri ise Cungarya, Yedisu ve Kazakistan üzerinden batı yönlü göç dalgasını başlatarak Avrasya tarihinin akışını değiştirdi."], "sources": [{"title": "TDV İslâm Ansiklopedisi, TÜRK", "url": "https://islamansiklopedisi.org.tr/turk"}, {"title": "Britannica, Xiongnu", "url": "https://www.britannica.com/topic/Xiongnu"}, {"title": "Wikipedia, Han–Xiongnu Wars", "url": "https://en.wikipedia.org/wiki/Han%E2%80%93Xiongnu_wars"}, {"title": "Wikipedia, Battle of the Altai Mountains", "url": "https://en.wikipedia.org/wiki/Battle_of_the_Altai_Mountains"}], "rulers": [{"id": "kuzey-hun-punu", "name": "Punu", "aliases": ["P'u-nu"], "title": "şanyü", "birth": null, "birthNote": "kayıtlarda yok", "death": 75, "deathNote": "Yaklaşık MS 75'te öldüğü tahmin edilir.", "reign": [48, 75], "reignNote": "MS 48'de Güney Hunlarının ayrılmasıyla Kuzey Hun Devleti'nin ilk bağımsız şanyüsü olarak hüküm sürdü.", "summary": "Huduershi'nin oğlu. 48 bölünmesinden sonra Moğolistan bozkırında bağımsız kalan Hun boylarını yönetti. Han hanedanına elçiler gönderip heqin antlaşması ve sınır pazarları istedi; talepleri reddedilince sınırları taciz etti. Çevre boyların ve kuraklığın baskısı altında bozkır egemenliğini korumaya çalıştı.", "traits": ["Bağımsızlıkta kararlılık", "Çetin koşullara göğüs germe"], "contribution": "Bölünme sonrası bozkırda bağımsız Hun varlığını sürdürdü.", "harm": "Çin ile ekonomik barış kuramayarak tecrit edildi.", "wives": [], "children": [], "wars": [{"name": "Güney Hun sınır çatışmaları", "when": "49-52", "foe": "Güney Hunları (Bi) ve Han sınır garnizonları", "result": "yenilgi", "note": "Bi'nin gönderdiği birlikler kuzey sınırlarını yağmaladı."}], "sources": [{"title": "TDV İslâm Ansiklopedisi, TÜRK", "url": "https://islamansiklopedisi.org.tr/turk"}, {"title": "Wikipedia, Punu Chanyu", "url": "https://en.wikipedia.org/wiki/Punu_Chanyu"}]}, {"id": "kuzey-hun-youliu", "name": "Youliu", "aliases": ["Yu-liu"], "title": "şanyü", "birth": null, "birthNote": "kayıtlarda yok", "death": 87, "deathNote": "MS 87'de Siyenpiler tarafından baskında öldürüldü ve derisi yüzüldü.", "reign": [75, 87], "reignNote": "Punu'nun ardından tahta geçtiği kabul edilir.", "summary": "Punu'dan sonraki Kuzey Hun şanyüsü. Doğu sınırlarında hızla güçlenen Siyenpilerin baskısı altında kaldı. 87 yılında Siyenpilerin ordugâhına düzenlediği ani baskında öldürüldü ve cesedinin derisi yüzüldü. Bu felaket Kuzey Hun boylarında kitlesel paniğe ve çözülmeye yol açtı.", "traits": [], "contribution": "", "harm": "Siyenpi tehlikesini zamanında engelleyemeyerek devletin savunma hattını çökertti.", "wives": [], "children": [], "wars": [{"name": "Siyenpi Baskını", "when": "87", "foe": "Siyenpiler (Xianbei)", "result": "yenilgi", "note": "Şanyü Youliu öldürüldü, ordugâh yağmalandı ve binlerce Hun boyu güneye kaçtı."}], "sources": [{"title": "Wikipedia, Chanyu", "url": "https://en.wikipedia.org/wiki/Chanyu"}, {"title": "Wikipedia, Han–Xiongnu Wars", "url": "https://en.wikipedia.org/wiki/Han%E2%80%93Xiongnu_wars"}]}, {"id": "kuzey-hun-adsiz", "name": "Adı kayıtlarda geçmeyen Kuzey Şanyüsü", "aliases": ["Kuzey Şanyüsü", "Northern Chanyu"], "title": "şanyü", "birth": null, "birthNote": "kayıtlarda yok", "death": null, "deathNote": "91 Tanrı Dağları hezimetinden sonra batıya kaçtı; nerede ve ne zaman öldüğü kayıtlarda yoktur.", "reign": [88, 91], "reignNote": "Youliu'nun kardeşi. Çin yıllıklarında özel adı verilmez, sadece 'Kuzey Şanyüsü' diye anılır.", "summary": "Youliu'nun kardeşi. 89'da Han generali Dou Xian ve Güney Hun şanyüsü Tuntuhe'nin İh Bayan'daki (Altay Dağları) büyük taarruzunda ağır hezimete uğradı. 91'de Tanrı Dağları eteklerinde Han generali Geng Kui tarafından ikinci kez kuşatılıp yaralanınca ordusunu bırakıp batıya (Cungarya ve İli havzasına) kaçtı.", "traits": ["Trajik çekiliş"], "contribution": "Çemberi yararak batıya çekilmeyi başardı.", "harm": "89 ve 91 hezimetleriyle Moğolistan platosundaki Hun siyasi hâkimiyeti fiilen sona erdi.", "wives": [{"name": "Yanzhi (Hatun)", "note": "89 İh Bayan Muharebesi'nde Han birliklerince esir alındı.", "certainty": "kesin"}], "children": [], "wars": [{"name": "İh Bayan (Altay Dağları) Muharebesi", "when": "89", "foe": "Han hanedanı (Dou Xian) ve Güney Hunları (Tuntuhe)", "result": "yenilgi", "note": "13.000 Hun askeri öldürüldü, yüz binlerce kabile teslim oldu; şanyü batıya kaçtı."}, {"name": "Tanrı Dağları (Tian Shan) Muharebesi", "when": "91", "foe": "Han generali Geng Kui", "result": "yenilgi", "note": "Kuzey ordugâhı tamamen ele geçirildi; şanyü yaralı halde batıya kaçtı."}], "sources": [{"title": "Wikipedia, Battle of the Altai Mountains", "url": "https://en.wikipedia.org/wiki/Battle_of_the_Altai_Mountains"}, {"title": "Wikipedia, Han–Xiongnu Wars", "url": "https://en.wikipedia.org/wiki/Han%E2%80%93Xiongnu_wars"}]}, {"id": "kuzey-hun-yuchujian", "name": "Yuchujian", "aliases": ["Yü-ch'u-chien"], "title": "şanyü", "birth": null, "birthNote": "kayıtlarda yok", "death": 93, "deathNote": "MS 93'te Han birliklerince takip edilirken yolda öldü/öldürüldü.", "reign": [91, 93], "reignNote": "Ağabeyinin batıya kaçmasının ardından Yiwu'da tahta çıktı.", "summary": "Kuzey Şanyüsü'nün kardeşi. Ağabeyinin 91'de batıya kaçmasından sonra Yiwu (Hami) civarında kalan boyların başına geçti ve Han hanedanına teslim oldu. 93'te Han memurlarının denetiminden kurtulup kuzeye kaçmaya çalışırken Çin kuvvetleri tarafından yakalandı ve hayatını kaybetti.", "traits": [], "contribution": "Kısa bir süre boyların dağılmasını geciktirdi.", "harm": "Ölümüyle birlikte Moğolistan'daki hanedan idaresi tamamen dağıldı.", "wives": [], "children": [], "wars": [{"name": "93 Kuzeye Kaçış ve Çatışma", "when": "93", "foe": "Han generalleri Ren Shang ve Wang Fu", "result": "yenilgi", "note": "Yuchujian takip edilip öldürüldü."}], "sources": [{"title": "Wikipedia, Yuchujian", "url": "https://en.wikipedia.org/wiki/Yuchujian"}, {"title": "Wikipedia, Chanyu", "url": "https://en.wikipedia.org/wiki/Chanyu"}]}, {"id": "kuzey-hun-fenghou", "name": "Feng-hou", "title": "şanyü", "birth": null, "birthNote": "kayıtlarda yok", "death": 118, "deathNote": "118'de Han hanedanına teslim olduktan sonra akıbeti kayıtlarda yoktur.", "reign": [94, 118], "reignNote": "Güney Hun prensi iken isyan edip kuzeye geçti; 24 yıl boyunca kuzey kalıntılarını yönetti.", "claim": true, "summary": "Güney Hun şanyüsü Tuntuhe'nin oğlu. 94'te Shizi'nin şanyülüğüne isyan eden 200.000 kişilik kitleyi alarak kuzeye kaçtı ve Kuzey Hunlarının kalıntılarıyla birleşerek şanyü unvanını aldı. Çölün kuzeyinde 24 yıl boyunca Han ve Siyenpi saldırılarına direndi. Açlık, tipi ve kabilelerin Han'a sığınması üzerine 118'de teslim oldu.", "traits": ["Çeyrek asırlık direniş", "Bozkır bağımsızlık inadı"], "contribution": "Kuzey Hun direnişini 24 yıl boyunca sürdürdü.", "harm": "Açlık ve tecrit yüzünden maiyetindeki kabilelerin tükenmesini engelleyemedi.", "wives": [], "children": [], "wars": [{"name": "Feng-hou Direnişi Savaşları", "when": "94-118", "foe": "Han hanedanı ve Siyenpiler", "result": "yenilgi", "note": "Siyenpi darbeleri ve açlık sonucu kuvvetleri eridi, 118'de teslim oldu."}], "sources": [{"title": "Wikipedia, Southern Xiongnu", "url": "https://en.wikipedia.org/wiki/Southern_Xiongnu"}, {"title": "Wikipedia, Chanyu", "url": "https://en.wikipedia.org/wiki/Chanyu"}]}]}, {"id": "gokturk", "name": "Birinci Göktürk Kağanlığı", "short": "I. Göktürk", "aliases": ["Kök Türk Kağanlığı", "Türk Kağanlığı", "Tujue"], "region": "bozkir", "start": 552, "end": 630, "startNote": "552 yılında Bumın Kağan'ın Juan-juan (Avar) egemenliğine son vermesiyle kuruldu.", "endNote": "581'de Taspar Kağan'ın ölümünden sonra başlayan taht kavgalarıyla doğu ve batı olarak ikiye bölündü; resmi birlik sona erdi.", "capital": "Ötüken", "religion": "Gök Tanrı inancı, atalar kültü", "confidence": "kayit", "confidenceNote": "Orhun yazıtları, Soğdca Bugut yazıtı ve Sui-Tang Çin kronikleriyle belgelidir.", "summary": "552'de Bumın Kağan önderliğinde Juan-juan boyunduruğunu kırarak Ötüken merkezli kurulan, 'Türk' adını resmi devlet adı olarak kullanan ilk imparatorluk. Doğuda Mançurya'dan batıda Karadeniz kıyılarına ve Sâsânî sınırına kadar Avrasya bozkırını tek bayrak altında birleştirdi. İkili teşkilatla yönetilen devlet, Bumın'ın kardeşi İstemi Yabgu'nun batı seferleriyle İpek Yolu kontrolünü ele geçirdi; Bizans ve Sâsânîler ile doğrudan diplomatik ilişki kurdu.", "legacy": "Türk adını siyasi ve milli bir kimlik olarak tarihe kazıdı. İkili devlet teşkilatı (doğu-batı), töre hukuku, kurultay meclisi ve Orhun alfabesiyle sonraki tüm Türk devletlerine vazgeçilmez bir kurumsal miras bıraktı.", "essay": ["Göktürk Kağanlığı, 6. yüzyılın ortalarında Altay dağları eteklerinde demircilikle uğraşan Aşina boyunun tarih sahnesine fırlayışıyla doğdu. Juan-juan (Rouran) Kağanlığı'na demir haraç ödeyen Aşina boyu reisi Bumın, 552'de Juan-juan hükümdarını mağlup ederek ilahi kut sahibi 'İllig Kağan' unvanıyla Ötüken'de bağımsızlığını ilan etti.", "Devlet geleneksel bozkır ikili teşkilatıyla örgütlendi: Büyük kağan doğuda Ötüken'de otururken, Bumın'ın kardeşi İstemi Yabgu batı kanadını idare etti. İstemi, Ak Hunlar'a (Eftalit) karşı Sâsânî Şahı I. Hüsrev Enûşirvân ile ittifak kurup bu devleti 557 civarında yıkarak Maveraünnehir ve İpek Yolu ticaretini ele geçirdi. Ardından Sâsânîler'in ipek ticaretini engellemesi üzerine Soğdlu tüccar Maniakh başkanlığındaki heyeti 568'de İstanbul'a, Bizans İmparatoru II. Justinianos'a göndererek Orta Asya'dan Bizans'a uzanan ilk resmi diplomatik köprüyü kurdu.", "Mukan Kağan devrinde (553-572) imparatorluk en parlak devrine ulaştı; kuzeyde Kırgızlar, doğuda Kıtaylar boyunduruk altına alındı. Ancak Taspar Kağan'ın Budizm'e meyletmesi ve 581'de ölümüyle veliaht tayinindeki kriz doğu ve batı kanatlarının arasını açtı; Sui hanedanının entrikalarıyla 581-582'de kağanlık resmen Doğu ve Batı olarak ikiye ayrıldı."], "sources": [{"title": "TDV İslâm Ansiklopedisi, GÖKTÜRKLER", "url": "https://islamansiklopedisi.org.tr/gokturkler"}, {"title": "TDV İslâm Ansiklopedisi, YABGU", "url": "https://islamansiklopedisi.org.tr/yabgu"}, {"title": "Britannica, Turkic peoples", "url": "https://www.britannica.com/topic/Turkic-peoples"}], "rulers": [{"id": "gokturk-bumin", "name": "Bumın Kağan", "aliases": ["İllig Kağan", "Tumen", "Bumin"], "title": "İllig Kağan", "birth": null, "birthNote": "Doğum yılı kayıtlarda yok", "death": 552, "deathNote": "Devleti kurduğu yılın sonunda Ötüken'de vefat etti", "reign": [552, 552], "reignNote": "552 yılı başında kağan oldu, aynı yıl içinde vefat etti.", "summary": "Juan-juan egemenliğindeki demirci boyları birleştirerek bağımsız Göktürk Kağanlığı'nı kuran tarihi lider. Batı kanadını kardeşi İstemi Yabgu'ya teslim ederek ikili teşkilatın temelini attı.", "traits": ["Devlet kurucu önder", "Askerî teşkilatçı", "Töre koyucu"], "contribution": "Aşina boyunu bağımsızlığa kavuşturdu, Juan-juan devletini yıkarak Ötüken merkezli ilk Türk imparatorluğunu kurdu.", "harm": "Çok kısa süre tahtta kaldığı için kurumsal yapıyı tam oturtamadan vefat etti.", "wives": [{"name": "Changle Prensesi", "note": "Batı Wei hanedanı prensesi, 551'de evlendi", "certainty": "kesin"}], "children": [{"name": "İssik Kağan (Kolo)", "mother": "", "note": "Babasından sonra tahta çıktı", "certainty": "kesin"}, {"name": "Mukan Kağan (Kushu)", "mother": "", "note": "İkinci oğlu, devleti zirveye taşıdı", "certainty": "kesin"}, {"name": "Taspar Kağan", "mother": "", "note": "Üçüncü oğlu", "certainty": "kesin"}], "wars": [{"name": "Töles İsyanının Bastırılması", "when": "546", "foe": "Töles boyları", "result": "zafer", "note": "Juan-juan hükümdarına sadakat gösterip Tölesleri itaat altına aldı."}, {"name": "Juan-juan Savaşı", "when": "552", "foe": "Juan-juan (Avar) Kağanlığı", "result": "zafer", "note": "Anagui'yi yenerek intihara sürükledi ve kağanlığını ilan etti."}], "legends": ["Ergenekon'dan çıkış ve demir dağı eritme destanı Bumın'ın atalarıyla ilişkilendirilir."], "sources": [{"title": "TDV İslâm Ansiklopedisi, GÖKTÜRKLER", "url": "https://islamansiklopedisi.org.tr/gokturkler"}, {"title": "Britannica, Bumin", "url": "https://www.britannica.com/biography/Bumin"}]}, {"id": "gokturk-istemi", "name": "İstemi Yabgu", "aliases": ["İstemi Kağan", "Stembis Dizabul", "Dizaboulos", "Şidiemibao"], "title": "Batı Yabgusu / Kağan", "birth": null, "birthNote": "Kayıtlarda yok", "death": 576, "deathNote": "576 yılında batı karargâhında vefat etti", "reign": [552, 576], "reignNote": "Devletin batı kanadını 24 yıl boyunca bağımsız yetkilerle yönetti.", "summary": "Bumın Kağan'ın kardeşi ve Göktürklerin batı kanadının efsanevi kurucusu. Sâsânîler ile birleşerek Ak Hun Devleti'ni ortadan kaldırdı, ardından Bizans ile diplomatik ittifak kurarak İpek Yolu ticaretini Türk denetimine aldı.", "traits": ["Usta diplomat", "Büyük fatih", "Jeopolitik deha"], "contribution": "Türk sınırlarını Hazar ve Karadeniz kıyılarına ulaştırdı, Bizans ile ilk resmi elçilik ilişkilerini kurdu.", "harm": "Batı kanadına kazandırdığı muazzam güç, ölümünden sonra doğu-batı çatışmasının altyapısını oluşturdu.", "wives": [{"name": "Sâsânî Prensesi", "note": "I. Hüsrev Enûşirvân'ın kızı ile evlendi", "certainty": "olasi"}], "children": [{"name": "Tardu Kağan (Kara Çor)", "mother": "", "note": "Batı Göktürk Kağanı", "certainty": "kesin"}, {"name": "Tamgan Tarkan", "mother": "", "note": "Bizans'a elçi gönderilen heyetlerde adı geçer", "certainty": "olasi"}], "wars": [{"name": "Ak Hun Seferi", "when": "557", "foe": "Ak Hunlar (Eftalitler)", "result": "zafer", "note": "Sâsânîler ile ortak harekâtla Ak Hun devleti ortadan kaldırıldı."}, {"name": "Batı Seferleri ve Soğd Fethi", "when": "560-565", "foe": "Soğd şehir devletleri", "result": "zafer", "note": "Buhara ve Semerkant Türk egemenliğini tanıdı."}], "legends": ["Bizans elçisi Zemarkhos'un çadırında altın tahtta otururken gördüğü ihtişam anlatısı."], "sources": [{"title": "TDV İslâm Ansiklopedisi, İSTEMİ YABGU", "url": "https://islamansiklopedisi.org.tr/yabgu"}, {"title": "Britannica, Istemi", "url": "https://www.britannica.com/biography/Istemi"}]}, {"id": "gokturk-issik", "name": "İssik Kağan", "aliases": ["Kara Kağan", "Kolo"], "title": "Kağan", "birth": null, "birthNote": "Kayıtlarda yok", "death": 553, "deathNote": "Tahta çıktıktan bir yıl sonra vefat etti", "reign": [552, 553], "reignNote": "Bumın'ın vefatı üzerine tahta geçti, saltanatı birkaç ay sürdü.", "summary": "Bumın Kağan'ın büyük oğlu. Juan-juan kalıntılarını Lai-shan dağlarında kesin bir mağlubiyete uğratarak babasının zaferini perçinledi fakat kısa süre sonra hastalanarak öldü.", "traits": ["Cesur savaşçı"], "contribution": "Juan-juanların toparlanma çabalarını ezerek devletin bekasını güvenceye aldı.", "harm": "Erken ölümü hanedan içi taht intikallerini sıklaştırdı.", "wives": [], "children": [{"name": "İşbara Kağan (Şabolüe)", "mother": "", "note": "Daha sonra kağan oldu", "certainty": "kesin"}], "wars": [{"name": "Lai-shan Muharebesi", "when": "553", "foe": "Juan-juan bakiyeleri", "result": "zafer", "note": "Juan-juanların son direnişi kırıldı."}], "legends": [], "sources": [{"title": "TDV İslâm Ansiklopedisi, GÖKTÜRKLER", "url": "https://islamansiklopedisi.org.tr/gokturkler"}]}, {"id": "gokturk-mukan", "name": "Mukan Kağan", "aliases": ["Muqan", "Kushu", "Mu-han"], "title": "Kağan", "birth": null, "birthNote": "Kayıtlarda yok", "death": 572, "deathNote": "Ötüken'de vefat etti", "reign": [553, 572], "reignNote": "19 yıllık hükümdarlığı Birinci Kağanlığın altın çağıdır.", "summary": "Bumın Kağan'ın ikinci oğlu. Göktürk Kağanlığı'nı Avrasya'nın en kudretli süper gücü haline getirdi; Kıtayları, Kırgızları ve Juan-juan kalıntılarını tamamen boyun eğdirip Kuzey Çin krallıklarını (Kuzey Zhou ve Kuzey Qi) yıllık vergiye bağladı.", "traits": ["Heybetli görünüş", "Acımasız disiplin", "Yenilmez fatih"], "contribution": "İmparatorluk sınırlarını Kore körfezinden Sayan dağlarına kadar genişletti; bozkırda mutlak otorite kurdu.", "harm": "Aşırı sertliği çevre boylar arasında gizli bir husumet birikmesine yol açtı.", "wives": [], "children": [{"name": "Ashina Prensesi (İmparatoriçe Aşina)", "mother": "", "note": "Kuzey Zhou İmparatoru Wu ile evlendirildi", "certainty": "kesin"}, {"name": "Apa Kağan (Daluobian)", "mother": "", "note": "Taspar ölünce taht mücadelesi başlattı", "certainty": "kesin"}], "wars": [{"name": "Kuzey Seferleri", "when": "554-555", "foe": "Yenisey Kırgızları", "result": "zafer", "note": "Kırgızlar ve Baykal boyları bağlandı."}, {"name": "Doğu Kıtay Seferi", "when": "560", "foe": "Kıtaylar", "result": "zafer", "note": "Doğu bozkırları emniyete alındı."}], "legends": ["Çin kaynakları onun kızıl sakallı, mavi-yeşil gözlü ve sesinin gök gürültüsü gibi olduğunu rivayet eder."], "sources": [{"title": "TDV İslâm Ansiklopedisi, GÖKTÜRKLER", "url": "https://islamansiklopedisi.org.tr/gokturkler"}, {"title": "Britannica, Muqan", "url": "https://www.britannica.com/biography/Muqan"}]}, {"id": "gokturk-taspar", "name": "Taspar Kağan", "aliases": ["Tatpar", "Tobo"], "title": "Kağan", "birth": null, "birthNote": "Kayıtlarda yok", "death": 581, "deathNote": "Hastalık sonucu vefat etti", "reign": [572, 581], "reignNote": "Mukan'ın vasiyetiyle tahta oturdu.", "summary": "Mukan Kağan'ın kardeşi. Kuzey Çin hanedanları üzerindeki baskıyı ve yıllık vergi akışını sürdürdü. Budizm'e ilgi duyarak Soğdlu misyonerleri sarayına kabul etti ve Budist metinlerin Türkçeye tercümesini başlattı.", "traits": ["Barışsever", "Budizm'e meyilli", "Cömert"], "contribution": "Çin'den gelen muazzam ipek ve gümüş servetiyle halkının refahını artırdı; yazılı çeviri faaliyetlerine öncülük etti.", "harm": "Ölürken tahtı öz oğlu yerine Mukan'ın oğlu Apa'ya vasiyet etmesi, devleti bölecek taht kavgalarının fitilini ateşledi.", "wives": [], "children": [{"name": "Anluo (Amrak)", "mother": "", "note": "Taspar'ın oğlu, kısa süre tahta oturdu", "certainty": "kesin"}], "wars": [{"name": "Kuzey Qi Destek Seferi", "when": "577", "foe": "Kuzey Zhou hanedanı", "result": "sonucsuz", "note": "Kuzey Qi yıkılınca Türk sınırına sığınan prensleri korudu."}], "legends": ["Budist keşiş Jinagupta'yı sarayında ağırlayıp Nirvana Sutra'yı Türkçeye çevirttiği rivayet edilir."], "sources": [{"title": "TDV İslâm Ansiklopedisi, GÖKTÜRKLER", "url": "https://islamansiklopedisi.org.tr/gokturkler"}]}, {"id": "gokturk-isbara", "name": "İşbara Kağan", "aliases": ["Şabolüe", "Nivar", "Bagatur Şad"], "title": "Kağan", "birth": null, "birthNote": "Kayıtlarda yok", "death": 587, "deathNote": "Ötüken civarında vefat etti", "reign": [581, 587], "reignNote": "581 taht bunalımından sonra Anluo feragat edince tahta çıktı.", "summary": "İssik Kağan'ın oğlu. Tahta geçişiyle Apa Kağan ve Batı Yabgusu Tardu ile çatışmaya girdi. Sui hanedanının entrikaları, amansız kuraklık ve kıtlık yüzünden Çin'e karşı taviz vermek ve Sui imparatoruna vasallık mektubu göndermek zorunda kaldı.", "traits": ["Savaşçı", "Gururlu fakat çaresiz"], "contribution": "Apa Kağan'ın isyanını bastırarak doğu merkezini korumaya çalıştı.", "harm": "Devletin Doğu ve Batı olarak resmen ikiye bölünmesine engel olamadı; Çin üstünlüğünü kabul eden ilk kağan oldu.", "wives": [{"name": "Qianjin Prensesi", "note": "Kuzey Zhou prensesi, sonradan Sui soyadını aldı", "certainty": "kesin"}], "children": [{"name": "Tulan Kağan (Yongyulü)", "mother": "", "note": "Kendisinden sonra kağan oldu", "certainty": "kesin"}, {"name": "Kimin Kağan (Qimin)", "mother": "", "note": "Doğu Göktürk kağanı", "certainty": "kesin"}], "wars": [{"name": "Sui Sınır Seferleri", "when": "582", "foe": "Sui Hanedanı", "result": "yenilgi", "note": "Bozkırda baş gösteren açlık ve Çin savunması nedeniyle geri çekildi."}, {"name": "İç Savaş (Apa ile Çatışma)", "when": "583-585", "foe": "Apa Kağan ve Tardu", "result": "belirsiz", "note": "Devlet doğu ve batı kanadı olarak fiilen ayrıldı."}], "legends": ["Sui İmparatoruna yazdığı mektupta 'Geleneklerimizi, dilimizi ve saç biçimimizi değiştirmemizi istemeyiniz, buna töremiz izin vermez' dediği Çin kroniklerinde kayıtlıdır."], "sources": [{"title": "TDV İslâm Ansiklopedisi, GÖKTÜRKLER", "url": "https://islamansiklopedisi.org.tr/gokturkler"}]}]}, {"id": "bati-gokturk", "name": "Batı Göktürk Kağanlığı", "short": "Batı Göktürk", "aliases": ["On Ok Kağanlığı", "Batı Türk Kağanlığı"], "region": "bozkir", "start": 581, "end": 659, "startNote": "İstemi Yabgu soyundan Tardu'nun 581'de bağımsız kağanlık ilan etmesiyle kuruldu.", "endNote": "657-659 yıllarında Hallıg İşbara Kağan'ın Tang generali Su Dingfang'a yenilip esir düşmesiyle Çin himayesine girdi.", "capital": "Suyab ve Navekat (kışlak), Ming-Bulak (yaylak)", "religion": "Gök Tanrı inancı", "confidence": "kayit", "confidenceNote": "Çin kaynakları, Xuanzang'ın seyahatnamesi ve Soğd yazıtlarıyla sabittir.", "summary": "İstemi Yabgu'nun mirası üzerinde Seyhun, Çu, Talas ve Isık Göl çevresinde kurulan, On Ok boy federasyonuna dayalı kağanlık. Tong Yabgu döneminde Hazar Denizi'nden İndus Nehri'ne kadar uzanarak gücünün zirvesine ulaştı; Sâsânîlere karşı Bizans ile Kafkasya'da ittifak yaptı. Boylar arası iç çekişmeler (Tulu ve Nuşibi kabileleri) sonucunda 659'da Tang İmparatorluğu tarafından yıkıldı.", "legacy": "Batı Türkistan'daki Türk nüfusunu ve On Ok teşkilatını kalıcı kıldı. Türgiş ve Hazar devletlerinin mayasını oluşturdu; batıya göçen Türk boylarının siyasi omurgası oldu.", "essay": ["Batı Göktürk Kağanlığı, İstemi Yabgu'nun idare ettiği zengin ve stratejik Maveraünnehir sahasında doğdu. İstemi'nin oğlu Tardu Kağan (576-603), 581'de doğudaki kağanlık krizini fırsat bilerek bağımsızlığını ilan etti ve tüm Göktürk imparatorluğunu tek elde toplamak için Ötüken'e saldırdı.", "Devletin en kudretli hükümdarı Tong Yabgu Kağan (618-628) oldu. Çinli Budist seyyah Xuanzang, 630 civarında Suyab'da ziyaret ettiği Tong Yabgu'nun altın işlemeli ipek çadırını, yeşil saten kaftanlı subaylarını ve yüzlerce süvarisinin debdebesini hayranlıkla anlatır. Tong Yabgu, Bizans İmparatoru Herakleios ile ittifak kurarak Tiflis Kuşatması'na katıldı ve Sâsânîlerin çöküşünü hızlandırdı.", "Tong Yabgu'nun amcası Külüg Sibir tarafından öldürülmesiyle devlet On Ok boylarının iki büyük fraksiyonu olan Tulu (Dulu) ve Nuşibi kabileleri arasında bitmek bilmeyen bir iç savaşa sürüklendi. Son bağımsız hükümdar Hallıg İşbara Kağan (Ashina Helu), boyları birleştirmeye çalıştıysa da 657 İrtiş Muharebesi'nde Tang ordularına yenilerek esir düştü ve 659'da devlet tamamen dağıldı."], "sources": [{"title": "TDV İslâm Ansiklopedisi, GÖKTÜRKLER", "url": "https://islamansiklopedisi.org.tr/gokturkler"}, {"title": "Britannica, Western Turkic Khaganate", "url": "https://www.britannica.com/place/Turkic-khaganates"}], "rulers": [{"id": "bati-gokturk-tardu", "name": "Tardu Kağan", "aliases": ["Kara Çor", "Datou", "Bilig Kağan"], "title": "Kağan", "birth": null, "birthNote": "Kayıtlarda yok", "death": 603, "deathNote": "Töles isyanı sırasında Kuku-nor civarında kayboldu veya öldürüldü", "reign": [576, 603], "reignNote": "576'da babası İstemi'nin yerine yabgu oldu, 581'den sonra bağımsız kağan unvanı aldı.", "summary": "İstemi Yabgu'nun oğlu. Batı Göktürklerini bağımsız bir imparatorluğa dönüştürdü. Hem Doğu Göktürk tahtını hem Çin'i ele geçirmek için devasa ordularla sefere çıktı fakat Çin entrikaları ve su kaynaklarının zehirlenmesiyle Töles boylarının isyanı sonucu mağlup oldu.", "traits": ["Gözü pek", "Büyük hedefleri olan fatih", "Otoriter"], "contribution": "Batı Göktürk sahasını Sâsânî sınırından Çin içlerine kadar genişletti.", "harm": "Doğu Göktürkleri ile giriştiği amansız iç savaş Türk birliğini kalıcı biçimde parçaladı.", "wives": [], "children": [{"name": "Nili Kağan", "mother": "", "note": "Kısa süre kağan oldu", "certainty": "kesin"}, {"name": "Külüg Sibir", "mother": "", "note": "Tong Yabgu'yu deviren kağan", "certainty": "kesin"}], "wars": [{"name": "Ötüken Seferi", "when": "582-584", "foe": "Doğu Göktürk (İşbara Kağan)", "result": "sonucsuz", "note": "Bütün Türk illerini birleştirme girişimi Çin müdahalesiyle durduruldu."}, {"name": "Töles İsyanı", "when": "601-603", "foe": "Töles boyları", "result": "yenilgi", "note": "Çin'in kışkırttığı boylar Tardu'nun ordusunu dağıttı."}], "legends": ["Soğdca Bugut yazıtında İstemi ile birlikte adı anılan kudretli liderlerdendir."], "sources": [{"title": "TDV İslâm Ansiklopedisi, GÖKTÜRKLER", "url": "https://islamansiklopedisi.org.tr/gokturkler"}]}, {"id": "bati-gokturk-tong-yabgu", "name": "Tong Yabgu Kağan", "aliases": ["Ziebel", "Tong Shehu", "Tung Yabgu"], "title": "Kağan", "birth": null, "birthNote": "Kayıtlarda yok", "death": 628, "deathNote": "Amcası Külüg Sibir'in suikastı sonucu öldürüldü", "reign": [618, 628], "reignNote": "Batı Kağanlığının en görkemli 10 yılı.", "summary": "Batı Göktürk Kağanlığı'nı gücünün zirvesine taşıyan büyük hükümdar. İpek Yolu'nun tüm kilit şehirlerini zaptetti, güneyde Gandhara ve İndus havzasına kadar indi. Bizans ile ittifak yaparak Sâsânî İmparatorluğu'na karşı Kafkasya cephesini açtı.", "traits": ["İhtişamlı hükümdar", "Askerî dahi", "Uluslararası vizyon"], "contribution": "Devletin hazinesini ve sınırlarını en üst noktaya ulaştırdı; On Ok teşkilatını sağlamlaştırdı.", "harm": "Akrabaları arasındaki kıskançlığı yönetemedi, suikasta uğramasıyla devlet 30 yıllık iç savaşa sürüklendi.", "wives": [], "children": [{"name": "Se-Yabgu Kağan", "mother": "", "note": "Babasından sonra taht mücadelesine girdi", "certainty": "kesin"}, {"name": "Tardu Şad", "mother": "", "note": "Toharistan valisi yapıldı", "certainty": "kesin"}], "wars": [{"name": "Tiflis Seferi", "when": "627-628", "foe": "Sâsânî İmparatorluğu", "result": "zafer", "note": "Bizans İmparatoru Herakleios ile birleşerek Tiflis ele geçirildi."}], "legends": ["Xuanzang onun sarayındaki Soğd ve Türk beylerinin altın ve ipek zarafetini hayranlıkla kaydetmiştir."], "sources": [{"title": "TDV İslâm Ansiklopedisi, GÖKTÜRKLER", "url": "https://islamansiklopedisi.org.tr/gokturkler"}, {"title": "Britannica, Tong Yabghu", "url": "https://www.britannica.com/biography/Tong-Yabghu"}]}, {"id": "bati-gokturk-hallig-isbara", "name": "Hallıg İşbara Kağan", "aliases": ["Ashina Helu", "Shaboluo Kağan"], "title": "Kağan", "birth": null, "birthNote": "Kayıtlarda yok", "death": 659, "deathNote": "Chang'an'da esaret altında vefat etti", "reign": [651, 657], "reignNote": "657 İrtiş savaşında yenildi, 659'da esarette öldü.", "summary": "Batı Göktürk Kağanlığı'nın son bağımsız kağanı. Birbirine düşen Tulu ve Nuşibi kabilelerini tek çatı altında toplayarak Çin'e karşı direniş başlattı ancak Tang ordularının devasa istilasına karşı İrtiş Nehri boylarında mağlup oldu.", "traits": ["Son direnişçi", "Cesur"], "contribution": "Bölünmüş On Ok boylarını son bir defa bağımsızlık ülküsü etrafında birleştirdi.", "harm": "Yenilgisiyle Batı Türkistan kapıları Çin askeri valiliklerine açıldı.", "wives": [], "children": [], "wars": [{"name": "İrtiş Nehri Muharebesi", "when": "657", "foe": "Tang Hanedanı (General Su Dingfang)", "result": "yenilgi", "note": "Kar fırtınasında yapılan savaşta Türk ordusu yenildi, kağan Taşbent'e kaçtıysa da teslim edildi."}], "legends": [], "sources": [{"title": "TDV İslâm Ansiklopedisi, GÖKTÜRKLER", "url": "https://islamansiklopedisi.org.tr/gokturkler"}]}]}, {"id": "dogu-gokturk", "name": "Doğu Göktürk Kağanlığı", "short": "Doğu Göktürk", "aliases": ["Doğu Türk Kağanlığı", "Ötüken Kağanlığı"], "region": "bozkir", "start": 581, "end": 630, "startNote": "Taspar Kağan'ın ölümünden sonra 581'de başlayan bölünmeyle Ötüken merkezli şekillendi.", "endNote": "630 Yinshan Muharebesi'nde İllig Kağan'ın Tang ordusuna esir düşmesiyle yıkıldı; 50 yıllık Çin esareti dönemi başladı.", "capital": "Ötüken", "religion": "Gök Tanrı inancı", "confidence": "kayit", "confidenceNote": "Orhun yazıtları ve Tang Hanedanı yıllıklarında (Tang Shu) teferruatıyla kayıtlıdır.", "summary": "581 bölünmesi sonrasında Ötüken ve Moğolistan merkezli varlığını sürdüren Göktürk ana kolu. Şibi ve İllig kağanlar devrinde zayıflayan Sui hanedanına karşı üstünlük sağlayıp Tang hanedanının kuruluşunda belirleyici rol oynadılar. Ancak 620'lerin sonundaki ağır kış şartları, Töles boylarının isyanı ve Tang İmparatoru Taizong'un saldırıları sonucu 630'da İllig Kağan esir düştü ve devlet yıkıldı.", "legacy": "Yıkılışının ardından yaşanan 50 yıllık esaret dönemi ve Kürşad (Ashina Jiesheshuai) ayaklanması, Türk bağımsızlık bilincini diri tutarak 682'de İkinci Göktürk Kağanlığı'nın doğuşuna zemin hazırladı.", "essay": ["Doğu Göktürk Kağanlığı, 581 yılındaki hanedan kavgasından sonra Ötüken yaylasını elinde tutan kağanların idaresinde devam etti. İlk yıllarda Sui entrikaları ve açlık sebebiyle Çin üstünlüğünü tanımak zorunda kalan Kimin Kağan, Sui himayesinde güç topladı.", "Kimin'in oğlu Şibi Kağan (609-619) tahta çıkınca Çin'e boyun eğme siyasetini terk etti. Sui hanedanının çöküş yıllarını çok iyi değerlendirerek 615'te Yanmen'de Çin İmparatoru Yang'ı yüz bin süvariyle kuşattı. Şibi ve halefi Çula Kağan, Çin'deki iç savaşta yerel asilere ve Tang hanedanının kurucusu Li Yuan'a destek vererek onları kendilerine tabi kıldı.", "İllig Kağan (620-630) döneminde Türk akınları Çin başkenti Chang'an yakınlarına kadar ulaştı ve 626'da Köprü Paktı ile İmparator Taizong haraca bağlandı. Ancak sonraki yıllarda peş peşe gelen şiddetli kar fırtınaları hayvan sürülerinin telef olmasına ve kıtlığa yol açtı. Uygur ve Sir-Tarduş boylarının isyanını fırsat bilen Tang ordusu 630'da Yinshan'da gece baskınıyla İllig Kağan'ı esir aldı ve Doğu Göktürk Kağanlığı tarihe karıştı."], "sources": [{"title": "TDV İslâm Ansiklopedisi, GÖKTÜRKLER", "url": "https://islamansiklopedisi.org.tr/gokturkler"}, {"title": "Britannica, Eastern Turkic Khaganate", "url": "https://www.britannica.com/place/Turkic-khaganates"}], "rulers": [{"id": "dogu-gokturk-qimin", "name": "Kimin Kağan", "aliases": ["Qimin", "Yami", "Ashina Rangan"], "title": "Kağan", "birth": null, "birthNote": "Kayıtlarda yok", "death": 609, "deathNote": "Hastalanarak vefat etti", "reign": [600, 609], "reignNote": "Sui desteğiyle Tulan Kağan'ın yerine tahta oturtuldu.", "summary": "İşbara Kağan'ın oğlu. Tulan Kağan ile çatışmasında Çin'e sığındı; Sui hanedanının desteğiyle güney sınırında güçlenip Tulan'ın ölümüyle Ötüken tahtına sahip oldu. Çin ile barış içinde yaşadı.", "traits": ["Çin yanlısı", "Diplomat"], "contribution": "Kıtlık ve kargaşa içindeki Doğu boylarının toparlanmasını ve nüfusun yeniden artmasını sağladı.", "harm": "Çin sarayına aşırı tavizler verdi, bağımsızlık ruhunu geçici olarak zedeledi.", "wives": [{"name": "Yicheng Prensesi", "note": "Sui hanedanı prensesi, dört Göktürk kağanına eşlik etti", "certainty": "kesin"}], "children": [{"name": "Şibi Kağan (Duojishi)", "mother": "", "note": "Babasından sonra bağımsızlığı yeniden kurdu", "certainty": "kesin"}, {"name": "Çula Kağan", "mother": "", "note": "İkinci oğlu", "certainty": "kesin"}, {"name": "İllig Kağan (Duobi)", "mother": "", "note": "Son Doğu kağanı", "certainty": "kesin"}], "wars": [{"name": "Tulan Kağan ile Taht Savaşı", "when": "599", "foe": "Tulan Kağan ve Tardu", "result": "zafer", "note": "Sui ordusunun yardımıyla galip geldi."}], "legends": [], "sources": [{"title": "TDV İslâm Ansiklopedisi, GÖKTÜRKLER", "url": "https://islamansiklopedisi.org.tr/gokturkler"}]}, {"id": "dogu-gokturk-sibi", "name": "Şibi Kağan", "aliases": ["Shibi", "Duojishi"], "title": "Kağan", "birth": null, "birthNote": "Kayıtlarda yok", "death": 619, "deathNote": "Sefer hazırlığı sırasında Taiyuan civarında öldü", "reign": [609, 619], "reignNote": "10 yıl hüküm sürdü.", "summary": "Kimin Kağan'ın oğlu. Çin vesayetini kökünden söküp attı. 615 yılında Yanmen Kalesi'nde Sui İmparatoru Yang'ı kuşatarak Çin'i dize getirdi ve Tang hanedanının kuruluşunda hamisi rolü oynadı.", "traits": ["Yetenekli komutan", "Bağımsızlık taraftarı", "Stratejist"], "contribution": "Göktürk askeri üstünlüğünü yeniden tesis etti, Çin hanedanlarını haraca bağladı.", "harm": "Çin'deki iç savaşa aşırı müdahil olması kaynak israfına yol açtı.", "wives": [{"name": "Yicheng Prensesi", "note": "Babasının dul eşiyle levirat geleneği gereği evlendi", "certainty": "kesin"}], "children": [{"name": "Tolis Kağan (Shibobi)", "mother": "", "note": "Doğu kanadı şadı", "certainty": "kesin"}, {"name": "Ashina Jiesheshuai (Kürşad)", "mother": "", "note": "639 saray baskınının lideri", "certainty": "kesin"}], "wars": [{"name": "Yanmen Kuşatması", "when": "615", "foe": "Sui Hanedanı (İmparator Yang)", "result": "zafer", "note": "İmparator kuşatıldı, Yicheng'in sahte tehlike haberiyle kuşatma kaldırıldı."}], "legends": ["Kürşad Destanı'na ilham veren ünlü prens Ashina Jiesheshuai onun oğludur."], "sources": [{"title": "TDV İslâm Ansiklopedisi, GÖKTÜRKLER", "url": "https://islamansiklopedisi.org.tr/gokturkler"}]}, {"id": "dogu-gokturk-illig", "name": "İllig Kağan", "aliases": ["Kie-li", "Kara Kağan", "Duobi", "Bagatur Kağan"], "title": "Kağan", "birth": null, "birthNote": "Kayıtlarda yok", "death": 634, "deathNote": "Chang'an'da Çin esaretinde kederinden vefat etti", "reign": [620, 630], "reignNote": "630'da Tang ordusuna esir düşerek devleti son buldu.", "summary": "Doğu Göktürk Kağanlığı'nın son hükümdarı. 626'da Çin başkenti önündeki Wei Nehri Köprüsü'nde Tang İmparatoru Taizong ile barış antlaşması yaptı. İklim felaketleri ve Töles isyanlarıyla zayıflayınca 630'da Yinshan'da esir düştü.", "traits": ["Cesur fakat sabırsız", "Baskıcı"], "contribution": "Çin içlerine kadar uzanan seferlerle Tang hanedanını uzun süre baskı altında tuttu.", "harm": "Doğal afetler sırasında Soğdlu danışmanlarının telkiniyle boylara ağır vergiler koyarak Uygur ve Sir-Tarduşların isyan etmesine yol açtı; devletin yıkılmasına sebep oldu.", "wives": [{"name": "Yicheng Prensesi", "note": "630 yenilgisinde Tang ordusunca öldürüldü", "certainty": "kesin"}], "children": [{"name": "Yutuk Şad", "mother": "", "note": "Kayıtlarda adı geçen şehzade", "certainty": "olasi"}], "wars": [{"name": "Wei Nehri Seferi (Köprü Paktı)", "when": "626", "foe": "Tang Hanedanı", "result": "antlasma", "note": "Chang'an kapılarına dayandı, beyaz at kurban edilerek barış yapıldı."}, {"name": "Yinshan (Baishidao) Muharebesi", "when": "630", "foe": "Tang Ordusu (General Li Jing)", "result": "yenilgi", "note": "Gece baskınında ordusu dağıldı, kendisi kaçarken yakalanıp esir edildi."}], "legends": ["Çin sarayında kendisine verilen unvanları reddedip kederinden dans etmeye zorlandığı rivayet edilir."], "sources": [{"title": "TDV İslâm Ansiklopedisi, GÖKTÜRKLER", "url": "https://islamansiklopedisi.org.tr/gokturkler"}, {"title": "Britannica, Illig Qaghan", "url": "https://www.britannica.com/biography/Illig-Qaghan"}]}]}, {"id": "ikinci-gokturk", "name": "İkinci Göktürk Kağanlığı", "short": "II. Göktürk (Kutluk)", "aliases": ["Kutluk Kağanlığı", "Doğu Kök Türk Kağanlığı"], "region": "bozkir", "start": 682, "end": 745, "startNote": "Kutluk (İlteriş) Kağan'ın 682'de Çin esaretine son verip Ötüken'i geri almasıyla kuruldu.", "endNote": "744-745 yıllarında Uygur, Basmıl ve Karluk ittifakının saldırısıyla son kağan Ozmış ve Bomei öldürülerek yıkıldı.", "capital": "Ötüken", "religion": "Gök Tanrı inancı", "confidence": "kayit", "confidenceNote": "Orhun Yazıtları (Kül Tigin, Bilge Kağan, Tonyukuk) bizzat bu devletin yöneticileri tarafından dikilmiştir.", "summary": "50 yıllık Çin esaretine başkaldıran Kutluk İlteriş Kağan, Vezir Tonyukuk ve ardından Kapgan ile Bilge Kağan kardeşler önderliğinde kurulan ikinci şanlı imparatorluk. Türk edebiyatı ve tarihinin ilk yazılı abideleri olan Orhun Yazıtları bu dönemde dikildi. Asya bozkırındaki tüm Türk boylarını yeniden Ötüken'e bağladılar; Çin'e karşı onlarca zafer kazandılar. 744'te Uygur-Karluk-Basmıl ittifakıyla yıkıldı.", "legacy": "Orhun Yazıtları ile ebedi milli şuuru taşa kazıdı. İlteriş, Tonyukuk, Kül Tigin ve Bilge Kağan Türk devlet aklının ve vatan sevgisinin ölümsüz sembolleri haline geldi.", "essay": ["630 yılında Doğu Göktürk Kağanlığı'nın yıkılmasıyla başlayan elli yıllık esaret dönemi, Türk milletinin hafızasında derin yaralar açtı. 639 yılında Changan sarayını basan Kürşad (Ashina Jiesheshuai) ihtilali bağımsızlık kıvılcımını tutuşturdu. Nihayet 682'de Aşina soyundan Kutluk, yanındaki onyedi silah arkadaşıyla dağa çıktı; kısa sürede boyları toplayıp 'İlteriş' (devleti derleyen) unvanıyla Ötüken'de İkinci Göktürk Kağanlığı'nı ilan etti. Bilge Tonyukuk ise başvezir ve ordu komutanı oldu.", "İlteriş'in ardından tahta geçen kardeşi Kapgan Kağan (691-716), Türk tarihinin en amansız fatihlerinden biri oldu. Çin içlerine 25 büyük sefer düzenledi, Demir Kapı'ya ve Maveraünnehir'e kadar ulaştı; Kırgızları, Türgişleri ve Kıtayları ezdi. Ancak aşırı sert siyaseti boyların isyanına sebep oldu ve 716'da Bayırku pususunda öldürüldü.", "Kapgan'ın oğlu İnel'i kansız bir darbeyle tasfiye eden İlteriş'in oğulları Bilge Kağan ve Kül Tigin tahta geçti. Bilge hükümdar, Kül Tigin ordular komutanı, tecrübeli Tonyukuk ise vezir olarak devleti muazzam bir ahenkle yönetti. 731'de Kül Tigin'in, 734'te Bilge Kağan'ın vefatıyla tahta geçen genç kağanlar iç çekişmeleri önleyemedi. 744-745'te Uygur, Karluk ve Basmıl ittifakı Ötüken'i ele geçirerek devlete son verdi."], "sources": [{"title": "TDV İslâm Ansiklopedisi, GÖKTÜRKLER", "url": "https://islamansiklopedisi.org.tr/gokturkler"}, {"title": "TDV İslâm Ansiklopedisi, BİLGE KAĞAN", "url": "https://islamansiklopedisi.org.tr/bilge-kagan"}, {"title": "TDV İslâm Ansiklopedisi, KÜL TİGİN", "url": "https://islamansiklopedisi.org.tr/kul-tigin"}, {"title": "TDV İslâm Ansiklopedisi, TONYUKUK", "url": "https://islamansiklopedisi.org.tr/tonyukuk"}], "rulers": [{"id": "ikinci-gokturk-ilteris", "name": "Kutluk İlteriş Kağan", "aliases": ["İlteriş Kağan", "Kutluk"], "title": "İlteriş Kağan", "birth": null, "birthNote": "Kayıtlarda yok", "death": 691, "deathNote": "Ötüken'de vefat etti", "reign": [682, 691], "reignNote": "Devleti 17 kişiyle başlatıp 9 yılda yeniden kurdu.", "summary": "İkinci Göktürk Kağanlığı'nın kurucusu. 50 yıllık Çin esaretini yıkarak dağınık Türk boylarını birleştirdi; 'İli (devleti) toplayıp derleyen' manasına gelen İlteriş unvanını aldı. Kırk yedi sefer düzenleyip yirmi savaş kazandı.", "traits": ["Kurtarıcı ata", "Büyük teşkilatçı", "İnançlı lider"], "contribution": "Türk milletini esaretten kurtararak bağımsız devlete ve Ötüken ana vatanına kavuşturdu.", "harm": "Erken vefatı sebebiyle çocukları küçük yaşta kaldı, taht kardeşi Kapgan'a geçti.", "wives": [{"name": "İlbilge Hatun", "note": "Bilge Kağan ve Kül Tigin'in annesi; yazıtlarda kutlu hatun olarak anılır", "certainty": "kesin"}], "children": [{"name": "Bilge Kağan (Bögü)", "mother": "İlbilge Hatun", "note": "Daha sonra kağan oldu", "certainty": "kesin"}, {"name": "Kül Tigin", "mother": "İlbilge Hatun", "note": "Büyük kahraman ve başkomutan", "certainty": "kesin"}], "wars": [{"name": "Bağımsızlık İsyanı ve Ötüken Fethi", "when": "682", "foe": "Tang garnizonları ve Dokuz Oğuzlar", "result": "zafer", "note": "Ötüken ele geçirilerek kağanlık ilan edildi."}, {"name": "Çin Sınır Seferleri", "when": "683-687", "foe": "Tang Hanedanı", "result": "zafer", "note": "Shanxi ve Hebei bölgeleri vurularak ordu techiz edildi."}], "legends": ["Orhun Yazıtlarında: 'Babam kağan on yedi erle dışarı çıkmış... Tanrı güç verdiği için babam kağanın askeri kurt gibi imiş, yağısı koyun gibi imiş' sözleriyle ölümsüzleştirilmiştir."], "sources": [{"title": "TDV İslâm Ansiklopedisi, GÖKTÜRKLER", "url": "https://islamansiklopedisi.org.tr/gokturkler"}, {"title": "TDV İslâm Ansiklopedisi, KUTLUK İLTERİŞ KAĞAN", "url": "https://islamansiklopedisi.org.tr/turk"}]}, {"id": "ikinci-gokturk-kapgan", "name": "Kapgan Kağan", "aliases": ["Qapaghan", "Mochuo", "Bögü Kağan"], "title": "Kağan", "birth": 664, "birthNote": "Yaklaşık 664 doğumlu", "death": 716, "deathNote": "Bayırkuların pususunda öldürüldü", "reign": [691, 716], "reignNote": "25 yıllık fetihlerle dolu fırtınalı hükümdarlık.", "summary": "İlteriş Kağan'ın kardeşi. Devleti Asya'nın bir ucundan diğer ucuna genişletti; Çin İmparatoriçesi Wu Zetian'ı yıllık yüz binlerce ölçek tahıl ve ipek vermeye mecbur etti. Bolçu'da Türgişleri, Kırgızları ve Soğdları dize getirdi fakat son yıllarındaki aşırı sertliği boyları isyana sevk etti.", "traits": ["Cihangir fatih", "Acımasız disiplin", "Durdurulamaz ordu komutanı"], "contribution": "Göktürk sınırlarını Mançurya'dan Maveraünnehir'deki Demir Kapı'ya kadar ulaştırdı; Çin'e tam bağımlılığı tersine çevirdi.", "harm": "Aşırı sertliği Türk boylarının (Oğuzlar, Dokuz Tatarlar, Karluklar) peş peşe isyan etmesine yol açtı; ölümünde devleti iç savaşın eşiğinde bıraktı.", "wives": [], "children": [{"name": "İnel Kağan (Bögü)", "mother": "", "note": "Babasından sonra kısa süre tahta oturdu", "certainty": "kesin"}, {"name": "Tongra Tarkan", "mother": "", "note": "Şehzade", "certainty": "olasi"}, {"name": "Mo Şad", "mother": "", "note": "Sol kanat şadı", "certainty": "olasi"}], "wars": [{"name": "Bolçu Muharebesi", "when": "698", "foe": "Türgiş Kağanlığı", "result": "zafer", "note": "Türgişler bozguna uğratıldı, On Ok sahası bağlandı."}, {"name": "Sayan Dağları Seferi", "when": "710", "foe": "Yenisey Kırgızları", "result": "zafer", "note": "Kırgız Kağanı Bars Bey mağlup edilerek öldürüldü."}, {"name": "Demir Kapı Seferi", "when": "701", "foe": "Soğd ve Emevi öncüleri", "result": "zafer", "note": "Tonyukuk komutasında Semerkant ve Ceyhun boyuna inildi."}], "legends": ["Çin sarayının onun korkusundan başkentin surlarını güçlendirdiği ve prenses göndermek için yalvardığı kaydedilir."], "sources": [{"title": "TDV İslâm Ansiklopedisi, GÖKTÜRKLER", "url": "https://islamansiklopedisi.org.tr/gokturkler"}]}, {"id": "ikinci-gokturk-bilge", "name": "Bilge Kağan", "aliases": ["Bögü", "Mogilian"], "title": "Kağan", "birth": 683, "birthNote": "683 yılı civarında doğdu", "death": 734, "deathNote": "Bakanı Buyruk Çor tarafından zehirlenerek öldürüldü", "reign": [716, 734], "reignNote": "18 yıllık altın dönem.", "summary": "İlteriş Kağan'ın büyük oğlu. Kardeşi Kül Tigin'in askeri dehası ve kayınpederi Bilge Tonyukuk'un bilgeliğiyle devleti yönetti. İsyan eden boyları yatıştırdı, Çin ile dengeli bir ticaret ve barış politikası kurdu. Kendi adına ve kardeşi adına Orhun Yazıtları'nı diktirdi.", "traits": ["Milletini seven ulu hakan", "Adil", "Bilge ve sabırlı"], "contribution": "Halkını doyuran ve giydiren sosyal devlet anlayışını getirdi; Türk kimliğini ölümsüzleştiren Orhun Abideleri'ni inşa ettirdi.", "harm": "Budizm ve Şehircilik hevesi Tonyukuk tarafından bozkır bağımsızlığına aykırı görülerek engellendi; zehirlenmesini önleyemedi.", "wives": [{"name": "El-Etmiş Bilge Hatun (Po Beg)", "note": "Tonyukuk'un kızı, bilge hatun", "certainty": "kesin"}], "children": [{"name": "Yollıg Kağan", "mother": "El-Etmiş Bilge Hatun", "note": "Babası ve amcasının yazıtlarını kaleme alan edip kağan", "certainty": "kesin"}, {"name": "Tengri Kağan", "mother": "El-Etmiş Bilge Hatun", "note": "Genç yaşta kağan oldu", "certainty": "kesin"}], "wars": [{"name": "Oğuz İsyanlarının Bastırılması", "when": "716-718", "foe": "Dokuz Oğuzlar", "result": "zafer", "note": "Kül Tigin ile birlikte beş büyük savaşta Oğuzları dize getirdi."}, {"name": "Lanshan Muharebesi", "when": "720", "foe": "Tang Hanedanı ve Kıtaylar", "result": "zafer", "note": "Çin'in büyük kuşatma ordusu püskürtüldü, Gansu yağmalandı."}], "legends": ["'Ey Türk milleti! Üstte mavi gök çökmedikçe, altta yağız yer delinmedikçe senin ilini ve töreni kim bozabilir?' hitabı onun ebedi mirasıdır."], "sources": [{"title": "TDV İslâm Ansiklopedisi, BİLGE KAĞAN", "url": "https://islamansiklopedisi.org.tr/bilge-kagan"}, {"title": "Britannica, Bilge Kagan", "url": "https://www.britannica.com/biography/Bilge-Kagan"}]}]}, {"id": "turges", "name": "Türgiş Kağanlığı", "short": "Türgiş", "aliases": ["Türgişler", "Türkeş Devleti"], "region": "bozkir", "start": 717, "end": 766, "startNote": "Batı Göktürklerin On Ok kolundan Türgiş boyunun Sulu Kağan önderliğinde bağımsız kağanlık kurması.", "endNote": "766'da Karlukların Talas ve Çu boylarını ele geçirmesiyle kağanlık sona erdi.", "capital": "Suyab (kuzey/büyük merkez), Taraz / Talas (küçük merkez)", "religion": "Gök Tanrı inancı, Maniheizm ve Budizm izleri", "confidence": "kayit", "confidenceNote": "Arap kronikleri (Taberî, İbnü'l-Esîr) ve Tang yıllıklarında kapsamlı biçimde anlatılır.", "summary": "Batı Göktürk mirası üzerinde Yedisu ve Isık Göl çevresinde kurulan, Maveraünnehir'e giren Emevi Arap ordularına karşı destansı bir direniş gösteren Türk devleti. Sulu Kağan (Arap kaynaklarında Ebu Müzahim / 'Zahmet Veren') komutasında Emevileri defalarca hezimete uğratarak Orta Asya'nın erken dönemde tamamen Araplaşmasını ve fethini durdurdular. Sarı ve Kara Türgiş iç çatışmalarıyla zayıflayıp 766'da yerlerini Karluklara bıraktılar.", "legacy": "Maveraünnehir Türk ve Soğd kültürünün İslam fetihlerine karşı korunmasında kalkan oldu; kendi adına ilk madeni Türk parasını (Türgiş sikkeleri) darp ettiler.", "essay": ["Türgişler, Batı Göktürklerin On Ok birliğine mensup Duolu boyları arasından sivrildi. 7. yüzyıl sonunda Uçele önderliğinde güçlenen Türgişler, İkinci Göktürk Kağanı Kapgan'ın 698 Bolçu zaferiyle geçici olarak bastırıldıysa da 717 civarında Sulu Kağan tahta geçerek devleti tam bağımsız bir bölgesel süper güce dönüştürdü.", "Sulu Kağan, Emevi ordularının Maveraünnehir'e yönelik yayılmasını durduran en büyük engel oldu. 724'te 'Susuzluk Günü' (Yevmü'l-Ataş) savaşında Emevi ordusunu Seyhun kıyısında feci bir hezimete uğrattı. 731'deki Tahtakaraca Geçidi Muharebesi'nde Arap ordusunu Semerkant yakınlarında neredeyse tamamen imha etti. Hareketli süvari taktikleri sebebiyle Araplar ona 'Ebu Müzahim' (Zahmet Veren / Toslayan Boğa) lakabını taktılar.", "Sulu Kağan'ın 738'de rakibi Kül Çor (Baga Tarkan) tarafından bir çadır suikastında öldürülmesiyle Türgişler 'Sarı' ve 'Kara' hizipler halinde amansız bir iç harbe sürüklendi. Bu zafiyet 751 Talas Savaşı'na zemin hazırladı ve 766'da Karluk boylarının Çu vadisine inmesiyle Türgiş egemenliği tarihe karıştı."], "sources": [{"title": "TDV İslâm Ansiklopedisi, TÜRGEŞLER", "url": "https://islamansiklopedisi.org.tr/turgesler"}, {"title": "Britannica, Turgesh", "url": "https://www.britannica.com/topic/Turgesh"}], "rulers": [{"id": "turges-ucele", "name": "Uçele Kağan", "aliases": ["Wuzhile", "Üç-Elig"], "title": "Kağan", "birth": null, "birthNote": "Kayıtlarda yok", "death": 706, "deathNote": "Yedisu'da vefat etti", "reign": [699, 706], "reignNote": "Türgiş birliğini kuran ilk lider.", "summary": "Batı Göktürk çözülüşü sırasında Suyab merkezli 20 tümenlik büyük bir güç toplayarak Türgiş bağımsızlığının temelini atan kurucu şahsiyet.", "traits": ["Teşkilatçı", "Halk önderi"], "contribution": "On Ok sahasını yeniden derleyip Türk hakimiyetini kurdu.", "harm": "İkinci Göktürk Kağanlığı ile çatışarak bozkır güçlerini böldü.", "wives": [], "children": [{"name": "Sa-kal Kağan", "mother": "", "note": "Babasından sonra kağan oldu", "certainty": "kesin"}], "wars": [{"name": "Suyab Fethi", "when": "699", "foe": "Tang garnizonu", "result": "zafer", "note": "Suyab şehri ele geçirilip başkent yapıldı."}], "legends": [], "sources": [{"title": "TDV İslâm Ansiklopedisi, TÜRGEŞLER", "url": "https://islamansiklopedisi.org.tr/turgesler"}]}, {"id": "turges-sulu", "name": "Sulu Kağan", "aliases": ["Su-lu", "Ebu Müzahim", "Suluk Çor"], "title": "Kağan", "birth": null, "birthNote": "Kayıtlarda yok", "death": 738, "deathNote": "Navakat'ta Kül Çor tarafından gece çadırında katledildi", "reign": [716, 738], "reignNote": "22 yıl boyunca Emevilere karşı destansı direniş yürüttü.", "summary": "Türgiş Devleti'nin en büyük hükümdarı. Emevi Hilafeti'nin Orta Asya'yı fethini durduran efsanevi başbuğ. Susuzluk Günü ve Tahtakaraca savaşlarında Arap ordularını ağır mağlubiyetlere uğrattı. Araplar çetin savaşçılığı sebebiyle ona Ebu Müzahim adını verdi.", "traits": ["Cesur süvari komutanı", "Bozkır taktik ustası", "Meydan okuyan"], "contribution": "Maveraünnehir ve Türkistan'ın erken dönemde zorla Araplaşmasını engelledi; Türklerin bağımsız kalmasını sağladı.", "harm": "Son döneminde kibri ve ganimet dağıtımındaki haksızlıkları beylerini kendisine düşman etti; suikasta kurban gitti.", "wives": [{"name": "Göktürk Prensesi", "note": "Bilge Kağan'ın kızı ile evlendi", "certainty": "kesin"}, {"name": "Tibet Prensesi", "note": "Tibet kralının kızı ile ittifak evliliği", "certainty": "olasi"}], "children": [{"name": "Kut-Çor (Tukvarşen)", "mother": "", "note": "Veliaht şehzade", "certainty": "kesin"}], "wars": [{"name": "Susuzluk Günü Muharebesi (Yevmü'l-Ataş)", "when": "724", "foe": "Emevi Ordusu (Müslim b. Said)", "result": "zafer", "note": "Seyhun kıyısında Emevi ordusu kuşatılarak perişan edildi."}, {"name": "Tahtakaraca Geçidi Muharebesi (Vak'atü'ş-Şib)", "when": "731", "foe": "Emevi Ordusu (Cüneyd b. Abdurrahman)", "result": "zafer", "note": "Semerkant dağ geçidinde Emevi ordusuna ağır zayiat verdirildi."}], "legends": ["Arap tarihçisi Taberî, Sulu Kağan'ın hücum ettiği zaman durdurulamaz bir boğa gibi tosladığını kaydeder."], "sources": [{"title": "TDV İslâm Ansiklopedisi, TÜRGEŞLER", "url": "https://islamansiklopedisi.org.tr/turgesler"}]}]}, {"id": "uygur-kaganligi", "name": "Uygur Kağanlığı", "short": "Ötüken'de 744'te kurulan, Maniheizm'i resmî din yapan bozkır kağanlığı", "aliases": ["Ötüken Uygur Kağanlığı", "Büyük Uygur Kağanlığı", "Dokuz Oğuz Kağanlığı", "Toquz Oğuz"], "region": "bozkir", "start": 744, "end": 840, "startNote": "TDV Türk maddesi kuruluşu 744, Uygurlar maddesi Basmıl kağanının yenilip Kutluğ Bilge Köl unvanının alınmasını 745 diye verir. İngilizce Vikipedi ve Britannica 744'ü kullanır; başlangıç 744 alındı.", "endNote": "Kırgız saldırısı ve Ordu-Balık'ın yıkılması TDV ile Britannica'da 840. Türkçe Vikipedi 847'ye kadar sürdürür; Üge ve Enian kağanlar Tang sınırına kaçtığı için bu kayıt 840'ta kesiliyor, kaçkın kağanlar hükümdar listesinde ayrıca gösterildi.", "capital": "Ötüken; Moyunçur'dan sonra Ordu-Balık (Karabalgasun)", "religion": "Önce Gök Tanrı inancı; Bögü Kağan'dan sonra Maniheizm resmî, Budizm ve Nasturî Hıristiyanlık da bulunur", "confidence": "kayit", "confidenceNote": "Devletin varlığı kayıtlıdır. Maniheizm'in kabul yılı ayrılır: TDV Uygurlar maddesi 764, Maniheizm maddesi ve İngilizce Vikipedi genelgesi 762. Bögü'nün ölüm yılı 779 ya da 780 diye verilir. 821-840 arası kağan adları Türkçe ve Çince kaynaklarda ayrı biçimlerde geçer.", "summary": "Göktürk hâkimiyetine karşı Karluk ve Basmıl ittifakının içinde 744'te Ötüken'de kurulan Uygur Kağanlığı, Moyunçur döneminde Seyhun'a kadar uzandı. Bögü Kağan Maniheizm'i resmî din yaptı; bu seçim devletin savaşçı yapısını ve Soğd etkisini büyüttü. 821'den sonra saray entrikaları ve taht kavgalarıyla sarsıldı, 840'ta Kırgız saldırısı Ordu-Balık'ı yıkınca dağıldı.", "legacy": "Yerleşik şehir kurma, yazı ve tercüme faaliyetiyle bozkırda istisna bir kültür bıraktı. Uygur yazısı Moğol ve Çağatay yazısının temeli sayılır. Dağılan boylar Kansu, Turfan ve Beşbalık'ta yeni devletler kurdu; bugünkü Uygurlar bu kollardan gelir.", "essay": ["Uygurlar Çin kaynaklarında Töles boyları arasında görünür; Göktürk Devleti'nin zayıfladığı VII. yüzyılda Uygur, Bugu, Bayırku ve Tongra gibi boylar İrkin unvanlı bir reisin çevresinde toplandı. 744'te Karluk ve Basmıl ittifakı Göktürk kağanı Ozmış'ı devirdikten sonra Basmıl kağanlığı kısa sürdü; Uygur yabgusu Basmıl kağanını yenip kendini kağan ilân etti ve Kutluğ Bilge Köl unvanını aldı. Böylece Ötüken merkezli Büyük Uygur Kağanlığı doğdu ve Orhon-Selenge havzası Uygur eline geçti.", "Moyunçur (Bayan Çor) döneminde devlet batıda Altay'ın güneybatısındaki Karluklar ve Çu-Talas Türgişleri üzerine seferlerle Siriderya kıyılarına kadar dayandı; Şine-Usu yazıtı bu dönemin anlatısıdır. Moyunçur 758'de Çin'deki T'ang hanedanına isyan bastırmada yardım etti. Oğlu Bögü Kağan An Luşan isyanına karşı seferden sonra Maniheizm'i kabul edip resmî din yaptı; Soğd rahipleri ve tüccarları sarayda ağırlık kazandı. Kağanlığın teşkilatı batı kanadında yabguluk, merkezde Dokuz Oğuz ve Sekiz Oğuz boyları üzerine kuruluydu.", "Bögü Kağan'ın Tang'a saldırı hazırlığına karşı çıkan amcası Tun Bağa Tarkan onu ve çevresinden yaklaşık iki bin kişiyi öldürüp tahta geçti; Maniheizm bir süre geriletilse de sonraki kağanlar bu dini yeniden destekledi. 795'ten 840'a kadar dokuz kişi kağan oldu; taht art arda el değiştirdi. Kuzeyde Kırgızlarla savaş yeniden başladı, ülkede Çin sarayının entrikaları ve kağanlık ailesinin bölünmesi etkili oldu.", "840'ta Uygur kumandanı Külüg Baga'nın Kırgızlarla anlaşması üzerine yaklaşık yüz bin süvari Ordu-Balık'a yürüdü; Ho-sa Tegin ve Kürebir öldürüldü, kağanlık otağı yakıldı. TDV, savaşçı ruhu gevşeten Maniheizm'i yıkılışın başlıca sebebi sayar. Kurtulan boylar Karluklar'a, Kansu'ya, Turfan ve Beşbalık yöresine dağıldı; Orta Asya'da boşalan otlaklara zamanla Moğol boyları yerleşti."], "sources": [{"title": "TDV İslâm Ansiklopedisi, UYGURLAR", "url": "https://islamansiklopedisi.org.tr/uygurlar"}, {"title": "TDV İslâm Ansiklopedisi, TÜRK", "url": "https://islamansiklopedisi.org.tr/turk"}, {"title": "TDV İslâm Ansiklopedisi, MANİHEİZM", "url": "https://islamansiklopedisi.org.tr/maniheizm"}, {"title": "Britannica, Uyghur", "url": "https://www.britannica.com/topic/Uighur"}, {"title": "Wikipedia, Uyghur Khaganate", "url": "https://en.wikipedia.org/wiki/Uyghur_Khaganate"}], "rulers": [{"id": "uygur-kutluk-bilge-kul", "name": "Kutluğ Bilge Köl Kağan", "aliases": ["Kutluk Bilge Kül", "Yaoluoge Yibiaobi", "Huairen Kağan"], "title": "kağan", "birth": null, "birthNote": "kayıtlarda yok", "death": 747, "deathNote": "TDV ölüm yılını vermez; İngilizce Vikipedi saltanatı 744-747 ile sınırlar.", "reign": [744, 747], "reignNote": "TDV Uygurlar maddesi kuruluşu 745'e kor; Çin kaynakları Huairen Kağan unvanını verir.", "summary": "Yaglakar boyundan Uygur yabgusu. Basmıl kağanını yenerek Ötüken'de Uygur Kağanlığı'nı kurdu ve Gök-türk tarzı teşkilatı devraldı. Ölümünde yerine oğlu Moyunçur geçti.", "traits": ["Basmıl ittifakını bozma", "Göktürk mirasını sahiplenme"], "contribution": "Dokuz Oğuz boylarını tek kağanlık altında toplayarak Uygur Devleti'ni kurdu.", "harm": "", "wives": [], "children": [{"name": "Moyunçur (Bayan Çor)", "mother": "", "note": "Yerine geçen oğul. İngilizce Vikipedi Bayanchur'u onun oğlu diye yazar.", "certainty": "kesin"}], "wars": [{"name": "Basmıl seferi", "when": "744-745", "foe": "Basmıllar", "result": "zafer", "note": "TDV Basmıl kağanının yenilgisini kuruluşun başlangıcı sayar."}, {"name": "Göktürk kalıntılarına karşı sefer", "when": "744", "foe": "İkinci Göktürk Kağanlığı", "result": "zafer", "note": "Ozmış'ın devrilmesiyle başlayan sürecin sonu."}], "legends": [], "sources": [{"title": "TDV İslâm Ansiklopedisi, UYGURLAR", "url": "https://islamansiklopedisi.org.tr/uygurlar"}, {"title": "Wikipedia, Uyghur Khaganate", "url": "https://en.wikipedia.org/wiki/Uyghur_Khaganate"}]}, {"id": "uygur-moyuncur", "name": "Moyunçur Kağan", "aliases": ["Bayan Çor", "Bayanchur Qaghan", "El Etmiş Bilge Kağan", "Yaoluoge Moyanchuo"], "title": "kağan", "birth": null, "birthNote": "kayıtlarda yok", "death": 759, "deathNote": "TDV ve İngilizce Vikipedi 759'u verir. Şine-Usu yazıtı oğlu Bögü tarafından bu yıl diktirilmiştir.", "reign": [747, 759], "reignNote": "TDV Moyen-çor adını kullanır; yazıtı 759'a koyar.", "summary": "Kağanlığın en geniş sınırlarına ulaştığı dönemin hükümdarı. Karluklar ve Türgişler üzerine seferlerle batıda Siriderya'ya kadar dayandı; Sekiz Oğuz ve Dokuz Tatarları itaat altına aldı. 758'de Çin'deki T'ang hanedanına isyan bastırmada yardım etti.", "traits": ["sefer ve şehir kurma", "Çin ile ittifak", "yazıt bırakma"], "contribution": "Karargâhını Ordu-Balık (Karabalgasun) yapıp Bay Balık'ı kurdurdu; Uygur gücünü Seyhun'a taşıdı.", "harm": "Batı seferleri bağlı boylara ağır yük getirdi.", "wives": [], "children": [{"name": "Bögü Kağan", "mother": "", "note": "Yerine geçen oğul; Şine-Usu yazıtını onun için diktirdi.", "certainty": "kesin"}], "wars": [{"name": "Türgiş ve Karluk seferleri", "when": "747-755", "foe": "Türgişler, Karluklar", "result": "zafer", "note": "TDV Şine-Usu yazıtına dayanarak sınırların Siriderya'ya uzandığını yazar."}, {"name": "An Luşan isyanına yardım", "when": "756-758", "foe": "An Luşan kuvvetleri", "result": "zafer", "note": "TDV Çin'deki T'ang hanedanına 758'de yardım edildiğini kaydeder."}], "legends": [], "sources": [{"title": "TDV İslâm Ansiklopedisi, UYGURLAR", "url": "https://islamansiklopedisi.org.tr/uygurlar"}, {"title": "Wikipedia, Uyghur Khaganate", "url": "https://en.wikipedia.org/wiki/Uyghur_Khaganate"}]}, {"id": "uygur-bogu-kagan", "name": "Bögü Kağan", "aliases": ["Tarkan Bögü", "Yaoluoge Yidijian", "Tengrida Kut Bulmış El Tutmış Alp Külüg Bilge Kağan"], "title": "kağan", "birth": null, "birthNote": "kayıtlarda yok", "death": 779, "deathNote": "TDV ve İngilizce Vikipedi 779; Vikipedi'deki Tun Baga Tarkhan maddesi 779/780 der.", "reign": [759, 779], "reignNote": "Bazı kaynaklar bitişi 780'e kor. Maniheizm'i kabul yılı TDV Uygurlar maddesinde 764, İngilizce Vikipedi'de 762.", "summary": "Moyunçur'un oğlu. 762'de An Luşan isyanına karşı sefere katıldı ve dönüşünde Soğd rahiplerinin etkisiyle Maniheizm'i resmî din yaptı; bu tarihten sonra Uygur sarayında Soğdlu ve Maniheist zümre ağırlık kazandı. 779'da Tang'a saldırı hazırlığına karşı çıkan amcası Tun Bağa Tarkan tarafından öldürüldü.", "traits": ["din değiştirme", "Soğd etkisine açıklık", "Çin seferlerine katılma"], "contribution": "Maniheizm'i devlet dini yaparak Uygur kültürünü yazılı ve yerleşik bir çizgiye çevirdi.", "harm": "Maniheist kurallar ve Soğd nüfuzu ordu ve yönetim içinde tepki yarattı; TDV yıkılışın başlıca sebebi olarak bu dönüşümü gösterir.", "wives": [], "children": [], "wars": [{"name": "An Luşan isyanına karşı Çin seferi", "when": "762", "foe": "An Luşan ve ardılları", "result": "zafer", "note": "Sefer dönüşünde Maniheizm kabul edildi. Vikipedi seferde yağmanın Çin kaynaklarında ağır eleştirildiğini yazar."}, {"name": "Tang'a saldırı hazırlığı", "when": "779", "foe": "Tang hanedanı", "result": "sonucsuz", "note": "Hazırlık saray darbesiyle kesildi; sefer yapılmadı."}], "legends": [], "sources": [{"title": "TDV İslâm Ansiklopedisi, UYGURLAR", "url": "https://islamansiklopedisi.org.tr/uygurlar"}, {"title": "TDV İslâm Ansiklopedisi, MANİHEİZM", "url": "https://islamansiklopedisi.org.tr/maniheizm"}, {"title": "Wikipedia, Uyghur Khaganate", "url": "https://en.wikipedia.org/wiki/Uyghur_Khaganate"}]}, {"id": "uygur-tun-baga-tarkan", "name": "Tun Bağa Tarkan", "aliases": ["Alp Kutluğ Bilge Kağan", "Yaoluoge Dunmohe", "Wuyi Chenggong Kağan", "Changshou Tianqin Kağan"], "title": "kağan", "birth": null, "birthNote": "Vikipedi yaklaşık 737-742 tahmini verir; kaynak gösterilmez.", "death": 789, "deathNote": "İngilizce Vikipedi Aralık 789 der.", "reign": [779, 789], "reignNote": "Bazı kaynaklar başlangıcı 780'e kor. Bögü'nün amcası ya da kuzeni olduğu tartışılır.", "summary": "Bögü Kağan'ı deviren saray ileri geleni. Tahta geçince Maniheist ve Soğdlu zümreyi korumadan çıkardı, yeni kanunlar koyarak birliği sağlamaya çalıştı. Tang hanedanından prenses isteyip 788'de evlendi; ertesi yıl öldü.", "traits": ["Maniheizm karşıtlığı", "kanun düzenlemesi", "Tang ile akrabalık"], "contribution": "Soğd nüfuzunu kısa süre geriletti ve kağanlık düzenini yeniden kurdu.", "harm": "Bögü ve çevresinden yaklaşık iki bin kişiyi öldürttü; kağanlık ailesi zayıfladı.", "wives": [{"name": "Xian'an Prensesi", "note": "Tang imparatoru De Zong'un kızı; nikâh 788. İngilizce Vikipedi.", "certainty": "kesin"}], "children": [{"name": "Külüg Bilge Kağan (Tolosi)", "mother": "", "note": "Yerine geçen oğul; suikastla öldürüldü.", "certainty": "olasi"}], "wars": [{"name": "Saray darbesi", "when": "779-780", "foe": "Bögü Kağan", "result": "zafer", "note": "İç savaş; Tang ile savaş değildir."}], "legends": [], "sources": [{"title": "TDV İslâm Ansiklopedisi, UYGURLAR", "url": "https://islamansiklopedisi.org.tr/uygurlar"}, {"title": "Wikipedia, Tun Baga Tarkhan", "url": "https://en.wikipedia.org/wiki/Tun_Baga_Tarkhan"}]}, {"id": "uygur-kulug-bilge", "name": "Külüg Bilge Kağan", "aliases": ["Tolosi", "Yaoluoge Duoluosi", "Zhongzhen Kağan"], "title": "kağan", "birth": null, "birthNote": "kayıtlarda yok", "death": 790, "deathNote": "İngilizce Vikipedi 790; tahta çıktıktan kısa süre sonra öldürüldüğünü yazar.", "reign": [789, 790], "reignNote": "Bir yıllık saltanat.", "summary": "Tun Bağa Tarkan'ın oğlu. Babasının ölümünden hemen sonra kağan oldu ve kısa süre içinde öldürüldü.", "traits": [], "contribution": "", "harm": "", "wives": [], "children": [], "wars": [], "legends": [], "sources": [{"title": "Wikipedia, Uyghur Khaganate", "url": "https://en.wikipedia.org/wiki/Uyghur_Khaganate"}, {"title": "Wikipedia, Tun Baga Tarkhan", "url": "https://en.wikipedia.org/wiki/Tun_Baga_Tarkhan"}]}, {"id": "uygur-kutluk-bilge-ii", "name": "Kutluk Bilge Kağan", "aliases": ["Yaoluoge Açuo", "Açuo", "Fengcheng Kağan"], "title": "kağan", "birth": null, "birthNote": "kayıtlarda yok", "death": 795, "deathNote": "İngilizce Vikipedi saltanatın 795'te bittiğini yazar, ölüm biçimini vermez.", "reign": [790, 795], "reignNote": "Tun Bağa Tarkan'ın soyundan; aynı adı taşıyan kağanlarla karıştırılmaması için bu kayıtta ikinci diye anıldı.", "summary": "Külüg Bilge'nin kardeşi. Taht kavgalarının sürdüğü bir dönemde beş yıl kağanlık yaptı; Tibet'in Tarım havzasına yönelmesiyle Uygur sınırı batıda baskı gördü.", "traits": [], "contribution": "", "harm": "", "wives": [], "children": [], "wars": [{"name": "Tibet-Uygur mücadelesi", "when": "790", "foe": "Tibet İmparatorluğu", "result": "yenilgi", "note": "Tibetliler Beşbalık (Beiting) yönünde Uygur kuvvetlerini bozdu. İngilizce Vikipedi ve Indiana Üniversitesi derlemesi."}], "legends": [], "sources": [{"title": "TDV İslâm Ansiklopedisi, UYGURLAR", "url": "https://islamansiklopedisi.org.tr/uygurlar"}, {"title": "Wikipedia, Uyghur Khaganate", "url": "https://en.wikipedia.org/wiki/Uyghur_Khaganate"}]}, {"id": "uygur-kutluk-iii", "name": "Kutluk Bilge Kağan", "aliases": ["Yaoluoge Guduolu", "Adie Guduolu", "Ay Tengride Ulug Bolmış Alp Kutluk Külüg Bilge Kağan", "Huaixin Kağan"], "title": "kağan", "birth": null, "birthNote": "kayıtlarda yok", "death": 808, "deathNote": "İngilizce Vikipedi saltanat sonunu 808 verir.", "reign": [795, 808], "reignNote": "Uygur kağanlığının en uzun saltanatlarından biri. Adı hem Türkçe unvanda hem Çin kaynaklarında ayrı biçimde geçer.", "summary": "Yaglakar soyundan gelmediği hâlde tahta çıktığı ileri sürülen kağan. Döneminde Maniheizm yeniden devlet desteği gördü; batıda Karluk ve Tibet baskısına karşı sınır korundu.", "traits": ["uzun saltanat", "Maniheist zümreyle barışma"], "contribution": "Taht kavgalarından sonra kağanlığa görece istikrar getirdi.", "harm": "", "wives": [], "children": [], "wars": [], "legends": ["Yaglakar soyundan olmadığı ve tahtı gasbettiği iddiası İngilizce Vikipedi'de yer alır; TDV bu ayrıntıya girmez."], "sources": [{"title": "TDV İslâm Ansiklopedisi, UYGURLAR", "url": "https://islamansiklopedisi.org.tr/uygurlar"}, {"title": "Wikipedia, Uyghur Khaganate", "url": "https://en.wikipedia.org/wiki/Uyghur_Khaganate"}]}, {"id": "uygur-baoyi", "name": "Baoyi Kağan", "aliases": ["Ay Tengride Kut Bulmış Alp Bilge Kağan", "保義可汗"], "title": "kağan", "birth": null, "birthNote": "kayıtlarda yok", "death": 821, "deathNote": "İngilizce Vikipedi ve TDV 821'i verir.", "reign": [808, 821], "reignNote": "Türkçe kaynaklarda Alp Bilge Kağan diye de anılır. Karabalgasun Yazıtı'nın Çince bölümü bu kağan adına dikilmiştir.", "summary": "Karabalgasun (Ordu-Balık) Yazıtı'nın hitap ettiği kağan. Döneminde devlet Çin ile ticaret ve elçilik ilişkilerini sürdürdü, batıda Karluk ve Tibet sınırında denge kuruldu. Arapların elçisi Temim b. Bahr'ın 821'de Ordu-Balık'ı ziyaret ettiği anlatılır.", "traits": ["yazıt bırakma", "ticaret ve elçilik"], "contribution": "Karabalgasun Yazıtı ile Uygur kağanlığının kuruluşundan kendi dönemine kadarki olayları kayda geçirtti.", "harm": "", "wives": [], "children": [{"name": "Üge Kağan", "mother": "", "note": "İngilizce Vikipedi Üge'yi Baoyi'nin oğlu diye yazar.", "certainty": "olasi"}], "wars": [], "legends": [], "sources": [{"title": "TDV İslâm Ansiklopedisi, UYGURLAR", "url": "https://islamansiklopedisi.org.tr/uygurlar"}, {"title": "Wikipedia, Uyghur Khaganate", "url": "https://en.wikipedia.org/wiki/Uyghur_Khaganate"}]}, {"id": "uygur-chongde", "name": "Çongde Kağan", "aliases": ["Kün Tengride Ülüg Bulmış Küçlüg Bilge Kağan", "崇德可汗", "Chongde Qaghan"], "title": "kağan", "birth": null, "birthNote": "kayıtlarda yok", "death": 824, "deathNote": "TDV 824'te öldüğünü yazar.", "reign": [821, 824], "reignNote": "TDV tahta çıkışı 821'e kor ve bu yılı Uygur tarihinin dönüm noktası sayar.", "summary": "TDV'ye göre 821'de Kün Tengride Ülüg Bulmış Alp Küçlüg Bilge unvanıyla kağan oldu. Çinli prensesle evliliği ve saraydaki entrikalar bu dönemin iç huzurunu bozdu. 824'te ölünce yerine kardeşi geçti.", "traits": [], "contribution": "", "harm": "TDV 821'i entrikalar ve suikastlar yılı olarak anar; kağanlık ailesinin gücü bu tarihten sonra zayıfladı.", "wives": [{"name": "Tang prensesi (adı kaynaklarda açık değil)", "note": "TDV kağanın Çinli prensesle evlendiğini ve onun faaliyetleri yüzünden iç huzurun sağlanamadığını yazar, prensesin adını vermez.", "certainty": "olasi"}], "children": [], "wars": [], "legends": [], "sources": [{"title": "TDV İslâm Ansiklopedisi, UYGURLAR", "url": "https://islamansiklopedisi.org.tr/uygurlar"}, {"title": "Wikipedia, Uyghur Khaganate", "url": "https://en.wikipedia.org/wiki/Uyghur_Khaganate"}]}, {"id": "uygur-zhaoli", "name": "Zhaoli Kağan", "aliases": ["Ho-sa Tegin", "Hazar Tegin", "Ay Tengride Kut Bulmış Alp Bilge Kağan", "昭禮可汗"], "title": "kağan", "birth": null, "birthNote": "kayıtlarda yok", "death": 839, "deathNote": "TDV 839'daki ayaklanmada öldürüldüğünü yazar.", "reign": [824, 833], "reignNote": "TDV bu kağanı Ho-sa (Hazar) Tegin olarak 824-832 arasında gösterir; İngilizce Vikipedi 824-833 verir. Yıl farkı reignNote'ta tutuldu.", "summary": "Çongde'nin kardeşi. TDV onu Ho-sa Tegin diye anar. Sekiz yıl kadar kağanlık yaptı; sonunda taht kavgası sırasında öldürüldü.", "traits": [], "contribution": "", "harm": "", "wives": [], "children": [], "wars": [], "legends": [], "sources": [{"title": "TDV İslâm Ansiklopedisi, UYGURLAR", "url": "https://islamansiklopedisi.org.tr/uygurlar"}, {"title": "Wikipedia, Uyghur Khaganate", "url": "https://en.wikipedia.org/wiki/Uyghur_Khaganate"}]}, {"id": "uygur-zhangxin", "name": "Zhangxin Kağan", "aliases": ["Hu Tegin", "Yaoluoge Hu", "Ay Tengride Kut Bulmış Alp Külüg Bilge Kağan", "彰信可汗"], "title": "kağan", "birth": null, "birthNote": "kayıtlarda yok", "death": 839, "deathNote": "TDV 839'da öldürüldüğünü, İngilizce Vikipedi saltanatın 839'da bittiğini yazar.", "reign": [833, 839], "reignNote": "TDV tahta çıkışı 832 diye verir. İngilizce Vikipedi 833-839.", "summary": "TDV'ye göre 839'da tahtı gasbetmeye çalışan devlet adamlarını öldürttü. Seferde olan Kürebir buna öfkelenip ayaklandı ve kağan öldürüldü; ardından Ho-sa Tegin kağan ilân edildi.", "traits": ["sert iç temizlik"], "contribution": "", "harm": "Ayaklanma ve suikast zinciri kağanlığı 840 öncesi iyice zayıflattı.", "wives": [], "children": [], "wars": [{"name": "Kürebir ayaklanması", "when": "839", "foe": "Kürebir ve taraftarları", "result": "yenilgi", "note": "İç isyan; kağan bu ayaklanmada öldürüldü."}], "legends": [], "sources": [{"title": "TDV İslâm Ansiklopedisi, UYGURLAR", "url": "https://islamansiklopedisi.org.tr/uygurlar"}, {"title": "Wikipedia, Uyghur Khaganate", "url": "https://en.wikipedia.org/wiki/Uyghur_Khaganate"}]}, {"id": "uygur-qasar", "name": "Qasar Kağan", "aliases": ["Ho-sa Tegin", "Hesa Kağan", "Jueluowu", "Yaoluoge Hesa"], "title": "kağan", "birth": null, "birthNote": "kayıtlarda yok", "death": 840, "deathNote": "TDV 840'ta Külüg Baga'nın onu öldürdüğünü yazar.", "reign": [839, 840], "reignNote": "Taht iddiası ve gasıp olarak anılır. TDV onu Ho-sa Tegin diye kaydeder; aynı adlı daha önceki kağanla karıştırılmaması için ayrı madde yapıldı.", "summary": "Hu Tegin'in ölümünden sonra kağan ilân edilen Ho-sa Tegin. Bir yıl bile sürmeyen saltanatı, seferden dönen Kürebir'in öfkesi ve Külüg Baga'nın Kırgızlarla anlaşmasıyla son buldu; kağanlık otağı yakıldı.", "traits": [], "contribution": "", "harm": "Kısa saltanatı kağanlığın sonunu hızlandırdı.", "wives": [], "children": [], "wars": [{"name": "Ordu-Balık baskını", "when": "840", "foe": "Kırgızlar ve Külüg Baga kuvvetleri", "result": "yenilgi", "note": "TDV yaklaşık yüz bin süvariden söz eder; rakam kaynak abartısı olabilir."}], "legends": [], "claim": true, "sources": [{"title": "TDV İslâm Ansiklopedisi, UYGURLAR", "url": "https://islamansiklopedisi.org.tr/uygurlar"}, {"title": "Wikipedia, Uyghur Khaganate", "url": "https://en.wikipedia.org/wiki/Uyghur_Khaganate"}]}, {"id": "uygur-uge", "name": "Üge Kağan", "aliases": ["Yaoluoge Wuxi", "Wujie Kağan", "Öge Kağan", "烏介可汗"], "title": "kağan", "birth": null, "birthNote": "kayıtlarda yok", "death": null, "deathNote": "TDV ve İngilizce Vikipedi ölüm yılını vermez; 846-847'de Tang topraklarında son bulduğu anlatılır.", "reign": [841, 847], "reignNote": "İngilizce Vikipedi 841-846, Türkçe Vikipedi 839-845. Indiana Üniversitesi derlemesi son birleşik kağan olarak 841-847 verir.", "summary": "840 sonrası Tang sınırına çekilen Uygur topluluğunun kağanı. Ordubalık'tan ayrılan yüz bin kişilik kitleyi yönetti, Tang'dan yerleşim ve yiyecek istedi; isteği geri çevrildi. Tang, Ormızt'ı ona karşı kullanmak üzere himaye etti.", "traits": ["sürgünde hükümdarlık", "Tang ile pazarlık"], "contribution": "", "harm": "Kağanlığın bakiyesi Tang topraklarında dağıldı.", "wives": [], "children": [], "wars": [{"name": "Tang sınırı çatışmaları", "when": "841-846", "foe": "Tang hanedanı", "result": "yenilgi", "note": "Sınıra akınlar geri çevrildi; iki yıl içinde Tang Budizm ve Hıristiyanlık yasakları getirdi."}], "legends": [], "claim": true, "sources": [{"title": "Wikipedia, Uyghur Khaganate", "url": "https://en.wikipedia.org/wiki/Uyghur_Khaganate"}]}, {"id": "uygur-enian", "name": "Enian Kağan", "aliases": ["Yaoluoge E'nian", "遏捻可汗"], "title": "kağan", "birth": null, "birthNote": "kayıtlarda yok", "death": null, "deathNote": "kayıtlarda yok", "reign": [846, 848], "reignNote": "İngilizce Vikipedi 846-848. TDV bu kağanı anmaz.", "summary": "Üge'den sonra Tang sınırında kağan sayılan son Uygur hükümdarı. Saltanatı iki yıl sürdü ve kalıcı bir devlet kurulamadı.", "traits": [], "contribution": "", "harm": "", "wives": [], "children": [], "wars": [], "legends": [], "claim": true, "sources": [{"title": "Wikipedia, Uyghur Khaganate", "url": "https://en.wikipedia.org/wiki/Uyghur_Khaganate"}]}]}, {"id": "karluk", "name": "Karluk Yabguluğu", "short": "Karluk", "aliases": ["Karluklar", "Üç Karluk"], "region": "bozkir", "start": 766, "end": 940, "startNote": "766'da Türgiş topraklarını (Suyab ve Taraz) tamamen ele geçirerek yabguluk kurdular.", "endNote": "940 yılında Balasagun merkezli Karahanlı Devleti'nin resmi kuruluşuyla bu yapı Karahanlı hanedanına dönüştü.", "capital": "Suyab, ardından Balasagun ve Taraz", "religion": "Gök Tanrı inancı; 9. yüzyıl sonlarından itibaren İslamiyet", "confidence": "kayit", "confidenceNote": "Arap-Fars coğrafyacıları (Hudûdü'l-Âlem, Gerdîzî, İbn Havkal) ve Karahanlı kaynaklarıyla sabittir.", "summary": "Altaylar'dan Çu ve Talas vadilerine inen, 751 Talas Savaşı'nda Abbasi tarafına geçerek tarihin akışını değiştiren ve İslamiyet'i ilk benimseyen Türk topluluklarından olan Karlukların kurduğu yabguluk. Samanilerle mücadele ettiler; 840'ta Uygur Kağanlığı yıkılınca liderleri Bilge Kül Kadir Han kendini Türklerin meşru kağanı ilan ederek Karahanlı Devleti'nin temellerini attı.", "legacy": "Türklerin kitleler halinde İslamiyet'e girişine öncülük etti. İlk Müslüman Türk devleti olan Karahanlıların etnik ve hanedan kurucu omurgasını teşkil etti.", "essay": ["Karluklar, Göktürk devrinde 'Üç Karluk' adıyla Altaylar ile Tarbagatay dağları arasında yaşayan güçlü bir Türk boy federasyonuydu. 744'te Uygurlar ve Basmıllarla birleşerek İkinci Göktürk Kağanlığı'nı yıktılar; fakat Uygurlarla girdikleri mücadeleyi kaybederek batıya, Yedisu bölgesine göç ettiler.", "751 yılında vuku bulan tarihi Talas Savaşı'nda Çin (Tang) ordusunun arkasından vurarak Abbasi ordusunun zafer kazanmasını sağladılar. Bu hamle Çin'in Batı Türkistan'daki yayılmasını ebediyen durdurdu ve Türk-İslam yakınlaşmasının kapısını araladı. 766'da Türgiş başkentleri Suyab ve Taraz'ı alarak bağımsız Karluk Yabguluğu'nu tesis ettiler.", "840 yılında Yenisey Kırgızlarının Uygur Kağanlığı'nı yıkması üzerine, bozkır töresine göre kağanlık unvanının Aşina soyuna en yakın Karluklara geçtiğini savunan Karluk Yabgusu Bilge Kül Kadir Han, kendisini 'Kara Han' ilan etti. Böylece Karluk Yabguluğu kesintisiz biçimde ilk Müslüman Türk imparatorluğu olan Karahanlı Devleti'ne dönüştü."], "sources": [{"title": "TDV İslâm Ansiklopedisi, KARLUKLAR", "url": "https://islamansiklopedisi.org.tr/karluklar"}, {"title": "Britannica, Qarluq", "url": "https://www.britannica.com/topic/Qarluq"}], "rulers": [{"id": "karluk-tun-bilge", "name": "Tun Bilge Yabgu", "aliases": ["Tun Bilge", "Kül Erkin"], "title": "Yabgu", "birth": null, "birthNote": "Kayıtlarda yok", "death": 790, "deathNote": "Yedisu'da vefat etti", "reign": [766, 790], "reignNote": "Yedisu'da bağımsız yabguluğu tesis etti.", "summary": "Türgiş topraklarını tamamen kontrol altına alarak Suyab ve Taraz'da Karluk Yabguluğu'nu kuran dirayetli lider. Şehirleşmeye ve ticarete önem verdi.", "traits": ["Teşkilatçı", "Usta yönetici"], "contribution": "Karlukları bozkır göçebeliğinden şehirli ve zengin bir ticaret havzası yöneticiliğine yükseltti.", "harm": "Tibet ve Uygur baskılarına karşı zaman zaman savunmada kaldı.", "wives": [], "children": [], "wars": [{"name": "Suyab ve Yedisu Fethi", "when": "766", "foe": "Türgiş bakiyeleri", "result": "zafer", "note": "Türgiş siyasi egemenliğine son verildi."}], "legends": [], "sources": [{"title": "TDV İslâm Ansiklopedisi, KARLUKLAR", "url": "https://islamansiklopedisi.org.tr/karluklar"}]}, {"id": "karluk-bilge-kul-kadir", "name": "Bilge Kül Kadir Han", "aliases": ["Bilge Kül Kadir", "Kadir Han"], "title": "Yabgu / Kağan", "birth": null, "birthNote": "Kayıtlarda yok", "death": 893, "deathNote": "Taraz savunmasında veya sonrasında vefat etti", "reign": [840, 893], "reignNote": "840'ta kağanlık unvanı aldı, Karahanlı hanedanının kurucu atası oldu.", "summary": "Karluk yabgusu iken 840'ta Uygurların çöküşü üzerine kağanlık ilan eden büyük ata. Samani saldırılarına karşı Taraz ve İsficab'ı savundu. Oğulları Bazır Arslan Han ve Oğulcak Kadir Han yoluyla torunu Satuk Buğra Han'a uzanan ilk Müslüman Türk hanedanının temelini attı.", "traits": ["Töreye bağlı", "Kararlı", "Hanedan kurucu"], "contribution": "Karlukları Karahanlı imparatorluk kimliğine taşıyarak Türk tarihinin yeni çağını açtı.", "harm": "893'te Taraz kalesinin Samanilerce zaptedilmesini engelleyemedi.", "wives": [], "children": [{"name": "Bazır Arslan Han", "mother": "", "note": "Büyük Kağan (Balasagun)", "certainty": "kesin"}, {"name": "Oğulcak Kadir Han", "mother": "", "note": "Batı Kağanı (Taraz ve Kaşgar)", "certainty": "kesin"}], "wars": [{"name": "Taraz Kuşatması", "when": "893", "foe": "Samaniler (İsmail b. Ahmed)", "result": "yenilgi", "note": "Taraz şehri düştü, eşi ve binlerce Karluk esir oldu, başkent Kaşgar'a taşındı."}], "legends": ["Uygur kağanlığının çöküşüyle Ötüken kutunun Karluklara geçtiğini ilan ettiği töre meclisi."], "sources": [{"title": "TDV İslâm Ansiklopedisi, BİLGE KÜL KADİR HAN", "url": "https://islamansiklopedisi.org.tr/bilge-kul-kadir-han"}, {"title": "TDV İslâm Ansiklopedisi, KARAHANLILAR", "url": "https://islamansiklopedisi.org.tr/karahanlilar"}]}]}, {"id": "yenisey-kirgiz", "name": "Yenisey Kırgız Kağanlığı", "short": "Yenisey kıyılarında kurulan, 840'ta Uygur Kağanlığı'nı yıkan devlet", "aliases": ["Kırgız Kağanlığı", "Eski Kırgızlar", "Qırqız El", "Kırgız Hanlığı"], "region": "bozkir", "start": 840, "end": 1207, "startNote": "Bars Bek 693'te kağan unvanını aldıysa da kuruluş yılı olarak genellikle Uygur Kağanlığı'nın yıkıldığı 840 alınır. Türkçe Vikipedi ve İngilizce Vikipedi 840'ı devlet başlangıcı sayar; Moğolistan'daki hâkimiyetin bitişi 920'de K'i-tanların Ötüken'e girmesiyle gelir.", "endNote": "Envanterde 1207 verildi: Cengiz Han'ın Merkit ve Nayman savaşları sırasında Kırgızları itaat altına alması TDV'ye göre 1207'dir. Kağanlığın imparatorluk dönemi İngilizce Vikipedi'de 925'te kapanır; 925-1207 arası beylikler hâlinde sürer.", "capital": "Uybat ırmağı çevresindeki yerleşim; 840'tan sonra kısa süre Ordu-Balık, sonra Tuva'da bir merkez", "religion": "Gök Tanrı inancı resmî; Uygurların ardından Maniheizm, ayrıca Budizm ve Nasturî Hıristiyanlık izleri", "confidence": "tartismali", "confidenceNote": "Devletin varlığı kayıtlıdır. İmparatorluk döneminin sınırı ve Ötüken'de kalıcı hâkimiyet tartışmalıdır: bir grup tarihçi 840 sonrası Moğolistan'ı ellerinde tuttuklarını, bir kısmı yalnız kısa süreli bir üstünlük kurduklarını söyler. Hükümdar adları Çince kaynaklarda biçim biçim gelir ve Türkçe kaynaklarda çoğu kez geçmez. Taştık kültürüyle bağları olasılık olarak anılır. Kırgızların Tagar/Az (açalar) boylarıyla anılan ortaklığı kaynaklarda \"Az ve Kırgız\" biçiminde geçer, ayrı bir halk olup olmadıkları kesin değildir.", "summary": "Yenisey'in yukarı havzasında Minusinsk ve Tannu-Ola çevresinde yaşayan Kırgızlar, Göktürk ve Uygur hâkimiyeti altında uzun süre kaldı. 840'ta Uygur başkenti Ordu-Balık'ı yıkıp Uygur Kağanlığı'na son verdiler ve kısa süre bozkırın en itibarlı gücü oldular. 920'de K'i-tanlar Moğolistan'ı alınca eski yurtlarına çekildiler; 1207'de Cengiz Han'a itaat eden ilk Türk topluluğu oldular.", "legacy": "Yenisey Yazıtları olarak bilinen runik Türkçe metinler bu toplumdan kalmadır. At yetiştiriciliği, demir işçiliği ve kürk ticaretiyle tanındılar. Bugünkü Hakaslar, Tuvalar ve Kırgızların ataları arasında sayılırlar.", "essay": ["Kırgız adı ilk kez Çin kaynaklarında Sima Qian'ın MÖ 203-201 olaylarını anlatan notlarında Gekun biçiminde geçer; Hun hükümdarı Mete'nin boyunduruğuna giren beş halk arasında sayılırlar. Ana yurtları Yenisey'in yukarı akışı, Minusinsk çukuru ve Tannu-Ola dağlarıydı. Taştık kültürüyle ilişkilendirilirler. VI. yüzyılda Göktürk hakanı Mukan zamanında hakanlığa bağlandılar; Göktürk fetretinde (630-680) bağımsız bir kimlik kazandılar ve 693'te Bars Bek'in kağan ilan edilmesiyle kendi kağanlıklarını kurdular.", "Bars Bek 710-711 kışında Kapgan Kağan'ın seferinde öldü ve Kırgızlar bir süre İkinci Göktürk Kağanlığı'na, ardından Uygurlara bağlandı. TDV, Uygur kağanı Moyunçur'un Kırgızları 758'de Uygur Hakanlığı'na bağladığını yazar. Bu tâbiiyet 840'a kadar sürdü; o yıl Uygur kumandanı Külüg Baga'nın Kırgızlarla anlaşması üzerine Kırgız ordusu Ordu-Balık'a yürüdü, başkenti yaktı ve Uygur kağanlığını sona erdirdi.", "Kırgızlar Ötüken'de kalıcı bir düzen kuramadı. 920'de bütün Moğolistan'ı ele geçiren K'i-tanlar onları Ötüken'den çıkarıp eski yurtlarına sürdü. Ekonomileri göçebe hayvancılıkla tarımı birleştirir; Çin kayıtlarına göre Himalaya çavdarı, arpa, darı ve buğday eker, demir işçiliği ve kürk ticareti yaparlardı. Hudûdü'l-âlem ölülerini gömmeyip yaktıklarını kaydeder.", "1207'de Cengiz Han'ın Merkit ve Naymanlarla savaşları sırasında Kırgızlar itaat altına alındı; TDV onları Cengiz Han'a itaat eden ilk Türk kavmi sayar. 1217'deki direnme girişimi ertesi yıl Cuci tarafından bastırıldı. Yenisey bölgesindeki Kırgız varlığı bundan sonra Kalmuk ve Kazak hâkimiyetleri altında devam etti."], "sources": [{"title": "TDV İslâm Ansiklopedisi, KIRGIZLAR", "url": "https://islamansiklopedisi.org.tr/kirgizlar"}, {"title": "TDV İslâm Ansiklopedisi, UYGURLAR", "url": "https://islamansiklopedisi.org.tr/uygurlar"}, {"title": "Wikipedia, Kyrgyz Khaganate", "url": "https://en.wikipedia.org/wiki/Kyrgyz_Khaganate"}, {"title": "Wikipedia, Bars Bek", "url": "https://en.wikipedia.org/wiki/Bars_Bek"}, {"title": "Wikipedia, Yenisei Kyrgyz", "url": "https://en.wikipedia.org/wiki/Yenisei_Kyrgyz"}], "rulers": [{"id": "kirgiz-bars-bek", "name": "Bars Bek", "aliases": ["İnanç Alp Bilge", "Ynançu Alp Bilge", "Inanch Alp Bilge"], "title": "kağan", "birth": 637, "birthNote": "İngilizce Vikipedi 637 verir; kaynak zayıftır. TDV doğum yılı vermez.", "death": 711, "deathNote": "İngilizce Vikipedi 711; Kırgız akademik yazınında 711 kışı diye geçer.", "reign": [693, 711], "reignNote": "İlteriş Kağan'ın ölümünden sonra (693) kağan ilan edildiği söylenir. Göktürk hakanı Kapgan'ın onu kağan olarak tanıdığı ve kız kardeşini verdiği kaydedilir.", "summary": "Kırgız Kağanlığı'nın ilk kağanı sayılan hükümdar. İkinci Göktürk Kağanlığı'nın kuzeye genişlemesine karşı direndi; 710-711 kışında Kapgan Kağan'ın seferinde öldü. Aşina soyuyla evlilik bağı küçük kağan statüsünde olduğunu gösterir.", "traits": ["Göktürk yayılmasına direniş", "hanedan evliliği"], "contribution": "Kırgız boylarını tek kağan çevresinde birleştirdi; kağanlık geleneğini başlattı.", "harm": "", "wives": [{"name": "Göktürk prensesi", "note": "Kapgan Kağan'ın kız kardeşi ya da kızı olduğu söylenir; İngilizce Vikipedi iki ayrı versiyonu birlikte anar.", "certainty": "tartismali"}], "children": [{"name": "kayıtlarda adı geçmiyor", "mother": "", "note": "İngilizce Vikipedi, babasının 710'daki yenilgisinden sonra oğlunun Kırgızları yönettiğini yazar; adını vermez.", "certainty": "olasi"}], "wars": [{"name": "Sayan dağları savaşı", "when": "710-711", "foe": "İkinci Göktürk Kağanlığı, Kapgan Kağan", "result": "yenilgi", "note": "Bars Bek bu savaşta öldü. Tonyukuk yazıtı Kırgız kağanının öldürüldüğünü kaydeder."}], "legends": ["Kırgız hanedanının Han generali Li Ling'in soyundan geldiği iddiası Tang kaynaklarına dayanır; bir soylama iddiasıdır, kanıtlanmış soy değildir. Bars Bek'in İnanç Alp Bilge unvanını taşıdığı tezine Saadeddin Gömeç karşı çıkmıştır."], "sources": [{"title": "Wikipedia, Bars Bek", "url": "https://en.wikipedia.org/wiki/Bars_Bek"}, {"title": "Wikipedia, Kyrgyz Khaganate", "url": "https://en.wikipedia.org/wiki/Kyrgyz_Khaganate"}, {"title": "TDV İslâm Ansiklopedisi, KIRGIZLAR", "url": "https://islamansiklopedisi.org.tr/kirgizlar"}]}, {"id": "kirgiz-bilge-tong-erkin", "name": "Bilge Tong Erkin", "aliases": ["Bilge Tong Erkin Kağan"], "title": "erkin", "birth": null, "birthNote": "kayıtlarda yok", "death": 795, "deathNote": "İngilizce Vikipedi saltanat sonunu 795 verir, ölüm biçimini yazmaz.", "reign": [758, 795], "reignNote": "Uygur tâbiiyeti dönemi. Bu dönemde Kırgız yöneticilerinin kağan mı, Uygurlara bağlı bey mi sayıldığı tartışmalıdır; unvanı erkin olarak kaydedilmiştir.", "summary": "Uygur hâkimiyeti altındaki Kırgızların başı. TDV, Uygur kağanı Moyunçur'un Kırgızları 758'de Uygur Hakanlığı'na bağladığını yazar; bu bağlılık döneminde Kırgız yönetimi Uygur atadığı kişilerin elindeydi.", "traits": [], "contribution": "", "harm": "", "wives": [], "children": [], "wars": [], "legends": [], "sources": [{"title": "TDV İslâm Ansiklopedisi, KIRGIZLAR", "url": "https://islamansiklopedisi.org.tr/kirgizlar"}, {"title": "Wikipedia, Kyrgyz Khaganate", "url": "https://en.wikipedia.org/wiki/Kyrgyz_Khaganate"}]}, {"id": "kirgiz-acu", "name": "Açu Kağan", "aliases": ["Aču Khagan", "Açu"], "title": "kağan", "birth": null, "birthNote": "kayıtlarda yok", "death": 847, "deathNote": "İngilizce Vikipedi saltanat sonunu 847 verir.", "reign": [795, 847], "reignNote": "840'a kadar Uygur tâbiiyetinde bir yerel yönetici, 840'tan sonra kağan. Uzun süreliğin tek kişinin saltanatı olup olmadığı belirsizdir.", "summary": "Uygur Kağanlığı'nın yıkıldığı yıl Kırgızların başında bulunan hükümdar. İngilizce Vikipedi onu 840 sonrası kağan olarak kaydeder; birlikte anılan Külüg Baga Uygur kumandanıdır ve Kırgızlarla anlaşarak Ordu-Balık'ın yıkılmasını sağlamıştır.", "traits": [], "contribution": "Kırgızları Ötüken'de kısa süreliğine de olsa bozkırın en itibarlı gücü yaptı.", "harm": "", "wives": [], "children": [], "wars": [{"name": "Ordu-Balık seferi", "when": "840", "foe": "Uygur Kağanlığı", "result": "zafer", "note": "Başkent yakıldı, Uygur kağanı öldürüldü. İngilizce Vikipedi yaklaşık 80.000 süvariden söz eder; TDV 100.000 der, iki rakam da kaynak abartısı olabilir."}], "legends": [], "sources": [{"title": "Wikipedia, Kyrgyz Khaganate", "url": "https://en.wikipedia.org/wiki/Kyrgyz_Khaganate"}, {"title": "TDV İslâm Ansiklopedisi, KIRGIZLAR", "url": "https://islamansiklopedisi.org.tr/kirgizlar"}]}, {"id": "kirgiz-ingu", "name": "İnğu Kağan", "aliases": ["Ïnǧu Khagan", "İncu Kağan"], "title": "kağan", "birth": null, "birthNote": "kayıtlarda yok", "death": 866, "deathNote": "İngilizce Vikipedi saltanat sonunu 866 verir.", "reign": [847, 866], "reignNote": "TDV bu kağanın adını anmaz; bilgi yalnızca İngilizce Vikipedi'nin hükümdar listesine dayanır.", "summary": "Açu'dan sonra kağan olan hükümdar. Döneminde Kırgızların Moğolistan'daki etkisi zayıflamaya başladı; 920'de K'i-tanların Ötüken'e girmesiyle bu hâkimiyet büsbütün bitti.", "traits": [], "contribution": "", "harm": "", "wives": [], "children": [], "wars": [], "legends": [], "sources": [{"title": "Wikipedia, Kyrgyz Khaganate", "url": "https://en.wikipedia.org/wiki/Kyrgyz_Khaganate"}]}, {"id": "kirgiz-adi-yok", "name": "kayıtlarda adı geçmiyor", "aliases": [], "title": "kağan", "birth": null, "birthNote": "kayıtlarda adı geçmiyor", "death": null, "deathNote": "kayıtlarda adı geçmiyor", "reign": [866, 1207], "reignNote": "866'dan sonraki kağan adları bu turda açılan kaynaklarda yok. İngilizce Vikipedi 925-1207 arası dönem için de 'bilinmeyen hanlar' kaydını kullanır. Bu madde tek bir kişi değil, adı geçmeyen makamı temsil eder.", "summary": "866'dan sonra Kırgız kağanlarının adları kaynaklarda düzenli olarak geçmez. 920'de K'i-tanlar Ötüken bölgesinden onları çıkarıp eski yurtlarına sürdü. XIII. yüzyılda Kırgızların Tanrı dağlarına göç ettiği tezi tarihçiler arasında tartışmalıdır; Radlov ve Barthold göçü geç bir döneme, Savinov XIII. yüzyıla koyar.", "traits": [], "contribution": "", "harm": "920 K'i-tan sürgünü ve sonraki Kalmuk ile Kazak hâkimiyetleri döneminde Kırgızlar bağımsız bir devlet kuramadı.", "wives": [], "children": [], "wars": [{"name": "K'i-tan saldırısı", "when": "920", "foe": "K'i-tanlar (Liao)", "result": "yenilgi", "note": "TDV bütün Moğolistan'ın K'i-tanlara geçtiğini ve Kırgızların eski yurtlarına sürüldüğünü yazar."}, {"name": "Moğol itaati", "when": "1207", "foe": "Cengiz Han", "result": "yenilgi", "note": "TDV Kırgızların Cengiz Han'a itaat eden ilk Türk kavmi olduğunu yazar; 1217 direnmesi 1218'de Cuci tarafından bastırıldı."}], "legends": ["Gerdîzî'nin aktardığı bir rivayette Kimeklerin Tatar kökenli olduğu anlatılır; Kırgızlara dair benzer bir soy rivayeti açılan kaynaklarda yoktur. Kırgız sözcüğünün kırk sayısıyla bağlantısı ise bir halk etimolojisi olarak tekrarlanır; gerçek anlamı bilinmemektedir."], "sources": [{"title": "TDV İslâm Ansiklopedisi, KIRGIZLAR", "url": "https://islamansiklopedisi.org.tr/kirgizlar"}, {"title": "Wikipedia, Kyrgyz Khaganate", "url": "https://en.wikipedia.org/wiki/Kyrgyz_Khaganate"}]}]}, {"id": "kimek", "name": "Kimek-Kıpçak Konfederasyonu", "short": "İrtiş ve Ob arasında yedi boydan kurulan, Kıpçaklara devreden konfederasyon", "aliases": ["Kimek Kağanlığı", "Kimäk", "Yemekler", "İmekler"], "region": "bozkir", "start": 880, "end": 1030, "startNote": "Kuruluş yılı tartışmalıdır: İngilizce Vikipedi konfederasyonu 880-1035 aralığına koyar, TDV için derli toplu bir kuruluş yılı vermez; Kimek adı IX-X. yüzyıllarda İrtiş boylarında yaşayan bir topluluk için kullanılır. Başlangıç envanterdeki 880 alındı.", "endNote": "Envanterde 1030 verildi: Kıpçakların konfederasyon içinde ağır basması XI. yüzyılın ilk yarısına yerleştirilir. İngilizce Vikipedi dağılmayı 1035'e koyar; Deşt-i Kıpçak adının XI. yüzyıl ortasından itibaren yerleşmesi bu sürecin sonucudur.", "capital": "Yazın Imakia (İmekia), kışın Hakan-Kimak adı verilen merkez", "religion": "Gök Tanrı inancı ve şamanlık; İslâm, Nasturî Hıristiyanlık ve Budizm etkileri kaydedilir", "confidence": "tartismali", "confidenceNote": "Kimekler Orhon yazıtlarında ve Çin yıllıklarında geçmez; bilgiler ağırlıklı olarak Gerdîzî ve Hudûdü'l-âlem gibi X. yüzyıl Arap-Fars coğrafyacılarına dayanır. Boy sayısı kaynaktan kaynağa değişir: Gerdîzî yedi boy sayar, Hudûdü'l-âlem hükümdarın on bir beyi olduğunu yazar. Kimek-Yemek özdeşliği tarihçiler arasında tartışılmış, P. Golden bu özdeşlikten vazgeçmiştir. Hükümdar adları kaynaklarda yoktur. Bu devletin bağımsız bir kağanlık mı, boylar arası gevşek bir birlik mi olduğu da açık değildir.", "summary": "İrtiş ve Ob arasındaki bozkırda yedi boydan oluşan konfederasyon, IX. yüzyılın sonunda Kimeklerin adıyla anılmaya başladı. Uygur Kağanlığı'nın 840'ta yıkılmasından sonra bağlantısız kalan Eymür, Bayandur ve Tatar gruplarının bir kısmı bu birliğe katıldı. Hükümdar hakan unvanını taşır, yanında on bir bey bulunurdu. XI. yüzyılda Kıpçak boyu ağır bastı ve birlik Deşt-i Kıpçak adıyla anılan Kıpçak topluluğuna dönüştü.", "legacy": "Kıpçak adı ve Kıpçakça'nın tabanı bu birlikten çıktı. İrtiş boylarındaki kürk ve hayvan ticareti kuzey-güney ticaret yollarına bağlandı. Konfederasyon dağıldıktan sonra Kıpçaklar Altın Orda halkının dil temelini oluşturdu.", "sources": [{"title": "TDV İslâm Ansiklopedisi, KİMEK", "url": "https://islamansiklopedisi.org.tr/kimek"}, {"title": "TDV İslâm Ansiklopedisi, KIPÇAKLAR", "url": "https://islamansiklopedisi.org.tr/kipcaklar"}, {"title": "Wikipedia, Kimek-Kipchak confederation", "url": "https://en.wikipedia.org/wiki/Kimek%E2%80%93Kipchak_confederation"}], "rulers": [{"id": "kimek-hakan-adi-yok", "name": "kayıtlarda adı geçmiyor", "aliases": [], "title": "hakan", "birth": null, "birthNote": "kayıtlarda adı geçmiyor", "death": null, "deathNote": "kayıtlarda adı geçmiyor", "reign": [880, 1030], "reignNote": "Kimek hükümdarının adı hiçbir açılan kaynakta geçmez. Hudûdü'l-âlem yalnız unvanını (hakan) ve on bir beyinin varlığını kaydeder. Bu madde tek bir kişiyi değil, adı geçmeyen hakanlık makamını temsil eder; saltanat sırası ve süreleri bilinmez.", "summary": "Kimeklerin başında hakan unvanlı bir hükümdar bulunur, kararlarda on bir beyin görüşü alınırdı. TDV, Kimeklerin X. yüzyılın ilk yarısında Türk âlemini temsil eden beş büyük kavimden biri sayıldığını ve komşu Türk topluluklarıyla dillerinin karşılıklı anlaşılır olduğunu yazar. Doğuda Oğuzlar, güneyde Türgişler ve Karluklar komşuydu.", "traits": ["boylar arası meclis", "kürk ve hayvan ticareti"], "contribution": "İrtiş havzasındaki boyları tek bir siyasî ad altında topladı.", "harm": "Müslüman tüccarlarla gelişen ilişkiler sonucu köle ticareti büyüdü; kaynaklar Kimek ülkesinden köle satışının iki yüzyıl sürdüğünü anlatır.", "wives": [], "children": [], "wars": [{"name": "Oğuz-Kimek mücadelesi", "when": "IX-X. yüzyıl", "foe": "Oğuz Yabgu Devleti", "result": "belirsiz", "note": "İki topluluk arasında sürekli otlak ve ticaret çekişmesi vardır; TDV tek tek muharebe adı vermez."}, {"name": "Kıpçakların ağır basması", "when": "XI. yüzyıl başı", "foe": "Kıpçak boyu", "result": "belirsiz", "note": "Konfederasyon içindeki Kıpçak boyunun öne çıkması ve birliğin Kıpçak adıyla anılması; bir meydan savaşı kaydedilmez."}], "legends": ["Gerdîzî'nin naklettiği rivayette Kimekler Tatar asıllı gösterilir: Tatar hükümdarının Şed (Şad?) adlı küçük oğlu ağabeyiyle taht mücadelesini kaybedip cariyesiyle İrtiş boylarına kaçar, oraya yerleşir ve hizmetine giren yedi Tatar çocuğundan Kimeklerin yedi boyu çıkar. TDV bu rivayetin kaynaklarca desteklenmediğini açıkça yazar.", "Kimek adının Iki-Imäk ('iki Imek') biçiminden türediği ve birliğin ilk iki boyuna işaret ettiği öne sürülür; bu bir tekliftir, kesin değildir."], "sources": [{"title": "TDV İslâm Ansiklopedisi, KİMEK", "url": "https://islamansiklopedisi.org.tr/kimek"}, {"title": "Wikipedia, Kimek-Kipchak confederation", "url": "https://en.wikipedia.org/wiki/Kimek%E2%80%93Kipchak_confederation"}]}, {"id": "kimek-kipcak-basbug-adi-yok", "name": "kayıtlarda adı geçmiyor", "aliases": [], "title": "başbuğ", "birth": null, "birthNote": "kayıtlarda adı geçmiyor", "death": null, "deathNote": "kayıtlarda adı geçmiyor", "reign": [1000, 1030], "reignNote": "Kıpçak boyunun öne çıktığı dönemin başbuğlarının adı kaynaklarda yoktur. Başlangıç için kayıtlarda bir yıl yok; 1000 yuvarlak yaklaşık değerdir. Bitiş, konfederasyonun Kıpçak adıyla anılmaya başladığı dönemdir.", "summary": "XI. yüzyılın ilk yarısında konfederasyon içinde ağır basan Kıpçak boyunun liderleri adlarıyla kaydedilmemiştir. TDV, Kıpçakların XI. yüzyıl ortasında Uzların ardından Güney Rusya bozkırına girdiğini ve Deşt-i Kıpçak adının bu yeni sahaya verildiğini yazar.", "traits": [], "contribution": "Kimek birliğini Kıpçak topluluğuna dönüştüren süreci yürüttüler.", "harm": "", "wives": [], "children": [], "wars": [{"name": "Batıya göç ve Uzların sürülmesi", "when": "XI. yüzyıl ortası", "foe": "Uzlar (Oğuzlar)", "result": "zafer", "note": "Kıpçakların batıya ilerleyişi; Kıpçak-Kuman birliği maddesinde ayrıntılıdır."}], "legends": [], "sources": [{"title": "TDV İslâm Ansiklopedisi, KIPÇAKLAR", "url": "https://islamansiklopedisi.org.tr/kipcaklar"}, {"title": "TDV İslâm Ansiklopedisi, KİMEK", "url": "https://islamansiklopedisi.org.tr/kimek"}]}]}, {"id": "oguz-yabgu", "name": "Oğuz Yabgu Devleti", "short": "Aşağı Seyhun'da yabgu unvanlı Oğuz birliği", "aliases": ["Oğuz Yabguluğu", "Yenikent Oğuzları"], "region": "turkistan", "start": 775, "end": 1003, "startNote": "Aşağı Seyhun'a geliş TDV'de Halife Mehdî dönemi (775-785) tahminidir. Bağımsız ve güçlü yabguluk X. yüzyılın ilk yarısında kaydedilir. Kuruluş yılı yoktur.", "endNote": "TDV, Sâmânî İsmâil b. Nûh'un 1003'te başvurduğu Oğuzların artık Selçuklu kolu olduğunu ve yabgu devletinin bu tarihten önce bittiğini yazar. Kesin yıkılış yılı yok. Kıpçakların yıktığı ihtimali zayıf diye ayrılır.", "capital": "Yenikent", "religion": "Geleneksel Türk dini; X. yüzyılda İslâmiyet boy boy yayıldı", "confidence": "kayit", "confidenceNote": "X. yüzyılda yabgu, kül erkin ve subaşı düzeni İbn Fadlân ve coğrafyacılarda vardır. Câmiü't-tevârîh'teki yabgu adları başka kaynakta geçmez; yazılmadı. Selçuk'un Yenikent'ten ayrılışı 961, 925-940, 955 veya 985-986 diye verilir.", "summary": "Batı Göktürk geleneğinden gelen Oğuzlar Aşağı Seyhun, Aral ve Mangışlak arasında göçerdi. Kışlığı Yenikent olan yabgunun vekili kül erkin, ordu başı subaşıydı. Peçenekleri Yayık ötesine sürdüler. İç çekişme ve Selçuk'un Cend'e ayrılmasıyla birlik X. yüzyıl sonunda dağıldı.", "legacy": "Selçuklu kolu bu ayrılmadan çıktı. Oğuz adı Türkiye, Azerbaycan ve Türkmenistan Türklerinin atasoyu anlatısında kaldı. Yabgu unvanı Selçuk'un oğullarında bir süre sürdü.", "sources": [{"title": "TDV İslâm Ansiklopedisi, OĞUZLAR", "url": "https://islamansiklopedisi.org.tr/oguzlar"}, {"title": "TDV İslâm Ansiklopedisi, SELÇUK BEY", "url": "https://islamansiklopedisi.org.tr/selcuk-bey"}, {"title": "TDV İslâm Ansiklopedisi, YABGU", "url": "https://islamansiklopedisi.org.tr/yabgu"}], "rulers": [{"id": "oguz-yabgu-adi-yok", "name": "kayıtlarda adı geçmiyor", "title": "yabgu", "birth": null, "birthNote": "kayıtlarda adı geçmiyor", "death": null, "deathNote": "Bir yabgunun Karluk savaşında öldüğü TDV'de vardır; adı ve yılı yok. Olay IX. yüzyıl veya daha önce diye tahmin edilir.", "reign": [null, null], "reignNote": "Destandaki yabgu listesi başka kaynakta doğrulanmaz.", "summary": "X. yüzyıl yabgusunun özel adı bağımsız kaynakta yoktur. Kışın Yenikent'te oturur, işleri meclisle görürdü. Dukak'la kılıçlı kavga anlatısı Selçuklu kaynaklarındadır.", "traits": [], "contribution": "", "harm": "", "wives": [], "children": [], "wars": [{"name": "Karluk savaşı", "when": "IX. yüzyıl veya daha önce", "foe": "Karluklar", "result": "yenilgi", "note": "Yabgu öldü. Tek savaşın yılı yoktur."}, {"name": "Peçeneklerin sürülmesi", "when": "898-902", "foe": "Peçenekler", "result": "zafer", "note": "Hazarlarla anlaşıp Peçenekleri İdil batısına sürdüler. Yıl aralığı TDV Oğuzlar'da 898-902, Peçenek maddesinde hücum 889'dur."}], "legends": ["Câmiü't-tevârîh'te Kayı, Yazır, Avşar ve Eymir boyundan çıktığı söylenen yabgu adları başka kaynakta yoktur."], "sources": [{"title": "TDV İslâm Ansiklopedisi, OĞUZLAR", "url": "https://islamansiklopedisi.org.tr/oguzlar"}]}, {"id": "oguz-dukak", "name": "Dukak", "title": "subaşı", "birth": null, "birthNote": "kayıtlarda yok", "death": null, "deathNote": "Selçuk 17-18 yaşındayken öldü. Yıl yok.", "reign": [null, null], "reignNote": "Yabgu değil. Temür Yalığ (demir yaylı) lakabıyla anılan subaşı veya boy başbuğu.", "summary": "Selçuk'un babası. Oğuz yabgusunun danıştığı nüfuzlu bir komutandı. Bir seferde yabguyla çatıştığı, yaraladığı ve sonra barıştırıldığı Selçuklu kaynaklarında yazılır. Hazar hakanına tâbi olduğu iddiasına TDV şüpheyle bakar.", "traits": [], "contribution": "", "harm": "", "wives": [], "children": [{"name": "Selçuk", "mother": "", "note": "Bazı geç kaynaklar babayı Lokman diye yazar; TDV bunu Dukak'ın bozulması sayar", "certainty": "olasi"}], "wars": [], "legends": ["Yabguyu gürzle attan düşürdüğü sahne Ahbâr ve İbnü'l-Esîr çizgisindedir."], "sources": [{"title": "TDV İslâm Ansiklopedisi, SELÇUK BEY", "url": "https://islamansiklopedisi.org.tr/selcuk-bey"}]}, {"id": "oguz-etrek", "name": "Etrek", "title": "subaşı", "birth": null, "birthNote": "kayıtlarda yok", "death": null, "deathNote": "kayıtlarda yok", "reign": [921, null], "reignNote": "921'de elçilik heyetini karşılayan subaşı. Yabgu değildir. İl Doğan oğlu diye anılır.", "summary": "Abbâsî elçilerine karşı ne yapılacağını tarhan ve yinaları toplayıp sordu. İdil Bulgar hanı Almış'ın damadıydı.", "traits": [], "contribution": "Oğuz meclis usulü onun 921 kaydında görülür.", "harm": "", "wives": [{"name": "kayıtlarda adı geçmiyor", "note": "Almış Han'ın kızı", "certainty": "olasi"}], "children": [], "wars": [], "legends": [], "sources": [{"title": "TDV İslâm Ansiklopedisi, OĞUZLAR", "url": "https://islamansiklopedisi.org.tr/oguzlar"}]}, {"id": "oguz-selcuk", "name": "Selçuk", "title": "subaşı", "birth": null, "birthNote": "Yaklaşık 287/900 tahmini. Kesin yıl yok.", "death": 1007, "deathNote": "Yaklaşık 397/1007, Cend'de. 100 veya 107 yaşında dendiği için 1009-1010 da ileri sürülür.", "reign": [961, 1007], "reignNote": "Yabgu değil. Yenikent'ten ayrılış muhtemel 350/961; 925-940, 955 ve 985-986 da verilir. TDV Oğuzlar Meliknâme'ye göre 375/985-86.", "summary": "Dukak ölünce yabgu onu subaşı yaptı. Hatunun kıskançlığı, otlak darlığı ve Kıpçak sıkıştırması anlatılarıyla Yenikent'ten Cend'e gitti. Orada İslâm'ı seçip yabgu devletiyle bağını kesti. Oğullarından İsrail, Arslan Yabgu unvanını aldı.", "traits": [], "contribution": "Cend'de müslüman olup Selçuklu kolunu yabgu birliğinden ayırdı.", "harm": "", "wives": [{"name": "kayıtlarda adı geçmiyor", "note": "TDV, Türkmen hükümdarlarından birinin kızıyla evli olduğunu Köymen'e dayanarak yazar", "certainty": "olasi"}], "children": [{"name": "Mîkâil", "mother": "", "note": "Muhtemelen bir seferde şehit düştü; yıl yok", "certainty": "olasi"}, {"name": "İsrâil", "mother": "", "note": "Arslan Yabgu. Üç oğullu listenin parçası", "certainty": "olasi"}, {"name": "Mûsâ", "mother": "", "note": "Üç oğullu listenin parçası", "certainty": "olasi"}, {"name": "Yûnus", "mother": "", "note": "Yalnızca bazı kaynaklardaki dört ve beş oğullu listede", "certainty": "rivayet"}, {"name": "Yûsuf", "mother": "", "note": "Yinal diye de anılır; yalnızca beş oğullu listede", "certainty": "rivayet"}], "wars": [], "legends": ["Soyun Efrâsiyâb'a bağlanması İbn Hassûl ve Nizâmülmülk'te vardır; TDV bunu efsane diye ayırır.", "Hâce Kereküçü oğlu Tokşurmuş adlı ata başka kaynakta doğrulanmaz."], "sources": [{"title": "TDV İslâm Ansiklopedisi, SELÇUK BEY", "url": "https://islamansiklopedisi.org.tr/selcuk-bey"}, {"title": "TDV İslâm Ansiklopedisi, OĞUZLAR", "url": "https://islamansiklopedisi.org.tr/oguzlar"}]}]}, {"id": "karahanli", "name": "Karahanlı Devleti", "short": "Karahanlılar", "aliases": ["Âl-i Afrâsiyâb", "Hakaniye", "İlek Hanlar", "Kara Hanlılar"], "region": "turkistan", "start": 840, "end": 1212, "startNote": "840 yılında Uygur Kağanlığı'nın çöküşü üzerine Bilge Kül Kadir Han'ın kağanlık ilan etmesiyle kuruldu.", "endNote": "1211'de Doğu Karahanlıların Karahıtaylar, 1212'de Batı Karahanlıların Harzemşah Alâeddin Muhammed tarafından ilhakıyla sona erdi.", "capital": "Balasagun, Kaşgar, Taraz ve Semerkant", "religion": "İslamiyet (Sünnî-Hanefî)", "confidence": "kayit", "confidenceNote": "Arap-Fars vekayinameleri (İbnü'l-Esîr, Utbî), Divânu Lugâti't-Türk ve Kutadgu Bilig ile sabittir.", "summary": "Tarihte İslamiyet'i kabul eden ilk büyük Türk devleti. Karluk, Çiğil ve Yağma boylarının birleşmesiyle kurulan devlet, Satuk Buğra Han (Abdülkerim) devrinde İslamiyet'i resmi din olarak kabul etti. Maveraünnehir'e inerek Samanîler hanedanını yıktılar. Yusuf Has Hacib'in Kutadgu Bilig'i ve Kâşgarlı Mahmud'un Dîvânu Lugâti't-Türk'ü bu muazzam kültür devrinde yazıldı. 1042 civarında Doğu ve Batı olarak ikiye ayrıldılar.", "legacy": "Türk-İslam medeniyetinin kurucu omurgasını oluşturdu. Türk dilini ve edebiyatını İslam potasında abideleştiren Kutadgu Bilig ve Dîvânu Lugâti't-Türk'ü insanlığa armağan etti.", "essay": ["Karahanlılar, 840 yılında Yenisey Kırgızlarının Uygur başkenti Karabalgasun'u yerle bir etmesi üzerine Karluk yabgusu Bilge Kül Kadir Han'ın kendisini bozkırın meşru kağanı ilan etmesiyle doğdu. Devlet geleneksel ikili teşkilatla yönetilirdi: Büyük Kağan (Arslan Han) Balasagun'da, ortak kağan (Buğra Han) ise Taraz veya Kaşgar'da otururdu.", "Bilge Kül Kadir Han'ın torunu Satuk Buğra Han, Samani şehzadeleri ve seyyah Ebû Nasr el-Sâmânî'nin vesilesiyle genç yaşta gizlice İslamiyet'i kabul ederek 'Abdülkerim' adını aldı. 940 civarında amcası Oğulcak Kadir Han'a karşı darbe yaparak tahta geçti ve İslamiyet'i devletin resmi inancı yaptı. Oğlu Baytaş Musa Han zamanında (960 civarı) 200 bin çadırlık Türkmen kitlesinin Müslüman olduğu tarihi kaynaklarda zikredilir.", "10. yüzyıl sonunda Nasr b. Ali (İlig Han) komutasındaki Karahanlı orduları Buhara ve Semerkant'ı zaptederek Samani Devleti'ne son verdi ve Ceyhun nehrini Gazneliler ile sınır yaptı. 1042 yılında hanedan içi çekişmeler sebebiyle Semerkant merkezli Batı Karahanlılar ve Kaşgar merkezli Doğu Karahanlılar olmak üzere ikiye ayrıldılar. Doğu devleti 1211'de Karahıtaylar, Batı devleti ise 1212'de Semerkant'ta Harzemşah Alâeddin Muhammed tarafından ortadan kaldırıldı."], "sources": [{"title": "TDV İslâm Ansiklopedisi, KARAHANLILAR", "url": "https://islamansiklopedisi.org.tr/karahanlilar"}, {"title": "TDV İslâm Ansiklopedisi, SATUK BUĞRA HAN", "url": "https://islamansiklopedisi.org.tr/satuk-bugra-han"}, {"title": "Britannica, Qarakhanid dynasty", "url": "https://www.britannica.com/topic/Qarakhanid-dynasty"}], "rulers": [{"id": "karahanli-satuk-bugra", "name": "Satuk Buğra Han", "aliases": ["Abdülkerim Satuk Buğra Han", "Sultan Satuk Buğra"], "title": "Kağan / Abdülkerim", "birth": 895, "birthNote": "Yaklaşık 895 Kaşgar civarı", "death": 955, "deathNote": "Artuş'ta vefat etti, türbesi oradadır", "reign": [920, 955], "reignNote": "920'lerde İslamiyet'i ilan edip 955'e kadar hüküm sürdü.", "summary": "İslamiyet'i kabul eden ilk Türk kağanı. Samani mültecisi Ebû Nasr vesilesiyle gizlice Müslüman oldu, amcası Oğulcak'ı mağlup ederek Kaşgar tahtına oturdu ve İslam'ı devlet dini ilan etti. Gazaları Türk destanlarına konu oldu.", "traits": ["Gazi kağan", "Dindar inkılapçı", "Manevi önder"], "contribution": "Türk milletinin İslam medeniyetine girişine kapı açtı; ilk cami ve medreseleri kurdurdu.", "harm": "Eski inançlarını korumak isteyen akrabaları ve boylarla uzun iç savaşlara girdi.", "wives": [], "children": [{"name": "Baytaş Musa Buğra Han", "mother": "", "note": "İslamiyet'i halkına tam olarak kabul ettiren sultan", "certainty": "kesin"}, {"name": "Süleyman Arslan Han", "mother": "", "note": "Büyük Kağan", "certainty": "kesin"}], "wars": [{"name": "Kaşgar Fethi ve İhtilal", "when": "920", "foe": "Oğulcak Kadir Han kuvvetleri", "result": "zafer", "note": "Kaşgar ele geçirilip İslam merkezi yapıldı."}, {"name": "Hoten Seferleri", "when": "940-950", "foe": "Budist Hoten Krallığı", "result": "zafer", "note": "Doğu Tarım havzasına İslamiyet yayıldı."}], "legends": ["Tezkire-i Satuk Buğra Han'da gece rüyasında gökten inen bir nur ile İslam'a davet edildiği ve kılıcının kırk arşın uzadığı rivayet edilir."], "sources": [{"title": "TDV İslâm Ansiklopedisi, SATUK BUĞRA HAN", "url": "https://islamansiklopedisi.org.tr/satuk-bugra-han"}]}, {"id": "karahanli-musa-bugra", "name": "Musa Buğra Han", "aliases": ["Baytaş Musa Han", "Tonga İlig"], "title": "Büyük Kağan", "birth": null, "birthNote": "Kayıtlarda yok", "death": 971, "deathNote": "Kaşgar'da vefat etti", "reign": [955, 971], "reignNote": "16 yıl hüküm sürdü.", "summary": "Satuk Buğra Han'ın oğlu. 960 yılında 200 bin çadırlık Türkmen boyunun kitleler halinde Müslüman olmasını sağladı. İslam dünyasında Karahanlıların itibarını en üst seviyeye çıkardı.", "traits": ["Adil tebliğci", "Dirayetli hükümdar"], "contribution": "200 bin çadırlık Türk kitlesinin barışçıl biçimde Müslüman olmasını sağlayarak Türk tarihinin dönüm noktasını gerçekleştirdi.", "harm": "Budist Hoten Krallığı'nın ani karşı taarruzlarında kardeşi Arslan Han şehit düştü.", "wives": [], "children": [{"name": "Ali Arslan Han", "mother": "", "note": "Hoten savaşında şehit düştü", "certainty": "kesin"}], "wars": [{"name": "Hoten Cihadı", "when": "965", "foe": "Budist Hoten Krallığı", "result": "zafer", "note": "Tarım havzasındaki direniş kırıldı."}], "legends": ["960 yılındaki 200 bin çadırlık ihtida hadisesi İbnü'l-Esîr kroniğinde İslam tarihinin en büyük toplu hidayet olayı olarak anılır."], "sources": [{"title": "TDV İslâm Ansiklopedisi, KARAHANLILAR", "url": "https://islamansiklopedisi.org.tr/karahanlilar"}]}, {"id": "karahanli-tamgac-bugra", "name": "Tamgaç Buğra Han", "aliases": ["İbrâhim b. Nasr", "Ebû İshak İbrâhim Tamgaç Han"], "title": "Batı Kağanı / Tamgaç Han", "birth": null, "birthNote": "Kayıtlarda yok", "death": 1068, "deathNote": "Semerkant'ta felç geçirerek vefat etti", "reign": [1052, 1068], "reignNote": "Batı Karahanlı Devleti'nin altın çağı.", "summary": "Batı Karahanlıların kurucusu ve İslam dünyasının en adil hükümdarlarından biri. Semerkant'ı ilim ve medeniyet yuvası yaptı; Semerkant Darüşşifası'nı kurdu. Yusuf Has Hacib ünlü Kutadgu Bilig eserini Doğu hükümdarı Tamgaç Uluğ Buğra Han'a ithaf ederken onun adalet anlayışından ilham aldı.", "traits": ["Hz. Ömer adaleti timsali", "Fakir babası", "Yolsuzluk düşmanı"], "contribution": "Semerkant'ta muazzam bir hastane, tıp medresesi ve kütüphane kurdu; piyasada fiyat narhını titizlikle korudu.", "harm": "Selçuklularla zaman zaman sürtüşmeye girdi.", "wives": [], "children": [{"name": "Şemsülmülk Nasr", "mother": "", "note": "Babasından sonra kağan oldu, Melikşah'ın bacanağı", "certainty": "kesin"}], "wars": [{"name": "Semerkant Kuşatması ve İstiklâl", "when": "1052", "foe": "Doğu Karahanlı birlikleri", "result": "zafer", "note": "Semerkant'ı alarak Batı Karahanlı devletini tam bağımsız kıldı."}], "legends": ["Geceleri kılık değiştirerek pazarları denetlediği, kasapların terazilerini bizzat kontrol ettiği ve çalınan tek bir elmanın hesabını sorduğu Avfî'nin Cevâmiu'l-Hikâyât eserinde anlatılır."], "sources": [{"title": "TDV İslâm Ansiklopedisi, TAMGAÇ BUĞRA HAN", "url": "https://islamansiklopedisi.org.tr/tamgac-bugra-han"}, {"title": "TDV İslâm Ansiklopedisi, KARAHANLILAR", "url": "https://islamansiklopedisi.org.tr/karahanlilar"}]}]}, {"id": "gazneli", "name": "Gazneliler", "short": "Gazneliler", "aliases": ["Gazne Devleti", "Yemînîler", "Sebükteginîler"], "region": "turkistan", "start": 963, "end": 1187, "startNote": "Alp Tigin'in 963'te Gazne şehrini fethederek bağımsız beyliğini kurmasıyla temellendi.", "endNote": "1187 yılında Gurluların son merkez Lahor'u zaptedip Hüsrev Melik'i esir almasıyla yıkıldı.", "capital": "Gazne, ardından Lahor", "religion": "İslamiyet (Sünnî-Hanefî)", "confidence": "kayit", "confidenceNote": "Utbî (Târîh-i Yemînî), Beyhakî (Târîh-i Beyhakī) ve Bîrûnî'nin eserleriyle eksiksiz sabittir.", "summary": "Samanîlerin Türk kumandanı Alp Tigin ve damadı Sebüktegin tarafından Afganistan'da kurulan, Sultan Mahmud devrinde Hindistan'a yapılan 17 büyük seferle İslamiyet'i Hint alt kıtasına taşıyan cihan devleti. 'Sultan' unvanını İslam tarihinde ilk kullanan hükümdar Sultan Mahmud oldu. Sarayında Bîrûnî ve Firdevsî gibi devasa dehaları ağırladılar. 1040 Dandanakan'da Selçuklulara yenilip batı topraklarını kaybettiler; 1187'de Gurlular tarafından yıkıldılar.", "legacy": "Hindistan'da İslamiyet'in kök salmasını sağladı; bugünkü Pakistan ve Bangladeş'in İslami kimliğinin temelini attı. Türk askerî dehâsını fil birlikleriyle harmanladı.", "essay": ["Gazneliler, Samani Devleti'nin ordu komutanı Alp Tigin'in 963'te Gazne kalesini fethetmesiyle kuruldu. Asıl hanedan kurucusu, Alp Tigin'in kölesi ve damadı olan, 'Pendnâme' adlı eseriyle bilinen bilge hükümdar Sebüktegin (977-997) oldu. Sebüktegin, Hint Racası Caypal'ı mağlup ederek Pencap kapılarını açtı.", "Sultan Mahmud (998-1030) devrinde Gazne İmparatorluğu gücünün zirvesine ulaştı. Abbasi Halifesi el-Kādir-Billâh tarafından 'Yemînüddövle' (Devletin Sağ Kolu) lakabı verilen Mahmud, Hindistan'a 17 büyük sefer düzenledi. 1026 yılında Gucerat'taki Somnath Tapınağı Seferi İslam dünyasında bir efsaneye dönüştü. Sarayında 400 şair ve yüzlerce âlim besleyen Mahmud, Bîrûnî için 'Sarayımın en değerli hazinesi' demiştir.", "Mahmud'un oğlu Sultan Mesud döneminde Selçuklularla yapılan 1040 Dandanakan Muharebesi'ndeki ağır yenilgi Horasan ve İran'ın tamamen elden çıkmasına yol açtı. Devlet merkezini Hindistan'daki Lahor'a kaydıran Gazneliler, 1187'de Afganistan'ın yerel kavmi Gurluların Lahor'u zaptetmesiyle tarihe karıştı."], "sources": [{"title": "TDV İslâm Ansiklopedisi, GAZNELİLER", "url": "https://islamansiklopedisi.org.tr/gazneliler"}, {"title": "TDV İslâm Ansiklopedisi, MAHMÛD-I GAZNEVÎ", "url": "https://islamansiklopedisi.org.tr/mahmud-i-gaznevi"}, {"title": "TDV İslâm Ansiklopedisi, SEBÜK TEGİN", "url": "https://islamansiklopedisi.org.tr/sebuk-tegin"}], "rulers": [{"id": "gazneli-sebuktegin", "name": "Sebüktegin", "aliases": ["Ebû Mansûr Sebüktegin", "Nâsırüddin Sebüktegin"], "title": "Emir / Nâsırüddin", "birth": 942, "birthNote": "Barsgan (Kırgızistan) civarında 942'de doğdu", "death": 997, "deathNote": "Belh seferi dönüşünde vefat etti", "reign": [977, 997], "reignNote": "20 yıl boyunca hanedanın gerçek temellerini attı.", "summary": "Gazneli hanedanının gerçek kurucusu. Alp Tigin'in kızıyla evlendi, beylerin ittifakıyla tahta çıktı. Hindistan Şahı Caypal'ı iki kez mağlup ederek Peşaver'i fethetti. Oğlu Mahmud için yazdığı devlet ahlakı kitabı Pendnâme ile meşhurdur.", "traits": ["Mütefekkir lider", "Gazi", "Adil"], "contribution": "Dağınık Gazne garnizonunu imparatorluğa dönüştürdü; Hindistan fetihlerinin yolunu açtı.", "harm": "Ölürken yerine küçük oğlu İsmail'i veliaht bırakması Mahmud ile taht kavgasına yol açtı.", "wives": [{"name": "Alp Tigin'in kızı", "note": "Hanedan meşruiyetini sağlayan eşi", "certainty": "kesin"}], "children": [{"name": "Sultan Mahmud", "mother": "", "note": "Büyük cihan sultanı", "certainty": "kesin"}, {"name": "İsmail", "mother": "", "note": "Kısa süre tahta oturdu", "certainty": "kesin"}, {"name": "Nasr", "mother": "", "note": "Sipehsalar", "certainty": "kesin"}], "wars": [{"name": "Lâmğan Muharebesi", "when": "988", "foe": "Hindu Şahi Krallığı (Caypal)", "result": "zafer", "note": "Hint ordusu ve yüzlerce savaş fili bozguna uğratıldı, Peşaver alındı."}], "legends": ["Avda yakaladığı bir ceylan yavrusunu annesinin acıklı bakışlarına kıyamayarak serbest bıraktığı ve rüyasında bu merhameti sebebiyle kendisine hükümdarlık müjdelendiği anlatılır."], "sources": [{"title": "TDV İslâm Ansiklopedisi, SEBÜK TEGİN", "url": "https://islamansiklopedisi.org.tr/sebuk-tegin"}]}, {"id": "gazneli-mahmud", "name": "Sultan Mahmud", "aliases": ["Mahmûd-ı Gaznevî", "Yemînüddövle", "Seyfüddevle Mahmud"], "title": "Sultan / Yemînüddövle", "birth": 971, "birthNote": "971 yılında doğdu", "death": 1030, "deathNote": "Gazne'de veremden vefat etti", "reign": [998, 1030], "reignNote": "32 yıl boyunca dünyaya nam salan hükümdarlık.", "summary": "Tarihte ilk 'Sultan' unvanını alan hükümdar. Hindistan'a düzenlediği 17 seferle putperest tapınakları yıktı, Somnath Seferi'yle efsaneleşti ve İslam'ı Pencap ve Gucerat'a yaydı. Gazne'yi saraylar, kütüphaneler ve camilerle bir dünya başkenti yaptı.", "traits": ["Büyük cihangir", "Put kırıcı gazi", "Sanat ve ilim hamisi"], "contribution": "Hindistan'da İslam hakimiyetinin temellerini attı; Bîrûnî ve Firdevsî'yi himaye etti.", "harm": "Sürekli Hindistan seferleriyle ordusunu batıdaki Türkmen göçlerini (Selçukluları) denetlemekte yetersiz bıraktı.", "wives": [{"name": "Kavsariyye Hatun", "note": "Mesud ve Muhammed'in annesi", "certainty": "kesin"}], "children": [{"name": "I. Mesud", "mother": "Kavsariyye Hatun", "note": "Dandanakan'da yenilen sultan", "certainty": "kesin"}, {"name": "Muhammed", "mother": "Kavsariyye Hatun", "note": "Kısa süre tahta oturdu", "certainty": "kesin"}], "wars": [{"name": "Somnath Seferi", "when": "1026", "foe": "Gucerat Racalıkları", "result": "zafer", "note": "Devasa Somnath tapınağı fethedildi, tapınak putları Gazne ve Mekke'ye gönderildi."}, {"name": "Peşaver Muharebesi", "when": "1001", "foe": "Raca Caypal", "result": "zafer", "note": "Caypal esir edildi, intihar etti."}], "legends": ["Somnath putunun rahipleri milyonlarca altın fidye teklif ettiğinde 'Ben put satan değil, put kıran Mahmud olarak anılmak isterim' diyerek gürzüyle putu parçaladığı meşhurdur."], "sources": [{"title": "TDV İslâm Ansiklopedisi, MAHMÛD-I GAZNEVÎ", "url": "https://islamansiklopedisi.org.tr/mahmud-i-gaznevi"}]}, {"id": "gazneli-mesud", "name": "Sultan I. Mesud", "aliases": ["Cemâlüddevle Mesud", "Gazi Mesud"], "title": "Sultan", "birth": 998, "birthNote": "998'de doğdu", "death": 1041, "deathNote": "Giri Kalesi'nde tahttan indirilip yeğeni tarafından öldürüldü", "reign": [1030, 1040], "reignNote": "1040 Dandanakan hezimetiyle son buldu.", "summary": "Sultan Mahmud'un oğlu. Bizzat savaş meydanlarında gürzü ve kılıcıyla cenk eden devasa cüsseli bir pehlivandı. Ancak Selçukluların Horasan'daki taktik yıpratma stratejisini küçümsedi; 1040 Dandanakan Muharebesi'nde ordusu dağılınca Horasan'ı Selçuklulara kaptırdı.", "traits": ["Pehlivan kuvvetli", "Kişisel cesareti yüksek", "Stratejide inatçı"], "contribution": "Hindistan'da Hansi kalesini fethederek gaza faaliyetlerini sürdürdü.", "harm": "Kibir ve inadı yüzünden Dandanakan'da imparatorluğun belkemiğini kırdı; Gaznelileri bölgesel bir Hindistan krallığına küçülttü.", "wives": [], "children": [{"name": "Mevdud b. Mesud", "mother": "", "note": "Babasından sonra Gazne tahtına geçti", "certainty": "kesin"}, {"name": "İbrahim b. Mesud", "mother": "", "note": "Uzun süre hüküm süren istikrarlı sultan", "certainty": "kesin"}], "wars": [{"name": "Dandanakan Muharebesi", "when": "1040", "foe": "Büyük Selçuklu Devleti (Tuğrul ve Çağrı)", "result": "yenilgi", "note": "Gazneli ordusu üç günlük kuşatmadan sonra çöktü, Mesud canını zor kurtardı."}], "legends": ["Târîh-i Beyhakī'de savaş meydanında tek başına yüzlerce düşman arasına daldığı ve devasa çelik gürzünü savurduğu ayrıntılarıyla anlatılır."], "sources": [{"title": "TDV İslâm Ansiklopedisi, GAZNELİLER", "url": "https://islamansiklopedisi.org.tr/gazneliler"}]}]}, {"id": "harzemsah", "name": "Harzemşahlar", "short": "Harzemşahlar", "aliases": ["Hârizmşahlar", "Anuşteginliler"], "region": "turkistan", "start": 1097, "end": 1231, "startNote": "Selçuklu valisi Anuş Tegin'in oğlu Kutbeddin Muhammed'in Hârizmşah unvanıyla göreve gelmesiyle temellendi.", "endNote": "1231 yılında Celâleddin Mengüberti'nin Meyyâfârikīn dağlarında bir Kürt köylüsü tarafından öldürülmesiyle yıkıldı.", "capital": "Gürgenç (Köhne Ürgenç), ardından Tebriz", "religion": "İslamiyet (Sünnî-Hanefî)", "confidence": "kayit", "confidenceNote": "Nesevî (Sîret-i Celâleddin), Cüveynî (Târîh-i Cihângüşâ) ve İbnü'l-Esîr ile sabittir.", "summary": "Aral gölü güneyindeki Hârizm havzasında Begdili Türkmen boyundan Anuş Tegin soyunca kurulan, 12. yüzyıl sonunda Büyük Selçuklu mirasını devralarak İran, Maveraünnehir ve Horasan'a hakim olan devasa imparatorluk. Alâeddin Tekiş ve oğlu Alâeddin Muhammed devrinde en geniş sınırlarına ulaştı. 1218 Otrar faciası sonrası başlayan Cengiz Han Moğol istilasıyla yıkıldı. Son hükümdar Celâleddin Mengüberti Moğollara karşı destansı bir direniş gösterdi.", "legacy": "Moğol kasırgasına karşı İslam dünyasının son büyük kalkanı oldu. Celâleddin Harzemşah'ın kahramanlığı Doğu ve Batı edebiyatında bağımsızlık ve cesaret sembolü olarak ölümsüzleşti.", "essay": ["Harzemşahlar Devleti, Selçuklu Sultanı Melikşah'ın taştdârı (ibrikçibaşı) olan Begdili boyu mensubu Anuş Tegin Garçai'nin soyundan gelir. 1097'de Hârizm valisi olan Kutbeddin Muhammed ve oğlu Atsız (1128-1156), Sultan Sencer'e karşı defalarca bağımsızlık mücadelesi vererek devleti güçlendirdi.", "İl Arslan'ın oğlu Alâeddin Tekiş (1172-1200), Karahıtay baskısını kırdı ve 1194'te son Irak Selçuklu Sultanı III. Tuğrul'u mağlup ederek bütün İran'ı egemenliği altına aldı. Halife Nâsır-Lidênillâh ile çatışmaya giren Tekiş, doğunun tartışmasız en büyük gücü oldu. Oğlu Alâeddin Muhammed (1200-1220) ise Gurluları ve Karahanlıları yıkarak sınırlarını Umman Denizi'nden Seyhun'a kadar genişletti.", "Ancak 1218 yılında Otrar valisi İnalcık'ın Moğol kervanındaki 450 Müslüman tüccarı casusluk iddiasıyla öldürtmesi (Otrar Faciası), Cengiz Han'ın devasa ordularıyla İslam dünyasına çullanmasına yol açtı. Alâeddin Muhammed Hazar Denizi'nde Abeskun adasında sefalet içinde öldü. Oğlu Celâleddin Mengüberti, 11 yıl boyunca Hindistan'dan Azerbaycan'a kadar Moğollarla tek başına savaştı; İndus nehrine atlayışı Cengiz Han'ı bile hayran bıraktı. 1230'da Yassıçemen'de Anadolu Selçuklularına yenildikten sonra 1231'de şehit edildi ve devlet son buldu."], "sources": [{"title": "TDV İslâm Ansiklopedisi, HÂRİZMŞAHLAR", "url": "https://islamansiklopedisi.org.tr/harizmsahlar"}, {"title": "TDV İslâm Ansiklopedisi, CELÂLEDDİN HÂRİZMŞAH", "url": "https://islamansiklopedisi.org.tr/celaleddin-harizmsah"}, {"title": "TDV İslâm Ansiklopedisi, ALÂEDDİN MUHAMMED", "url": "https://islamansiklopedisi.org.tr/alaeddin-muhammed"}], "rulers": [{"id": "harzemsah-tekis", "name": "Alâeddin Tekiş", "aliases": ["Tekiş b. İl Arslan"], "title": "Hârizmşah / Sultan", "birth": null, "birthNote": "Kayıtlarda yok", "death": 1200, "deathNote": "Hârizm yolunda Şehristan civarında vefat etti", "reign": [1172, 1200], "reignNote": "28 yıl hüküm sürdü.", "summary": "İl Arslan'ın oğlu. Harzemşahları bölgesel bir emirlikten cihanşümul imparatorluğa yükselten hükümdar. 1194'te Rey yakınlarında Irak Selçuklularına son verdi; Abbasi halifesini siyasi vesayetine aldı.", "traits": ["Kurt politikacı", "Büyük stratejist", "Yorulmaz fatih"], "contribution": "İran, Horasan ve Hârizm'i tek bayrak altında toplayarak Selçuklu mirasını devraldı.", "harm": "Abbasi halifesiyle girdiği sert çatışma İslam dünyasındaki mezhep ve meşruiyet dengelerini sarstı.", "wives": [{"name": "Terken Hatun", "note": "Kıpçak Kanglı boyundan, devlette muazzam nüfuz sahibi güçlü hatun", "certainty": "kesin"}], "children": [{"name": "Alâeddin Muhammed", "mother": "Terken Hatun", "note": "Babasından sonra tahta geçen imparator", "certainty": "kesin"}, {"name": "Taceddin Ali Şah", "mother": "", "note": "İsfahan valisi", "certainty": "kesin"}], "wars": [{"name": "Rey Muharebesi", "when": "1194", "foe": "Irak Selçuklu Sultanı III. Tuğrul", "result": "zafer", "note": "Tuğrul öldürüldü, Irak Selçuklu devleti tamamen yıkıldı."}, {"name": "Buhara Seferi", "when": "1182", "foe": "Karahıtay valileri", "result": "zafer", "note": "Buhara fethedildi."}], "legends": [], "sources": [{"title": "TDV İslâm Ansiklopedisi, TEKİŞ", "url": "https://islamansiklopedisi.org.tr/tekis"}]}, {"id": "harzemsah-alaeddin-muhammed", "name": "Alâeddin Muhammed", "aliases": ["Kutbüddin Muhammed", "İkinci İskender", "Sencer-i Sânî"], "title": "Hârizmşah / Sultan", "birth": 1169, "birthNote": "1169 doğumlu", "death": 1220, "deathNote": "Hazar Denizi'ndeki Âbeskûn adasında zatürre ve kederden sefalet içinde öldü", "reign": [1200, 1220], "reignNote": "20 yıllık saltanatı ihtişamla başlayıp Moğol felaketiyle bitti.", "summary": "Tekiş'in oğlu. Kendisini 'İkinci İskender' ilan etti; Gurluları, Karahanlıları ve Karahıtayları yıkarak devasa bir imparatorluk kurdu. Ancak annesi Terken Hatun'un baskısı, Otrar Faciası ve Moğol ordusu karşısında ordusunu şehirlere dağıtıp kaçması İslam dünyasının tarihteki en büyük Moğol yıkımına uğramasına neden oldu.", "traits": ["Gururlu", "Hırslı fakat kriz anında panikleyen"], "contribution": "İmparatorluk sınırlarını Umman'dan Seyhun'a kadar genişletti.", "harm": "Otrar Faciası'na göz yumarak Cengiz Han istilasını tetikledi; ordusunu meydan savaşı yerine kalelere bölerek İslam şehirlerinin tek tek katledilmesine sebep oldu.", "wives": [], "children": [{"name": "Celâleddin Mengüberti", "mother": "", "note": "Efsanevi son hükümdar ve kahraman", "certainty": "kesin"}, {"name": "Gıyâseddin Pîrşah", "mother": "", "note": "Irak meliki", "certainty": "kesin"}, {"name": "Uzlagşah", "mother": "Terken Hatun soyundan", "note": "Terken Hatun'un veliaht yaptırdığı şehzade", "certainty": "kesin"}], "wars": [{"name": "Otrar Faciası ve Moğol İstilası", "when": "1219-1220", "foe": "Moğol İmparatorluğu (Cengiz Han)", "result": "yenilgi", "note": "Buhara, Semerkant ve Gürgenç düştü, milyonlarca insan katledildi, sultan kaçtı."}], "legends": ["Ölürken üzerinde kefen bezi bile bulunamadığı, sırtındaki yırtık gömlekle Hazar'daki ıssız adada toprağa verildiği anlatılır."], "sources": [{"title": "TDV İslâm Ansiklopedisi, ALÂEDDİN MUHAMMED", "url": "https://islamansiklopedisi.org.tr/alaeddin-muhammed"}]}, {"id": "harzemsah-celaleddin", "name": "Celâleddin Mengüberti", "aliases": ["Celâleddin Hârizmşah", "Mengüberti", "Mengü-Berti"], "title": "Hârizmşah / Sultan", "birth": 1199, "birthNote": "Yaklaşık 1199 doğumlu", "death": 1231, "deathNote": "Meyyâfârikīn dağlarında bir eşkıya tarafından şehit edildi", "reign": [1220, 1231], "reignNote": "11 yıllık efsanevi direniş destanı.", "summary": "Harzemşahların son hükümdarı ve Türk-İslam tarihinin en büyük kahramanlarından biri. Cengiz Han Moğollarına karşı Pervan'da İslam dünyasının ilk büyük zaferini kazandı. İndus nehrini atıyla geçerek Hindistan'a sığındı; geri dönüp Azerbaycan ve Gürcistan'ı fethederek Tebriz'de devletini yeniden kurdu. 11 yıl boyunca durmaksızın Moğollarla savaştı.", "traits": ["Yenilmez cengaver", "Döneminin Rüstem'i", "Korkusuz lider"], "contribution": "Moğolların yenilmezlik efsanesini Pervan'da yıktı; Kafkasya ve Doğu Anadolu'da direniş ruhunu canlı tuttu.", "harm": "Eyyûbîler ve Anadolu Selçukluları ile ittifak kurmak yerine Ahlat'ı kuşatıp Yassıçemen'de I. Alâeddin Keykubad ile savaşması İslam birliğini parçaladı.", "wives": [{"name": "Melike Hatun", "note": "İldenizli Atabeyi Özbek'in eşi, Selçuklu II. Tuğrul'un kızı", "certainty": "kesin"}], "children": [{"name": "Menkeli", "mother": "", "note": "Oğlu", "certainty": "olasi"}], "wars": [{"name": "Pervan Muharebesi", "when": "1221", "foe": "Moğol Ordusu (Şigi Kutuku)", "result": "zafer", "note": "Cengiz Han'ın seçkin ordusu imha edildi; Moğollara karşı ilk büyük İslam zaferi kazanıldı."}, {"name": "İndus Nehri Yarma Harekâtı", "when": "1221", "foe": "Cengiz Han bizzat", "result": "yenilgi", "note": "Kuşatılınca atını uçurumdan coşkun İndus nehrine sürdü, Cengiz Han hayranlıkla izledi."}, {"name": "Garni Muharebesi", "when": "1225", "foe": "Gürcistan Krallığı", "result": "zafer", "note": "Tiflis fethedildi, Gürcü ordusu dağıtıldı."}, {"name": "Yassıçemen Muharebesi", "when": "1230", "foe": "Anadolu Selçukluları (I. Alâeddin Keykubad) ve Eyyûbîler", "result": "yenilgi", "note": "İslam dünyasının iki büyük Türk hükümdarı karşılaştı, Celâleddin yenildi."}], "legends": ["İndus nehrine atlayıp karşı kıyıya geçtiğinde Cengiz Han oğullarına dönüp: 'Bir babanın böyle bir oğlu olmalı! İki elinde kılıçla azgın nehri yarıp geçti' demiştir."], "sources": [{"title": "TDV İslâm Ansiklopedisi, CELÂLEDDİN HÂRİZMŞAH", "url": "https://islamansiklopedisi.org.tr/celaleddin-harizmsah"}, {"title": "TDV İslâm Ansiklopedisi, HÂRİZMŞAHLAR", "url": "https://islamansiklopedisi.org.tr/harizmsahlar"}]}]}, {"id": "delhi-turk-sultanligi", "name": "Delhi Türk Sultanlığı", "short": "Delhi Sultanlığı (Memlûk-Halacî)", "aliases": ["Delhi Sultanate", "Saltanat-ı Dehlî", "Hindistan Türk Devleti"], "region": "turkistan", "start": 1206, "end": 1526, "startNote": "1206'da Kutbüddin Aybeg'in bağımsızlığını ilan etmesiyle kurulan; Memlûk, Halacî ve Tuğluk Türk hanedanlarının yönettiği büyük imparatorluk.", "endNote": "1526 Panipat Meydan Muharebesi'nde Bâbür Şah'ın İbrâhim Lûdî'yi yenmesiyle yerini Bâbür İmparatorluğu'na bıraktı.", "capital": "Delhi (Lâl Kot, Tughlakabad)", "religion": "İslamiyet (Sünnî-Hanefî)", "confidence": "kayit", "confidenceNote": "Minhâc-ı Sirâc (Tabakât-ı Nâsırî), Ziyâeddin Berenî (Târîh-i Fîrûzşâhî) ve İbn Battûta seyahatnamesiyle sabittir.", "summary": "Hindistan alt kıtasında İslam hakimiyetini kalıcı kılan, 320 yıl boyunca Delhi merkezli hüküm süren kudretli Türk imparatorluğu. Kutbüddin Aybeg, Şemseddin İltutmuş, Türk ve İslam tarihinin ilk kadın hükümdarı Raziyye Sultan, Alâeddin Halacî ve Muhammed bin Tuğluk gibi büyük hükümdarlar yönetti. Kutub Minar gibi abidevi eserler inşa edildi. Moğol istilalarını defalarca püskürterek Hindistan'ı tahripten kurtardı. 1526'da Bâbür İmparatorluğu'na devroldu.", "legacy": "Dünyanın en yüksek tuğla minaresi olan Kutub Minar'ı insanlığa kazandırdı; Hint alt kıtasını Türk-İslam mimarisi ve sanatıyla yoğurdu.", "essay": ["Delhi Türk Sultanlığı, Gurlu kumandanı Kıpçak asıllı Kutbüddin Aybeg'in 1206'da bağımsızlığını ilan etmesiyle kuruldu. Aybeg'in başlattığı Kutub Minar, Türk-İslam mimarisinin Hindistan'daki zafer anıtı oldu.", "Şemseddin İltutmuş devleti teşkilatlandırdı; vefatında yerine kızı Raziyye Sultan'ı veliaht bıraktı. Raziyye Sultan (1236-1240), erkek kıyafetleriyle ordusunun başında bizzat sefere çıkan, feraseti ve adaletli yönetimiyle Türk tarihine geçen ilk kadın sultan oldu.", "Alâeddin Halacî (1296-1316), Moğol ordularını beş kez üst üste hezimete uğratarak Hindistan'ı Moğol felaketinden kurtardı ve Güney Hindistan'ı fethetti. Muhammed bin Tuğluk devrinde imparatorluk tüm Hint kıtasına yayıldı. 1526'da taht Timur soyundan gelen Bâbür Şah'a geçti."], "sources": [{"title": "TDV İslâm Ansiklopedisi, DELHİ SULTANLIĞI", "url": "https://islamansiklopedisi.org.tr/delhi-sultanligi"}, {"title": "TDV İslâm Ansiklopedisi, KUTBÜDDİN AYBEG", "url": "https://islamansiklopedisi.org.tr/kutbuddin-aybeg"}, {"title": "TDV İslâm Ansiklopedisi, RAZİYYE BEGÜM", "url": "https://islamansiklopedisi.org.tr/raziyye-begum"}, {"title": "TDV İslâm Ansiklopedisi, ALÂEDDİN HALACÎ", "url": "https://islamansiklopedisi.org.tr/alaeddin-halaci"}], "rulers": [{"id": "delhi-kutbuddin-aybeg", "name": "Kutbüddin Aybeg", "aliases": ["Aybeg", "Lâh-bahş (Milyonlar Bağışlayan)"], "title": "Sultan / Memlûk / Kurucu", "birth": 1150, "birthNote": "Türkistan bozkırında doğdu, Nişabur'da köle pazarından alındı", "death": 1210, "deathNote": "Lahor'da polo (çevgân) oynarken atından düşerek vefat etti", "reign": [1206, 1210], "reignNote": "Delhi Sultanlığı ve Muizzî (Memlûk) Hanedanı'nın kurucusu.", "summary": "Türkistan'dan köle olarak getirilip liyakatiyle Hindistan fatihi ve hükümdarı olan büyük sultan. Delhi'yi fethederek başkent yaptı. Hindistan'ın en görkemli taş minaresi olan Kutub Minar'ın ve Kuvvetü'l-İslam Camii'nin inşasını başlattı. Cömertliği sebebiyle 'Lâh-bahş' lakabını aldı.", "traits": ["Fevkalade cömert", "Yenilmez fatih", "Mütevazı teşkilatçı"], "contribution": "Hindistan'da 300 yıl sürecek Türk hakimiyetini kurdu; Kutub Minar'ın temelini attı.", "harm": "Erken vefatı sebebiyle sultanlığın idari teşkilatını tam olarak tamamlayamadı.", "wives": [{"name": "Tâceddin Yıldız'ın Kızı", "note": "Siyasi izdivaç", "certainty": "olasi"}], "children": [{"name": "Ârâm Şah", "mother": "", "note": "Kısa süre tahta oturdu", "certainty": "tartismali"}, {"name": "Kutbiyye Hatun", "mother": "", "note": "Şemseddin İltutmuş ile evlenen kızı", "certainty": "kesin"}], "wars": [{"name": "Tarain Muharebesi", "when": "1192", "foe": "Çauhan Racput Krallığı (Prithviraj)", "result": "zafer", "note": "Kuzey Hindistan kapıları Türk ordularına açıldı."}, {"name": "Delhi Kuşatması ve Fethi", "when": "1193", "foe": "Tomara Hanedanı", "result": "zafer", "note": "Delhi zaptedilerek Türk hakimiyetinin merkezi yapıldı."}], "legends": ["Kutub Minar'ın dibinde bulunan paslanmaz demir sütunun (Iron Pillar of Delhi) yanına inşa ettiği cami günümüzde UNESCO Dünya Mirasıdır."], "sources": [{"title": "TDV İslâm Ansiklopedisi, KUTBÜDDİN AYBEG", "url": "https://islamansiklopedisi.org.tr/kutbuddin-aybeg"}]}, {"id": "delhi-raziyye-sultan", "name": "Raziyye Sultan", "aliases": ["Celâletüddin Raziyye Begüm", "Razia Sultana"], "title": "Sultan / Padişah-ı Âlem", "birth": 1205, "birthNote": "Delhi'de sarayda doğdu", "death": 1240, "deathNote": "Kaithal yakınlarında esir alınıp şehit edildi", "reign": [1236, 1240], "reignNote": "Türk-İslam tarihinin tahta geçen İLK kadın hükümdarı.", "summary": "Şemseddin İltutmuş'un kızı. Babasının vasiyeti ve halkın desteğiyle tahta çıktı. Sarayda ve orduda erkek kıyafetleriyle göründü; ata bindi, ordusunun başında bizzat savaştı. 'Umdetü'n-Nisvân' unvanıyla sikke bastırdı. Kırklar Meclisi'nin (Çihilgân) Türk emirlerinin entrikalarına karşı cesurca savaştı. Altuniye ile evlenerek tahtını geri almaya çalışırken pusuya düşürülüp şehit edildi.", "traits": ["Cesur kadın hükümdar", "Adalet timsali", "Fevkalade zeki", "Halkın sevgilisi"], "contribution": "Türk kadınının devlet idaresindeki kudretini ve cesaretini tüm dünyaya kanıtladı; medreseler ve kütüphaneler kurdu.", "harm": "Gelenekçi Türk emirleri ('Kırklar') ile girdiği iktidar mücadelesi saray krizlerini tetikledi.", "wives": [], "children": [], "wars": [{"name": "Delhi Taht İsyanı Bastırması", "when": "1236", "foe": "Vezir Cüneydî ve İsyancı Türk Emirleri", "result": "zafer", "note": "Kırmızı elbise giyip halkın önüne çıkarak adaleti sağladı ve tahtını güvenceye aldı."}, {"name": "Kaithal Muharebesi", "when": "1240", "foe": "Behram Şah Destekçisi Emirler", "result": "yenilgi", "note": "Ordusu dağıldı, esir alınarak şehit edildi."}], "legends": ["Tarihçi Minhâc-ı Sirâc onun için: 'Büyük bir hükümdarda bulunması gereken bütün vasıflara fazlasıyla sahipti; tek eksiği kaderin onu kadın yaratmış olmasıydı' diye yazmıştır."], "sources": [{"title": "TDV İslâm Ansiklopedisi, RAZİYYE BEGÜM", "url": "https://islamansiklopedisi.org.tr/raziyye-begum"}]}, {"id": "delhi-alaeddin-halaci", "name": "Alâeddin Halacî", "aliases": ["Sikander-i Sâni (İkinci İskender)"], "title": "Sultan / İkinci İskender", "birth": 1266, "birthNote": "Delhi civarında doğdu", "death": 1316, "deathNote": "Delhi'de vefat etti", "reign": [1296, 1316], "reignNote": "20 yıllık hükümdarlığıyla Hindistan'ın en kudretli fatihi.", "summary": "Halacî Türk hanedanının en büyük sultanı. Çağatay Moğollarının 5 büyük istila ordusunu Kili, Delhi ve Amroha muharebelerinde imha ederek Hindistan'ı Moğol istilasından kurtardı. Güney Hindistan'ı (Dekkan, Madurai) fethetti. Tarihin ilk sıkı fiyat denetimi ve narh sistemini (pazar ekonomisi kontrolü) başarıyla uyguladı. Kendisine 'İkinci İskender' lakabını verdi.", "traits": ["Yenilmez mareşal", "Ekonomi dehası", "Kati disiplinli lider", "Moğol fatihi"], "contribution": "Hindistan'ı Moğol soykırımından kurtardı; pazar ve narh reformlarıyla halkın alım gücünü ve ordu donanımını zirveye çıkardı.", "harm": "Vergileri çok yüksek tuttu; şüphelendiği muhaliflere karşı acımasız cezalar uyguladı.", "wives": [{"name": "Kemlâ Devî", "note": "Gucerât racasının eski eşi", "certainty": "kesin"}, {"name": "Mehru'n-Nisâ", "note": "Alp Han'ın kız kardeşi", "certainty": "olasi"}], "children": [{"name": "Hızır Han", "mother": "", "note": "Veliaht şehzade", "certainty": "kesin"}, {"name": "Kutbüddin Mübârek Şah", "mother": "", "note": "Sonraki sultan", "certainty": "kesin"}], "wars": [{"name": "Kili Muharebesi (Moğol İstilası)", "when": "1299", "foe": "Çağatay Hanlığı Moğol Ordusu (Kutluk Hoca)", "result": "zafer", "note": "200 bin kişilik Moğol ordusu Delhi önlerinde bozguna uğratıldı."}, {"name": "Çitor Kuşatması ve Fethi", "when": "1303", "foe": "Mewar Racput Krallığı (Ratan Singh)", "result": "zafer", "note": "Aşılamaz Çitor dağ kalesi fethedildi."}, {"name": "Amroha Muharebesi", "when": "1305", "foe": "Moğol Ordusu (Ali Beg ve Tarğı)", "result": "zafer", "note": "Moğol komutanları esir alındı, Moğol tehdidi kalıcı olarak kırıldı."}], "legends": ["Bastırdığı sikkelerin üzerine 'İskender-i Sâni' (İkinci İskender) unvanını kazıtması ve dünyayı fethetme ideali tarih boyunca anlatılmıştır."], "sources": [{"title": "TDV İslâm Ansiklopedisi, ALÂEDDİN HALACÎ", "url": "https://islamansiklopedisi.org.tr/alaeddin-halaci"}]}]}, {"id": "ak-orda", "name": "Ak Orda Hanlığı", "short": "Ak Orda (Sol Kol)", "aliases": ["White Horde", "Gök Orda", "Sol Kol Ulusu", "Sıgnak Hanlığı"], "region": "turkistan", "start": 1227, "end": 1428, "startNote": "Cuci'nin büyük oğlu Orda Ecen'e İrtiş, Seyhun ve Balkaş boylarının verilmesiyle Altın Orda'nın doğu kanadı olarak kuruldu.", "endNote": "1428'de Şeybânî Ebulhayr Han'ın Özbek Ulusu'nu kurmasıyla tarihe karıştı.", "capital": "Sıgnak", "religion": "İslamiyet (Sünnî-Hanefî)", "confidence": "kayit", "confidenceNote": "Câmiu't-Tevârîh ve Şibanîler dönemi vakayinâmeleriyle sabittir.", "summary": "Cuci'nin en büyük oğlu Orda Ecen sülalesi tarafından İrtiş'ten Seyhun kıyılarına kadar uzanan sahada kurulan hanlık. Altın Orda'nın 'Sol Kolu'nu teşkil etti. Başkenti Sıgnak şehri ilim ve ticaret merkezi oldu. 14. yüzyılda Urus Han devrinde büyük bir askeri güç haline geldi; Kazak ve Özbek hanedanlarının doğrudan kök hücresini oluşturdu.", "legacy": "Kazak Hanlığı'nın han sülalesinin doğrudan atasıdır; Sıgnak ve Yesi havzasını Türk-İslam medeniyetiyle yoğurmuştur.", "essay": ["Ak Orda, Cuci'nin büyük oğlu Orda Ecen'e tahsis edilen doğu bozkırlarında özerk bir ulus olarak gelişti. Batıdaki Batu Han (Altın Orda) ulusuna tabiyet bağı zamanla gevşedi ve Sıgnak merkezli tam bağımsız bir hanlığa dönüştü.", "Urus Han (1368-1377), Ak Orda'yı bozkırın en çekinilen devleti yaptı. Saray tahtını ele geçirmeye çalıştı; Toktamış ve hamisi Emir Timur ile amansız savaşlara girdi. Urus Han'ın oğulları ve torunları daha sonra Kazak Hanlığı'nı kuracak olan çekirdek kadroyu oluşturdu."], "sources": [{"title": "TDV İslâm Ansiklopedisi, ALTIN ORDA", "url": "https://islamansiklopedisi.org.tr/altin-orda"}, {"title": "TDV İslâm Ansiklopedisi, KAZAKLAR", "url": "https://islamansiklopedisi.org.tr/kazaklar"}], "rulers": [{"id": "ak-orda-urus-han", "name": "Urus Han", "aliases": ["Oruz Han", "Muhammed Urus"], "title": "Han", "birth": 1330, "birthNote": "Sıgnak yöresinde doğdu", "death": 1377, "deathNote": "Seyhun boyunda vefat etti", "reign": [1368, 1377], "reignNote": "Ak Orda'nın en güçlü hükümdarı; Kazak hanlarının doğrudan atası.", "summary": "Ak Orda tahtında merkezi otoriteyi kuran, Sıgnak'ta kendi adına para bastıran ve Altın Orda başkenti Saray'ı da ele geçiren kudretli han. Toktamış'ın babasını isyan ettiği için idam ettirdi; Timur'un Toktamış'ı iade etme talebini reddederek Timur ordularına karşı direndi.", "traits": ["Tavizsiz hükümdar", "Cengaver", "Otoriter lider"], "contribution": "Ak Orda'yı müstakil bir güç yaptı; torunları Kerey ve Canıbek Hanlar Kazak Hanlığı'nı kurdu.", "harm": "Timur ile giriştiği savaşlar Ak Orda şehirlerinin tahrip olmasına yol açtı.", "wives": [], "children": [{"name": "Kutluk Buka", "mother": "", "note": "Timur ile savaşırken şehit oldu", "certainty": "kesin"}, {"name": "Toktakıya", "mother": "", "note": "Kısa süre tahta geçti", "certainty": "kesin"}, {"name": "Koyurçuk", "mother": "", "note": "Kazak hanlarının dedesi", "certainty": "kesin"}], "wars": [{"name": "Sıgnak Savunması", "when": "1376", "foe": "Timur İmparatorluğu Ordusu", "result": "zafer", "note": "Timur'un gönderdiği ilk ordu püskürtüldü."}], "legends": ["Kazak şecerelerinde Kazak hanlarının 'Urus Han nesli' olarak anılması onun bozkırdaki derin meşruiyetinin simgesidir."], "sources": [{"title": "TDV İslâm Ansiklopedisi, ALTIN ORDA", "url": "https://islamansiklopedisi.org.tr/altin-orda"}]}]}, {"id": "timur-imparatorlugu", "name": "Timur İmparatorluğu", "short": "Timurlular", "aliases": ["Tîmûriyye", "Gürgâniyye", "Timurid Empire"], "region": "turkistan", "start": 1370, "end": 1507, "startNote": "Emir Timur'un 1370'te Belh kurultayında 'Büyük Emir' seçilerek Semerkant tahtına oturmasıyla kuruldu.", "endNote": "1507 yılında Özbek Hanı Muhammed Şeybânî'nin Herat'ı zaptetmesiyle sona erdi.", "capital": "Semerkant ve Herat", "religion": "İslamiyet (Sünnî-Hanefî)", "confidence": "kayit", "confidenceNote": "Yezdî (Zafernâme), Nizâmeddin Şâmî (Zafernâme), İbn Arabşah ve Clavijo sefaretnâmesiyle sabittir.", "summary": "Barlas boyuna mensup Emir Timur (Aksak Timur / Timurlenk) tarafından Semerkant merkezli kurulan, Volga'dan Ganj'a, İzmir'den Çin sınırına kadar uzanan cihan imparatorluğu. Timur girdiği hiçbir meydan muharebesinde yenilmedi; 1402'de Ankara Savaşı'nda Yıldırım Bayezid'i mağlup etti. Semerkant'ı dünyanın en göz kamaştırıcı başkentine dönüştürdü. Oğlu Şahruh ve torunu Uluğ Bey devirlerinde astronomi, matematik, mimari ve Çağatay Türk edebiyatı (Ali Şîr Nevâî) Rönesans seviyesine ulaştı. 1507'de Şeybânîler tarafından yıkıldı.", "legacy": "Timurlu Rönesansı'nı başlattı; Uluğ Bey Rasathanesi ve Zîc-i Uluğ Bey ile modern gökbiliminin temellerini attı. Ali Şîr Nevâî ve Hüseyin Baykara meclisleriyle Çağatay Türkçesini yüksek bir medeniyet ve edebiyat dili haline getirdi.", "essay": ["Timur İmparatorluğu, Çağatay Hanlığı'nın kargaşa günlerinde Türkleşmiş Barlas boyu reisi Emîr Taragay'ın oğlu Timur tarafından 1370'te kuruldu. Cengiz soyundan olmadığı için 'Han' unvanını almayıp 'Emîr' unvanıyla yetindi; Cengiz hanedanından bir prensesle evlenerek 'Gürgân' (Han Damadı) lakabını kullandı.", "Timur, 35 yıllık hükümdarlığında üç yıllık, beş yıllık ve yedi yıllık seferlerle Altın Orda'yı (Toktamış), Memlükleri (Halep ve Şam), Delhi Sultanlığı'nı ve 1402 Ankara Meydan Muharebesi'nde Osmanlı Devleti'ni (Yıldırım Bayezid) mağlup etti. İzmir'i Rodos Şövalyeleri'nden fethederek Hristiyan dünyasını sarstı. Semerkant'ta Bîbî Hanım Camii ve Gûr-ı Emîr türbesini inşa ettirdi; fethettiği yerlerdeki en mahir sanatkârları ve âlimleri Semerkant'a topladı. 1405'te Çin Seferi'ne giderken Otrar'da vefat etti.", "Timur'un oğlu Şahruh (1409-1447) ve eşi Gevher Şad devleti Herat merkezli barış ve sanat çağına taşıdı. Semerkant'ta hüküm süren torunu Uluğ Bey, dünyanın en gelişmiş rasathanesini kurarak yıldız cetvellerini hazırladı. Son büyük dönem Hüseyin Baykara ve çocukluk dostu vezir Ali Şîr Nevâî'nin Herat meclisleriyle geçti. 1507'de Özbeklerin Herat'ı almasıyla imparatorluk çöktü, hanedanın mirası Bâbür Şah ile Hindistan'a taşındı."], "sources": [{"title": "TDV İslâm Ansiklopedisi, TİMURLULAR", "url": "https://islamansiklopedisi.org.tr/timurlular"}, {"title": "TDV İslâm Ansiklopedisi, TİMUR", "url": "https://islamansiklopedisi.org.tr/timur"}, {"title": "TDV İslâm Ansiklopedisi, ULUĞ BEY", "url": "https://islamansiklopedisi.org.tr/ulug-bey"}], "rulers": [{"id": "timur-imparatorlugu-timur", "name": "Emir Timur", "aliases": ["Timur Gürgân", "Timurlenk", "Aksak Timur", "Tamerlane"], "title": "Büyük Emir / Gürgân / Sahipkıran", "birth": 1336, "birthNote": "Keş (Şehr-i Sebz) yakınlarında 1336'da doğdu", "death": 1405, "deathNote": "Çin Seferi sırasında Otrar'da hastalanarak vefat etti, Gûr-ı Emîr'dedir", "reign": [1370, 1405], "reignNote": "35 yıl boyunca yenilgi yüzü görmeyen cihan fatihi.", "summary": "Tarihin en büyük askeri dahilerinden biri. Asya'nın bir ucundan diğer ucuna ordular yürüttü; girdiği hiçbir savaşı kaybetmedi. Altın Orda, Delhi Sultanlığı, Memlükler ve Osmanlıları mağlup etti. Semerkant'ı eşsiz anıtlarla donattı.", "traits": ["Yenilmez mareşal", "Satranç ve tarih üstadı", "İmar hamisi fakat acımasız"], "contribution": "Semerkant'ı bir dünya kültür ve mimarlık cennetine çevirdi; Türk-İslam medeniyetinde Timurlu Rönesansı'nı başlattı.", "harm": "Altın Orda'yı yıkması Rus knezliklerinin önünü açtı; Osmanlı'yı yenmesi İstanbul'un fethini yarım asır geciktirdi; fethettiği şehirlerdeki kafa kuleleri dehşet saçtı.", "wives": [{"name": "Saray Mülk Hatun (Büyük Hanım)", "note": "Kazan Han'ın kızı; Timur'a Gürgân unvanını kazandıran baş hatun", "certainty": "kesin"}, {"name": "Ulcay Türkan Ağa", "note": "Emir Kazgan'ın torunu", "certainty": "kesin"}], "children": [{"name": "Cihangir Mirza", "mother": "", "note": "Çok sevdiği büyük oğlu, erken vefat etti", "certainty": "kesin"}, {"name": "Ömer Şeyh Mirza", "mother": "", "note": "Fars valisi", "certainty": "kesin"}, {"name": "Miranşah", "mother": "", "note": "Azerbaycan valisi, Bâbür'ün dedesi", "certainty": "kesin"}, {"name": "Şahruh", "mother": "", "note": "Babasından sonra imparatorluğu toparlayan sultan", "certainty": "kesin"}], "wars": [{"name": "Kunduzca Muharebesi", "when": "1391", "foe": "Altın Orda Hanlığı (Toktamış)", "result": "zafer", "note": "Volga boylarında Toktamış Han'ın ordusu bozguna uğratıldı."}, {"name": "Terek Irmağı Muharebesi", "when": "1395", "foe": "Altın Orda Hanlığı (Toktamış)", "result": "zafer", "note": "Altın Orda ordusu tamamen imha edildi, Saray şehri yıkıldı."}, {"name": "Delhi Muharebesi", "when": "1398", "foe": "Delhi Türk Sultanlığı (Sultan Mahmud)", "result": "zafer", "note": "120 zırhlı savaş filine karşı develere saman bağlayıp yakarak filleri püskürttü, Delhi alındı."}, {"name": "Ankara Meydan Muharebesi", "when": "1402", "foe": "Osmanlı Devleti (Yıldırım Bayezid)", "result": "zafer", "note": "Çubuk Ovası'nda Yıldırım esir alındı, Anadolu beylikleri yeniden canlandırıldı."}, {"name": "İzmir Kuşatması", "when": "1402", "foe": "Rodos Şövalyeleri (Hospitalier)", "result": "zafer", "note": "Hristiyan şövalyelerin deniz kalesi 15 günde yerle bir edildi."}], "legends": ["Semerkant'taki mezar taşına 'Kim ki benim mezarımı açarsa benden daha korkunç bir istilacıyla karşılaşır' yazıldığı ve Sovyet arkeolog Gerasimov'un mezarı açtığı 22 Haziran 1941 günü Hitler'in SSCB'ye saldırdığı tarihi bir rastlantı olarak anılır."], "sources": [{"title": "TDV İslâm Ansiklopedisi, TİMUR", "url": "https://islamansiklopedisi.org.tr/timur"}]}, {"id": "timur-imparatorlugu-ulug-bey", "name": "Uluğ Bey", "aliases": ["Muhammed Taragay Uluğ Bey"], "title": "Sultan / Müneccimbaşı / Âlim", "birth": 1394, "birthNote": "Sultaniye'de 1394'te doğdu", "death": 1449, "deathNote": "Oğlu Abdüllatif'in azmettirdiği suikastçılar tarafından Semerkant yakınlarında şehit edildi", "reign": [1447, 1449], "reignNote": "1409'dan itibaren 38 yıl Semerkant valisi ve hükümdarı, 1447-1449 arasında büyük sultan.", "summary": "Timur'un torunu, Şahruh'un oğlu. Dünya gökbilim ve matematik tarihinin en büyük dehalarından biri. Semerkant Rasathanesi'ni kurdu, Kadızâde-i Rûmî ve Ali Kuşçu ile birlikte 1018 yıldızın konumunu hatasız hesaplayan 'Zîc-i Uluğ Bey'i hazırladı. Kendi nankör oğlu tarafından şehit edildi.", "traits": ["Gökbilimci dahi", "Matematikçi", "Müşfik hükümdar", "İlim aşığı"], "contribution": "Semerkant Rasathanesi ve Uluğ Bey Medresesi'ni kurdu; hazırladığı yıldız cetvelleri asırlarca Doğu ve Batı dünyasında temel kaynak oldu; Ali Kuşçu'yu yetiştirdi.", "harm": "Devlet idaresinde askeri disiplini bilimsel çalışmalarının gerisinde tuttu; oğlu Abdüllatif'in isyanını bastıramadı.", "wives": [], "children": [{"name": "Abdüllatif", "mother": "", "note": "Babasını katlettiren isyancı oğul", "certainty": "kesin"}, {"name": "Abdülaziz", "mother": "", "note": "Şehzade", "certainty": "kesin"}], "wars": [], "legends": ["Ay üzerindeki kraterlerden birine ve bir asteroide uluslararası astronomi birliği tarafından 'Ulugh Beg' adı verilmiştir."], "sources": [{"title": "TDV İslâm Ansiklopedisi, ULUĞ BEY", "url": "https://islamansiklopedisi.org.tr/ulug-bey"}]}]}, {"id": "ozbek-hanligi", "name": "Özbek Hanlığı", "short": "Özbek Hanlığı (Ebu'l-Hayr)", "aliases": ["Ebu'l-Hayr Hanlığı", "Göçebe Özbek Devleti"], "region": "turkistan", "start": 1428, "end": 1500, "startNote": "Cuci'nin oğlu Şiban soyundan Ebu'l-Hayr Han'ın Sibir ve Deşt-i Kıpçak boylarını birleştirmesiyle kuruldu.", "endNote": "1500 yılında Muhammed Şeybânî Han'ın Maveraünnehir'e inip Buhara merkezli Şeybânî Devleti'ni kurmasıyla dönüştü.", "capital": "Çimki-Tura (Tümen), Sıgnak", "religion": "İslamiyet (Sünnî-Hanefî)", "confidence": "kayit", "confidenceNote": "Târîh-i Ebü'l-Hayr Hânî ve Habîbü's-Siyer kronikleriyle sabittir.", "summary": "Deşt-i Kıpçak bozkırlarında Cengiz Han'ın torunu Şiban soyundan Ebu'l-Hayr Han tarafından kurulan ilk müstakil Özbek devleti. Adını Altın Orda Hanı Özbek Han'dan alan bu konfederasyon, bozkır Türk ve Moğol boylarını birleştirdi. Sıgnak şehrini başkent yaparak şehirleşmeye yöneldiler. Hanlıktan ayrılan Canibek ve Kerey hanlar Kazak Hanlığı'nı kurarken, Ebu'l-Hayr'ın torunu Şeybânî Han Maveraünnehir'e inerek Timurluları yıktı.", "legacy": "Özbek ve Kazak milli kimliklerinin doğduğu tarihi beşik oldu.", "essay": ["Özbek Hanlığı, 1428 yılında henüz 16 yaşındaki Ebu'l-Hayr Han'ın Sibirya ve İdil boylarındaki Şibanî boylarını birleştirmesiyle doğdu.", "Ebu'l-Hayr Han, Siriderya boyundaki Sıgnak, Suzak ve Arkuk şehirlerini fethederek göçebe boyları ticaret merkezlerine bağladı. Timurlu taht kavgalarına müdahil olarak Ebu Said Mirza'ya destek verdi. Ancak 1450'lerin sonunda aşırı merkeziyetçi baskılar sebebiyle Canibek ve Kerey hanlar boylarıyla birlikte ayrılarak Kazak Hanlığı'nın temelini attılar.", "Ebu'l-Hayr'ın 1468'de Kalmuklar ve Kazaklarla mücadelesinde ölümünden sonra hanlık dağıldı. Torunu Muhammed Şeybânî Han boyları yeniden toplayarak 1500'de Semerkant ve Buhara'yı fethedip Şeybânîler Hanedanı'nı başlattı."], "sources": [{"title": "TDV İslâm Ansiklopedisi, ÖZBEKLER", "url": "https://islamansiklopedisi.org.tr/ozbekler"}, {"title": "TDV İslâm Ansiklopedisi, EBÜ'l-HAYR HAN", "url": "https://islamansiklopedisi.org.tr/ebul-hayr-han"}], "rulers": [{"id": "ozbek-hanligi-ebul-hayr", "name": "Ebu'l-Hayr Han", "aliases": ["Ebü'l-Hayr Han"], "title": "Han", "birth": 1412, "birthNote": "1412'de doğdu", "death": 1468, "deathNote": "Kazak bozkırında Ak-Kışlak civarında vefat etti", "reign": [1428, 1468], "reignNote": "40 yıllık kurucu hükümdarlık.", "summary": "Özbek Hanlığı'nın kurucusu. 40 yıl boyunca Deşt-i Kıpçak'ta hüküm sürdü. Seyhun havzasını zaptedip Sıgnak'ı başkent yaptı. Torunu Şeybânî Han yoluyla modern Özbekistan'ın temelini attı.", "traits": ["Bozkır fatihi", "Teşkilatçı"], "contribution": "Özbek siyasi varlığını teşkilatlandırdı, bozkır göçebelerini yerleşik medeniyetle buluşturdu.", "harm": "Aşırı sertliği Kazak boylarının kopmasına engel olamadı.", "wives": [{"name": "Rabia Sultan Begüm", "note": "Uluğ Bey'in kızı", "certainty": "kesin"}], "children": [{"name": "Şah Budak", "mother": "", "note": "Muhammed Şeybânî Han'ın babası", "certainty": "kesin"}, {"name": "Haydar Sultan", "mother": "", "note": "Şehzade", "certainty": "kesin"}], "wars": [{"name": "Sıgnak Fethi", "when": "1446", "foe": "Timurlu sınır valileri", "result": "zafer", "note": "Sıgnak ve Siriderya boyları zaptedildi."}], "legends": [], "sources": [{"title": "TDV İslâm Ansiklopedisi, EBÜ'l-HAYR HAN", "url": "https://islamansiklopedisi.org.tr/ebul-hayr-han"}]}]}, {"id": "buhara-hanligi", "name": "Buhara Hanlığı", "short": "Buhara Hanlığı (Emirliği)", "aliases": ["Buhara Emirliği", "Şeybânîler Hanlığı", "Canidler", "Mangıtlar"], "region": "turkistan", "start": 1500, "end": 1920, "startNote": "Muhammed Şeybânî Han'ın Semerkant ve Buhara'yı fethedip Timurlu hakimiyetine son vermesiyle kuruldu.", "endNote": "1920 yılında Kızıl Ordu'nun Buhara'yı bombalayıp son emir Alim Han'ı devirmesiyle sona erdi.", "capital": "Buhara ve Semerkant", "religion": "İslamiyet (Sünnî-Hanefî)", "confidence": "kayit", "confidenceNote": "Buhara vakfiyeleri, Mahmûd b. Velî (Bahrü'l-Esrâr) ve Rus arşivleriyle sabittir.", "summary": "Maveraünnehir'de Şeybânîler, Aşterhanîler (Canidler) ve Mangıt hanedanları tarafından 420 yıl yönetilen ulu Türk devleti. Şeybânî Han ve II. Abdullah Han devirlerinde Safevîlere ve Babürlülere karşı zaferler kazanarak Orta Asya'da Sünnî İslam'ın kalesi oldular. Buhara ve Semerkant'ı yüzlerce medrese ve camiyle donatarak 'Kubbetü'l-İslam' unvanını korudular. 1920'de Bolşevik Kızıl Ordu tarafından yıkıldı.", "legacy": "Buhara Kelyan Minaresi ve Medresesi, Mir Arab Medresesi ve Semerkant Registan Meydanı'ndaki Şir-Dor ve Tilla-Kari medreselerini insanlığa kazandırdı.", "essay": ["Buhara Hanlığı, Ebu'l-Hayr Han'ın torunu Muhammed Şeybânî Han'ın 1500 yılında Timurlu şehzadelerini kovarak Semerkant ve Buhara'yı almasıyla kuruldu.", "Şeybânîler (1500-1599) devrinde Ubeydullah Han ve II. Abdullah Han İran Safevîlerine karşı amansız bir mücadele vererek Horasan'ı ve Herat'ı fethetti. Ardından gelen Astrahan soyundan Canidler (Aşterhanîler, 1599-1785) döneminde Semerkant Registan Meydanı bugünkü muazzam çinili silüetine kavuştu.", "Mangıt Hanedanı (1785-1920) devrinde devlet 'Buhara Emirliği' adını aldı. 1868'de Çarlık Rusyası'nın himayesine giren emirlik, iç işlerinde serbest kaldı. 2 Eylül 1920'de General Frunze komutasındaki Kızıl Ordu Buhara'yı uçaklarla bombalayarak son emir Seyyid Âlim Han'ı Afganistan'a kaçırdı ve devlete son verdi."], "sources": [{"title": "TDV İslâm Ansiklopedisi, BUHARA HANLIĞI", "url": "https://islamansiklopedisi.org.tr/buhara-hanligi"}, {"title": "TDV İslâm Ansiklopedisi, ŞEYBÂNÎ HAN", "url": "https://islamansiklopedisi.org.tr/seybani-han"}], "rulers": [{"id": "buhara-hanligi-seybani-han", "name": "Muhammed Şeybânî Han", "aliases": ["Şibani Han", "Şâhibek Han"], "title": "Han / Şâhibek", "birth": 1451, "birthNote": "1451 doğumlu", "death": 1510, "deathNote": "Merv Meydan Muharebesi'nde Şah İsmail'e karşı şehit düştü", "reign": [1500, 1510], "reignNote": "10 yıllık büyük fütuhat saltanatı.", "summary": "Hanlığın kurucusu. Timurluları Maveraünnehir'den sürdü, Bâbür'ü Semerkant'ta mağlup etti; Hârizm ve Horasan'ı fethetti. Türkçe divanı olan şair ve fakih bir hükümdardı. 1510 Merv savaşında Şah İsmail tarafından öldürüldü.", "traits": ["Fatih", "Âlim hükümdar", "Şair"], "contribution": "Maveraünnehir'de 4 asır sürecek Özbek hanlıkları düzenini kurdu.", "harm": "Şah İsmail'e karşı tedbirsizce kuşatmadan çıkıp pusuya düşmesi canına ve Horasan'ın kaybına mal oldu.", "wives": [], "children": [{"name": "Muhammed Temür Sultan", "mother": "", "note": "Şehzade", "certainty": "kesin"}], "wars": [{"name": "Sar-ı Pul Muharebesi", "when": "1501", "foe": "Bâbür Şah", "result": "zafer", "note": "Bâbür mağlup edildi, Semerkant kesin olarak zaptedildi."}, {"name": "Merv Meydan Muharebesi", "when": "1510", "foe": "Safevî Devleti (Şah İsmail)", "result": "yenilgi", "note": "Kızılbaş ordusunun sahte ricat tuzağına düştü, bataklıkta öldürüldü."}], "legends": ["Şah İsmail'in onun kafatasını altınla kaplatıp kadeh olarak kullandığı tarihi kaynaklarda zikredilir."], "sources": [{"title": "TDV İslâm Ansiklopedisi, ŞEYBÂNÎ HAN", "url": "https://islamansiklopedisi.org.tr/seybani-han"}]}]}, {"id": "hive-hanligi", "name": "Hive Hanlığı", "short": "Hive Hanlığı", "aliases": ["Hârizm Hanlığı", "Yadigâr Şibanîleri"], "region": "turkistan", "start": 1511, "end": 1920, "startNote": "İlbars Han'ın Safevî garnizonunu kovarak Hive merkezli bağımsız hanlık kurmasıyla başladı.", "endNote": "1920'de Bolşevik Kızıl Ordu tarafından son han İsfendiyar'ın devrilmesiyle Harezm Sovyet Cumhuriyeti'ne çevrildi.", "capital": "Vezir, Ürgenç ve Hive", "religion": "İslamiyet (Sünnî-Hanefî)", "confidence": "kayit", "confidenceNote": "Ebulgazi Bahadır Han (Şecere-i Terâkime / Şecere-i Türkî) ve Münis ile Âgehî kronikleriyle sabittir.", "summary": "Aral gölü güneyindeki tarihi Hârizm havzasında Cengiz soyundan İlbars Han tarafından kurulan Türkmen ve Özbek devleti. Safevî yayılmasına karşı vatanlarını korudular. Ebulgazi Bahadır Han devrinde Türk boylarının şecerelerini ve Oğuznâme rivayetlerini toplayan 'Şecere-i Terâkime' ve 'Şecere-i Türkî' gibi ölümsüz tarih eserleri yazıldı. İçan Kale mimari kompleksi bugün UNESCO Dünya Mirası olarak ayaktadır. 1920'de Kızıl Ordu tarafından yıkıldı.", "legacy": "Hive İçan Kale açık hava müze kentini günümüze ulaştırdı; Ebulgazi Bahadır Han'ın eserleriyle Türk boylarının tarihini ve soy kütüğünü aydınlattı.", "essay": ["Hive Hanlığı, 1511 yılında Şiban soyundan İlbars Han'ın Hârizm halkının davetiyle Safevî valilerini kılıçtan geçirerek Vezir ve Ürgenç şehirlerini almasıyla kuruldu.", "Hanlığın en bilgin hükümdarı Ebulgazi Bahadır Han (1643-1663) oldu. Rus ve Kalmuk baskılarına karşı savaştı; Türk diline aşık bir bilgin olarak Türk boylarının şecerelerini halk Türkçesiyle kaleme aldı. Eserleri Türk tarih yazıcılığının temel taşlarındandır.", "1873 yılında General Kaufmann komutasındaki Çarlık Rusyası ordularınca işgal edilerek Rus vassalı yapıldı. 1920'de Sovyet Kızıl Ordusu hanlığı tamamen ortadan kaldırdı."], "sources": [{"title": "TDV İslâm Ansiklopedisi, HİVE HANLIĞI", "url": "https://islamansiklopedisi.org.tr/hive-hanligi"}, {"title": "TDV İslâm Ansiklopedisi, EBULGAZİ BAHADIR HAN", "url": "https://islamansiklopedisi.org.tr/ebulgazi-bahadir-han"}], "rulers": [{"id": "hive-hanligi-ebulgazi", "name": "Ebulgazi Bahadır Han", "aliases": ["Ebülfeyz Bahadır Han", "Ebülgazi Han"], "title": "Han / Müverrih", "birth": 1603, "birthNote": "1603'te Ürgenç'te doğdu", "death": 1663, "deathNote": "Hive'de vefat etti", "reign": [1643, 1663], "reignNote": "20 yıllık ilim ve gazâ saltanatı.", "summary": "Hive Hanı ve büyük Türk tarihçisi. Kalmuklar ve Ruslarla savaştı. Türkmen boylarının tarihini 'Şecere-i Terâkime', Türk hanedanlarını 'Şecere-i Türkî' adlı eserlerinde sade ve akıcı bir Türkçeyle yazarak dünya Türkolojisine en kıymetli hazineleri bıraktı.", "traits": ["Müverrih han", "Türkçe aşığı", "Cengaver"], "contribution": "Türk boylarının tarih ve şecere hafızasını kayıt altına aldı; Hive'yi imar etti.", "harm": "Türkmen boylarına karşı zaman zaman sert tenkil hareketlerine girişti.", "wives": [], "children": [{"name": "Enûşe Han", "mother": "", "note": "Babasının eserini tamamlayan halef", "certainty": "kesin"}], "wars": [{"name": "Kalmuk Seferleri", "when": "1646-1655", "foe": "Kalmuk (Oyrat) istilacıları", "result": "zafer", "note": "Bozkırdan gelen Kalmuk yağmaları püskürtüldü."}], "legends": ["Kitabının önsözünde 'Bu kitabı Türk, Tacik herkes anlasın diye açık ve arı bir Türk diliyle yazdım, tek bir Farsça veya Arapça lügate ihtiyaç duyulmasın istedim' demesi milli dil bilincinin zirvesidir."], "sources": [{"title": "TDV İslâm Ansiklopedisi, EBULGAZİ BAHADIR HAN", "url": "https://islamansiklopedisi.org.tr/ebulgazi-bahadir-han"}]}]}, {"id": "babur-imparatorlugu", "name": "Bâbür İmparatorluğu", "short": "Bâbürlüler (Hint Türk Devleti)", "aliases": ["Gürgâniyye", "Mughal Empire", "Bâbür Devleti"], "region": "turkistan", "start": 1526, "end": 1857, "startNote": "Bâbür Şah'ın 1526 Panipat Meydan Muharebesi'nde İbrâhim Lûdî'yi yenerek Delhi tahtına oturmasıyla kuruldu.", "endNote": "1857 Sipahi İsyanı sonrası İngilizlerin son imparator II. Bahadır Şah'ı Rangun'a sürmesiyle sona erdi.", "capital": "Agra, Delhi ve Lahor", "religion": "İslamiyet (Sünnî-Hanefî)", "confidence": "kayit", "confidenceNote": "Bâbürnâme, Ebü'l-Fazl el-Allâmî (Âyin-i Ekberî / Ekbernâme) ve resmi vakayinâmelerle sabittir.", "summary": "Timur'un torunlarından Zahîrüddin Muhammed Bâbür tarafından Hindistan'da kurulan, 330 yılı aşkın süre Hint alt kıtasını yöneten muazzam cihan devleti. Bâbür Şah dünya otobiyografi şaheseri Bâbürnâme'yi Türkçe kaleme aldı. Ekber Şah imparatorluğu kıtasal güce ulaştırdı; Şah Cihan eşi Mümtaz Mahal için mimarlık tarihinin zirvesi Tac Mahal'i inşa ettirdi; Evrengzib devrinde Hindistan'ın tamamına hükmedildi. 1857'de İngiliz sömürgeciliği tarafından yıkıldı.", "legacy": "Dünyanın 7 harikasından biri kabul edilen Tac Mahal'i, Delhi Kızıl Kale'yi, Lahor Şâlimâr Bahçeleri'ni ve Bâbürnâme'yi insanlığa armağan etti.", "essay": ["Bâbür İmparatorluğu, Fergana vadisinde tahtını kaybeden Timur soyundan Zahîrüddin Muhammed Bâbür'ün yılmayan iradesiyle doğdu. Önce Kabil'i fetheden Bâbür, 21 Nisan 1526'da Panipat Meydan Muharebesi'nde yüz bin kişilik ve savaş filleriyle donatılmış Delhi Sultanı İbrâhim Lûdî'nin ordusunu Osmanlı tarzı top ve tüfek taktiğiyle imha ederek Delhi ve Agra'ya hakim oldu.", "Bâbür'ün torunu Ekber Şah (1556-1605), Racput prensleriyle akrabalıklar kurarak imparatorluğu merkezileştirdi. Cihangir ve ardından Şah Cihan (1628-1658) devirleri Türk-İslam mimarisinin Hindistan'daki zirvesi oldu. Şah Cihan, 14. çocuğunu doğururken vefat eden eşi Ercümend Bânû Begüm (Mümtaz Mahal) için Agra'da beyaz mermerden bir aşk ve zarafet abidesi olan Tac Mahal'i inşa ettirdi.", "Evrengzib (1658-1707) devrinde imparatorluk tüm Hindistan ve Afganistan'ı kapsayarak 150 milyonu aşan nüfusuyla dünyanın en kalabalık ve zengin devleti oldu; Fetâvâ-yı Hindiyye derlendi. Ancak Evrengzib sonrası taht kavgaları ve İngiliz Doğu Hindistan Şirketi'nin sömürgeci yayılması devleti tüketti. 1857 Bağımsızlık İsyanı'nın ardından İngilizler son hükümdar şair II. Bahadır Şah'ı Burma'ya sürgüne göndererek hanedana son verdi."], "sources": [{"title": "TDV İslâm Ansiklopedisi, BÂBÜRLÜLER", "url": "https://islamansiklopedisi.org.tr/baburluler"}, {"title": "TDV İslâm Ansiklopedisi, BÂBÜR", "url": "https://islamansiklopedisi.org.tr/babur"}, {"title": "TDV İslâm Ansiklopedisi, TAC MAHAL", "url": "https://islamansiklopedisi.org.tr/tac-mahal"}], "rulers": [{"id": "babur-imparatorlugu-babur", "name": "Bâbür Şah", "aliases": ["Zahîrüddin Muhammed Bâbür"], "title": "Padişah / Şehinşah", "birth": 1483, "birthNote": "1483'te Fergana'da Andican'da doğdu", "death": 1530, "deathNote": "Agra'da vefat etti, vasiyeti üzerine Kabil'deki Bâbür Bahçesi'ne defnedildi", "reign": [1526, 1530], "reignNote": "1526'da Panipat ile Hindistan tahtını kurdu.", "summary": "İmparatorluğun kurucusu, büyük fatih ve edebiyatçı. Fergana'dan sürülmesine rağmen Kabil'i ve ardından Hindistan'ı fethetti. Doğu Türkçesiyle yazdığı hatıratı Bâbürnâme, samimiyeti, coğrafi gözlemleri ve edebi zarafetiyle dünya edebiyatının şaheseridir.", "traits": ["Eşsiz edebiyatçı", "Askerî teşkilatçı", "Tabiat aşığı ve samimi"], "contribution": "Hindistan'da 330 yıl sürecek muazzam bir Türk imparatorluğu kurdu; Bâbürnâme'yi Türk kültürüne kazandırdı.", "harm": "Kayıtlarda belirgin bir zararı geçmez.", "wives": [{"name": "Mâhım Begüm", "note": "Hümâyun'un annesi, baş hatun", "certainty": "kesin"}], "children": [{"name": "Hümâyun", "mother": "Mâhım Begüm", "note": "İkinci imparator", "certainty": "kesin"}, {"name": "Kâmrân Mirza", "mother": "", "note": "Kabil valisi", "certainty": "kesin"}, {"name": "Gülbeden Begüm", "mother": "", "note": "Hümâyunnâme yazarı ünlü prenses", "certainty": "kesin"}], "wars": [{"name": "Panipat Meydan Muharebesi", "when": "1526", "foe": "Delhi Lûdî Sultanlığı (İbrâhim Lûdî)", "result": "zafer", "note": "Sayıca kat kat üstün Hint ordusu topçu ateşiyle bozguna uğratıldı, Delhi fethedildi."}, {"name": "Kanhua (Khanwa) Muharebesi", "when": "1527", "foe": "Racput Konfederasyonu (Rana Sanga)", "result": "zafer", "note": "Racput süvarileri imha edildi, Kuzey Hindistan hakimiyeti kesinleşti."}], "legends": ["Oğlu Hümâyun ölümcül bir hastalığa yakalandığında yatağının etrafında üç kez dönüp 'Onun canını bana ver, ona şifa ihsan eyle' diye dua ettiği ve oğlunun iyileşip kendisinin hastalanarak vefat ettiği tarihi bir fedakarlık destanıdır."], "sources": [{"title": "TDV İslâm Ansiklopedisi, BÂBÜR", "url": "https://islamansiklopedisi.org.tr/babur"}]}, {"id": "babur-imparatorlugu-sah-cihan", "name": "Şah Cihan", "aliases": ["Şihâbüddin Muhammed Şah Cihan", "Hurrem"], "title": "Padişah / Sahipkıran", "birth": 1592, "birthNote": "1592'de Lahor'da doğdu", "death": 1666, "deathNote": "Agra Kalesi'nde mahpusken Tac Mahal'e bakarak vefat etti, Tac Mahal'dedir", "reign": [1628, 1658], "reignNote": "30 yıllık mimarlık ve refah mucizesi.", "summary": "Cihangir'in oğlu. İmparatorluğu iktisadi ve mimari zirvesine taşıdı. Erken yaşta kaybettiği eşi Mümtaz Mahal için 22 yılda 20 bin işçi ve mimarla Tac Mahal'i yaptırdı; Delhi'de Cuma Camii ve Şahcihanabad'ı kurdu. Oğlu Evrengzib tarafından tahttan indirilip Agra kalesine hapsedildi.", "traits": ["Büyük mimar hükümdar", "Aşk ve sanat timsali", "Estetik deha"], "contribution": "Tac Mahal, Agra Kalesi, Delhi Moti Mescid gibi dünya harikalarını inşa ettirdi.", "harm": "Devasa inşaat projeleri devlet hazinesini tüketti; oğulları arasında kanlı taht kavgasını engelleyemedi.", "wives": [{"name": "Ercümend Bânû Begüm (Mümtaz Mahal)", "note": "Adına Tac Mahal yaptırılan efsanevi eşi", "certainty": "kesin"}], "children": [{"name": "Dârâ Şükûh", "mother": "Mümtaz Mahal", "note": "Âlim veliaht, Evrengzib tarafından katledildi", "certainty": "kesin"}, {"name": "Evrengzib (Alemgîr)", "mother": "Mümtaz Mahal", "note": "İmparatorluğu devralan oğul", "certainty": "kesin"}, {"name": "Cihanâra Begüm", "mother": "Mümtaz Mahal", "note": "Babasını hapiste yalnız bırakmayan vefakar kızı", "certainty": "kesin"}], "wars": [{"name": "Dekken Seferleri", "when": "1630-1636", "foe": "Güney Hindistan Sultanlıkları (Ahmednagar, Bicapur)", "result": "zafer", "note": "Dekken bölgesi haraca bağlandı."}], "legends": ["Ömrünün son sekiz yılını Agra Kalesi'nin zindanında pencereden Yamuna nehri kıyısındaki Tac Mahal'i seyrederek geçirdiği anlatılır."], "sources": [{"title": "TDV İslâm Ansiklopedisi, ŞAH CİHAN", "url": "https://islamansiklopedisi.org.tr/sah-cihan"}, {"title": "TDV İslâm Ansiklopedisi, TAC MAHAL", "url": "https://islamansiklopedisi.org.tr/tac-mahal"}]}]}, {"id": "hokand-hanligi", "name": "Hokand Hanlığı", "short": "Hokand Hanlığı", "aliases": ["Kokand Hanlığı", "Fergana Hanlığı", "Ming Hanedanı"], "region": "turkistan", "start": 1709, "end": 1876, "startNote": "Özbek Ming boyundan Şahruh Bey'in Fergana vadisinde bağımsızlık ilan etmesiyle kuruldu.", "endNote": "1876'da Rus Çarlığı generali Skobelev tarafından tamamen ilhak edilerek Fergana vilayeti yapıldı.", "capital": "Hokand", "religion": "İslamiyet (Sünnî-Hanefî)", "confidence": "kayit", "confidenceNote": "Târîh-i Şahruhî, Molla Âlim Mahdum (Târîh-i Türkistan) ve Rus askeri raporlarıyla sabittir.", "summary": "Bereketli Fergana vadisinde (Özbekistan, Kırgızistan, Tacikistan kavşağında) Ming boyu tarafından kurulan zengin hanlık. Âlim Han ve Ömer Han devirlerinde Taşkent, Çimkent ve Türkistan şehirlerini alarak Doğu Türkistan'a (Kaşgar) kadar nüfuz ettiler. Ömer Han ve eşi Nâdire Begüm saraylarında zengin bir edebiyat meclisi kurdular. 1876'da Rus Çarlığı tarafından kanlı bir savaşla ilhak edildi.", "legacy": "Hokand Hüdâyâr Han Sarayı'nı ve Fergana ipekçilik/dokuma zanaatını miras bıraktı; Nâdire Begüm divanıyla kadın Türk edebiyatını taçlandırdı.", "essay": ["Hokand Hanlığı, 1709 yılında Buhara hakimiyetinden ayrılan Özbek Ming boyu beyi Şahruh Bey tarafından zengin Fergana vadisinde kuruldu.", "Âlim Han (1798-1810) 'Han' unvanını alarak Taşkent'i fethetti. Halefi Ömer Han (1810-1822) ve eşi büyük şaire Nâdire Begüm dönemi hanlığın kültürel altın çağı oldu. Medreseler açıldı, kanallar kazıldı.", "19. yüzyıl ortalarında Çarlık Rusyası'nın güneye inmesiyle General Çernyayev ve Skobelev komutasındaki Rus orduları Taşkent'i (1865) ve ardından Hokand'ı kuşattı. Polat Han'ın halk direnişine rağmen 1876'da hanlık resmen lağvedildi ve toprakları Rus Fergana Valiliği yapıldı."], "sources": [{"title": "TDV İslâm Ansiklopedisi, HOKAND HANLIĞI", "url": "https://islamansiklopedisi.org.tr/hokand-hanligi"}], "rulers": [{"id": "hokand-hanligi-omer-han", "name": "Muhammed Ömer Han", "aliases": ["Ömer Han", "Emîrü'l-Müslimîn"], "title": "Han / Emîrü'l-Müslimîn", "birth": 1787, "birthNote": "1787'de doğdu", "death": 1822, "deathNote": "Hokand'da vefat etti", "reign": [1810, 1822], "reignNote": "12 yıllık altın dönem.", "summary": "Hokand Hanlığı'nın en sevilen hükümdarı. Sınırları Seyhun boylarına genişletti. Kendisi 'Emîrî' mahlasıyla Türkçe ve Farsça divanlar yazdı; eşi Nâdire Begüm ile birlikte Hokand'ı bir şiir ve sanat başkenti yaptı.", "traits": ["Şair hükümdar", "Halk dostu", "İmar hamisi"], "contribution": "Hokand'da büyük medreseler ve kanallar açtırdı; Fergana edebiyat meclislerini kurdu.", "harm": "Kayıtlarda belirgin bir zararı geçmez.", "wives": [{"name": "Mâhlar Âyim (Nâdire Begüm)", "note": "Ünlü Türk şairesi ve naibe hatun", "certainty": "kesin"}], "children": [{"name": "Muhammed Ali Han (Madali)", "mother": "Nâdire Begüm", "note": "Babasından sonra han oldu", "certainty": "kesin"}], "wars": [{"name": "Türkistan Şehri Fethi", "when": "1814", "foe": "Kazak cüzleri", "result": "zafer", "note": "Hoca Ahmed Yesevî türbesinin bulunduğu Türkistan şehri hanlığa bağlandı."}], "legends": [], "sources": [{"title": "TDV İslâm Ansiklopedisi, HOKAND HANLIĞI", "url": "https://islamansiklopedisi.org.tr/hokand-hanligi"}]}]}, {"id": "avrupa-hun", "name": "Avrupa Hunları", "short": "İdil'i aşıp IV-V. yüzyılda Orta Avrupa'da kurulan bozkır birliği", "aliases": ["Batı Hunları", "Hun İmparatorluğu"], "region": "bati", "start": 375, "end": 469, "startNote": "İdil'i aşma TDV'de 374-375; Britannica güneydoğu Avrupa'ya girişi yaklaşık 370 diye yazar.", "endNote": "TDV İdil maddesi Batı Hun aralığını 374-469 verir. Britannica 455 Nedao'dan sonra siyasî rollerinin bittiğini, Dengizik'in 468'de öldüğünü TDV kaydeder.", "capital": "Sabit şehir adı kayıtlarda yok; merkez 400 civarında Orta Avrupa'ya kaydı", "religion": "Açılan sayfalarda resmî bir din adı yok", "confidence": "tartismali", "confidenceNote": "TDV bu birliği Asya Hunlarının batıdaki devamı ve Türk sayar. Britannica Avrupa Hunları ile Çin kayıtlarındaki Hiung-nu ilişkisini belirsiz bırakır; Eftalitler de bazen Hun diye anılır ama bağları ayrı bir sorudur.", "summary": "IV. yüzyılın sonlarında İdil ötesinden gelen atlı birlik önce Alanları, ardından Ostrogotları sürdükten sonra Tuna sınırına dayandı. V. yüzyılda Rua, sonra Attila ve Bleda döneminde Doğu Roma vergiye bağlandı. Attila'nın 453'teki ölümünden sonra oğullar arasındaki çekişme ve bağlı Germen grupların isyanı birliği dağıttı.", "legacy": "Kavimler göçünü hızlandırdı. Dil ve soy bağı az ve tartışmalı izlere dayanır; Avrupa'da ayrı bir Hun halkı olarak VI. yüzyıla kalmadılar.", "sources": [{"title": "TDV İslâm Ansiklopedisi, TÜRK", "url": "https://islamansiklopedisi.org.tr/turk"}, {"title": "TDV İslâm Ansiklopedisi, İDİL BULGAR HANLIĞI", "url": "https://islamansiklopedisi.org.tr/idil-bulgar-hanligi"}, {"title": "Britannica, Hun", "url": "https://www.britannica.com/topic/Hun-people"}], "rulers": [{"id": "avrupa-hun-balamir", "name": "Balamir", "title": "başbuğ", "birth": null, "birthNote": "kayıtlarda yok", "death": null, "deathNote": "kayıtlarda yok", "reign": [374, null], "reignNote": "TDV onu 370'lerde İdil boyunun başı diye yazar. Ammianus'a dayanan Britannica, IV. yüzyılda Hunların tek kralı olup olmadığını tartışmalı sayar.", "summary": "TDV'ye göre 374-375'te İdil'i aşıp Alanları ve Ostrogotları batıya süren önderdir. Adı çağdaş Roma tasvirinde geçmez.", "traits": [], "contribution": "TDV anlatısında Avrupa'ya geçiş onun adıyla başlar.", "harm": "", "wives": [], "children": [], "wars": [{"name": "Alan ve Ostrogot seferi", "when": "374-375", "foe": "Alanlar, Ostrogotlar", "result": "zafer", "note": "TDV; tek komutan olarak Balamir tartışmalıdır."}], "legends": ["Balamir'in bütün Hunların kralı olduğu sonraki anlatılardan gelir; IV. yüzyılda tek hükümdar olup olmadığı kayıtlarda çözülmüş değildir."], "sources": [{"title": "TDV İslâm Ansiklopedisi, TÜRK", "url": "https://islamansiklopedisi.org.tr/turk"}, {"title": "Britannica, Hun", "url": "https://www.britannica.com/topic/Hun-people"}]}, {"id": "avrupa-hun-rua", "name": "Rua", "title": "kral", "birth": null, "birthNote": "kayıtlarda yok", "death": 434, "deathNote": "TDV ölümü 433, Britannica 434 diye yazar.", "reign": [432, 434], "reignNote": "Britannica'ya göre 432'de dağınık Hun grupları tek kral altında toplandı. Rugila diye de anılır.", "summary": "Orta Tuna ve Tisa havzasını tutan, çeşitli Germen ve Slav gruplarını bağlayan hükümdar. Ölünce yerini kardeşi Muncuk'un oğulları Attila ve Bleda aldı.", "traits": [], "contribution": "Hun liderliğini tek elde topladığı kaydedilir.", "harm": "", "wives": [], "children": [], "wars": [], "legends": [], "sources": [{"title": "TDV İslâm Ansiklopedisi, TÜRK", "url": "https://islamansiklopedisi.org.tr/turk"}, {"title": "Britannica, Hun", "url": "https://www.britannica.com/topic/Hun-people"}]}, {"id": "avrupa-hun-bleda", "name": "Bleda", "title": "kral", "birth": null, "birthNote": "kayıtlarda yok", "death": 445, "deathNote": "TDV yalnızca öldüğünü yazar. Britannica Attila'nın kardeşini öldürdüğünü söyler.", "reign": [434, 445], "reignNote": "Attila ile ortak saltanat. Britannica Bleda'yı ağabey diye anar.", "summary": "Rua'nın yeğeni. Yaklaşık on bir yıl Attila ile birlikte hüküm sürdü. 445'te öldü; ölüm şekli kaynaklarda ayrılır.", "traits": [], "contribution": "", "harm": "", "wives": [], "children": [], "wars": [{"name": "Margus antlaşması", "when": "434", "foe": "Doğu Roma", "result": "antlasma", "note": "Ortak hükümdarlıkta yapıldı. Roma, Hunlara ödediği desteği iki katına çıkarmayı kabul etti."}], "legends": [], "sources": [{"title": "TDV İslâm Ansiklopedisi, TÜRK", "url": "https://islamansiklopedisi.org.tr/turk"}, {"title": "Britannica, Hun", "url": "https://www.britannica.com/topic/Hun-people"}]}, {"id": "avrupa-hun-attila", "name": "Attila", "title": "kral", "birth": null, "birthNote": "kayıtlarda yok", "death": 453, "deathNote": "TDV ve Britannica aynı yılı verir; ölüm biçimi açılan sayfalarda anlatılmaz.", "reign": [434, 453], "reignNote": "434-445 Bleda ile ortak, 445'ten sonra tek başına. Babası TDV'ye göre Muncuk'tur.", "summary": "Doğu Roma'dan yıllık vergi alan, Balkanlar'ı ve sonra Galya ile Kuzey İtalya'yı zorlayan hükümdar. TDV, doğuda Aral'dan batıda Ren'e kadar çok sayıda topluluğun bağlandığını yazar. 453'te ölünce birlik dağılmaya başladı.", "traits": [], "contribution": "Doğu Roma'yı ağır bir vergiye bağladı.", "harm": "447 Balkan seferinde kentler tahrip edildi. 451'de Galya yağmalandı.", "wives": [], "children": [{"name": "İlek", "mother": "", "note": "TDV'ye göre Attila'nın yerine geçen oğul", "certainty": "olasi"}, {"name": "Dengizik", "mother": "", "note": "TDV'ye göre oğul", "certainty": "olasi"}, {"name": "İrnek", "mother": "", "note": "TDV'ye göre küçük oğul; İdil maddesinde İrne diye de geçer", "certainty": "olasi"}], "wars": [{"name": "Tuna sınırı seferi", "when": "441", "foe": "Doğu Roma", "result": "zafer", "note": "Margus'ta kararlaştırılan ödeme gelmeyince açıldı. Ordu Konstantinopolis yakınına indi."}, {"name": "Balkan seferi", "when": "447", "foe": "Doğu Roma imparatoru II. Theodosios", "result": "zafer", "note": "TDV: 6000 libre altın tazminat ve 2100 libre yıllık vergiyle barış. Sofya, Filibe, Preslav, Lüleburgaz ve Büyükçekmece hattı anılır."}, {"name": "Theodosios barışı", "when": "447", "foe": "Doğu Roma", "result": "antlasma", "note": "Aynı seferin sonu."}, {"name": "Campus Mauriacus (Katalaun ovaları)", "when": "451", "foe": "Batı Roma kumandanı Aetius ve Vizigotlar", "result": "belirsiz", "note": "TDV iki tarafın da çekildiğini, Britannica Attila'nın yenildiğini yazar. Bu onun kayıtlardaki tek bozgunu sayılır."}, {"name": "İtalya seferi", "when": "452", "foe": "Batı Roma", "result": "belirsiz", "note": "Kuzey İtalya yağmalandı. TDV dönüşü Papa Leon'un ricasına bağlar; Britannica kıtlık ve salgını öne çıkarır."}], "legends": ["TDV, Honoria'nın nişan yüzüğünün Batı Roma üzerinde hak iddiasına bahane edildiğini yazar.", "Papa Leon'un yalvarıp Attila'yı İtalya'dan çevirdiği anlatı TDV'de vardır; Britannica çekilmeyi kıtlık ve salgınla açıklar."], "sources": [{"title": "TDV İslâm Ansiklopedisi, TÜRK", "url": "https://islamansiklopedisi.org.tr/turk"}, {"title": "Britannica, Hun", "url": "https://www.britannica.com/topic/Hun-people"}]}, {"id": "avrupa-hun-ilek", "name": "İlek", "title": "kral", "birth": null, "birthNote": "kayıtlarda yok", "death": 455, "deathNote": "TDV, Gepid kralıyla savaşta öldüğünü yazar, yıl vermez. Britannica Hunların 455'te Nedao'da bozulduğunu söyler, komutan adı vermez. Yıl bu iki kaydın yan yana konmasıdır.", "reign": [453, 455], "reignNote": "Attila'nın yerine geçti. Kardeşleriyle taht kavgası TDV'de dağılmanın sebebi sayılır.", "summary": "Attila'nın oğlu. Kısa saltanatı Germen isyanları ve kardeş çekişmesi içinde kapandı.", "traits": [], "contribution": "", "harm": "", "wives": [], "children": [], "wars": [{"name": "Nedao", "when": "455", "foe": "Gepidler, Ostrogotlar, Heruller", "result": "yenilgi", "note": "Irmak adı Britannica'da geçer ve yeri belirsizdir. TDV yalnızca Gepid kralıyla savaşı anar."}], "legends": [], "sources": [{"title": "TDV İslâm Ansiklopedisi, TÜRK", "url": "https://islamansiklopedisi.org.tr/turk"}, {"title": "Britannica, Hun", "url": "https://www.britannica.com/topic/Hun-people"}]}, {"id": "avrupa-hun-dengizik", "name": "Dengizik", "title": "kral", "birth": null, "birthNote": "kayıtlarda yok", "death": 468, "deathNote": "TDV: Bizans'a yenildi, esir düştü, İstanbul'da idam edildi.", "reign": [null, 468], "reignNote": "Başlangıç yılı kayıtlarda yok.", "summary": "Attila'nın oğlu. Birliğin dağılmasından sonra Bizans sınırında tutunamadı.", "traits": [], "contribution": "", "harm": "", "wives": [], "children": [], "wars": [{"name": "Bizans seferi", "when": "468", "foe": "Bizans", "result": "yenilgi", "note": "Esir edilip idam edildi."}], "legends": [], "sources": [{"title": "TDV İslâm Ansiklopedisi, TÜRK", "url": "https://islamansiklopedisi.org.tr/turk"}]}, {"id": "avrupa-hun-irnek", "name": "İrnek", "title": "başbuğ", "birth": null, "birthNote": "kayıtlarda yok", "death": null, "deathNote": "kayıtlarda yok", "reign": [null, null], "reignNote": "Yıl yok. TDV İdil maddesinde İrne diye anılır.", "summary": "Attila'nın küçük oğlu. TDV, kendine bağlı gruplarla Karadeniz kuzeyine döndüğünü ve oradaki Ogurlarla karışıp Bulgar adının bu karışımdan çıktığını yazar. Bu soy bağı bir yorumdur.", "traits": [], "contribution": "", "harm": "", "wives": [], "children": [], "wars": [], "legends": ["İrnek'in Bulgarların atası sayılması TDV'nin etnogenez anlatısıdır; kişi olarak ayrıca belgelenmiş bir saltanatı yoktur."], "sources": [{"title": "TDV İslâm Ansiklopedisi, TÜRK", "url": "https://islamansiklopedisi.org.tr/turk"}, {"title": "TDV İslâm Ansiklopedisi, İDİL BULGAR HANLIĞI", "url": "https://islamansiklopedisi.org.tr/idil-bulgar-hanligi"}]}]}, {"id": "avar-kaganligi", "name": "Avar Kağanlığı", "short": "Karpat havzasında 567'den VIII. yüzyıl sonuna kadar süren kağanlık", "aliases": ["Avar Hakanlığı", "Panonya Avarları"], "region": "bati", "start": 567, "end": 805, "startNote": "557-558'de Azak ve Bizans sınırı, 567'de Gepidlerin yenilmesi, 568'de Longobardların İtalya'ya çekilmesiyle havza Avarlarda kaldı.", "endNote": "Frank seferleri 791, 795 ve 796. TDV ve Britannica siyasî teslimiyeti 805'e koyar. Vikipedi Frank sarayında Avar elçisini 822'ye kadar anar.", "capital": "Tuna ile Tisa arası; şehir adı kayıtlarda yok", "religion": "Bozkır inancı; dağılmayla birlikte Hıristiyanlaşma", "confidence": "tartismali", "confidenceNote": "Köken tartışmalıdır. TDV, Juan-juanlarla ilgisi olmadığını ve Uar-Hun kolu olduklarını yazar. Britannica Moğolistan çıkışını muhtemel sayar. Göktürkler onları Varchonit ve kaçak kul diye anmaktaydı. Yeni arkeogenetik çalışmalar elit çekirdekte İç Asya ve Rouran ihtimalini güçlendirir; bütün nüfusun Rouran olduğu kanıtlanmış değildir. TDV'nin AVARLAR maddesindeki Dağıstan Avarları ayrı bir halktır.", "summary": "Göktürk genişlemesi önünden batıya gelen ve Bizans'ın Avar dediği birlik, 567'de Longobardlarla Gepidleri yenip Karpat havzasını tuttu. Bayan döneminde Tuna-Tisa merkez oldu. 626 İstanbul kuşatması başarısız kalınca nüfuz kırıldı. VIII. yüzyıl sonunda Frank seferleri kağanlığı parçaladı.", "legacy": "Slav gruplarının Balkanlar'a inmesinde payları oldu. Kağan unvanı Avrupa kaynaklarına bu yolla geçti. Siyasî yapı 805'ten sonra eridi.", "sources": [{"title": "TDV İslâm Ansiklopedisi, TÜRK", "url": "https://islamansiklopedisi.org.tr/turk"}, {"title": "TDV İslâm Ansiklopedisi, MACARİSTAN", "url": "https://islamansiklopedisi.org.tr/macaristan"}, {"title": "Britannica, Avar", "url": "https://www.britannica.com/topic/Avar"}, {"title": "Wikipedia, Pannonian Avars", "url": "https://en.wikipedia.org/wiki/Pannonian_Avars"}], "rulers": [{"id": "avar-bayan", "name": "Bayan", "title": "kağan", "birth": null, "birthNote": "kayıtlarda yok", "death": 602, "deathNote": "Vikipedi 602 der; maddenin savaş bölümü kaynak göstermez. TDV ölüm yılı vermez.", "reign": [562, 602], "reignNote": "Vikipedi ilk kağanlığı 562-602 diye yazar ve atıfı zayıftır. TDV yalnızca en güçlü dönemin Bayan zamanı olduğunu söyler. 626 kuşatması ona bağlanamaz.", "summary": "Avarların en güçlü kağanı diye anılır. Merkezi Tuna-Tisa arasına aldı. TDV sınırları Dinyeper'den Elbe'ye, Adriyatik'ten Kuzey Denizi kıyılarına kadar genişlettiğini yazar; bu uçlar abartılı olabilir.", "traits": [], "contribution": "Kağanlığın Karpat havzasındaki çekirdeğini kurdu.", "harm": "Bizans sınır kentlerine ve Frank topraklarına akınlar açtı.", "wives": [], "children": [], "wars": [{"name": "Gepid savaşı", "when": "567", "foe": "Gepid kralı Cunimund", "result": "zafer", "note": "Longobardlarla birlikte. TDV Macaristan 567 Longobard-Avar ittifakını yazar."}, {"name": "Sigebert seferleri", "when": "562 ve 566", "foe": "Frank kralı I. Sigebert", "result": "belirsiz", "note": "Vikipedi 562'de yenilgi, 566'da galibiyet der. TDV Frankları yendiklerini kaydeder, yıl vermez."}], "legends": ["Vikipedi, Bayan'ın Cunimund'un kafatasından kadeh yaptırıp Alboin'e verdiğini yazar. Anlatı Longobard geleneğindendir; TDV'de yoktur."], "sources": [{"title": "TDV İslâm Ansiklopedisi, TÜRK", "url": "https://islamansiklopedisi.org.tr/turk"}, {"title": "Wikipedia, Bayan I", "url": "https://en.wikipedia.org/wiki/Bayan_I"}]}, {"id": "avar-kagan-adi-yok", "name": "kayıtlarda adı geçmiyor", "title": "kağan", "birth": null, "birthNote": "kayıtlarda adı geçmiyor", "death": null, "deathNote": "kayıtlarda adı geçmiyor", "reign": [null, 805], "reignNote": "626 ve Frank savaşlarının kağan adı açılan sayfalarda yok. 630'da kağanın zamansız öldüğü TDV'de geçer, adı verilmez.", "summary": "Bayan'dan sonraki kağanların kişisel adları bu turda açılan sayfalarda güvenilir biçimde yok. 626 başarısızlığı ve 630 Bulgar isyanı nüfuzu düşürdü. Frank seferleri 805'te siyasî varlığı kapattı.", "traits": [], "contribution": "", "harm": "", "wives": [], "children": [], "wars": [{"name": "İstanbul kuşatması", "when": "626", "foe": "Bizans; Sâsânîler müttefik", "result": "yenilgi", "note": "Şehir alınamadı. TDV, Avar emrindeki Slavların isyanını ve donanma yokluğunu yazar. Britannica kuşatmanın şehre yaklaştığını söyler."}, {"name": "Frank seferleri", "when": "791-805", "foe": "Charlemagne (Büyük Charles)", "result": "yenilgi", "note": "791, 795, 796 seferleri. Teslimiyet TDV ve Britannica'da 805."}], "legends": ["Göktürklerin 'sahte Avar' demesi bir hakaret ve siyaset dili olarak da okunur; gerçek adın Var ve Chunni olduğu tezi Theophylaktos'a dayanır ve tartışmalıdır."], "sources": [{"title": "TDV İslâm Ansiklopedisi, TÜRK", "url": "https://islamansiklopedisi.org.tr/turk"}, {"title": "Britannica, Avar", "url": "https://www.britannica.com/topic/Avar"}, {"title": "Wikipedia, Pannonian Avars", "url": "https://en.wikipedia.org/wiki/Pannonian_Avars"}]}]}, {"id": "buyuk-bulgarya", "name": "Büyük Bulgarya", "short": "Kubrat'ın Karadeniz kuzeyinde kurduğu kısa ömürlü Bulgar birliği", "aliases": ["Magna Bulgaria", "Büyük Bulgar Devleti", "Patria Onoguria"], "region": "bati", "start": 630, "end": 665, "startNote": "TDV bağımsızlığı 630'a, Britannica Avarlara isyanı 635'e koyar. Britannica saltanat başlangıcını yaklaşık 605, TDV Bulgar maddesi 584 diye de yazar.", "endNote": "Kurucunun ölümü TDV İdil ve Türk maddelerinde 665, TDV Bulgar ve Britannica'da yaklaşık 642, TDV Bulgaristan'da 650'lerdedir. Dağılma Hazar baskısıyladır.", "capital": "Sabit şehir adı kayıtlarda yok; güney sınır Kuban", "religion": "Açılan sayfalarda resmî din adı yok", "confidence": "tartismali", "confidenceNote": "Birliğin varlığı Bizans kayıtlarına dayanır. Kurucunun adı Kurt, Kobrat, Kubrat, Kuvrat biçimlerinde gelir. Ölüm yılı üç ayrı TDV maddesinde uyuşmaz. Doulo sülalesinin Asya Hun T'u-ko hanedanına bağlanması TDV'de bir iddiadır, kanıtlanmış soy değildir. Bulgarların Türk mü, İranî unsurlu mu olduğu Britannica'da açık bırakılır.", "summary": "Ogur ve Kutrigur-Utrigur Bulgarları, Avar ve Göktürk baskısı zayıflayınca Kubrat altında Kuban-Azak-Karadeniz kuzeyinde toplandı. TDV Bulgaristan batı sınırını Dinyeper, doğuyu İdil, güneyi Kuban diye çizer. Kurucu ölünce oğullar dağıldı; bir kol Hazarlara kaldı, biri Tuna'ya, biri Orta İdil'e gitti.", "legacy": "Tuna Bulgar Devleti ile İdil Bulgarlarının ortak çıkış noktası sayılır. Kendisi bir kuşak sürdü.", "sources": [{"title": "TDV İslâm Ansiklopedisi, TÜRK", "url": "https://islamansiklopedisi.org.tr/turk"}, {"title": "TDV İslâm Ansiklopedisi, İDİL BULGAR HANLIĞI", "url": "https://islamansiklopedisi.org.tr/idil-bulgar-hanligi"}, {"title": "TDV İslâm Ansiklopedisi, BULGAR", "url": "https://islamansiklopedisi.org.tr/bulgar"}, {"title": "TDV İslâm Ansiklopedisi, BULGARİSTAN", "url": "https://islamansiklopedisi.org.tr/bulgaristan"}, {"title": "Britannica, Bulgar", "url": "https://www.britannica.com/topic/Bulgar"}], "rulers": [{"id": "buyuk-bulgarya-kubrat", "name": "Kubrat", "title": "han", "birth": null, "birthNote": "kayıtlarda yok", "death": null, "deathNote": "TDV İdil ve Türk 665; TDV Bulgar ile Britannica yaklaşık 642; TDV Bulgaristan 650'ler. Tek yıl seçilmedi.", "reign": [630, null], "reignNote": "Britannica yaklaşık 605-642 ve 635 isyanı; TDV Bulgar 584-642; TDV Türk bağımsızlık 630.", "summary": "Kurt, Kobrat, Kobratos ve Kuvrat diye de yazılır. Avar hâkimiyetini kırıp Büyük Bulgarya'yı topladı. Herakleios döneminde Bizans'la ilişki kurdu. Ölümünden sonra birlik Hazar baskısı ve oğulların ayrılmasıyla parçalandı.", "traits": [], "contribution": "Dağınık Bulgar boylarını kısa süreli tek birlik haline getirdi.", "harm": "", "wives": [], "children": [{"name": "Bat-Bayan", "mother": "", "note": "TDV: On Ogur ve Macarların başında Kafkasya'da kalarak Hazarlara tâbi oldu", "certainty": "olasi"}, {"name": "Asparuh", "mother": "", "note": "Tuna'ya giden oğul. TDV Bulgar onu küçük oğul diye anar", "certainty": "kesin"}, {"name": "Kotrag", "mother": "", "note": "Britannica kuzeye, İdil-Kama yöresine giden oğul diye yazar. TDV bu kolu adsız Otuz-Ogur kitlesi sayar", "certainty": "olasi"}], "wars": [{"name": "Avarlara isyan", "when": "635", "foe": "Avarlar", "result": "zafer", "note": "Britannica. TDV bağımsızlığı 630 Göktürk fetretine bağlar, tek muharebe adı vermez."}], "legends": ["Doulo soyunun Asya Hun T'u-ko hanedanına çıktığı TDV'de yazılır; bu bir hanedan iddiasıdır."], "sources": [{"title": "TDV İslâm Ansiklopedisi, TÜRK", "url": "https://islamansiklopedisi.org.tr/turk"}, {"title": "TDV İslâm Ansiklopedisi, BULGARİSTAN", "url": "https://islamansiklopedisi.org.tr/bulgaristan"}, {"title": "Britannica, Bulgar", "url": "https://www.britannica.com/topic/Bulgar"}]}]}, {"id": "hazar-kaganligi", "name": "Hazar Kağanlığı", "short": "VII-X. yüzyıllarda Kuzey Kafkasya, İdil ve Karadeniz kuzeyinde ticaret devleti", "aliases": ["Hazar Hakanlığı", "Hazarlar"], "region": "bati", "start": 630, "end": 969, "startNote": "Batı Göktürk bağının kopması TDV'de 630. Britannica VII. yüzyıl başında bağımsızlaştıklarını yazar.", "endNote": "Britannica Sviatoslav'ın 965 seferiyle gücün kırıldığını, TDV hakanın 965'te Hârizmlilere sığındığını ve Semender'in 968'den sonraki seferlerde harap olduğunu yazar. Vikipedi Atil'in yağmasını 969'a koyar. Hazar adı XI. yüzyıl içinde de anılır.", "capital": "Önce Belencer, Arap baskısından sonra İdil (İtil, Atil)", "religion": "Halkta Tengri inancı, İslâm ve Hıristiyanlık bir arada; yönetici zümrede Mûsevîlik", "confidence": "kayit", "confidenceNote": "Devletin varlığı kayıtlıdır. Mûsevîliğin yılı ayrılır: Yahuda Halevi 740, Mes'ûdî Hârûnürreşîd dönemi (786-809), Britannica yaklaşık 740. Kabulün derinliği belirsizdir. Hakan adlarının çoğu yoktur. Bulan ve Obadiah yalnızca Hasdai-Yûsuf mektubundadır. Böri Şad ve Bulu Han açılan TDV ve Britannica maddelerinde hakan diye geçmez. Ercan adlı bir muharebe de yoktur; 730 bozgunu Erdebil'dedir.", "summary": "Hazarlar Sabar bakiyesi ve Batı Göktürk ucu olarak Kafkasya'da sivrildi, 630'dan sonra kendi kağanlıklarını kurdu. Belencer sonra İdil, Hazar denizi-Karadeniz ticaretinin düğümü oldu. Hükümdar kutsal hakan, icra hakan beg elindeydi. Halife ordularını Kafkasya'da durdurdular; 965-969 Rus seferleri bu gücü kırdı.", "legacy": "Arap ilerleyişini Kafkasların kuzeyinde kestiler. İdil Bulgarları ve bir süre Macarlar ile Slav grupları onlara bağlı yaşadı. Yönetici din olarak Yahudilik bozkırda istisnadır. Hazarca bir metin kalmamıştır.", "sources": [{"title": "TDV İslâm Ansiklopedisi, HAZARLAR", "url": "https://islamansiklopedisi.org.tr/hazarlar"}, {"title": "Britannica, Khazar", "url": "https://www.britannica.com/topic/Khazar"}, {"title": "Wikipedia, Khazar Khaganate", "url": "https://en.wikipedia.org/wiki/Khazar_Khaganate"}], "rulers": [{"id": "hazar-hakan-adi-yok", "name": "kayıtlarda adı geçmiyor", "title": "hakan", "birth": null, "birthNote": "kayıtlarda adı geçmiyor", "death": null, "deathNote": "626 civarında Herakleios'un kızını isteyen hakan düğünden önce öldü; adı yok.", "reign": [630, null], "reignNote": "Arap savaşları döneminin hakanları TDV'de adsızdır. Bu kayıt tek kişi değil, adı geçmeyen makamdır.", "summary": "Bağımsızlığın ilk yüzyılında hakanların özel adı verilmez. Çorpan Tarhan ve As-Tarhan kumandan olarak ayrılır. Mervân seferinde hakan kısa süre İslâm'ı kabul edip sonra döndü.", "traits": [], "contribution": "Kafkas geçitlerinde halife ordularını birkaç kez durdurdular.", "harm": "", "wives": [], "children": [], "wars": [{"name": "Belencer", "when": "652-653", "foe": "Selmân b. Rebîa kumandasındaki ordu", "result": "zafer", "note": "Derbend aşıldı, başkent Belencer'e kadar gelindi. Hazarlar orduyu yendi. Ercan diye ayrı bir savaş açılan sayfalarda yok."}, {"name": "Mercülhicâre", "when": "717'den yaklaşık beş yıl sonra", "foe": "Emevî ordusu", "result": "zafer", "note": "TDV: Kıpçak ve başka Türk boylarının yardımıyla müslüman ordusu bozuldu."}, {"name": "Belencer'in düşmesi", "when": "722-723", "foe": "Cerrâh b. Abdullah el-Hakemî", "result": "yenilgi", "note": "TDV, Cerrâh'ın Tarki ve Belencer'i aldığını yazar. Yıl Vikipedi'nin 722-723 kaydına dayanır."}, {"name": "Erdebil", "when": "730", "foe": "Cerrâh b. Abdullah", "result": "zafer", "note": "Cerrâh Azerbaycan'a çekilerek yenildi. Vikipedi komutanı Barjik diye anar; TDV ad vermez. Ercan bu savaşın adı değildir."}, {"name": "Mervân'ın İdil seferi", "when": "732 valiliğinden sonra; Vikipedi 737", "foe": "Mervân b. Muhammed", "result": "yenilgi", "note": "Belencer alındı, ordu İdil'e vardı. Hakanın gönderdiği ordu yenildi."}, {"name": "Mervân barışı", "when": "aynı seferin sonu", "foe": "Mervân b. Muhammed", "result": "antlasma", "note": "İslâm'ı kabul şartıyla barış. İdil'de iki fakih bırakıldı. Hakan kısa süre sonra eski dinine döndü."}], "legends": ["Bulu Han ve Böri Şad bağlantısı açılan TDV ve Britannica maddelerinde kurulmaz.", "Hakanın saltanat süresini boğularak seçtiği ve süre dolunca öldürüldüğü anlatı İbn Fadlân çizgisindedir; her hakan için doğrulanmış bir olay değildir."], "sources": [{"title": "TDV İslâm Ansiklopedisi, HAZARLAR", "url": "https://islamansiklopedisi.org.tr/hazarlar"}, {"title": "Wikipedia, Khazar Khaganate", "url": "https://en.wikipedia.org/wiki/Khazar_Khaganate"}]}, {"id": "hazar-corpan-tarhan", "name": "Çorpan Tarhan", "title": "tarhan", "birth": null, "birthNote": "kayıtlarda yok", "death": null, "deathNote": "kayıtlarda yok", "reign": [null, null], "reignNote": "VII. yüzyıl başı. Hakan olduğu yazılmaz; Sâsânîlere karşı sefer açan Hazar kumandanı diye anılır.", "summary": "Aras'a kadar Kuzey Azerbaycan'ı aldı. 629'da Tiflis zaptedildi. Başkent o sırada Belencer'di.", "traits": [], "contribution": "Hazar akınını Güney Kafkasya'ya taşıdı.", "harm": "", "wives": [], "children": [], "wars": [{"name": "Tiflis", "when": "629", "foe": "Sâsânîler", "result": "zafer", "note": "TDV zaptı Hazar seferine bağlar; Çorpan'ın bizzat Tiflis'te olduğu ayrıca belirtilmez."}], "legends": [], "sources": [{"title": "TDV İslâm Ansiklopedisi, HAZARLAR", "url": "https://islamansiklopedisi.org.tr/hazarlar"}]}, {"id": "hazar-as-tarhan", "name": "As-Tarhan", "title": "tarhan", "birth": null, "birthNote": "kayıtlarda yok", "death": null, "deathNote": "kayıtlarda yok", "reign": [null, null], "reignNote": "764 seferinin kumandanı. Hakan değildir.", "summary": "Hazar prensesinin doğumda ölmesi üzerine hakanın gönderdiği ordunun başında Tiflis'i aldı.", "traits": [], "contribution": "", "harm": "764'te Tiflis ele geçirildi.", "wives": [], "children": [], "wars": [{"name": "Tiflis seferi", "when": "764", "foe": "Abbâsîler", "result": "zafer", "note": "Yezîd b. Esîd'in Hazar hatununun ölümünden sonra."}], "legends": [], "sources": [{"title": "TDV İslâm Ansiklopedisi, HAZARLAR", "url": "https://islamansiklopedisi.org.tr/hazarlar"}]}, {"id": "hazar-bulan", "name": "Bulan", "title": "hakan", "birth": null, "birthNote": "kayıtlarda yok", "death": null, "deathNote": "kayıtlarda yok", "reign": [null, null], "reignNote": "Yalnızca Hakan Yûsuf'un mektubunda, Yahudiliğe giriş onun zamanına bağlanır. Yıl yok.", "summary": "Hasdai ben Şaprut'a cevap diye bilinen mektupta Hazarların Yahudiliğe Bulan zamanında girdiği yazılır. Olay bir rüyaya bağlanır. Mektup dışında adı doğrulanmaz.", "traits": [], "contribution": "", "harm": "", "wives": [], "children": [], "wars": [], "legends": ["Mektup, dini seçişi Bulan'ın rüyasına bağlar.", "Bulu Han biçimi ve Böri Şad ile özdeşleştirme açılan TDV ve Britannica maddelerinde yoktur."], "sources": [{"title": "TDV İslâm Ansiklopedisi, HAZARLAR", "url": "https://islamansiklopedisi.org.tr/hazarlar"}]}, {"id": "hazar-obadiah", "name": "Obadiah", "title": "hakan", "birth": null, "birthNote": "kayıtlarda yok", "death": null, "deathNote": "kayıtlarda yok", "reign": [null, null], "reignNote": "Yine yalnızca Yûsuf mektubunda, Bulan'dan sonraki din düzenlemesi onun adına yazılır.", "summary": "Mektuba göre sinagog ve okul açtırdı; Tevrat, Mişna ve Talmud öğretimi onun zamanında yayıldı. Bağımsız bir doğrulama yoktur.", "traits": [], "contribution": "", "harm": "", "wives": [], "children": [], "wars": [], "legends": ["Obadiah'ın ıslahatı mektubun anlatısıdır; yılı ve saltanatı ayrıca kayıtlı değildir."], "sources": [{"title": "TDV İslâm Ansiklopedisi, HAZARLAR", "url": "https://islamansiklopedisi.org.tr/hazarlar"}]}, {"id": "hazar-yusuf", "name": "Yûsuf", "title": "hakan", "birth": null, "birthNote": "kayıtlarda yok", "death": null, "deathNote": "kayıtlarda yok", "reign": [950, 960], "reignNote": "Hasdai mektubu TDV'ye göre 950-960 arasında yazılmış sayılır. Bu aralık saltanatın tamamı değildir.", "summary": "Endülüs veziri Hasdai ben Şaprut ile mektuplaştığı ileri sürülen X. yüzyıl hakanı. Mektup Hazar tarihini ve Bulan'ı anlatır. Cambridge belgesi de Yûsuf ile Hârun'un Ruslara karşı direndiğini söyler.", "traits": [], "contribution": "Hazarların Yahudiliğe girişine dair başlıca yerli anlatı onun mektubuna dayanır.", "harm": "", "wives": [], "children": [], "wars": [{"name": "Sviatoslav seferi", "when": "965-969", "foe": "Kiev knezi Sviatoslav", "result": "yenilgi", "note": "965'te gücün kırılması Britannica ve TDV'de vardır. 965'teki hakanın Yûsuf olduğu kesin değildir. Semender 968'den sonra, Atil Vikipedi'ye göre 969'da yağmalandı."}], "legends": ["Mektup Hazarları Togarmah oğlu Kozar'a bağlar. Bu bir soy efsanesidir."], "sources": [{"title": "TDV İslâm Ansiklopedisi, HAZARLAR", "url": "https://islamansiklopedisi.org.tr/hazarlar"}, {"title": "Britannica, Khazar", "url": "https://www.britannica.com/topic/Khazar"}, {"title": "Wikipedia, Khazar Khaganate", "url": "https://en.wikipedia.org/wiki/Khazar_Khaganate"}]}, {"id": "hazar-harun", "name": "Hârun", "title": "hakan", "birth": null, "birthNote": "kayıtlarda yok", "death": null, "deathNote": "kayıtlarda yok", "reign": [null, null], "reignNote": "Yalnızca Cambridge belgesinde, Yûsuf ile birlikte Ruslara karşı anılır.", "summary": "Adı bilinmeyen bir Hazar Yahudisinin mektubunda Rus direnişinin hükümdarlarından biri diye geçer. Ayrı bir saltanat yılı yoktur.", "traits": [], "contribution": "", "harm": "", "wives": [], "children": [], "wars": [], "legends": [], "sources": [{"title": "TDV İslâm Ansiklopedisi, HAZARLAR", "url": "https://islamansiklopedisi.org.tr/hazarlar"}]}]}, {"id": "tuna-bulgar", "name": "Tuna Bulgar Devleti", "short": "Asparuh'tan Boris'in vaftizine kadar Türkçe han dönemi", "aliases": ["Birinci Bulgar Devleti", "Tuna Bulgar Hanlığı"], "region": "bati", "start": 681, "end": 864, "startNote": "TDV Türk, Balkanlar'a geçişi 668 ve kuruluşu 679 diye de yazar. Bizans'ın antlaşmayla tanıması 681'dir.", "endNote": "Boris'in vaftizi TDV İdil, Türk, Bulgar ve Britannica'da 864; TDV Bulgaristan 865 yazar. Devlet sürdü fakat han unvanı ve Türkçe karakter bu tarihten sonra kalktı. Simeon 893'te çar unvanını aldı.", "capital": "Pliska", "religion": "Eski Türk inancı; 864'te Ortodoks Hıristiyanlık resmî oldu", "confidence": "kayit", "confidenceNote": "Kuruluş ve 864/865 vaftizi kayıtlıdır. 718-803 arası hanların adları bu turda açılan sayfalarda dökülmediği için yazılmadı. Omurtag'ın başlangıcı 814 veya 816 diye ayrılır. Boris'in cülûsu TDV Bulgar'da 859, Bulgaristan ve Britannica'da 852'dir.", "summary": "Kubrat'ın oğlu Asparuh, Hazar baskısı üzerine Tuna'yı geçip yedi Slav boyu ve Severilerle Bizans'a karşı tutundu. 681 antlaşması vergi ve tanıma getirdi. Krum ve Omurtag döneminde sınır ve imar genişledi. Boris'in vaftiziyle hanlık Slav-Hıristiyan bir çarlığa döndü; Türkçe unvan ve dil eridi.", "legacy": "Bugünkü Bulgaristan'ın adı ve ilk devlet çekirdeği bu hanlıktandır. Yönetici Bulgarlar Slav çoğunluk içinde eridi. 864'ten sonrası bu kaydın dışındadır.", "sources": [{"title": "TDV İslâm Ansiklopedisi, BULGAR", "url": "https://islamansiklopedisi.org.tr/bulgar"}, {"title": "TDV İslâm Ansiklopedisi, BULGARİSTAN", "url": "https://islamansiklopedisi.org.tr/bulgaristan"}, {"title": "TDV İslâm Ansiklopedisi, TÜRK", "url": "https://islamansiklopedisi.org.tr/turk"}, {"title": "Britannica, Bulgar", "url": "https://www.britannica.com/topic/Bulgar"}, {"title": "Britannica, Bulgaria", "url": "https://www.britannica.com/place/Bulgaria/History"}], "rulers": [{"id": "tuna-bulgar-asparuh", "name": "Asparuh", "title": "han", "birth": null, "birthNote": "kayıtlarda yok", "death": null, "deathNote": "kayıtlarda yok", "reign": [681, null], "reignNote": "İsperih ve Esperih diye de yazılır. Tuna'yı geçiş TDV Türk'te 668. Tanınma 681.", "summary": "Kubrat'ın oğlu. Dobruca ve Tuna güneyinde Slav boylarıyla birlikte Bizans'ı antlaşmaya zorladı. Başkent Pliska oldu. Ordu ve birliğin başı Bulgar hanıydı.", "traits": [], "contribution": "Tuna Bulgar Devleti'ni Bizans'a tanıttı.", "harm": "Trakya akınında kentler tahrip edildi.", "wives": [], "children": [], "wars": [{"name": "Onglos ve Tuna savaşı", "when": "681", "foe": "Bizans imparatoru IV. Konstantinos", "result": "zafer", "note": "İstanbul kuşatması (674-678) sırasında açıldığı TDV Bulgar'da yazılır."}, {"name": "681 antlaşması", "when": "681", "foe": "Bizans", "result": "antlasma", "note": "Yıllık vergi ve devletin tanınması."}], "legends": [], "sources": [{"title": "TDV İslâm Ansiklopedisi, BULGARİSTAN", "url": "https://islamansiklopedisi.org.tr/bulgaristan"}, {"title": "TDV İslâm Ansiklopedisi, İDİL BULGAR HANLIĞI", "url": "https://islamansiklopedisi.org.tr/idil-bulgar-hanligi"}]}, {"id": "tuna-bulgar-tervel", "name": "Tervel", "title": "han", "birth": null, "birthNote": "kayıtlarda yok", "death": null, "deathNote": "kayıtlarda yok", "reign": [701, 718], "reignNote": "TDV Bulgaristan ve Britannica bu yılları verir. Asparuh'un oğlu olduğu yazılmaz.", "summary": "II. Iustinianos'un tahta dönüşüne yardım etti. Karşılığında Zagore ve imparatordan sonraki bir unvan aldı. 717'de İstanbul'u kuşatan Arap kuvvetlerine Trakya'da saldırdı.", "traits": [], "contribution": "717-718 kuşatmasında Bizans'ın yanında yer aldı.", "harm": "", "wives": [], "children": [], "wars": [{"name": "İstanbul kuşatması", "when": "717-718", "foe": "Emevî ordusu", "result": "zafer", "note": "Bulgarlar Bizans'ın yanında savaştı. Şehir düşmedi."}], "legends": [], "sources": [{"title": "TDV İslâm Ansiklopedisi, BULGARİSTAN", "url": "https://islamansiklopedisi.org.tr/bulgaristan"}, {"title": "Britannica, Bulgar", "url": "https://www.britannica.com/topic/Bulgar"}]}, {"id": "tuna-bulgar-krum", "name": "Krum", "title": "han", "birth": null, "birthNote": "kayıtlarda yok", "death": 814, "deathNote": "TDV Türk: İstanbul kuşatması sırasında öldü.", "reign": [803, 814], "reignNote": "TDV Bulgar Kurum Han diye 803-814 yazar. 718-803 arası hanlar bu dosyada yok.", "summary": "Tuna Bulgarlarının parlak dönemini açtı. Slav ve Bulgar nüfusu birleştirmeye çalıştı, kanun çıkardığı kaydedilir. Sofya'dan Üsküp'e ticaret yolları bu çağda Bulgar eline geçti.", "traits": [], "contribution": "Devleti VIII. yüzyıl gerilemesinden çıkardı.", "harm": "Bizans ordusunu imha etti; imparatorun kafatasından kadeh yaptırdığı Britannica'da yazılır.", "wives": [], "children": [{"name": "Omurtag", "mother": "", "note": "TDV Türk yerine geçen oğul diye yazar", "certainty": "olasi"}], "wars": [{"name": "Nikeforos seferi", "when": "803-814 arası", "foe": "Bizans imparatoru I. Nikeforos", "result": "zafer", "note": "İmparatorluk ordusu imha edildi. Yıl açılan sayfada yok. Kafatası kadehi Britannica'da vardır."}, {"name": "İstanbul kuşatması", "when": "814", "foe": "Bizans", "result": "yenilgi", "note": "Şehir alınamadı. Krum kuşatma sırasında öldü."}], "legends": ["Nikeforos'un kafatasının gümüş kaplanıp kadeh yapılması Britannica'da kayıtlı bir anlatıdır."], "sources": [{"title": "TDV İslâm Ansiklopedisi, BULGAR", "url": "https://islamansiklopedisi.org.tr/bulgar"}, {"title": "TDV İslâm Ansiklopedisi, TÜRK", "url": "https://islamansiklopedisi.org.tr/turk"}, {"title": "Britannica, Bulgaria", "url": "https://www.britannica.com/place/Bulgaria/History"}]}, {"id": "tuna-bulgar-omurtag", "name": "Omurtag", "title": "han", "birth": null, "birthNote": "kayıtlarda yok", "death": 831, "deathNote": "Saltanat sonu 831 diye yazılır; ölüm biçimi yok.", "reign": [814, 831], "reignNote": "TDV Türk ve Bulgar 814-831. TDV Bulgaristan 816-831.", "summary": "Bizans'la otuz yıllık barış yaptı. Franklarla uğraştı, Tuna-Sava-Drava havzasını ve Maroş tuzlalarını aldığı TDV'de yazılır. Pliska, Preslav ve Madara'daki yapı ve Krum kayalığı bu çağa bağlanır.", "traits": [], "contribution": "Güneyde sükûn, tuz ve imar getirdi.", "harm": "", "wives": [], "children": [], "wars": [{"name": "Bizans'la otuz yıllık barış", "when": "814'ten sonra", "foe": "Bizans", "result": "antlasma", "note": "Bulgaristan maddesi bunu Omurtag dönemine koyar."}, {"name": "Frank mücadelesi", "when": "814-831", "foe": "Franklar", "result": "zafer", "note": "TDV tek muharebe adı vermez; Tuna-Sava-Drava'nın alındığını yazar."}], "legends": [], "sources": [{"title": "TDV İslâm Ansiklopedisi, TÜRK", "url": "https://islamansiklopedisi.org.tr/turk"}, {"title": "TDV İslâm Ansiklopedisi, BULGARİSTAN", "url": "https://islamansiklopedisi.org.tr/bulgaristan"}]}, {"id": "tuna-bulgar-malamir", "name": "Malamir", "title": "han", "birth": null, "birthNote": "kayıtlarda yok", "death": null, "deathNote": "kayıtlarda yok", "reign": [831, 836], "reignNote": "TDV Bulgar ve Bulgaristan aynı yılları verir.", "summary": "Filibe'yi aldı. Bu dönemde Hıristiyanlık Bizans etkisiyle Bulgarlar arasında yayılmaya başladı; resmî din henüz değişmedi.", "traits": [], "contribution": "", "harm": "", "wives": [], "children": [], "wars": [{"name": "Filibe", "when": "831-836", "foe": "Bizans", "result": "zafer", "note": "TDV Bulgaristan ele geçirmeyi yazar, muharebe adı vermez."}], "legends": [], "sources": [{"title": "TDV İslâm Ansiklopedisi, BULGAR", "url": "https://islamansiklopedisi.org.tr/bulgar"}, {"title": "TDV İslâm Ansiklopedisi, BULGARİSTAN", "url": "https://islamansiklopedisi.org.tr/bulgaristan"}]}, {"id": "tuna-bulgar-presiyan", "name": "Presiyan", "title": "han", "birth": null, "birthNote": "kayıtlarda yok", "death": null, "deathNote": "kayıtlarda yok", "reign": [836, 852], "reignNote": "TDV Bulgar Persiyan 836-852, Türk maddesi 837-852, Bulgaristan Presiyan 836-852. Britannica Pressian 836-852.", "summary": "Makedonya'da Slav boylarının oturduğu yerleri ve Rodopları aldığı kaydedilir. Hıristiyanlığın yayılması sürdü.", "traits": [], "contribution": "Makedonya ve Rodop yönünde sınır genişledi.", "harm": "", "wives": [], "children": [], "wars": [{"name": "Makedonya ve Rodop seferleri", "when": "836-852", "foe": "Bizans", "result": "zafer", "note": "Tek muharebe adı yok."}], "legends": [], "sources": [{"title": "TDV İslâm Ansiklopedisi, BULGARİSTAN", "url": "https://islamansiklopedisi.org.tr/bulgaristan"}, {"title": "Britannica, Bulgar", "url": "https://www.britannica.com/topic/Bulgar"}]}, {"id": "tuna-bulgar-boris", "name": "Boris", "title": "han", "birth": null, "birthNote": "kayıtlarda yok", "death": null, "deathNote": "Açılan sayfalarda ölüm yılı yok. Saltanat 889'da biter.", "reign": [852, 889], "reignNote": "TDV Bulgaristan ve Britannica 852-889. TDV Bulgar 859-890. Vaftiz 864; Bulgaristan maddesi 865. Vaftiz adı Mikhail. Bu dosya Türkçe han dönemini vaftizde keser.", "summary": "Hıristiyanlığı resmen kabul etti ve halkı vaftiz ettirdi. TDV Türk, o zamana kadar tek tanrı inancı taşıyan Bulgarların bu tarihte hıristiyanlaştığını ve devletin Slav-Bizans kültürüne girdiğini yazar. Halefi Simeon han yerine çar unvanını kullandı.", "traits": [], "contribution": "Vaftiz, Slav ve Bulgar nüfusunu tek kilise altında birleştirdi.", "harm": "Türkçe han unvanı ve yönetici dil bu seçimle silindi.", "wives": [], "children": [{"name": "Simeon", "mother": "", "note": "TDV Türk halef diye 893-917, Bulgaristan 893-927 yazar. Çar unvanı vaftizden sonradır", "certainty": "olasi"}], "wars": [], "legends": [], "sources": [{"title": "TDV İslâm Ansiklopedisi, BULGARİSTAN", "url": "https://islamansiklopedisi.org.tr/bulgaristan"}, {"title": "TDV İslâm Ansiklopedisi, TÜRK", "url": "https://islamansiklopedisi.org.tr/turk"}, {"title": "TDV İslâm Ansiklopedisi, BULGAR", "url": "https://islamansiklopedisi.org.tr/bulgar"}]}]}, {"id": "pecenek", "name": "Peçenek birliği", "short": "Merkezi krallığı olmayan, boy beylerinden oluşan bozkır birliği", "aliases": ["Becenâk", "Patzinak"], "region": "bati", "start": 895, "end": 1091, "startNote": "Hazar-Oğuz darbesi 889 (276 hicrî). Don'dan Tuna'ya hâkimiyet 895. Britannica Karadeniz kuzeyini VIII-XII. yüzyıl diye geniş tutar.", "endNote": "TDV siyasî gücün 29 Nisan 1091'de bittiğini, son akının 1197'de yapıldığını yazar. Britannica 1122'deki ikinci Bizans zaferinin gücü fiilen yok ettiğini söyler.", "capital": "", "religion": "Kamlık; Hıristiyan misyonu tutmadı, İslâm bazı gruplarda yayıldı", "confidence": "kayit", "confidenceNote": "Boy düzeni Konstantinos Porfirogennetos'ta kayıtlıdır. Merkezî krallık yoktur. Kangar adının Kül Tigin'deki Keñeres ile birleştirilmesi TDV'de şüpheli görülür.", "summary": "Önce Seyhun ve Aral, sonra Yayık-İdil arasında yaşayan Peçenekler 889-895'te batıya itildi. Macarları Pannonia'ya sürdüler ve Don-Tuna bozkırını tuttular. Sekiz boy ve kırk obaydılar. Hükümdarları yoktu; boy beyleri gerektiğinde toplanırdı. 1091'de Bizans-Kıpçak hattında ağır yenilgiyle siyasî birlikleri kırıldı.", "legacy": "Macarların bugünkü yurda inmesinin başlıca sebebi oldular. Dağınık gruplar Macaristan, Bizans hizmeti ve Kıpçaklar içinde eridi. Oğuzlar arasında kalan kol Oğuz Peçenek boyunu oluşturdu.", "sources": [{"title": "TDV İslâm Ansiklopedisi, PEÇENEKLER", "url": "https://islamansiklopedisi.org.tr/pecenekler"}, {"title": "Britannica, Pechenegs", "url": "https://www.britannica.com/topic/Pechenegs"}], "rulers": [{"id": "pecenek-kure", "name": "Küre", "title": "boy beyi", "birth": null, "birthNote": "kayıtlarda yok", "death": null, "deathNote": "kayıtlarda yok", "reign": [972, null], "reignNote": "Kral değil. 972'de Sviatoslav'ı yenen başbuğ.", "summary": "Bizans'ın müttefiki olarak Kiev knezi Sviatoslav'ı savaşta öldürdü. Bütün Peçeneklerin hükümdarı diye anılmaz.", "traits": [], "contribution": "", "harm": "", "wives": [], "children": [], "wars": [{"name": "Sviatoslav çarpışması", "when": "972", "foe": "Kiev knezi Sviatoslav", "result": "zafer", "note": "Britannica prensin adını Sriatoslav diye yazar. Aynı kişi."}], "legends": [], "sources": [{"title": "TDV İslâm Ansiklopedisi, PEÇENEKLER", "url": "https://islamansiklopedisi.org.tr/pecenekler"}, {"title": "Britannica, Pechenegs", "url": "https://www.britannica.com/topic/Pechenegs"}]}, {"id": "pecenek-turak", "name": "Turak", "title": "boy beyi", "birth": null, "birthNote": "kayıtlarda yok", "death": null, "deathNote": "kayıtlarda yok", "reign": [1048, null], "reignNote": "Durak diye de yazılır. 1048'de on üç oymağın başbuğu. Kral değil.", "summary": "Tuna kuzeyindeki ana kolun başıydı. Bizans'a sığınan Kegen'e yenildi, 140 beyle birlikte esir düştü, sonra Tuna boyuna döndü. 1049'da Bizans ordusunu yenip Edirne'ye vardı.", "traits": [], "contribution": "", "harm": "1048 akını Bulgaristan'ı yakıp yıktı.", "wives": [], "children": [], "wars": [{"name": "Kegen'e karşı", "when": "1048", "foe": "Kegen ve Bizans", "result": "yenilgi", "note": "Esir düştü, sonra döndü."}, {"name": "Edirne'ye kadar sefer", "when": "1049", "foe": "Bizans", "result": "zafer", "note": ""}], "legends": [], "sources": [{"title": "TDV İslâm Ansiklopedisi, PEÇENEKLER", "url": "https://islamansiklopedisi.org.tr/pecenekler"}]}, {"id": "pecenek-kegen", "name": "Kegen", "title": "boy beyi", "birth": null, "birthNote": "kayıtlarda yok", "death": null, "deathNote": "kayıtlarda yok", "reign": [1048, null], "reignNote": "İki oymağın başbuğu. Bizans sınırına yerleştirildi.", "summary": "Uzlara karşı ün kazandı. Bizans'a sığınıp Tuna ve Silistre yakınında toprak aldı. Bizans yardımıyla Turak'ı yendi.", "traits": [], "contribution": "", "harm": "", "wives": [], "children": [], "wars": [{"name": "Turak'a karşı", "when": "1048", "foe": "Turak", "result": "zafer", "note": "Bizans desteğiyle."}], "legends": [], "sources": [{"title": "TDV İslâm Ansiklopedisi, PEÇENEKLER", "url": "https://islamansiklopedisi.org.tr/pecenekler"}]}]}, {"id": "kipcak-kuman", "name": "Kıpçak-Kuman birliği", "short": "Deşt-i Kıpçak'ta tek devleti olmayan boylar birliği", "aliases": ["Kumanlar", "Polovets", "Deşt-i Kıpçak"], "region": "bati", "start": 1054, "end": 1241, "startNote": "Kıpçak adı VIII. yüzyıl Şine-Usu yazıtında geçer. Doğu Avrupa bozkırında Rus yıllıklarına ilk giriş 1054 Polovtsı diye. Bölge 1080'lerde Balkaş'tan Tuna ağzına yayıldı.", "endNote": "Britannica Kumanların Macaristan'a sığınmasını 1237-1239'a, TDV Köten'in bozulmasını 1239'a, Altın Orda ile siyasî rolün bitmesini 1241'e koyar. Köten 1240-41 kışında Macaristan'da öldürüldü.", "capital": "", "religion": "Başta şamanlık; bir kısmı Ortodoks oldu, Kırım ve İdil'de İslâm yayıldı", "confidence": "kayit", "confidenceNote": "Tek merkezî devlet kuramadıkları TDV'de açıktır. Beş bölgenin (Orta Asya, İtil-Yayık, Don-Donets, Aşağı Dinyeper, Tuna) kendi başbuğları vardı. Kuman batıdaki addır; doğuda Kıpçak denir. Bölge hem Karadeniz kuzeyi hem İdil boyunu kapsar; bu kayıtta bölge bati tutuldu.", "summary": "Kimeklerin bir kolu olan Kıpçaklar XI. yüzyıl ortasında Uzların ardından Güney Rusya bozkırına girdi. İslâm kaynakları bu alana Deşt-i Kıpçak dedi. Boylar ortak bir kral seçmedi. Rus knezleriyle hem savaştılar hem kız alıp verdiler. 1223 Kalka ve 1238-1239 Moğol seferleri birliği dağıttı.", "legacy": "Altın Orda halkının dil tabanı oldular. Macaristan'da Kuman adıyla, Mısır'da Memlük sultanları arasında sürdüler. Codex Cumanicus dillerinden kalan başlıca derlemedir.", "sources": [{"title": "TDV İslâm Ansiklopedisi, KIPÇAKLAR", "url": "https://islamansiklopedisi.org.tr/kipcaklar"}, {"title": "Britannica, Cuman", "url": "https://www.britannica.com/topic/Cuman"}], "rulers": [{"id": "kipcak-atrak", "name": "Atrak", "title": "başbuğ", "birth": null, "birthNote": "kayıtlarda yok", "death": null, "deathNote": "kayıtlarda yok", "reign": [1118, 1125], "reignNote": "Bütün Kıpçakların hükümdarı değil. Don-Kuban kolunun başbuğu. 1125'te Gürcistan'dan döndü.", "summary": "Kızı Gürcü kralı II. David ile evlendi. 1118'de Gürcistan'a giden Kıpçaklardan 40.000 atlılık bir kuvvet kurulduğu TDV'de yazılır. Kendisi 1125'te yurduna döndü; gidenlerin çoğu kaldı.", "traits": [], "contribution": "Gürcü ordusuna Kıpçak atlısı kattı.", "harm": "", "wives": [], "children": [{"name": "kayıtlarda adı geçmiyor", "mother": "", "note": "Güzelliği anılan kız, II. David ile evlendi", "certainty": "olasi"}], "wars": [{"name": "Selçuklu akınlarına karşı Gürcü seferleri", "when": "1118-1125", "foe": "Anadolu Selçukluları", "result": "belirsiz", "note": "TDV Gürcülerin bu atlılarla akınlara karşı koyduğunu yazar; tek meydan sonucu vermez."}], "legends": [], "sources": [{"title": "TDV İslâm Ansiklopedisi, KIPÇAKLAR", "url": "https://islamansiklopedisi.org.tr/kipcaklar"}]}, {"id": "kipcak-barc", "name": "Barc", "title": "bey", "birth": null, "birthNote": "kayıtlarda yok", "death": null, "deathNote": "kayıtlarda yok", "reign": [1227, null], "reignNote": "Britannica onu Kuman prensi diye anar. Merkezî kağan değildir.", "summary": "1227'de 15.000 kişilik bir grupla vaftiz oldu. 1228'de Kuman piskoposluğu kuruldu. Bütün Deşt'in hükümdarı değildir.", "traits": [], "contribution": "", "harm": "", "wives": [], "children": [], "wars": [], "legends": [], "sources": [{"title": "Britannica, Cuman", "url": "https://www.britannica.com/topic/Cuman"}]}, {"id": "kipcak-koten", "name": "Köten", "title": "başbuğ", "birth": null, "birthNote": "kayıtlarda yok", "death": 1241, "deathNote": "Britannica, Macaristan'ın 1240-41 Moğol akınından hemen önce öldürüldüğünü yazar. Tek gün yok.", "reign": [1239, 1241], "reignNote": "Kuthen diye de yazılır. Don-Donets kolunun başbuğu. Bütün Kıpçakların kralı değil.", "summary": "Moğol karşısında Don ve Donets'te dağıldı, 1239'da Macaristan'a sığındı. Rus direnişini örgütleme girişimi sonuçsuz kaldı. Macaristan'da tehlikeli yabancı sayılıp öldürüldü.", "traits": [], "contribution": "", "harm": "", "wives": [], "children": [], "wars": [{"name": "Don-Donets bozgunu", "when": "1239", "foe": "Batu Han'ın ordusu", "result": "yenilgi", "note": "Kaçabilenler Macaristan'a gitti."}, {"name": "Kalka", "when": "1223", "foe": "Cebe Noyan ve Sübütay", "result": "yenilgi", "note": "Kıpçak-Rus ordusu. Köten'in bu savaşta komutan olduğu TDV'de ayrıca yazılmaz."}], "legends": [], "sources": [{"title": "TDV İslâm Ansiklopedisi, KIPÇAKLAR", "url": "https://islamansiklopedisi.org.tr/kipcaklar"}, {"title": "Britannica, Cuman", "url": "https://www.britannica.com/topic/Cuman"}]}]}, {"id": "itil-bulgar", "name": "İtil Bulgar Devleti", "short": "Orta İdil'de İslâm'ı resmen kabul eden Bulgar hanlığı, 1236'ya kadar", "aliases": ["İdil Bulgar Hanlığı", "Volga Bulgarları"], "region": "kuzey", "start": 922, "end": 1236, "startNote": "Kuzeye çekiliş VII. yüzyıl sonu ile VIII. yüzyıl başı. Hazar tâbiiyeti 965'e kadar sürdü. Resmî İslâm ve elçilik 922. Başlangıç yılı olarak bu tarih alındı.", "endNote": "TDV Batu'nun yakıp yıkmasını 1236'ya, Britannica Altın Orda'ya bağlanmayı 1237'ye koyar. Yarı bağımlı hayat Altın Orda'da sürdü; bu kayıt 1236'da biter.", "capital": "Bulgar", "religion": "Önce eski Türk inancı; 922'den sonra İslâm", "confidence": "kayit", "confidenceNote": "922 elçiliği İbn Fadlân üzerinden kayıtlıdır. Han adı Almış'tır. TDV Bulgar maddesindeki 'Yaltavar oğlu' ifadesi unvanı baba adı gibi okur; İdil maddesi babayı Şilkey, unvanı yeltever/ilteber diye ayırır. Kotrag adı yalnızca Britannica'dadır. Sikkelerdeki diğer hanların 1236'dan önce mi sonra mı olduğu ayırt edilmez.", "summary": "Büyük Bulgarya dağılınca Otuz-Ogur kolu Orta İdil ve Kama'ya çekildi. Fin-Ogur komşularını bağlayıp kürk, bal ve İdil ticaretine oturdu. Almış Han 922'de Abbâsî elçilerini kabul edip İslâm'ı resmen aldı. 965'te Hazar darbesinden sonra tam bağımsız kaldı. 1223'te bir Moğol tümenini yendiler; 1236'da Batu ülkeyi yaktı.", "legacy": "İslâm'ı resmî din yapan ilk Türk devleti diye anılır. Bulgar gönü ve taş yapı izleri kaldı. Dil yadigârları Çuvaşçanın öncülü sayılır. Moğol sonrası Kıpçakça ağır bastı.", "sources": [{"title": "TDV İslâm Ansiklopedisi, İDİL BULGAR HANLIĞI", "url": "https://islamansiklopedisi.org.tr/idil-bulgar-hanligi"}, {"title": "TDV İslâm Ansiklopedisi, BULGAR", "url": "https://islamansiklopedisi.org.tr/bulgar"}, {"title": "Britannica, Bulgar", "url": "https://www.britannica.com/topic/Bulgar"}], "rulers": [{"id": "itil-bulgar-almis", "name": "Almış", "title": "ilteber", "birth": null, "birthNote": "kayıtlarda yok", "death": null, "deathNote": "kayıtlarda yok", "reign": [922, null], "reignNote": "Şilkey oğlu. Unvanı yeltever/ilteber/yaltavar. Bitiş yılı yok. Elçi 12 Muharrem 310 (12 Mayıs 922) karargâha vardı. TDV Bulgar elçinin yola çıkışını 920 diye de yazar.", "summary": "Abbâsî halifesi Muktedir-Billâh'tan din adamı istedi. Sevsen er-Ressî heyetinde kâtip İbn Fadlân vardı. Han ve ileri gelenler İslâm'ı kabul etti. Halife ve han adına sikke basıldı, cami ve kadılık kuruldu.", "traits": [], "contribution": "İdil Bulgar ülkesini resmen müslüman bir hanlık haline getirdi.", "harm": "", "wives": [], "children": [{"name": "kayıtlarda adı geçmiyor", "mother": "", "note": "Oğuz subaşısı Etrek'in kayınpederi Almış'tır; kızının adı yoktur", "certainty": "olasi"}], "wars": [], "legends": [], "sources": [{"title": "TDV İslâm Ansiklopedisi, İDİL BULGAR HANLIĞI", "url": "https://islamansiklopedisi.org.tr/idil-bulgar-hanligi"}, {"title": "TDV İslâm Ansiklopedisi, BULGAR", "url": "https://islamansiklopedisi.org.tr/bulgar"}, {"title": "TDV İslâm Ansiklopedisi, OĞUZLAR", "url": "https://islamansiklopedisi.org.tr/oguzlar"}]}, {"id": "itil-bulgar-han-adi-yok", "name": "kayıtlarda adı geçmiyor", "title": "han", "birth": null, "birthNote": "kayıtlarda adı geçmiyor", "death": null, "deathNote": "kayıtlarda adı geçmiyor", "reign": [null, 1236], "reignNote": "964, 985, 1223 ve 1236 olaylarının han adı TDV'de yoktur. Sikke adları (Şülkî, Ahmed, Tâlib, Mü'min, Haydar, Muhammed, Saîd b. Haydar, Baraj, İbrâhim, Selim, İlham, Abdullah, Hasan, Mahmud, Altınbek, Âlimbek) yıllara bağlanamadığı için ayrı hükümdar yazılmadı.", "summary": "Almış'tan sonraki müslüman hanların sırası sikke adlarıyla sınırlıdır. 965'te Hazar zayıflayınca tam bağımsızlık geldi. Moğol öncesi hanın adı verilmez.", "traits": [], "contribution": "", "harm": "", "wives": [], "children": [], "wars": [{"name": "Kiev akınları", "when": "964 ve 985", "foe": "Kiev Rus knezliği", "result": "zafer", "note": "TDV akınların etkisizleştirildiğini yazar."}, {"name": "Ticaret antlaşması", "when": "1006", "foe": "Kiev", "result": "antlasma", "note": ""}, {"name": "1223 Moğol çarpışması", "when": "1223", "foe": "Moğol öncü ordusu", "result": "zafer", "note": "Kalka'dan dönen Moğol kuvveti İdil Bulgarlarınca imha edildi."}, {"name": "Batu seferi", "when": "1236", "foe": "Batu Han", "result": "yenilgi", "note": "Ülke ve Bulgar şehri yakıldı. Britannica bağlanmayı 1237 diye yazar."}], "legends": [], "sources": [{"title": "TDV İslâm Ansiklopedisi, İDİL BULGAR HANLIĞI", "url": "https://islamansiklopedisi.org.tr/idil-bulgar-hanligi"}]}]}, {"id": "altin-orda", "name": "Altın Orda Hanlığı", "short": "Altın Orda (Cuci Ulusu)", "aliases": ["Altın Ordu", "Deşt-i Kıpçak Hanlığı", "Cuci Ulusu", "Kıpçak Hanlığı", "Golden Horde"], "region": "kuzey", "start": 1227, "end": 1502, "startNote": "Cengiz Han'ın büyük oğlu Cuci'nin vefatı ve Batu Han'ın Deşt-i Kıpçak seferleriyle 1227-1242'de kuruldu.", "endNote": "1502 yılında Kırım Hanı I. Mengli Giray'ın Saray şehrini zaptetmesi ve son han Şeyh Ahmed'in yenilgisiyle yıkıldı.", "capital": "Saray (Sarây-ı Bâtû ve Sarây-ı Berke)", "religion": "İslamiyet (Özbek Han devrinden itibaren resmi din; önceleri Şamanizm / Gök Tanrı)", "confidence": "kayit", "confidenceNote": "Cüveynî, Reşîdüddin (Câmiu't-Tevârîh), İbn Battûta seyahatnamesi ve Rus vakayinâmeleriyle sabittir.", "summary": "Cuci'nin oğlu Batu Han tarafından Deşt-i Kıpçak, Harezm, İdil boyu ve Doğu Avrupa'da kurulan, yaklaşık üç asır boyunca Rus knezliklerini haraca bağlayan ve Avrasya bozkırlarını birleştiren ulu Türk-Tatar devleti. Berke Han devrinde İslamiyet kabul edildi; Memlüklerle ittifak kurularak İlhanlılar durduruldu. Özbek Han devrinde İslam resmi din ilan edildi ve imparatorluk en parlak devrini yaşadı. Timur istilaları ve taht kavgaları sonucu dağılarak Kazan, Kırım, Astrahan ve Sibir hanlıklarına bölündü.", "legacy": "Rus knezliklerini 250 yıl boyunca 'Tatar Boyunduruğu' (Yoke) altında tutarak Rusların birliğini geciktirdi; İpek Yolu ve Kürk Yolu ticaretini güvene aldı; Saray şehrini doğunun en büyük kültür ve ticaret merkezlerinden biri yaptı.", "essay": ["Altın Orda Hanlığı, Moğol istilası sonrası Deşt-i Kıpçak sahasına yerleşen yönetici tabakanın kısa sürede bölgedeki yoğun Kıpçak Türk nüfusuyla kaynaşıp Türkleşmesi ve İslamlaşması sonucu tam anlamıyla bir Türk-Tatar imparatorluğuna dönüştü.", "Batu Han, 1236-1242 Batı Seferi ile Moskova, Vladimir, Kiev, Polonya ve Macaristan'ı ezerek Adriyatik Denizi'ne kadar ilerledi. Başkent Saray'ı İdil (Volga) kıyısında kurdu. Kardeşi Berke Han İslamiyeti kabul etti; 1258 Bağdat fâciası sonrası İlhanlı Hülâgû'ya savaş açarak Memlük Sultanı Baybars ile tarihi bir ittifak kurdu.", "Gıyâseddin Muhammed Özbek Han (1313-1341) İslamiyeti devlet dini yaptı. İbn Battûta, Saray şehrinin camilerini, hanlarını, saraylarını ve zenginliğini hayranlıkla kaydeder. Canıbek Han'ın ardından başlayan iç karışıklıklar ('Büyük Kargaşa'), Toktamış Han tarafından geçici olarak toparlandıysa da Timur'un 1391 ve 1395 seferleri Saray şehrini yerle bir etti ve devletin belini kırdı. 1502'de Kırım Hanlığı tarafından son verildi."], "sources": [{"title": "TDV İslâm Ansiklopedisi, ALTIN ORDA", "url": "https://islamansiklopedisi.org.tr/altin-orda"}, {"title": "TDV İslâm Ansiklopedisi, BATU HAN", "url": "https://islamansiklopedisi.org.tr/batu-han"}, {"title": "TDV İslâm Ansiklopedisi, BERKE HAN", "url": "https://islamansiklopedisi.org.tr/berke-han"}, {"title": "TDV İslâm Ansiklopedisi, ÖZBEK HAN", "url": "https://islamansiklopedisi.org.tr/ozbek-han"}], "rulers": [{"id": "altin-orda-batu", "name": "Batu Han", "aliases": ["Sain Han", "Batu Khan"], "title": "Uluğ Han / Fatih", "birth": 1205, "birthNote": "Cuci'nin ikinci oğlu olarak Moğol bozkırında doğdu", "death": 1255, "deathNote": "Saray şehrinde vefat etti", "reign": [1227, 1255], "reignNote": "1227'de babasının ulusunu devraldı; 1236-1242 seferleriyle Altın Orda'yı fiilen kurdu.", "summary": "Altın Orda Devleti'nin kurucusu ve tarihin en kudretli fatihlerinden biri. Rus knezliklerini, Polonya ve Macar krallıklarını bozguna uğrattı. İdil boyunda Saray şehrini kurdu. 'Sain Han' (Adil/İyi Han) unvanıyla anıldı.", "traits": ["Büyük stratejist", "Teşkilatçı", "Adil hükümdar", "Askeri deha"], "contribution": "Avrasya bozkırlarını tek idarede birleştirdi; Deşt-i Kıpçak'ta asırlarca sürecek Türk-Tatar devlet geleneğini kurdu.", "harm": "Doğu Avrupa ve Rus şehirlerinde ağır tahribat ve can kaybına yol açtı.", "wives": [{"name": "Borakçin Hatun", "note": "Büyük baş hatun", "certainty": "kesin"}], "children": [{"name": "Sartak Han", "mother": "", "note": "Hristiyanlığı kabul eden veliaht, kısa süre han oldu", "certainty": "kesin"}, {"name": "Tokokan", "mother": "", "note": "Mengü Timur'un babası", "certainty": "kesin"}], "wars": [{"name": "Rus Seferi (Vladimir ve Moskova)", "when": "1237-1238", "foe": "Rus Knezlikleri (Yuri II)", "result": "zafer", "note": "Ryazan, Kolomna, Moskova ve Vladimir zaptedildi."}, {"name": "Sit Nehri Muharebesi", "when": "1238", "foe": "Vladimir Büyük Dükalığı", "result": "zafer", "note": "Büyük Knez Yuri öldürüldü, Rusya tamamen itaat altına alındı."}, {"name": "Mohi Muharebesi", "when": "1241", "foe": "Macaristan Krallığı (IV. Bela)", "result": "zafer", "note": "Sajo nehri kıyısında Macar ve Templar şövalye ordusu imha edildi."}, {"name": "Legnica (Liegnitz) Muharebesi", "when": "1241", "foe": "Polonya ve Alman Şövalyeleri (II. Henryk)", "result": "zafer", "note": "Polonya dükü ve şövalye orduları imha edildi."}], "legends": ["Moğol kurultayına gitmeyip 'hastayım' diyerek kendi hanlığında kalması ve imparatorluk kaderini Saray'dan belirlemesi efsaneleşmiştir."], "sources": [{"title": "TDV İslâm Ansiklopedisi, BATU HAN", "url": "https://islamansiklopedisi.org.tr/batu-han"}]}, {"id": "altin-orda-berke", "name": "Berke Han", "aliases": ["Birkai Khan"], "title": "Han / Mücahid", "birth": 1208, "birthNote": "Cuci'nin üçüncü oğlu olarak doğdu", "death": 1266, "deathNote": "Kafkasya seferi sırasında Tiflis yakınlarında Kura Irmağı boyunda vefat etti", "reign": [1257, 1266], "reignNote": "İslamiyeti kabul eden ilk Altın Orda hükümdarı.", "summary": "Batu Han'ın kardeşi. Buhara'da Şeyh Seyfeddin Bâharzî vasıtasıyla Müslüman oldu. Hülâgû'nun 1258'de Bağdat'ı tahrip edip Abbâsî halifesini katletmesine öfkelenerek İlhanlılar'a savaş açtı. Mısır Memlük Sultanı I. Baybars ile ilk Türk-İslam ittifakını kurdu. Sarây-ı Berke şehrini imar etti.", "traits": ["Mütedeyyin Müslüman", "Cesur başbuğ", "Diplomat", "Adil"], "contribution": "Altın Orda'nın İslamlaşmasını başlattı; Memlüklerle kurduğu ittifakla İslam dünyasının İlhanlılar tarafından tamamen yutulmasını önledi.", "harm": "İlhanlılar ile Altın Orda arasında uzun sürecek kardeş kavgalarını ve Kafkasya kanlı çatışmalarını başlattı.", "wives": [{"name": "Cicek Hatun", "note": "Müslüman eşi", "certainty": "olasi"}], "children": [], "wars": [{"name": "Terek Irmağı Muharebesi", "when": "1262", "foe": "İlhanlı Devleti (Hülâgû Han)", "result": "zafer", "note": "Hülâgû'nun ordusu buz tutmuş Terek üzerinde kırılan buzlar ve süvari hücumuyla bozguna uğratıldı."}], "legends": ["Hülâgû'nun Bağdat katliamını duyduğunda 'O masum Müslümanların kanını döktü, Allah şahidim olsun ki bunun hesabını soracağım' diye ant içtiği rivayet edilir."], "sources": [{"title": "TDV İslâm Ansiklopedisi, BERKE HAN", "url": "https://islamansiklopedisi.org.tr/berke-han"}]}, {"id": "altin-orda-ozbek", "name": "Gıyâseddin Muhammed Özbek Han", "aliases": ["Özbek Han", "Sultan Muhammed Özbek"], "title": "Uluğ Han / Padişah", "birth": 1282, "birthNote": "Tuğrulça'nın oğlu olarak Saray'da doğdu", "death": 1341, "deathNote": "Başkent Saray'da vefat etti", "reign": [1313, 1341], "reignNote": "28 yıllık saltanatıyla Altın Orda'nın altın çağını yaşattı.", "summary": "Altın Orda'nın en parlak hükümdarı. İslamiyeti devletin resmi dini ilan etti. Bozkır halklarının İslamlaşmasını tamamladı. Başkent Saray'ı camiler, medreseler ve saraylarla bezedi; İbn Battûta onun meclislerini hayranlıkla tasvir etti. Adı, bugünkü 'Özbek' Türk boyunun etnonimine dönüştü.", "traits": ["Karizmatik lider", "Reformcu", "İlim ve sanat hamisi", "Ticaret koruyucusu"], "contribution": "İslamiyet'i devletin resmi dini yaptı; Altın Orda'yı dünyanın en zengin ticaret kavşaklarından biri haline getirdi; Rus knezliklerini mutlak vergiye bağladı.", "harm": "Moskova Knezliği'nin güçlenmesine göz yumarak Kalita İvan'a büyük knezlik yetkisi verdi, bu da gelecekte Rus birliğinin önünü açtı.", "wives": [{"name": "Taydula Hatun", "note": "Devlet işlerinde çok etkili baş hatun", "certainty": "kesin"}, {"name": "Bayalun Hatun", "note": "Bizans İmparatoru IX. Andronikos'un kızı", "certainty": "kesin"}], "children": [{"name": "Tini Bek", "mother": "Taydula Hatun", "note": "Kısa süre tahta oturdu", "certainty": "kesin"}, {"name": "Canıbek Han", "mother": "Taydula Hatun", "note": "Babasından sonra tahta geçen büyük sultan", "certainty": "kesin"}], "wars": [{"name": "Kafkasya İlhanlı Seferi", "when": "1319", "foe": "İlhanlı Devleti (Ebu Said Bahadır Han)", "result": "sonucsuz", "note": "Kür Irmağı boyunda çarpışmalar yapıldı."}, {"name": "Tver İsyanı Bastırması", "when": "1327", "foe": "Tver Rus Knezliği", "result": "zafer", "note": "İsyan eden Rus kenti yerle bir edildi, Moskova knezi vergi tahsildarı tayin edildi."}], "legends": ["Seyyah İbn Battûta, Özbek Han'ın cuma namazına giderken halkın önünde tevazuyla yürüdüğünü ve sarayında âlimlerle dini münazaralar yaptığını hayranlıkla nakleder."], "sources": [{"title": "TDV İslâm Ansiklopedisi, ÖZBEK HAN", "url": "https://islamansiklopedisi.org.tr/ozbek-han"}]}, {"id": "altin-orda-canibek", "name": "Celâleddin Mahmud Canıbek Han", "aliases": ["Canıbek Han", "Djani Beg"], "title": "Sultan / Han", "birth": 1315, "birthNote": "Saray şehrinde doğdu", "death": 1357, "deathNote": "Tebriz dönüşü hastalanarak oğlu Berdibek tarafından zehirlenerek şehit edildi", "reign": [1342, 1357], "reignNote": "Altın Orda'nın kudretli son büyük padişahı.", "summary": "Özbek Han'ın oğlu. Tebriz'i fethederek İlhanlı mirasçısı Çobanoğulları'na son verdi ve Azerbaycan'ı Altın Orda'ya kattı. Kefe'deki Ceneviz kolonisini kuşatması sırasında vebalı cesetleri mancınıkla surların içine fırlatması, tarihte ilk biyolojik savaş taktiği ve Kara Ölüm'ün Avrupa'ya yayılma noktası olarak anılır.", "traits": ["Cengaver fatih", "Mütefekkir", "Adaletli", "Şair ruhlu"], "contribution": "Azerbaycan ve Kafkasya'yı tamamen bağladı; Altın Orda sınırlarını en geniş haline getirdi.", "harm": "Ölümüyle birlikte hanlık 20 yıl sürecek kanlı taht kavgalarına ('Büyük Kargaşa') sürüklendi.", "wives": [], "children": [{"name": "Berdibek Han", "mother": "", "note": "Babasını öldürerek tahtı ele geçiren zalim han", "certainty": "kesin"}], "wars": [{"name": "Kefe Kuşatması", "when": "1346", "foe": "Ceneviz Cumhuriyeti (Kefe Kolonisi)", "result": "sonucsuz", "note": "Veba salgını sebebiyle kuşatma kaldırıldı; Ceneviz gemileri vebayı İtalya'ya taşıdı."}, {"name": "Tebriz Seferi", "when": "1356-1357", "foe": "Çobanoğulları Devleti (Melik Eşref)", "result": "zafer", "note": "Tebriz fethedildi, Melik Eşref asıldı, Azerbaycan bağlandı."}], "legends": ["Kefe kuşatmasında mancınıkla surların içine atılan vebalı cesetlerin Avrupa'daki Kara Veba salgınını tetiklediği dünya tıp ve tarih literatüründe en çok tartışılan vakalardandır."], "sources": [{"title": "TDV İslâm Ansiklopedisi, CANIBEK HAN", "url": "https://islamansiklopedisi.org.tr/canibek-han"}]}, {"id": "altin-orda-toktamis", "name": "Nâsırüddin Toktamış Han", "aliases": ["Toktamış", "Tokhtamysh"], "title": "Han", "birth": 1350, "birthNote": "Ak Orda bozkırında doğdu", "death": 1406, "deathNote": "Sibirya'da Tümen yakınlarında Şadibek ve İdigü taraftarlarınca öldürüldü", "reign": [1380, 1396], "reignNote": "Altın Orda'yı son kez tek bayrak altında birleştiren hükümdar.", "summary": "Emir Timur'un yardımıyla Ak Orda ve Altın Orda tahtını ele geçirdi. 1380 Kulikovo yenilgisinin ardından dağılan devleti topladı; 1382'de Moskova'yı kuşatarak yaktı ve Rusları tekrar haraca bağladı. Ancak nankörlük ederek Timur'un topraklarına (Harezm ve Azerbaycan) saldırdı; Timur'a karşı 1391 Kunduzca ve 1395 Terek muharebelerinde ağır hezimete uğrayarak Altın Orda'nın yıkımını getirdi.", "traits": ["Hırslı kumandan", "Fırsatçı", "İnatçı savaşçı", "Talihsiz siyasetçi"], "contribution": "Kulikovo sonrası Rus knezliklerinin bağımsızlık hevesini 1382 Moskova Seferi ile kırarak hanlığı birleştirdi.", "harm": "Hamisi Timur'a ihanet edip savaş açarak Saray ve Deşt-i Kıpçak şehirlerinin yerle bir olmasına, Altın Orda'nın parçalanmasına sebep oldu.", "wives": [{"name": "Togaybike Hatun", "note": "Baş hatun", "certainty": "olasi"}], "children": [{"name": "Celâleddin Han", "mother": "", "note": "1410 Grunwald Muharebesi'nde Polonya-Litvanya safında Töton Şövalyeleri'ni ezen Tatar komutan", "certainty": "kesin"}, {"name": "Kerim Berdi", "mother": "", "note": "Kısa süre hanlık yaptı", "certainty": "kesin"}, {"name": "Kebek Han", "mother": "", "note": "Han", "certainty": "kesin"}], "wars": [{"name": "Moskova Kuşatması ve Yakılması", "when": "1382", "foe": "Moskova Knezliği (Dmitriy Donskoy)", "result": "zafer", "note": "Moskova tamamen yakıldı, 24.000 Rus öldürüldü, Rus knezleri tekrar vergiye bağlandı."}, {"name": "Kunduzca Irmağı Muharebesi", "when": "1391", "foe": "Timur İmparatorluğu (Emir Timur)", "result": "yenilgi", "note": "Volga boyunda Timur'un ordusu karşısında ordusu dağıldı."}, {"name": "Terek Irmağı Muharebesi", "when": "1395", "foe": "Timur İmparatorluğu (Emir Timur)", "result": "yenilgi", "note": "Altın Orda ordusu tamamen imha edildi; Timur başkent Saray'ı yerle bir etti."}], "legends": ["Oğlu Celâleddin Han'ın komutasındaki Tatar süvarilerinin 1410 Tannenberg/Grunwald Muharebesi'nde sahte ricat taktiğiyle Töton Şövalyeleri'ni pusuya düşürüp Avrupa tarihini değiştirdiği meşhurdur."], "sources": [{"title": "TDV İslâm Ansiklopedisi, TOKTAMIŞ HAN", "url": "https://islamansiklopedisi.org.tr/toktamis-han"}]}]}, {"id": "nogay-ordasi", "name": "Nogay Ordası", "short": "Nogay Ordası (Mangıt Yurdu)", "aliases": ["Nogai Horde", "Mangıt Yurdu", "Nogay Hanlığı"], "region": "kuzey", "start": 1391, "end": 1634, "startNote": "Emir Edigü Bey'in Altın Orda'dan ayrılarak İdil-Yayık (Volga-Ural) bozkırlarında Mangıt boylarını birleştirmesiyle kuruldu.", "endNote": "1634 yılında Doğu'dan gelen Kalmuk Budist istilası ve Rus Çarlığı baskısı sonucu dağıldı.", "capital": "Saraycık (Yayık Irmağı üzerinde)", "religion": "İslamiyet (Sünnî-Hanefî)", "confidence": "kayit", "confidenceNote": "Edige Destanı, Şecere-i Terâkime ve Rus sefaretnâmeleriyle sabittir.", "summary": "Altın Orda'nın parçalanma sürecinde İdil ile Yayık (Ural) ırmakları arasındaki uçsuz bucaksız bozkırlarda Mangıt boy beyleri tarafından kurulan güçlü göçebe Türk devleti. Kurucusu Emir Edigü Bey, Altın Orda tahtına hanlar oturtup indiren efsanevi bir başbuğdur. 1399 Vorskla zaferiyle Doğu Avrupa'nın kaderini değiştirdi. Nogay atlıları Kırım ve Osmanlı seferlerinin en çevik süvari gücünü oluşturdu.", "legacy": "Nogay Türkçesi ve zengin Edige Destanı kültürünü Avrasya edebiyatına kazandırdı; hafif süvari savaş taktiğinin zirvesini temsil etti.", "essay": ["Nogay Ordası, adını Altın Orda'nın kudretli kumandanı Nogay Han'dan alsa da asıl siyasi varlığını Mangıt kabilesi reisi Emir Edigü Bey'in önderliğinde kazandı. Başkent Saraycık, İpek Yolu'nun Hazar kuzeyi güzergâhında gelişmiş bir ticaret merkeziydi.", "Edigü Bey, 1399'da Vorskla Irmağı Savaşı'nda Litvanya Büyük Dükü Vytautas ve müttefiki Toktamış'ı hezimete uğratarak Doğu Avrupa'da Haçlı-Litvanya yayılmasını durdurdu; 1408'de Moskova'yı kuşatarak haraca bağladı.", "16. yüzyılda Büyük Nogay ve Küçük Nogay olarak ikiye bölündü. Doğudan gelen Kalmuk Moğollarının kanlı saldırıları, kuraklık ve Rus Çarlığı'nın baskıları sonucu 1634'te siyasi birliğini kaybetti; Nogay boylarının bir kısmı Kırım, Kafkasya ve Dobruca'ya göç etti."], "sources": [{"title": "TDV İslâm Ansiklopedisi, NOGAYLAR", "url": "https://islamansiklopedisi.org.tr/nogaylar"}, {"title": "TDV İslâm Ansiklopedisi, EDİGÜ", "url": "https://islamansiklopedisi.org.tr/edigu"}], "rulers": [{"id": "nogay-edigu-bey", "name": "Emir Edigü Bey", "aliases": ["Edige Bey", "İdigü", "Edigu Mangıt"], "title": "Uluğ Bey / Başbuğ / Bîklerbîkî", "birth": 1352, "birthNote": "Deşt-i Kıpçak sahasında Mangıt boy beyi Baltyçak'ın oğlu olarak doğdu", "death": 1419, "deathNote": "Saraycık yakınlarında Seyhun boyunda Toktamış'ın oğullarıyla girdiği muharebede şehit düştü", "reign": [1396, 1419], "reignNote": "23 yıl boyunca fiili Altın Orda ve Nogay hükümdarı.", "summary": "Nogay Ordası'nın kurucusu ve Avrasya bozkırının efsanevi kahramanı (Edige Destanı). Timur'un desteğiyle yükseldi; Altın Orda'da veziriazam (Bîklerbîkî) sıfatıyla kukla hanlar idare etti. 1399 Vorskla Meydan Muharebesi'nde Litvanya-Polonya ve müttefik ordularını imha etti. Moskova'yı kuşatarak Rusları dize getirdi.", "traits": ["Dahi mareşal", "Siyasi satranç ustası", "Bozkır destan kahramanı"], "contribution": "Nogay birliğini kurdu; Doğu Avrupa'da Litvanya ve Töton yayılmasını kırarak İslam-Türk varlığını korudu.", "harm": "Cengiz soyundan olmadığı için tahta meşru hanlar yerine kuklalar oturtarak hanlık otoritesinin büsbütün aşınmasına yol açtı.", "wives": [], "children": [{"name": "Nureddin Bey", "mother": "", "note": "Babasından sonra Nogay Ordası'nı yöneten kudretli bey", "certainty": "kesin"}, {"name": "Mansur Bey", "mother": "", "note": "Kırım ve bozkır siyasetinde etkili bey", "certainty": "kesin"}, {"name": "Gazi Bey", "mother": "", "note": "Nogay mirzası", "certainty": "kesin"}], "wars": [{"name": "Vorskla Irmağı Meydan Muharebesi", "when": "1399", "foe": "Litvanya Büyük Dükalığı ve Polonya (Vytautas & Toktamış)", "result": "zafer", "note": "Doğu Avrupa tarihinin en büyük meydan savaşlarından biri; Haçlı-Litvanya ordusu tamamen imha edildi."}, {"name": "Moskova Seferi ve Kuşatması", "when": "1408", "foe": "Moskova Knezliği (I. Vasili)", "result": "zafer", "note": "Moskova surları altına gelindi, 3000 ruble haraç alınarak Rus knezliği itaate bağlandı."}], "legends": ["Bütün Türk boylarında (Kazak, Kırgız, Karakalpak, Tatar, Nogay, Başkurt) müştereken anlatılan 'Edige Destanı' onun kahramanlıkları üzerine inşa edilmiştir."], "sources": [{"title": "TDV İslâm Ansiklopedisi, EDİGÜ", "url": "https://islamansiklopedisi.org.tr/edigu"}]}]}, {"id": "kazan-hanligi", "name": "Kazan Hanlığı", "short": "Kazan Hanlığı (Qazan Yurtı)", "aliases": ["Kazan Khanate", "Qazan Hanlığı", "Kazan Krallığı"], "region": "kuzey", "start": 1438, "end": 1552, "startNote": "Altın Orda hanlarından Uluğ Muhammed Han'ın İdil (Volga) kıyısında Kazan merkezli kurmasıyla başladı.", "endNote": "1552 yılında Korkunç İvan komutasındaki 150 bin kişilik Rus ordusunun Kazan Kalesi'ni zaptetmesiyle yıkıldı.", "capital": "Kazan", "religion": "İslamiyet (Sünnî-Hanefî)", "confidence": "kayit", "confidenceNote": "Kazan Kroniği (Kazanskaya Istoriya), Rus vakayinâmeleri ve kitabelerle sabittir.", "summary": "İdil Bulgar mirası üzerine Altın Orda hanı Uluğ Muhammed Han tarafından kurulan zengin ve medeni Türk-Tatar devleti. Volga nehir ticaretini elinde tuttu. 1445 Suzdal zaferiyle Moskova Büyük Knezini esir aldı. Sarayları, camileri (Kul Şerif Camii) ve zengin kütüphaneleriyle tanındı. 1552'de Korkunç İvan'ın aylar süren kanlı kuşatması sonrası düşerek Rus Çarlığı tarafından ilhak edildi.", "legacy": "Kazan Tatarlarının yüksek şehir kültürünü, Kul Şerif destanını ve Süyümbike Minaresi efsanesini tarihe emanet etti.", "essay": ["Kazan Hanlığı, eski İdil Bulgar Devleti'nin verimli topraklarında ve Altın Orda'nın çöküş boşluğunda Uluğ Muhammed Han tarafından 1438'de kuruldu.", "Uluğ Muhammed Han, 1445'te Suzdal Meydan Muharebesi'nde Moskova Büyük Knezi II. Vasili'yi ordusuyla birlikte esir alarak Rusları ağır haraca bağladı ve Kasım Hanlığı'nın kurulmasına zemin hazırladı.", "Hanlık içindeki Rus yanlısı ve Kırım-Osmanlı yanlısı hizipler devleti zayıflattı. Safa Giray Han devrinde bağımsızlık korunduysa da onun ölümünden sonra tahta çıkan küçük yaştaki oğlu adına devleti yöneten kahraman naibe Süyümbike Hatun, Moskova entrikalarına direndi. 1552 sonbaharında Korkunç İvan 150 bin asker ve yüzlerce topla Kazan'ı kuşattı; Seyyid Kul Şerif ve talebeleri cami önünde son nefeslerine kadar dövüşerek şehit düştü ve hanlık yıkıldı."], "sources": [{"title": "TDV İslâm Ansiklopedisi, KAZAN HANLIĞI", "url": "https://islamansiklopedisi.org.tr/kazan-hanligi"}, {"title": "TDV İslâm Ansiklopedisi, ULUĞ MUHAMMED HAN", "url": "https://islamansiklopedisi.org.tr/ulug-muhammed-han"}, {"title": "TDV İslâm Ansiklopedisi, SÜYÜMBİKE", "url": "https://islamansiklopedisi.org.tr/suyumbike"}], "rulers": [{"id": "kazan-ulug-muhammed", "name": "Uluğ Muhammed Han", "aliases": ["Oluğ Muhammed", "Ulan Han"], "title": "Han / Kurucu", "birth": 1405, "birthNote": "Deşt-i Kıpçak sahasında doğdu", "death": 1445, "deathNote": "Kazan'da vefat etti", "reign": [1438, 1445], "reignNote": "Kazan Hanlığı ve Kasım Hanlığı'nın kurucu atası.", "summary": "Altın Orda tahtından ayrıldıktan sonra İdil boyuna gelerek Kazan Hanlığı'nı kuran tecrübeli hükümdar. 1445 Suzdal Muharebesi'nde Moskova ordusunu bozguna uğratıp Rus Büyük Knezi II. Vasili'yi esir aldı; Rusları ağır tazminata bağladı.", "traits": ["Dirayetli lider", "Usta komutan", "Teşkilatçı"], "contribution": "Kazan Hanlığı'nı kurdu; Rus knezliklerine karşı Tatar askeri üstünlüğünü sürdürdü.", "harm": "Vefatından sonra oğlu Mahmud ile kardeşi Kasım arasında başlayan çekişme hanlığın bölünmesine yol açtı.", "wives": [], "children": [{"name": "Mahmud Han", "mother": "", "note": "Kazan tahtına geçen oğlu", "certainty": "kesin"}, {"name": "Kasım Han", "mother": "", "note": "Kasım Hanlığı'nı kuran oğlu", "certainty": "kesin"}, {"name": "Yakup Bey", "mother": "", "note": "Kazan prensi", "certainty": "kesin"}], "wars": [{"name": "Belyov Muharebesi", "when": "1437", "foe": "Moskova Knezliği (II. Vasili)", "result": "zafer", "note": "40 bin kişilik Rus ordusu 3 bin kişilik Tatar süvarisi tarafından darmadağın edildi."}, {"name": "Suzdal Meydan Muharebesi", "when": "1445", "foe": "Moskova Büyük Knezliği (II. Vasili)", "result": "zafer", "note": "Büyük Knez esir alındı, ağır fidye ve vergi anlaşması imzalandı."}], "legends": ["Rus Büyük Knezini bizzat çadırında esir tutup ayağına diz çöktürmesi Rus vakayinâmelerinde asırlarca utançla anılmıştır."], "sources": [{"title": "TDV İslâm Ansiklopedisi, ULUĞ MUHAMMED HAN", "url": "https://islamansiklopedisi.org.tr/ulug-muhammed-han"}]}, {"id": "kazan-suyumbike", "name": "Süyümbike Hatun", "aliases": ["Soyembika", "Melike Süyümbike"], "title": "Naibe Hanım / Han Bike", "birth": 1516, "birthNote": "Nogay Ordası'nda başkent Saraycık'ta doğdu", "death": 1554, "deathNote": "Kasimov'da sürgünde vefat etti", "reign": [1549, 1551], "reignNote": "Kazan Hanlığı'nın efsanevi kadın naibesi ve hükümdarı.", "summary": "Nogay Beyi Yusuf'un kızı, Kazan Hanı Safa Giray'ın eşi. Eşinin vefatından sonra 2 yaşındaki oğlu Ötemiş Giray adına taht naibesi olarak devleti yönetti. Moskova'nın tehditlerine karşı Kazan Kalesi'ni savundu. Rus işbirlikçisi hain beyler tarafından hileyle esir alınıp Ruslara teslim edildi. Moskova'da vaftiz edilmeye zorlandı, zorla Şah Ali ile evlendirildi. Tatar bağımsızlık mücadelesinin en kutsal sembolüdür.", "traits": ["Milli kahraman", "Fedakar anne", "Bağımsızlık sembolü", "Asil melike"], "contribution": "Kazan halkının bağımsızlık ruhunu diri tuttu; adaletli ve dirayetli bir naibelik yürüttü.", "harm": "İçteki Rus taraftarı aristokratların entrikalarını ve hanlığın teslim edilmesini engelleyemedi.", "wives": [], "children": [{"name": "Ötemiş Giray", "mother": "", "note": "Kazan'ın küçük hanı, annesiyle birlikte Moskova'ya esir götürüldü", "certainty": "kesin"}], "wars": [{"name": "Kazan Kalesi Savunması", "when": "1550", "foe": "Moskova Çarlığı (Korkunç İvan)", "result": "zafer", "note": "Korkunç İvan'ın şehri kuşatan ordusu ağır kış şartları ve Tatar taarruzuyla püskürtüldü."}], "legends": ["Kazan Kremlin'indeki meşhur 'Süyümbike Minaresi' efsanesine göre, Korkunç İvan onunla evlenmek istemiş, o da 7 günde 7 katlı minare yapılması şartını koşmuş, minare bitince kendisini minarenin tepesinden atarak can vermiştir (tarihte ise esir edilip sürülmüştür)."], "sources": [{"title": "TDV İslâm Ansiklopedisi, SÜYÜMBİKE", "url": "https://islamansiklopedisi.org.tr/suyumbike"}]}]}, {"id": "kirim-hanligi", "name": "Kırım Hanlığı", "short": "Kırım Hanlığı (Qırım Yurtı)", "aliases": ["Crimean Khanate", "Kırım Yurdu", "Qırım Hanlığı", "Giray Hanedanı"], "region": "kuzey", "start": 1441, "end": 1783, "startNote": "1441'de Hacı Giray Han'ın Altın Orda'dan ayrılarak Bahçesaray merkezli bağımsız hanlığını kurmasıyla başladı.", "endNote": "1783 yılında Rus Çariçesi II. Katerina tarafından Kırım'ın resmen ilhak edilmesiyle sona erdi.", "capital": "Bahçesaray (Çufutkale ve Hansaray)", "religion": "İslamiyet (Sünnî-Hanefî)", "confidence": "kayit", "confidenceNote": "Kırım Hanlığı mahkeme sicilleri (şer'iyye sicilleri), Osmanlı mühimme defterleri ve sefaretnâmelerle sabittir.", "summary": "Hacı Giray Han tarafından kurulan, yaklaşık 350 yıl boyunca Karadeniz'in kuzeyine, Kırım yarımadasına ve Ukrayna bozkırlarına hükmeden ulu hanlık. 1475'te Fatih Sultan Mehmed devrinde Osmanlı himayesine girdi; Osmanlı ordusunun en seçkin ve korkusuz süvari kanadını teşkil etti. 1502'de Altın Orda'yı yıktı; 1571'de I. Devlet Giray Moskova'yı ateşe verdi. Bahçesaray Hansarayı ve zengin medreseleriyle İslami kültürün kuzeydeki kalesi oldu. 1774 Küçük Kaynarca Antlaşması sonrası 1783'te Çarlık Rusyası tarafından ilhak edildi.", "legacy": "Bahçesaray Hansaray'ı, Gözleve Cuma Cami, Zincirli Medrese ve Tarak Tamga sembolüyle Kırım Tatar milli kimliğinin ebedi timsalidir.", "essay": ["Kırım Hanlığı, Altın Orda'nın çöküş devrinde Cuci soyundan gelen Hacı Giray Han'ın Bahçesaray'da bağımsızlığını ilan etmesiyle tarih sahnesine çıktı. Hacı Giray, sülalenin arması olarak 'Tarak Tamga'yı seçti.", "1475 yılında Fatih Sultan Mehmed'in veziri Gedik Ahmed Paşa Kefe'deki Ceneviz kolonilerini fethettiğinde, I. Mengli Giray Osmanlı Devleti'nin yüksek himayesini kabul etti. Bu ittifak Kırım Hanlarına özel bir statü kazandırdı; Giraylar protokolde sadrazam ile denk tutuldu, Osmanlı hanedanının tükenmesi halinde tahta geçecek yegâne soy kabul edildi. 1502'de Mengli Giray Saray şehrini zaptederek Altın Orda Devleti'ne nihai darbeyi indirdi.", "1571'de I. Devlet Giray, Korkunç İvan'ın yayılmacılığına son vermek üzere 120 bin süvariyle Moskova'yı kuşatarak yaktı ve 'Taht Algan' (Taht Alan) unvanını kazandı. Ancak 18. yüzyılda Rus Çarlığı'nın Karadeniz'e inme siyaseti neticesinde 1774 Küçük Kaynarca Antlaşması ile hanlık Osmanlı'dan koparıldı; son han Şahin Giray'ın basiretsizliği sonucu 1783'te Rusya tarafından ilhak edildi."], "sources": [{"title": "TDV İslâm Ansiklopedisi, KIRIM HANLIĞI", "url": "https://islamansiklopedisi.org.tr/kirim-hanligi"}, {"title": "TDV İslâm Ansiklopedisi, HACI GİRAY I", "url": "https://islamansiklopedisi.org.tr/haci-giray-i"}, {"title": "TDV İslâm Ansiklopedisi, DEVLET GİRAY I", "url": "https://islamansiklopedisi.org.tr/devlet-giray-i"}, {"title": "TDV İslâm Ansiklopedisi, MENGLİ GİRAY I", "url": "https://islamansiklopedisi.org.tr/mengli-giray-i"}], "rulers": [{"id": "kirim-haci-giray", "name": "I. Hacı Giray Han", "aliases": ["Melek Hacı Giray", "Haji Giray"], "title": "Han / Kurucu", "birth": 1397, "birthNote": "Litvanya'da sürgünde (Troki) doğdu", "death": 1466, "deathNote": "Bahçesaray yakınlarında Çufutkale'de vefat etti", "reign": [1441, 1466], "reignNote": "Kırım Hanlığı ve Giray Hanedanı'nın kurucusu.", "summary": "Kırım Tatarlarının ve Giray Hanedanı'nın atası. Kırım beylerinin ve Şirin kabilesinin davetiyle Kırım'a gelerek Altın Orda valilerini kovdu ve bağımsızlığını ilan etti. Litvanya Büyük Dükalığı ile ittifak kurdu. Bahçesaray ve Salaçık'ta Zincirli Medrese ve türbesini inşa ettirdi.", "traits": ["Kurucu lider", "Mutedil ve adil", "Halk tarafından sevilen ('Melek')"], "contribution": "350 yıl sürecek bağımsız Kırım Hanlığı'nı kurdu; Tarak Tamga'yı hanedan arması yaptı.", "harm": "Vefatından sonra oğulları arasında 10 yıl süren taht kavgası baş gösterdi.", "wives": [{"name": "Asiye Hatun", "note": "Baş hatun", "certainty": "olasi"}], "children": [{"name": "Nur Devlet", "mother": "", "note": "Kısa süre hanlık yaptı", "certainty": "kesin"}, {"name": "Haydar Han", "mother": "", "note": "Han", "certainty": "kesin"}, {"name": "I. Mengli Giray", "mother": "", "note": "Devleti kurumsallaştıran kudretli hükümdar", "certainty": "kesin"}], "wars": [{"name": "Altın Orda Kuşatması Püskürtmesi", "when": "1455", "foe": "Altın Orda Hanlığı (Seyyid Ahmed Han)", "result": "zafer", "note": "Kırım'ı istilaya gelen Seyyid Ahmed Han mağlup edilerek esir alındı."}], "legends": ["Adaleti ve dindarlığı sebebiyle Kırım halkı tarafından kendisine 'Melek' lakabının verildiği kaydedilir."], "sources": [{"title": "TDV İslâm Ansiklopedisi, HACI GİRAY I", "url": "https://islamansiklopedisi.org.tr/haci-giray-i"}]}, {"id": "kirim-mengli-giray", "name": "I. Mengli Giray Han", "aliases": ["Mengli I Giray"], "title": "Uluğ Han / Padişah", "birth": 1445, "birthNote": "Kırım'da doğdu", "death": 1515, "deathNote": "Bahçesaray'da vefat etti, Salaçık Türbesi'ndedir", "reign": [1467, 1515], "reignNote": "Fatih Sultan Mehmed ile ittifak kuran ve Altın Orda'yı yıkan büyük hükümdar.", "summary": "Hacı Giray'ın oğlu. 1475'te Gedik Ahmed Paşa'nın Kefe fethinden sonra Fatih Sultan Mehmed ile ebedi ittifak kurarak Osmanlı himayesini kabul etti. 1502'de Saray şehrini yerle bir ederek 300 yıllık Altın Orda Hanlığı'na son verdi. Kızı Ayşe Hafsa Sultan'ı Şehzade Selim (Yavuz Sultan Selim) ile evlendirdi; Kanunî Sultan Süleyman'ın dedesidir.", "traits": ["Büyük siyasetçi", "Stratejist", "İmar hamisi", "Sadık müttefik"], "contribution": "Kırım Hanlığı'nı kurumsallaştırdı; Zincirli Medrese'yi tamamladı; Altın Orda'ya son vererek Kırım'ı kuzeyin tek meşru gücü yaptı.", "harm": "Altın Orda'nın yıkılması ilerleyen asırlarda Rus knezliklerinin doğuya doğru yayılmasının önündeki en büyük engeli kaldırmış oldu.", "wives": [{"name": "Nursultan Hatun", "note": "Kazan Hanı Halil ve İbrâhim'in eski eşi, diplomatik evlilik", "certainty": "kesin"}], "children": [{"name": "I. Mehmed Giray", "mother": "", "note": "Babasından sonra tahta geçen fatih han", "certainty": "kesin"}, {"name": "I. Saadet Giray", "mother": "", "note": "Han", "certainty": "kesin"}, {"name": "I. Sahib Giray", "mother": "", "note": "Kazan ve Kırım Hanı", "certainty": "kesin"}, {"name": "Ayşe Hafsa Sultan", "mother": "", "note": "Yavuz Sultan Selim'in eşi, Kanunî Sultan Süleyman'ın annesi (Valide Sultan)", "certainty": "kesin"}], "wars": [{"name": "Saray Kuşatması ve Fethi", "when": "1502", "foe": "Altın Orda Devleti (Şeyh Ahmed Han)", "result": "zafer", "note": "Başkent Saray yerle bir edildi, Altın Orda Devleti tarihe karıştı."}], "legends": ["Kızı Ayşe Hafsa Sultan'ın Manisa'da şifa kaynağı Mesir Macunu geleneğini başlatan muhterem valide sultan olması aile bağlarının canlı timsalidir."], "sources": [{"title": "TDV İslâm Ansiklopedisi, MENGLİ GİRAY I", "url": "https://islamansiklopedisi.org.tr/mengli-giray-i"}]}, {"id": "kirim-devlet-giray", "name": "I. Devlet Giray Han", "aliases": ["Taht Algan Devlet Giray", "Devlet I Giray"], "title": "Han / Gazi / Taht Algan", "birth": 1512, "birthNote": "Bahçesaray'da doğdu", "death": 1577, "deathNote": "Bahçesaray'da veba sebebiyle vefat etti", "reign": [1551, 1577], "reignNote": "26 yıl saltanat sürdü; Moskova'yı yakan ünlü gazi han.", "summary": "Kırım Hanlığı'nın en muzaffer hükümdarı. Kanunî Sultan Süleyman devrinde Kırım tahtına oturdu. Çar Korkunç İvan'ın Kazan ve Astrahan'ı işgal etmesine karşı 1571'de 120 bin süvariyle Moskova Seferi'ne çıktı; şehri ve Kremlin varoşlarını ateşe vererek Çarı kaçmaya mecbur etti. 'Taht Algan' (Moskova Tahtını Alan) unvanını aldı.", "traits": ["Yenilmez akıncı", "Sert mareşal", "Gözü pek gazî", "Osmanlı'nın en sadık müttefiki"], "contribution": "Korkunç İvan'ın güneye ve Kırım'a sarkmasını 20 yıl geciktirdi; Kırım süvarisinin yenilmezliğini dünyaya kanıtladı.", "harm": "1572 Molodi Muharebesi'nde aşırı özgüven sonucu pusuya düşerek ağır süvari zayiatı verdi.", "wives": [{"name": "Ayşe Fâtıma Hatun", "note": "Baş hatun", "certainty": "olasi"}], "children": [{"name": "II. Mehmed Giray (Semiz)", "mother": "", "note": "Han", "certainty": "kesin"}, {"name": "II. İslâm Giray", "mother": "", "note": "Han", "certainty": "kesin"}, {"name": "II. Gazi Giray (Bora)", "mother": "", "note": "Meşhur şair ve bestekâr kahraman han", "certainty": "kesin"}, {"name": "I. Fetih Giray", "mother": "", "note": "Haçova fatihi han", "certainty": "kesin"}, {"name": "I. Selâmet Giray", "mother": "", "note": "Han", "certainty": "kesin"}], "wars": [{"name": "Moskova Seferi ve Yangını", "when": "1571", "foe": "Rus Çarlığı (Korkunç İvan)", "result": "zafer", "note": "Moskova surlarına girildi, şehir tamamen yakıldı; Çar İvan şehirden kaçtı."}, {"name": "Molodi Muharebesi", "when": "1572", "foe": "Rus Çarlığı (Prens Mihail Vorotınski)", "result": "yenilgi", "note": "Gulyay-gorod tahkimatına çarpan Kırım ordusu geri çekildi."}], "legends": ["Korkunç İvan'a gönderdiği mektupta 'Moskova'yı yaktım, tacını ve tahtını çiğnedim; gururundan vazgeçip Kazan ve Astrahan'ı geri ver' diye meydan okuduğu meşhurdur."], "sources": [{"title": "TDV İslâm Ansiklopedisi, DEVLET GİRAY I", "url": "https://islamansiklopedisi.org.tr/devlet-giray-i"}]}, {"id": "kirim-sahin-giray", "name": "Şahin Giray Han", "aliases": ["Shahin Giray", "Son Kırım Hanı"], "title": "Son Han", "birth": 1745, "birthNote": "Edirne'de sürgünde doğdu", "death": 1787, "deathNote": "Osmanlı'ya sığındıktan sonra Rodos'ta idam edildi", "reign": [1777, 1783], "reignNote": "Kırım Hanlığı'nın son hükümdarı.", "summary": "Kırım'ın son hanı. Petersburg ve Avrupa'da eğitim gördü. Rus Çariçesi II. Katerina'nın desteğiyle tahta çıktı. Kırım'da orduyu ve idareyi Batı tarzında modernize etmeye çalıştı; ancak halk bu reformları ve Rus kuklalığını reddederek isyan etti. 1783'te Katerina'nın Kırım'ı ilhak fermanına boyun eğdi. Pişman olarak Osmanlı'ya sığındıysa da vatanı Ruslara teslim ettiği gerekçesiyle Rodos'ta idam edildi.", "traits": ["Batı hayranı", "Halkından kopuk", "Trajik reformcu", "Basiretsiz siyasetçi"], "contribution": "Bahçesaray'da modern matbaa ve darphane kurmaya çalıştı.", "harm": "Rus politikalarına alet olarak 350 yıllık bağımsız Kırım Hanlığı'nın haritadan silinmesine ve Kırım Tatarlarının yüzyıllar sürecek sürgün ve trajedilerine sebep oldu.", "wives": [], "children": [], "wars": [{"name": "Kırım Halk İsyanı Bastırması", "when": "1781-1782", "foe": "Kırım Tatar Halkı ve Ulema", "result": "yenilgi", "note": "Halk isyan etti, Şahin Giray Rus süngüleriyle tahtta kalabildi."}], "legends": ["Tahttan feragat ettikten sonra Rusya'da ev hapsine alındığında Çariçe Katerina'nın kendisine verdiği sözleri tutmadığını anlayıp Osmanlı'ya kaçtığı bilinir."], "sources": [{"title": "TDV İslâm Ansiklopedisi, ŞÂHİN GİRAY", "url": "https://islamansiklopedisi.org.tr/sahin-giray"}]}]}, {"id": "kasim-hanligi", "name": "Kasım Hanlığı", "short": "Kasım Hanlığı (Mişer Yurdu)", "aliases": ["Kasimov Khanate", "Mişer Yurdu", "Gorodets Hanlığı"], "region": "kuzey", "start": 1452, "end": 1681, "startNote": "Kazan Hanı Uluğ Muhammed'in oğlu Kasım Han'a Oka Nehri boyundaki Gorodets kentinin yurtluk verilmesiyle kuruldu.", "endNote": "1681 yılında son naibe Fâtıma Sultan Bikem'in vefatıyla özerklik tamamen kaldırılarak Rusya'ya bağlandı.", "capital": "Kasimov (Gorodets Meşçerskiy)", "religion": "İslamiyet (Sünnî-Hanefî)", "confidence": "kayit", "confidenceNote": "Velyaminov-Zernov'un dört ciltlik Kasimov Hanlığı tetkikatı ve Rus elçilik defterleriyle sabittir.", "summary": "Moskova Knezliği sınırları içinde, Oka Irmağı üzerinde 230 yıl boyunca varlığını sürdüren özerk Müslüman-Türk hanlığı. Kurucusu Kasım Han'ın adıyla anılan başkent Kasimov'da camiler ve han türbeleri inşa edildi. Rusya'nın Kazan, Astrahan, Kırım ve Livonya ile diplomatik ve askeri ilişkilerinde kilit köprü rolü oynadı. 1681'de Rusya tarafından ilhak edildi.", "legacy": "Moskova'nın göbeğinde iki asır boyunca İslam sancağını dalgalandırdı; Kasimov Han Camii minaresi günümüze kadar ayakta kaldı.", "essay": ["Kasım Hanlığı, 1445 Suzdal zaferinden sonra Uluğ Muhammed Han'ın oğlu Kasım Han'ın Moskova Büyük Knezi II. Vasili ile yaptığı anlaşma neticesinde Oka boyunda bir tampon Türk beyliği olarak 1452'de kuruldu.", "Hanlığın ahalisini Mişer Tatarları oluşturuyordu. Kasım Hanları Rusya'nın dış ilişkilerinde ordu komutanı, elçi ve arabulucu olarak en yüksek mertebede görev yaptılar. Şah Ali Han ve Seyyid Burhan gibi hanlar döneminde hanlık Rusya içi siyasetin odak noktası oldu. 1681'de son naibe Fâtıma Sultan Bikem'in vefatıyla lağvedildi."], "sources": [{"title": "TDV İslâm Ansiklopedisi, KASIM HANLIĞI", "url": "https://islamansiklopedisi.org.tr/kasim-hanligi"}], "rulers": [{"id": "kasim-kasim-han", "name": "Kasım Han", "aliases": ["Qasim Khan"], "title": "Han / Kurucu", "birth": 1425, "birthNote": "Altın Orda bozkırında doğdu", "death": 1469, "deathNote": "Kasimov'da vefat etti", "reign": [1452, 1469], "reignNote": "Kasım Hanlığı'nın kurucusu ve isim babası.", "summary": "Uluğ Muhammed Han'ın oğlu. 1445'te Suzdal zaferinden sonra Moskova knezine yardım etti; Oka Irmağı boyundaki Gorodets şehri kendisine bağışlandı. Burada bağımsız bir Müslüman idare kurdu; şehir 'Kasimov' adını aldı.", "traits": ["Diplomat", "Usta kumandan", "Mutedil siyasetçi"], "contribution": "Rus topraklarında 230 yıl sürecek Müslüman Türk yurdunu ve hanlığını kurdu.", "harm": "Moskova ile kurduğu bağımlılık ilişkisi hanlığın tam bağımsız bir devlet olmasını engelledi.", "wives": [], "children": [{"name": "Danyal Han", "mother": "", "note": "Babasından sonra han olan oğlu", "certainty": "kesin"}], "wars": [{"name": "Moskova Taht Kavgası Müdahalesi", "when": "1449-1450", "foe": "Dmitriy Şemyaka Birlikleri", "result": "zafer", "note": "II. Vasili'nin tahtını kurtararak Oka boyunu yurtluk olarak kazandı."}], "legends": ["Kasimov kentinde 1467 yılında inşa ettirdiği taş minarenin bugün dahi Rusya Federasyonu'nda ayakta duran en eski İslam anıtlarından biri olması onun mirasıdır."], "sources": [{"title": "TDV İslâm Ansiklopedisi, KASIM HANLIĞI", "url": "https://islamansiklopedisi.org.tr/kasim-hanligi"}]}]}, {"id": "astrahan-hanligi", "name": "Astrahan Hanlığı", "short": "Astrahan (Hacı Tarhan)", "aliases": ["Astrakhan Khanate", "Hacı Tarhan Hanlığı", "Ejderhan Hanlığı"], "region": "kuzey", "start": 1465, "end": 1556, "startNote": "Altın Orda'nın dağılmasıyla Mahmud Han tarafından İdil deltasındaki Hacı Tarhan merkezli kuruldu.", "endNote": "1556 yılında Korkunç İvan komutasındaki Rus donanması ve ordusu tarafından zaptedilerek ilhak edildi.", "capital": "Hacı Tarhan (Astrahan)", "religion": "İslamiyet (Sünnî-Hanefî)", "confidence": "kayit", "confidenceNote": "Osmanlı Don-Volga kanalı layiha vesikaları ve Rus arşivleriyle sabittir.", "summary": "İdil Irmağı'nın Hazar Denizi'ne döküldüğü stratejik delta üzerinde kurulan ticaret hanlığı. Hazar deniz ticareti, ipek, tuz ve kürk yollarını denetledi. 1556'da Korkunç İvan tarafından ilhak edilerek Rusların Hazar Denizi'ne inmesine yol açtı. 1569'da Osmanlı Sadrazamı Sokullu Mehmed Paşa burayı geri almak ve Rus yayılmasını kesmek için Don-Volga Kanalı Seferi'ni başlattı.", "legacy": "Don-Volga Kanal projesine ilham kaynağı oldu; Hazar-İdil ticaret havzasını asırlarca canlandırdı.", "essay": ["Astrahan Hanlığı, Altın Orda Hanı Küçük Muhammed'in oğlu Mahmud Han tarafından İdil deltasındaki Hacı Tarhan şehrinde kuruldu. Coğrafi konumu sebebiyle Asya, Rusya, Kafkasya ve İran ticaretinin kilit düğüm noktasıydı.", "Hanlık, Kırım Hanlığı ve Nogay Ordası'nın sürekli siyasi çekişmelerine sahne oldu. 1556'da Korkunç İvan'ın nehir donanması şehri işgal etti. Osmanlı Devleti 1569'da Kırım Hanı Devlet Giray ve Kasım Paşa komutasında Don-Volga Kanalı Projesi ile Astrahan'ı geri almayı hedeflediyse de kış şartları ve Kırım Hanı'nın isteksizliği sebebiyle sefer tamamlanamadı."], "sources": [{"title": "TDV İslâm Ansiklopedisi, ASTRAHAN HANLIĞI", "url": "https://islamansiklopedisi.org.tr/astrahan-hanligi"}], "rulers": [{"id": "astrahan-mahmud-han", "name": "Mahmud Han", "aliases": ["Mahmud bin Küçük"], "title": "Han / Kurucu", "birth": 1430, "birthNote": "Saray şehrinde doğdu", "death": 1476, "deathNote": "Hacı Tarhan'da vefat etti", "reign": [1465, 1476], "reignNote": "Astrahan Hanlığı'nın kurucusu.", "summary": "Altın Orda Hanı Küçük Muhammed'in oğlu. Kardeşi Ahmed Han ile anlaşamayarak Hacı Tarhan'a çekildi ve bağımsız Astrahan Hanlığı'nı kurdu. Hazar ticaretini organize etti.", "traits": ["Ticaret ehli", "Diplomat", "Mutedil lider"], "contribution": "Hacı Tarhan'ı Doğu ile Batı arasında uluslararası ticaret limanına dönüştürdü.", "harm": "Askeri kuvvetini zayıf tutarak hanlığı komşu güçlerin nüfuz mücadelesine açık bıraktı.", "wives": [], "children": [{"name": "Kasım Han", "mother": "", "note": "Babasından sonra tahta geçen han", "certainty": "kesin"}], "wars": [{"name": "Hacı Tarhan Savunması", "when": "1468", "foe": "Altın Orda Ordusu (Ahmed Han)", "result": "zafer", "note": "Kardeşinin şehri alma girişimi püskürtüldü."}], "legends": ["Hacı Tarhan şehrinin adının buraya yerleşip vergiden muaf tutulan kutlu bir derviş olan 'Hacı Tarhan'dan geldiği anlatılır."], "sources": [{"title": "TDV İslâm Ansiklopedisi, ASTRAHAN HANLIĞI", "url": "https://islamansiklopedisi.org.tr/astrahan-hanligi"}]}]}, {"id": "kazak-hanligi", "name": "Kazak Hanlığı", "short": "Kazak Hanlığı (Qazaq Eli)", "aliases": ["Kazakh Khanate", "Qazaq Khandygy", "Kazak Eli"], "region": "kuzey", "start": 1465, "end": 1847, "startNote": "1465'te Kerey Han ve Canıbek Han'ın Ebulhayr Han'dan ayrılarak Yedisu bölgesinde bağımsızlık ilan etmesiyle kuruldu.", "endNote": "1847 yılında son bağımsız han Kenesarı Han'ın şehit düşmesi ve Rus Çarlığı'nın bozkırı ilhakıyla sona erdi.", "capital": "Türkistan (Yesi), Sıgnak, Sozak", "religion": "İslamiyet (Sünnî-Hanefî)", "confidence": "kayit", "confidenceNote": "Mirza Muhammed Haydar Duğlat (Târîh-i Reşîdî), Kadir Ali Bey (Câmiu't-Tevârîh) ve Rus arşivleriyle sabittir.", "summary": "15. yüzyıl ortalarında Özbek Ebulhayr Han'a isyan eden Kerey ve Canıbek Hanlar öncülüğünde Yedisu ve Çu vadilerinde kurulan bağımsız Türk devleti. 'Kazak' (hür, başına buyruk, yiğit) adını alan halk, bozkır Türk kültürünü ve Yesevî İslam geleneğini yaşattı. Kasım Han devrinde sınırları Hazar'dan Balkaş'a genişledi ve nüfusu 1 milyonu aştı. Üç Cüz (Ulu, Orta, Küçük Cüz) idari yapısıyla yönetildi. 18. yüzyılda Abılay Han Cungar istilasını kırarak ülkeyi birleştirdi. 1847'de Rus Çarlığı işgaliyle son buldu.", "legacy": "Modern Kazakistan devletinin doğrudan tarihi ve kültürel atasıdır; zengin bozkır epik geleneği (akınlar, cıravlar) ve töresi günümüze taşınmıştır.", "essay": ["Kazak Hanlığı'nın doğuşu, bozkır Türk halklarının hürriyet arayışının timsalidir. 1465-1466 civarında Şeybânî Ebulhayr Han'ın baskıcı yönetimine karşı çıkan Cuci soyundan Kerey ve Canıbek Hanlar, kendilerine bağlı boylarla Moğolistan Hanı Esen Buğa'nın topraklarına göç ederek Çu vadisinde bağımsız sancak açtılar.", "Kasım Han (1511-1521) döneminde Kazak Hanlığı Avrasya sahnesine büyük güç olarak çıktı. 'Kasım Han'ın Kaşka Yolu' (Qasym Khannyn Qasqa Zholy) adı verilen ilk Kazak töre kanunnamesi yürürlüğe girdi. 17. yüzyıl sonlarında Cungar (Kalmuk) istilası 'Aktaban Şubırındı' (Büyük Felaket) adıyla Kazak bozkırını sarstıysa da Abılay Han önderliğinde Anırakay Zaferi ile Cungarlar püskürtüldü.", "19. yüzyılda Rus Çarlığı bozkırı kalelerle kuşatarak cüzleri yutmaya başladı. Son Han Kenesarı Kasımoğlu (1841-1847), 10 yıl boyunca Rus sömürgeciliğine karşı gerilla ve meydan savaşı yürüterek destan yazdı; 1847'de şehit edilmesiyle hanlık devri kapandı."], "sources": [{"title": "TDV İslâm Ansiklopedisi, KAZAKLAR", "url": "https://islamansiklopedisi.org.tr/kazaklar"}, {"title": "TDV İslâm Ansiklopedisi, ABILAY HAN", "url": "https://islamansiklopedisi.org.tr/abilay-han"}, {"title": "TDV İslâm Ansiklopedisi, KASIM HAN", "url": "https://islamansiklopedisi.org.tr/kasim-han--kazak"}], "rulers": [{"id": "kazak-kerey-canibek", "name": "Kerey Han ve Canıbek Han", "aliases": ["Girey Han ve Canıbek Han"], "title": "Müşterek Hanlar / Kurucular", "birth": 1420, "birthNote": "Deşt-i Kıpçak bozkırında doğdular", "death": 1480, "deathNote": "Yedisu bölgesinde vefat ettiler", "reign": [1465, 1480], "reignNote": "Kazak Hanlığı'nın ortaklaşa kurucusu iki büyük han.", "summary": "Cuci Han'ın torunları. Şeybânî Ebulhayr Han'ın despotluğuna başkaldırarak 200 bin göçebeyle birlikte Çu ve Kozybasi vadilerine göçtüler. 'Kazak' (hür ve serbest) kimliğini devletleştirdiler.", "traits": ["Özgürlük öncüsü", "Bozkır töresi koruyucusu", "Cesur diplomat"], "contribution": "Kazak milletinin ve devletinin temellerini attılar; bozkır boylarını hürriyet sancağı altında topladılar.", "harm": "Bozkır boylarının bölünmesine ve Şeybânî Özbekleri ile uzun kanlı mücadelelere yol açtı.", "wives": [], "children": [{"name": "Burunduk Han", "mother": "", "note": "Kerey Han'ın oğlu, sonraki han", "certainty": "kesin"}, {"name": "Kasım Han", "mother": "", "note": "Canıbek Han'ın oğlu, devleti imparatorluk yapan hükümdar", "certainty": "kesin"}], "wars": [{"name": "Çu Vadisi Bağımsızlık Savaşı", "when": "1465-1468", "foe": "Özbek Hanlığı (Ebulhayr Han)", "result": "zafer", "note": "Ebulhayr Han'ın seferi başarısız oldu, Kazak Hanlığı bağımsızlığını pekiştirdi."}], "legends": ["Tarihçi Mirza Haydar Duğlat'ın Târîh-i Reşîdî adlı eserinde 'Kazak sultanlarının hükümranlığı 870 (1465-66) yılında başladı' kaydı bağımsızlığın tescili sayılır."], "sources": [{"title": "TDV İslâm Ansiklopedisi, KAZAKLAR", "url": "https://islamansiklopedisi.org.tr/kazaklar"}]}, {"id": "kazak-kasim", "name": "Kasım Han", "aliases": ["Qasym Khan"], "title": "Han / Kanun Koyucu", "birth": 1445, "birthNote": "Sıgnak bozkırında doğdu", "death": 1521, "deathNote": "Başkent Saraycık'ta vefat etti ve orada defnedildi", "reign": [1511, 1521], "reignNote": "Kazak Hanlığı'nı Avrasya'nın en güçlü bozkır devletine dönüştürdü.", "summary": "Canıbek Han'ın oğlu. Hanlığın sınırlarını Hazar Denizi'nden Balkaş Gölü'ne, İdil nehrinden Seyhun'a kadar genişletti. Ordusunu 300 bin ata çıkardı, nüfus 1 milyonu aştı. 'Kasım Han'ın Kaşka Yolu' kanunnamesini hazırladı.", "traits": ["Büyük kanun koyucu", "Usta kumandan", "Merhametli ve kudretli"], "contribution": "İlk yazılı Kazak kanunnamesini (Töre) yürürlüğe koydu; devleti uluslararası alanda Moskova ve Safevîler nezdinde tanıttı.", "harm": "Ölümünün ardından oğulları ve boy beyleri arasında geçici otorite boşluğu yaşandı.", "wives": [], "children": [{"name": "Mamak Han", "mother": "", "note": "Kısa süre hanlık yaptı", "certainty": "kesin"}, {"name": "Haknazar Han", "mother": "", "note": "Devleti tekrar toparlayan büyük han", "certainty": "kesin"}], "wars": [{"name": "Sayram ve Taşkent Seferleri", "when": "1512-1513", "foe": "Şeybânîler Devleti (Muhammed Şeybânî mirasçıları)", "result": "zafer", "note": "Seyhun boyundaki stratejik kaleler ve ticaret şehirleri Kazak hakimiyetine girdi."}], "legends": ["Bâbür Şah'ın hatıratında 'Kasım Han gibi kudretli bir hükümdar Cuci ulusunda Batu Han'dan sonra görülmedi' diye övdüğü nakledilir."], "sources": [{"title": "TDV İslâm Ansiklopedisi, KASIM HAN", "url": "https://islamansiklopedisi.org.tr/kasim-han--kazak"}]}, {"id": "kazak-abilay", "name": "Abılay Han", "aliases": ["Abilmansur", "Ablai Khan"], "title": "Büyük Han / Bozkır Kaplanı", "birth": 1711, "birthNote": "Türkistan bozkırında doğdu", "death": 1781, "deathNote": "Arıs Irmağı boyunda Taşkent yakınlarında vefat etti; Yesi'de Hoca Ahmed Yesevî Türbesi'ne defnedildi", "reign": [1771, 1781], "reignNote": "Üç Kazak Cüzü'nün müşterek ulu hanı.", "summary": "18. yüzyılda Üç Cüz'ü birleştiren dahi lider. Gençliğinde 'Sabaalak' adıyla çobanlık yaptı, Cungar istilasına karşı teke tek dövüşte Cungar noyonu Şarış'ı öldürerek kahramanlaştı. Kalmukları mağlup ederek toprakları geri aldı. Rus Çarlığı ve Çin Mançu İmparatorluğu arasında usta bir denge politikası güttü.", "traits": ["Manevi önder", "Askeri deha", "Denge ustası diplomat", "Halk aşığı"], "contribution": "Cungar soykırım ve istila tehdidini bertaraf etti; Kazak toprak bütünlüğünü sağladı; Ahmed Yesevî türbesini ihya etti.", "harm": "Rusya ile yapılan taktiksel anlaşmalar ileride Çarlık ordularının bozkırda kale hatları kurmasını engelleyemedi.", "wives": [{"name": "Babak Hanım", "note": "Baş eşi", "certainty": "olasi"}], "children": [{"name": "Vali Han", "mother": "", "note": "Orta Cüz Hanı", "certainty": "kesin"}, {"name": "Kasım Sultan", "mother": "", "note": "Kenesarı Han'ın babası", "certainty": "kesin"}], "wars": [{"name": "Anırakay Muharebesi", "when": "1729-1730", "foe": "Cungar Hanlığı (Kalmuklar)", "result": "zafer", "note": "Balkaş Gölü güneyinde Cungar ordusu ezildi, 'Aktaban Şubırındı' felaketi son buldu."}], "legends": ["Yesi'deki Hoca Ahmed Yesevî türbesinde Üç Cüz'ün aksakalları ve biy'leri tarafından beyaz keçe üzerine oturtulup göğe kaldırılarak 'Ulu Han' ilan edilmiştir."], "sources": [{"title": "TDV İslâm Ansiklopedisi, ABILAY HAN", "url": "https://islamansiklopedisi.org.tr/abilay-han"}]}, {"id": "kazak-kenesari", "name": "Kenesarı Han", "aliases": ["Kenesary Kasymov", "Son Han"], "title": "Son Bağımsız Kazak Hanı / Şehid", "birth": 1802, "birthNote": "Kokşetav bozkırında doğdu", "death": 1847, "deathNote": "Kırgız dağlarında Maitobe mevkiinde pusuya düşürülerek şehit edildi", "reign": [1841, 1847], "reignNote": "1841'de tüm cüzlerin temsilcileri tarafından han seçildi; 10 yıl Rus işgaline direndi.", "summary": "Abılay Han'ın torunu. Rus Çarlığı'nın Kazak bozkırındaki hanlık sistemini kaldırıp sömürge kaleleri kurmasına karşı 1837-1847 yılları arasında 10 yıl süren destansı bir bağımsızlık savaşı yürüttü. Rus tahkimatlarını bastı, Hokand Hanlığı ile savaştı. 1847'de Rus kışkırtmasıyla Kırgız manapları tarafından tuzağa düşürülüp şehit edildi.", "traits": ["Yılmayan bağımsızlık savaşçısı", "Sert disiplinli başbuğ", "Halk kahramanı"], "contribution": "Kazakların milli bağımsızlık bilincini ebedileştirdi; Rus istilasına karşı tek vücut direniş sembolü oldu.", "harm": "Kırgız kabileleriyle diplomatik uzlaşma sağlayamayarak kardeş kavgasına girdi ve ordusunu kaybetti.", "wives": [{"name": "Kunimcan Hatun", "note": "Sadık eşi ve mücadele yoldaşı", "certainty": "kesin"}], "children": [{"name": "Sıdık Sultan (Sadyk)", "mother": "Kunimcan Hatun", "note": "Babasının intikamı için Ruslara ve Hokand'a karşı savaşan kahraman", "certainty": "kesin"}], "wars": [{"name": "Akmeşit ve Sozak Kuşatması", "when": "1841", "foe": "Hokand Hanlığı ve Rus İleri Karakolları", "result": "zafer", "note": "Kaleler zaptedildi, güney Kazak boyları kurtarıldı."}, {"name": "Maitobe Muharebesi", "when": "1847", "foe": "Çarlık Destekli Kırgız Manap Birlikleri", "result": "yenilgi", "note": "Kenesarı Han kuşatıldı ve 32 yiğidiyle birlikte son nefesine kadar savaşarak şehit düştü."}], "legends": ["Kenesarı Han'ın kesik başının Rusya'ya götürülerek Petersburg'da Çara sunulduğu ve Hermitage Müzesi depolarında saklandığı iddiaları Kazakistan'da halen canlı bir milli meseledir."], "sources": [{"title": "TDV İslâm Ansiklopedisi, KAZAKLAR", "url": "https://islamansiklopedisi.org.tr/kazaklar"}]}]}, {"id": "sibir-hanligi", "name": "Sibir Hanlığı", "short": "Sibir Hanlığı (Tümen Yurdu)", "aliases": ["Sibir Khanate", "Tümen Hanlığı", "İsker Hanlığı", "Sibir Yurtı"], "region": "kuzey", "start": 1468, "end": 1598, "startNote": "Batı Sibirya'da İrtiş ve Tobol nehirleri havzasında İbak Han ve Taibuga sülalesi tarafından kuruldu.", "endNote": "1598 Irmak Muharebesi sonrası son han Küçüm Han'ın çekilmesi ve Rus Çarlığı ilhakıyla sona erdi.", "capital": "Çingi-Tura (Tümen) ve İsker (Kaşlık)", "religion": "İslamiyet (Sünnî-Hanefî) ve Şamanizm", "confidence": "kayit", "confidenceNote": "Stroganov ve Remezov Sibirya kronikleri ve Buhara elçilik kayıtlarıyla sabittir.", "summary": "Tarihte 'Sibirya' coğrafyasına adını veren tek Müslüman-Türk devleti. Batı Sibirya düzlüklerinde, İrtiş ve Tobol ırmakları boyunda hüküm sürdü. Küçüm Han devrinde Buhara'dan din âlimleri ve şeyhler getirtilerek bölge halkları (Tatarlar, Hantılar, Mansiler) arasında İslamiyet hızla yayıldı. 1581'de Rus Kazak atamanı Yermak'ın istilasına karşı Küçüm Han 17 yıl boyunca amansız bir gerilla ve meydan savaşı verdi; Yermak'ı İrtiş Nehri'nde boğdurarak intikam aldı. 1598'de yıkıldı.", "legacy": "Uçsuz bucaksız Sibirya kıtasına adını mühürledi; kutup dairesine yakın topraklarda İslam medeniyetinin meşalesini yaktı.", "essay": ["Sibir Hanlığı, Altın Orda'nın dağılmasıyla Batı Sibirya'nın orman ve tayga kuşağında kuruldu. Hanlık başkenti önce Çingi-Tura (bugünkü Tümen), ardından İrtiş kıyısındaki korunaklı İsker (Kaşlık / Sibir) şehri oldu.", "Hanlığın en büyük hükümdarı Şeybânî soyundan gelen Küçüm Han (1563-1598) oldu. Küçüm Han, tebaası arasında İslamiyeti samimiyetle yaydı. Ancak Çar Korkunç İvan'ın fermanı ve zengin Stroganov tüccarlarının finansmanıyla donatılan Kazak Atamanı Yermak Timofeyeviç, 1581'de ateşli silahlarla Sibirya'yı istila etti.", "Küçüm Han, başkenti İsker'i kaybetmesine rağmen teslim olmadı; taygalarda 17 yıl süren destansı bir direniş örgütledi. 1585'te gece baskınıyla Yermak'ın birliğini kılıçtan geçirdi; zırhıyla İrtiş'e atlayan Yermak boğuldu. Ancak Rus takviye orduları karşısında 1598'de son savaşını kaybeden ihtiyar Küçüm Han bozkıra çekildi ve hanlık çöktü."], "sources": [{"title": "TDV İslâm Ansiklopedisi, SİBİR HANLIĞI", "url": "https://islamansiklopedisi.org.tr/sibir-hanligi"}, {"title": "TDV İslâm Ansiklopedisi, KÜÇÜM HAN", "url": "https://islamansiklopedisi.org.tr/kucum-han"}], "rulers": [{"id": "sibir-kucum-han", "name": "Küçüm Han", "aliases": ["Kuchum Khan", "Kocum Han"], "title": "Han / Gazi / Sibirya Mücahidi", "birth": 1515, "birthNote": "Aral bozkırında doğdu", "death": 1605, "deathNote": "Buhara bozkırında Nogaylar arasında vefat etti", "reign": [1563, 1598], "reignNote": "35 yıl saltanat sürdü; Yermak'a karşı Sibirya'yı savunan efsanevi han.", "summary": "Sibir Hanlığı'nın en şanlı hükümdarı. Buhara Emiri Abdullah Han'ın desteğiyle tahta çıktı; Sibirya'da camiler ve medreseler açtı. Rus Çarlığı'nın paralı atamanı Yermak'ın ateşli silahlı Kazak ordusuna karşı 17 yıl savaştı. 1585'te Vagay Nehri baskınında Yermak'ı nehirde boğdurdu. Gözleri kör olana ve son askeri şehit düşene kadar Çarlığa boyun eğmedi.", "traits": ["Yılmayan mücahid", "Dindar hami", "Cesur başbuğ", "Vatanperver"], "contribution": "Sibirya'da İslamiyet'in kök salmasını sağladı; Rus istilasına karşı eşsiz bir direniş destanı bıraktı.", "harm": "Ateşli silahlara karşı ordusunun geleneksel ok ve kılıç taktiğinde geç kalması mağlubiyeti kaçınılmaz kıldı.", "wives": [{"name": "Süzenge Hatun", "note": "İsker savunmasında kahramanca direnen ve esir düşmemek için canına kıyan baş hatun", "certainty": "kesin"}], "children": [{"name": "Ali Han", "mother": "", "note": "Babasından sonra direnişi sürdüren oğlu", "certainty": "kesin"}, {"name": "Kanay Han", "mother": "", "note": "Sibirya şehzadesi", "certainty": "kesin"}, {"name": "İşim Sultan", "mother": "", "note": "Şehzade", "certainty": "kesin"}], "wars": [{"name": "Çuvaş Burnu Muharebesi", "when": "1582", "foe": "Rus Çarlığı Kazakları (Ataman Yermak)", "result": "yenilgi", "note": "Ateşli tüfeklerin gürültüsü ve etkisi karşısında İsker tahliye edildi."}, {"name": "Vagay Irmağı Gece Baskını", "when": "1585", "foe": "Rus Çarlığı Kazak Birliği (Ataman Yermak)", "result": "zafer", "note": "Yermak'ın kampı gece basıldı; Çarın hediye ettiği çifte ağır zırhı taşıyan Yermak nehre atlayıp boğuldu."}, {"name": "Irmak Muharebesi", "when": "1598", "foe": "Rus Çarlığı Ordusu (Voyvoda Voyeykov)", "result": "yenilgi", "note": "Küçüm Han'ın son ordusu dağıldı, ailesi esir alındı, kendisi bozkıra çekildi."}], "legends": ["Çar Boris Godunov'un kendisine teslim olması halinde sarayında hürmet göreceği teklifini 'Ben hür doğdum, bir kula kul olarak ölemem; gözlerim görmez oldu ama kalbim hürdür' diyerek reddetmesi destanlaşmıştır."], "sources": [{"title": "TDV İslâm Ansiklopedisi, KÜÇÜM HAN", "url": "https://islamansiklopedisi.org.tr/kucum-han"}]}]}, {"id": "buyuk-selcuklu", "name": "Büyük Selçuklu İmparatorluğu", "short": "Büyük Selçuklu", "aliases": ["Selçuklular", "Selçuklu Devleti", "Seljuq Empire"], "region": "iran", "start": 1040, "end": 1194, "startNote": "1040 Dandanakan Zaferi ile Gazneliler mağlup edilerek Tuğrul Bey adına Nişabur'da hutbe okutuldu.", "endNote": "1194 yılında son Irak Selçuklu Sultanı III. Tuğrul'un Harzemşah Tekiş'e yenilip öldürülmesiyle hanedan sona erdi.", "capital": "Nişabur, Rey, İsfahan ve Merv", "religion": "İslamiyet (Sünnî-Hanefî)", "confidence": "kayit", "confidenceNote": "Dönemin çağdaş vekâyinâmeleri (Râvendî, İbnü'l-Esîr, Ahbârü'd-Devleti's-Selcûkıyye) ile sabittir.", "summary": "Oğuzların Kınık boyuna mensup Selçuk Bey'in torunları Tuğrul ve Çağrı beyler tarafından temelleri atılan, 1040 Dandanakan Zaferi ile kurulan ulu imparatorluk. 1055'te Bağdat'a giren Tuğrul Bey Şii Büveyhî tahakkümünü kırıp Abbasi Halifeliği'ni himayesine aldı; halife tarafından 'Doğunun ve Batının Hükümdarı' ilan edildi. Sultan Alparslan 1071 Malazgirt Zaferi ile Anadolu'nun kapılarını Türk milletine ebediyen açtı; Sultan Melikşah ve dahi Vezir Nizâmülmülk devrinde sınırları Kaşgar'dan Boğaziçi'ne ve Mısır'a kadar ulaştı.", "legacy": "İslam dünyasında Şii Fatımi ve Büveyhi baskısını kırarak Sünnî birliği yeniden kurdu. Nizamiye medreseleriyle ilim ve düşünce hayatına çağ atlattı. Anadolu'yu kalıcı Türk vatanı yapacak tarihi süreci başlattı.", "essay": ["Büyük Selçuklu Devleti, Seyhun nehri boylarında Cend şehrinde İslamiyet'i kabul eden Kınık boyu beyi Selçuk Bey'in torunları Tuğrul ve Çağrı beylerin Horasan'a gelişiyle kuruldu. Karahanlı ve Gazneli baskılarına rağmen Horasan halkının desteğini alan Selçuklular, 23 Mayıs 1040'ta Dandanakan Muharebesi'nde Gazneli Sultan Mesud'un fil destekli dev ordusunu kesin bir hezimete uğrattı. Bu zaferle Horasan'da bağımsız Büyük Selçuklu Devleti kuruldu; Tuğrul Bey sultan, kardeşi Çağrı Bey ise doğu kanadı Meliki oldu.", "Tuğrul Bey, 1055'te Abbasi Halifesi Kaim-Biemrillâh'ın çağrısıyla Bağdat'a girerek Şii Büveyhîler hanedanına son verdi. Halife tarafından 'Doğunun ve Batının Hükümdarı' unvanı verilerek İslam dünyasının siyasi ve askeri liderliği Türklere geçti. Tuğrul Bey'in çocuğu olmadığından yerine Çağrı Bey'in oğlu Alparslan tahta çıktı. Alparslan, Kafkasya ve Gürcistan seferlerinden sonra 26 Ağustos 1071'de Malazgirt Meydan Muharebesi'nde Bizans İmparatoru IV. Romanos Diogenes'i ordusuyla birlikte esir alarak dünya tarihini değiştirdi ve Türklerin Anadolu fethine izin verdi.", "Alparslan'ın oğlu Sultan Melikşah ve efsanevi Vezir Nizâmülmülk'ün 20 yıllık idaresi (1072-1092) Selçuklu İmparatorluğu'nun altın çağı oldu. Şam, Kudüs, Yemen, Hicaz, Umman ve Diyarbekir Selçuklu topraklarına katıldı. Bağdat, Nişabur ve İsfahan'da kurulan Nizâmiye Medreseleri dönemin en büyük âlimlerini (İmam Gazâlî dahil) yetiştirdi; Celâlî takvimi hazırlandı. Ancak Nizâmülmülk'ün Bâtınî (Haşhaşî) fedailerince şehit edilmesi ve hemen ardından Melikşah'ın vefatı devleti sarsıcı bir taht kavgasına sürükledi.", "Melikşah'ın eşi Terken Hatun'un küçük oğlu Mahmud'u tahta çıkarma hırsı, Berkyaruk ile kanlı bir mücadele başlattı. Berkyaruk ve Muhammed Tapar dönemleri taht kavgaları ve Haçlı Seferleri'nin yarattığı kaosla geçti. Son büyük sultan Sencer (1118-1157), Horasan'da devleti yeniden toparladıysa da 1141 Katvan Savaşı'nda gayrimüslim Karahıtaylara yenildi. 1153'te vergi yüzünden isyan eden Oğuzlara esir düşen Sencer'in kurtulduktan kısa süre sonra 1157'de ölümüyle imparatorluğun merkezi gövdesi çöktü."], "sources": [{"title": "TDV İslâm Ansiklopedisi, SELÇUKLULAR", "url": "https://islamansiklopedisi.org.tr/selcuklular"}, {"title": "TDV İslâm Ansiklopedisi, TUĞRUL BEY", "url": "https://islamansiklopedisi.org.tr/tugrul-bey"}, {"title": "TDV İslâm Ansiklopedisi, ALPARSLAN", "url": "https://islamansiklopedisi.org.tr/alparslan"}, {"title": "TDV İslâm Ansiklopedisi, MELİKŞAH", "url": "https://islamansiklopedisi.org.tr/meliksah"}, {"title": "TDV İslâm Ansiklopedisi, SENCER", "url": "https://islamansiklopedisi.org.tr/sencer"}], "rulers": [{"id": "buyuk-selcuklu-tugrul", "name": "Tuğrul Bey", "aliases": ["Rükneddîn Tuğrul Bey", "Muhammed Tuğrul", "Toghrul Beg"], "title": "Sultan / Doğunun ve Batının Hükümdarı", "birth": 990, "birthNote": "Yaklaşık 990 yılında doğdu", "death": 1063, "deathNote": "Rey yakınlarında Tecriş'te vefat etti", "reign": [1040, 1063], "reignNote": "1040 Dandanakan Zaferi'nden vefatına kadar 23 yıl.", "summary": "Büyük Selçuklu İmparatorluğu'nun kurucu sultanı. Kardeşi Çağrı Bey ile birlikte Gaznelileri yenerek devleti kurdu. 1055'te Bağdat'a girerek Şii Büveyhî hanedanını yıktı ve Abbasi halifesini himaye altına aldı. Halife tarafından 'Doğunun ve Batının Sultanı' ilan edildi.", "traits": ["Devlet kurucu önder", "Dindar ve adil", "Yüksek siyasi basiret"], "contribution": "Selçuklu devlet teşkilatını kurdu, İslam hilafetinin himayesini Türk milletine kazandırdı.", "harm": "Çocuğu olmadığı için ölümünden sonra taht krizine yol açtı.", "wives": [{"name": "Altuncan Hatun", "note": "Tuğrul Bey'in devlet işlerinde en güvendiği dirayetli eşi", "certainty": "kesin"}, {"name": "Seyyide Fâtıma Hatun", "note": "Abbasi Halifesi Kaim-Biemrillâh'ın kızı", "certainty": "kesin"}], "children": [], "wars": [{"name": "Dandanakan Meydan Muharebesi", "when": "1040", "foe": "Gazneli Devleti (Sultan Mesud)", "result": "zafer", "note": "Gazneli ordusu imha edildi, Selçuklu devleti resmen kuruldu."}, {"name": "Pasinler Muharebesi", "when": "1048", "foe": "Bizans İmparatorluğu ve Gürcü kuvvetleri", "result": "zafer", "note": "İbrahim Yinal ve Kutalmış komutasındaki Türk ordusu Bizans'ı bozguna uğrattı."}, {"name": "Bağdat Seferi", "when": "1055", "foe": "Büveyhîler (Melikü'r-Rahîm)", "result": "zafer", "note": "Bağdat'a girildi, Büveyhî tahakkümü sona erdirildi."}], "legends": ["Bağdat'a girdiğinde halifenin huzurunda iki kılıç kuşanarak şarkın ve garbın sultanı ilan edildiği tarihi meclis."], "sources": [{"title": "TDV İslâm Ansiklopedisi, TUĞRUL BEY", "url": "https://islamansiklopedisi.org.tr/tugrul-bey"}]}, {"id": "buyuk-selcuklu-alparslan", "name": "Sultan Alparslan", "aliases": ["Ebû Şücâ‘ Muhammed Alparslan", "Alp Arslan"], "title": "Sultan / Ebû Şücâ‘", "birth": 1029, "birthNote": "Yaklaşık 1029 doğumlu", "death": 1072, "deathNote": "Barzam kalesini fethettiğinde esir komutan Yûsuf Hârizmî tarafından hançerlenerek şehit edildi", "reign": [1063, 1072], "reignNote": "9 yıllık zaferlerle dolu hükümdarlık.", "summary": "Çağrı Bey'in oğlu. Kafkasya'yı ve Ani Ermeni Krallığı'nı fethetti (1064). 26 Ağustos 1071 Cuma günü Malazgirt Ovası'nda Bizans İmparatoru Romanos Diogenes'i mağlup edip esir alarak Anadolu'nun kapılarını Türklere açtı.", "traits": ["Kahraman savaşçı", "Asil ve merhametli", "Büyük stratejist"], "contribution": "Malazgirt Zaferi ile Türk milletine Anadolu'yu ebedi yurt yaptı; Nizamülmülk'ü vezirlik makamına getirerek medreselerin önünü açtı.", "harm": "Esir aldığı kale komutanını bizzat sorgularken tedbirsiz davranması erken şehadetine yol açtı.", "wives": [{"name": "Seferiyye Hatun (Aka Hatun)", "note": "Melikşah'ın annesi", "certainty": "kesin"}], "children": [{"name": "I. Melikşah", "mother": "Seferiyye Hatun", "note": "Veliahtı ve üçüncü büyük sultan", "certainty": "kesin"}, {"name": "Tutuş", "mother": "", "note": "Suriye Selçuklu Meliki", "certainty": "kesin"}, {"name": "Tekiş", "mother": "", "note": "Horasan Meliki, isyan etti", "certainty": "kesin"}, {"name": "Arslan Argun", "mother": "", "note": "Horasan Meliki", "certainty": "kesin"}, {"name": "Ayşe Hatun", "mother": "", "note": "Karahanlı Şemsülmülk Nasr ile evlendi", "certainty": "kesin"}], "wars": [{"name": "Ani Kalesi Kuşatması ve Kafkas Seferi", "when": "1064", "foe": "Bizans ve Ermeni Krallıkları", "result": "zafer", "note": "Alınamaz denilen müstahkem Ani kalesi fethedildi, halife 'Ebü'l-Feth' unvanı verdi."}, {"name": "Malazgirt Meydan Muharebesi", "when": "1071", "foe": "Bizans İmparatorluğu (Romanos Diogenes)", "result": "zafer", "note": "Bizans ordusu imha edildi, imparator esir alındı, Anadolu'nun fethi başladı."}], "legends": ["Malazgirt sabahı beyaz elbisesini giyip 'Ölürsem kefenim bu olsun' diyerek ordusunun önünde namaz kılması ve atının kuyruğunu bizzat bağlaması destanlaşmıştır."], "sources": [{"title": "TDV İslâm Ansiklopedisi, ALPARSLAN", "url": "https://islamansiklopedisi.org.tr/alparslan"}]}, {"id": "buyuk-selcuklu-meliksah", "name": "Sultan I. Melikşah", "aliases": ["Celâlüddevle Melikşah", "Muizzüddin Melikşah"], "title": "Sultan / Celâlüddin", "birth": 1055, "birthNote": "1055 yılında doğdu", "death": 1092, "deathNote": "Bağdat'ta av seferi sonrası şüpheli şekilde 37 yaşında vefat etti", "reign": [1072, 1092], "reignNote": "20 yıl boyunca imparatorluğu en geniş sınırlarına ulaştırdı.", "summary": "Alparslan'ın oğlu. Büyük Selçuklu İmparatorluğu'nun zirve hükümdarı. Vezir Nizâmülmülk ile birlikte devleti idare etti; Suriye, Filistin, Hicaz, Yemen, Kafkaslar ve Maveraünnehir Selçuklu egemenliğine girdi. Nizamiye medreseleri ve Celâlî takvimi bu devirde tamamlandı.", "traits": ["Cihanşümul hükümdar", "İlim ve sanat hamisi", "Adil ve müşfik"], "contribution": "Devlet sınırlarını Çin'den Boğaziçi'ne ulaştırdı; kültürel ve ilmi altın çağı yaşattı.", "harm": "Eşi Terken Hatun'un entrikalarına kapılarak son döneminde Nizâmülmülk'ün azline meyledip otorite boşluğuna yol açtı.", "wives": [{"name": "Terken Hatun", "note": "Karahanlı prensesi, oğlu Mahmud'u tahta geçirmek için büyük entrikalar çevirdi", "certainty": "kesin"}, {"name": "Zübeyde Hatun", "note": "Berkyaruk'un annesi, Selçuklu soyundan", "certainty": "kesin"}], "children": [{"name": "Berkyaruk", "mother": "Zübeyde Hatun", "note": "Melikşah'tan sonraki büyük sultan", "certainty": "kesin"}, {"name": "Muhammed Tapar", "mother": "", "note": "Sultan", "certainty": "kesin"}, {"name": "Sultan Sencer (Ahmed)", "mother": "", "note": "Son büyük sultan", "certainty": "kesin"}, {"name": "I. Mahmud", "mother": "Terken Hatun", "note": "Çocuk yaşta sultan ilan edildi", "certainty": "kesin"}, {"name": "Gevher Hatun", "mother": "", "note": "Gazneli III. Mesud ile evlendirildi", "certainty": "kesin"}], "wars": [{"name": "Kavurt İsyanının Bastırılması", "when": "1073", "foe": "Kirman Meliki Kavurt Bey", "result": "zafer", "note": "Kerec muharebesinde amcası Kavurt mağlup edilerek merkezi otorite sağlandı."}, {"name": "Maveraünnehir Seferleri", "when": "1089", "foe": "Karahanlılar", "result": "zafer", "note": "Buhara, Semerkant ve Kaşgar Selçuklu hakimiyetine girdi."}], "legends": ["Akdeniz kıyısına vardığında atını denize sürüp kılıcını suya daldırarak 'Ya Rabbi! Beni dünyanın bir ucundan diğer ucuna ulaştırdın' diyerek şükür secdesine kapandığı rivayet edilir."], "sources": [{"title": "TDV İslâm Ansiklopedisi, MELİKŞAH", "url": "https://islamansiklopedisi.org.tr/meliksah"}]}, {"id": "buyuk-selcuklu-berkyaruk", "name": "Sultan Berkyaruk", "aliases": ["Rükneddîn Berkyaruk"], "title": "Sultan", "birth": 1081, "birthNote": "1081 yılında doğdu", "death": 1104, "deathNote": "Verem hastalığından 24 yaşında Berûcird yakınlarında vefat etti", "reign": [1092, 1104], "reignNote": "12 yıl taht kavgaları ve Haşhaşî suikastları arasında hükümdarlık yaptı.", "summary": "Melikşah'ın büyük oğlu. Babasının ölümü üzerine üvey annesi Terken Hatun, amcası Tutuş ve kardeşi Muhammed Tapar ile çetin taht mücadelelerine girdi. Bâtınîlerin yoğun suikastlarına ve I. Haçlı Seferi'nin yıkımına karşı devleti ayakta tutmaya çalışırken genç yaşta vefat etti.", "traits": ["Metanetli", "Talihsiz hükümdar", "Sabırlı"], "contribution": "Terken Hatun ve Tutuş isyanlarını bastırarak imparatorluğun bölünmesini bir süre engelledi.", "harm": "Kardeşi Muhammed Tapar ile giriştiği amansız iç savaş Selçuklu ordusunu tüketti; Kudüs ve Antakya'nın Haçlılar eline geçmesine müdahale edemedi.", "wives": [], "children": [{"name": "II. Melikşah", "mother": "", "note": "Çocuk yaşta kısa süre tahta oturtuldu", "certainty": "kesin"}], "wars": [{"name": "Ruyan Muharebesi", "when": "1095", "foe": "Suriye Meliki Tutuş", "result": "zafer", "note": "Amcası Tutuş öldürülerek saltanat iddiası bertaraf edildi."}, {"name": "Kardeşler İç Savaşı", "when": "1100-1104", "foe": "Muhammed Tapar ve Sencer", "result": "antlasma", "note": "Beş büyük muharebeden sonra devlet iki kardeş arasında paylaşıldı."}], "legends": ["Bâtınî fedailerinin sarayına kadar girip kendisini yaralaması üzerine zırhını elbisesinin altından hiç çıkarmadığı anlatılır."], "sources": [{"title": "TDV İslâm Ansiklopedisi, BERKYARUK", "url": "https://islamansiklopedisi.org.tr/berkyaruk"}]}, {"id": "buyuk-selcuklu-muhammed-tapar", "name": "Muhammed Tapar", "aliases": ["Gıyâseddin Muhammed Tapar"], "title": "Sultan", "birth": 1082, "birthNote": "1082 yılında doğdu", "death": 1118, "deathNote": "İsfahan'da hastalanarak vefat etti", "reign": [1105, 1118], "reignNote": "13 yıllık istikrarlı saltanat.", "summary": "Melikşah'ın oğlu. Berkyaruk'un ölümüyle tek başına tahta çıktı. Bâtınî (Alamut Haşhaşîleri) tehlikesine karşı amansız bir savaş yürüterek Şahdiz kalesini fethetti ve İbn Attâş'ı idam ettirdi. Haçlılara karşı Suriye'ye ordular sevk etti.", "traits": ["Kararlı", "Dindar", "Sert iradeli"], "contribution": "İsfahan ve civarındaki Bâtınî terörünü kökünden temizledi, merkezi idareyi güçlendirdi.", "harm": "Haçlılara karşı gönderdiği Selçuklu emirlerinin birlik kuramaması yüzünden Suriye'de kesin zafer kazanılamadı.", "wives": [{"name": "Gevher Hatun", "note": "İsmail b. Yakuti'nin kızı", "certainty": "kesin"}], "children": [{"name": "Mahmud", "mother": "", "note": "Irak Selçuklu Sultanı", "certainty": "kesin"}, {"name": "Mesud", "mother": "", "note": "Irak Selçuklu Sultanı", "certainty": "kesin"}, {"name": "Tuğrul", "mother": "", "note": "Irak Selçuklu Meliki", "certainty": "kesin"}, {"name": "Süleyman Şah", "mother": "", "note": "Sultan", "certainty": "kesin"}], "wars": [{"name": "Şahdiz Kalesi Kuşatması", "when": "1107", "foe": "Bâtınîler (İbn Attâş)", "result": "zafer", "note": "İsfahan yakınındaki Bâtınî kalesi yerle bir edildi."}, {"name": "Musul Seferi", "when": "1107", "foe": "Anadolu Selçuklu Sultanı I. Kılıç Arslan", "result": "zafer", "note": "Habur nehrinde Kılıç Arslan yenilerek nehirde boğuldu."}], "legends": [], "sources": [{"title": "TDV İslâm Ansiklopedisi, MUHAMMED TAPAR", "url": "https://islamansiklopedisi.org.tr/muhammed-tapar"}]}, {"id": "buyuk-selcuklu-sencer", "name": "Sultan Sencer", "aliases": ["Muizzüddin Ahmed Sencer", "Sultanü'l-Âzam", "Sencer"], "title": "Büyük Sultan / Sultan-ı Âzam", "birth": 1086, "birthNote": "Sincar sahrasında 1086'da doğdu", "death": 1157, "deathNote": "Merv'de 71 yaşında kederinden vefat etti", "reign": [1118, 1157], "reignNote": "1097'den itibaren Horasan meliki, 1118-1157 arasında 39 yıl Büyük Selçuklu Sultanı.", "summary": "Melikşah'ın oğlu, Selçukluların son büyük cihan sultanı. Horasan'ı merkez yaparak Gaznelileri ve Karahanlıları vassalı yaptı. 1141 Katvan Savaşı'nda gayrimüslim Karahıtaylara yenilmesiyle imparatorluk sarsıldı. 1153'te Oğuz isyanında esir düşüp üç yıl kafeste tutuldu; kaçtıktan sonra Merv'in harabelerini görüp kederinden vefat etti.", "traits": ["Ulu hakan", "Cömert", "Edebiyat ve ilim aşığı", "Devlet tecrübesi deryası"], "contribution": "Merv şehrini devrin en görkemli medeniyet merkezine dönüştürdü; 40 yıla yakın doğu İslam dünyasını korudu.", "harm": "1141 Katvan hezimeti ve Oğuzlara karşı vergi anlaşmazlığında esir düşmesi imparatorluğun kesin yıkılışına sebep oldu.", "wives": [{"name": "Türken Hatun", "note": "Karahanlı Arslan Han'ın kızı, Sencer'in baş hatunu", "certainty": "kesin"}], "children": [{"name": "İki kız evlat", "mother": "Türken Hatun", "note": "Biri Mahmud b. Muhammed Tapar ile evlendi", "certainty": "kesin"}], "wars": [{"name": "Gazne Seferi", "when": "1117", "foe": "Gazneliler (Melik Arslan)", "result": "zafer", "note": "Gazne fethedildi, Behramşah haraca bağlandı."}, {"name": "Katvan Bozkırı Muharebesi", "when": "1141", "foe": "Karahıtaylar (Gürhan)", "result": "yenilgi", "note": "Selçuklu ordusu ağır hezimete uğradı, Maveraünnehir elden çıktı."}, {"name": "Oğuz İsyanı ve Esaret", "when": "1153", "foe": "Oğuz boyları", "result": "yenilgi", "note": "Sultan esir alındı, Horasan talan edildi."}], "legends": ["Merv'deki türbesi (Devlet-hâne) Moğol istilasına kadar dünyanın sekiz harikasından biri kabul edilirdi."], "sources": [{"title": "TDV İslâm Ansiklopedisi, SENCER", "url": "https://islamansiklopedisi.org.tr/sencer"}]}]}, {"id": "ildenizli", "name": "İldenizliler", "short": "İldenizliler (Azerbaycan Atabeyliği)", "aliases": ["Azerbaycan Atabegleri", "Eldigüzîler", "Eldegüzidler"], "region": "iran", "start": 1136, "end": 1225, "startNote": "Şemseddin İldeniz'in Arran valisi tayin edilmesi ve atabeglik unvanı almasıyla kuruldu.", "endNote": "1225 yılında Harzemşah Celâleddin Mengüberti'nin Tebriz'i almasıyla tarih sahnesinden çekildi.", "capital": "Nahçıvan, Tebriz ve Hemedan", "religion": "İslamiyet (Sünnî)", "confidence": "kayit", "confidenceNote": "Râvendî, İbnü'l-Esîr, Ahbârü'd-Devleti's-Selcûkıyye ve Nesevî kronikleriyle sabittir.", "summary": "Kıpçak asıllı memlük kumandanı Şemseddin İldeniz tarafından kurulan, Arran, Azerbaycan ve Cibâl bölgesinde hüküm süren Türk devleti. Irak Selçuklu sultanlarının atabegi olarak tüm idareyi ellerine aldılar; Gürcü Krallığı'nın İslam dünyasına yönelik akınlarını durdurdular. Tebriz ve Nahçıvan'ı eşsiz mimari anıtlarla (Mümine Hatun Kümbeti) donattılar; Nizâmî-i Gencevî'yi himaye ettiler.", "legacy": "Azerbaycan'ın Türkleşmesinde ve bayındır hale gelmesinde kurucu rol oynadı. Selçuklu mimarisinin şaheseri olan Mümine Hatun Kümbeti'ni ve zengin Türk edebiyat muhitini miras bıraktı.", "essay": ["İldenizliler hanedanının kurucusu Şemseddin İldeniz, Kıpçak bozkırlarından getirilmiş bir köle iken kabiliyeti sayesinde Sultan Mesud'un takdirini kazandı ve 1136'da Arran valiliğine getirildi. Sultan II. Tuğrul'un dul eşi Mü'mine Hatun ile evlenen İldeniz, üvey oğlu Arslanşah'ı 1160 yılında Irak Selçuklu tahtına çıkararak 'Büyük Atabeg' (Atabegü'l-A'zam) unvanıyla devletin mutlak hakimi oldu.", "İldeniz'in oğlu Nusretüddin Cihan Pehlivan (1175-1186), devleti altın çağına taşıdı. Gürcü saldırılarını tamamen kırdı, Abbasi halifesinin dünyevi siyasete karışmasını engelledi ve Selâhaddîn-i Eyyûbî ile diplomatik denge kurdu. Kardeşi Kızılarslan ise 1191'de bizzat Selçuklu tahtına oturup kendisini sultan ilan etti fakat saray suikastıyla öldürüldü.", "Son dönemde tahta çıkan Ebû Bekir ve Özbek zevk ve sefahat içinde devleti zaafa uğrattı. 1220-1221 Moğol akınlarıyla sarsılan hanedan, 1225'te Tebriz'e giren Harzemşah Celâleddin tarafından ortadan kaldırıldı."], "sources": [{"title": "TDV İslâm Ansiklopedisi, İLDENİZLİLER", "url": "https://islamansiklopedisi.org.tr/ildenizliler"}, {"title": "TDV İslâm Ansiklopedisi, ŞEMSÜDDİN İLDENİZ", "url": "https://islamansiklopedisi.org.tr/ildeniz"}], "rulers": [{"id": "ildenizli-semseddin", "name": "Şemseddin İldeniz", "aliases": ["Eldigüz", "Atabeg İldeniz"], "title": "Büyük Atabeg / Atabegü'l-Âzam", "birth": null, "birthNote": "Kayıtlarda yok", "death": 1175, "deathNote": "Nahçıvan'da vefat etti", "reign": [1136, 1175], "reignNote": "1136'da Arran valiliğiyle başladı, 1160'ta Irak Selçuklu atabegi oldu.", "summary": "Kıpçak asıllı memlük kumandanı, devletin kurucusu. Irak Selçuklu tahtına üvey oğlu Arslanşah'ı çıkararak Kafkaslar'dan Hemedan'a kadar uzanan muazzam bir sahayı tek başına yönetti; Gürcüleri ağır yenilgilere uğrattı.", "traits": ["Kendi gücüyle yükselen deha", "Azimli", "Büyük fatih"], "contribution": "Azerbaycan ve Arran'da güçlü bir Türk devleti kurdu; Gürcü istilasını durdurdu.", "harm": "Irak Selçuklu hanedanını kuklaya çevirmesi Selçuklu meşruiyetini zedeledi.", "wives": [{"name": "Mümine Hatun", "note": "Sultan II. Tuğrul'un dul eşi, Arslanşah'ın annesi", "certainty": "kesin"}], "children": [{"name": "Nusretüddin Cihan Pehlivan", "mother": "Mümine Hatun", "note": "İkinci atabeg", "certainty": "kesin"}, {"name": "Muzafferüddin Kızılarslan", "mother": "Mümine Hatun", "note": "Üçüncü atabeg, sultan oldu", "certainty": "kesin"}], "wars": [{"name": "Gürcü Seferi", "when": "1163", "foe": "Gürcistan Krallığı (III. Giorgi)", "result": "zafer", "note": "Dvin şehri kurtarıldı, Gürcü ordusu hezimete uğratıldı."}, {"name": "Hemedan Harekâtı", "when": "1160", "foe": "Selçuklu muhalif emirleri", "result": "zafer", "note": "Arslanşah tahta oturtuldu."}], "legends": ["Nahçıvan'daki görkemli türbe Mümine Hatun Kümbeti onun oğulları tarafından anneleri için yaptırıldı."], "sources": [{"title": "TDV İslâm Ansiklopedisi, İLDENİZLİLER", "url": "https://islamansiklopedisi.org.tr/ildenizliler"}]}, {"id": "ildenizli-cihan-pehlivan", "name": "Nusretüddin Cihan Pehlivan", "aliases": ["Cihan Pehlivan", "Muhammed Pehlivan"], "title": "Büyük Atabeg", "birth": null, "birthNote": "Kayıtlarda yok", "death": 1186, "deathNote": "Hemedan'da hastalanarak vefat etti", "reign": [1175, 1186], "reignNote": "11 yıllık huzur ve sükun devri.", "summary": "Şemseddin İldeniz'in büyük oğlu. Irak Selçuklu Devleti'ni 11 yıl boyunca mutlak bir dirayet ve adaletle idare etti. Ülkesinde eşkıyalığı bitirdi, şairleri ve âlimleri himaye etti, devlete en güçlü dönemini yaşattı.", "traits": ["Adil hükümdar", "Pehlivan yapılı", "Diplomat"], "contribution": "İç barışı sağladı, Nizâmî-i Gencevî gibi büyük şairleri himaye etti.", "harm": "Ölümünden önce eyaletleri oğulları ve kardeşi arasında paylaştırması taht kavgalarına zemin hazırladı.", "wives": [{"name": "İnanç Hatun (Kattîbe)", "note": "Rey hakimi İnanç Sungur'un kızı", "certainty": "kesin"}], "children": [{"name": "Kutluğ İnanç", "mother": "İnanç Hatun", "note": "Atabeglik mücadelesine girdi", "certainty": "kesin"}, {"name": "Emîr-i Emîrân Ömer", "mother": "İnanç Hatun", "note": "Şehzade", "certainty": "kesin"}, {"name": "Ebû Bekir", "mother": "", "note": "Cariyeden doğma büyük oğul, atabeg oldu", "certainty": "kesin"}, {"name": "Muzafferüddin Özbek", "mother": "", "note": "Son atabeg", "certainty": "kesin"}], "wars": [{"name": "Tebriz Kuşatması", "when": "1175", "foe": "Aksunguriler (Ahmedîlîler)", "result": "zafer", "note": "Tebriz barış yoluyla teslim alınıp kardeşi Kızılarslan'a verildi."}], "legends": ["Nizâmî-i Gencevî ünlü 'Hüsrev ü Şîrîn' mesnevisini Cihan Pehlivan'a ithaf etmiştir."], "sources": [{"title": "TDV İslâm Ansiklopedisi, İLDENİZLİLER", "url": "https://islamansiklopedisi.org.tr/ildenizliler"}]}]}, {"id": "salgurlu", "name": "Salgurlular", "short": "Salgurlular (Fars Atabeyliği)", "aliases": ["Fars Atabegleri", "Salgurlular"], "region": "iran", "start": 1148, "end": 1284, "startNote": "Oğuzların Salur boyundan Sungur b. Mevdûd'un Şiraz'da bağımsızlığını ilan etmesiyle kuruldu.", "endNote": "1284 yılında Abiş Hatun'un vefatı ve İlhanlıların bölgeyi doğrudan ilhak etmesiyle sona erdi.", "capital": "Şiraz", "religion": "İslamiyet (Sünnî)", "confidence": "kayit", "confidenceNote": "Şebânkâreî, İbnü'l-Esîr, Sâdî-i Şîrâzî'nin Gülistan ve Bostan eserlerindeki ithaf kayıtlarıyla sabittir.", "summary": "Oğuzların Salur boyu tarafından Fars eyaletinde (Şiraz merkezli) kurulan Türk atabeyliği. Moğol istilası döneminde akılcı bir diplomasi takip ederek Şiraz'ı yıkımdan kurtardılar. Atabeg Sa'd b. Zengi ve Ebû Bekir devirlerinde Şiraz büyük bir kültür merkezine dönüştü; dünya edebiyatının zirvesi Sâdî-i Şîrâzî bu sarayda yetişti ve mahlasını Atabeg Sa'd'dan aldı.", "legacy": "Şiraz'ı Moğol katliamından koruyarak İran-Türk İslam medeniyetinin ve Fars edebiyatının en büyük eserlerinin doğmasını sağladı.", "essay": ["Salgurlular, Büyük Selçuklu İmparatorluğu'nun parçalanma sürecinde Oğuzların Salur boyu reisi Emîr Mevdûd'un oğlu Sungur Bey tarafından 1148'de Şiraz merkezli kuruldu.", "Atabeyliğin en meşhur hükümdarı Ebû Bekir b. Sa'd (1226-1260), Moğol istilasının dehşetini görerek Cengiz Han'a ve Hülagû'ya tabi olmayı kabul etti. Bu sayede Şiraz şehri tek bir kılıç darbesi almadan, kütüphaneleri ve medreseleriyle korundu. Ünlü şair Sâdî-i Şîrâzî, Gülistan ve Bostan eserlerini Atabeg Ebû Bekir'e ithaf etti.", "Hanedanın son hükümdarı kadın hükümdar Abiş Hatun oldu. Hülagû'nun oğlu Mengü Timur ile evlendirilen Abiş Hatun'un 1284'te Tebriz'de ölümüyle Salgurlu toprakları doğrudan İlhanlı Devleti'ne bağlandı."], "sources": [{"title": "TDV İslâm Ansiklopedisi, SALGURLULAR", "url": "https://islamansiklopedisi.org.tr/salgurlular"}], "rulers": [{"id": "salgurlu-sungur", "name": "Sungur b. Mevdûd", "aliases": ["Muzafferüddin Sungur"], "title": "Atabeg", "birth": null, "birthNote": "Kayıtlarda yok", "death": 1161, "deathNote": "Şiraz'da vefat etti", "reign": [1148, 1161], "reignNote": "13 yıl hüküm sürdü.", "summary": "Salgurlular hanedanının kurucusu. Selçuklu valisini kovarak Şiraz'da bağımsızlığını ilan etti ve Fars bölgesini hakimiyeti altına aldı.", "traits": ["Kurucu lider", "Cesur komutan"], "contribution": "Fars eyaletinde 136 yıl sürecek barış ve imar dönemini başlattı.", "harm": "Selçuklu şehzadeleri arasındaki çekişmelere müdahil oldu.", "wives": [], "children": [], "wars": [{"name": "Şiraz Kuşatması ve İstiklâl", "when": "1148", "foe": "Selçuklu Fars Emiri", "result": "zafer", "note": "Şiraz zaptedildi, Salgurlu atabeyliği kuruldu."}], "legends": [], "sources": [{"title": "TDV İslâm Ansiklopedisi, SALGURLULAR", "url": "https://islamansiklopedisi.org.tr/salgurlular"}]}, {"id": "salgurlu-ebu-bekir", "name": "Ebû Bekir b. Sa'd", "aliases": ["Muzafferüddin Ebû Bekir Kutluğ Han"], "title": "Atabeg / Kutluğ Han", "birth": null, "birthNote": "Kayıtlarda yok", "death": 1260, "deathNote": "Şiraz'da vefat etti", "reign": [1226, 1260], "reignNote": "34 yıllık altın ve huzur çağı.", "summary": "Salgurluların en dirayetli hükümdarı. Moğollara vergi vermeyi kabul ederek Fars bölgesini Moğol katliamından ve yıkımından tamamen korudu. Şiraz'ı camiler, medreseler ve hastanelerle donattı; Sâdî-i Şîrâzî'nin en büyük hamisi oldu.", "traits": ["İleri görüşlü siyasetçi", "Cömert ve merhametli", "İlim aşığı"], "contribution": "Halkını Moğol soykırımından kurtardı; Şiraz'ı İslam dünyasının en güvenli kültür sığınağı yaptı.", "harm": "Moğol himayesini kabul etmek zorunda kaldı.", "wives": [], "children": [{"name": "II. Sa'd", "mother": "", "note": "Babasının sağlığında vefat etti", "certainty": "kesin"}], "wars": [{"name": "Hürmüz ve Körfez Seferi", "when": "1230", "foe": "Basra Körfezi korsanları ve adalar", "result": "zafer", "note": "Kiş ve Bahreyn adaları ele geçirildi, deniz ticareti güvenceye alındı."}], "legends": ["Sâdî onun hakkında 'Onun adil gölgesinde Fars ülkesi cennet bahçesine döndü' beytini yazmıştır."], "sources": [{"title": "TDV İslâm Ansiklopedisi, SALGURLULAR", "url": "https://islamansiklopedisi.org.tr/salgurlular"}]}]}, {"id": "akkoyunlu", "name": "Akkoyunlu Devleti", "short": "Akkoyunlular", "aliases": ["Bayındıriyye", "Ak Koyunlular", "Bayandurids"], "region": "iran", "start": 1378, "end": 1508, "startNote": "Oğuzların Bayındır boyundan Kara Yülük Osman Bey'in Diyarbekir merkezli bağımsızlık kazanmasıyla temellendi.", "endNote": "1501 Şerûr yenilgisinden sonra 1508'de Şah İsmail'in Bağdat ve Diyarbekir'i almasıyla sona erdi.", "capital": "Diyarbekir (ilk merkez), ardından Tebriz", "religion": "İslamiyet (Sünnî-Hanefî)", "confidence": "kayit", "confidenceNote": "Ebû Bekr-i Tahrânî'nin Kitâb-ı Diyârbekriyye'si, Âşıkpaşazâde ve Venedik sefaretnâmeleriyle sabittir.", "summary": "Oğuzların Bayındır boyuna mensup Türkmenler tarafından Doğu Anadolu, Azerbaycan, İran ve Irak'ta kurulan büyük imparatorluk. Uzun Hasan devrinde Karakoyunluları ve Timurluları mağlup ederek başkenti Tebriz'e taşıdılar; Venedik ve Avrupa krallıklarıyla diplomatik ittifaklar kurdular. Fatih Sultan Mehmed ile 1473 Otlukbeli Meydan Muharebesi'nde karşılaştılar. İlim ve kanunlaştırmaya büyük önem verip 'Hasan Padişah Kanunları'nı uyguladılar. 1501-1508 yıllarında Safevîler tarafından yıkıldılar.", "legacy": "Diyarbekir ve Tebriz'i Türk-İslam mimarisinin şaheserleriyle donattı; Hasan Padişah Kanunnâmesi Osmanlı fethinden sonra dahi bölgede asırlarca yürürlükte kaldı.", "essay": ["Akkoyunlular, Moğol istilasından sonra Diyarbekir yöresine yerleşen Oğuzların Bayındır boyuna dayanır. Beyliğin gerçek kurucusu Kara Yülük Osman Bey, Timur'un Anadolu seferinde onun yanında yer alarak Diyarbekir vilayetini taltif olarak aldı.", "Devlet en şanlı devrini Uzun Hasan (1453-1478) zamanında yaşadı. Uzun Hasan 1467'de Karakoyunlu Cihan Şah'ı ve 1469'da Timur hükümdarı Ebû Said'i mağlup edip öldürerek imparatorluk sınırlarını Horasan'dan Fırat'a kadar genişletti ve başkenti Tebriz yaptı. Trabzon Rum İmparatoru'nun kızı Theodora (Despina Hatun) ile evlenerek Venedik ile Osmanlı aleyhine ittifak kurdu. 11 Ağustos 1473'te Otlukbeli Meydan Muharebesi'nde Fatih Sultan Mehmed'in ateşli silahlarla donatılmış ordusuna yenildi.", "Uzun Hasan'ın ardından Sultan Yakub (1478-1490) devrinde kültür, şiir ve mimari gelişti. Ancak hanedan içi kavgalar devleti zayıflattı; 1501'de Şah İsmail Nahçıvan yakınlarında Şerûr Muharebesi'nde Elvend Bey'i yenerek Tebriz'e girdi ve Akkoyunlu mirası üzerinde Safevî Devleti'ni kurdu."], "sources": [{"title": "TDV İslâm Ansiklopedisi, AKKOYUNLULAR", "url": "https://islamansiklopedisi.org.tr/akkoyunlular"}, {"title": "TDV İslâm Ansiklopedisi, UZUN HASAN", "url": "https://islamansiklopedisi.org.tr/uzun-hasan"}], "rulers": [{"id": "akkoyunlu-uzun-hasan", "name": "Uzun Hasan", "aliases": ["Hasan Padişah", "Ebû'n-Nasr Uzun Hasan"], "title": "Padişah / Sultan", "birth": 1423, "birthNote": "Diyarbekir'de 1423'te doğdu", "death": 1478, "deathNote": "Tebriz'de vefat etti, Nasriyye Külliyesi'ndeki türbesindedir", "reign": [1453, 1478], "reignNote": "25 yıllık büyük imparatorluk dönemi.", "summary": "Akkoyunluların en büyük hükümdarı. Cihan Şah'ı ve Timur Sultanı Ebû Said'i yenerek imparatorluğunu Fırat'tan Horasan'a ulaştırdı. Kur'an-ı Kerim'i Türkçeye tercüme ettirdi, Hasan Padişah Kanunları ile adil vergi nizamı kurdu. Fatih ile Otlukbeli'nde karşılaştı.", "traits": ["Cihangir hükümdar", "Adil kanun koyucu", "Usta diplomat"], "contribution": "İran, Azerbaycan ve Doğu Anadolu'yu birleştirerek büyük bir Türk imparatorluğu kurdu; adil vergi kanunnameleri hazırlattı.", "harm": "Venedik kışkırtmasıyla Osmanlı'ya karşı savaşa girmesi Otlukbeli hezimetine yol açtı.", "wives": [{"name": "Theodora Komnene (Despina Hatun)", "note": "Trabzon Rum İmparatoru IV. İoannes'in kızı, Şah İsmail'in anneannesi", "certainty": "kesin"}, {"name": "Selçukşah Begüm", "note": "Karakoyunlu prensesi", "certainty": "kesin"}], "children": [{"name": "Sultan Halil", "mother": "", "note": "Babasından sonra tahta oturdu", "certainty": "kesin"}, {"name": "Sultan Yakub", "mother": "Selçukşah Begüm", "note": "İlim ve sanat hamisi padişah", "certainty": "kesin"}, {"name": "Uğurlu Mehmed", "mother": "", "note": "Fatih'in kızı Gevherhan Hatun ile evlendi", "certainty": "kesin"}, {"name": "Halime Begüm (Âlemşah)", "mother": "Despina Hatun", "note": "Şeyh Haydar ile evlendi, Şah İsmail'in annesi", "certainty": "kesin"}], "wars": [{"name": "Çapakçur Muharebesi", "when": "1467", "foe": "Karakoyunlular (Cihan Şah)", "result": "zafer", "note": "Cihan Şah öldürüldü, Karakoyunlu devleti yıkılıp toprakları ilhak edildi."}, {"name": "Otlukbeli Meydan Muharebesi", "when": "1473", "foe": "Osmanlı Devleti (Fatih Sultan Mehmed)", "result": "yenilgi", "note": "Osmanlı top ve tüfek ateşi karşısında Türkmen süvarileri tutunamadı, Uzun Hasan çekildi."}], "legends": ["Kur'an-ı Kerim'i Türkçe mealiyle beraber okuttuğu ve huzurunda Türkçe tefsir meclisleri kurdurduğu kaydedilir."], "sources": [{"title": "TDV İslâm Ansiklopedisi, UZUN HASAN", "url": "https://islamansiklopedisi.org.tr/uzun-hasan"}]}]}, {"id": "karakoyunlu", "name": "Karakoyunlu Devleti", "short": "Karakoyunlular", "aliases": ["Baraniler", "Kara Koyunlular", "Qara Qoyunlu"], "region": "iran", "start": 1380, "end": 1469, "startNote": "Bayram Hoca ve Kara Mehmed'in Erciş ve Van çevresinde beylik kurmasıyla başladı.", "endNote": "1468-1469'da Uzun Hasan'ın Cihan Şah ve oğullarını mağlup edip Tebriz'i almasıyla sona erdi.", "capital": "Erciş ve Tebriz", "religion": "İslamiyet (Şiî-Sünnî geçişli)", "confidence": "kayit", "confidenceNote": "Târîh-i Kızılbaşân, İbn Arabşah ve Tebriz Gök Mescid kitabeleriyle sabittir.", "summary": "Oğuzların Yıva boyuna mensup Baranlu oymağı tarafından Doğu Anadolu, Azerbaycan, Ermenistan, Gürcistan ve Irak sahasında kurulan büyük devlet. Kara Yusuf devrinde Timur istilasına karşı Osmanlılarla (Yıldırım Bayezid) ittifak yaptılar; Timur'un ölümünden sonra Tebriz ve Bağdat'ı zaptettiler. Cihan Şah devrinde Tebriz'de 'İslam'ın Turkuvazı' denilen muazzam Gök Mescid'i inşa ettiler. 1468'de Akkoyunlular tarafından yıkıldılar.", "legacy": "Tebriz Gök Mescid (Mescid-i Kebûd) gibi çini ve mozaik sanatının dünyadaki zirve eserlerini bıraktı; Türkçe şiir ve edebiyat muhitini geliştirdi.", "essay": ["Karakoyunlular, Moğol hakimiyetinin sarsılmasıyla Van Gölü'nün kuzeyindeki Erciş merkezli olarak Bayram Hoca ve oğlu Kara Mehmed tarafından kuruldu.", "Kara Yusuf (1389-1420), Timur'un gazabına uğrayıp Osmanlı Sultanı Yıldırım Bayezid'e sığındı; bu sığınma 1402 Ankara Savaşı'nın başlıca sebeplerinden biri oldu. Timur'un ölümünden sonra Tebriz'e dönen Kara Yusuf, Şehzade Miranşah'ı mağlup edip öldürerek Azerbaycan ve Irak'ın tek hakimi oldu.", "Cihan Şah (1438-1467) devri beyliğin en parlak ve kültürel zirve dönemi oldu. Cihan Şah, 'Hakîkî' mahlasıyla Türkçe ve Farsça muazzam divanlar yazdı; Tebriz'de çinileriyle meşhur Gök Mescid'i yaptırdı. Ancak 1467'de Akkoyunlu Uzun Hasan'ın ani sabah baskınında (Çapakçur) öldürüldü ve devlet Akkoyunlulara katıldı."], "sources": [{"title": "TDV İslâm Ansiklopedisi, KARAKOYUNLULAR", "url": "https://islamansiklopedisi.org.tr/karakoyunlular"}, {"title": "TDV İslâm Ansiklopedisi, CİHAN ŞAH", "url": "https://islamansiklopedisi.org.tr/cihansah"}], "rulers": [{"id": "karakoyunlu-kara-yusuf", "name": "Kara Yusuf", "aliases": ["Ebû Nasr Kara Yusuf Bey"], "title": "Bey / Sultan", "birth": 1357, "birthNote": "Yaklaşık 1357 doğumlu", "death": 1420, "deathNote": "Şahruh'a karşı sefere giderken Uçan mevkiinde hastalanarak vefat etti", "reign": [1389, 1420], "reignNote": "31 yıllık fırtınalı hükümdarlık.", "summary": "Karakoyunluların en savaşçı hükümdarı. Timur'a asla boyun eğmedi, Osmanlı'ya sığınarak Ankara Savaşı kıvılcımını ateşledi. Timur ölünce dönüp Tebriz ve Bağdat'ı fethetti; Timurlu ordularını defalarca mağlup etti.", "traits": ["Yılmayan cengaver", "Özgürlük aşığı", "Stratejist"], "contribution": "Azerbaycan ve Irak'ı Türkmen hakimiyetine kazandırdı, Tebriz'i başkent yaptı.", "harm": "Timur ile giriştiği amansız kavga Anadolu'nun istilasına ve Yıldırım'ın esaretine zemin hazırladı.", "wives": [], "children": [{"name": "İskender", "mother": "", "note": "Hükümdar oldu", "certainty": "kesin"}, {"name": "Cihan Şah", "mother": "", "note": "Büyük şair ve hükümdar", "certainty": "kesin"}, {"name": "İsbend", "mother": "", "note": "Bağdat valisi", "certainty": "kesin"}], "wars": [{"name": "Serdrûd Muharebesi", "when": "1408", "foe": "Timurlular (Miranşah ve Ebû Bekir)", "result": "zafer", "note": "Timurlu ordusu imha edildi, Timur'un oğlu Miranşah savaşta öldürüldü."}], "legends": ["Ölüm döşeğinde bile Şahruh'un ordusuna meydan okuyup sedyede savaşa yürümek istediği rivayet edilir."], "sources": [{"title": "TDV İslâm Ansiklopedisi, KARAKOYUNLULAR", "url": "https://islamansiklopedisi.org.tr/karakoyunlular"}]}, {"id": "karakoyunlu-cihan-sah", "name": "Cihan Şah", "aliases": ["Cihânşah", "Hakîkî"], "title": "Sultan / Hakîkî", "birth": 1397, "birthNote": "Mardin civarında 1397'de doğdu", "death": 1467, "deathNote": "Çapakçur ovasında Uzun Hasan'ın baskınında şehit edildi", "reign": [1438, 1467], "reignNote": "29 yıllık medeniyet ve şiir çağı.", "summary": "Kara Yusuf'un oğlu. Karakoyunluların en parlak hükümdarı ve büyük divan şairi. Gürcistan'ı, Fars'ı ve Bağdat'ı fethetti; Herat'a kadar girerek Timurluları haraca bağladı. Tebriz'de Gök Mescid'i yaptırdı. 1467'de Uzun Hasan'ın sabah baskınında şehit oldu.", "traits": ["Büyük divan şairi", "Sanat ve mimari hamisi", "Cihangir"], "contribution": "Tebriz Gök Mescid'i inşa ettirdi; Azerbaycan Türkçesini saray ve edebiyat dili yaptı.", "harm": "Akkoyunluların gücünü küçümseyip kış şartlarında tedbirsiz ordugâh kurması felaketine yol açtı.", "wives": [{"name": "Can Begüm Hatun", "note": "Gök Mescid vakfiyesini tanzim eden eşi", "certainty": "kesin"}], "children": [{"name": "Hasan Ali", "mother": "", "note": "Son hükümdar", "certainty": "kesin"}, {"name": "Pir Budak", "mother": "", "note": "Bağdat valisi, babasına isyan etti", "certainty": "kesin"}], "wars": [{"name": "Bağdat Seferi", "when": "1446", "foe": "Kardeşi İsbend'in varisleri", "result": "zafer", "note": "Bağdat zaptedildi."}, {"name": "Çapakçur Muharebesi", "when": "1467", "foe": "Akkoyunlular (Uzun Hasan)", "result": "yenilgi", "note": "Kar örtüsü altında yapılan baskında ordusu dağıldı, Cihan Şah öldürüldü."}], "legends": ["'Hakîkî' mahlasıyla yazdığı Türkçe gazeller Azerbaycan ve Türk edebiyatının en lirik örnekleri arasında yer alır."], "sources": [{"title": "TDV İslâm Ansiklopedisi, CİHAN ŞAH", "url": "https://islamansiklopedisi.org.tr/cihansah"}]}]}, {"id": "safevi", "name": "Safevî Devleti", "short": "Safevîler", "aliases": ["Safevî İmparatorluğu", "Devlet-i Kızılbaş"], "region": "iran", "start": 1501, "end": 1736, "startNote": "Şah İsmail'in 1501'de Şerûr zaferinden sonra Tebriz'de tahta çıkıp On İki İmam Şiiliğini ilan etmesiyle kuruldu.", "endNote": "1736 yılında Avşar Hanı Nâdir Şah'ın III. Abbas'ı tahttan indirip şahlığını ilan etmesiyle sona erdi.", "capital": "Tebriz (1501-1555), Kazvin (1555-1598) ve İsfahan (1598-1736)", "religion": "İslamiyet (Şiî-İsnâaşeriyye)", "confidence": "kayit", "confidenceNote": "Hasan-ı Rûmlû (Ahsenü't-Tevârîh), İskender Bey Türkmen (Âlem-ârâ-yı Abbâsî) ve Osmanlı mühimme kayıtlarıyla sabittir.", "summary": "Erdebil tekkesi şeyhi Şah İsmail tarafından Anadolu ve Azerbaycan Türkmen boylarının (Ustaclu, Şamlu, Avşar, Kaçar, Tekelü, Rumlu, Dulkadır) desteğiyle kurulan ve İran'ı Şiileştiren büyük imparatorluk. Şah İsmail 'Hatâî' mahlasıyla Türkçe divanlar yazdı. 1514 Çaldıran'da Yavuz Sultan Selim'e mağlup oldu. I. Abbas devrinde başkent İsfahan'a taşındı, 'Nısf-ı Cihan' (Cihanın Yarısı) denilen Nakş-ı Cihan Meydanı inşa edildi. 1639 Kasr-ı Şîrîn Antlaşması ile bugünkü Türkiye-İran sınırı çizildi. 1736'da Nâdir Şah tarafından yıkıldı.", "legacy": "İran'ın bugünkü Şii dini ve milli kimliğini kurdu. İsfahan Nakş-ı Cihan Meydanı, Şeyh Lütfullah Camii ve Şah Camii gibi dünya çapında anıtlar miras bıraktı. Şah İsmail'in Türkçe şiirleri Alevi-Bektaşi nefeslerinin omurgası oldu.", "essay": ["Safevîler, kökleri Erdebil tekkesi pîri Şeyh Safiyyüddin'e uzanan tasavvufi bir tarikatın Şeyh Cüneyd ve Şeyh Haydar dönemlerinde siyasallaşmasıyla doğdu. Müridlerine on iki dilimli kırmızı başlık giydirdikleri için 'Kızılbaş' adını aldılar.", "Şeyh Haydar'ın oğlu Şah İsmail, henüz 14 yaşında Erzincan'da toplanan Türkmen aşiretlerinin başına geçerek 1501'de Akkoyunluları yendi ve Tebriz'de şahlığını ilan etti. On İki İmam Şiiliğini devletin resmi mezhebi yaptı. Ancak Anadolu'ya yönelik Şii-Kızılbaş propagandası Osmanlı ile kaçınılmaz bir savaşa yol açtı; 23 Ağustos 1514'te Çaldıran Meydan Muharebesi'nde Yavuz Sultan Selim'e karşı ağır bir hezimete uğradı.", "Devlet en parlak devrini Şah I. Abbas (1587-1629) zamanında yaşadı. Abbas, başkenti İsfahan'a taşıdı; Nakş-ı Cihan Meydanı, Ali Kapu sarayı ve Çehil Sütun'u inşa ettirdi. Osmanlılardan Tebriz, Bağdat ve Kafkasları geri aldı; Hürmüz'den Portekizlileri çıkardı. 1639'da IV. Murad ile imzalanan Kasr-ı Şîrîn Antlaşması iki devlet arasındaki asırlık savaşı barışa bağladı. 1722'de Afgan istilasıyla çöken devlete 1736'da Nâdir Şah Avşar son verdi."], "sources": [{"title": "TDV İslâm Ansiklopedisi, SAFEVÎLER", "url": "https://islamansiklopedisi.org.tr/safeviler"}, {"title": "TDV İslâm Ansiklopedisi, İSMÂİL I", "url": "https://islamansiklopedisi.org.tr/ismail-i"}, {"title": "TDV İslâm Ansiklopedisi, ABBAS I", "url": "https://islamansiklopedisi.org.tr/abbas-i"}], "rulers": [{"id": "safevi-sah-ismail", "name": "Şah I. İsmail", "aliases": ["Şah İsmail", "Hatâî", "İsmail-i Safevî"], "title": "Şah / Hatâî", "birth": 1487, "birthNote": "1487'de Erdebil'de doğdu", "death": 1524, "deathNote": "Serab yakınlarında 37 yaşında kederinden vefat etti, Erdebil'e defnedildi", "reign": [1501, 1524], "reignNote": "23 yıllık devrimci ve fırtınalı hükümdarlık.", "summary": "Safevî Devleti'nin kurucusu. 14 yaşında Tebriz tahtına oturup İran'ı Şiileştirdi. Özbek Hanı Şeybânî'yi Merv'de mağlup etti. 'Hatâî' mahlasıyla hece ve aruzla yazdığı Türkçe şiirlerle edebiyat tarihine geçti. 1514 Çaldıran'da Yavuz'a yenildikten sonra matem tuttu.", "traits": ["Karizmatik mürşid-i kâmil", "Büyük Türk şairi", "Gözü pek süvari"], "contribution": "İran'da 235 yıl sürecek Safevî İmparatorluğu'nu kurdu; Türkçe divanıyla halk edebiyatını derinden etkiledi.", "harm": "Sünnî halka ve Akkoyunlu hanedan mezarlarına yönelik katliamları ve mezhep taassubu İslam dünyasında asırlarca sürecek kanlı bir ayrışma başlattı.", "wives": [{"name": "Taclı Bégüm", "note": "Çaldıran'da esir düşen ünlü baş hatunu", "certainty": "kesin"}, {"name": "Behrûze Hanım", "note": "Eşi", "certainty": "kesin"}], "children": [{"name": "I. Tahmasb", "mother": "Taclı Bégüm", "note": "İkinci şah, 52 yıl tahtta kaldı", "certainty": "kesin"}, {"name": "Elkas Mirza", "mother": "", "note": "Osmanlı'ya sığınan şehzade", "certainty": "kesin"}, {"name": "Sâm Mirza", "mother": "", "note": "Şair şehzade", "certainty": "kesin"}, {"name": "Behmen Mirza", "mother": "", "note": "Şehzade", "certainty": "kesin"}], "wars": [{"name": "Şerûr Muharebesi", "when": "1501", "foe": "Akkoyunlular (Elvend Bey)", "result": "zafer", "note": "Tebriz fethedildi, şahlık ilan edildi."}, {"name": "Merv Meydan Muharebesi", "when": "1510", "foe": "Özbek Hanlığı (Şeybânî Han)", "result": "zafer", "note": "Şeybânî Han öldürüldü, Horasan fethedildi."}, {"name": "Çaldıran Meydan Muharebesi", "when": "1514", "foe": "Osmanlı Devleti (Yavuz Sultan Selim)", "result": "yenilgi", "note": "Osmanlı topçu ve tüfek ateşiyle Kızılbaş süvarileri kırıldı, Tebriz Osmanlı eline geçti."}], "legends": ["Kılıcıyla tek vuruşta bir düşman askerinin zırhını ve atını ikiye böldüğü, Çaldıran'da Osmanlı topunun namlusunu kestiği rivayet edilir."], "sources": [{"title": "TDV İslâm Ansiklopedisi, İSMÂİL I", "url": "https://islamansiklopedisi.org.tr/ismail-i"}]}, {"id": "safevi-sah-abbas", "name": "Şah I. Abbas", "aliases": ["Büyük Abbas", "Şah Abbas"], "title": "Şah / Şehinşah", "birth": 1571, "birthNote": "Herat'ta 1571'de doğdu", "death": 1629, "deathNote": "Mazenderan'da Behşehr sarayında vefat etti", "reign": [1587, 1629], "reignNote": "42 yıllık muhteşem altın çağ.", "summary": "Safevîlerin en büyük şahı. Ordusunu ateşli silahlarla modernleştirdi, başkenti İsfahan'a taşıyarak Nakş-ı Cihan Meydanı'nı kurdu. Osmanlılardan Tebriz ve Bağdat'ı geri aldı; İngilizlerin yardımıyla Portekizlileri Hürmüz Boğazı'ndan kovdu. İpek ticaretini devlet tekeline alıp Avrupa ile doğrudan ticaret başlattı.", "traits": ["Büyük reformcu", "Askerî dahi", "İmar hamisi", "Şüpheci ve acımasız"], "contribution": "İsfahan'ı dünyanın en gözde sanat ve ticaret metropolü yaptı; Safevî devletini zirveye taşıdı.", "harm": "Aşırı şüpheciliği yüzünden kendi oğullarını idam ettirdi ve kör etti; tahtı tecrübesiz torununa bırakarak çöküşü hazırladı.", "wives": [], "children": [{"name": "Safî Mirza", "mother": "", "note": "Babası tarafından öldürtülen veliaht", "certainty": "kesin"}, {"name": "İmam Kulu Mirza", "mother": "", "note": "Gözleri kör edildi", "certainty": "kesin"}, {"name": "Rıza Kulu Mirza", "mother": "", "note": "Gözleri kör edildi", "certainty": "kesin"}], "wars": [{"name": "Tebriz ve Azerbaycan Seferi", "when": "1603", "foe": "Osmanlı Devleti (Cigalazâde Sinan Paşa)", "result": "zafer", "note": "Tebriz, Nahçıvan ve Erivan geri alındı."}, {"name": "Bağdat'ın Zaptı", "when": "1624", "foe": "Osmanlı Bağdat garnizonu", "result": "zafer", "note": "Irak ve kutsal türbeler Safevî eline geçti."}, {"name": "Hürmüz Seferi", "when": "1622", "foe": "Portekiz Krallığı", "result": "zafer", "note": "İngiliz donanması desteğiyle Portekiz kalesi fethedildi, Benderabbas limanı kuruldu."}], "legends": ["'İsfahan nısf-ı cihanest' (İsfahan cihanın yarısıdır) darb-ı meseli onun inşa ettirdiği muazzam meydan ve saraylar için söylenmiştir."], "sources": [{"title": "TDV İslâm Ansiklopedisi, ABBAS I", "url": "https://islamansiklopedisi.org.tr/abbas-i"}]}]}, {"id": "avsar", "name": "Avşar Hanedanı", "short": "Avşarlar", "aliases": ["Avşar Devleti", "Nâdir Şah İmparatorluğu"], "region": "iran", "start": 1736, "end": 1796, "startNote": "Oğuzların Avşar boyundan Nâdir Şah'ın Mugan kurultayında şah ilan edilmesiyle kuruldu.", "endNote": "1796'da Kaçar hükümdarı Ağa Muhammed Şah'ın son Avşar hükümdarı Şahruh'u işkenceyle öldürmesiyle sona erdi.", "capital": "Meşhed", "religion": "İslamiyet (Ca'ferî-Sünnî uzlaşması arayışı)", "confidence": "kayit", "confidenceNote": "Mirza Mehmed Mehdî-i Esterâbâdî'nin Târîh-i Cihângüşâ-yı Nâdirî eseriyle sabittir.", "summary": "Oğuzların Avşar boyu Kırklu obasına mensup Nâdir Şah tarafından kurulan ve Asya'yı titreten askeri imparatorluk. Nâdir Şah, Osmanlı ve Rusları İran topraklarından çıkardıktan sonra 1739'da Karnal Meydan Muharebesi'nde Bâbürlü ordusunu ezerek Delhi'yi fethetti; Tavus Kuşu Tahtı ve Koh-i Noor elmasını İran'a getirdi. Mezhep ayrılıklarını bitirmek için Ca'ferîliği beşinci hak mezhep olarak kabul ettirmeye çalıştı. 1747'de ordugâhında suikastla öldürüldü.", "legacy": "Askeri dehâsıyla 'Doğunun Napolyon'u' unvanını aldı; Hindistan'dan getirdiği hazineler Meşhed İmam Rıza Türbesi'ni ve hazinelerini zenginleştirdi.", "essay": ["Avşarlar hanedanı, Horasan'da yaşayan Avşar boyunun Kırklu obasından Nâdir Kulu Han'ın askeri dehâsıyla tarih sahnesine çıktı. 1722'de çöken Safevî Devleti'ni Afgan işgalcilerden temizleyen Nâdir, 1736'da Mugan Ovası'nda topladığı büyük kurultayda kendisini şah ilan etti.", "1738'de Kandahar'ı fetheden Nâdir Şah, Hayber Geçidi'ni aşarak Hindistan'a girdi. 1739 Karnal Muharebesi'nde 300 bin kişilik devasa Bâbürlü ordusunu üç saatte bozguna uğratıp Delhi'ye girdi. Dünyanın en büyük hazinelerini, efsanevi Koh-i Noor ve Derya-yı Nûr elmasları ile Tavus Kuşu Tahtı'nı alarak İran'a döndü ve halkından üç yıl vergi almadı.", "Ancak son yıllarında aşırı şüphecilik ve öfke krizleriyle kendi oğlu Rıza Kulu Mirza'nın gözlerini kör ettirdi; etrafındaki Türkmen ve Kürt beylerine zulmetmeye başladı. 1747 yılında Fethâbâd ordugâhında kendi muhafızları tarafından çadırında katledildi. Ardından Meşhed merkezli torunu Şahruh'un kör hükümdarlığı 1796'da Kaçarlar tarafından sonlandırıldı."], "sources": [{"title": "TDV İslâm Ansiklopedisi, AVŞARLAR", "url": "https://islamansiklopedisi.org.tr/avsarlar"}, {"title": "TDV İslâm Ansiklopedisi, NÂDİR ŞAH", "url": "https://islamansiklopedisi.org.tr/nadir-sah"}], "rulers": [{"id": "avsar-nadir-sah", "name": "Nâdir Şah", "aliases": ["Nâdir Kulu Han", "Tahmasb Kulu Han", "Doğunun Napolyonu"], "title": "Şah / Şehinşah", "birth": 1688, "birthNote": "Horasan'da Dergaz yakınlarında 1688'de doğdu", "death": 1747, "deathNote": "Koçan yakınındaki Fethâbâd ordugâhında suikastla çadırında katledildi", "reign": [1736, 1747], "reignNote": "11 yıllık fetih fırtınası.", "summary": "Avşar hanedanının kurucusu ve dünyanın en büyük askeri dahilerinden biri. İran'ı Afgan, Rus ve Osmanlı işgalinden kurtardı. Hindistan Seferi ile Delhi'yi fethetti, Buhara ve Hive hanlıklarını dize getirdi. Ca'ferîliği beşinci mezhep yapıp mezhep barışı kurmak istedi. Son yıllarındaki zulümleri yüzünden suikastla öldürüldü.", "traits": ["Askerî dehâ", "Korkusuz fatih", "Sert ve şüpheci"], "contribution": "İran'ın bağımsızlığını kurtardı ve sınırlarını Delhi'den Bağdat'a kadar genişletti.", "harm": "Kendi veliahtını kör ettirdi, son yıllarındaki aşırı vergi ve kafa kuleleri diktirmesi devleti kan gölüne çevirdi.", "wives": [], "children": [{"name": "Rıza Kulu Mirza", "mother": "", "note": "Babası tarafından gözleri kör edilen veliaht", "certainty": "kesin"}, {"name": "Nasrullah Mirza", "mother": "", "note": "Karnal kahramanı şehzade", "certainty": "kesin"}], "wars": [{"name": "Karnal Meydan Muharebesi", "when": "1739", "foe": "Bâbür İmparatorluğu (Muhammed Şah)", "result": "zafer", "note": "300 bin kişilik Hint ordusu darmadağın edildi, Delhi fethedildi, devasa hazineler alındı."}, {"name": "Muradtepe Muharebesi", "when": "1735", "foe": "Osmanlı Ordusu (Köprülüzâde Abdullah Paşa)", "result": "zafer", "note": "Revan yakınlarında Osmanlı ordusu mağlup edildi, Kafkaslar geri alındı."}], "legends": ["Delhi fethinde getirilen Koh-i Noor (Işık Dağı) elmasını görünce hayretle 'Koh-i Noor!' diye haykırdığı rivayet edilir."], "sources": [{"title": "TDV İslâm Ansiklopedisi, NÂDİR ŞAH", "url": "https://islamansiklopedisi.org.tr/nadir-sah"}]}]}, {"id": "kacar", "name": "Kaçar Hanedanı", "short": "Kaçarlar", "aliases": ["Kaçar Devleti", "Devlet-i Aliyye-i İran"], "region": "iran", "start": 1796, "end": 1925, "startNote": "Ağa Muhammed Şah'ın Tahran'ı başkent yaparak taç giymesiyle kuruldu.", "endNote": "1925 yılında Rıza Pehlevî'nin meclis kararıyla Kaçar hanedanına son verip Pehlevî rejimini kurmasıyla sona erdi.", "capital": "Tahran", "religion": "İslamiyet (Şiî-İsnâaşeriyye)", "confidence": "kayit", "confidenceNote": "Rızâ Kulı Han Hidâyet (Ravzatü's-Safâ-yı Nâsırî), sefaretnâmeler ve resmi devlet arşivleriyle sabittir.", "summary": "Oğuzların Bozok koluna mensup Kaçar Türkmenleri tarafından kurulan ve İran'ı 130 yıl yöneten son Türk hanedanı. Ağa Muhammed Şah Tahran'ı ilk kez başkent yaptı. Feth Ali Şah ve Nasreddin Şah devirlerinde Rusya ile yapılan kanlı savaşlar sonucu Kafkaslar (Gülistan 1813 ve Türkmençay 1828 antlaşmalarıyla) kaybedildi ve Azerbaycan ikiye bölündü. 1906 yılında Muzafferüddin Şah devrinde Meşrutiyet ilan edilerek anayasal monarşiye geçildi. 1925'te Rıza Şah Pehlevî tarafından yıkıldı.", "legacy": "Tahran'ı modern İran'ın başkenti yaptı; Gülistan Sarayı ve Kaçar saray resim sanatını miras bıraktı. 1906 Meşrutiyet Devrimi ile Orta Doğu'nun ilk anayasalarından birini hayata geçirdi.", "essay": ["Kaçarlar, Safevîler devrinden beri Gence, Karabağ ve Esterâbâd bölgesinde yaşayan köklü bir Türk boyudur. Zend hanedanının çöküşüyle harekete geçen Kaçar reisi Ağa Muhammed Han, olağanüstü bir acımasızlık ve askeri disiplinle bütün İran'ı birleştirdi; Tahran'ı başkent yaparak 1796'da şahlık tacını giydi.", "Feth Ali Şah (1797-1834) devrinde Çarlık Rusyası'nın Kafkaslara yayılmasına karşı veliaht Abbas Mirza kahramanca direndiyse de 1813 Gülistan ve 1828 Türkmençay antlaşmalarıyla Aras nehrinin kuzeyi (Bakü, Gence, Erivan, Nahçıvan) Rusya'ya bırakıldı; Azerbaycan Türk yurdu kalıcı olarak bölündü.", "Nasreddin Şah'ın 48 yıllık saltanatında (1848-1896) telgraf, posta ve Dârü'l-Fünûn gibi modern kurumlar kuruldu; ancak İngiliz ve Rus tütün ve demiryolu imtiyazları halkı ayaklandırdı (Tütün İsyanı). 1906 Meşrutiyet devrimiyle meclis açıldı. I. Dünya Savaşı'nda yabancı işgallerle sarsılan hanedan, 1925'te son hükümdar Ahmed Şah'ın yurt dışındayken tahttan indirilmesiyle sona erdi."], "sources": [{"title": "TDV İslâm Ansiklopedisi, KAÇARLAR", "url": "https://islamansiklopedisi.org.tr/kacarlar"}, {"title": "TDV İslâm Ansiklopedisi, AĞA MUHAMMED ŞAH", "url": "https://islamansiklopedisi.org.tr/aga-muhammed-sah"}, {"title": "TDV İslâm Ansiklopedisi, NASREDDİN ŞAH", "url": "https://islamansiklopedisi.org.tr/nasreddin-sah"}], "rulers": [{"id": "kacar-aga-muhammed", "name": "Ağa Muhammed Şah", "aliases": ["Ağa Muhammed Han Kaçar"], "title": "Şah / Han", "birth": 1742, "birthNote": "1742'de Esterâbâd'da doğdu", "death": 1797, "deathNote": "Şuşa kalesinde iki hizmetkârı tarafından hançerlenerek öldürüldü", "reign": [1796, 1797], "reignNote": "1789'dan itibaren fiili lider, 1796'da taç giydi.", "summary": "Kaçar hanedanının kurucusu. Çocukken hadım edilmesine rağmen demir bir iradeyle Zendleri ve Avşarları ezerek İran birliğini kurdu; Tahran'ı başkent yaptı. Tiflis'i zaptetti. Şuşa kalesinde kendi uşakları tarafından öldürüldü.", "traits": ["Çelik iradeli", "Acımasız disiplinli", "Askerî teşkilatçı"], "contribution": "İran'da yüzyıllık hanedan birliğini kurdu; Tahran'ı ebedi başkent yaptı.", "harm": "Tiflis ve Kirman'daki aşırı intikamcı katliamları dehşet yarattı.", "wives": [], "children": [], "wars": [{"name": "Krktsanisi (Tiflis) Muharebesi", "when": "1795", "foe": "Gürcistan Krallığı (II. Erekle)", "result": "zafer", "note": "Tiflis fethedildi, Gürcistan itaate alındı."}], "legends": ["Kavun dilimini izinsiz yiyen iki hizmetkarını sabah idam ettireceğini söyleyip gece onları nöbette bırakması kendi ölümüne yol açmıştır."], "sources": [{"title": "TDV İslâm Ansiklopedisi, AĞA MUHAMMED ŞAH", "url": "https://islamansiklopedisi.org.tr/aga-muhammed-sah"}]}, {"id": "kacar-feth-ali-sah", "name": "Feth Ali Şah", "aliases": ["Baba Han"], "title": "Şah / Şehinşah", "birth": 1772, "birthNote": "Damgan'da 1772'de doğdu", "death": 1834, "deathNote": "İsfahan yolunda 1834'te vefat etti", "reign": [1797, 1834], "reignNote": "37 yıllık görkemli ve hüzünlü saltanat.", "summary": "Ağa Muhammed Şah'ın yeğeni. Meşhur upuzun sakalı, mücevherli tahtı ve saray debdebesiyle tanındı. Rusya ile iki büyük savaş yaşadı; Türkmençay Antlaşması ile Kafkasya elden çıktı. Çok sayıda şehzade babası oldu.", "traits": ["Görkem ve sanat aşığı", "Şair", "Geleneksel hükümdar"], "contribution": "Gülistan Sarayı'nı inşa ettirdi; Kaçar saray resim ve portre sanatının zirvesini yaşattı.", "harm": "Rusya karşısında Kafkasların ve Kuzey Azerbaycan'ın ebediyen kaybedilmesine engel olamadı.", "wives": [{"name": "Tâvûs Hanım (Tâcü'd-Devle)", "note": "En sevdiği eşi, Gürcü asıllı", "certainty": "kesin"}], "children": [{"name": "Abbas Mirza", "mother": "", "note": "Kafkasya savaşlarının kahraman veliahtı, babasından önce öldü", "certainty": "kesin"}, {"name": "Muhammed Ali Mirza", "mother": "", "note": "Kudretli şehzade", "certainty": "kesin"}], "wars": [{"name": "Birinci Rus-Kaçar Savaşı", "when": "1804-1813", "foe": "Çarlık Rusyası", "result": "yenilgi", "note": "Gülistan Antlaşması ile Karabağ, Gence, Şirvan, Şeki, Bakü ve Dağıstan Rusya'ya bırakıldı."}, {"name": "İkinci Rus-Kaçar Savaşı", "when": "1826-1828", "foe": "Çarlık Rusyası (Paskeviç)", "result": "yenilgi", "note": "Türkmençay Antlaşması imzalandı, Erivan ve Nahçıvan kaybedildi, Aras sınırı çizildi."}], "legends": ["Yüzü aşkın oğlu ve kızı olduğu, her vilayete bir şehzadesini vali atadığı saray vekayinamelerinde geçer."], "sources": [{"title": "TDV İslâm Ansiklopedisi, FETH ALİ ŞAH", "url": "https://islamansiklopedisi.org.tr/feth-ali-sah"}]}]}, {"id": "tulun", "name": "Tolunoğulları", "short": "Tolunoğulları", "aliases": ["Tulunîler", "Benu Tulun"], "region": "anadolu", "start": 868, "end": 905, "startNote": "Buhara asıllı Türk kumandanı Ahmed b. Tolun'un Mısır valisi olarak Fustat'a girmesiyle kuruldu.", "endNote": "905 yılında Abbasi ordusunun Fustat'a girip şehri işgal etmesiyle yıkıldı.", "capital": "Katâi (Fustat/Kahire)", "religion": "İslamiyet (Sünnî)", "confidence": "kayit", "confidenceNote": "Kindî, İbnü'l-Esîr, Makrîzî ve İbn Haldûn eserleriyle eksiksiz belgelidir.", "summary": "İslam tarihinde Mısır ve Suriye'de kurulan ilk bağımsız Türk-İslam devleti. Samerra'da yetişen Buhara asıllı Ahmed b. Tolun tarafından kuruldu. Nil taşkınlarını ıslah edip tarımı ve sanayiyi canlandırdılar; Akdeniz'in en güçlü donanmalarından birini inşa ettiler. Günümüzde hala ayakta duran meşhur İbn Tolun Camii ve helezonik minaresi bu devletin şaheseridir.", "legacy": "Mısır'da bin yıl sürecek Türk siyasi ve askeri hakimiyetinin ilk meşalesini yaktı. İbn Tolun Camii ve Bimaristan ile İslam mimarisine damga vurdu.", "essay": ["Tolunoğulları hanedanının kurucusu Ahmed b. Tolun'un babası Tolun, Abbasi Halifesi Me'mûn devrinde Buhara'dan Bağdat'a getirilen seçkin Türk kumandanlarındandı. Ahmed b. Tolun, askeri dehâsı ve ilmi birikimi sayesinde 868 yılında Mısır valiliği vekili sıfatıyla Fustat'a girdi ve hızla kendi bağımsız idaresini tesis etti.", "Ordusunu 100 bin kişilik profesyonel süvari ve donanma gücüne ulaştıran Ahmed b. Tolun, Fustat'ın yanında yeni başkent Katâi'yi kurdu. Nil taşkınlarını düzenleyen mikyasları ıslah etti, vergileri düşürerek halkın refahını artırdı. 877'de Suriye ve Filistin'i fethetti; kendi adına altın Tolunî dinarları bastırarak tam bağımsızlığını ilan etti.", "Oğlu Humâreveyh (884-896) devrinde devlet Bizans'a karşı seferler düzenleyip en geniş sınırlarına ulaştı. Ancak Humâreveyh'in Şam'da köleleri tarafından öldürülmesinden sonra çocuk yaştaki şehzadeler ve kumandanlar arasındaki taht kavgaları hazineyi tüketti; 905 yılında Abbasi ordusu Mısır'a girerek Katâi şehrini yaktı ve devlete son verdi."], "sources": [{"title": "TDV İslâm Ansiklopedisi, TOLUNOĞULLARI", "url": "https://islamansiklopedisi.org.tr/tolunogullari"}, {"title": "TDV İslâm Ansiklopedisi, AHMED B. TOLUN", "url": "https://islamansiklopedisi.org.tr/ahmed-b-tolun"}], "rulers": [{"id": "tulun-ahmed", "name": "Ahmed b. Tolun", "aliases": ["İbn Tolun"], "title": "Emir / Sultan", "birth": 835, "birthNote": "835'te Bağdat'ta doğdu", "death": 884, "deathNote": "Antakya seferi dönüşünde Fustat'ta vefat etti", "reign": [868, 884], "reignNote": "16 yıllık kurucu ve parlak hükümdarlık.", "summary": "Mısır'daki ilk Türk devletinin kurucusu. Mısır'ın gelirlerinin Bağdat'a akmasını durdurup ülkesini imar etti; Katâi şehrini ve ünlü İbn Tolun Camii'ni yaptırdı. Suriye ve Trablusgarp'ı topraklarına katarak Akdeniz'de güçlü bir donanma kurdu.", "traits": ["Büyük teşkilatçı", "Halk dostu adil emir", "İmar hamisi"], "contribution": "Mısır'ı müreffeh bir dünya merkezine çevirdi; hastaneler (Bimaristan) ve kanallar açtı.", "harm": "Büyük oğlu Abbas'ın isyanı aile içi güveni sarstı.", "wives": [{"name": "Yârcûh et-Türkî'nin kızı", "note": "Kayınpederinin ölümüyle Mısır idaresi tekeline girdi", "certainty": "kesin"}], "children": [{"name": "Abbas b. Ahmed", "mother": "", "note": "İsyan etti, hapsedildi", "certainty": "kesin"}, {"name": "Humâreveyh", "mother": "", "note": "İkinci hükümdar", "certainty": "kesin"}, {"name": "Şeybân", "mother": "", "note": "Son hükümdar", "certainty": "kesin"}], "wars": [{"name": "Suriye Seferi", "when": "878", "foe": "Abbasi valileri", "result": "zafer", "note": "Dımaşk, Humus, Hama ve Halep fethedildi."}, {"name": "Tarsus Seferi", "when": "883", "foe": "Bizans sınır garnizonu", "result": "zafer", "note": "Kilikya sınırında Türk hakimiyeti kuruldu."}], "legends": ["Yaptırdığı caminin minaresinin spiral rampa biçimini, parmağına doladığı bir kâğıt şeridinden esinlenerek bizzat çizdiği rivayet edilir."], "sources": [{"title": "TDV İslâm Ansiklopedisi, AHMED B. TOLUN", "url": "https://islamansiklopedisi.org.tr/ahmed-b-tolun"}]}, {"id": "tulun-humareveyh", "name": "Humâreveyh b. Ahmed", "aliases": ["Ebû'l-Ceyş Humâreveyh"], "title": "Emir", "birth": 864, "birthNote": "864'te Samerra'da doğdu", "death": 896, "deathNote": "Dımaşk'ta gece yatağında uşakları tarafından öldürüldü", "reign": [884, 896], "reignNote": "12 yıl hüküm sürdü.", "summary": "Ahmed b. Tolun'un oğlu. Abbasileri hezimete uğratarak Mısır ve Suriye üzerindeki hakimiyetini halifeye 30 yıllığına tasdik ettirdi. Kızı Katrunnedâ'yı Abbasi Halifesi Mu'tazıd ile evlendirerek tarihin en mutantan düğününü yaptı. İhtişamlı sarayları ve cıva havuzlu bahçesiyle tanındı.", "traits": ["Lüks ve debdebe aşığı", "Cömert", "Cesur komutan"], "contribution": "Devletin sınırlarını Fırat'tan Libya'ya kadar genişletti; Bizans ile barış yaptı.", "harm": "Aşırı israfı ve lüks harcamaları devlet hazinesini iflasın eşiğine getirdi.", "wives": [], "children": [{"name": "Ceyş b. Humâreveyh", "mother": "", "note": "Kısa süre tahta oturdu", "certainty": "kesin"}, {"name": "Hârûn b. Humâreveyh", "mother": "", "note": "Dördüncü hükümdar", "certainty": "kesin"}, {"name": "Katrunnedâ Hatun", "mother": "", "note": "Halife Mu'tazıd ile evlendi", "certainty": "kesin"}], "wars": [{"name": "Tevâhîn (Değirmenler) Muharebesi", "when": "885", "foe": "Abbasi Ordusu (Muvaffak)", "result": "zafer", "note": "Suriye sınırında Abbasi ordusu mağlup edildi, hilafet barış istedi."}], "legends": ["Uykusuzluk çektiği için cıva dolu havuzun üzerinde hava dolu ipek yatakta uyuduğu ve başucunda evcil aslanının beklediği rivayet edilir."], "sources": [{"title": "TDV İslâm Ansiklopedisi, TOLUNOĞULLARI", "url": "https://islamansiklopedisi.org.tr/tolunogullari"}]}]}, {"id": "ihsid", "name": "İhşîdîler", "short": "İhşîdîler", "aliases": ["Akşitler", "İhşîd Devleti"], "region": "anadolu", "start": 935, "end": 969, "startNote": "Fergana hanedanından Muhammed b. Tuğç'un 935'te Mısır genel valiliğine atanmasıyla kuruldu.", "endNote": "969 yılında Fâtımî orduları kumandanı Cevher es-Sıkıllî'nin Fustat'ı fethetmesiyle sona erdi.", "capital": "Fustat", "religion": "İslamiyet (Sünnî)", "confidence": "kayit", "confidenceNote": "Kindî, İbn Zûlâk, İbnü'l-Esîr ve Makrîzî kaynaklarında detaylarıyla yazılıdır.", "summary": "Fergana Türk hükümdarlarının soyundan gelen Muhammed b. Tuğç tarafından kurulan, Mısır, Suriye, Filistin ve Hicaz'da hüküm süren Türk devleti. Abbasi halifesi tarafından Fergana krallarına verilen kadim 'İhşîd' (Akşit / Güneş Hükümdarı) unvanı verildi. Mekke ve Medine'ye hakim olan ilk Türk hanedanı oldular. 969'da Fâtımîlerin Mısır'ı işgaliyle yıkıldılar.", "legacy": "Mekke ve Medine (Haremeyn) hizmetini üstlenen ilk Türk devleti oldu. Suriye ve Mısır'ı Fâtımî yayılmasına karşı uzun süre savundu.", "essay": ["İhşîdîler hanedanı, Orta Asya'da Fergana hükümdar ailesine mensup Cuf'un torunu Muhammed b. Tuğç tarafından kuruldu. Babası Tuğç, Tolunoğullarının hizmetinde bulunmuş bir Türk kumandanıydı. Muhammed b. Tuğç, Fâtımîlerin Mısır'a yönelik ilk saldırılarını 914 ve 919 yıllarında püskürterek Abbasi sarayında büyük şöhret kazandı.", "Halife Râzî-Billâh, 935 yılında onu Mısır genel valisi yaptı ve Fergana meliklerinin unvanı olan 'İhşîd' lakabını tevcih etti. Muhammed b. Tuğç kısa sürede Suriye, Filistin ve ardından Hicaz'ı (Mekke ve Medine) hakimiyeti altına aldı. Mekke ve Medine'de adına hutbe okunan ilk Türk hükümdarı oldu.", "Muhammed b. Tuğç'un 946'da vefatından sonra çocukları yaşça küçük olduğundan idare, Nûbeli siyahi hadım Ebü'l-Misk Kâfûr'un eline geçti. Kâfûr devleti dirayetle yönetti ve Şair Mütenebbî'yi sarayında ağırladı. Ancak Kâfûr'un 968'deki ölümüyle çıkan iç karışıklıklar, kıtlık ve Fâtımî propagandası neticesinde 969'da Cevher es-Sıkıllî komutasındaki Fâtımî ordusu Mısır'a girerek İhşîdî Devleti'ne son verdi."], "sources": [{"title": "TDV İslâm Ansiklopedisi, İHŞÎDÎLER", "url": "https://islamansiklopedisi.org.tr/ihsidiler"}], "rulers": [{"id": "ihsid-muhammed", "name": "Muhammed b. Tuğç el-İhşîd", "aliases": ["El-İhşîd", "Muhammed el-İhşîd", "İhşid"], "title": "Emir / İhşîd", "birth": 882, "birthNote": "882 yılında Bağdat'ta doğdu", "death": 946, "deathNote": "Dımaşk'ta vefat etti, Kudüs'e defnedildi", "reign": [935, 946], "reignNote": "11 yıl boyunca Mısır, Suriye ve Hicaz'ı yönetti.", "summary": "İhşîdîler Devleti'nin kurucusu. Fergana Türk hanedanı kökenlidir. Fâtımî saldırılarını durdurarak Mısır'ı kurtardı. Abbasi halifesi tarafından kendisine 'İhşîd' unvanı verildi. Suriye'yi zaptedip Mekke ve Medine'yi kendine bağladı.", "traits": ["Cesur fatih", "Dirayetli yönetici", "Tedbirli"], "contribution": "Mekke ve Medine'de Türk hakimiyetini ilk kez kurdu; Mısır'ı Fâtımî istilasından korudu.", "harm": "Ağır vergiler zaman zaman halkta hoşnutsuzluk yarattı.", "wives": [], "children": [{"name": "Ebü'l-Kāsım Ünûcûr", "mother": "", "note": "İkinci hükümdar", "certainty": "kesin"}, {"name": "Ebü'l-Hasan Ali", "mother": "", "note": "Üçüncü hükümdar", "certainty": "kesin"}], "wars": [{"name": "Arîş Muharebesi", "when": "940", "foe": "İbn Râik kuvvetleri", "result": "zafer", "note": "Mısır'a saldıran İbn Râik mağlup edildi."}, {"name": "Kınnesrîn Muharebesi", "when": "945", "foe": "Hamdânîler (Seyfüddevle)", "result": "zafer", "note": "Kuzey Suriye Hamdânîlerde kaldı, Güney Suriye ve Dımaşk İhşîdîlere bağlandı."}], "legends": ["Bizans İmparatoru Romanos Lekapenos ile dostane mektuplaşmaları ve esir mübadeleleri gerçekleştirmesi dönemin diplomasisinde meşhurdur."], "sources": [{"title": "TDV İslâm Ansiklopedisi, İHŞÎDÎLER", "url": "https://islamansiklopedisi.org.tr/ihsidiler"}]}, {"id": "ihsid-kafur", "name": "Ebü'l-Misk Kâfûr", "aliases": ["Kâfûr el-İhşîdî"], "title": "Emir / Naip", "birth": 905, "birthNote": "Yaklaşık 905 doğumlu", "death": 968, "deathNote": "Fustat'ta vefat etti, Kudüs'e defnedildi", "reign": [966, 968], "reignNote": "946-966 arasında naip olarak fiili yönetici, 966-968 arasında resmen hükümdar.", "summary": "Muhammed b. Tuğç'un güvenini kazanarak şehzadelerin vasisi olan devlet adamı. 22 yıl boyunca devleti perde arkasından ve bizzat tahta çıkarak başarıyla yönetti. Şair Mütenebbî'yi himaye etti; Fâtımîleri Mısır sınırından uzak tuttu.", "traits": ["Siyasi dehâ", "Kudretli naip", "Edebiyat dostu"], "contribution": "İç karışıklıkları önleyerek Mısır'ın 20 yıl boyunca istikrarını ve Fâtımîlere karşı bağımsızlığını korudu.", "harm": "Ölümünden sonra yerine güçlü bir lider bırakamadı.", "wives": [], "children": [], "wars": [{"name": "Fâtımî Akınlarının Püskürtülmesi", "when": "958-960", "foe": "Fâtımîler", "result": "zafer", "note": "Batı sınırından gelen saldırılar bertaraf edildi."}], "legends": ["Ünlü Arap şairi Mütenebbî'nin önce onu öven, sonra umduğu valiliği alamayınca hicveden ünlü kasideleri edebiyat tarihine geçmiştir."], "sources": [{"title": "TDV İslâm Ansiklopedisi, İHŞÎDÎLER", "url": "https://islamansiklopedisi.org.tr/ihsidiler"}]}]}, {"id": "mengucek", "name": "Mengücekliler", "short": "Mengücekliler", "aliases": ["Mengücek Beyliği", "Âl-i Mengücek"], "region": "anadolu", "start": 1071, "end": 1277, "startNote": "Malazgirt Zaferi'nin ardından Mengücek Gazi'nin Erzincan, Kemah ve Divriği'yi fethetmesiyle kuruldu.", "endNote": "1277 yılında Anadolu Selçukluları ve Moğol idaresi altında tamamen lağvedildi.", "capital": "Kemah, Erzincan ve Divriği", "religion": "İslamiyet (Sünnî-Hanefî)", "confidence": "kayit", "confidenceNote": "UNESCO Dünya Mirası Divriği Ulu Camii kitabeleri, İbn Bîbî ve Süryani kronikleriyle sabittir.", "summary": "Malazgirt kahramanlarından Mengücek Gazi tarafından Erzincan, Kemah, Divriği ve Şebinkarahisar yöresinde kurulan beylik. Bilime, tıbba ve sanata büyük kıymet verdiler; meşhur tabip Abdüllatîf el-Bağdâdî'yi Erzincan sarayında ağırladılar. Hükümdar Ahmed Şah ve eşi Turan Melek tarafından 1228'de yaptırılan UNESCO Dünya Mirası Divriği Ulu Camii ve Darüşşifası, taş işçiliğinin dünyadaki en muazzam başyapıtı kabul edilir.", "legacy": "İslam taş işçiliğinin 'Görmeden ölmeyin' denilen başyapıtı Divriği Ulu Camii ve Darüşşifası'nı (UNESCO Dünya Mirası) dünya kültür hazinesine kazandırdı.", "essay": ["Mengücekliler, Malazgirt Zaferi'nin ardından Fırat'ın yukarı havzasını fetheden Mengücek Gazi tarafından kuruldu. Başlangıçta Kemah kalesi merkez yapıldı, ardından Erzincan ve Divriği gelişti.", "Fahreddin Behramşah (1162-1225) dönemi beyliğin altın çağı oldu. Şair Nizâmî-i Gencevî, meşhur 'Mahzenü'l-Esrâr' (Sırlar Hazinesi) mesnevisini Behramşah'a ithaf etti. Behramşah'ın torunu Ahmed Şah ve eşi Turan Melek Hatun, 1228'de Divriği Ulu Camii ve Darüşşifası'nı inşa ettirdi. Cami kapısındaki taş oyma süslemelerin güneş ışığıyla ikindi vaktinde namaz kılan bir insan silueti oluşturması matematik ve mimari dehanın zirvesidir. 1228'de I. Alâeddin Keykubad Erzincan kolunu ilhak etti, Divriği kolu ise 1277'ye kadar Selçuklu vassalı olarak sürdü."], "sources": [{"title": "TDV İslâm Ansiklopedisi, MENGÜCEKLİLER", "url": "https://islamansiklopedisi.org.tr/mengucekliler"}, {"title": "TDV İslâm Ansiklopedisi, DİVRİĞİ ULU CAMİİ VE DÂRÜŞŞİFASI", "url": "https://islamansiklopedisi.org.tr/divrigi-ulu-camii-ve-darussifasi"}], "rulers": [{"id": "mengucek-mengucek-gazi", "name": "Mengücek Gazi", "aliases": ["Emir Mengücek", "Mengücük Gazi"], "title": "Gazi / Emir", "birth": null, "birthNote": "Kayıtlarda yok", "death": 1118, "deathNote": "Kemah'ta şehit düştü, türbesi Kemah Kalesi eteklerindedir", "reign": [1071, 1118], "reignNote": "47 yıllık kurucu beylik ve fetih dönemi.", "summary": "Malazgirt fatihlerinden, beyliğin kurucusu. Kemah, Erzincan ve Divriği'yi Rumlardan fethedip İslamlaştırdı. Türbesi Kemah Fırat kıyısında asırlardır ziyaretgahtır.", "traits": ["Alp-gazi", "Korkusuz serhat kumandanı"], "contribution": "Fırat vadisini Türk yurdu haline getirdi.", "harm": "Kayıtlarda belirgin bir zararı geçmez.", "wives": [], "children": [{"name": "İshak Bey", "mother": "", "note": "Babasından sonra beyliği devraldı", "certainty": "kesin"}], "wars": [{"name": "Kemah ve Erzincan Fethi", "when": "1071-1075", "foe": "Bizans sınır garnizonu", "result": "zafer", "note": "Sarp Kemah kalesi fethedildi."}], "legends": ["Kemah'taki türbesinde cesedinin çürümeden mumyalanmış halde günümüze ulaştığına inanılır."], "sources": [{"title": "TDV İslâm Ansiklopedisi, MENGÜCEKLİLER", "url": "https://islamansiklopedisi.org.tr/mengucekliler"}]}, {"id": "mengucek-fahreddin-behramsah", "name": "Fahreddin Behramşah", "aliases": ["Melik Behramşah"], "title": "Melik / Gazi", "birth": null, "birthNote": "Kayıtlarda yok", "death": 1225, "deathNote": "Erzincan'da vefat etti", "reign": [1162, 1225], "reignNote": "63 yıllık adalet ve ilim çağı.", "summary": "Mengüceklilerin en büyük meliki. Selçuklu II. Kılıç Arslan'ın damadı oldu. Bilim adamlarına, hekimlere ve şairlere sınırsız imkanlar sundu. Nizâmî-i Gencevî 'Mahzenü'l-Esrâr' eserini ona ithaf edince şaire binlerce altın, köle ve hediye katarları gönderdi.", "traits": ["İlim ve şiir aşığı", "Cömertlik abidesi", "Adil melik"], "contribution": "Erzincan'ı doğunun en saygın ilim ve tıp merkezlerinden biri yaptı.", "harm": "Ölümüyle oğulları Selçuklulara karşı direnemedi.", "wives": [{"name": "Selçuklu Prensesi", "note": "II. Kılıç Arslan'ın kızı", "certainty": "kesin"}], "children": [{"name": "Dâvud Şah", "mother": "", "note": "Erzincan meliki", "certainty": "kesin"}, {"name": "Hüsamettin Ahmed Şah", "mother": "", "note": "Divriği Ulu Camii'ni yaptıran melik", "certainty": "kesin"}], "wars": [], "legends": ["Gence'den gelen elçinin getirdiği şiire karşılık şair Nizâmî'ye deve yükleriyle kumaş ve altın gönderdiği Cüveynî'de anlatılır."], "sources": [{"title": "TDV İslâm Ansiklopedisi, MENGÜCEKLİLER", "url": "https://islamansiklopedisi.org.tr/mengucekliler"}]}]}, {"id": "saltuklu", "name": "Saltuklular", "short": "Saltuklular", "aliases": ["Saltuklu Beyliği", "Âl-i Saltuk"], "region": "anadolu", "start": 1072, "end": 1202, "startNote": "Malazgirt Zaferi'nin ardından Ebü'l-Kāsım Saltuk'un Erzurum ve Kars havalisini fethetmesiyle kuruldu.", "endNote": "1202 yılında Rükneddin Süleyman Şah'ın Gürcü seferi sırasında Erzurum'u ilhak etmesiyle sona erdi.", "capital": "Erzurum", "religion": "İslamiyet (Sünnî-Hanefî)", "confidence": "kayit", "confidenceNote": "İbnü'l-Esîr, Ahbârü'd-Devleti's-Selcûkıyye ve Erzurum kitabeleriyle sabittir.", "summary": "Malazgirt Zaferi sonrası Doğu Anadolu'da kurulan ilk Türk beyliği. Erzurum merkezli olarak Bayburt, Kars, Oltu ve İspir bölgelerine hakim oldular. Gürcü Krallığı'nın akınlarına karşı İslam sınır boylarını korudular. Erzurum Kale Mescidi, Tepsi Minare, Ulu Cami ve Tercan'daki ünlü Mama Hatun Kümbeti ve Kervansarayı bu beyliğin şaheserleridir.", "legacy": "Doğu Anadolu'nun kapısı Erzurum'u Türk-İslam mimarisinin abidevi eserleriyle donattı; Türk kadınının devlet yöneticiliğindeki dirayetini simgeleyen Mama Hatun Külliyesi'ni armağan etti.", "essay": ["Saltuklular, Sultan Alparslan'ın Malazgirt Zaferi'nden sonra fethettiği Erzurum ve civarını dirlik olarak verdiği kumandanı Ebü'l-Kāsım Saltuk Bey tarafından 1072'de kuruldu.", "Beylik en parlak devrini II. İzzeddin Saltuk (1132-1168) ve kızı Mama Hatun zamanında yaşadı. Mama Hatun, Tercan'da kendi adına yaptırdığı dairevi planlı eşsiz kümbet, kervansaray ve hamamıyla Türk kadın hükümdarlarının zarafet ve kudret timsali oldu. 1202 yılında Anadolu Selçuklu Sultanı Rükneddin Süleyman Şah, Gürcü seferi sırasında itaatsizlik gösteren son Saltuklu beyi Alâeddin Muhammed'i tutuklayarak beyliği Anadolu Selçuklu Devleti'ne bağladı."], "sources": [{"title": "TDV İslâm Ansiklopedisi, SALTUKLULAR", "url": "https://islamansiklopedisi.org.tr/saltuklular"}], "rulers": [{"id": "saltuklu-ebul-kasim", "name": "Ebü'l-Kāsım Saltuk Bey", "aliases": ["Saltuk Gazi", "Emir Saltuk"], "title": "Emir / Bey", "birth": null, "birthNote": "Kayıtlarda yok", "death": 1102, "deathNote": "Erzurum'da vefat etti", "reign": [1072, 1102], "reignNote": "30 yıllık kurucu beylik.", "summary": "Malazgirt komutanlarından, Erzurum'un fatihi ve beyliğin kurucusu. Gürcü ve Bizans saldırılarına karşı sınır boyunu müdafaa etti; Erzurum Kalesi'ni tahkim ettirdi.", "traits": ["Gazi komutan", "Serhat muhafızı"], "contribution": "Doğu Anadolu'da ilk Türk yerleşimini ve idaresini kurdu.", "harm": "Kayıtlarda belirgin bir zararı geçmez.", "wives": [], "children": [{"name": "Ali b. Saltuk", "mother": "", "note": "İkinci bey", "certainty": "kesin"}], "wars": [{"name": "Erzurum Fethi", "when": "1072", "foe": "Bizans ve Gürcü garnizonları", "result": "zafer", "note": "Erzurum fethedilip başkent yapıldı."}], "legends": [], "sources": [{"title": "TDV İslâm Ansiklopedisi, SALTUKLULAR", "url": "https://islamansiklopedisi.org.tr/saltuklular"}]}, {"id": "saltuklu-mama-hatun", "name": "Melike Mama Hatun", "aliases": ["Mama Hatun"], "title": "Melike / Kadın Hükümdar", "birth": null, "birthNote": "Kayıtlarda yok", "death": 1201, "deathNote": "Tercan veya Erzurum'da vefat etti", "reign": [1191, 1200], "reignNote": "Saltuklu tahtını tek başına dirayetle yöneten kadın hükümdar.", "summary": "II. Saltuk'un kızı. 10 yıl boyunca Saltuklu tahtında oturarak beyliği yönetti. Eyyûbîlerle diplomatik ilişkiler kurdu. Tercan'da inşa ettirdiği, Türk mimarisinin dünya çapındaki şaheseri sayılan dilimli kubbeli Mama Hatun Kümbeti ve Kervansarayı ile ölümsüzleşti.", "traits": ["Dirayetli kadın lider", "Sanat ve mimari hamisi", "Adil"], "contribution": "Anadolu'da eşsiz bir mimari külliye inşa ettirdi; kadın hükümdarlık geleneğinin seçkin bir temsilcisi oldu.", "harm": "Evlilik meselesinde beylerle anlaşmazlığa düşüp tahttan indirildi.", "wives": [], "children": [], "wars": [], "legends": ["Ahlatlı Mimar Ebü'n-Nemâ b. Mufaddal'a yaptırdığı dairevi planlı türbe mimarlık tarihinde dünyada tektir."], "sources": [{"title": "TDV İslâm Ansiklopedisi, MAMA HATUN", "url": "https://islamansiklopedisi.org.tr/mama-hatun"}, {"title": "TDV İslâm Ansiklopedisi, SALTUKLULAR", "url": "https://islamansiklopedisi.org.tr/saltuklular"}]}]}, {"id": "anadolu-selcuklu", "name": "Anadolu Selçuklu Devleti", "short": "Türkiye Selçukluları", "aliases": ["Türkiye Selçuklu Devleti", "Rum Selçukluları", "Sultanate of Rum"], "region": "anadolu", "start": 1077, "end": 1308, "startNote": "Kutalmışoğlu Süleyman Şah'ın İznik'i fethederek başkent yapmasıyla kuruldu.", "endNote": "1308 yılında Sultan II. Mesud'un vefatıyla hanedan sona erdi; Anadolu beylikler dönemine girdi.", "capital": "İznik (1077-1097), ardından Konya (1097-1308)", "religion": "İslamiyet (Sünnî-Hanefî)", "confidence": "kayit", "confidenceNote": "İbn Bîbî (el-Evâmirü'l-Alâiyye), Kerîmüddin Aksarâyî (Müsâmeretü'l-Ahbâr) ve Bizans kronikleriyle sabittir.", "summary": "1071 Malazgirt Zaferi'nin ardından Kutalmışoğlu Süleyman Şah tarafından İznik merkezli kurulan, I. Haçlı Seferi'nden sonra başkenti Konya'ya taşıyan büyük Türk devleti. II. Kılıç Arslan devrinde 1176 Miryokefalon Zaferi ile Anadolu'nun tapusu kesin olarak alındı ve Avrupalılar Anadolu'ya 'Turchia' (Türkiye) demeye başladı. I. Alâeddin Keykubad zamanında kervansaraylar, tersaneler ve kalelerle Akdeniz ve Karadeniz ticaretine hükmeden bir refah imparatorluğu oldu. 1243 Kösedağ hezimetinin ardından İlhanlı Moğol vesayetine girdi ve 1308'de dağıldı.", "legacy": "Anadolu'yu geri dönülemez biçimde kalıcı bir Türk ve İslam yurdu kıldı. İpek Yolu üzerinde inşa ettiği yüzlerce kervansaray, medrese, darüşşifa ve kümbetlerle eşsiz Selçuklu mimarisini miras bıraktı. Mevlânâ Celâleddîn-i Rûmî, Yûnus Emre ve Hacı Bektâş-ı Velî gibi manevi kurucuların ocağı oldu.", "essay": ["Anadolu Selçuklu Devleti, Büyük Selçuklu hanedan ailesinden Arslan Yabgu'nun torunu Kutalmışoğlu Süleyman Şah'ın Türkmen boylarıyla Anadolu içlerine akmasıyla doğdu. 1075-1077 yıllarında Bizans'ın elindeki İznik'i fetheden Süleyman Şah, başkentini İstanbul Boğazı'nın yanı başında kurdu. 1086'da Antakya yakınlarında Suriye Meliki Tutuş ile yaptığı savaşta şehit düştü.", "Oğlu I. Kılıç Arslan (1092-1107), 1096-1097'de yüz binlerce kişilik I. Haçlı Seferi ordularına karşı İznik'i kahramanca savundu; şehri Bizans'a bırakmak zorunda kalınca devlet merkezini Konya'ya nakletti. Haçlı ordularını Eskişehir ve Toroslar'da gerilla taktikleriyle yıprattı. II. Kılıç Arslan (1155-1192) devrinde Bizans İmparatoru Manuel Komnenos büyük bir orduyla Anadolu'yu geri almak için harekete geçtiyse de 17 Eylül 1176'da Eğirdir gölü yakınlarındaki Miryokefalon Geçidi'nde Türk ordusunca pusuya düşürülüp tamamen imha edildi. Bu zaferle Bizans'ın Türkleri Anadolu'dan atma ümidi ebediyen söndü.", "Devlet en parlak devrini I. Alâeddin Keykubad (1220-1237) zamanında yaşadı. Akdeniz'de Alâiye (Alanya) fethedilerek tersane kuruldu; Karadeniz'de Kırım'daki Suğdak limanına ilk denizaşırı deniz seferi düzenlendi. Anadolu baştan başa kervansaraylarla örüldü, dünyada ilk devlet sigortacılığı sistemi uygulandı. Ancak Keykubad'ın zehirlenerek ölümü ve ehliyetsiz vezir Sadettin Köpek'in entrikaları devleti zaafa uğrattı. 1240 Babâî İsyanı ile sarsılan ordu, 1243 Kösedağ Muharebesi'nde Moğol kumandanı Baycu Noyan'a mağlup oldu. Devlet Moğol haraçgüzarı haline geldi ve 1308'de son sultan II. Mesud'un ölümüyle tarih sahnesinden çekildi."], "sources": [{"title": "TDV İslâm Ansiklopedisi, ANADOLU SELÇUKLULARI", "url": "https://islamansiklopedisi.org.tr/anadolu-selcuklulari"}, {"title": "TDV İslâm Ansiklopedisi, ALÂEDDİN KEYKUBAD I", "url": "https://islamansiklopedisi.org.tr/alaeddin-keykubad-i"}, {"title": "TDV İslâm Ansiklopedisi, KILIÇARSLAN II", "url": "https://islamansiklopedisi.org.tr/kilicarslan-ii"}], "rulers": [{"id": "anadolu-selcuklu-suleyman-sah", "name": "Kutalmışoğlu Süleyman Şah", "aliases": ["I. Süleyman Şah", "Süleyman bin Kutalmış"], "title": "Sultan / Fatih", "birth": null, "birthNote": "Kayıtlarda yok", "death": 1086, "deathNote": "Ayn Seylem Muharebesi'nde Tutuş'a yenilince kendi hançeriyle intihar etti veya öldürüldü", "reign": [1077, 1086], "reignNote": "9 yıllık kurucu hükümdarlık.", "summary": "Anadolu Selçuklu Devleti'nin kurucusu. İznik'i fethederek başkent yaptı; Marmara ve Boğaziçi kıyılarına kadar uzanıp Bizans iç siyasetinde imparator belirleyecek güce ulaştı. 1084'te Antakya'yı fethetti; Suriye Meliki Tutuş ile savaşında vefat etti.", "traits": ["Büyük fatih", "Cesur komutan", "Teşkilatçı"], "contribution": "Anadolu'da bağımsız Türk devletini kurdu; İznik ve Antakya'yı fethetti.", "harm": "Büyük Selçuklu hanedan mensuplarıyla girdiği çatışma erken ölümüne ve devletin 6 yıl başsız kalmasına yol açtı.", "wives": [], "children": [{"name": "I. Kılıç Arslan", "mother": "", "note": "İkinci sultan, Haçlı savaşçısı", "certainty": "kesin"}, {"name": "Kulan Arslan (Davud)", "mother": "", "note": "Şehzade", "certainty": "kesin"}], "wars": [{"name": "İznik'in Fethi", "when": "1075", "foe": "Bizans İmparatorluğu", "result": "zafer", "note": "İznik fethedilip başkent yapıldı."}, {"name": "Antakya Fethi", "when": "1084", "foe": "Bizans valisi Philaretos", "result": "zafer", "note": "Müstahkem Antakya kalesi gece baskınıyla fethedildi."}, {"name": "Ayn Seylem Muharebesi", "when": "1086", "foe": "Suriye Selçuklu Meliki Tutuş", "result": "yenilgi", "note": "Süleyman Şah savaşta vefat etti, oğulları İsfahan'a rehin götürüldü."}], "legends": ["Mezarı Caber Kalesi eteklerinde 'Türk Mezarı' olarak asırlarca Türk bayrağı altında saygıyla korundu."], "sources": [{"title": "TDV İslâm Ansiklopedisi, SÜLEYMAN ŞAH I", "url": "https://islamansiklopedisi.org.tr/suleyman-sah-i"}]}, {"id": "anadolu-selcuklu-kilic-arslan-1", "name": "I. Kılıç Arslan", "aliases": ["Ebû'l-Kāsım Kılıç Arslan"], "title": "Sultan", "birth": 1079, "birthNote": "1079 doğumlu", "death": 1107, "deathNote": "Habur çayında zırhının ağırlığıyla atıyla birlikte boğularak şehit oldu", "reign": [1092, 1107], "reignNote": "15 yıllık Haçlı seferleriyle dolu kahramanlık devri.", "summary": "Süleyman Şah'ın oğlu. Melikşah'ın ölümü üzerine esaretten dönüp İznik'te tahta çıktı. 1096'da Keşiş Pierre l'Ermite'in ilk Haçlı sürüsünü Yalova'da tamamen imha etti. I. Haçlı Seferi'nin devasa şövalye ordularına karşı başkenti Konya'ya taşıyıp gerilla savaşıyla Haçlılara ağır kayıplar verdirdi. Musul'u fethettikten sonra Habur nehrinde şehit düştü.", "traits": ["Haçlı fatihi", "Yılmayan savaşçı", "Millet muhafızı"], "contribution": "Haçlı ordularının Anadolu'da tutunmasını engelleyerek Türk varlığını korudu; Konya'yı ebedi başkent yaptı.", "harm": "Kayınpederi Çaka Bey'i Bizans entrikasıyla öldürtmesi Ege'deki deniz gücünü yok etti.", "wives": [{"name": "Ayşe Hatun", "note": "Çaka Bey'in kızı", "certainty": "kesin"}], "children": [{"name": "I. Mesud", "mother": "", "note": "Uzun süre hüküm süren kudretli sultan", "certainty": "kesin"}, {"name": "Melikşah (Şahinşah)", "mother": "", "note": "Taht mücadelesine girdi", "certainty": "kesin"}, {"name": "Tuğrul Arslan", "mother": "", "note": "Malatya meliki", "certainty": "kesin"}], "wars": [{"name": "Halk Haçlı Seferi İmhası (Kibotos)", "when": "1096", "foe": "Pierre l'Ermite ve Walter Sans-Avoir komutasındaki Haçlılar", "result": "zafer", "note": "20 binden fazla Haçlı Yalova'da kılıçtan geçirildi."}, {"name": "Dorylaion (Eskişehir) Muharebesi", "when": "1097", "foe": "I. Haçlı Seferi büyük ordusu (Bohemund, Godfrey)", "result": "yenilgi", "note": "Sayıca üstün Haçlılara karşı gerilla taktiğine dönüldü, başkent Konya'ya taşındı."}, {"name": "1101 Haçlı Seferlerinin İmhası", "when": "1101", "foe": "Fransız, Alman ve Lombard Haçlı orduları", "result": "zafer", "note": "Danişmend Gazi ile birleşerek Merzifon, Konya ve Ereğli'de üç ayrı Haçlı ordusunu yok etti."}], "legends": ["Silvan'daki kayıp mezarı (Kümbet-i Sultan) 2021 yılında Türk tarihçileri ve arkeologlarınca keşfedilmiştir."], "sources": [{"title": "TDV İslâm Ansiklopedisi, KILIÇARSLAN I", "url": "https://islamansiklopedisi.org.tr/kilicarslan-i"}]}, {"id": "anadolu-selcuklu-kilic-arslan-2", "name": "II. Kılıç Arslan", "aliases": ["İzzeddin Kılıç Arslan"], "title": "Sultan / Gazi", "birth": 1113, "birthNote": "Yaklaşık 1113 doğumlu", "death": 1192, "deathNote": "Konya'da 79 yaşında vefat etti", "reign": [1155, 1192], "reignNote": "37 yıllık muhteşem saltanat.", "summary": "I. Mesud'un oğlu. 1176 Miryokefalon Zaferi ile Bizans ordusunu perişan ederek Anadolu'nun ebediyen Türk yurdu olduğunu tescil ettirdi. Danişmendli beyliğine son vererek Anadolu Türk birliğini ilk kez geniş ölçüde kurdu. Aksaray şehrini kurdu, ilk Selçuklu gümüş ve altın parasını bastırdı.", "traits": ["Büyük stratejist", "İmar hamisi", "Metanetli"], "contribution": "Miryokefalon Zaferi ile Anadolu'nun Türklüğünü kesinleştirdi; kervansaray mimarisini başlattı (Alay Han).", "harm": "Yaşlılığında ülkeyi 11 oğlu arasında paylaştırması ölümünden önce ve sonra kanlı iç savaşlara yol açtı.", "wives": [], "children": [{"name": "Kutbeddin Melikşah", "mother": "", "note": "Sivas meliki, babasına isyan etti", "certainty": "kesin"}, {"name": "I. Gıyâseddin Keyhüsrev", "mother": "", "note": "Tahtı devralan sultan", "certainty": "kesin"}, {"name": "Rükneddin Süleyman Şah", "mother": "", "note": "Kardeşlerini tasfiye edip tek başına sultan oldu", "certainty": "kesin"}, {"name": "Muhyiddin Mesud Şah", "mother": "", "note": "Ankara meliki", "certainty": "kesin"}], "wars": [{"name": "Miryokefalon Meydan Muharebesi", "when": "1176", "foe": "Bizans İmparatorluğu (Manuel I Komnenos)", "result": "zafer", "note": "Bizans ordusu dar dağ geçidinde pusuya düşürülüp imha edildi, Bizans ağır tazminat ödedi."}], "legends": ["Miryokefalon zaferinden sonra Batılı kroniklerin Anadolu'ya 'Turchia' (Türklerin Yurdu) adını vermeye başlaması bu zaferin meyvesidir."], "sources": [{"title": "TDV İslâm Ansiklopedisi, KILIÇARSLAN II", "url": "https://islamansiklopedisi.org.tr/kilicarslan-ii"}]}, {"id": "anadolu-selcuklu-alaeddin-keykubad", "name": "I. Alâeddin Keykubad", "aliases": ["Alâeddin Keykubad", "Uluğ Sultan"], "title": "Sultan / Sultanü'l-Gālib", "birth": 1190, "birthNote": "1190 doğumlu", "death": 1237, "deathNote": "Kayseri Meşhedliğindeki ziyafette av etinden zehirlenerek şehit edildi", "reign": [1220, 1237], "reignNote": "17 yıllık altın çağ.", "summary": "Anadolu Selçuklularının en kudretli ve en büyük sultanı. Akdeniz'de Kalonoros kalesini fethedip Alâiye (Alanya) adıyla donanma üssü ve kışlık başkent yaptı. Karadeniz'de Kırım'a donanma gönderip Suğdak'ı fethetti. Konya, Sivas ve Kayseri surlarını tahkim etti, kervansaraylarla ülkeyi donattı. Yassıçemen'de Harzemşah Celâleddin'i mağlup etti. Moğol tehlikesine karşı tedbirler alırken zehirlendi.", "traits": ["Cihan devleti hükümdarı", "Mimar ve şehir kurucusu", "Yüksek adalet ve basiret"], "contribution": "Türkiye'yi denizci bir ticaret imparatorluğuna yükseltti; kervansaray ağı ve tüccar sigortasıyla iktisadi altın çağı inşa etti.", "harm": "Ani zehirlenmesi devletin liyakatsiz vezir Sadettin Köpek'in eline düşmesine yol açtı.", "wives": [{"name": "Mahperi Hunat Hatun", "note": "Alanya tekfurunun kızı, Kayseri'deki Hunat Hatun Külliyesi'ni yaptıran dindar valide sultan", "certainty": "kesin"}, {"name": "Melike Âdile Hatun", "note": "Eyyûbî Sultanı el-Âdil'in kızı", "certainty": "kesin"}], "children": [{"name": "II. Gıyâseddin Keyhüsrev", "mother": "Mahperi Hunat Hatun", "note": "Kösedağ'da mağlup olan sultan", "certainty": "kesin"}, {"name": "İzzettin Kılıç Arslan", "mother": "Melike Âdile Hatun", "note": "Keykubad'ın veliahtıydı, katledildi", "certainty": "kesin"}, {"name": "Rükneddin", "mother": "Melike Âdile Hatun", "note": "Şehzade, katledildi", "certainty": "kesin"}], "wars": [{"name": "Kalonoros (Alanya) Kuşatması", "when": "1221", "foe": "Ermeni Kir Fard tekfurluğu", "result": "zafer", "note": "Alanya fethedildi, tersane ve Kızıl Kule inşa edildi."}, {"name": "Suğdak Kırım Deniz Seferi", "when": "1224", "foe": "Kıpçaklar ve Rus dükleri", "result": "zafer", "note": "Emir Hüsameddin Çoban donanmayla Kırım'a çıktı, Suğdak alındı."}, {"name": "Yassıçemen Muharebesi", "when": "1230", "foe": "Harzemşahlar (Celâleddin)", "result": "zafer", "note": "Erzincan yakınlarında Celâleddin mağlup edildi, doğu sınırları emniyete alındı."}], "legends": ["Konya ve Sivas surlarının taşlarına şairlerin beyitlerini ve kentin koruyucu çift başlı kartal tılsımlarını bizzat elleriyle koydurduğu anlatılır."], "sources": [{"title": "TDV İslâm Ansiklopedisi, ALÂEDDİN KEYKUBAD I", "url": "https://islamansiklopedisi.org.tr/alaeddin-keykubad-i"}]}]}, {"id": "danismendli", "name": "Dânişmendliler", "short": "Dânişmendliler", "aliases": ["Dânişmend Beyliği", "Âl-i Dânişmend"], "region": "anadolu", "start": 1080, "end": 1178, "startNote": "Malazgirt fatihlerinden Dânişmend Gazi tarafından Sivas merkezli kuruldu.", "endNote": "1178'de II. Kılıç Arslan'ın Malatya koluna son vermesiyle Anadolu Selçuklu Devleti'ne bağlandı.", "capital": "Sivas, Niksar ve Malatya", "religion": "İslamiyet (Sünnî-Hanefî)", "confidence": "kayit", "confidenceNote": "Dânişmendnâme destanı, İbnü'l-Esîr, Süryani Mihail ve Bizans kronikleriyle sabittir.", "summary": "Malazgirt Zaferi'nden sonra Orta ve Kuzey Anadolu'da (Sivas, Tokat, Niksar, Amasya, Kayseri, Malatya) kurulan en güçlü Türk beyliği. Haçlı Seferleri'ne karşı kahramanca savaştılar; Antakya Haçlı Prensi Bohemund'u esir alıp Niksar kalesine hapsettiler. Anadolu'da ilk tıp medresesi olan Tokat ve Niksar Yağıbasan Medresesi'ni (kapalı kubbeli) inşa ettiler. Dânişmend Gazi'nin kahramanlıkları Dânişmendnâme adıyla halk destanına dönüştü.", "legacy": "Anadolu'da ilk kubbeli Türk medresesini (Niksar ve Tokat Yağıbasan Medreseleri) inşa etti; Dânişmendnâme Türk halk edebiyatının kurucu şaheseri oldu.", "essay": ["Dânişmendliler, Sultan Alparslan'ın Anadolu fethiyle görevlendirdiği ve ilmi kişiliği dolayısıyla 'Dânişmend' (bilgin/hoca) lakabıyla anılan Ahmed Gazi tarafından 1080 civarında Sivas merkezli kuruldu.", "Melik Gazi devrinde I. Kılıç Arslan ile birleşerek 1101 yılı Haçlı dalgalarını Merzifon ve Ereğli'de imha ettiler. Antakya Prensi Bohemund'u esir alarak İslam dünyasında büyük şöhret kazandılar. Melik Muhammed ve Nizamettin Yağıbasan dönemlerinde Kayseri ve Tokat muhteşem imar hareketleriyle donatıldı.", "Hanedanın Sivas, Kayseri ve Malatya kollarına ayrılması gücünü zayıflattı. 1178 yılında Anadolu Selçuklu Sultanı II. Kılıç Arslan bütün Dânişmendli topraklarını ilhak ederek Anadolu Türk birliğini kurdu."], "sources": [{"title": "TDV İslâm Ansiklopedisi, DÂNİŞMENDLİLER", "url": "https://islamansiklopedisi.org.tr/danismendliler"}, {"title": "TDV İslâm Ansiklopedisi, DÂNİŞMEND GAZİ", "url": "https://islamansiklopedisi.org.tr/danismend-gazi"}], "rulers": [{"id": "danismendli-ahmed-gazi", "name": "Dânişmend Gazi", "aliases": ["Dânişmend Ahmed Gazi", "Gümüştekin Ahmed Gazi"], "title": "Melik / Gazi", "birth": null, "birthNote": "Kayıtlarda yok", "death": 1104, "deathNote": "Niksar'da vefat etti, türbesi oradadır", "reign": [1080, 1104], "reignNote": "24 yıllık gazalarla dolu beylik.", "summary": "Beyliğin kurucusu ve Dânişmendnâme kahramanı. Sivas, Niksar, Çorum ve Tokat'ı fethederek Türk yurdu yaptı. 1100 yılında Antakya Prinkepsi Bohemund'u Malatya önlerinde esir alarak İslam dünyasına bayram yaşattı.", "traits": ["Âlim savaşçı", "Destan kahramanı", "Adil"], "contribution": "Orta Karadeniz ve Sivas havzasının fethini ve Türkleşmesini sağladı.", "harm": "Malatya kuşatması yüzünden Selçuklu Sultanı Kılıç Arslan ile çekişti.", "wives": [], "children": [{"name": "Emir Gazi (Gümüştekin)", "mother": "", "note": "Babasından sonra tahta oturdu, Abbasi halifesi meliklik menşuru verdi", "certainty": "kesin"}], "wars": [{"name": "Malatya Muharebesi (Bohemund'un Esareti)", "when": "1100", "foe": "Antakya Haçlı Prensliği (I. Bohemund)", "result": "zafer", "note": "Bohemund esir edildi, Niksar kalesine hapsedildi, 100 bin altın fidye alındı."}], "legends": ["Dânişmendnâme'de Battal Gazi'nin soyundan geldiği ve rüyasında Peygamber Efendimiz tarafından Anadolu fethine memur edildiği anlatılır."], "sources": [{"title": "TDV İslâm Ansiklopedisi, DÂNİŞMEND GAZİ", "url": "https://islamansiklopedisi.org.tr/danismend-gazi"}]}]}, {"id": "caka-beyligi", "name": "Çaka Beyliği", "short": "Çaka Beyliği", "aliases": ["İzmir Türk Beyliği"], "region": "anadolu", "start": 1081, "end": 1093, "startNote": "Çaka Bey'in Bizans esaretinden kurtulup 1081'de İzmir'i fethederek ilk Türk donanmasını kurmasıyla başladı.", "endNote": "1093 yılında damadı Anadolu Selçuklu Sultanı I. Kılıç Arslan tarafından bir ziyafette öldürülmesiyle yıkıldı.", "capital": "İzmir (Smyrna)", "religion": "İslamiyet (Sünnî)", "confidence": "kayit", "confidenceNote": "Anna Komnena'nın Alexiad eseriyle en ince ayrıntısına kadar belgelidir.", "summary": "Tarihteki ilk Türk denizcisi ve amirali kabul edilen Çaka Bey tarafından İzmir merkezli kurulan beylik. 40 parçalık ilk Türk donanmasını inşa ederek Urla, Foça, Midilli, Sakız, Sisam ve Rodos adalarını fethetti. 1090 yılında Koyun Adaları Deniz Muharebesi'nde Bizans donanmasını hezimete uğratarak tarihteki ilk Türk deniz zaferini kazandı. İstanbul'u Peçenekler ile ortaklaşa fethetmeyi planlarken Bizans İmparatoru Aleksios Komnenos'un entrikası sonucu damadı I. Kılıç Arslan tarafından öldürüldü.", "legacy": "Türk Deniz Kuvvetleri'nin kuruluş tarihi kabul edilen 1081 yılını ve ilk Türk amiralliği mirasını tarihe hediye etti.", "essay": ["Çaka Bey, Malazgirt Zaferi sonrası Batı Anadolu akınlarına katılan bir Türkmen beyi iken 1078 civarında Bizans kumandanı Kabalika Aleksandros'a esir düşerek İstanbul'a saraya götürüldü. Burada Yunancayı ve Bizans saray entrikalarını, denizcilik ve gemi yapım tekniklerini öğrendi. İmparator Botaneiates ona 'protonobilissimos' unvanı verdi.", "1081'de I. Aleksios Komnenos tahta çıkınca rütbeleri elinden alınan Çaka Bey İstanbul'dan kaçarak İzmir'e geldi. İzmir'i fethedip burada bir tersane kurdu ve 40 parçalık kürekli ve yelkenli ilk Türk donanmasını inşa etti. Bu tarih (1081), modern Türk Deniz Kuvvetleri'nin de resmi kuruluş yılıdır.", "Çaka Bey Ege Denizi'ne açılarak Klazomenai (Urla), Phokaia (Foça) limanlarını ve Sakız, Midilli, Sisam adalarını fethetti. 19 Mayıs 1090'da Sakız açıklarında Koyun Adaları Deniz Muharebesi'nde Bizans Amiralı Niketas Kastamonites komutasındaki donanmayı ağır bir yenilgiye uğrattı. Kendisine 'İmparator' (Basileus) unvanı veren Çaka Bey, Trakya'daki Peçenek Türkleriyle anlaşarak İstanbul'u denizden ve karadan kuşatma planı yaptı. Ancak Bizans İmparatoru Aleksios, Anadolu Selçuklu Sultanı I. Kılıç Arslan'a mektup yazarak Çaka Bey'in onu tahtından edeceğini fısıldadı; 1093'te Abydos kuşatması sırasında Kılıç Arslan kayınpederi Çaka Bey'i bir ziyafette kılıçla öldürttü ve beylik dağıldı."], "sources": [{"title": "TDV İslâm Ansiklopedisi, ÇAKA BEY", "url": "https://islamansiklopedisi.org.tr/caka-bey"}, {"title": "Britannica, Tzachas", "url": "https://www.britannica.com/biography/Tzachas"}], "rulers": [{"id": "caka-bey", "name": "Çaka Bey", "aliases": ["Tzachas", "Çaka Gazi"], "title": "Emir / İlk Türk Amirali", "birth": null, "birthNote": "Kayıtlarda yok", "death": 1093, "deathNote": "Abydos'ta I. Kılıç Arslan tarafından bir ziyafette katledildi", "reign": [1081, 1093], "reignNote": "12 yıl boyunca Ege'ye hükmetti.", "summary": "İlk Türk denizcisi ve amirali. İzmir'de ilk Türk donanmasını inşa etti. Ege adalarını fethetti, 1090 Koyun Adaları zaferiyle Bizans donanmasını yendi. İstanbul'u fethetmeyi tasarlarken Bizans entrikasıyla katledildi.", "traits": ["Öncü denizci", "Dahi amiral", "Stratejist"], "contribution": "Türklere denizcilik ufkunu kazandırdı; ilk Türk tersanesini ve donanmasını kurdu.", "harm": "Hedeflerini çok erken aşamada açık etmesi Bizans ve Selçukluları kendisine karşı birleştirdi.", "wives": [], "children": [{"name": "Ayşe Hatun", "mother": "", "note": "I. Kılıç Arslan ile evlendi", "certainty": "kesin"}], "wars": [{"name": "Koyun Adaları Deniz Muharebesi", "when": "1090", "foe": "Bizans İmparatorluk Donanması (Kastamonites)", "result": "zafer", "note": "Tarihteki ilk Türk deniz zaferi kazanıldı, Bizans donanması yok edildi."}, {"name": "Midilli ve Sakız Seferleri", "when": "1089", "foe": "Bizans Ege garnizonları", "result": "zafer", "note": "Ege adaları Türk hakimiyetine girdi."}], "legends": ["Bizans prensesi Anna Komnena'nın Alexiad adlı eserinde Çaka Bey'in denizdeki cüreti ve savaş zekası korkuyla karışık bir hayranlıkla anlatılır."], "sources": [{"title": "TDV İslâm Ansiklopedisi, ÇAKA BEY", "url": "https://islamansiklopedisi.org.tr/caka-bey"}]}]}, {"id": "ahlatsah", "name": "Ahlatşahlar", "short": "Ahlatşahlar (Sökmenliler)", "aliases": ["Ermenşahlar", "Sökmeniyye Devleti"], "region": "anadolu", "start": 1100, "end": 1207, "startNote": "Sökmen el-Kutbî'nin Ahlat ve Van Gölü çevresinde beyliğini kurmasıyla temellendi.", "endNote": "1207 yılında Eyyûbîlerin Ahlat'ı zaptetmesiyle tarih sahnesinden çekildi.", "capital": "Ahlat", "religion": "İslamiyet (Sünnî-Hanefî)", "confidence": "kayit", "confidenceNote": "İbnü'l-Esîr, Râvendî ve Ahlat Selçuklu Meydan Mezarlığı taş kitabeleriyle sabittir.", "summary": "Van Gölü havzasında (Ahlat, Erciş, Adilcevaz, Van, Bitlis, Malazgirt) hüküm süren Türk devleti. Selçuklu emiri Sökmen el-Kutbî tarafından kuruldu. Başkent Ahlat 'Kubbetü'l-İslam' (İslam'ın Kubbesi) unvanını aldı; yüz binlerce nüfusu, zengin tüccarları ve devasa mezar taşlarıyla dünyanın en büyük Türk nekropolünü meydana getirdi. Gürcülere karşı Doğu Anadolu'yu savundular.", "legacy": "Dünyanın en büyük tarihi İslam mezarlığı olan Ahlat Selçuklu Meydan Mezarlığı'ndaki abidevi şahideleri, kümbetleri ve zengin taş işçiliği ekolünü miras bıraktı.", "essay": ["Ahlatşahlar, Büyük Selçuklu veliahtı Kutbeddin İsmail'in kölesi (gulâmı) olan Sökmen el-Kutbî tarafından 1100 yılında Van Gölü kıyısındaki Ahlat merkez yapılarak kuruldu.", "II. Sökmen (1128-1185) dönemi Ahlat'ın en mamur ve zengin çağı oldu. Şehir sanatkârlar, hattatlar ve taş yontucularıyla doldu; 'Kubbetü'l-İslam' sıfatını Belh ve Buhara ile paylaştı. Ahlat mezar taşları birer heykel zarafetinde işlendi. II. Sökmen'in çocuksuz vefatı üzerine idare memlük kumandanların eline geçti; iç çekişmeleri fırsat bilen Eyyûbîler 1207'de şehri işgal etti."], "sources": [{"title": "TDV İslâm Ansiklopedisi, AHLATŞAHLAR", "url": "https://islamansiklopedisi.org.tr/ahlat-sahlar"}], "rulers": [{"id": "ahlatsah-sokmen", "name": "Sökmen el-Kutbî", "aliases": ["I. Sökmen", "Ahlatşah Sökmen"], "title": "Şah / Emir", "birth": null, "birthNote": "Kayıtlarda yok", "death": 1111, "deathNote": "Haçlı seferinden dönerken hastalanarak vefat etti", "reign": [1100, 1111], "reignNote": "11 yıl hüküm sürdü.", "summary": "Ahlatşahlar Devleti'nin kurucusu. Van Gölü havzasını tek bayrak altında topladı. Haçlılara karşı Suriye'deki cihat ordularına katılarak büyük kahramanlıklar gösterdi.", "traits": ["Gazi", "Şehir kurucu", "Cesur"], "contribution": "Van Gölü havzasında zengin bir Türk medeniyet odağı kurdu.", "harm": "Kayıtlarda belirgin bir zararı geçmez.", "wives": [], "children": [{"name": "Zahîreddîn İbrâhim", "mother": "", "note": "İkinci hükümdar", "certainty": "kesin"}], "wars": [{"name": "Tel Bâşir Kuşatması", "when": "1108", "foe": "Haçlılar (Joscelin)", "result": "zafer", "note": "Haçlı garnizonu mağlup edildi."}], "legends": [], "sources": [{"title": "TDV İslâm Ansiklopedisi, AHLATŞAHLAR", "url": "https://islamansiklopedisi.org.tr/ahlat-sahlar"}]}]}, {"id": "artuklu", "name": "Artuklular", "short": "Artuklular", "aliases": ["Artuklu Beyliği", "Âl-i Artuk"], "region": "anadolu", "start": 1102, "end": 1409, "startNote": "Artuk Bey'in oğulları Sökmen ve İlgazi tarafından Hasankeyf ve Mardin merkezli kuruldu.", "endNote": "1409 yılında Karakoyunlu Kara Yusuf'un Mardin'i almasıyla sona erdi.", "capital": "Hısnkeyfâ (Hasankeyf), Mardin ve Harput", "religion": "İslamiyet (Sünnî-Hanefî)", "confidence": "kayit", "confidenceNote": "İbnü'l-Ezrak (Târîhu Meyyâfârikīn), İbn Şeddâd, İbnü'l-Esîr kronikleri ve El-Cezerî'nin mekanik kitabı ile sabittir.", "summary": "Oğuzların Döğer boyundan Eksük oğlu Artuk Bey'in evlatları tarafından Güneydoğu Anadolu'da (Mardin, Hasankeyf, Harput, Meyyâfârikīn) kurulan köklü Türk devleti. Necmeddin İlgazi devrinde 1119 Tell-Akrîbâ (Kanlı Meydan) Zaferi ile Antakya Haçlı ordusunu yok ettiler. Dünyanın ilk robot ve sibernetik bilgini İsmâil el-Cezerî, Artuklu sarayında 25 yıl başmühendislik yaparak su saatleri ve otomatik makineler icat etti. Malabadi Köprüsü ve Mardin taş medreseleri bu beyliğin şaheseridir.", "legacy": "Sibernetik ve robotik ilminin kurucusu El-Cezerî'yi yetiştirdi; dünyanın en geniş açıklıklı taş kemerli köprüsü olan Malabadi Köprüsü'nü ve Mardin medreselerini miras bıraktı.", "essay": ["Artuklular, Selçuklu ordusunda Kudüs valiliği yapmış olan Döğer boyu beyi Artuk Bey'in vefatından sonra oğulları Sökmen ve İlgazi tarafından kuruldu. Sökmen 1102'de Hasankeyf (Hısnkeyfâ), İlgazi ise 1107 civarında Mardin merkezli kollarını kurdu; daha sonra Harput kolu teşekkül etti.", "İlgazi Bey, Haçlı Seferleri'ne karşı İslam dünyasının en büyük kahramanlarından biri oldu. 28 Haziran 1119'da Tell-Akrîbâ (Ager Sanguinis / Kanlı Meydan) Muharebesi'nde Antakya Prinkepsi Roger komutasındaki Haçlı ordusunu neredeyse tek bir kişi sağ kalmayacak şekilde imha etti.", "Hasankeyf hükümdarı Nâsırüddin Mahmud devrinde (1200-1222), Cizreli büyük Türk-İslam bilgini İsmâil el-Cezerî sarayda başmühendis olarak çalıştı. 1206 yılında tamamladığı 'Kitâb fî Ma'rifeti'l-Hiyeli'l-Hendesiye' adlı eserinde 50'den fazla robot, mekanik su saati, krank mili ve şifreli kilitlerin çizim ve çalışma prensiplerini insanlığa kazandırdı. Beylik Moğol, Eyyûbî ve Akkoyunlu baskılarına rağmen 1409'a kadar Mardin kalesinde 3 asırdan fazla varlığını korudu."], "sources": [{"title": "TDV İslâm Ansiklopedisi, ARTUKLULAR", "url": "https://islamansiklopedisi.org.tr/artuklular"}, {"title": "TDV İslâm Ansiklopedisi, CEZERÎ, İsmâil b. Rezzâz", "url": "https://islamansiklopedisi.org.tr/cezeri-ismail-b-rezzaz"}, {"title": "TDV İslâm Ansiklopedisi, İLGAZİ, Necmeddin", "url": "https://islamansiklopedisi.org.tr/ilgazi-necmeddin"}], "rulers": [{"id": "artuklu-ilgazi", "name": "Necmeddin İlgazi", "aliases": ["İlgazi b. Artuk", "Necmeddin İlgazi"], "title": "Emir / Kutbüddin", "birth": 1062, "birthNote": "Yaklaşık 1062 doğumlu", "death": 1122, "deathNote": "Meyyâfârikīn (Silvan) yolunda hastalanarak vefat etti", "reign": [1107, 1122], "reignNote": "15 yıllık Haçlı gazalarıyla dolu şanlı hükümdarlık.", "summary": "Mardin Artuklularının kurucusu ve Haçlıların korkulu rüyası. Bağdat şahneliği yaptı. 1119 Kanlı Meydan Muharebesi'nde Antakya Haçlı Prensliği ordusunu bütünüyle imha ederek Haçlıların Doğu Akdeniz'deki yayılmasını durdurdu; Halep'i korudu.", "traits": ["Yenilmez gazâ önderi", "Meydan muharebesi ustası", "Cesur"], "contribution": "Güneydoğu Anadolu ve Suriye'yi Haçlı istilasından kurtardı; Mardin'i Türk başkenti yaptı.", "harm": "Sert tabiatı ve zaman zaman içki nöbetleri kriz anlarında karar almasını zorlaştırdı.", "wives": [{"name": "Firk Hatun", "note": "Dımaşk Atabeyi Tuğtekin'in kızı", "certainty": "kesin"}], "children": [{"name": "Hüsameddin Timurtaş", "mother": "", "note": "Mardin beyi, Malabadi Köprüsü'nü tamamlayan melik", "certainty": "kesin"}, {"name": "Süleyman", "mother": "", "note": "Halep valisi", "certainty": "kesin"}], "wars": [{"name": "Ager Sanguinis (Kanlı Meydan Muharebesi)", "when": "1119", "foe": "Antakya Haçlı Prensliği (Prinkeps Roger)", "result": "zafer", "note": "Haçlı ordusu imha edildi, Roger savaş meydanında öldürüldü, yüzlerce şövalye esir alındı."}], "legends": ["Haçlı kronikçileri Walter the Chancellor ve William of Tyre onun adını dehşet ve hayranlıkla anar."], "sources": [{"title": "TDV İslâm Ansiklopedisi, İLGAZİ, Necmeddin", "url": "https://islamansiklopedisi.org.tr/ilgazi-necmeddin"}]}, {"id": "artuklu-sokmen", "name": "Muînüddin Sökmen", "aliases": ["Sökmen b. Artuk"], "title": "Emir / Muînüddin", "birth": null, "birthNote": "Kayıtlarda yok", "death": 1104, "deathNote": "Haçlı seferi yolunda Karyeteyn'de vefat etti", "reign": [1102, 1104], "reignNote": "Hasankeyf kolunun kurucusu.", "summary": "Artuk Bey'in oğlu. Kudüs valiliği yaptıktan sonra Hasankeyf'te beyliğini kurdu. 1104 Harran Muharebesi'nde Çökürmüş ile birleşerek Urfa Haçlı Kontu II. Baudouin'i esir aldı ve Haçlıların Fırat doğusuna geçişini ebediyen kesti.", "traits": ["Gazi", "Stratejist"], "contribution": "Harran Zaferi ile Haçlıların Musul ve Bağdat'a yürümesini önledi.", "harm": "Erken ölümü beyliğin toparlanma sürecini yavaşlattı.", "wives": [], "children": [{"name": "İbrâhim", "mother": "", "note": "Hasankeyf meliki", "certainty": "kesin"}, {"name": "Dâvud", "mother": "", "note": "Hasankeyf meliki", "certainty": "kesin"}], "wars": [{"name": "Harran (Belih Çayı) Muharebesi", "when": "1104", "foe": "Haçlı Kontlukları (Urfa Kontu Baudouin ve Antakya Kontu Bohemund)", "result": "zafer", "note": "Haçlı ordusu dağıtıldı, Baudouin esir edildi, Urfa Haçlı Kontluğu ölümcül darbe aldı."}], "legends": [], "sources": [{"title": "TDV İslâm Ansiklopedisi, ARTUKLULAR", "url": "https://islamansiklopedisi.org.tr/artuklular"}]}]}, {"id": "zengi", "name": "Zengîler", "short": "Zengîler (Musul ve Halep Atabeyliği)", "aliases": ["Musul Atabegleri", "Halep Atabegleri", "Âl-i Zengî"], "region": "anadolu", "start": 1127, "end": 1250, "startNote": "İmâdeddin Zengî'nin 1127'de Musul ve Halep valisi ve Selçuklu atabegi olmasıyla kuruldu.", "endNote": "1250 civarında Eyyûbîlerin Halep kolunu, ardından Hülagû'nun Musul'u zaptetmesiyle sona erdi.", "capital": "Musul ve Halep", "religion": "İslamiyet (Sünnî-Hanefî)", "confidence": "kayit", "confidenceNote": "İbnü'l-Esîr (et-Târîhu'l-Bâhir fi'd-Devleti'l-Atâbekiyye), İbnü'l-Adîm (Zübdetü'l-Haleb) ile eksiksiz sabittir.", "summary": "Selçuklu emiri Aksungur el-Hâcib'in oğlu İmâdeddin Zengî tarafından kurulan, Haçlı Seferleri'ne karşı İslam dünyasının ilk büyük karşı taarruzunu başlatan şanlı Türk devleti. 1144'te Urfa Haçlı Kontluğu'nu fethederek tarihte ilk kez bir Haçlı devletini ortadan kaldırdılar ve II. Haçlı Seferi'ni tetiklediler. Oğlu Nûreddin Mahmud Zengî, Şam ve Mısır'ı birleştirerek Selâhaddîn-i Eyyûbî'yi yetiştirdi; Kudüs'ün fethinin manevi mimarı oldu.", "legacy": "Haçlıların yenilmezlik efsanesini yıktı; Selâhaddîn-i Eyyûbî'yi yetiştirip Kudüs fethinin askeri ve manevi zeminini hazırladı. Nûreddin Zengî'nin yaptırdığı Mescid-i Aksâ ahşap kündekârî minberi İslam sanatının şaheseridir.", "essay": ["Zengîler, Sultan Melikşah'ın has emiri Halep Valisi Aksungur'un oğlu İmâdeddin Zengî tarafından 1127'de Musul merkezli kuruldu. İmâdeddin, Suriye ve el-Cezire'deki dağınık Türk emirlerini tek çatı altında topladı.", "24 Aralık 1144'te Urfa'yı fethederek Haçlıların kurduğu ilk devlet olan Urfa Kontluğu'nu tarihten sildi. Bu tarihi zafer Avrupa'yı dehşete düşürdü ve Alman İmparatoru ile Fransız Kralı'nın katıldığı II. Haçlı Seferi'ne yol açtı; Zengîler bu seferi Anadolu ve Şam önlerinde püskürttü.", "İmâdeddin'in şehadetinden sonra Halep kolunun başına geçen oğlu el-Melikü'l-Âdil Nûreddin Mahmud Zengî (1146-1174), adaleti ve dindarlığıyla 'Hulefâ-yi Râşidîn' dönemini andıran bir sultan oldu. Şam'ı fethetti, Haçlı ordularını Harim ve İnab'da hezimete uğrattı. Kumandanı Şîrkûh ve yeğeni Selâhaddîn-i Eyyûbî'yi Mısır'a göndererek Fâtımî hilafetine son verdi. Kudüs'ün fethi için Mescid-i Aksâ'ya konulmak üzere muazzam bir ahşap minber yaptırdı. 1174'teki vefatıyla yerini Selâhaddîn-i Eyyûbî aldı."], "sources": [{"title": "TDV İslâm Ansiklopedisi, ZENGÎLER", "url": "https://islamansiklopedisi.org.tr/zengiler"}, {"title": "TDV İslâm Ansiklopedisi, NÛREDDİN ZENGÎ", "url": "https://islamansiklopedisi.org.tr/nureddin-zengi"}], "rulers": [{"id": "zengi-imadeddin", "name": "İmâdeddin Zengî", "aliases": ["İmâdüddin Zengî b. Aksungur"], "title": "Atabeg / Melik", "birth": 1085, "birthNote": "1085 doğumlu", "death": 1146, "deathNote": "Câber Kalesi kuşatmasında uykudayken kölesi Yârektaş tarafından şehit edildi", "reign": [1127, 1146], "reignNote": "19 yıllık cihat ve fütuhat saltanatı.", "summary": "Zengîler Devleti'nin kurucusu. Haçlılara karşı İslam cihadını örgütleyen ilk büyük lider. 1144'te Urfa Haçlı Kontluğu'nu yıkarak İslam alemine en büyük zaferlerinden birini kazandırdı.", "traits": ["Büyük mücahid", "Korkusuz komutan", "Demir disiplinli"], "contribution": "Urfa'yı fethedip Haçlı Kontluğu'nu yıktı; Haçlı yayılmasına karşı İslam mukavemet cephesini kurdu.", "harm": "Aşırı sert disiplini kölesi tarafından uğradığı suikasta zemin hazırladı.", "wives": [{"name": "Zümrüd Hatun", "note": "Dımaşk hakimi Börü'nün annesi", "certainty": "kesin"}], "children": [{"name": "Nûreddin Mahmud", "mother": "", "note": "Halep meliki, büyük adalet timsali", "certainty": "kesin"}, {"name": "I. Seyfeddin Gazi", "mother": "", "note": "Musul meliki", "certainty": "kesin"}, {"name": "Kutbeddin Mevdud", "mother": "", "note": "Musul meliki", "certainty": "kesin"}], "wars": [{"name": "Urfa'nın Fethi", "when": "1144", "foe": "Urfa Haçlı Kontluğu (II. Joscelin)", "result": "zafer", "note": "Urfa Kalesi fethedildi, Urfa Haçlı Kontluğu ortadan kaldırıldı."}, {"name": "Bârin Muharebesi", "when": "1137", "foe": "Kudüs Haçlı Krallığı (Kral Fulk)", "result": "zafer", "note": "Haçlı ordusu dağıtıldı, Kral Fulk Bârin kalesinde kuşatılıp teslim alındı."}], "legends": ["Tarihçi İbnü'l-Esîr babasının ve kendisinin atabeglik sarayında yetiştiği için onun adalet ve heybetini destansı bir dille anlatır."], "sources": [{"title": "TDV İslâm Ansiklopedisi, ZENGÎ, İmâdüddin", "url": "https://islamansiklopedisi.org.tr/zengi-imaduddin"}]}, {"id": "zengi-nureddin-mahmud", "name": "Nûreddin Mahmud Zengî", "aliases": ["Nûreddin Zengî", "el-Melikü'l-Âdil"], "title": "Melik / Sultan / el-Âdil", "birth": 1118, "birthNote": "1118'de Halep'te doğdu", "death": 1174, "deathNote": "Dımaşk'ta boğaz iltihabından vefat etti, Dârü'l-Hadîs medresesindeki türbesindedir", "reign": [1146, 1174], "reignNote": "28 yıllık adalet, cihat ve medeniyet devri.", "summary": "İmâdeddin Zengî'nin oğlu. İslam tarihinin Hulefâ-yi Râşidîn ve Ömer b. Abdülazîz'den sonraki en adil ve takva sahibi hükümdarı sayılır. Şam'ı fethetti, II. Haçlı Seferi'ni püskürttü, Mısır'ı kontrolüne alıp Fâtımîleri bitirdi. Selâhaddîn-i Eyyûbî'nin hamisi ve Kudüs fethinin manevi mimarıdır.", "traits": ["Adalet ve zühd timsali", "Büyük mücahid", "İlim ve hadis aşığı"], "contribution": "Suriye ve Mısır'ı birleştirerek Kudüs'ün fethini hazırladı; tarihteki ilk Dârü'l-Hadîs ihtisas medresesini ve adalet saraylarını (Dârü'l-Adl) kurdu.", "harm": "Kayıtlarda belirgin bir zararı geçmez.", "wives": [{"name": "İsmetüddin Hatun", "note": "Dımaşk Atabeyi Üner'in kızı; Nûreddin'den sonra Selâhaddîn ile evlendi", "certainty": "kesin"}], "children": [{"name": "el-Melikü's-Sâlih İsmâil", "mother": "İsmetüddin Hatun", "note": "Çocuk yaşta halef oldu", "certainty": "kesin"}], "wars": [{"name": "İnâb Muharebesi", "when": "1149", "foe": "Antakya Haçlı Prensliği (Raymond de Poitiers)", "result": "zafer", "note": "Haçlı ordusu imha edildi, Antakya Prensi Raymond öldürüldü."}, {"name": "Harim Muharebesi", "when": "1164", "foe": "Birleşik Haçlı ve Bizans ordusu", "result": "zafer", "note": "Antakya Prensi III. Bohemund ve Trablus Kontu Raymond esir alındı."}], "legends": ["Kudüs'ün fethine o kadar inanmıştı ki fetihten 20 yıl önce Halep'te kündekârî sanatıyla tek bir çivi çakılmadan muazzam bir ahşap minber yaptırmıştı. Selâhaddîn 1187'de Kudüs'ü alınca bu minberi Mescid-i Aksâ'ya yerleştirdi."], "sources": [{"title": "TDV İslâm Ansiklopedisi, NÛREDDİN ZENGÎ", "url": "https://islamansiklopedisi.org.tr/nureddin-zengi"}]}]}, {"id": "memluk", "name": "Memlük Devleti", "short": "Memlükler", "aliases": ["Devletü'l-Memâlîk", "Bahrî ve Burcî Memlükleri"], "region": "anadolu", "start": 1250, "end": 1517, "startNote": "1250'de Eyyûbî sultanı Turanşah'ın devrilmesi ve Şecerüddür'ün sultan ilan edilmesi başlangıç sayılır.", "endNote": "1517 Ridaniye Savaşı'nda Tomanbay yenildi ve Mısır Osmanlı toprağı oldu; Abbasi halifeliği İstanbul'a taşındı.", "capital": "Kahire", "religion": "Sünni İslam", "confidence": "kayit", "summary": "Kölemen askerlerin (memlük) kurduğu, Mısır ve Suriye'yi 267 yıl yöneten devlettir. Moğolları Aynicâlût'ta durdurdu, Haçlı kalıntılarını tasfiye etti. Bahrî dönemi Kıpçak Türk, Burcî dönemi Çerkes kökenli emirlerin yönetimindedir.", "legacy": "Kahire'yi İslam dünyasının kültür merkezi olarak korudu; Memlük mimarisi, vakıfları ve Abbasi hilafetinin Kahire'de sürdürülmesi hanedanın bıraktığı en kalıcı izdir. Ordu ve yönetim dili Türkçe, bürokrasi dili Arapça kaldı.", "essay": ["Memlük düzeni, Eyyûbîlerin satın alıp yetiştirdiği askerî kölelerin kendi hanedanını kurmasıyla doğdu. Sultanlar emirler arasından seçilir, sık sık devrilirdi; bu yüzden iki buçuk yüzyılda kırka yakın sultan değişti.", "Bahrî (deniz) kol adını Nil üzerindeki adalardaki kışlalarından alır ve çoğu Kıpçak Türküdür. 1260 Aynicâlût zaferi, 1291'de Akka'nın alınması, 1299 ve 1303'te İlhanlılara karşı kazanılan savaşlar bu döneme denk düşer. Burcî kol ise kule (burc) kışlalarından gelir ve Çerkes kökenlidir; 1382'de Berkuk ile yönetimi devraldı.", "Memlükler yönetimde Türkçeyi, dış ilişkilerde Arapçayı kullandı; ulema, vakıf ve ticaret düzeni Kahire'yi Akdeniz'in en büyük şehirlerinden biri yaptı. Osmanlı ile rekabet 15. yüzyılda Dulkadir ve Karaman beylikleri üzerinden kızıştı.", "1516 Mercidabık ve 1517 Ridaniye'de ateşli silah üstünlüğü Osmanlı'da kaldı; Memlük ordusunun atlı düzeni çözüldü. Mısır ilhak edildi, hilafet İstanbul'a geçti."], "sources": [{"title": "TDV İslâm Ansiklopedisi, MEMLÜKLER", "url": "https://islamansiklopedisi.org.tr/memlukler"}], "rulers": [{"id": "memluk-aybek", "name": "İzzeddin Aybek", "title": "sultan", "birth": null, "birthNote": "kayıtlarda yok", "death": 1257, "deathNote": "Suikast sonucu öldü", "reign": [1250, 1257], "summary": "Memlük Devleti'nin ilk sultanı sayılır. Şecerüddür ile evlenerek yönetimi devraldı, Eyyûbî kalıntıları ve Haçlılarla uğraştı.", "traits": ["memlük kökenli emir"], "contribution": "Kölemen yönetimini hanedan hâline getirdi.", "harm": "Kısa saltanatı ve suikastla ölümü, emirler arası çekişmenin ilk örneğidir.", "wives": [{"name": "Şecerüddür", "note": "Eyyûbî sultanı Salih Eyyûb'un dul eşi; önce kendisi sultan ilan edilmişti", "certainty": "kesin"}], "children": [{"name": "Nureddin Ali", "mother": "", "note": "Halef olarak ilan edildi", "certainty": "olasi"}], "wars": [], "legends": [], "sources": [{"title": "TDV İslâm Ansiklopedisi, MEMLÜKLER", "url": "https://islamansiklopedisi.org.tr/memlukler"}]}, {"id": "memluk-kutuz", "name": "Seyfeddin Kutuz", "title": "sultan", "birth": null, "birthNote": "kayıtlarda yok", "death": 1260, "deathNote": "Aynicâlût dönüşü öldürüldü", "reign": [1259, 1260], "summary": "Moğol ilerleyişi karşısında Baybars'la birlikte orduyu Filistin'e sürdü ve Aynicâlût'ta Moğolları yendi.", "traits": ["hızlı karar alan kumandan"], "contribution": "Moğol ilerleyişini durdurdu.", "harm": "Zaferin ardından emirlerle çatıştı ve öldürüldü.", "wives": [], "children": [], "wars": [{"name": "Aynicâlût Savaşı", "when": "3 Eylül 1260", "foe": "İlhanlılar (Ketboğa Noyan)", "result": "zafer", "note": "Moğol yayılmasının batı sınırı çizildi."}], "legends": [], "sources": [{"title": "TDV İslâm Ansiklopedisi, MEMLÜKLER", "url": "https://islamansiklopedisi.org.tr/memlukler"}]}, {"id": "memluk-baybars", "name": "I. Baybars", "aliases": ["Baybars el-Bundukdârî"], "title": "sultan", "birth": 1223, "birthNote": "Yaklaşık; Kıpçak kökenli", "death": 1277, "deathNote": "Şam'da öldü", "reign": [1260, 1277], "summary": "Memlük Devleti'nin gerçek kurucusu sayılır. İlhanlıları Elbistan'da yendi, Haçlı kalelerini tasfiye etmeye başladı, Abbasi gölgesini Kahire'de yeniden kurdurdu.", "traits": ["askerî örgütlenme", "casusluk ve posta düzeni", "sert disiplin"], "contribution": "Merkezî ordu, ikta ve haberleşme düzenini kurdu; Kahire'yi bölgenin en güçlü başkenti yaptı.", "harm": "Sürekli seferler hazineyi yordu; emirler üzerindeki baskısı sonraki krizlerin zeminini hazırladı.", "wives": [], "children": [{"name": "Berke Han", "mother": "", "note": "Halef; oğlu olarak anılır", "certainty": "olasi"}, {"name": "Selamiş", "mother": "", "note": "Kısa süre sultan", "certainty": "kesin"}], "wars": [{"name": "Elbistan Savaşı", "when": "1277", "foe": "İlhanlılar", "result": "zafer", "note": "Anadolu'ya girildi, İlhanlı ordusu bozuldu."}, {"name": "Antakya'nın fethi", "when": "1268", "foe": "Haçlılar", "result": "zafer", "note": "Antakya Prinkepsliği yıkıldı."}, {"name": "Hums Savaşı", "when": "1260", "foe": "Haçlı-İlhanlı ittifakına karşı Memlük savunması", "result": "zafer", "note": "Suriye'de Moğol ilerleyişi kesin olarak durdu."}], "legends": ["Baybars'ın Altın Orda hanı Berke ile ittifak kurup İlhanlılara karşı ortak cephe oluşturması dönemin kaynaklarında geçer; ayrıntılar tartışmalıdır."], "sources": [{"title": "TDV İslâm Ansiklopedisi, MEMLÜKLER", "url": "https://islamansiklopedisi.org.tr/memlukler"}]}, {"id": "memluk-kalavun", "name": "Kalavun", "aliases": ["Mansûr Kalavun"], "title": "sultan", "birth": null, "birthNote": "kayıtlarda yok", "death": 1290, "reign": [1279, 1290], "summary": "Baybars'ın komutanı ve halefi. 1281 Hums zaferiyle İlhanlıları Suriye'den attı, 1289'da Trablus'u aldı.", "traits": ["diplomasi ve ittifak", "imar"], "contribution": "Kahire'de büyük hastane ve külliyeler; Memlük hukuk ve vakıf düzeni.", "harm": "Sefer maliyetleri ve emir çekişmeleri sürdü.", "wives": [], "children": [{"name": "Halil", "mother": "", "note": "Halef", "certainty": "kesin"}, {"name": "Nasır Muhammed", "mother": "", "note": "Halef", "certainty": "kesin"}], "wars": [{"name": "Hums Savaşı", "when": "1281", "foe": "İlhanlılar", "result": "zafer", "note": "Suriye'de Moğol hâkimiyeti kesin olarak kırıldı."}, {"name": "Trablus'un fethi", "when": "1289", "foe": "Haçlılar", "result": "zafer", "note": ""}], "legends": [], "sources": [{"title": "TDV İslâm Ansiklopedisi, MEMLÜKLER", "url": "https://islamansiklopedisi.org.tr/memlukler"}]}, {"id": "memluk-halil", "name": "Eşref Halil", "title": "sultan", "birth": null, "birthNote": "kayıtlarda yok", "death": 1293, "deathNote": "Suikastla öldürüldü", "reign": [1290, 1293], "summary": "1291'de Akka'yı alarak Haçlı varlığını Kutsal Topraklarda sona erdirdi.", "traits": ["sert ve hızlı sefer tarzı"], "contribution": "Haçlı kalelerinin tasfiyesini tamamladı.", "harm": "Emirlerle ilişkisi bozuldu, suikastla devrildi.", "wives": [], "children": [], "wars": [{"name": "Akka'nın fethi", "when": "1291", "foe": "Haçlılar", "result": "zafer", "note": "Kudüs Krallığı'nın son büyük kalesi düştü."}], "legends": [], "sources": [{"title": "TDV İslâm Ansiklopedisi, MEMLÜKLER", "url": "https://islamansiklopedisi.org.tr/memlukler"}]}, {"id": "memluk-nasir-muhammed", "name": "Nasır Muhammed b. Kalavun", "title": "sultan", "birth": 1285, "birthNote": "Yaklaşık", "death": 1341, "reign": [1310, 1341], "reignNote": "Üç dönem saltanat: 1293-1294, 1299-1309, 1310-1341. Uzun ve olgun dönemi 1310-1341 arasıdır.", "summary": "Memlük tarihinin en uzun ve en istikrarlı saltanatını kurdu. İlhanlı savaşları sınırda kaldı; ticaret, imar ve vakıf düzeni büyüdü.", "traits": ["uzun saltanat", "imar ve vakıf patronu", "emirlerle denge siyaseti"], "contribution": "Kahire'de yoğun imar, su kanalları ve camiler; Memlük ekonomisinin altın çağı.", "harm": "Veba salgını (1347 sonrası) ve ağır vergiler dönemin sonunda toplumu sarstı.", "wives": [], "children": [{"name": "Ebu Bekir", "mother": "", "note": "Halef", "certainty": "olasi"}, {"name": "Şaban I", "mother": "", "note": "", "certainty": "olasi"}], "wars": [{"name": "Şakhab Savaşı", "when": "1303", "foe": "İlhanlılar (Gazan)", "result": "zafer", "note": "Suriye'ye İlhanlı yerleşmesi kesin olarak engellendi."}], "legends": [], "sources": [{"title": "TDV İslâm Ansiklopedisi, MEMLÜKLER", "url": "https://islamansiklopedisi.org.tr/memlukler"}]}, {"id": "memluk-berkuk", "name": "Berkuk", "aliases": ["Zâhir Berkuk"], "title": "sultan", "birth": 1339, "birthNote": "Yaklaşık; Çerkes kökenli", "death": 1399, "reign": [1382, 1399], "reignNote": "1382-1389 ve 1390-1399 arasında iki dönem.", "summary": "Burcî (Çerkes) kolunu iktidara taşıdı. Timur tehdidi karşısında Suriye'yi savunmaya çalıştı, 1394'te Halep yakınlarında yenildi.", "traits": ["Çerkes memlüklerin örgütlenmesi", "mali baskı"], "contribution": "Yönetimi Çerkes koluna devretti; askerî düzeni yenilemeye çalıştı.", "harm": "Emir çekişmesi arttı; Timur karşısında Suriye kaybedildi.", "wives": [], "children": [{"name": "Farac", "mother": "", "note": "Halef", "certainty": "kesin"}], "wars": [{"name": "Suriye seferi", "when": "1394", "foe": "Timur", "result": "yenilgi", "note": "Halep yöresinde Timurlu ordusuna karşı başarısızlık."}], "legends": [], "sources": [{"title": "TDV İslâm Ansiklopedisi, MEMLÜKLER", "url": "https://islamansiklopedisi.org.tr/memlukler"}]}, {"id": "memluk-barsbay", "name": "Barsbay", "title": "sultan", "birth": null, "birthNote": "kayıtlarda yok", "death": 1438, "reign": [1422, 1438], "summary": "Kıbrıs'a sefer düzenledi, Kıbrıs kralını vergiye bağladı. Hindistan ve Karadeniz ticaretinde Memlük tekelini korumaya çalıştı.", "traits": ["deniz seferleri", "ticaret siyaseti"], "contribution": "Kıbrıs seferiyle Akdeniz'de Memlük üstünlüğünü yeniden kurdu.", "harm": "Baharat ticaretine konan ağır vergiler Avrupa'da Memlük aleyhtarı ittifakları besledi.", "wives": [], "children": [], "wars": [{"name": "Kıbrıs seferi", "when": "1426", "foe": "Kıbrıs Krallığı", "result": "zafer", "note": "Kral esir alındı ve vergiye bağlandı."}], "legends": [], "sources": [{"title": "TDV İslâm Ansiklopedisi, MEMLÜKLER", "url": "https://islamansiklopedisi.org.tr/memlukler"}]}, {"id": "memluk-kayitbay", "name": "Kayıtbay", "title": "sultan", "birth": 1416, "birthNote": "Yaklaşık; Çerkes kökenli", "death": 1496, "reign": [1468, 1496], "summary": "Uzun saltanatında Osmanlı ve Dulkadir beyleriyle dengeli politika izledi, Memlük mimarisine damga vurdu.", "traits": ["imar", "denge diplomasisi"], "contribution": "Kahire ve Mekke'de büyük yapılar; hac yollarının güvenliği.", "harm": "Osmanlı ile rekabette askerî üstünlük kaybedildi; ateşli silahlara geçiş gecikti.", "wives": [], "children": [], "wars": [{"name": "Osmanlı-Dulkadir çekişmesi", "when": "1485-1491", "foe": "Osmanlı Devleti", "result": "sonucsuz", "note": "Karşılıklı seferler sınırda kaldı."}], "legends": [], "sources": [{"title": "TDV İslâm Ansiklopedisi, MEMLÜKLER", "url": "https://islamansiklopedisi.org.tr/memlukler"}]}, {"id": "memluk-kansu-gavri", "name": "Kansu Gavri", "title": "sultan", "birth": null, "birthNote": "kayıtlarda yok", "death": 1516, "deathNote": "Mercidabık'ta öldü", "reign": [1501, 1516], "summary": "Safevî tehdidi ve Osmanlı yükselişi arasında kalan son güçlü Memlük sultanı. 1516 Mercidabık'ta Osmanlı ordusuna yenildi ve savaşta öldü.", "traits": ["şair ve edebiyat hamisi", "ateşli silaha geç kalan ordu"], "contribution": "Memlük kültür hayatını son kez canlı tuttu.", "harm": "Mercidabık yenilgisi Mısır'ın kapısını açtı.", "wives": [], "children": [], "wars": [{"name": "Mercidabık Savaşı", "when": "24 Ağustos 1516", "foe": "Osmanlı Devleti (Yavuz Selim)", "result": "yenilgi", "note": "Suriye Osmanlı'ya geçti."}], "legends": [], "sources": [{"title": "TDV İslâm Ansiklopedisi, MEMLÜKLER", "url": "https://islamansiklopedisi.org.tr/memlukler"}]}, {"id": "memluk-tomanbay", "name": "Tomanbay", "title": "sultan", "birth": null, "birthNote": "kayıtlarda yok", "death": 1517, "deathNote": "Kahire'de asıldı", "reign": [1516, 1517], "summary": "Son Memlük sultanı. Ridaniye'de yenildi, şehir savaşı verdi, yakalanıp idam edildi.", "traits": ["direnişe bağlılık"], "contribution": "Memlük hanedanının sonunu temsil eder.", "harm": "Yenilgi Mısır'ın bağımsızlığını bitirdi.", "wives": [], "children": [], "wars": [{"name": "Ridaniye Savaşı", "when": "22 Ocak 1517", "foe": "Osmanlı Devleti", "result": "yenilgi", "note": "Mısır ilhak edildi, hilafet İstanbul'a taşındı."}], "legends": [], "sources": [{"title": "TDV İslâm Ansiklopedisi, MEMLÜKLER", "url": "https://islamansiklopedisi.org.tr/memlukler"}]}]}, {"id": "karamanoglu", "name": "Karamanoğulları Beyliği", "short": "Karamanoğulları", "aliases": ["Karaman Beyliği", "Karamanoğulları Devleti"], "region": "anadolu", "start": 1256, "end": 1487, "startNote": "Nûre Sûfî ve oğlu Kerîmüddin Karaman Bey'in Ermenek ve Toroslar'da beylik kurmasıyla başladı.", "endNote": "1487 yılında II. Bayezid devrinde son Karaman kalıntıları temizlenerek Osmanlı'ya bağlandı.", "capital": "Ermenek, Lârende (Karaman) ve Konya", "religion": "İslamiyet (Sünnî-Hanefî)", "confidence": "kayit", "confidenceNote": "Şikârî'nin Karamannâme'si, İbn Bîbî, Âşıkpaşazâde ve Neşrî kronikleriyle sabittir.", "summary": "Oğuzların Avşar boyuna mensup Nûre Sûfî ve Kerîmüddin Karaman Bey tarafından Toroslar'da kurulan, Anadolu Selçuklu Devleti'nin gerçek varisi olma iddiasıyla Osmanlı Devleti'ne karşı en uzun ve çetin direnişi gösteren güçlü beylik. 13 Mayıs 1277'de Karamanoğlu Mehmed Bey, Selçuklu başkenti Konya'yı fethederek ünlü 'Bugünden sonra divanda, dergâhta, bargâhta, mecliste ve meydanda Türkçeden başka dil kullanılmaya' fermanını yayınladı. Fatih Sultan Mehmed ve II. Bayezid dönemlerinde Osmanlı'ya katıldı.", "legacy": "Türkçenin resmi devlet dili olarak ilan edilmesinin bayraktarı oldu. Her yıl 13 Mayıs'ta Türk Dil Bayramı olarak kutlanan tarihi mirasın mimarıdır.", "essay": ["Karamanoğulları, Moğol istilası önünden Anadolu'ya göç eden Avşar Türkmenlerinin başında bulunan Nûre Sûfî ve oğlu Kerîmüddin Karaman Bey önderliğinde Ermenek çevresinde kuruldu. Selçuklu Devleti'nin Moğol vesayetine girmesine karşı en sert Türkmen direnişini temsil ettiler.", "1277 yılında Kerîmüddin Karaman'ın oğlu Mehmed Bey, Selçuklu şehzadesi Cimri (Siyavuş) ile birlikte Konya'ya girdi ve Selçuklu vezirlerini saf dışı bıraktı. 13 Mayıs 1277'de Türkçe fermanını yayınlayarak Farsçanın devlet ve bürokrasi dili hakimiyetine son verdi. Ancak Selçuklu-Moğol karşı ordusuyla yapılan savaşta şehit düştü.", "14. ve 15. yüzyıllarda Konya, Karaman, Niğde, Aksaray ve Antalya'ya hakim olan beylik, Alâeddin Ali Bey ve II. İbrâhim Bey devirlerinde Osmanlı Devleti ile amansız bir Anadolu hakimiyeti mücadelesine girdi. Zaman zaman Memlükler, Akkoyunlular ve Macarlar ile Osmanlı aleyhine ittifaklar kurdular. Fatih Sultan Mehmed'in 1468 Konya ve Karaman seferleri ve ardından Gedik Ahmed Paşa'nın harekatıyla 1487'de tamamen Osmanlı topraklarına katıldı."], "sources": [{"title": "TDV İslâm Ansiklopedisi, KARAMANOĞULLARI", "url": "https://islamansiklopedisi.org.tr/karamanogullari"}, {"title": "TDV İslâm Ansiklopedisi, MEHMED BEY, Karamanoğlu", "url": "https://islamansiklopedisi.org.tr/mehmed-bey-karamanoglu"}], "rulers": [{"id": "karamanoglu-mehmed-bey", "name": "Karamanoğlu Mehmed Bey", "aliases": ["Şemseddin Mehmed Bey"], "title": "Bey / Vezir", "birth": null, "birthNote": "Kayıtlarda yok", "death": 1277, "deathNote": "Moğol-Selçuklu müfrezesiyle çarpışırken okla şehit edildi", "reign": [1261, 1277], "reignNote": "16 yıl beylik yaptı.", "summary": "Kerîmüddin Karaman Bey'in oğlu. 1277'de Konya'yı fethedip vezir oldu ve Türkçeyi resmi devlet dili ilan eden tarihi fermanı yayınladı. Moğollara karşı Göksu boylarında şehit düştü.", "traits": ["Türkçe aşığı", "Milli şuur önderi", "Gözü pek gazi"], "contribution": "Türk dilini devlet ve edebiyat dili mertebesine yükseltti; Moğol tahakkümüne karşı Türkmen direnişinin bayrağı oldu.", "harm": "Selçuklu şehzadesi Siyavuş (Cimri) macerasına girişerek siyasi meşruiyet krizine yol açtı.", "wives": [], "children": [], "wars": [{"name": "Konya'nın Fethi", "when": "1277", "foe": "Moğol kuklası Selçuklu naibleri", "result": "zafer", "note": "Konya fethedildi, Türkçe fermanı ilan edildi."}, {"name": "Göksu Muharebesi", "when": "1277", "foe": "Moğol ve Selçuklu ortak ordusu", "result": "yenilgi", "note": "Pusuda iki kardeşiyle birlikte şehit düştü."}], "legends": ["'Bugünden sonra divanda, dergâhta, bargâhta, mecliste ve meydanda Türkçeden başka dil kullanılmaya' fermanı Karaman meydanında tunç yazıtlara kazınmıştır."], "sources": [{"title": "TDV İslâm Ansiklopedisi, MEHMED BEY, Karamanoğlu", "url": "https://islamansiklopedisi.org.tr/mehmed-bey-karamanoglu"}]}, {"id": "karamanoglu-ibrahim-2", "name": "Tâceddin II. İbrâhim Bey", "aliases": ["İbrâhim Bey II"], "title": "Bey", "birth": null, "birthNote": "Kayıtlarda yok", "death": 1464, "deathNote": "Gevele kalesinde kederinden vefat etti", "reign": [1424, 1464], "reignNote": "40 yıllık uzun hükümdarlık.", "summary": "Mehmed Bey'in oğlu. Osmanlı Sultanı II. Murad'ın kız kardeşi İsfendiyar Sultan (İlaldı Hatun) ile evlendi. Osmanlıların Rumeli'de Haçlılarla savaştığı anlarda defalarca Anadolu'da Osmanlı şehirlerine saldırdı; Varna öncesi anlaşmak zorunda kaldı. Karaman'daki İbrâhim Bey İmareti ve Külliyesi'ni inşa ettirdi.", "traits": ["İnatçı siyasetçi", "İmar hamisi", "Fırsatçı"], "contribution": "Karaman ve Konya'da çok sayıda medrese, köprü ve imaret yaptırdı.", "harm": "Osmanlı'nın Haçlılarla yaptığı ölüm kalım savaşlarında arkadan saldırması Türk-İslam dünyasında büyük tepki çekti.", "wives": [{"name": "İsfendiyar Sultan (İlaldı Hatun)", "note": "Osmanlı Sultanı II. Murad'ın kız kardeşi", "certainty": "kesin"}], "children": [{"name": "İshak Bey", "mother": "", "note": "Akkoyunlu destekli veliaht", "certainty": "kesin"}, {"name": "Pîr Ahmed Bey", "mother": "İsfendiyar Sultan", "note": "Osmanlı destekli oğlu", "certainty": "kesin"}, {"name": "Kasım Bey", "mother": "İsfendiyar Sultan", "note": "Son direnişçi bey", "certainty": "kesin"}], "wars": [{"name": "Akşehir ve Beyşehir Kuşatmaları", "when": "1443", "foe": "Osmanlı Devleti (II. Murad)", "result": "yenilgi", "note": "Osmanlı ordusu gelince Toros dağlarına kaçtı, 'Sevgendnâme' ile barış istedi."}], "legends": ["Yaptırdığı İbrâhim Bey İmareti'nin çinili mihrabı günümüzde İstanbul Çinili Köşk Müzesi'nin başyapıtıdır."], "sources": [{"title": "TDV İslâm Ansiklopedisi, KARAMANOĞULLARI", "url": "https://islamansiklopedisi.org.tr/karamanogullari"}]}]}, {"id": "mentese", "name": "Menteşeoğulları Beyliği", "short": "Menteşe", "aliases": ["Menteşe Beyliği", "Menteşe-ili", "Menteşeoğulları"], "region": "anadolu", "start": 1261, "end": 1424, "startNote": "Menteşe Bey'in Muğla ve sahil bölgesinde faaliyete başlaması 1261 civarıdır; Bizans kaynaklarında fütûhatı 1282'de açıkça anılır.", "endNote": "1391'de Yıldırım Bayezid toprakları aldı; 1402 sonrası Timur ihyası ile süren beylik 1424'te II. Murad tarafından kesin olarak ilhak edildi.", "capital": "Milas (Peçin kalesi ve Balat limanı önemli merkezlerdi)", "religion": "İslâm", "confidence": "kayit", "confidenceNote": "Beyliğin varlığı, sikkeleri, mimari kitabeleri, Venedik-Girit arşiv antlaşmaları ve P. Wittek'in monografisinde tescillidir.", "summary": "Güneybatı Anadolu'da (Muğla, Milas, Peçin, Balat, Fethiye) hüküm süren ilk denizci Türkmen beyliklerindendir. Ege ve Akdeniz sahillerinde kurduğu donanma ile Rodos'u işgal etmiş, Girit ve Venedik ile yoğun ticari ve askerî temaslarda bulunmuştur. Balat limanında Latin ticaret kolonileri barındırmış, zengin imar ve tercüme faaliyetleriyle öne çıkmıştır.", "legacy": "Muğla yöresinin Türkleşmesini sağlamış; Peçin Külliyesi, Milas Ahmed Gazi Camii ve Balat İlyas Bey Camii gibi özgün mimari başyapıtlar bırakmıştır.", "essay": ["Menteşeoğulları Beyliği, Kıyı Karia bölgesinde sahille Denizli dağları arasına yerleşen Türkmenlerin Menteşe Bey önderliğinde kurduğu denizci bir uç beyliğidir. 1282'de Tralles ve Nyssa'yı fetheden Menteşe Bey, Güney Ege sahil şeridine hâkim olmuştur.", "Mesud Bey döneminde 1300 yılında Rodos Adası'nın büyük kısmı zaptedilmiş, Hospitalier Şövalyeleri'nin 1308'de adayı almasına kadar Türk donanması burada üslenmiştir. Şücâüddin Orhan ve İbrâhim beyler devrinde Peçin başkent yapılmış, Balat limanı ise Venedik ticaretinin Ege'deki ana iskelesi haline gelmiştir.", "Gazi Ahmed Bey döneminde beylik Ege adalarından haraç alacak güce ulaşmıştır. 1391'de Yıldırım Bayezid'in seferiyle Osmanlıya bağlanan Menteşe toprakları, 1402 Ankara Savaşı'ndan sonra İlyas Bey idaresinde yeniden canlanmıştır. İlyas Bey'in ölümünün ardından oğulları Leys ve Ahmed'in tahta geçişi üzerine II. Murad 1424'te müdahale ederek beyliği kesin olarak Osmanlı idaresine katmıştır."], "sources": [{"title": "TDV İslâm Ansiklopedisi, MENTEŞEOĞULLARI", "url": "https://islamansiklopedisi.org.tr/menteseogullari"}, {"title": "Britannica, Menteşe Dynasty", "url": "https://www.britannica.com/topic/Mentese-dynasty"}], "rulers": [{"id": "mentese-mentese-bey", "name": "Menteşe Bey", "aliases": ["Menteşe Gazi"], "title": "bey", "birth": null, "birthNote": "kayıtlarda yok", "death": 1293, "deathNote": "1293'ten sonra vefat ettiği tahmin edilmektedir.", "reign": [1261, 1293], "reignNote": "Beyliğin kurucusu ve ilk ulu beyidir.", "summary": "Menteşe Beyliği'nin kurucusudur. Muğla, Milas, Aydın ve Sultanhisar yörelerini fethederek Ege kıyılarında ilk denizci Türkmen beyliklerinden birini teşkil etmiştir.", "traits": ["fatih", "kurucu", "gazi"], "contribution": "Karia bölgesini fethedip Türkleştirmiştir.", "harm": "", "wives": [], "children": [{"name": "Mesud Bey", "mother": "", "note": "Halefi, ulu bey", "certainty": "kesin"}, {"name": "Kirman Bey", "mother": "", "note": "Finike kolunu yönetti", "certainty": "kesin"}], "wars": [{"name": "Tralles ve Nyssa Fethi", "when": "1282", "foe": "Bizans İmparatorluğu", "result": "zafer", "note": "Bizans sınır müdafaası yarıldı ve Menderes vadisine inildi."}], "legends": [], "sources": [{"title": "TDV İslâm Ansiklopedisi, MENTEŞEOĞULLARI", "url": "https://islamansiklopedisi.org.tr/menteseogullari"}, {"title": "Britannica, Menteşe Dynasty", "url": "https://www.britannica.com/topic/Mentese-dynasty"}]}, {"id": "mentese-mesud-bey", "name": "Mesud Bey", "aliases": ["Mesud b. Menteşe"], "title": "bey", "birth": null, "birthNote": "kayıtlarda yok", "death": 1319, "deathNote": "1319'dan önce vefat ettiği kabul edilir.", "reign": [1293, 1319], "reignNote": "Menteşe Bey'in yerine ulu bey olmuştur.", "summary": "Menteşe donanmasını kurarak 1300'de Rodos Adası'nın büyük bölümünü fetheden denizci hükümdardır. Girit ve Cenevizlilerle ilk ticari münasebetleri başlatmıştır.", "traits": ["denizci", "fatih"], "contribution": "Rodos'a çıkarma yapmış, beyliği deniz aşırı güç haline getirmiştir.", "harm": "1308'den sonra Hospitalier Şövalyeleri Rodos'a yerleşerek Türk yayılmasını güçleştirmiştir.", "wives": [], "children": [{"name": "Şücâüddin Orhan Bey", "mother": "", "note": "Halefi, ulu bey", "certainty": "kesin"}], "wars": [{"name": "Rodos Seferi", "when": "1300", "foe": "Bizans ve Latin korsanları", "result": "zafer", "note": "Rodos adasının önemli kısmı fethedildi."}], "legends": [], "sources": [{"title": "TDV İslâm Ansiklopedisi, MENTEŞEOĞULLARI", "url": "https://islamansiklopedisi.org.tr/menteseogullari"}, {"title": "Britannica, Menteşe Dynasty", "url": "https://www.britannica.com/topic/Mentese-dynasty"}]}, {"id": "mentese-orhan-bey", "name": "Şücâüddin Orhan Bey", "aliases": ["Orhan Bey"], "title": "bey", "birth": null, "birthNote": "kayıtlarda yok", "death": 1340, "deathNote": "1340 civarında vefat ettiği tahmin edilmektedir.", "reign": [1319, 1340], "reignNote": "İbn Battûta 1333'te onu Peçin'de ziyaret etmiş ve 'Milas sultanı' olarak vasıflandırmıştır.", "summary": "Beyliğin merkezini müstahkem Peçin Kalesi'ne nakletmiş, Milas'ta Hacı İlyas Camii'ni yaptırmıştır. İbn Battûta seyahatnamesinde onun adaletini ve şehirlerinin bayındırlığını övgüyle anlatır.", "traits": ["imarperver", "âdil"], "contribution": "Peçin şehrini bayındır bir merkez haline getirmiş, cami ve saraylar inşa ettirmiştir.", "harm": "", "wives": [], "children": [{"name": "İbrâhim Bey", "mother": "", "note": "Halefi, ulu bey", "certainty": "kesin"}, {"name": "Hızır Bey", "mother": "", "note": "Çine hâkimi", "certainty": "kesin"}], "wars": [], "legends": [], "sources": [{"title": "TDV İslâm Ansiklopedisi, MENTEŞEOĞULLARI", "url": "https://islamansiklopedisi.org.tr/menteseogullari"}]}, {"id": "mentese-ibrahim-bey", "name": "İbrâhim Bey", "aliases": ["İbrâhim b. Orhan"], "title": "bey", "birth": null, "birthNote": "kayıtlarda yok", "death": 1355, "deathNote": "1355 civarında vefat etmiştir.", "reign": [1340, 1355], "reignNote": "Muğla Ulucamii kitâbesi 1344 tarihlidir.", "summary": "Aydınoğulları ile ittifak kurarak Haçlı donanmasına ve Latin Girit'e karşı akınlar düzenlemiştir. Balat limanında Venediklilere ticaret izni veren ilk resmi antlaşmaları akdetmiştir.", "traits": ["denizci", "diplomat"], "contribution": "Muğla ve Ula ulucamilerini yaptırmıştır; Balat liman ticaretini canlandırmıştır.", "harm": "1352-1355'te Venedik donanmasının Balat'ı tehdidi sonucu donanma faaliyetlerinde kısıtlamaya gitmek zorunda kalmıştır.", "wives": [], "children": [{"name": "Mûsâ Bey", "mother": "", "note": "Peçin ve Balat hâkimi", "certainty": "kesin"}, {"name": "Mehmed Bey", "mother": "", "note": "Muğla ve Çine hâkimi", "certainty": "kesin"}, {"name": "Gazi Ahmed Bey", "mother": "", "note": "Makri ve Marmaris hâkimi, sonra ulu bey", "certainty": "kesin"}], "wars": [{"name": "Girit Deniz Akınları", "when": "1344-1350", "foe": "Venedik Cumhuriyeti (Girit)", "result": "zafer", "note": "Aydınoğulları ile birlikte Girit sahillerine sefer düzenlendi."}], "legends": [], "sources": [{"title": "TDV İslâm Ansiklopedisi, MENTEŞEOĞULLARI", "url": "https://islamansiklopedisi.org.tr/menteseogullari"}, {"title": "Britannica, Menteşe Dynasty", "url": "https://www.britannica.com/topic/Mentese-dynasty"}]}, {"id": "mentese-musa-bey", "name": "Mûsâ Bey", "aliases": ["Mûsâ b. İbrâhim"], "title": "bey", "birth": null, "birthNote": "kayıtlarda yok", "death": 1375, "deathNote": "1375'ten önce vefat etti.", "reign": [1355, 1375], "reignNote": "Peçin, Balat ve Milas kolunun ulu beyidir.", "summary": "Babası İbrâhim Bey'in ardından ulu bey sıfatıyla Venedik Kandiye dukası ile barış ve ticaret antlaşmaları yapmıştır.", "traits": ["ticarete önem veren"], "contribution": "Latin dünyasıyla ticari istikrarı sürdürmüştür.", "harm": "", "wives": [], "children": [], "wars": [], "legends": [], "sources": [{"title": "TDV İslâm Ansiklopedisi, MENTEŞEOĞULLARI", "url": "https://islamansiklopedisi.org.tr/menteseogullari"}]}, {"id": "mentese-ahmed-gazi-bey", "name": "Gazi Ahmed Bey", "aliases": ["Ahmed Gazi"], "title": "gazi", "birth": null, "birthNote": "kayıtlarda yok", "death": 1391, "deathNote": "1391 yılı Temmuz ayında (Şaban 793) vefat etti; Peçin'deki medresesinin türbesine defnedildi.", "reign": [1375, 1391], "reignNote": "Menteşe Beyliği'nin en parlak hükümdarlarındandır; 'sultânü's-sevâhil' lakabını kullanmıştır.", "summary": "Menteşeoğulları'nın en güçlü hükümdar ve deniz gazilerindendir. Ege adalarından (Naksos) vergi almış, Rodos Şövalyeleri ve Kıbrıs filolarına karşı Akdeniz'i savunmuştur. Peçin'deki Ahmed Gazi Medresesi ve Milas Ulucamii gibi eşsiz mimari eserler bırakmıştır.", "traits": ["gazi", "büyük denizci", "imarperver"], "contribution": "Peçin Ahmed Gazi Medresesi (1375) ve Milas Ulucamii'ni (1378) inşa ettirmiştir.", "harm": "Ölümüyle beylik Yıldırım Bayezid'in Osmanlı kuvvetlerince kolayca ilhak edilmiştir.", "wives": [], "children": [], "wars": [{"name": "Ege Adaları ve Rodos Seferleri", "when": "1375-1385", "foe": "Latin Düklükleri ve Hospitalier Şövalyeleri", "result": "zafer", "note": "Nakşa adası haraca bağlandı."}], "legends": ["Türbesindeki kılıç ve sancağı halk arasında asırlarca gazilik sembolü olarak ziyaret edilmiştir."], "sources": [{"title": "TDV İslâm Ansiklopedisi, MENTEŞEOĞULLARI", "url": "https://islamansiklopedisi.org.tr/menteseogullari"}]}, {"id": "mentese-mehmed-bey", "name": "Mehmed Bey", "aliases": ["Mehmed b. İbrâhim"], "title": "bey", "birth": null, "birthNote": "kayıtlarda yok", "death": 1403, "deathNote": "1403 başında vefat etti.", "reign": [1402, 1403], "reignNote": "Ankara Savaşı sonrası Timur'un ordugâhına giderek beyliği iade alan yaşlı ulu beydir.", "summary": "1391 öncesinde Muğla ve Çine hâkimi iken Osmanlı ilhakıyla çekilmiş, 1402'de Timur'a biat ederek beyliğin başına dönmüş fakat kısa süre sonra vefat etmiştir.", "traits": ["yaşlı ulu bey"], "contribution": "Beyliğin 1402'de yeniden ihya edilmesini sağlamıştır.", "harm": "", "wives": [], "children": [{"name": "İlyas Bey", "mother": "", "note": "Halefi, ulu bey", "certainty": "kesin"}, {"name": "Gıyâseddin Mahmud", "mother": "", "note": "Balat hâkimi; adına Bâznâme tercüme ettirmiştir", "certainty": "kesin"}], "wars": [], "legends": [], "sources": [{"title": "TDV İslâm Ansiklopedisi, MENTEŞEOĞULLARI", "url": "https://islamansiklopedisi.org.tr/menteseogullari"}]}, {"id": "mentese-ilyas-bey", "name": "İlyas Bey", "aliases": ["Menteşeoğlu İlyas Bey"], "title": "bey", "birth": null, "birthNote": "kayıtlarda yok", "death": 1421, "deathNote": "1421'de vefat etti; Balat'taki İlyas Bey Külliyesi türbesine defnedildi.", "reign": [1403, 1421], "reignNote": "Menteşe Beyliği'nin son kudretli hükümdarıdır.", "summary": "Fetret Devri'nde Osmanlı taht kavgalarına müdahil olmuş, Çelebi Mehmed'in üstünlüğü üzerine onun vasalı olarak beyliğini yönetmiştir. Venedik ile 1414'te Peçin'de ticaret antlaşması yenilemiş, Balat'ta Türk mimarisinin başyapıtlarından İlyas Bey Camii ve Külliyesi'ni (1404) yaptırmıştır.", "traits": ["imarperver", "diplomat", "kültür hamisi"], "contribution": "Balat İlyas Bey Külliyesi'ni yaptırmış, tıp eseri İlyâsiyye'yi tercüme ettirmiştir.", "harm": "1415'te oğullarını Edirne sarayına rehin göndermek zorunda kalmıştır.", "wives": [], "children": [{"name": "Leys Bey", "mother": "", "note": "Halefi", "certainty": "kesin"}, {"name": "Ahmed Bey", "mother": "", "note": "Halefi", "certainty": "kesin"}], "wars": [{"name": "Fetret Devri Muharebeleri", "when": "1405", "foe": "Çelebi Mehmed", "result": "yenilgi", "note": "Îsâ Çelebi safında savaştı, yenilince Çelebi Mehmed'in tâbiiyetini tanıdı."}], "legends": [], "sources": [{"title": "TDV İslâm Ansiklopedisi, MENTEŞEOĞULLARI", "url": "https://islamansiklopedisi.org.tr/menteseogullari"}]}, {"id": "mentese-leys-ve-ahmed-beyler", "name": "Leys ve Ahmed Beyler", "aliases": ["Leys b. İlyas ve Ahmed b. İlyas"], "title": "bey", "birth": null, "birthNote": "kayıtlarda yok", "death": 1424, "deathNote": "1424'te II. Murad tarafından esir alınıp hapsedildiler.", "reign": [1421, 1424], "reignNote": "Babaları İlyas Bey'in ölümü üzerine Edirne'den kaçarak müştereken beyliğin başına geçtiler.", "summary": "İlyas Bey'in oğullarıdır. Babalarının vefatı üzerine rehin tutuldukları Edirne'den firar ederek Menteşe tahtına oturmuşlardır. II. Murad 1424'te sefere çıkarak iki kardeşi yakalatıp hapsetmiş ve Menteşe Beyliği'ne kesin olarak son vermiştir.", "traits": ["cüretkâr"], "contribution": "", "harm": "Osmanlı ile çatışmaları beyliğin kesin tasfiyesine yol açtı.", "wives": [], "children": [], "wars": [{"name": "Menteşe'nin Osmanlı Tarafından İlhakı", "when": "1424", "foe": "II. Murad ordusu", "result": "yenilgi", "note": "İki kardeş esir alındı, Menteşe ili Osmanlı sancağı yapıldı."}], "legends": [], "sources": [{"title": "TDV İslâm Ansiklopedisi, MENTEŞEOĞULLARI", "url": "https://islamansiklopedisi.org.tr/menteseogullari"}, {"title": "Britannica, Menteşe Dynasty", "url": "https://www.britannica.com/topic/Mentese-dynasty"}]}]}, {"id": "esref", "name": "Eşrefoğulları Beyliği", "short": "Eşrefoğulları", "aliases": ["Eşref Beyliği", "Eşrefoğlu Beyliği"], "region": "anadolu", "start": 1284, "end": 1326, "startNote": "Seyfeddin Süleyman Bey'in Selçuklu nâibi olması ve Gorgorum-Beyşehir merkezli bağımsız hareket etmeye başlaması 1284 civarıdır.", "endNote": "9 Ekim 1326'da İlhanlı genel valisi Timurtaş'ın Beyşehir'e girerek II. Süleyman Bey'i göle attırıp katletmesiyle beylik yıkılmıştır.", "capital": "Beyşehir (Süleymanşehir)", "religion": "İslâm", "confidence": "kayit", "confidenceNote": "Beyşehir Eşrefoğlu Camii kitabeleri (1299), vakfiyesi, sikkeleri ve Aksarâyî ile İbn Fazlullah el-Ömerî'de ayrıntılı biçimde mevcuttur.", "summary": "Beyşehir Gölü havzası ve Seydişehir çevresinde kurulan Türkmen beyliğidir. Kurucusu Seyfeddin Süleyman Bey, merkezini Beyşehir'e taşıyarak muhteşem ahşap direkli Eşrefoğlu Camii'ni inşa ettirmiştir. Mehmed Bey devrinde Akşehir ve Bolvadin'e kadar genişleyen beylik, 1326'da Moğol emiri Timurtaş Noyan'ın kanlı istilasıyla tarihe karışmış, toprakları Hamîdoğulları ve Karamanoğulları arasında paylaşılmıştır.", "legacy": "Beyşehir Eşrefoğlu Camii (1299), Anadolu Türk ahşap direkli cami mimarisinin günümüze ulaşan en büyük ve en görkemli şaheseridir.", "essay": ["Eşrefoğulları, Anadolu Selçuklu Devleti'nin son çeyreğinde Beyşehir ve Seydişehir yöresinde kurulan önemli bir Türkmen beyliğidir. Selçuklu uç beyi Seyfeddin Süleyman Bey, 1284 saltanat buhranında saltanat nâibliğine kadar yükselmiş, ardından merkezini Gorgorum'dan Beyşehir'e taşıyarak kale, cami, bedesten ve imaret inşa ettirmiştir.", "Süleyman Bey'in 1299'da tamamladığı ahşap direkli Eşrefoğlu Camii, Selçuklu taş ve ahşap işçiliğinin, çini mozaik mihrabının ve karlık sisteminin eşsiz bir sentezidir. Süleyman Bey'in ardından oğlu Mübârizüddin Mehmed Bey devrinde beylik Akşehir, Bolvadin, Ilgın ve Seydişehir'i içine alarak 70.000 süvari çıkaracak güce erişmiştir.", "İlhanlı genel valisi Timurtaş'ın bağımsızlık ilan edip Türkmen beyliklerini ezmeye yönelmesi Eşrefoğulları'nın sonunu getirmiştir. Timurtaş'ı Tebriz'deki Ebû Said Bahadır Han'a şikâyet eden II. Süleyman Bey, affedilip geri dönen Timurtaş'ın ani bir intikam seferiyle karşı karşıya kalmış; 9 Ekim 1326'da Beyşehir Kalesi zaptedilerek Süleyman Bey göle atılmak suretiyle katledilmiştir. Beylik böylece yıkılmıştır."], "sources": [{"title": "TDV İslâm Ansiklopedisi, EŞREFOĞULLARI", "url": "https://islamansiklopedisi.org.tr/esrefogullari"}, {"title": "TDV İslâm Ansiklopedisi, EŞREFOĞLU CAMİİ", "url": "https://islamansiklopedisi.org.tr/esrefoglu-camii"}], "rulers": [{"id": "esref-seyfeddin-suleyman-bey", "name": "Seyfeddin Süleyman Bey", "aliases": ["Eşrefoğlu Süleyman Bey"], "title": "emîr-i kebîr", "birth": null, "birthNote": "kayıtlarda yok", "death": 1302, "deathNote": "1302 yılı Ağustos ayında Beyşehir'de vefat etti ve yaptırdığı türbesine defnedildi.", "reign": [1284, 1302], "reignNote": "Beyliğin kurucusudur; 1288'de Beyşehir Kalesi'ni yaptırmış, 1299'da istiklâlini pekiştirmiştir.", "summary": "Eşrefoğulları Beyliği'nin kurucusudur. Selçuklu Devleti'nde saltanat nâibliği yapmış, Beyşehir şehrini (Süleymanşehir) imar ederek Türk mimarisinin zirvelerinden olan ahşap direkli Eşrefoğlu Camii'ni (1299) yaptırmıştır.", "traits": ["kurucu", "büyük bâni", "teşkilatçı"], "contribution": "Beyşehir Kalesi, Eşrefoğlu Camii, bedesten, hamam ve medreseyi yaptırarak Beyşehir'i mamur bir merkez yaptı.", "harm": "", "wives": [{"name": "kayıtlarda adı geçmiyor", "note": "Türbede sandukası bulunan eşi", "certainty": "olasi"}], "children": [{"name": "Mübârizüddin Mehmed Bey", "mother": "", "note": "Halefi, ulu bey", "certainty": "kesin"}, {"name": "Eşref Bey", "mother": "", "note": "Vakfiyede adı geçen ve babasının türbesinde yatan küçük oğlu", "certainty": "kesin"}, {"name": "Gülcemal Hatun", "mother": "", "note": "Selçuklu şehzadesi Rükneddin Geyûmers ile evlendirilmek istenen kızı", "certainty": "olasi"}], "wars": [{"name": "Moğol Geyhatu Seferi Direnişi", "when": "1291-1292", "foe": "İlhanlı Geyhatu Han ordusu", "result": "yenilgi", "note": "Beyşehir yağmalandı, Süleyman Bey bir süre Gevele Kalesi'ne çekildi."}], "legends": ["Eşrefoğlu Camii'nin ortasındaki karlık kuyusuna kışın gölden kar doldurularak sedir sütunların nem dengesinin sağlandığı mimari harika rivayet edilir."], "sources": [{"title": "TDV İslâm Ansiklopedisi, EŞREFOĞULLARI", "url": "https://islamansiklopedisi.org.tr/esrefogullari"}, {"title": "TDV İslâm Ansiklopedisi, EŞREFOĞLU CAMİİ", "url": "https://islamansiklopedisi.org.tr/esrefoglu-camii"}]}, {"id": "esref-mubarizuddin-mehmed-bey", "name": "Mübârizüddin Mehmed Bey", "aliases": ["Mehmed Bey b. Süleyman"], "title": "emîrü'l-a‘zam", "birth": null, "birthNote": "kayıtlarda yok", "death": 1320, "deathNote": "1320 yılında Beyşehir'de vefat etti.", "reign": [1302, 1320], "reignNote": "Babası Süleyman Bey'in ardından ulu bey olmuştur.", "summary": "Eşrefoğulları'nın en güçlü hükümdarıdır. Topraklarını Bolvadin, Akşehir, Sultandağı ve Ilgın'a kadar genişletmiştir. Âlimleri ve şairleri himaye etmiş, adına el-Fusûlü'l-Eşrefiyye felsefe kitabı yazılmıştır.", "traits": ["fatih", "âlimperver", "Mevlevî"], "contribution": "Bolvadin Çarşı Camii (1320) ve Akşehir'de cami inşa ettirdi; felsefe ve münşeat kitaplarına hamisi oldu.", "harm": "", "wives": [], "children": [{"name": "II. Süleyman Bey", "mother": "", "note": "Halefi, Süleyman Şah", "certainty": "kesin"}], "wars": [{"name": "Akşehir ve Bolvadin Seferleri", "when": "1314-1318", "foe": "İlhanlı valileri ve yerel güçler", "result": "zafer", "note": "Ilgın, Akşehir, Çay ve Bolvadin beylik topraklarına katıldı."}], "legends": ["Mevlânâ'nın torunu Ulu Ârif Çelebi ile Beyşehir'de sohbet ettiği ve Mevlevîliğe intisap ettiği Menâkıbü'l-ârifîn'de geçer."], "sources": [{"title": "TDV İslâm Ansiklopedisi, EŞREFOĞULLARI", "url": "https://islamansiklopedisi.org.tr/esrefogullari"}]}, {"id": "esref-ii-suleyman-bey", "name": "II. Süleyman Bey", "aliases": ["Süleyman Şah"], "title": "şah", "birth": null, "birthNote": "kayıtlarda yok", "death": 1326, "deathNote": "9 Ekim 1326'da İlhanlı valisi Timurtaş tarafından Beyşehir Gölü'ne atılarak boğduruldu.", "reign": [1320, 1326], "reignNote": "Eşrefoğulları'nın son beyidir.", "summary": "Mübârizüddin Mehmed Bey'in oğludur. İlhanlı genel valisi Timurtaş'ın isyan ve tiranlığını İlhanlı sultanı Ebû Said Bahadır Han'a şikâyet etmiştir. İntikam için Beyşehir'e hücum eden Timurtaş tarafından feci şekilde katledilmiş ve beylik yıkılmıştır.", "traits": ["cesur", "talihsiz"], "contribution": "", "harm": "Timurtaş'ın ani taarruzu karşısında ülkesini savunamayarak beyliğin yok olmasına engel olamadı.", "wives": [], "children": [], "wars": [{"name": "Beyşehir Savunması", "when": "1326", "foe": "İlhanlı genel valisi Timurtaş ordusu", "result": "yenilgi", "note": "Beyşehir düştü, Süleyman Bey esir edilip katledildi."}], "legends": ["Timurtaş'ın Süleyman Şah'ı Beyşehir Gölü'nde boğdurttuğu ve cesedinin suya atıldığı kaynaklarda teessürle nakledilir."], "sources": [{"title": "TDV İslâm Ansiklopedisi, EŞREFOĞULLARI", "url": "https://islamansiklopedisi.org.tr/esrefogullari"}]}]}, {"id": "candaroglu", "name": "Candaroğulları Beyliği", "short": "Candaroğulları", "aliases": ["İsfendiyaroğulları", "Kastamonu Beyliği"], "region": "anadolu", "start": 1291, "end": 1461, "startNote": "Şemseddin Yaman Candar'ın Selçuklu Sultanı Mesud tarafından Kastamonu emirliğine atanmasıyla kuruldu.", "endNote": "1461 yılında Fatih Sultan Mehmed'in Trabzon Seferi sırasında Sinop ve Kastamonu'yu ilhakıyla sona erdi.", "capital": "Kastamonu ve Sinop", "religion": "İslamiyet (Sünnî-Hanefî)", "confidence": "kayit", "confidenceNote": "İbn Battûta Seyahatnâmesi, Osmanlı vekayinameleri ve Sinop kitabeleriyle sabittir.", "summary": "Oğuzların Kayı koluyla akraba Türkmenler tarafından Kuzey Anadolu'da (Kastamonu, Sinop, Çankırı, Safranbolu) kurulan beylik. Sinop tersanesi sayesinde güçlü bir Karadeniz donanması kurdular; Cenevizlilerle deniz ticareti yaptılar. İsfendiyar Bey devrinde Osmanlı ile denge siyaseti güttüler. İlim ve tababete büyük önem verdiler; ilk Türkçe tıp kitapları bu sarayda yazıldı. 1461'de Fatih Sultan Mehmed tarafından Osmanlı'ya katıldı.", "legacy": "Sinop tersanesi ve Karadeniz Türk denizciliğini geliştirdi; Türkçe telif ve tercüme tıp eserlerinin (Müntahab-ı Şifâ) yazılmasını teşvik etti.", "essay": ["Candaroğulları, Selçuklu Sultanı II. Mesud'u düşmanlarının elinden kurtaran Şemseddin Yaman Candar'a Kastamonu'nun dirlik verilmesiyle 1291'de kuruldu.", "Süleyman Paşa 1322'de Sinop'u fethederek beyliğe güçlü bir deniz üssü kazandırdı. İbn Battûta 1332'de Kastamonu'ya uğradığında burayı ucuz ve mamur bir şehir, hükümdarı Süleyman Bey'i de dindar ve adil bir sultan olarak tasvir eder.", "Kötürüm Bâyezid ve İsfendiyar Bey dönemlerinde Timur istilasında beylik genişledi. Fatih Sultan Mehmed, Trabzon Rum İmparatorluğu'na sefere çıktığı 1461 yılında Sinop'u karadan ve denizden kuşattı; son hükümdar İsmail Bey kan dökülmesini istemeyerek şehri teslim etti ve kendisine Bursa ve Yenişehir tımar olarak verildi."], "sources": [{"title": "TDV İslâm Ansiklopedisi, CANDAROĞULLARI", "url": "https://islamansiklopedisi.org.tr/candarogullari"}], "rulers": [{"id": "candaroglu-yaman-candar", "name": "Şemseddin Yaman Candar", "aliases": ["Yaman Candar"], "title": "Emir / Candar", "birth": null, "birthNote": "Kayıtlarda yok", "death": 1301, "deathNote": "Kastamonu'da vefat etti", "reign": [1291, 1301], "reignNote": "10 yıllık kurucu beylik.", "summary": "Beyliğin kurucusu. Selçuklu saray muhafız birliği (candar) komutanıydı. Sultan II. Mesud'u kurtardığı için kendisine Kastamonu dirlik verildi.", "traits": ["Sadık muhafız", "Cesur komutan"], "contribution": "Batı Karadeniz'de köklü bir Türk beyliğinin temelini attı.", "harm": "Kayıtlarda belirgin bir zararı geçmez.", "wives": [], "children": [{"name": "I. Süleyman Paşa", "mother": "", "note": "Sinop'u fetheden hükümdar", "certainty": "kesin"}], "wars": [{"name": "Kastamonu Muharebesi", "when": "1291", "foe": "Çobanoğulları muhalifleri", "result": "zafer", "note": "Kastamonu zaptedildi."}], "legends": [], "sources": [{"title": "TDV İslâm Ansiklopedisi, CANDAROĞULLARI", "url": "https://islamansiklopedisi.org.tr/candarogullari"}]}, {"id": "candaroglu-ismail-bey", "name": "Kemâleddin İsmail Bey", "aliases": ["İsmail Bey"], "title": "Bey / Kemâleddin", "birth": null, "birthNote": "Kayıtlarda yok", "death": 1479, "deathNote": "Filibe'de vefat etti, türbesi oradadır", "reign": [1443, 1461], "reignNote": "18 yıl hüküm sürdü.", "summary": "Candaroğullarının son hükümdarı. Büyük bir âlim ve tıp aşığıydı. Kendisi 'Hulviyyât-ı Şâhî' adlı fıkıh kitabını yazdı; Kastamonu'da İsmail Bey Külliyesi'ni yaptırdı. 1461'de Fatih'in ordusu gelince Müslüman kanı dökülmesin diye Sinop'u teslim etti.", "traits": ["Âlim hükümdar", "Merhametli ve cömert", "Yazar"], "contribution": "Kastamonu'da muhteşem İsmail Bey Külliyesi'ni kurdu; Türkçe ilmi eserler telif ettirdi.", "harm": "Devletini Osmanlı'ya karşı askeri olarak savunamadı.", "wives": [], "children": [{"name": "Hasan Bey", "mother": "", "note": "Oğlu", "certainty": "kesin"}], "wars": [], "legends": ["Fatih Sultan Mehmed onun teslimiyetindeki asalete hürmet ederek kendisine hürmetle muamele etmiş ve Filibe zeametini vermiştir."], "sources": [{"title": "TDV İslâm Ansiklopedisi, CANDAROĞULLARI", "url": "https://islamansiklopedisi.org.tr/candarogullari"}]}]}, {"id": "karesi", "name": "Karesioğulları Beyliği", "short": "Karesi", "aliases": ["Karesi Beyliği", "Karasioğulları", "Karesi Vilâyeti"], "region": "anadolu", "start": 1297, "end": 1361, "startNote": "TDV İslâm Ansiklopedisi, Selçuklu uç beyi Kalemşah ve oğlu Karesi Bey'in Bizans Mysia şehirlerini fethini 1296-1297 yıllarına koyar. Bağımsız beylik ilanı yaklaşık 1300'dür.", "endNote": "Demirhan Bey'in Bergama'da teslim olması 1345'tir; Marmara ve Çanakkale kıyılarındaki son toprakların ilhakı ve Karesi beylerinin Osmanlı idaresine tam intibakı 1361 civarına kadar sürer.", "capital": "Balıkesir (daha sonra Bergama ikinci merkez oldu)", "religion": "İslâm", "confidence": "kayit", "confidenceNote": "Beyliğin kuruluşu ve hükümdarları çağdaş Bizans kaynakları (Kantakuzenos, Gregoras, Dukas) ve erken Osmanlı vekayinamelerinde (Âşıkpaşazâde, Neşrî) kayıtlıdır.", "summary": "Güney Marmara ve Kuzey Ege kıyılarında (Balıkesir, Çanakkale, Bergama) kurulan denizci Türkmen beyliğidir. Güçlü bir donanma kurarak Ege adaları ve Trakya sahillerine akınlar düzenlemiş, Edremit açıklarında Haçlı donanmasıyla savaşmıştır. İç karışıklıklar ve taht kavgaları neticesinde Orhan Gazi döneminde Osmanlı topraklarına katılmış, donanması ve tecrübeli ümerası Rumeli fütûhatında kilit rol oynamıştır.", "legacy": "Osmanlı Devleti'nin ilhak ettiği ilk beyliktir. Karesi bahriyesi Osmanlı denizciliğinin çekirdeğini oluşturmuş; Hacı İlbey, Evrenos Bey ve Ece Bey gibi komutanlar Rumeli fethinin öncüsü olmuştur.", "essay": ["Karesioğulları, Selçuklu Devleti'nin dağılma sürecinde Batı Anadolu uçlarında kurulan ilk denizci beyliklerdendir. Dânişmendliler soyuna dayandıkları Tokat'taki aile mezar kitabelerinden anlaşılan Kalem Bey ile oğlu Karesi Bey, XIII. yüzyılın sonlarında Balıkesir ve Bergama çevresini Bizans'tan alarak beyliğin temellerini atmışlardır.", "Karesi Bey'in ardından Bergama'da oturan Yahşi Bey döneminde beylik güçlü bir donanma inşa etmiş, Ege adaları ve Gelibolu-Trakya sahillerine yoğun akınlar yapmıştır. Bu deniz gazaları üzerine Venedik, Bizans ve Rodos Şövalyeleri birleşerek bir Haçlı ittifakı kurmuş ve 1334'te Edremit Körfezi'nde Karesi donanmasıyla şiddetli bir muharebeye tutuşmuştur.", "Yahşi Bey'in vefatından sonra Balıkesir'deki Demirhan Bey ile halk tarafından sevilen Dursun Bey arasında taht mücadelesi baş göstermiştir. Karesi ümerasının davetiyle müdahale eden Orhan Gazi, Dursun Bey'in Bergama surları önünde maktul düşmesinin ardından kaleyi teslim alıp Demirhan'ı Bursa'ya göndermiştir. Böylece Karesi ili Osmanlı idaresine geçmiş ve Rumeli'ye geçişin kapısı aralanmıştır."], "sources": [{"title": "TDV İslâm Ansiklopedisi, KARESİOĞULLARI", "url": "https://islamansiklopedisi.org.tr/karesiogullari"}, {"title": "Britannica, Karası", "url": "https://www.britannica.com/biography/Karasi"}], "rulers": [{"id": "karesi-karesi-bey", "name": "Karesi Bey", "aliases": ["Karası Bey"], "title": "bey", "birth": null, "birthNote": "kayıtlarda yok", "death": 1328, "deathNote": "1328'den önce vefat ettiği kabul edilir; kesin ölüm yılı kayıtlarda yoktur.", "reign": [1297, 1328], "reignNote": "Babası Kalem Bey ile fethe başladığı tarih 1296-1297; beyliğin müstakil kuruluşu 1300 civarıdır.", "summary": "Karesioğulları Beyliği'nin kurucusudur. Babası Kalem Bey ile birlikte Mysia bölgesindeki Bizans kalelerini fethederek Balıkesir merkezli müstakil idare tesis etmiştir.", "traits": ["gaza önderi", "teşkilatçı"], "contribution": "Balıkesir ve Çanakkale yöresini Türk yurdu haline getirmiş, beyliğin siyasî teşekkülünü sağlamıştır.", "harm": "", "wives": [], "children": [{"name": "Yahşi Bey", "mother": "", "note": "Bergama emiri ve halefi", "certainty": "kesin"}, {"name": "Demirhan Bey", "mother": "", "note": "Balıkesir emiri; kaynaklarda oğlu veya kardeşi diye geçer", "certainty": "tartismali"}, {"name": "Dursun Bey", "mother": "", "note": "Orhan Gazi'den yardım isteyen oğul", "certainty": "olasi"}], "wars": [{"name": "Mysia ve Balıkesir Fetihleri", "when": "1296-1300", "foe": "Bizans İmparatorluğu", "result": "zafer", "note": "Erdek, Biga, Edremit ve Bergama çevresi ele geçirildi."}], "legends": ["Balıkesir Zağanos Paşa Camii civarındaki Karesi Dede (Karaisa) türbesinde yattığı rivayet edilir."], "sources": [{"title": "TDV İslâm Ansiklopedisi, KARESİOĞULLARI", "url": "https://islamansiklopedisi.org.tr/karesiogullari"}, {"title": "Britannica, Karası", "url": "https://www.britannica.com/biography/Karasi"}]}, {"id": "karesi-yahsi-bey", "name": "Yahşi Bey", "aliases": ["Aclan Bey"], "title": "melik", "birth": null, "birthNote": "kayıtlarda yok", "death": 1341, "deathNote": "1341 Bizans seferinden sonra kayıtlardan çekilmiş, kısa süre sonra vefat ettiği kabul edilir.", "reign": [1328, 1341], "reignNote": "Bergama merkezli olarak han ve melik unvanlarıyla hüküm sürmüştür.", "summary": "Karesi donanmasını güçlendirerek Ege adalarına ve Trakya sahillerine akınlar düzenleyen denizci hükümdardır. 1334'te Edremit sularında Haçlı donanmasıyla çarpışmıştır.", "traits": ["denizci", "akıncı", "cesur"], "contribution": "Karesi deniz gücünü Ege'de söz sahibi yapmış, adına gümüş ve bakır sikkeler darbettirmiştir.", "harm": "1334 Edremit deniz savaşında Karesi donanması ağır hasar almıştır.", "wives": [], "children": [{"name": "Beylerbeyi", "mother": "", "note": "Adına sikke basılmış oğlu", "certainty": "kesin"}], "wars": [{"name": "Edremit Deniz Muharebesi", "when": "1334", "foe": "Haçlı İttifakı (Venedik, Rodos Şövalyeleri, Bizans)", "result": "yenilgi", "note": "Yahşi Bey kumandasındaki filo Haçlı donanmasına yenildi."}, {"name": "Trakya ve Gelibolu Seferleri", "when": "1337-1341", "foe": "Bizans İmparatorluğu", "result": "belirsiz", "note": "Gelibolu ve Trakya'ya asker çıkarıldı; III. Andronikos'un ölümünün ardından yapılan taarruzlar sonuçsuz kalıp saldırmazlık antlaşması yapıldı."}], "legends": [], "sources": [{"title": "TDV İslâm Ansiklopedisi, KARESİOĞULLARI", "url": "https://islamansiklopedisi.org.tr/karesiogullari"}]}, {"id": "karesi-demirhan-bey", "name": "Demirhan Bey", "aliases": ["Timurhan Bey"], "title": "bey", "birth": null, "birthNote": "kayıtlarda yok", "death": 1347, "deathNote": "1345'te Bergama'da teslim olup Bursa'ya gönderilmiş, iki yıl sonra veba veya eceliyle ölmüştür.", "reign": [1341, 1345], "reignNote": "1328'den itibaren Balıkesir hâkimidir; Yahşi Bey'in ardından ulu bey durumuna geçmiştir.", "summary": "Balıkesir ve Bergama hâkimidir. İdaresindeki hoşnutsuzluk ve kardeşi Dursun Bey ile taht kavgası üzerine Orhan Gazi müdahale etmiş, Bergama Kalesi'nde teslim olan Demirhan Bey Bursa'ya sürgün edilerek beylik ilhak edilmiştir.", "traits": ["uzlaşmaz"], "contribution": "", "harm": "Kardeşiyle kavgası ve kötü idaresi beyliğin iç karışıklıkla Osmanlılara ilhakına yol açmıştır.", "wives": [], "children": [], "wars": [{"name": "Bergama Kuşatması", "when": "1345", "foe": "Orhan Gazi ve Dursun Bey taraftarları", "result": "yenilgi", "note": "Demirhan Bey kalede teslim oldu, beylik Osmanlı topraklarına katıldı."}], "legends": [], "sources": [{"title": "TDV İslâm Ansiklopedisi, KARESİOĞULLARI", "url": "https://islamansiklopedisi.org.tr/karesiogullari"}, {"title": "Britannica, Karası", "url": "https://www.britannica.com/biography/Karasi"}]}, {"id": "karesi-dursun-bey", "name": "Dursun Bey", "aliases": ["Turhasan"], "title": "bey", "birth": null, "birthNote": "kayıtlarda yok", "death": 1345, "deathNote": "Bergama surları önünde kaleden atılan bir okla vurularak öldü.", "reign": [1345, 1345], "reignNote": "Ulu beylik yapamamıştır; taht iddiacısı sıfatıyla Orhan Gazi'nin desteğinde Bergama'ya gelmiştir.", "summary": "Karesi ileri gelenleri ve halk tarafından desteklenen şehzadedir. Orhan Gazi'yi yardıma çağırarak Bergama önüne gelmiş, kaledeki ağabeyiyle müzakere ederken atılan bir okla şehit düşmüştür.", "traits": ["halk tarafından sevilen"], "contribution": "", "harm": "", "wives": [], "children": [], "wars": [{"name": "Bergama Kuşatması Müzakeresi", "when": "1345", "foe": "Demirhan Bey kalesi muhafızları", "result": "yenilgi", "note": "Surlardan atılan okla öldürüldü."}], "legends": ["Balıkesir'in Dursunbey ilçesinin adının bu şehzadeden kaldığı rivayet edilir."], "sources": [{"title": "TDV İslâm Ansiklopedisi, KARESİOĞULLARI", "url": "https://islamansiklopedisi.org.tr/karesiogullari"}]}]}, {"id": "osmanli", "name": "Osmanlı Devleti", "short": "Osmanlı", "aliases": ["Âl-i Osmân", "Devlet-i Aliyye", "Osmanlı İmparatorluğu"], "region": "anadolu", "start": 1299, "end": 1922, "startNote": "1299, kendi adına hutbe okutulduğu yolundaki geç kronik anlatısının geleneksel ve simgesel yılıdır. Halil İnalcık TDV Osman maddesinde bu hutbe-bağımsızlık hikâyesinin sonradan eklendiğini, hukukî sultanlığın hutbe ve sikkeyle ancak İlhanlı çizgisinin çözülmesinden sonra yaygınlaştığını yazar; beyliğin daha erken bir uç süreci olduğunu ve çağdaş Pachymeres'e dayanan Bapheus/Koyunhisar zaferini (1302-07-27) hânedanın fiilî kuruluş eşiği sayar. TDV Osmanlılar maddesi siyasî tarihi 1300-1922 aralığıyla verir. Beylik, Söğüt-Yenişehir hattında Osman'dan önce Ertuğrul'un uç beyliği olarak şekillenmeye başlamıştır.", "endNote": "Saltanat, Türkiye Büyük Millet Meclisi'nce 1922-11-01 kaldırıldı. VI. Mehmed 1922-11-17 İstanbul'dan ayrıldı. Hilâfet 1922-11-19 Abdülmecid Efendi'ye geçirildi, 1924'te ilga edildi. Devlet kaydının sonu saltanatın kaldırıldığı 1922'dir; padişahın ölümü (1926) devlet sonu değildir.", "capital": ["Söğüt", "Bursa", "Edirne", "İstanbul"], "religion": "İslâm (Sünnî fıkıh ve gazâ ideolojisi; erken uçta tasavvuf ve istimâlet, 16. yüzyıldan itibaren Sünnîlik daha belirgin devlet siyaseti)", "confidence": "kayit", "confidenceNote": "14. yüzyıl ortasından 1922'ye kadarki padişah dizisi, saltanat yılları ve büyük savaşların sonuçları TDV maddelerinde yüksektir. Kuruluş (Ertuğrul'un babası, Osman'ın doğumu, 1299'un hukuki anlamı, Mal Hatun'un kimliği) düşüktür; çatışmada İnalcık'ın TDV Osman ve Orhan maddeleri esas alındı. I. Selim'in 1517'de hilâfeti bir törenle devraldığı anlatısı TDV Selim maddesinde şüpheli bulunur, olay diye yazılmadı. 17.-19. yüzyıl 'gerileme' diye tek yönlü bir okul evresine bölünmedi; dönüşüm, savaş sonucu ve mali kriz olarak yazıldı. Fâtih Kanunnâmesi'ne bağlanan kardeş katli hükmünün metin tarihi TDV'de kesinlenmez.", "summary": "Batı Anadolu'nun kuzeyindeki Türkmen uçundan çıkan Osmanlılar, Orhan'dan itibaren Bursa-İznik-İzmit hattını ve 1354'ten sonra Gelibolu köprübaşını tuttular. I. Murad ve I. Bayezid devrinde Balkanlar'da ve Anadolu beylikleri üzerinde merkezîleşme hızlandı; 1402 Ankara bozgunu devleti fetret'e düşürdü, I. Mehmed 1413'te tek hükümdar oldu. II. Mehmed'in İstanbul'u alması (1453) Anadolu-Rumeli topraklarını bir pâyitahtta birleştirdi. I. Selim doğuda Safevî ve Memlük savaşlarıyla Suriye, Mısır ve Haremeyn koruyuculuğunu üstlendi; I. Süleyman Macaristan, Akdeniz ve Irak'ta klasik idareyi pekiştirdi. 17. yüzyıldan itibaren ekberiyet, saray ve bürokrasi ortaklığı, uzun savaşlar ve mali uyum arayışı öne çıktı. 1699 Karlofça ve 1774 Küçük Kaynarca toprak ve statü kaybı getirdi; 19. yüzyıl ıslahat, borç ve milliyetçi isyanlarla, 1908-1922 meşrutiyet, savaş ve saltanatın kaldırılmasıyla kapandı.", "legacy": "Tek hânedanın altı yüzyılı aşan sürekliliği, istimâlet ve zimmet hukukuyla Balkan ve Arap topraklarında çok dinli idare, timar-tahrir düzeni, klasik çağda İstanbul'un imparatorluk başkenti oluşu. Bedeli: veraset savaşları ve kardeş katli, fetret, 1402'de merkezî yapının çöküşü, 17.-18. yüzyıl savaşlarının maliyeti ve Büyük Kaçgun, 19. yüzyıl borç ve toprak kaybı, I. Dünya Savaşı ve işgaller. Hilâfet, klasik dönemde gazâ ve Haremeyn hizmeti olarak yorumlandı; Kureyş soyuna bağlanan ve siyaseten öne çıkarılan hilâfet iddiası TDV'ye göre daha çok 18. yüzyılda, 19. yüzyılda ise siyasî sebeplerle güçlendi. Kardeş katli Fâtih'ten önce de vardı (I. Bayezid'in Yâkub'u); I. Ahmed'den sonra 1617'de ekberiyete geçildi.", "sources": [{"title": "TDV İslâm Ansiklopedisi, Osmanlılar", "url": "https://islamansiklopedisi.org.tr/osmanlilar"}, {"title": "TDV İslâm Ansiklopedisi, Mehmed VI", "url": "https://islamansiklopedisi.org.tr/mehmed-vi"}], "rulers": [{"id": "ertugrul", "name": "Ertuğrul Gazi", "title": "Uç beyi, Osman'ın babası; padişah sayılmaz", "claim": false, "birth": null, "birthNote": "Doğum yılı bilinmez. Geç kronikler doksan yaşını aşmış öldüğünü söyler; bu, doğumu 1190'lara çeken menkıbevî bir hesaptır.", "death": 1281, "deathNote": "TDV (Fahameddin Başar): muhtemelen 680/1281-82. Aynı maddede ölüm yılı olarak 1288 veya 1289 da verilir. Çağdaş Bizans ve İslâm kaynakları adını anmaz; bilgiler XV. yüzyıl kroniklerindendir.", "reign": [null, 1281], "reignNote": "Padişah sayımına girmez; predecessor. Söğüt-Domaniç hattında uç beyi. 1279'da III. Gıyâseddin Keyhusrev'i karşılayıp bağlılık bildirdiği kroniklerde geçer; ardından idareyi Osman'a bıraktığı anlaşılır. Saltanat yılı yoktur.", "summary": "Osman Bey'in babasıdır. Erken Osmanlı kronikleri onu Kayı boyuna bağlar; nesebi Oğuz Han'a ve Nûh'a kadar götüren şecerelerin tarihî değeri yoktur. Ahmedî, Enverî ve Karamânî Mehmed Paşa babasını Gündüz Alp yazar; Oruç, Âşıkpaşazâde ve Neşrî Süleyman Şah der. TDV ikinci grubu güvenilmez sayar; Osman'a ait bir sikkedeki 'Osman b. Ertuğrul b. Gündüz Alp' ibaresi Gündüz Alp lehinedir. Süleyman Şah'ın Fırat'ta boğulması bu geç ve reddedilen şecerenin rivayetidir.", "traits": ["Çağdaş tasvir yoktur. Kroniklerde gazâ ve Selçuklu sultanına bağlılık vurgulanır; bunlar kuruluştan 100-150 yıl sonra yazılmıştır."], "contribution": "Söğüt ve çevresinin Osmanlı öncesi uç merkezi olarak yerleşmesi; oğlu Osman'ın devraldığı gazi çevresi (Akça Koca, Samsa Çavuş, Konuralp gibi adlar kroniklerde onun etrafında anılır).", "harm": "Doğrudan belgelenmiş bir zulüm veya bozgun kaydı yoktur. Menkıbevî fetih listesi (Karacahisar 1231 gibi) Selçuklu seferlerinin Ertuğrul'a mal edilmesi olabilir; abartılı kuruluş kahramanlığı sonraki meşruiyet metnidir.", "wives": [{"name": "Halime Hatun", "note": "TDV Ertuğrul biyografisi anne veya eş adı vermez. Söğüt türbe bahçesinde doğudaki kabir geleneği onu Ertuğrul'un eşi diye gösterir (TDV Ertuğrul Gazi Camii ve Türbesi); türbe defalarca yenilenmiştir. Osman'ın annesi olduğu iddiası bu geç ziyaret geleneğine dayanır, biyografi maddesinde doğrulanmaz.", "certainty": "rivayet"}], "children": [{"name": "Osman", "mother": null, "note": "Beyliğin kurucusu. Babalığı sikke ve kroniklerle en sağlam bağdır.", "certainty": "kesin"}, {"name": "Saru Yatı (Savcı)", "mother": null, "note": "Kroniklerde Ertuğrul'un oğlu; 1286 İkizce/Domaniç çatışmasında öldüğü Osman maddesinde geçer. Türbe bahçesinde Savcı Bey kabri geleneği vardır.", "certainty": "olasi"}, {"name": "Gündüz", "mother": null, "note": "Neşrî'de Ertuğrul'un oğlu diye geçer. Osman'ın kardeşi Gündüz Alp ile amcası/dedesi Gündüz Alp kroniklerde karışır.", "certainty": "tartismali"}], "wars": [{"name": "Ermeni Derbendi / Sultanönü uç çatışması", "when": "1231?", "foe": "İznik Laskaris kuvvetleri", "result": "belirsiz", "note": "Kronik geleneği Ertuğrul'u I. Alâeddin Keykubad'ın Bitinya seferine bağlar. İnalcık bunu 1225-1231 uç savaşlarının bulanık hâtırası sayar; Ertuğrul'un kişisel komutanlığı çağdaş kaynakla doğrulanmaz."}, {"name": "Karacahisar", "when": "1231-32?", "foe": "Bizans tekfuru", "result": "belirsiz", "note": "Başar maddesi kronik fetihini aktarır. İnalcık, Karacahisar'ın o dönemde alınıp sonra terkedildiğini, Osman'ın 1288 civarı yeniden aldığını yazar."}], "legends": ["Babasının Süleyman Şah olduğu ve Fırat'ta (Caber) boğulduğu anlatısı Neşrî-Âşıkpaşazâde kolundadır; TDV bunu güvenilmez sayar. Daha eski kol babayı Gündüz Alp verir.", "Halime Hatun'un Osman'ın annesi olduğu halk ve türbe geleneğidir; TDV biyografisi bunu olgu diye yazmaz.", "Yassıçimen'de (1230) Selçuklu ordusuna yetişip savaşı çevirdiği yalnızca Neşrî'de geçer ve tarihî özdeşlik tartışmalıdır.", "Oğuz Han'a ve Nûh'a çıkan soy kütüğü kuruluştan çok sonra yazılmıştır."], "sources": [{"title": "TDV İslâm Ansiklopedisi, Ertuğrul Gazi", "url": "https://islamansiklopedisi.org.tr/ertugrul-gazi"}], "aliases": []}, {"id": "osman-i", "name": "Osman Gazi", "title": "Bey, hânedan kurucusu", "claim": false, "birth": null, "birthNote": "Osmanlı rivayeti, 1324'te 69 yaşında ve 27 yıl hükümdar öldüğünü söyler; buna göre doğum 1257 olur. İnalcık bunu rivayet hesabı olarak aktarır, müstakil doğum belgesi yoktur.", "death": 1324, "deathNote": "TDV İnalcık: Asporça Hatun vakfiyesinde 723 Ramazan başları (1323 Eylül) Osman hayattadır; Orhan'ın beyliği Rebîülevvel 724 (1324 Mart) başlar. Ölüm bu aralıktadır, yani 1324. Mekece vakfiyesi (1324 Mart ortası) onu ölmüş gösterir. Geleneksel 1326, Bursa'nın alınışına (1326-04-06) bağlanan sonraki anlatıdır; vakfiye tarihini yutmaz. 1324 ile 1326 çatışması not edilir, tek yıl seçilip diğeri silinmez: belge kolu 1324, popüler fetih kolu 1326.", "reign": [1299, 1324], "reignNote": "Geleneksel başlangıç 1299 (Bilecik-Yenişehir'e kayış ve hutbe iddiası). İnalcık fiilî eşiği 1302-07-27 Bapheus sayar. Beylik fiilen 1324 Mart'ta Orhan'a geçti. Nikris yüzünden son yıllarda işleri Orhan yürüttü (Âşıkpaşazâde, Neşrî).", "summary": "Ertuğrul'un oğlu, Söğüt uç gazisi. İbn Battûta ona Osmancık da der. Pachymeres onu Kastamonu Çobanoğulları'na bağlı ileri hat savaşçısı diye tanıtır. Karacahisar (yaklaşık 1288), Bilecik-Yenişehir (1299 geleneksel) ve Bapheus (1302) ile Bitinya'da karizmatik bey oldu. Amcası Dündar'ı, Bilecik tekfuruna mudârâyı sürdürme görüşüne karşı 1299 civarı okla öldürdüğü Neşrî'de vardır. Bursa'yı alamadı; kuşatma havale kuleleriyle oğluna kaldı. Bursa'da vasiyeti üzere Tophane'de gömüldü; bugünkü türbe 1863'te Abdülaziz döneminde yapıldı.", "traits": ["Pachymeres: uçtaki en atılgan akıncı önderi. Kroniklerde alp yoldaşlarını timar/yurtlukla tutan, fakih ve ahîlere danışan bir bey. Son yıllarda nikris ve yaşlılık."], "contribution": "Söğüt'ten Yenişehir'e kayan çekirdek beyliğin kurulması; Bapheus ile gazilerin onun sancağı altında toplanması; kadı, subaşı ve pazar düzeninin ilk uygulaması; Edebâli ve Dursun Fakih gibi fakihlerle şer'î meşruiyet arayışı. İstimâlet: itaat eden tekfurlara yerinde bırakma (Lefke, Mekece örnekleri).", "harm": "Amcası Dündar'ın öldürülmesi. Akınların Bitinya köylüsünü İstanbul'a kaçırdığı Pachymeres'te dramatik anlatılır; Bapheus sonrası yağma ve esir. Kite tekfurunun teslim sonrası idamı (1303) kroniklerde geçer.", "wives": [{"name": "Mal Hatun bint Ömer Bey", "note": "Mekece vakfiyesi (8-18 Mart 1324) şahitleri arasında. TDV Mal Hatun: Osman'ın çocuğu olan hanımı olması akla yakındır; Şeyh Edebâli'nin kızı değildir. Orhan'ın annesi olup olmadığı kesinlik taşımaz. Âşıkpaşazâde onu Edebâli'nin kızı ve Orhan'ın annesi yapar; bu, vakfiyeyle ve 'kızının adı Râbia' diyen Oruç'la çatışır. Bâlâ Hatun yazımı Mal Hatun istinsahı sayılır.", "certainty": "tartismali"}, {"name": "Şeyh Edebâli'nin kızı (Râbia / menkıbedeki Mal)", "note": "Evlilik ve rüya menkıbesi beyliği kutsar. TDV, Mal Hatun ile Edebâli'nin kızını ayırır. Ayrı bir eş mi, yoksa aynı kadının karıştırılması mı olduğu çözülmüş değildir.", "certainty": "rivayet"}], "children": [{"name": "Orhan", "mother": "Mal Hatun?", "note": "Halef. Annesinin Mal Hatun olduğu kroniklerde kesindir, TDV Mal Hatun maddesi bunu ihtimal sayar.", "certainty": "olasi"}, {"name": "Çoban", "mother": null, "note": "1324 Mekece vakfiyesi şahidi. İnalcık adın İlhanlı emîr Çoban ile ilişkili olabileceğini not eder.", "certainty": "kesin"}, {"name": "Melik", "mother": null, "note": "Aynı vakfiye şahidi.", "certainty": "kesin"}, {"name": "Hamid", "mother": null, "note": "Aynı vakfiye şahidi.", "certainty": "kesin"}, {"name": "Pazarlı (Pazarlu)", "mother": null, "note": "Aynı vakfiye. Orhan maddesinde Pelekanon'da bir kısım kuvveti kardeşi Pazarlu'nun yönettiği yazar.", "certainty": "kesin"}, {"name": "Fatma", "mother": null, "note": "Mekece vakfiyesinde kız olarak adı geçer. İnalcık 'Fatma Melek' diye birleştirir; Mal Hatun maddesi Fatma'yı kız, Melek'i Melik'in kızı diye ayırır. İkinci okuma esas alındı.", "certainty": "olasi"}, {"name": "Alâeddin Ali (Alâeddin Paşa)", "mother": null, "note": "Kroniklerde vezir-oğul diye geçer; 1324 şahit listesinde adı yoktur. Asporça vakfiyesinde Orhan'ın eşi onu vekil tayin eder. Varlığı güçlü gelenektir, vakfiye şahitliği kadar kesin değildir.", "certainty": "olasi"}], "wars": [{"name": "Kulaca baskını", "when": "1285", "foe": "İnegöl tekfuru", "result": "zafer", "note": "Yağma ve hisarın yakılması. Küçük uç çatışması."}, {"name": "İkizce / Domaniç beli", "when": "1286", "foe": "Karacahisar ve İnegöl tekfurları", "result": "zafer", "note": "Kardeşi Saru Yatı öldü. Osman'ın ilk gerçek savaşı sayılır."}, {"name": "Karacahisar", "when": "1288", "foe": "Karacahisar tekfuru", "result": "zafer", "note": "Bölgenin hâkim kalesi. Sancak beyliği iddiası bu fetihe bağlanır."}, {"name": "Bapheus (Koyunhisar)", "when": "1302-07-27", "foe": "Bizans (Muzalon kumandasında)", "result": "zafer", "note": "İznik'i kurtarmaya gelen imparatorluk kuvveti yenildi. İnalcık bu zaferi hânedan kuruluş eşiği sayar."}, {"name": "Dimboz (Dinboz)", "when": "1303", "foe": "Bursa ovası tekfurları ittifakı", "result": "zafer", "note": "Ulubat'a kadar ova açıldı. Bursa abluka altına alındı, şehir düşmedi."}, {"name": "Sakarya seferi", "when": "1304", "foe": "Lefke, Mekece, Geyve tekfurları", "result": "zafer", "note": "Bir kısmı ahidle itaat etti. İznik yolu daraldı."}], "legends": ["Edebâli rüyası ve kılıç kuşanma menkıbesi beyliği kutsar; tarihî evlilik belgesi değildir.", "1299'da kendi adına hutbe okutup Selçuklu'dan koptuğu iddiası sonraki meşruiyet metnidir.", "Kayı'dan Oğuz Han'a inen soy, İnalcık'a göre özellikle Timur-Şâhruh baskısı döneminde (II. Murad çağında) siyasî teoridir. Kayı damgasının kullanılması ayrı bir olgudur; Wittek hânedanın Kayı olmadığı tezini savunur, Köprülü etnik çekirdek der."], "sources": [{"title": "TDV İslâm Ansiklopedisi, Osman Gazi", "url": "https://islamansiklopedisi.org.tr/osman-i"}], "aliases": []}, {"id": "orhan", "name": "Orhan Gazi", "title": "Bey, ikinci Osmanlı hükümdarı", "claim": false, "birth": null, "birthNote": "TDV: doğum tartışmalıdır. 1299'da Nilüfer'le evlendiğinde 'yiğit' denmesinden hareketle o tarihte yaklaşık on sekiz yaşında olabileceği tahmin edilir; bu tahmin evlilik tarihinin kendisi de kronik olduğundan zayıftır.", "death": 1362, "deathNote": "Cemâziyelevvel 763 / Mart 1362, Bursa, veba. 1354'te karaciğer rahatsızlığı ve Rum hekim Taronites kaydı vardır. Türbesi Bursa'da Osman Gazi'nin yanındadır.", "reign": [1324, 1362], "reignNote": "Beyliğe geliş Rebîülevvel 724 / Mart 1324. Ölüm Mart 1362. Edirne'yi oğlu Murad şehzade iken 1361'de aldı; pâyitahtın Edirne'ye yerleşmesi Murad'ın saltanatındadır.", "summary": "Osman'ın oğlu. Bursa'yı 1326'da ahidle aldı, Pelekanon'da (1329) III. Andronikos'u yendi, İznik (1331) ve İzmit'i (1337) teslim aldı. Karesi'yi ilhak etti, Bizans iç savaşında Kantakuzenos'un müttefiki oldu, kızı Theodora ile evlendi. Oğlu Süleyman Paşa Gelibolu yarımadasında tutundu (1352-1354). Ankara ve Sivrihisar 1354'te Osmanlı'ya geçti. 1357'de Süleyman'ın ölümü ve oğlu Halil'in Foça'da tutsaklığı Rumeli'yi bir süre durdurdu.", "traits": ["İbn Battûta: sürekli kaleleri dolaşan, gazâda olan bir bey. İnalcık onu istimâlet ve gazi uç örgütlenmesini birlikte yürüten hükümdar diye anlatır. Oğlu Halil için ağır taviz verecek kadar baba kaygısı taşıdığı Bizans kaynağından çıkar."], "contribution": "Bursa'nın pâyitaht olması, ilk medrese (İznik, Dâvûd-i Kayserî), yaya-müsellem çekirdeği, Karesi donanma geleneğinin devralınması, Rumeli'de kalıcı köprübaşı, Ceneviz'le 1352 kapitülasyonu. Teslim ahidlerinde yağmasız girişi şart koşması (Bursa).", "harm": "Halil'i kurtarmak için Trakya akınlarını durduran 1357-59 antlaşması gazileri zorda bıraktı. Bizans'tan haraç ve toprak tavizi. Theodora evliliği Kantakuzenos'un askerî yardımı içindi; Trakya'nın iç savaşta tahribi her iki tarafın bedelidir. Karesi ilhakında Tursun'un ölümü ve beyliğin sonu.", "wives": [{"name": "Nilüfer (Lülüfer) Hatun", "note": "Kroniklerde Yarhisar tekfurunun kızı, Murad ve Süleyman'ın annesi. TDV Nilüfer maddesi düğün baskını hikâyesini ve 1299 tarihini Bizans kaynağıyla doğrulanmamış sayar; Murad'ın 1326 doğumu bu erken evlilik hikâyesiyle çatışır. İznik'te imareti ve Bursa'da türbede kabri vardır.", "certainty": "olasi"}, {"name": "Asporça Hatun", "note": "1323 tarihli vakfiyesi Osman hayattayken düzenlendi. Oğulları Şerefullah ve İbrahim vakfiyede anılır. III. Andronikos'un kızı olduğu iddiası Nilüfer maddesinde ihtiyatla anılır, kesin değildir.", "certainty": "kesin"}, {"name": "Theodora Kantakuzenos", "note": "1346'da VI. Ioannes Kantakuzenos'un kızı olarak Silivri dışında nikâhlandı. Babası onun Hıristiyan kaldığını ve esir fidyelediğini yazar. Oğlu Halil.", "certainty": "kesin"}], "children": [{"name": "Süleyman Paşa", "mother": "Nilüfer?", "note": "Rumeli geçişinin kumandanı. 1357'de kaza veya suikast sonucu öldü; Bolayır'da gömülmek istediği rivayettir. Oğulları İshak, Melik Nâsır, İsmâil Düstûrnâme'de anılır.", "certainty": "kesin"}, {"name": "Murad", "mother": "Nilüfer", "note": "Halef, I. Murad. TDV Murad maddesi annesini Nilüfer diye yazar.", "certainty": "kesin"}, {"name": "İbrahim", "mother": "Asporça?", "note": "1362'de hayattaydı. Asporça vakfiyesindeki İbrahim ile aynı kişi olması muhtemeldir, kesin özdeşlik not edilir.", "certainty": "olasi"}, {"name": "Halil", "mother": "Theodora", "note": "1357'de Foça'da tutsak edildi, 1359'da fidye ve siyasî tavizle kurtuldu. Bizans, Orhan'dan sonra onu tahta geçirme vaadi aldı; veliahtlık uygulanmadı.", "certainty": "kesin"}, {"name": "Kasım", "mother": null, "note": "Altı oğul listesinde adı geçer.", "certainty": "olasi"}, {"name": "Sultan", "mother": null, "note": "Altı oğul listesinde (Süleyman, Sultan, Murad, İbrahim, Halil, Kasım). 1362'de hayatta olanlar Murad, İbrahim ve Halil'dir.", "certainty": "olasi"}, {"name": "Şerefullah", "mother": "Asporça", "note": "Asporça vakfiyesinde oğul.", "certainty": "kesin"}], "wars": [{"name": "Bursa teslimi", "when": "1326-04-06", "foe": "Bursa tekfuru", "result": "zafer", "note": "Ahid: yağma ve esir yok, gidecek olan serbest, 30.000 altın. 2 Cemâziyelevvel 726."}, {"name": "Pelekanon", "when": "1329-06", "foe": "Bizans, III. Andronikos", "result": "zafer", "note": "İmparator yaralandı, İstanbul'a çekildi. Kocaeli Osmanlı'da kaldı."}, {"name": "İznik", "when": "1331-03-02", "foe": "Bizans", "result": "zafer", "note": "İbn Kemal 1333 der; İnalcık 2 Mart 1331'i esas alır."}, {"name": "İzmit", "when": "1337", "foe": "Bizans", "result": "antlasma", "note": "1333'te haraç karşılığı kuşatma kalkmıştı; 1337'de şehir teslim oldu."}, {"name": "Karesi ilhakı", "when": "1334-1345", "foe": "Karesi Beyliği", "result": "zafer", "note": "Tursun'un davetiyle. Bergama ve Balıkesir hattı. Tam yıl tartışmalıdır; Osmanlılar maddesi 1334-1345 der."}, {"name": "Gelibolu ve Çimbi", "when": "1352-1354", "foe": "Bizans", "result": "zafer", "note": "1354 depremiyle Gelibolu düştü. Kantakuzenos'un Tzympe'yi geçici verdiği anlatısı eksiktir; Bolayır köprübaşı belirleyicidir."}, {"name": "Sırp-Bulgar kuvvetleri (Empithion)", "when": "1352", "foe": "Sırp ve Bulgar yardımcıları", "result": "zafer", "note": "Süleyman Paşa, Kantakuzenos'un oğlu lehine Meriç'te yendi."}], "legends": ["Rumeli'ye öküz derisi ve sal hikâyesi Âşıkpaşazâde'dedir; İnalcık bunu Düstûrnâme'deki tarihî geçişin folklorik biçimi sayar.", "Nilüfer'in Bilecik düğününden kaçırılması kuruluş menkıbesidir."], "sources": [{"title": "TDV İslâm Ansiklopedisi, Orhan Gazi", "url": "https://islamansiklopedisi.org.tr/orhan"}], "aliases": []}, {"id": "murad-i", "name": "I. Murad", "title": "Sultan, Hüdâvendigâr", "claim": false, "birth": 1326, "birthNote": "TDV: 726 (1326). Bazı kayıtlar 1326-1327. Annesi Nilüfer. Gün-ay verilmez.", "death": 1389, "deathNote": "Kosova meydanında 1389. Savaş 15 Haziran 1389'da kazanıldı (Bayezid maddesi bu tarihi şehzadenin rolü için verir). Gazânâme'ye göre Murad birkaç hasekisiyle dolaşırken öldürüldü. Haber İstanbul'da sevinçle karşılandı.", "reign": [1362, 1389], "reignNote": "Babasının ölümü 1362. Edirne'yi şehzadeyken 1361'de Lala Şâhin ile aldığı İnalcık tezidir; literatürde 1363-1371 tarihleri de öne sürülür. Pâyitaht Edirne'ye kaydı.", "summary": "Orhan'ın oğlu, annesi Nilüfer. Rumeli'de üç koldan yayılma, Edirne, Çirmen (1371) ve Kosova (1389) ile Balkan vasallığını kurdu. Anadolu'da Hamîdoğulları, Germiyan çeyizi ve Karamanoğlu ile mücadele etti. Kosova'da zafer kazanıldığı gün öldürüldü. Kardeşi değil oğlu Yâkub, Bayezid tarafından öldürtüldü.", "traits": ["Seferi bizzat yöneten gazi hükümdar tipi. İnalcık onu devletleşme (beylerbeyilik, timar, pençik) eşiği sayar."], "contribution": "Edirne'nin başkentleşmesi, Rumeli beylerbeyiliği (Lala Şâhin), Çirmen sonrası Bizans, Bulgar ve Makedon Sırp beylerinin bağlanması, istimâletle iskân. Kapıkulu çekirdeğinin gelişmesi.", "harm": "Kosova'da Sırp knezi Lazar'ın idamı ve Balkan ittifakının kanlı dağılışı. Anadolu beylik topraklarının ilhakı yerel hânedanlarda Timur'a kadar sürecek intikam biriktirdi. Oğlu Yâkub'un katli sonraki kardeş katlinin erken örneğidir (babasının emri değil, Bayezid ve erkân).", "wives": [{"name": "Nilüfer Hatun", "note": "Annesi değil eşi sanılmasın: Nilüfer annesidir. Eş olarak Gülçiçek Hatun Bayezid'in annesi diye Bayezid maddesinde geçer.", "certainty": "kesin"}, {"name": "Gülçiçek Hatun", "note": "I. Bayezid'in annesi. TDV Bayezid maddesi.", "certainty": "kesin"}], "children": [{"name": "Bayezid", "mother": "Gülçiçek Hatun", "note": "Halef. Kosova'da sağ kolu tuttu, Yıldırım lakabını daha önce Frenk Yazısı'nda almıştı.", "certainty": "kesin"}, {"name": "Yâkub", "mother": null, "note": "Kosova sonrası, iç savaşı önlemek gerekçesiyle Bayezid tarafından öldürtüldü. Hayattaki tek kardeş diye anılır.", "certainty": "kesin"}, {"name": "Savcı", "mother": null, "note": "Bizans'la birlikte isyan ettiği ve gözlerine mil çekildiği kroniklerde geçer. Bu okumada Murad maddesinin özeti ismi ayrıntılandırmadı; oğul listesine ihtiyatla kondu, ayrı savaş anlatısı şişirilmedi.", "certainty": "olasi"}], "wars": [{"name": "Çirmen (Meriç)", "when": "1371", "foe": "Sırp despotları Vukaşin ve Ugljeşa", "result": "zafer", "note": "TDV Osmanlılar: Makedonya'daki Sırp beyleri, Bizans ve Bulgar kralı bağlandı."}, {"name": "Frenk Yazısı", "when": "1386", "foe": "Karamanoğlu Alâeddin", "result": "zafer", "note": "Şehzade Bayezid'in Yıldırım lakabı bu savaştaki atılganlığına bağlanır."}, {"name": "Kosova", "when": "1389-06-15", "foe": "Lazar önderliğinde Sırp-Boşnak-yardımcı ittifakı", "result": "zafer", "note": "Osmanlı zaferi, sultan savaş alanında öldü. Lazar idam edildi. Kuzey Sırbistan yolu açıldı, Sırp despotluğu vasal oldu."}], "legends": ["Miloş Obiliç'in çadırda hançerlemesi popüler anlatıdır. TDV Murad maddesi Gazânâme'ye dayanarak meydanda öldürüldüğünü yazar; suikastçının adı bu okunan pasajda kesinlenmedi.", "Edirne fetih yılı (1361 mi, daha geç mi) literatürde çatışmalıdır; İnalcık 1361'i şehzadelik fethi sayar."], "sources": [{"title": "TDV İslâm Ansiklopedisi, I. Murad", "url": "https://islamansiklopedisi.org.tr/murad-i"}], "aliases": []}, {"id": "bayezid-i", "name": "I. Bayezid", "title": "Sultan, Yıldırım", "claim": false, "birth": 1354, "birthNote": "755 (1354). Gün verilmez. Annesi Gülçiçek Hatun. Babası I. Murad.", "death": 1403, "deathNote": "Ankara'da 1402'de esir edildi. TDV Bayezid maddesi: esaret altında Akşehir'de 8 Mart 1403 vefat. 1402 esaret ile 1403 Mart ölümü ayrı tutulur.", "reign": [1389, 1402], "reignNote": "Kosova'da babasının ölümüyle 1389'da tahta çıktı. Fiilî saltanat Ankara bozgunu 28 Temmuz 1402'de bitti. Ölüm 1403'tür; bazı listeler saltanatı 1403'e kadar uzatır. Burada saltanat sonu esaret, ölüm yılı ayrıca yazıldı.", "summary": "I. Murad'ın büyük oğlu. 1381 dolayında Germiyanoğlu Süleyman Şah'ın kızı Sultan Hatun ile evlendi, çeyiz topraklarına Kütahya sancakbeyi oldu. Anadolu beyliklerini sancaklaştırdı, Niğbolu'da Haçlı ordusunu yendi, İstanbul'u abluka etti. Timur'la 28 Temmuz 1402 Çubuk ovasında yenildi, esir düştü, 8 Mart 1403'te Akşehir'de öldü. Anadolu birliği dağıldı, oğulları fetret'e girdi.", "traits": ["TDV: son derece cesur, faal, yetenekli ve âdil; sert mizaç. Hayatı savaşla geçmiş bir merkezîleştirici."], "contribution": "Anadolu'da beyliklerin Osmanlı sancağına çevrilmesi, Niğbolu ile Haçlı akınının kırılması, Bursa Ulucamii (1400), Anadoluhisarı (1396-97), imaret ve dârüşşifâlar. Rumeli bütünlüğü bozulmadığı için fetretten dönüş mümkün oldu.", "harm": "Ankara bozgunu merkezî devleti çökertti; beylikler Timur yarlığıyla geri geldi. Kardeşi Yâkub'u saltanat başında öldürttü. İstanbul ablukası ve vasallere sertlik, Timur'a karşı Anadolu beylerinin düşmanlığını büyüttü. Esaret devletin itibarını sarstı.", "wives": [{"name": "Sultan Hatun", "note": "Germiyan Beyi Süleyman Şah'ın kızı. Yaklaşık 1381 evlilik. İsa Çelebi'nin annesi TDV İsa maddesinde odur.", "certainty": "kesin"}, {"name": "Olivera (Maria Despina)", "note": "Sırp knezi Lazar'ın kızı. Kosova sonrası Stefan Lazareviç ile yapılan antlaşmanın evlilik bağı. Sırp yardımcı kuvveti bu bağa dayanır.", "certainty": "kesin"}, {"name": "Devlet Hatun", "note": "I. Mehmed'in annesi. TDV Mehmed maddesi onu câriye diye anar.", "certainty": "kesin"}], "children": [{"name": "Ertuğrul", "mother": null, "note": "Süleyman Çelebi'den önce doğan büyük oğul diye anılır. Ankara'dan önce ölmüştür (yaklaşık 1400).", "certainty": "olasi"}, {"name": "Süleyman", "mother": null, "note": "Fetret'te Rumeli'de hükümdarlık ilan etti. Padişah sayımına girmez.", "certainty": "kesin"}, {"name": "İsa", "mother": "Sultan Hatun", "note": "Fetret talibi. Germiyan prensesinden.", "certainty": "kesin"}, {"name": "Musa", "mother": null, "note": "En küçük oğul diye Musa maddesi. Fetret talibi.", "certainty": "kesin"}, {"name": "Mehmed", "mother": "Devlet Hatun", "note": "Dördüncü oğul. Fetret talibi ve sonra I. Mehmed.", "certainty": "kesin"}, {"name": "Mustafa", "mother": null, "note": "Ankara'da Timur'a esir düşüp Semerkant'a götürüldüğü Enverî'de vardır. Sonra 'Düzmece' tartışmasıyla ortaya çıktı. Bu kartta ayrı hükümdar değildir.", "certainty": "olasi"}, {"name": "Kasım", "mother": null, "note": "En küçük oğul. Süleyman onu Bizans'a rehin bıraktı.", "certainty": "kesin"}, {"name": "Fatma Sultan", "mother": null, "note": "Fetret maddesi: Süleyman onu Kasım ile İstanbul'da rehin bıraktı.", "certainty": "olasi"}], "wars": [{"name": "Kosova", "when": "1389-06-15", "foe": "Sırp ittifakı", "result": "zafer", "note": "Şehzade olarak sağ kol. Babasının ölümü üzerine taht."}, {"name": "Anadolu beylikleri seferi", "when": "1390", "foe": "Germiyan, Aydın, Saruhan, Menteşe, ardından Karamanoğlu", "result": "antlasma", "note": "Batı beylikleri ilhak. Karamanoğlu ile Çarşamba suyu sınır, Beyşehir Osmanlı'da kaldı."}, {"name": "Niğbolu", "when": "1396", "foe": "Macar kralı Sigismund önderliğinde Haçlı ordusu", "result": "zafer", "note": "TDV Osmanlılar: son Haçlılar ağır yenilgi. Bulgar krallığı ortadan kalktı."}, {"name": "Ankara (Çubuk ovası)", "when": "1402-07-28", "foe": "Timur", "result": "yenilgi", "note": "Bayezid esir. Anadolu beylikleri iade edildi. TDV Ankara Savaşı ve Bayezid maddeleri."}], "legends": ["Timur'un onu kafeste gezdirmesi popüler anlatıdır; TDV Bayezid maddesinin okunan kısmı esaret ve 8 Mart 1403 Akşehir ölümünü verir, kafes ayrıntısını olgu diye kurmaz."], "sources": [{"title": "TDV İslâm Ansiklopedisi, I. Bayezid", "url": "https://islamansiklopedisi.org.tr/bayezid-i"}], "aliases": []}, {"id": "suleyman-celebi", "name": "Süleyman Çelebi (Emîr)", "title": "Fetret talibi; bazı Batı kaynaklarında I. Süleyman", "claim": true, "birth": null, "birthNote": "Doğum yılı verilmez. Yıldırım'ın Ertuğrul'dan sonraki oğlu. İlk kayıt 1389-90 Batı Anadolu seferi sonrası Aydın ilinin idarecisidir.", "death": 1411, "deathNote": "22 Şevval 813 / 17 Şubat 1411. Musa Edirne'yi bastı. Kaçan Süleyman Düğüncü köyünde yakalanıp katledildi. Naaşı Bursa'da I. Murad türbesi yanına gönderildi.", "reign": [1403, 1411], "reignNote": "Padişah sayımına girmez (36'nın dışındadır). Ankara sonrası hazneyi alıp Rumeli'ye geçti. Gelibolu Antlaşması Şubat 1403; ardından Edirne'de hükümdarlığını ilan etti. TDV: modern literatür onu padişahlar arasına koymaz; bazı Osmanlı, Bizans ve Batı kaynakları meşrû hükümdar sayar.", "summary": "Rumeli'yi ve Edirne'yi elinde tuttu. Bizans'a Selânik, Tesalya ve Anadolu yakasında bazı yerleri bırakıp vergiyi kaldırdı (1403). Venedik ve Ceneviz'e imtiyaz verdi. Anadolu'da İsa ve Mehmed ile mücadele etti. 1410'da Musa'yı iki kez yendi, 17 Şubat 1411'de Edirne baskınında öldürüldü.", "traits": ["TDV, Venediklilerin 1406'da onu 'Türkler'in sultanı' diye andığını nakleder. Fetret hükümdarlığı toprak tavizi ve ittifak üzerine kuruludur."], "contribution": "Rumeli'nin dağılmaması fetretten dönüşün maddi şartıdır. Edirne Eski Cami'nin yapımını başlattı, I. Mehmed tamamladı.", "harm": "1403 Gelibolu Antlaşmasıyla Bizans'a geniş toprak ve vergi muafiyeti verdi. Kardeş kavgası Anadolu'yu parçaladı.", "wives": [], "children": [{"name": "Orhan", "mother": null, "note": "TDV: 1395-1429 arasında yaşadı. Musa ve sonra Bizans onu rakip şehzade olarak kullandı. I. Mehmed döneminde kör edilip zindana konduğu Mehmed maddesinde geçer.", "certainty": "kesin"}], "wars": [{"name": "Gelibolu Antlaşması", "when": "1403-02", "foe": "Bizans", "result": "antlasma", "note": "Toprak ve vergi tavizi karşılığı Rumeli'de tanınma."}, {"name": "Yanbolu", "when": "1410-02-13", "foe": "Musa Çelebi", "result": "yenilgi", "note": "İlk karşılaşma."}, {"name": "Musa'ya karşı iki savaş", "when": "1410-06", "foe": "Musa Çelebi", "result": "zafer", "note": "Haziran 1410'a kadar iki yenilgi verdirdi."}, {"name": "Edirne baskını", "when": "1411-02-17", "foe": "Musa Çelebi", "result": "yenilgi", "note": "Öldürüldü."}], "legends": ["Batı literatüründe I. Süleyman sayılması, klasik 36 padişah sayımına aykırıdır. Bu atlas da onu talip (claim true) sayar, 36'ya katmaz."], "sources": [{"title": "TDV İslâm Ansiklopedisi, Süleyman Çelebi (Emîr)", "url": "https://islamansiklopedisi.org.tr/suleyman-celebi"}], "aliases": []}, {"id": "isa-celebi", "name": "İsa Çelebi", "title": "Fetret talibi", "claim": true, "birth": null, "birthNote": "Doğum ve ilk yıllar bilinmez. Yıldırım'ın adı bilinen yedi erkek çocuğunun üçüncüsü. Annesi Germiyan prensesi Sultan Hatun.", "death": 1404, "deathNote": "TDV (Nezihi Aykut, kronik kolu): Mehmed Çelebi'nin adamları onu Eskişehir'de bir hamamda yakalayıp yay kirişiyle boğdurttu. Yıl 806/1403-1404. Elizabeth Zachariadou ise 1403'te Süleyman tarafından öldürüldüğünü yazar. TDV İsa maddesi her iki ihtimali de anar; tek yıl yutulmaz.", "reign": [1403, 1404], "reignNote": "Padişah sayımına girmez. Timur'dan Karesi menşuru aldı, Bursa'yı tutup 1403 Ocak'ta Anadolu'da saltanat ilan etti, Venedik ve Bizans'la antlaştı. Mehmed Bursa'yı alınca Kastamonu ve İzmir'e sığındı.", "summary": "Ankara sonrası Anadolu'da ilk saltanat iddiasını Mehmed ile paylaşan şehzade. Bursa'da tutunamadı. Bizanslı Ioannes Tonteres'in kızıyla evlendiği Hammer üzerinden nakledilir.", "traits": ["Kısa süreli talip. Siyasî portresi kronik düşmanlığıyla çizilir."], "contribution": "Müstakil kurum veya imar bırakmadı. Fetretin Anadolu safhasının parçasıdır.", "harm": "Kardeş savaşı Bursa ve Batı Anadolu'yu tahrip etti. Yenilgileri müttefik beyleri Mehmed'e mecbur bıraktı.", "wives": [{"name": "Ioannes Tonteres'in kızı", "note": "Hammer, II, 93 üzerinden TDV'de geçer. Bizans ailesiyle antlaşma evliliği.", "certainty": "olasi"}], "children": [], "wars": [{"name": "Bursa mücadelesi", "when": "1403", "foe": "Mehmed Çelebi", "result": "yenilgi", "note": "Sarı Timurtaş Paşa Mehmed tarafından öldürüldü."}, {"name": "Gerede", "when": "1403-1404", "foe": "Mehmed Çelebi", "result": "yenilgi", "note": "İsfendiyar ile birlikte tutunamadı."}, {"name": "Eskişehir'de yakalanma", "when": "1403 veya 1404", "foe": "Mehmed Çelebi", "result": "yenilgi", "note": "Boğduruldu. Katilin kim olduğu (Mehmed'in adamları mı, Süleyman mı) çatışmalıdır."}], "legends": [], "sources": [{"title": "TDV İslâm Ansiklopedisi, İsa Çelebi", "url": "https://islamansiklopedisi.org.tr/isa-celebi"}], "aliases": []}, {"id": "musa-celebi", "name": "Musa Çelebi", "title": "Fetret talibi", "claim": true, "birth": null, "birthNote": "Doğum yılı yok. TDV: Yıldırım'ın en küçük oğlu.", "death": 1413, "deathNote": "5 Rebîülâhir 816 / 5 Temmuz 1413. Çamurlu/Sofya civarında yenildi, Eflak'a kaçarken yakalanıp boğduruldu. Naaşı Bursa'da babasının türbesine kondu.", "reign": [1411, 1413], "reignNote": "Padişah sayımına girmez. Timur esaretinden dönüp önce Anadolu'da İsa ile uğraştı. Mehmed onu Süleyman'a karşı Rumeli'ye gönderdi. 17 Şubat 1411'de Edirne'yi alıp hükümdarlığını ilan etti. 5 Temmuz 1413'te Mehmed'e yenildi.", "summary": "Edirne'de Şeyh Bedreddin'i kazasker, Mihaloğlu Mehmed'i beylerbeyi yaptı. Sırp despotu ve Bizans'a karşı sertleşince uç beyleri Mehmed tarafına geçti. 1413'te son savaşı kaybetti.", "traits": ["Akıncı kökenli, Rumeli beylerini önce toplayıp sonra kaçıran sert bir talip."], "contribution": "Süleyman'ın Bizans'a bıraktığı bazı tavizleri geri çevirme teşebbüsü. Bedreddin'in kazaskerliği fetret siyasetinin dinî kanadını görünür kılar.", "harm": "Edirne baskını ve Süleyman'ın öldürülmesi. Sırp topraklarının yağmalanması. Beylerin kaçışı Rumeli'yi Mehmed'e açtı.", "wives": [], "children": [], "wars": [{"name": "Ankara", "when": "1402-07-28", "foe": "Timur", "result": "yenilgi", "note": "Babasıyla esir düştü, sonra serbest bırakıldı."}, {"name": "Edirne'nin alınması", "when": "1411-02-17", "foe": "Süleyman Çelebi", "result": "zafer", "note": "Hükümdarlığını ilan etti."}, {"name": "Çamurlu", "when": "1413-07-05", "foe": "Mehmed Çelebi", "result": "yenilgi", "note": "Yakalanıp boğduruldu. Fetret fiilen kapandı."}], "legends": [], "sources": [{"title": "TDV İslâm Ansiklopedisi, Musa Çelebi", "url": "https://islamansiklopedisi.org.tr/musa-celebi"}], "aliases": []}, {"id": "mehmed-i", "name": "I. Mehmed", "title": "Sultan, Çelebi", "claim": false, "birth": 1386, "birthNote": "788 (1386) veya 789 (1387). Gün yok. I. Bayezid'in Devlet Hatun adlı câriyesinden dördüncü oğlu. 'Çelebi' ve 'Kirişçi' lakapları.", "death": 1421, "deathNote": "23 Cemâziyelâhir 824 / 25 Haziran 1421, Edirne. Oğlu Murad Bursa'da tahta çıktı.", "reign": [1413, 1421], "reignNote": "Fetret talibi olarak 1402-1413'te Tokat, Amasya ve zaman zaman Bursa'ya hâkimdi. Tek hükümdarlık 5 Temmuz 1413'te Musa'nın ölümünden 25 Haziran 1421'e kadardır. 36 sayımında bir kez yazılır; ayrı talip kartı açılmaz. Klasik sırada I. Mehmed odur.", "summary": "Amasya valisiyken Ankara'dan sonra Anadolu'da tutundu, İsa'yı ve sonunda Musa'yı eledi. Timurlulara karşı ihtiyatlıydı, Bizans ve Venedik'e yumuşak davrandı. Şeyh Bedreddin ve Börklüce isyanları, Düzmece Mustafa'nın ortaya çıkışı saltanatının son buhranıdır. Ölürken Murad'ın sorunsuz geçmesini istedi; küçük oğulları Yûsuf ve Mahmud'u Bizans'a rehin verme tasarısı Murad tarafından uygulanmadı.", "traits": ["İnalcık onu toparlayıcı, timarı yaygınlaştıran, vasallere ölçülü bir sultan diye anlatır. Hastalığında veraseti oğlunun lehine kilitlemeye çalıştı."], "contribution": "Fetretin kapanması, timar ve tahririn geliştirilmesi, Bursa'da cami (1419), medrese, imaret ve türbe, Edirne Eski Cami'nin tamamlanması (1414) ve bedesten.", "harm": "Kardeşlerin boğdurulması fetretin bedelidir. Mustafa'yı 'düzmece' diye damgalayan propaganda sonraki iç savaşı çözmedi. Rehin şehzade tasarısı Bizans'a koz bırakıyordu.", "wives": [{"name": "Adı belirtilmeyen câriye", "note": "II. Murad'ın annesi TDV'de 'bir câriyeden olma' diye geçer. Hüseyin Hüsâmeddin Amasya Tarihi onu Divitdâr Ahmed Paşa'nın kızı Şehzade Hatun diye yazar. Çatışma not edilir, tek ad yutulmaz.", "certainty": "tartismali"}], "children": [{"name": "Murad", "mother": "câriye veya Şehzade Hatun", "note": "Halef. Amasya'da Haziran 1404 doğumu.", "certainty": "kesin"}, {"name": "Mustafa", "mother": null, "note": "Anadolu'da bırakılması tasarlanan oğul. Sonra II. Murad'a rakip oldu.", "certainty": "kesin"}, {"name": "Kasım", "mother": null, "note": "Altı oğul listesinde.", "certainty": "kesin"}, {"name": "Ahmed", "mother": null, "note": "Aynı liste.", "certainty": "kesin"}, {"name": "Yûsuf", "mother": null, "note": "1421'de sekiz yaşında. Bizans'a rehin tasarısı.", "certainty": "kesin"}, {"name": "Mahmud", "mother": null, "note": "1421'de yedi yaşında. Aynı tasarının parçası.", "certainty": "kesin"}, {"name": "Yedi kız", "mother": null, "note": "TDV: yedi kızı olduğu bilinir, adları bu maddede sayılmaz. Adsız yedi isim uydurulmadı.", "certainty": "olasi"}], "wars": [{"name": "İsa Çelebi mücadelesi", "when": "1403-1404", "foe": "İsa Çelebi", "result": "zafer", "note": "Bursa ve Anadolu'da üstünlük."}, {"name": "Musa'ya karşı son sefer", "when": "1413", "foe": "Musa Çelebi", "result": "zafer", "note": "5 Temmuz 1413 Musa boğduruldu. Edirne'de tek hükümdarlığını ilan etti."}, {"name": "Şeyh Bedreddin ve Börklüce", "when": "1416", "foe": "Bedreddinîler", "result": "zafer", "note": "Osmanlılar maddesi ve Murad biyografisi bu isyanı I. Mehmed sonuna koyar."}, {"name": "Düzmece Mustafa", "when": "1416-1421", "foe": "Mustafa Çelebi", "result": "sonucsuz", "note": "Bizans Mustafa'yı tuttu. Mehmed ölünce sorun Murad'a kaldı."}], "legends": ["Kirişçi lakabının Yunanca krytsez'den geldiği İnalcık'ın etimoloji notudur."], "sources": [{"title": "TDV İslâm Ansiklopedisi, I. Mehmed", "url": "https://islamansiklopedisi.org.tr/mehmed-i"}], "aliases": []}, {"id": "murad-ii", "name": "II. Murad", "title": "Sultan", "claim": false, "birth": 1404, "birthNote": "Zilhicce 806 / Haziran 1404, Amasya. Gün yok. Annesi: TDV ana metin bir câriye der; Hüseyin Hüsâmeddin, Amasya âyanından Divitdâr Ahmed Paşa'nın kızı Şehzade Hatun der.", "death": 1451, "deathNote": "1 Muharrem 855 / 3 Şubat 1451, hastalık. Edirne. Vasiyetinde Bursa'da oğlu Ali'nin yanına gömülmeyi istedi.", "reign": [1421, 1451], "reignNote": "İki saltanat, tek kart. Babasının ölümüyle 1421. 1444'te tahtı oğlu Mehmed'e bıraktı. Varna buhranında geri çağrıldı, 1446'da tekrar tahta çıktı, 1451'e kadar oturdu. Oğlu Mehmed'in ilk saltanatı 1444-1446'dır.", "summary": "Fetret artığı Mustafa tehlikesini, İstanbul kuşatması teşebbüsünü ve Anadolu beylerini yönetti. 1444 Varna ve 1448 II. Kosova, Osmanlılar'ın Balkanlar'dan atılamayacağını gösterdi. 1440 Belgrad kuşatması başarısızdı. Tahttan çekilip dönmesi oğluyla gerilim yarattı. Türkçe kültüre ve Oğuz töresine ağırlık verilen bir toparlanma padişahıdır.", "traits": ["İnalcık ve Emecen: dedesi ve oğlu kadar fütuhatçı olmayan, denge arayan bir sultan. Tahtı oğluna bırakıp geri alması kararsızlık değil, Haçlı buhranına tepkidir."], "contribution": "Varna ve II. Kosova ile Balkan tutunuşunun kesinleşmesi, Selânik'in 1430'da yeniden alınması, Edirne'de imar ve Türkî kültür hamlesi. Şâhruh karşısında Oğuz-Kayı meşruiyetinin siyaseten öne çıkarılması.", "harm": "1444 Segedin-Edirne barışının hemen bozulması Haçlı seferini geri getirdi. Belgrad 1440 başarısızlığı. Oğlunu 1446'da fiilen ikinci plana itmesi II. Mehmed'in ilk saltanatını gölgeledi. Kardeşleri konusunda I. Mehmed'in koruma tasarısını uygulamadı.", "wives": [{"name": "Adı bu okumada tek tek sayılmayan hasekiler", "note": "Oğlu Mehmed'in Dulkadıroğlu Süleyman Bey'in kızı Sitti Hatun ile 1450 evliliği şehzade düğünüdür, Murad'ın eşi değildir.", "certainty": "tartismali"}], "children": [{"name": "Mehmed", "mother": "Hümâ Hatun", "note": "Halef, II. Mehmed. Doğum 30 Mart 1432 Edirne. Annesi TDV vâlide sultan listesinde Hümâ Hatun'dur.", "certainty": "kesin"}, {"name": "Alâeddin Ali", "mother": null, "note": "Amasya valisi. 1443'te öldü. Murad vasiyetinde onun kabrinin yanını ister.", "certainty": "kesin"}, {"name": "Ahmed", "mother": null, "note": "II. Mehmed tahta çıkınca henüz memede olan kardeşini boğdurdu. Murad'ın küçük oğludur.", "certainty": "kesin"}, {"name": "Diğer kardeşler", "mother": null, "note": "Murad, Çelebi Mehmed'in en büyük oğlu olup dört erkek ve yedi kız kardeşi vardı; bunlar Murad'ın kardeşleridir, çocukları değildir.", "certainty": "kesin"}], "wars": [{"name": "Düzmece Mustafa", "when": "1421-1422", "foe": "Mustafa Çelebi ve Bizans desteği", "result": "zafer", "note": "Mustafa bertaraf edildi. Ardından İstanbul kuşatması sonuçsuz kaldı."}, {"name": "Belgrad kuşatması", "when": "1440", "foe": "Macaristan", "result": "yenilgi", "note": "TDV Osmanlılar: mağlûbiyet ve geri çekilme."}, {"name": "Varna", "when": "1444", "foe": "Macar kralı, Hunyadi", "result": "zafer", "note": "Haçlı ordusu dağıldı. Murad sefere oğlu tahttayken çağrıldı."}, {"name": "II. Kosova", "when": "1448", "foe": "Hunyadi", "result": "zafer", "note": "Balkanlar'dan atılma ihtimali kapandı."}], "legends": [], "sources": [{"title": "TDV İslâm Ansiklopedisi, II. Murad", "url": "https://islamansiklopedisi.org.tr/murad-ii"}], "aliases": []}, {"id": "mehmed-ii", "name": "II. Mehmed", "title": "Sultan, Fâtih, Ebü'l-feth", "claim": false, "birth": 1432, "birthNote": "27 Receb 835 / 30 Mart 1432, Edirne. II. Murad'ın oğlu. Annesi TDV vâlide sultan listesinde Hümâ Hatun'dur. Altı yaşında Amasya valiliği iddiası şüphelidir; 1443'te Manisa'ya gönderildiği bilinir.", "death": 1481, "deathNote": "4 Rebîülevvel 886 / 3 Mayıs 1481, Üsküdar-Gebze arasında Hünkârçayırı (Maltepe civarı), yeni sefere çıkarken. Ani ölüm. Otranto köprübaşı bu ölümle sonuçsuz kaldı.", "reign": [1444, 1481], "reignNote": "İki saltanat, tek kart. İlki: babasının 1444 çekilmesi, Varna buhranı, 1446'da babasının dönüşü. İkincisi: 3 Şubat 1451'den 3 Mayıs 1481'e. Klasik 36 sayımında bir kişidir.", "summary": "İstanbul'u 1453'te aldı, pâyitaht yaptı. Sırbistan, Mora, Bosna, Trabzon ve Karamanoğulları'nı ortadan kaldırdı; Kırım'ı himayeye aldı; Otlukbeli'nde Uzun Hasan'ı yendi. 1480'de Otranto'ya çıkıldı. Merkezî kapıkulu, kanunname ve İstanbul imarı onun saltanatına bağlanır. Tahta çıkar çıkmaz küçük kardeşi Ahmed'i boğdurdu. 'Nizâm-ı âlem için karındaşlarını katletmek câizdir' hükmü Fâtih Kanunnâmesi'ne atfedilir; metnin yazılış tarihi tartışmalıdır.", "traits": ["Cihanşümul unvanlar: han, sultan, kayser. İtalyan hümanistlerini sarayında tuttu, Batlamyus haritası yaptırdı. Sert, merkezî, fütuhatçı. İlk saltanatında Çandarlı çevresi onu çocuk hükümdar gibi gördü."], "contribution": "İstanbul'un fethi ve iskânı, Ayasofya'nın camiye çevrilmesi, yeni saray, kanunname ile merkezî teşrifat, Kapalıçarşı ve külliyeler, Karadeniz'in güney kapısının kapanması, Otlukbeli ile Akkoyunlu tehdidinin kırılması.", "harm": "Kardeş Ahmed'in bebekken boğdurulması ve kardeş katlinin kanunnâme hükmü haline gelmesi. Belgrad 1456 başarısızlığı. Savaş finansmanı, tağşiş ve yeni vergiler ulemâ ile halkta muhalefet biriktirdi; bu tepki II. Bayezid devrinde geri alındı. Otranto çıkarması ölümle birlikte boş kaldı. Oğulları Bayezid-Cem kavgası devleti dış şantaja açtı.", "wives": [{"name": "Sitti Hatun", "note": "Dulkadıroğlu Süleyman Bey'in kızı. Şevval-Zilkade 854 / Kasım-Aralık 1450 Edirne düğünü. Mehmed henüz şehzadeydi.", "certainty": "kesin"}, {"name": "Gülbahar Hatun", "note": "II. Bayezid'in annesi. TDV Bayezid maddesi. Haseki/hatun statüsü valide sultan listesiyle uyumludur.", "certainty": "kesin"}, {"name": "Diğer eşler", "note": "Alderson 17 hanım sayar. TDV Mehmed maddesi bu listeyi tekrarlamaz. Adı açılmayan eşler buraya yazılmadı.", "certainty": "tartismali"}], "children": [{"name": "Bayezid", "mother": "Gülbahar Hatun", "note": "Halef. 1448 Dimetoka doğumu.", "certainty": "kesin"}, {"name": "Mustafa", "mother": null, "note": "879/1474'te babasından önce öldü.", "certainty": "kesin"}, {"name": "Cem", "mother": null, "note": "1481'de taht iddiası, yenilgi, Rodos ve Avrupa esareti, 1495'te muhtemelen zehirlenerek öldü.", "certainty": "kesin"}, {"name": "Ayşe", "mother": null, "note": "TDV'nin adını verdiği iki kızdan biri.", "certainty": "kesin"}, {"name": "Gevherhan", "mother": null, "note": "TDV'nin adını verdiği ikinci kız. Alderson dört kız der; diğer iki ad bu okumada geçmedi.", "certainty": "kesin"}], "wars": [{"name": "Varna", "when": "1444", "foe": "Haçlı / Hunyadi", "result": "zafer", "note": "İlk saltanatında baba seferi yönetti. Sonuç Osmanlı lehine."}, {"name": "İstanbul", "when": "1453", "foe": "Bizans", "result": "zafer", "note": "Şehir savaşla alındı. Pâyitaht oldu."}, {"name": "Belgrad", "when": "1456", "foe": "Macaristan (Hunyadi)", "result": "yenilgi", "note": "Şahsî kahramanlığına rağmen çekildi."}, {"name": "Trabzon", "when": "1461", "foe": "Trabzon Rum İmparatorluğu", "result": "zafer", "note": "Devlet sona erdi."}, {"name": "Otlukbeli", "when": "1473", "foe": "Akkoyunlu Uzun Hasan", "result": "zafer", "note": "Anadolu'da Timur artığı rakip kırıldı."}, {"name": "Otranto", "when": "1480-1481", "foe": "Napoli krallığı", "result": "sonucsuz", "note": "Köprübaşı tutuldu, padişahın ölümüyle boşaltıldı."}], "legends": ["Fâtih Kanunnâmesi'ndeki kardeş katli maddesinin bizzat Fâtih elinden ve hangi yılda çıktığı tartışmalıdır. TDV katl maddesi hükmü anar ve fıkha uygunluğunun geniş tartışma konusu olduğunu söyler. Uygulama kanunnâmeden öncedir: I. Bayezid Yâkub'u, II. Mehmed kardeşi Ahmed'i öldürttü.", "Ayasofya'da ezan ve kehanet menkıbeleri fetih edebiyatıdır; fetihin kendisi tartışmasızdır."], "sources": [{"title": "TDV İslâm Ansiklopedisi, II. Mehmed", "url": "https://islamansiklopedisi.org.tr/mehmed-ii"}], "aliases": []}, {"id": "bayezid-ii", "name": "II. Bayezid", "title": "Sultan", "claim": false, "birth": 1448, "birthNote": "1448, Dimetoka. Gün yok. Fâtih'in Gülbahar Hatun'dan büyük oğlu.", "death": 1512, "deathNote": "25 Rebîülevvel 918 / 10 Haziran 1512, Çorlu yakınında Abalar köyü, tahttan çekildikten sonra Dimetoka'ya giderken. 24 Nisan 1512'de yeniçeri baskısıyla çekilmişti.", "reign": [1481, 1512], "reignNote": "Babasının 3 Mayıs 1481 ölümü üzerine taht. Oğlu Korkut vekâleten oturtulmuştu. 24 Nisan 1512 feragat, 10 Haziran 1512 ölüm.", "summary": "Cem meselesi yüzünden dış siyasette ihtiyatlı kaldı. Fâtih'in sert örfî uygulamalarını yumuşattı. Kili ve Akkirman (1484), Modon-Koron-İnebahtı alındı. Memlük savaşı (1485-1491) yıpratıcıydı. Son yıllarda oğulları Ahmed, Korkut ve Selim arasında taht kavgası çıktı; yeniçeriler Selim'i çıkardı.", "traits": ["TDV: nikris, çok kadınla evlenen ve çok çocuklu bir padişah. Şehzadeliğinde afyon kullandığı, babasıyla arasının açıldığı, sonra vazgeçtiğini bildirdiği kayıtlıdır (TSMA). Ahmed'i kendine benzettiği için veliaht görmek istedi."], "contribution": "Şer'î çerçevenin örfî tasarrufa karşı güçlenmesi, Karadeniz'in kuzey kapısında Kili-Akkirman, Mora'da Venedik kaleleri, Endülüs muhacirlerinin getirilmesi, imar ve vakıf. Cem buhranını devleti parçalamadan kapattı.", "harm": "Cem'in Avrupa'da rehin tutulması Haçlı şantajına yol açtı; 1495'te muhtemel zehirlenme bu bedelin parçasıdır. Oğullar arası savaş 1511-12'de Anadolu'yu karıştırdı. Memlük savaşı Karaman ve Dulkadır siyasetini bozdu. Tahttan yeniçeri zoruyla indirilmesi kapıkulu müdahalesini büyüttü.", "wives": [{"name": "Ayşe Hatun", "note": "Dulkadıroğlu Alâüddevle'nin kızı, I. Selim'in annesi. TDV Selim maddesi Cenâbî'ye dayanır. Gülbahar bint Abdüssamed annelik iddiasını yakıştırma sayar.", "certainty": "kesin"}, {"name": "Diğer hanımlar", "note": "TDV: hanımlarının sayısı sekizdir; sekiz oğul ve on bir kız. Sekiz hanımın adları bu okumada tek tek dökülmedi, uydurulmadı.", "certainty": "olasi"}], "children": [{"name": "Abdullah", "mother": null, "note": "Büyük oğul. Selim maddesinde Fâtih'in onu Şehzade Mustafa'nın kızıyla evlendirdiği geçer. Babasından önce öldü.", "certainty": "kesin"}, {"name": "Ahmed", "mother": null, "note": "Amasya. Babasının tercih ettiği oğul. Selim mücadelesinde saf dışı kaldı.", "certainty": "kesin"}, {"name": "Korkut", "mother": null, "note": "1481'de vekâleten tahta oturtuldu. Son mücadelede de adaydı.", "certainty": "kesin"}, {"name": "Mahmud", "mother": null, "note": "Selim'in kardeşleri arasında sayılır.", "certainty": "kesin"}, {"name": "Âlemşah", "mother": null, "note": "Aynı kardeş listesi.", "certainty": "kesin"}, {"name": "Selim", "mother": "Ayşe Hatun", "note": "Halef. Trabzon sancakbeyi.", "certainty": "kesin"}, {"name": "İki oğul daha ve on bir kız", "mother": null, "note": "TDV sekiz oğul ve on bir kız der. Adı bu okumada geçmeyen iki oğul ve kızlar tek tek yazılmadı. İbn Kemal çocuk ve torun sayısını 300'ü aşmış gösterir; bu mübalağalı bir toplamdır.", "certainty": "olasi"}], "wars": [{"name": "Yenişehir", "when": "1481-06-22", "foe": "Cem Sultan", "result": "zafer", "note": "Cem Mısır'a, sonra Rodos'a gitti."}, {"name": "Kili ve Akkirman", "when": "1484", "foe": "Boğdan / Karadeniz kıyısı", "result": "zafer", "note": "TDV Osmanlılar."}, {"name": "Osmanlı-Memlük savaşı", "when": "1485-1491", "foe": "Memlükler", "result": "sonucsuz", "note": "Çukurova ve Dulkadır üzerinde yıpratıcı mücadele. Kalıcı ilhak Yavuz'a kaldı."}, {"name": "Modon, Koron, İnebahtı", "when": "1500", "foe": "Venedik", "result": "zafer", "note": "Mora istihkâmları."}], "legends": [], "sources": [{"title": "TDV İslâm Ansiklopedisi, II. Bayezid", "url": "https://islamansiklopedisi.org.tr/bayezid-ii"}], "aliases": []}, {"id": "selim-i", "name": "I. Selim", "title": "Sultan, Yavuz", "claim": false, "birth": 1470, "birthNote": "Bir rivayet 872 (1467-68), daha kuvvetli ihtimal 875 (1470), Amasya. Gün yok. Annesi Ayşe Hatun (Dulkadır). Gülbahar bint Abdüssamed anneliği TDV'de yakıştırma sayılır. İki yıl da not edilir, tek yıl yutulmaz: kartta 1470, nota 1467-68.", "death": 1520, "deathNote": "8-9 Şevval 926 / 21-22 Eylül 1520 gecesi, Çorlu civarı, sırtındaki ur (muhtemelen veba yumrusu). Ölüm, oğlu Süleyman Manisa'dan gelene kadar gizlendi. Türbesini oğlu Fatih Camii yanında yaptırdı.", "reign": [1512, 1520], "reignNote": "24 Nisan 1512'de babasının çekilmesiyle fiilen padişah. Ölüm 21-22 Eylül 1520.", "summary": "Trabzon sancakbeyiyken Gürcistan ve Safevî sınırında gazâ şöhreti kazandı. Kardeşleri ve babasıyla taht kavgasını göze aldı. 1514 Çaldıran'da Şah İsmail'i yendi, Tebriz'e girdi, kalıcı yerleşmedi. 1516 Mercidâbık ve 1517 Ridâniye ile Memlükler yıkıldı; Suriye, Mısır ve Haremeyn hizmeti Osmanlı'ya geçti. Mukaddes emanetler ve Halife Mütevekkil İstanbul'a gönderildi. Hilâfeti Ayasofya'da bir törenle devraldığı rivayetinin tarihî değeri TDV'ye göre yoktur.", "traits": ["TDV: orta boy, çatık kaş, sert bakış, sakalsız, gür ve uzun bıyık. Kendi çağında Yavuz lakabı sertlik ve ataklıktan gelir. Resmî belgelerde hâdimü'l-Haremeyn."], "contribution": "Doğu Anadolu'nun kontrolü, Memlük topraklarının ve Haremeyn koruyuculuğunun devralınması, donanmayla emanetlerin İstanbul'a gelişi, Safevî propagandasına karşı Sünnî siyasetin sertleşmesi. Mısır gelirinin hazineye eklenmesi.", "harm": "Kardeş ve yeğen katli veraset savaşının bedelidir. Anadolu'da Kızılbaş takibatı: TDV, idam edilenlerin daha çok Safevî halifeleri ve tekke mensupları olduğunu, bir kısmının sürgün edildiğini yazar; toptan katliam anlatısını doğrulamaz, yine de takibat ağırdır. Vezir Yunus Paşa'nın Mısır dönüşü idamı. Çaldıran sonrası Tebriz'i tutamama.", "wives": [{"name": "Hafsa Sultan", "note": "I. Süleyman'ın annesi. Kırım hanının kızı veya Dulkadırlı olduğu iddiası TDV Süleyman maddesinde yanlıştır.", "certainty": "kesin"}], "children": [{"name": "Süleyman", "mother": "Hafsa Sultan", "note": "Tek hayatta kalan oğul. Trabzon'da 6 Kasım 1494 (başka kayıtlar 1496).", "certainty": "kesin"}, {"name": "Sâlih", "mother": null, "note": "Trabzon'da doğdu, 1499'da küçük yaşta öldü.", "certainty": "kesin"}, {"name": "Kamerşah Sultan", "mother": null, "note": "Trabzon'da doğdu, 1503'te küçük yaşta öldü.", "certainty": "kesin"}, {"name": "Üveys Paşa (rivayet)", "mother": "adı verilmeyen câriye", "note": "Âlî Mustafa, Selim'in şehzadeliğinde gizlediği bir oğlu olduğunu ve bunun Üveys Paşa olduğunu, Süleyman'ın bildiğini aktarır. TDV bunu rivayet diye verir.", "certainty": "rivayet"}], "wars": [{"name": "Çaldıran", "when": "1514", "foe": "Safevî Şah İsmail", "result": "zafer", "note": "Tebriz'e girildi, kalıcı olunmadı. Doğu Anadolu Osmanlı kontrolüne geçti."}, {"name": "Mercidâbık", "when": "1516", "foe": "Memlükler (Kansu Gavri)", "result": "zafer", "note": "Halep. Abbâsî halifesi Mütevekkil esir düştü, Selim ona saygı gösterdi."}, {"name": "Ridâniye", "when": "1517", "foe": "Memlükler (Tomanbay)", "result": "zafer", "note": "Mısır alındı. Mekke statüsü korundu. Hilâfet devri bu seferin efsanesidir, ayrı maddeye bakınız."}], "legends": ["1517'de hilâfeti Mütevekkil'den Ayasofya töreniyle devraldığı ve oğullarına miras bıraktığı anlatısının doğruluğu TDV Selim maddesinde şüphelidir; törene tarihî değer biçilmez. Dönem kaynakları onu 'hilâfet tahtının sultanı' diye anabilir; resmî unvan hâdimü'l-Haremeyn'dir. Hilâfet maddesi, Osmanlı hilâfetinin klasik şekliyle değil gazâ ve Haremeyn hizmetiyle okunduğunu, Kureyş'e bağlanan canlandırmanın XVIII. yüzyılda çıktığını yazar.", "Mukaddes emanetlerin İstanbul'a gönderilmesi tarihîdir; bu, hukukî hilâfet devri değildir."], "sources": [{"title": "TDV İslâm Ansiklopedisi, I. Selim", "url": "https://islamansiklopedisi.org.tr/selim-i"}], "aliases": []}, {"id": "suleyman-i", "name": "I. Süleyman", "title": "Sultan; sonradan Kanûnî, Batı'da Muhteşem", "claim": false, "birth": 1494, "birthNote": "6 Safer 900 / 6 Kasım 1494, Trabzon (Lokman, Hünernâme). Mecdî Şâban 901 / Nisan-Mayıs 1496 der. TDV Hünernâme tarihini başa alır, farkı not eder. Annesi Hafsa Sultan. Kırım veya Dulkadır soy iddiası yanlıştır.", "death": 1566, "deathNote": "20-21 Safer 974 / 6-7 Eylül 1566 gecesi, Sigetvar kuşatması sırasında, kale düşmeden. Ölüm gizlendi. 'Kanûnî' lakabı XVIII. yüzyılda Cantemir'de geçer, XIX. yüzyılda Osmanlı tarihçilerince yaygınlaşır.", "reign": [1520, 1566], "reignNote": "Babasının Eylül 1520 ölümü üzerine Manisa'dan gelip tahta çıktı. Ölüm 6-7 Eylül 1566.", "summary": "Belgrad (1521), Rodos (1522), Mohaç (1526) ve 1541'de Budin beylerbeyiliği ile Orta Avrupa'da tutundu. 1529 Viyana kuşatması ve 1532 Alman seferi Habsburg'a gözdağıydı, şehir alınmadı. Preveze (1538) Doğu Akdeniz'de üstünlük getirdi. Irakeyn (1534) ile Bağdat, 1555 Amasya Antlaşması ile İran savaşı durdu. İçeride İbrahim Paşa'nın idamı (1536), Mustafa'nın öldürülmesi (1553) ve Bayezid'in isyanı hânedan buhranıdır. Malta (1565) alınamadı.", "traits": ["1542 Fransız tasviri: uzun, ince, esmer, geniş alın, iri siyah göz, kemerli burun, kızılımsı bıyık. Gazâya bizzat çıkan son klasik padişah kuşağındandır. Hürrem, Mihrimah ve Rüstem hizbine gittikçe daha açık yaslandı."], "contribution": "Klasik teşrifat ve kanun uygulamasının olgunlaşması, Budin ve Tımışvar hattı, Barbaros ile Cezayir'in bağlanması, Bağdat-Basra, Habeş beylerbeyiliği (1555), Süleymaniye. Fransa ile Habsburg dengesinde Osmanlı'nın Avrupa siyasetine girmesi.", "harm": "Şehzade Mustafa'nın 1553'te öldürülmesi ordu ve kamuoyunda ağır bir meşruiyet yarasıdır; TDV, Hürrem, Mihrimah ve Rüstem'in rolünden şüphe olmadığını yazar. Şehzade Bayezid'in isyanı ve oğullarıyla birlikte öldürülmesi. İbrahim Paşa'nın ansızın idamı. Viyana ve Malta başarısızlıkları, Macaristan'ın sürekli savaş maliyeti. Kıbrıs ve İnebahtı oğluna kaldı.", "wives": [{"name": "Mâhidevran", "note": "İlk yılların hasekisi, Mustafa'nın annesi. Hafsa'nın 1534 ölümünden sonra Manisa'da Mustafa'nın yanına gönderildi.", "certainty": "kesin"}, {"name": "Hürrem Sultan", "note": "Haseki. 1521'de Mehmed'i doğurduktan sonra haseki unvanı. Hafsa'nın ölümünden sonra nikâhlandı. Mihrimah, Abdullah, Selim, Bayezid, Cihangir onun çocuklarıdır. Batı'da Roxelane. Ukrayna/Rogatin kökeni muhtemeldir.", "certainty": "kesin"}], "children": [{"name": "Mustafa", "mother": "Mâhidevran", "note": "Tahtın güçlü adayı. 1553 İran seferinde öldürüldü.", "certainty": "kesin"}, {"name": "Mahmud", "mother": "Mâhidevran?", "note": "Cülusta Manisa'dan getirilen üç oğuldan biri. TDV bunların büyük ihtimalle Mâhidevran'dan olduğunu söyler. Küçük yaşta öldü.", "certainty": "olasi"}, {"name": "Murad", "mother": "Mâhidevran?", "note": "Aynı üçlü. Küçük yaşta öldü. III. Murad ile karıştırılmamalı.", "certainty": "olasi"}, {"name": "Mehmed", "mother": "Hürrem", "note": "1521 doğum. 5-6 Kasım 1543 Manisa'da öldü. Şehzade Camii onun içindir.", "certainty": "kesin"}, {"name": "Mihrimah", "mother": "Hürrem", "note": "1522 civarı. Rüstem Paşa ile evlendi. Babasının üzerinde geç dönemde etkili.", "certainty": "kesin"}, {"name": "Abdullah", "mother": "Hürrem", "note": "Hürrem maddesinde oğullar arasında sayılır. Küçük yaşta öldü.", "certainty": "kesin"}, {"name": "Selim", "mother": "Hürrem", "note": "30 Mayıs 1524, Topkapı. Halef.", "certainty": "kesin"}, {"name": "Bayezid", "mother": "Hürrem", "note": "Kardeşi Selim'e karşı isyan etti, yenildi, oğullarıyla birlikte öldürüldü.", "certainty": "kesin"}, {"name": "Cihangir", "mother": "Hürrem", "note": "Küçük oğul. Mustafa'nın ölümünden sonra kederden öldüğü anlatılır; bu okumada ölüm sebebi kesinlenmedi. Cihangir Camii onun adınadır.", "certainty": "olasi"}, {"name": "Adı bilinmeyen bir kız", "mother": null, "note": "Hammer'in 'on çocuk' sözü TDV'de Hurûfî yakıştırma sayılır. Adsız çocuk çoğaltılmadı.", "certainty": "tartismali"}], "wars": [{"name": "Belgrad", "when": "1521", "foe": "Macaristan", "result": "zafer", "note": "Orta Avrupa kapısı."}, {"name": "Rodos", "when": "1522", "foe": "Hospitalier şövalyeleri", "result": "zafer", "note": "Şövalyeler Malta'ya geçti."}, {"name": "Mohaç", "when": "1526", "foe": "Macaristan", "result": "zafer", "note": "Müstakil Macar krallığı sona erdi. Osmanlı'ya bağlı krallık denendi."}, {"name": "Viyana kuşatması", "when": "1529", "foe": "Habsburg", "result": "sonucsuz", "note": "On yedi gün. Şehir doğrudan hedef değildi, kuşatma kaldırıldı."}, {"name": "Preveze", "when": "1538", "foe": "Haçlı donanması (Andrea Doria)", "result": "zafer", "note": "Barbaros kumandasında. Doğu Akdeniz kontrolü."}, {"name": "Irakeyn", "when": "1534", "foe": "Safevîler", "result": "zafer", "note": "Tebriz ve Bağdat. Tebriz kalıcı olmadı, Bağdat kaldı."}, {"name": "Amasya Antlaşması", "when": "1555", "foe": "Safevîler", "result": "antlasma", "note": "Nahcıvan seferi sonrası. Sınır çizgisi uzun süre esas kaldı."}, {"name": "Malta", "when": "1565", "foe": "Hospitalier", "result": "yenilgi", "note": "Ada alınamadı."}, {"name": "Sigetvar", "when": "1566", "foe": "Habsburg Macaristan'ı", "result": "zafer", "note": "Kale düştü, padişah düşüşü göremeden 6-7 Eylül gecesi öldü."}], "legends": ["Hürrem'in büyü yaptığı anlatısı rakip hizip edebiyatıdır. Siyasî etkisi belgelenir, büyü iddiası rivayettir."], "sources": [{"title": "TDV İslâm Ansiklopedisi, I. Süleyman", "url": "https://islamansiklopedisi.org.tr/suleyman-i"}], "aliases": []}, {"id": "selim-ii", "name": "II. Selim", "title": "Sultan", "claim": false, "birth": 1524, "birthNote": "26 Receb 930 / 30 Mayıs 1524, Topkapı Sarayı. Kanûnî ile Hürrem'in oğlu. İstanbul'da doğup tahta çıkan ilk padişah.", "death": 1574, "deathNote": "28 Şâban 982 / 13 Aralık 1574 Pazartesi akşamı. TDV: hamamda düştükten sonra iki ay divana çıkamadı. On iki gün sarayda bekletildi. Cenâbî aynı tarihi verir. İlk kez sefere çıkmadan İstanbul'da ölen padişah diye Osmanlılar maddesi anar.", "reign": [1566, 1574], "reignNote": "Babasının 1566 ölümü üzerine taht. Ölüm 13 Aralık 1574.", "summary": "Kıbrıs 1570-71'de Venedik'ten alındı. İnebahtı'nda (1571) donanma ağır yenildi; ertesi yıl donanma yenilendi, 1574'te Tunus alındı. Sokullu'nun Don-Volga, Süveyş ve Endülüs tasarıları gerçekleşmedi. Yemen ve Basra'da isyanlar bastırıldı. Taht kavgasında kardeşi Bayezid saf dışı kalmıştı.", "traits": ["Uysal ve mütevazı diye babasının takdirini kazandığı Nahcıvan seferinde yazılır. Nurbânû, Mihrimah ve musâhib Hubbî Hatun'un tesirinde kaldığı belirtilir. 'Sarhoş' lakabı popülerdir; TDV ölümünü hamam düşmesine bağlar, lakabı olgu diye kurmaz."], "contribution": "Kıbrıs'ın alınması Doğu Akdeniz ada denetimini tamamladı. İnebahtı sonrası donanmanın bir yılda yenilenmesi deniz kapasitesinin sürdüğünü gösterdi. Tunus ile Kuzey Afrika'da İspanyol iddiası kırıldı.", "harm": "İnebahtı deniz gücüne ve itibara ağır darbe vurdu. Padişahın sefere çıkmaması gazâ şahsından ordu başarısına kaydı. Sokullu projelerinin terk edilmesi kuzey ve Hint siyasetini kapattı. Kıbrıs savaşı maliyeti ve Müslüman-Hıristiyan ada nüfusunun yer değiştirmesi.", "wives": [{"name": "Nurbânû Sultan", "note": "Venedik asıllı, asıl adı Cecilia Baffo. III. Murad'ın annesi. TDV, Safiye ile karıştırılmamasını özellikle yazar.", "certainty": "kesin"}], "children": [{"name": "Murad", "mother": "Nurbânû", "note": "4 Temmuz 1546, Manisa Bozdağ. Halef.", "certainty": "kesin"}, {"name": "Mehmed", "mother": null, "note": "Küçük yaşta, babasından yaklaşık iki yıl önce öldü.", "certainty": "olasi"}, {"name": "İsmihan", "mother": "Nurbânû?", "note": "Manisa/Uşak civarında doğdu. Sokullu Mehmed Paşa ile evlendi.", "certainty": "kesin"}, {"name": "Gevherhan", "mother": null, "note": "Piyâle Paşa ile evlendi.", "certainty": "kesin"}, {"name": "Şah Sultan", "mother": null, "note": "Önce Hasan Paşa, sonra Zal Mahmud Paşa.", "certainty": "kesin"}, {"name": "Fatma Sultan", "mother": null, "note": "1560 Konya doğumu. III. Murad dönemine kalır.", "certainty": "olasi"}], "wars": [{"name": "Kıbrıs", "when": "1570-1571", "foe": "Venedik", "result": "zafer", "note": "Ada alındı."}, {"name": "İnebahtı", "when": "1571", "foe": "Haçlı donanması", "result": "yenilgi", "note": "Osmanlı donanması ağır kayıp verdi."}, {"name": "Tunus", "when": "1574", "foe": "İspanya", "result": "zafer", "note": "İnebahtı'nın siyasî cevabı. Kuzey Afrika'da İspanyol emeli kırıldı."}], "legends": ["Sürekli sarhoşluk portresi rakip ve Batı edebiyatında abartılmıştır. TDV ölümü hamam kazasına bağlar."], "sources": [{"title": "TDV İslâm Ansiklopedisi, II. Selim", "url": "https://islamansiklopedisi.org.tr/selim-ii"}], "aliases": []}, {"id": "murad-iii", "name": "III. Murad", "title": "Sultan", "claim": false, "birth": 1546, "birthNote": "5 Cemâziyelevvel 953 / 4 Temmuz 1546, Manisa Bozdağ yaylası. Babası II. Selim, annesi Nurbânû (Cecilia Baffo).", "death": 1595, "deathNote": "6 Cemâziyelevvel 1003 / 17 Ocak 1595. Ayasofya hazîresine defnedildi. Selânikî mesane rahatsızlığı ve ölüm söylentisini yazar. Ölüm yaklaşık yirmi gün önce başlayan soğuk algınlığıyla ilişkilendirilir.", "reign": [1574, 1595], "reignNote": "Babasının Aralık 1574 ölümü üzerine Manisa'dan çağrıldı. Ölüm 17 Ocak 1595.", "summary": "1578'de İran savaşı başladı, 1590 Ferhat Paşa Antlaşması ile geniş doğu toprakları alındı; kalıcılığı I. Abbas döneminde bozuldu. 1593'te Habsburg savaşı açıldı. İngiliz ticarî imtiyazı ve Fas'ta 1578 nüfuzu bu devirdedir. Haremde Safiye ve Canfedâ Hatun nüfuzu, tağşiş ve kapıkulu isyanı mali bunalımın işaretidir. Ölümünde çok sayıda şehzade vardı; oğlu III. Mehmed bunların on dokuzunu öldürttü.", "traits": ["TDV: kumral, orta boy, iyi silah kullanır, ata biner. Servet ve mücevher meraklısı. Sevdiği kadınlara, çocuklara ve hocalarına cömert; kan dökmekten çekinen, ağzından nadiren 'hayır' çıkan bir mizaç diye dönem kaynakları yazar. Schweigger onu soluk yüzlü ve sağlıksız görür."], "contribution": "1590'a kadar Kafkas ve Azerbaycan hattında genişleme, İngiliz kapitülasyonları, Fas üzerinden Atlantik eşiğine nüfuz denemesi. Medrese ve hayrat.", "harm": "Uzun İran savaşı maliyeyi ve tımarı sarstı. Tağşiş 1589'da kapıkulu isyanı çıkardı (Beylerbeyi Vakası). Harem fraksiyonları sadrazamları yıprattı. Çok sayıda şehzadenin büyütülmesi III. Mehmed'in toplu kardeş katlinin zeminidir. 1593 Habsburg savaşı oğluna on dört yıllık bir yük olarak kaldı.", "wives": [{"name": "Safiye Sultan", "note": "Arnavut asıllı, Dukakin'de Rezi köyünden. Uzun süre tek haseki. III. Mehmed'in annesi. Venedikli Baffo olduğu iddiası yanlıştır; Baffo, Nurbânû'dur.", "certainty": "kesin"}, {"name": "Çok sayıda câriye", "note": "Nurbânû ve İsmihan'ın teşvikiyle Safiye'den sonra câriyelere rağbet ettiği Venedik raporları ve Schweigger'de vardır. Adları tek tek yazılmaz.", "certainty": "olasi"}], "children": [{"name": "Mehmed", "mother": "Safiye", "note": "26 Mayıs 1566 Manisa. Halef.", "certainty": "kesin"}, {"name": "Mahmud", "mother": "Safiye?", "note": "Manisa'da doğduğu TDV'de geçer. III. Mehmed'in öldürttüğü yetişkin kardeşlerden ayrı bir Mahmud'dur; karışmaması için not.", "certainty": "olasi"}, {"name": "Ayşe", "mother": "Safiye?", "note": "Manisa'da doğdu.", "certainty": "olasi"}, {"name": "Fatma", "mother": "Safiye?", "note": "Manisa'da doğdu.", "certainty": "olasi"}, {"name": "Adı geçmeyen çok sayıda çocuk", "mother": null, "note": "TDV: haseki, câriye ve çocuk sayısı hakkında mübalağalı rivayet vardır. Vefatında 49 çocuğu hayattaydı, yedi câriye gebeydi. Bu sayı dönem kaynaklarına dayanır. Adı verilmeyen onlarca çocuk tek tek uydurulmadı. III. Mehmed tahta çıkınca dördü yetişkin (Mustafa, Bayezid, Osman, Abdullah) olmak üzere on dokuz şehzadeyi boğdurdu; yirmi yedi kız Eski Saray'a gönderildi.", "certainty": "kesin"}], "wars": [{"name": "İran savaşı ve Ferhat Paşa Antlaşması", "when": "1578-1590", "foe": "Safevîler", "result": "antlasma", "note": "Geniş toprak alındı. Kalıcılığı zayıftı."}, {"name": "Habsburg savaşı", "when": "1593-1606", "foe": "Avusturya", "result": "sonucsuz", "note": "Onun ölümünden sonra da sürdü. 1596 Haçova oğlu devrindedir. 1606 Zitvatorok eşitlik ilkesini getirdi."}], "legends": ["Yüzlerce çocuk rivayeti mübalağalıdır. TDV'nin tuttuğu somut rakam vefatta 49 hayatta çocuk ve 7 gebeliktir."], "sources": [{"title": "TDV İslâm Ansiklopedisi, III. Murad", "url": "https://islamansiklopedisi.org.tr/murad-iii"}], "aliases": []}, {"id": "mehmed-iii", "name": "III. Mehmed", "title": "Sultan", "claim": false, "birth": 1566, "birthNote": "7 Zilkade 973 / 26 Mayıs 1566, Manisa Sart ovası. Babası III. Murad, annesi Safiye. Adını Sigetvar seferindeyken Kanûnî'nin koyduğu rivayettir.", "death": 1603, "deathNote": "18 Receb 1012 / 22 Aralık 1603. Oğlu I. Ahmed 28 Nisan 1590 doğumluydu ve bu ölüm üzerine tahta çıktı.", "reign": [1595, 1603], "reignNote": "16-17 Ocak 1595'te babasının ölüm haberi, 27 Ocak İstanbul. Cülus 1595. Ölüm 22 Aralık 1603.", "summary": "Tahta çıkınca on dokuz kardeşini boğdurdu. 1596'da Eğri ve Haçova seferine bizzat çıktı; Haçova kritik bir anda döndü ve zafer sayıldı. Celâlî isyanları ve İran cephesi aynı yıllara bindi. 1603'te büyük oğlu Mahmud'u taht şüphesiyle boğdurdu, annesini ve yaklaşık otuz hizmetçisini denize attırdı. Annesi Safiye devlet işlerine karıştı.", "traits": ["TDV: mülâyim, etki altında kalan, kardeş katlinin ağırlığını üzerinden atamayan, son yıllarda içine kapanan bir padişah. Safiye onu kontrol altında tuttu."], "contribution": "Haçova, uzun savaşın ortasında dağılmayı önleyen bir meydan başarısıdır. Eğri'nin alınması sınırda tutunma sağladı.", "harm": "On dokuz kardeşin katli kardeş katlinin en geniş uygulamasıdır ve tepki, I. Ahmed'in Mustafa'yı sağ bırakmasının gerekçelerinden biri oldu. Şehzade Mahmud'un ve annesinin öldürülmesi. Celâlî ve uzun savaş maliyesi. Safiye'nin müdahalesi kapıkulu ve ulemâda nefret biriktirdi.", "wives": [{"name": "Handan Sultan", "note": "I. Ahmed'in annesi. TDV Ahmed maddesi.", "certainty": "kesin"}, {"name": "Adı bilinmeyen Abaza câriye", "note": "I. Mustafa'nın annesi. TDV Mustafa maddesi adını bilmez, Abaza asıllı der.", "certainty": "olasi"}, {"name": "Şehzade Mahmud'un annesi", "note": "Adı bu okumada geçmez. 7 Haziran 1603'te oğluyla birlikte ortadan kaldırıldı, denize atıldı.", "certainty": "olasi"}], "children": [{"name": "Mahmud", "mother": "adı bu okumada yok", "note": "Büyük oğul. 27 Zilhicce 1011 / 7 Haziran 1603 boğuldu.", "certainty": "kesin"}, {"name": "Ahmed", "mother": "Handan Sultan", "note": "28 Nisan 1590 Manisa. Halef.", "certainty": "kesin"}, {"name": "Mustafa", "mother": "adı bilinmeyen Abaza kadın", "note": "Yaklaşık 1591-92 Manisa. Sonraki padişah. Kardeş katlinden Ahmed'in henüz oğlu olmadığı için kurtuldu.", "certainty": "kesin"}, {"name": "Diğer çocuklar", "mother": null, "note": "Sancağa çıkamadan İstanbul'da büyüyen kuşak. Adları bu maddede dökülmeyenler yazılmadı.", "certainty": "tartismali"}], "wars": [{"name": "Eğri", "when": "1596", "foe": "Habsburg", "result": "zafer", "note": "Sefer-i hümâyun."}, {"name": "Haçova", "when": "1596", "foe": "Habsburg ve müttefikler", "result": "zafer", "note": "Ordu bir ara bozuldu, sonra toparlandı. Uzun savaşın en bilinen meydanı."}, {"name": "İran cephesi", "when": "1603", "foe": "Safevî Şah Abbas", "result": "yenilgi", "note": "1590 kazançları bu yıldan itibaren geri alınmaya başladı. Savaş oğluna kaldı."}], "legends": [], "sources": [{"title": "TDV İslâm Ansiklopedisi, III. Mehmed", "url": "https://islamansiklopedisi.org.tr/mehmed-iii"}], "aliases": []}, {"id": "ahmed-i", "name": "I. Ahmed", "title": "Sultan", "claim": false, "birth": 1590, "birthNote": "28 Nisan 1590, Manisa. Babası III. Mehmed, annesi Handan Sultan. Celâlî yüzünden sancağa çıkamadı.", "death": 1617, "deathNote": "22 Kasım 1617, yirmi sekiz yaşında, elli bir gün süren mide hastalığı. Sultan Ahmed Camii yanına defnedildi.", "reign": [1603, 1617], "reignNote": "22 Aralık 1603'te babasının ölümü üzerine on dört yaşında tahta çıktı. Ölüm 22 Kasım 1617. Yerine oğlu Osman değil amcası Mustafa çıkarıldı; ekberiyet uygulamasının başlangıcı.", "summary": "Safiye Sultan'ı Eski Saray'a gönderdi. 1606 Zitvatorok, Habsburg ile eşitlik esasını getirdi ve uzun savaşı kapattı. Celâlîler Kuyucu Murad Paşa eliyle bastırıldı. İran savaşı sürdü. Sultan Ahmed Camii onun eseridir. Çocukları küçükken ölürse hânedan Mustafa'ya kalacağı için kardeşini öldürtmedi.", "traits": ["Genç yaşta tahta çıkan, av ve hayır işlerine düşkün bir padişah. Kardeş katlini uygulamaması hem zaruret hem tepkinin sonucudur."], "contribution": "Zitvatorok ile batı cephesinin kapanması, Sultan Ahmed Camii, ekberiyete giden uygulamanın fiilî başlaması. Celâlî şiddetinin bir süre için durulması.", "harm": "Zitvatorok, yıllık haracı ve protokol üstünlüğünü zayıflattı. Celâlî tenkili Anadolu'yu daha da kırdı. İran cephesinde kayıplar. 1617 veraset kararı (Mustafa) kısa sürede darbelere yol açtı.", "wives": [{"name": "Mahfiruz Sultan", "note": "II. Osman'ın annesi. TDV Osman maddesi Mahfîrûz yazar. Kösem maddesi Mahfirûz Hatice der.", "certainty": "kesin"}, {"name": "Kösem Mahpeyker Sultan", "note": "IV. Murad ve İbrahim'in annesi. Saraya nasıl girdiği bilinmez; Ortodoks papaz kızı ve Bosna kökeni ileri sürülür, kesin değildir. I. Ahmed'in önde gelen hasekisi.", "certainty": "kesin"}], "children": [{"name": "Osman", "mother": "Mahfiruz", "note": "3 Kasım 1604. Sonraki II. Osman. Ahmed'in ilk oğlu.", "certainty": "kesin"}, {"name": "Mehmed", "mother": null, "note": "8 Mart 1605 doğumu Osman maddesinde anılır. II. Osman tarafından, taht sırasında kendisine rakip görüldüğü için öldürtüldü.", "certainty": "kesin"}, {"name": "Murad", "mother": "Kösem", "note": "27 Temmuz 1612. Sonraki IV. Murad.", "certainty": "kesin"}, {"name": "İbrahim", "mother": "Kösem", "note": "4 Kasım 1615. Sonraki sultan.", "certainty": "kesin"}, {"name": "Bayezid ve Süleyman", "mother": null, "note": "IV. Murad 1635'te boğdurdu. İbrahim maddesi onları kendi kardeşleri diye anar.", "certainty": "kesin"}, {"name": "Kasım", "mother": "Kösem?", "note": "IV. Murad 1638'de Bağdat seferi öncesi idam ettirdi. İbrahim ile ana-baba bir kardeşler arasında sayılır.", "certainty": "olasi"}], "wars": [{"name": "Zitvatorok", "when": "1606", "foe": "Habsburg", "result": "antlasma", "note": "Yirmi üç gün müzakere, on yedi madde. İki hükümdar eşit sayıldı. Uzun savaş bitti. Büyümenin durduğu yorumu tarihçilerde yaygındır; bu, tek yönlü gerileme etiketi değildir."}, {"name": "Celâlî tenkili", "when": "1606-1610", "foe": "Celâlî grupları", "result": "zafer", "note": "Canbolatoğlu, Kalenderoğlu ve diğerleri. Bastırma ağır tahribatla geldi."}, {"name": "İran seferleri", "when": "1603-1617", "foe": "Safevîler", "result": "yenilgi", "note": "Şah Abbas Revân ve başka kaleleri geri aldı. Savaş kapanmadı."}], "legends": ["Kösem'in, Osman'ın yerine Mustafa'yı çıkarmak için 1617 komplosunun içinde olduğu rivayettir. TDV bunu rivayet diye yazar."], "sources": [{"title": "TDV İslâm Ansiklopedisi, I. Ahmed", "url": "https://islamansiklopedisi.org.tr/ahmed-i"}], "aliases": []}, {"id": "mustafa-i", "name": "I. Mustafa", "title": "Sultan", "claim": false, "birth": 1591, "birthNote": "Muhtemelen 1000 (1591-92), Manisa. Gün yok. Babası III. Mehmed. Annesi Abaza asıllı, adı bilinmiyor.", "death": 1639, "deathNote": "15 Ramazan 1048 / 20 Ocak 1639. İkinci saltanattan uzun yıllar sonra, kafes hayatı içinde öldü. TDV cümlesi kardeşleri Süleyman ve Bayezid'i öldürten IV. Murad bağlamında kesilir; tarih aktarılır.", "reign": [1617, 1623], "reignNote": "İki saltanat, tek kart. Birinci: I. Ahmed'in 22 Kasım 1617 ölümünden II. Osman'ın 26 Şubat 1618 cülusuna (yaklaşık doksan altı gün). İkinci: II. Osman'ın 20 Mayıs 1622 katlinden IV. Murad'ın 10 Eylül 1623 cülusuna. Klasik sayımda bir padişahtır.", "summary": "Ahmed'in oğlu Osman dururken, henüz padişahın erkek vârisi yokken ve III. Mehmed'in katliamı nefretle hatırlanırken tahta çıkarıldı. Aklî dengesi yerinde değildi. İlk saltanatı kısa sürdü. İkincisi yeniçeri darbesinin eseridir; annesi ve damadı Dâvud Paşa fiilen iş gördü. 1623'te indirilip yerine çocuk Murad çıkarıldı.", "traits": ["TDV ve Peçuylu: aklî melekeleri zayıf, ikinci saltanatında daha da kötüleşmiş. Saray dedikodusu ve 'Deli' lakabı bu gözleme dayanır; klinik teşhis yoktur."], "contribution": "Kendisinin kurumsal eseri yoktur. Tahta çıkışı, kardeş katli yerine hânedanın en büyüğünün geçmesi uygulamasını başlattı. Bu, sonraki padişahların kafes hayatı pahasına hânedanın tükenmemesini sağladı.", "harm": "İkinci saltanatında II. Osman'ın katli meşrulaştırıldı. Dâvud Paşa ve vâlide etrafında rüşvet ve tevcih. Devletin fiilen sahipsiz kaldığı aylar Kapıkulu'nun darbesini normalleştirdi.", "wives": [], "children": [], "wars": [], "legends": ["Tahttayken denizlere altın atması gibi hikâyeler aklî zafiyet edebiyatıdır. TDV siyasi anlatıyı esas alır, bu hikâyeleri olgu diye kurmaz."], "sources": [{"title": "TDV İslâm Ansiklopedisi, I. Mustafa", "url": "https://islamansiklopedisi.org.tr/mustafa-i"}], "aliases": []}, {"id": "osman-ii", "name": "II. Osman", "title": "Sultan, Genç Osman", "claim": false, "birth": 1604, "birthNote": "10 Cemâziyelâhir 1013 / 3 Kasım 1604 Çarşamba, İstanbul. Babası I. Ahmed, annesi Mahfiruz. Ahmed'in ilk oğlu olduğu için Osman Gazi'nin adı verildi.", "death": 1622, "deathNote": "20 Mayıs 1622'de yeniçeriler yakaladı. Yedikule'de boğuldu. Kulak ve burnunun kesilip vâlideye gösterildiği bazı tarihçilerde vardır. Ceset gizlice Topkapı'ya getirildi.", "reign": [1618, 1622], "reignNote": "1 Rebîülevvel 1027 / 26 Şubat 1618'de amcasının indirilmesiyle tahta çıktı. 20 Mayıs 1622'de katledildi.", "summary": "Hotin seferine (1621) bizzat çıktı, kaleyi alamadı, Lehistan ile ağır şartlarda döndü. Yeniçeriye güveni sarsılınca hac ve Anadolu askeri toplama söylentisi isyanı büyüttü. Kardeşi Mehmed'i öldürttü. Yakalanıp Yedikule'de boğulması, padişah katlinin kapıkulu eliyle meşrulaştığı eşiktir.", "traits": ["Genç, hırslı, kapıkuluna karşı alternatif ordu arayan bir padişah. Amcasının kendisi dururken tahta çıkarılmasından kırgındı. TDV onu gazi hükümdar tipini canlandırmaya çalışan son örneklerden sayar."], "contribution": "Hotin seferi sonuçsuz olsa da padişahın sefere çıkma iradesini gösterdi. Yeniçeri disiplinini düzeltme teşebbüsü, başarısız da olsa sorunu görünür kıldı.", "harm": "Kardeşi Mehmed'in katli. Hotin'in başarısızlığı ve dönüşte asker ücretine müdahale isyanı besledi. Öldürülmesi padişah kanının dökülmesini siyaset aracı yaptı. Oğlu Ömer'in 1622'de kaza kurşunuyla ölmesi hânedan umudunu kısalttı.", "wives": [{"name": "Ayşe", "note": "Venedik kaynakları: Rus/Ukrayna asıllı, Kızlarağası Mustafa Ağa'nın yetiştirdiği, nikâhlı hanım. Şehzade Ömer'in annesi diye anılır.", "certainty": "olasi"}, {"name": "Pertev Paşa ailesinden bir kız", "note": "1622'de, Ömer'in ölümünden sonra nikâh.", "certainty": "olasi"}, {"name": "Âkıle", "note": "Şeyhülislâm Esad Efendi'nin kızı. Ulemâyı yanına çekmek için nikâhlandığı düşünülür.", "certainty": "kesin"}], "children": [{"name": "Ömer", "mother": "Ayşe?", "note": "Edirne'de doğum müjdesi. 1622 Şubat'ında Hotin temsilî gösterisinde seken kurşunla öldü.", "certainty": "olasi"}], "wars": [{"name": "Hotin", "when": "1621", "foe": "Lehistan", "result": "sonucsuz", "note": "Kale alınamadı. Antlaşmayla dönüldü. Padişah ordunun başındaydı."}], "legends": ["Genç Osman menkıbeleri şehadet edebiyatına dönüşmüştür. Katlin kendisi görgü şahitli tarihçilerle sabittir."], "sources": [{"title": "TDV İslâm Ansiklopedisi, II. Osman", "url": "https://islamansiklopedisi.org.tr/osman-ii"}], "aliases": []}, {"id": "murad-iv", "name": "IV. Murad", "title": "Sultan", "claim": false, "birth": 1612, "birthNote": "28 Cemâziyelevvel 1021 / 27 Temmuz 1612, İstanbul. Babası I. Ahmed, annesi Kösem.", "death": 1640, "deathNote": "15 Şevval 1049 / 8 Şubat 1640 Perşembe, yatsıdan sonra. Şehzade Kasım'ı boğdurduğu odada öldü. Sultan Ahmed Camii yanında babasının türbesine gömüldü. Son günlerde ara sıra şuurunu kaybettiği nakledilir.", "reign": [1623, 1640], "reignNote": "15 Zilkade 1032 / 10 Eylül 1623'te, amcası Mustafa indirilerek, annesinin de tesiriyle çocuk yaşta tahta çıktı. 1632'ye kadar valide ve ocak nüfuzu güçlüdür. Ölüm 8 Şubat 1640.", "summary": "İlk yıllar isyanlar ve valide naipliğiyle geçti. 1632'den sonra bizzat idare etti. Revan (1635) ve Bağdat (1638) seferleri, 1639 Kasr-ı Şirin ile İran sınırını uzun süre sabitledi. İçki, tütün ve gece sokağa çıkma yasakları ve sık idamlarla düzen kurdu. Kardeşleri Bayezid, Süleyman ve Kasım'ı öldürttü; tek erkek vârisi İbrahim kaldı.", "traits": ["Sert, bizzat kılıç kullanan, yasağı önce kendisi çiğneyebilen bir padişah. Kösem'in onu eğlenceyle oyaladığı, sonra oğlunun sertleşmesinden çekindiği yazılır. Gazi hükümdar tipini XVII. yüzyılda yeniden deneyen örneklerdendir."], "contribution": "Kasr-ı Şirin (1639) ile Bağdat, Van, Kars ve Kuzey Irak çizgisinin tasdiki. Revan ve Bağdat seferleri doğu cephesini kapattı. İstanbul'da asayişin sert tedbirle sağlanması kısa vadede düzen getirdi.", "harm": "Kardeş katli hânedanı tek kişiye, İbrahim'e indirdi. Keyfî idamlar (Şeyhülislâm Ahîzâde dahil) ulemâyı sindirdi. Yasaklar ve içki düşkünlüğü aynı kişide çelişti. Anadolu'da isyan tenkili köylüyü de vurdu.", "wives": [{"name": "Adları bu okumada dökülmeyen hasekiler", "note": "Kızı Kaya Sultan Silâhdar Mustafa Paşa ile evlendirilmek istendi. Anne adı bu pasajda geçmez.", "certainty": "tartismali"}], "children": [{"name": "Kaya Sultan", "mother": null, "note": "Kösem'in torunu olarak evlilik siyasetinde adı geçer. Babası IV. Murad.", "certainty": "kesin"}, {"name": "Küçük yaşta ölen oğullar", "mother": null, "note": "İbrahim maddesi: IV. Murad'ın oğulları çok küçük yaşta öldü; bu yüzden İbrahim tek vârisi kaldı. Adlar uydurulmadı.", "certainty": "kesin"}], "wars": [{"name": "Revan", "when": "1635", "foe": "Safevîler", "result": "zafer", "note": "Kale alındı. Kalıcılığı sınırlı kaldı."}, {"name": "Bağdat", "when": "1638", "foe": "Safevîler", "result": "zafer", "note": "Bağdat geri alındı."}, {"name": "Kasr-ı Şirin", "when": "1639", "foe": "Safevîler", "result": "antlasma", "note": "Sınır uzun süre esas kaldı. TDV Osmanlılar."}], "legends": ["Gece tebdili ve anında idam hikâyelerinin bir kısmı gözlem, bir kısmı abartıdır. Sertlik politikasının kendisi belgelidir."], "sources": [{"title": "TDV İslâm Ansiklopedisi, IV. Murad", "url": "https://islamansiklopedisi.org.tr/murad-iv"}], "aliases": []}, {"id": "ibrahim", "name": "İbrahim", "title": "Sultan", "claim": false, "birth": 1615, "birthNote": "12 Şevval 1024 / 4 Kasım 1615. Babası I. Ahmed, annesi Kösem. Tahta çıktığında yirmi beş yaşındaydı.", "death": 1648, "deathNote": "Hal' 18 Receb 1058 / 8 Ağustos 1648. Öldürülme: Kâtib Çelebi'nin 8 Şâban tarihi TDV yazarı tarafından 28 Receb / 18 Ağustos 1648 diye düzeltilir. Cellât Kara Ali. Gılmânî, sadrazam, şeyhülislâm ve nakîbüleşrafın boğdurduğunu yazar.", "reign": [1640, 1648], "reignNote": "8 Şubat 1640'ta ağabeyinin ölümüyle, hânedanın tek erkeği olarak tahta çıktı. 8 Ağustos 1648'de indirildi, 18 Ağustos 1648'de öldürüldü.", "summary": "Yıllarca öldürüleceği korkusuyla yaşadı. İlk yıllar Kemankeş Kara Mustafa Paşa idaresinde sakin, onun 1644 idamından sonra saray musahipleri ve câriye rekabeti belirleyici oldu. 1645'te Girit savaşı başladı. 1648'de yeniçeri ve Kösem'in de dahil olduğu darbe ile indirildi, yerine yedi yaşındaki oğlu IV. Mehmed çıkarıldı.", "traits": ["TDV: çocukluk ve kardeş katli travması sinirlerini bozmuştu. Kapris, kürk ve koku düşkünlüğü, musahiplere açıklık dönem kaynaklarında vardır. 'Deli' lakabı klinik teşhis değildir; siyasî literatürdür."], "contribution": "Sekiz oğlu hânedanın sürmesini sağladı; sonraki bütün padişahlar onun soyundandır (TDV Osmanlılar). Girit savaşını başlatması adanın 1669'da alınmasına giden yolu açtı, bedeli uzundu.", "harm": "Girit savaşı maliyesi ve Venedik'in Çanakkale ablukası. Sadrazamların sık idamı. Kaprisli tevcihler. Hal' ve boğulma padişah katlini tekrarladı. Küçük yaştaki oğlunun tahta çıkması valide nüfuzunu kurumsallaştırdı.", "wives": [{"name": "Hatice Turhan", "note": "IV. Mehmed'in annesi.", "certainty": "kesin"}, {"name": "Sâliha Dilâşub", "note": "II. Süleyman'ın annesi.", "certainty": "kesin"}, {"name": "Hatice Muazzez", "note": "II. Ahmed'in annesi.", "certainty": "kesin"}, {"name": "Ayşe", "note": "TDV'nin saydığı zevcelerdendir.", "certainty": "kesin"}, {"name": "Mâhenver", "note": "Aynı liste.", "certainty": "kesin"}, {"name": "Şîvekâr", "note": "Aynı liste.", "certainty": "kesin"}, {"name": "Hümâşah", "note": "Aynı liste. Telli Haseki diye de anılır; bu okumada lakap ayrıca doğrulanmadı, ad TDV listesindedir.", "certainty": "kesin"}], "children": [{"name": "Mehmed", "mother": "Hatice Turhan", "note": "2 Ocak 1642. IV. Mehmed.", "certainty": "kesin"}, {"name": "Süleyman", "mother": "Sâliha Dilâşub", "note": "15 Nisan 1642. II. Süleyman.", "certainty": "kesin"}, {"name": "Ahmed", "mother": "Hatice Muazzez", "note": "25 Şubat 1643. II. Ahmed.", "certainty": "kesin"}, {"name": "Murad", "mother": null, "note": "TDV iki ayrı Murad sayar. Küçük yaşta öldüler.", "certainty": "kesin"}, {"name": "Orhan", "mother": null, "note": "Küçük yaşta öldü.", "certainty": "kesin"}, {"name": "Bayezid", "mother": null, "note": "Küçük yaşta öldü.", "certainty": "kesin"}, {"name": "Cihangir", "mother": null, "note": "Küçük yaşta öldü.", "certainty": "kesin"}, {"name": "Selim", "mother": null, "note": "Küçük yaşta öldü.", "certainty": "kesin"}], "wars": [{"name": "Girit savaşı", "when": "1645-1648", "foe": "Venedik", "result": "sonucsuz", "note": "Onun döneminde başladı. Hanya alındı, Kandiye 1669'a kadar düşmedi. Sonuç oğlunun saltanatına kaldı."}], "legends": ["Samur ve amber düşkünlüğü abartılı fıkralara bağlanır. Siyasî istikrarsızlık ve Girit savaşı belgedir."], "sources": [{"title": "TDV İslâm Ansiklopedisi, İbrahim", "url": "https://islamansiklopedisi.org.tr/ibrahim"}], "aliases": []}, {"id": "mehmed-iv", "name": "IV. Mehmed", "title": "Sultan, Avcı", "claim": false, "birth": 1642, "birthNote": "30 Ramazan 1051 / 2 Ocak 1642, İstanbul. Babası İbrahim, annesi Hatice Turhan.", "death": 1693, "deathNote": "28 Rebîülâhir 1104 / 6 Ocak 1693, Edirne. Naaşı İstanbul'da Turhan Sultan'ın Yenicami civarındaki türbesine kondu. Tahttan indirilişi 1687'dedir; ölüm indirildikten sonradır.", "reign": [1648, 1687], "reignNote": "18 Receb 1058 / 8 Ağustos 1648'de yedi yaşında tahta çıktı. 1687'de hal' edildi. Yerine oğlu değil kardeşi II. Süleyman geçti. Ölüm 1693.", "summary": "Çocukluğu Kösem ile Turhan çekişmesi ve 1651'de Kösem'in öldürülmesiyle geçti. Köprülü Mehmed (1656) ve Fâzıl Ahmed paşalar döneminde Girit tamamlandı (1669), Uyvar (1663) ve Kamaniçe (1672) alındı. 1683 Viyana bozgunu çok cepheli savaşa döndü. 1687'de ordu onu indirip Süleyman'ı çıkardı. Av merakı 'Avcı' lakabını doğurdu.", "traits": ["Ava tutkulu. Seferde bulundu ama Viyana kararını Merzifonlu Kara Mustafa'ya bıraktı. Oğlu Mustafa'nın geçmesini istedi, erkân Süleyman'ı seçti."], "contribution": "Köprülü restorasyonu: Boğaz ablukasının kalkması, Kandiye'nin düşmesi, Uyvar ve Podolya'da batının en geniş sınırına yaklaşma. Turhan Sultan'ın Yenicami'yi tamamlaması bu saltanatın imar yüzüdür.", "harm": "1683 Viyana bozgunu ve ardından Budin (1686), Uyvar ve Macaristan hattının kaybı. Çocuk padişah yıllarında valide ve ocak cinayetleri. Av partilerinin devlet işini ikinci plana atması çağdaş eleştiridir.", "wives": [{"name": "Gülnûş Emetullah (Râbia Gülnûş)", "note": "II. Mustafa ve III. Ahmed'in annesi. TDV Mustafa ve Ahmed maddeleri.", "certainty": "kesin"}], "children": [{"name": "Mustafa", "mother": "Gülnûş Emetullah", "note": "2 Haziran 1664 Edirne. Sonraki II. Mustafa.", "certainty": "kesin"}, {"name": "Ahmed", "mother": "Gülnûş Emetullah", "note": "31 Aralık 1673. Sonraki III. Ahmed.", "certainty": "kesin"}, {"name": "Bir kız", "mother": null, "note": "1675 Edirne şenliğinde oğullarıyla birlikte evlilik ve sünnet düğünü yapılan kızın adı bu pasajda geçmez.", "certainty": "olasi"}], "wars": [{"name": "Kandiye", "when": "1669", "foe": "Venedik", "result": "zafer", "note": "Girit'in tamamlanması. Savaş 1645'te başlamıştı."}, {"name": "Uyvar", "when": "1663", "foe": "Habsburg", "result": "zafer", "note": "Batıda en ileri hattlardan biri. 1685'te kaybedildi."}, {"name": "Kamaniçe", "when": "1672", "foe": "Lehistan", "result": "zafer", "note": "Podolya. 1676 Zuravno ve 1681 Rus antlaşması bu genişlemeyi bir süre tasdik etti."}, {"name": "II. Viyana", "when": "1683", "foe": "Habsburg ve müttefikler", "result": "yenilgi", "note": "Kuşatma başarısız. Ardından çok cepheli savaş ve 1699 Karlofça."}, {"name": "Budin'in kaybı", "when": "1686", "foe": "Habsburg", "result": "yenilgi", "note": "1541'den beri tutulan merkez elden çıktı. Onun hal'inden hemen önce ve hal' sürecinde."}], "legends": [], "sources": [{"title": "TDV İslâm Ansiklopedisi, IV. Mehmed", "url": "https://islamansiklopedisi.org.tr/mehmed-iv"}], "aliases": []}, {"id": "suleyman-ii", "name": "II. Süleyman", "title": "Sultan", "claim": false, "birth": 1642, "birthNote": "15 Muharrem 1052 / 15 Nisan 1642 (bazı kaynaklar 14, bir belge 16 Muharrem), İstanbul. Babası İbrahim, annesi Sâliha Dilâşub.", "death": 1691, "deathNote": "25 Ramazan 1102 / 22 Haziran 1691 Cuma, öğleye doğru, Edirne civarı sefer hazırlığında. Yerine kardeşi II. Ahmed'in geçmesini vasiyet etti.", "reign": [1687, 1691], "reignNote": "1687'de IV. Mehmed indirilerek, kırk yıldan uzun kafes hayatından çıkarıldı. 22 Haziran 1691'de öldü.", "summary": "Karlofça öncesi buhranın padişahı. Cülus bahşişi ve Sancak Vakası ile başladı. Köprülüzâde Fâzıl Mustafa Paşa'yı cephede tuttu. 1691'de ordunun başında gibi sefere niyetlendi, yolda öldü. Aynı yıl Salankamen'de Fâzıl Mustafa şehid düştü.", "traits": ["Uzun hapis yüzünden zayıf eğitim, kırılgan mizaç. Saray odaklarının etkisinde kaldı. Annesinin ölümünden sonra Kethüdâ Kadın'a has tayini gibi alışılmadık bir uygulama yaptı."], "contribution": "Orduyu tamamen dağıtmadan savaşı sürdürme iradesi. Kardeşi Ahmed'e düzenli geçiş vasiyeti ekberiyeti işletti.", "harm": "Saltanatı kayıplarla geçti. Cülus isyanı İstanbul'u karıştırdı. Kısa sürede siyasî inisiyatif sadrazama kaldı.", "wives": [], "children": [], "wars": [{"name": "Sancak Vakası", "when": "1687-1688", "foe": "Kapıkulu", "result": "sonucsuz", "note": "İç isyan. Padişah indirilmek istendi, dört ay süren karışıklık kapandı."}, {"name": "Salankamen", "when": "1691", "foe": "Habsburg", "result": "yenilgi", "note": "Fâzıl Mustafa Paşa şehid, ordu dağıldı. Padişah sonucu göremeden ölmüştü; savaş onun sefer kararının devamıdır."}], "legends": [], "sources": [{"title": "TDV İslâm Ansiklopedisi, II. Süleyman", "url": "https://islamansiklopedisi.org.tr/suleyman-ii"}], "aliases": []}, {"id": "ahmed-ii", "name": "II. Ahmed", "title": "Sultan", "claim": false, "birth": 1643, "birthNote": "6 Zilhicce 1052 / 25 Şubat 1643. Babası İbrahim, annesi Muazzez Sultan.", "death": 1695, "deathNote": "6 Şubat 1695, Edirne, istiska (ödem), elli iki yaşında.", "reign": [1691, 1695], "reignNote": "23 Haziran 1691'de Edirne'de, kırk dokuz yaşında tahta çıktı. 6 Şubat 1695'te öldü.", "summary": "Avusturya savaşı sürerken tahta çıktı. Salankamen sonrası ordu dağılmıştı. Sadrazamlar sık değişti. Sakız Venedik tarafından basıldı; kurtarma hazırlığı ölümüne yetişmedi. Yerine yeğeni II. Mustafa geçti.", "traits": ["Kısa saltanat. Siyasî portresi savaş haberleri ve azillerle doludur; kişisel huy üzerine TDV az konuşur."], "contribution": "Hânedan geçişini sürdürdü. Müstakil bir ıslahat hamlesi bu okumada yoktur.", "harm": "Varad'ın kaybı ve Sakız baskını moral bozdu. Savaş maliyeti sürdü. Kısa saltanat cepheye istikrar vermedi.", "wives": [], "children": [], "wars": [{"name": "Salankamen sonrası", "when": "1691", "foe": "Habsburg", "result": "yenilgi", "note": "Tahta çıktığında bozgun olmuştu. Fâzıl Mustafa ölmüştü."}, {"name": "Sakız", "when": "1694-1695", "foe": "Venedik", "result": "yenilgi", "note": "Ada basıldı. Kurtarma emri verdi, tamamlayamadan öldü. Ada sonra geri alındı."}], "legends": [], "sources": [{"title": "TDV İslâm Ansiklopedisi, II. Ahmed", "url": "https://islamansiklopedisi.org.tr/ahmed-ii"}], "aliases": []}, {"id": "mustafa-ii", "name": "II. Mustafa", "title": "Sultan", "claim": false, "birth": 1664, "birthNote": "8 Zilkade 1074 / 2 Haziran 1664, Edirne. Babası IV. Mehmed, annesi Gülnûş Emetullah. Doğumda yedi gün şenlik.", "death": 1703, "deathNote": "Muhtemelen 20 Şâban 1115 / 29 Aralık 1703, Edirne. İstiska ve mesane hastalığı, tahttan indirilmenin üzüntüsü. Bazı Batı kaynakları zehir söylentisini halk kanaati diye yazar; TDV bunu kanaat diye aktarır, olgu diye kesinlemez. Hal' 1703 Edirne Vakası.", "reign": [1695, 1703], "reignNote": "Amcası II. Ahmed'in 6 Şubat 1695 ölümünden sonra tahta çıktı. 1703'te Edirne Vakası ile indirildi. Ölüm aynı yıl Aralık.", "summary": "Bizzat üç Avusturya seferine çıktı. 1697 Zenta bozgunu 1699 Karlofça'ya giden yolu açtı. Macaristan hattı, Mora'nın bir kısmı ve Podolya bırakıldı. Hocası Feyzullah Efendi'nin nüfuzu Edirne Vakası'nın hedefi oldu. Yerine kardeşi III. Ahmed çıktı.", "traits": ["Seferde zırh ve sorguçla görünen, gazi tipini deneyen son örneklerden. Edirne'yi İstanbul'a tercih etmesi payitaht gerilimi yarattı."], "contribution": "Kişisel seferleri orduyu bir süre toparladı. Karlofça, ağır da olsa çok cepheli savaşı kapattı ve diplomasi dönemini açtı.", "harm": "Zenta ve Karlofça, 1526'dan beri tutulan Macaristan'ın elden çıkışının belgesidir. Feyzullah nüfuzu merkezî meşruiyeti yıprattı. Edirne'de oturması İstanbul ocaklarını isyana itti.", "wives": [{"name": "Sâliha Sultan", "note": "I. Mahmud'un annesi. 1680 doğumlu ve Rum asıllı olduğu ileri sürülür. 2 Ağustos 1696'da Edirne'de Mahmud'u doğurdu.", "certainty": "olasi"}, {"name": "Şehsuvar Vâlide Sultan", "note": "III. Osman'ın annesi.", "certainty": "kesin"}], "children": [{"name": "Mahmud", "mother": "Sâliha Sultan", "note": "2 Ağustos 1696 Edirne. I. Mahmud.", "certainty": "kesin"}, {"name": "Osman", "mother": "Şehsuvar", "note": "3 Ocak 1699 Edirne. III. Osman.", "certainty": "kesin"}, {"name": "Diğer şehzadeler", "mother": null, "note": "Edirne Vakası sonrası kardeşleriyle İstanbul'a getirildiler. Adları bu okumada dökülmedi.", "certainty": "olasi"}], "wars": [{"name": "Avusturya seferleri", "when": "1695-1697", "foe": "Habsburg", "result": "sonucsuz", "note": "1695'te bizzat çıktı. Kalıcı dönüş olmadı."}, {"name": "Zenta", "when": "1697", "foe": "Habsburg (Eugen)", "result": "yenilgi", "note": "Ağır bozgun."}, {"name": "Karlofça", "when": "1699", "foe": "Habsburg, Venedik, Lehistan, (Ruslarla İstanbul antlaşması ayrı)", "result": "antlasma", "note": "Macaristan hattı ve başka topraklar bırakıldı. TDV Osmanlılar."}], "legends": ["Zehirlenerek öldürüldüğü halk söylentisidir; TDV hastalık ve üzüntüyü esas alır."], "sources": [{"title": "TDV İslâm Ansiklopedisi, II. Mustafa", "url": "https://islamansiklopedisi.org.tr/mustafa-ii"}], "aliases": []}, {"id": "ahmed-iii", "name": "III. Ahmed", "title": "Sultan", "claim": false, "birth": 1673, "birthNote": "22 Ramazan 1084 / 31 Aralık 1673 Pazar. Babası IV. Mehmed, annesi Râbia Emetullah Gülnûş. İlk hoca Şeyh-i Sultânî Mehmed Efendi, sonra Feyzullah Efendi.", "death": 1736, "deathNote": "14 Safer 1149 / 24 Haziran 1736, altmış üç yaşında. Saltanatı 1730'da bitti; ölüm indirildikten sonradır.", "reign": [1703, 1730], "reignNote": "Edirne Vakası: 17 Ağustos 1703'te tahta çıkarılmasına karar verildi, 18 Ağustos'ta Çorlu'da hutbe okundu. 2 Ekim 1730 Patrona Halil isyanıyla feragat etti. Ölüm 1736.", "summary": "Prut (1711) Rus seferini durdurdu. Mora Venedik'ten geri alındı (1715). 1716 Petervaradin ve 1718 Pasarofça ile Tımışvar, Belgrad ve Küçük Eflak Avusturya'ya geçti. 1718-1730 görece sakin yıllar sonradan Lale Devri diye anıldı. 1723'te İran savaşı açıldı. 1730'da Patrona isyanı damadı İbrahim Paşa'yı ve kendi saltanatını bitirdi.", "traits": ["Teşrifata ve İstanbul mesiresine düşkün. İsyan başında damatlarını feda ederek tahtı korumaya çalıştı, yetmedi."], "contribution": "Prut ile Rusya'nın bir süre durdurulması, Mora'nın geri alınması, matbaanın (İbrahim Müteferrika, 1727) şeyhülislâm fetvasıyla açılması, çeşme ve yalı mimarisi. Diplomasinin savaş kadar gerekli görüldüğü bir eşik.", "harm": "Pasarofça ile Belgrad ve Tımışvar kaybı. Lale Devri harcamaları ve İran savaşı Patrona isyanının bahanesi oldu. Damatlarının boğdurulması isyanı durdurmadı. Birçok oğlu küçük yaşta öldü; hânedan daraldı.", "wives": [{"name": "Adları bu okumada tek tek dökülmeyen kadınlar", "note": "TDV: hanımlarından birçok oğlu oldu, çoğu küçük yaşta öldü. I. Mahmud'un annesi Sâliha, II. Mustafa'nın kadınıdır, III. Ahmed'in eşi değildir.", "certainty": "tartismali"}], "children": [{"name": "Mustafa", "mother": "Mihrişah Emine Sultan", "note": "28 Ocak 1717 Edirne. Sonraki III. Mustafa. Annesi Mihrişah Emine; bazı yerlerde yanlışlıkla Mihrimah yazılır.", "certainty": "kesin"}, {"name": "Abdülhamid", "mother": "Râbia Şermi Sultan", "note": "20 Mart 1725 İstanbul. Sonraki I. Abdülhamid.", "certainty": "kesin"}, {"name": "Küçük yaşta ölen oğullar", "mother": null, "note": "TDV çoğunun küçük öldüğünü söyler. Adlar uydurulmadı. 1730-1757 arasında erkek şehzade doğmaması III. Selim'in doğumunu bayram yaptırdı; bu, Ahmed'in hayatta kalan oğullarının kendi çocuklarının geç gelmesindendir.", "certainty": "kesin"}], "wars": [{"name": "Prut", "when": "1711", "foe": "Rusya (Petro)", "result": "antlasma", "note": "Baltacı Mehmed Paşa. Rus ordusu kuşatıldı, antlaşmayla çıkarıldı. Tam yok etme olmadı."}, {"name": "Mora", "when": "1715", "foe": "Venedik", "result": "zafer", "note": "Yarımada geri alındı."}, {"name": "Petervaradin", "when": "1716", "foe": "Avusturya", "result": "yenilgi", "note": "Belgrad'ın kaybına giden bozgun."}, {"name": "Pasarofça", "when": "1718", "foe": "Avusturya ve Venedik", "result": "antlasma", "note": "Tımışvar, Küçük Eflak ve Belgrad Avusturya'da. Mora Osmanlı'da kaldı."}, {"name": "İran savaşı", "when": "1723-1730", "foe": "Safevî / Afgan karmaşası", "result": "sonucsuz", "note": "Onun feragatına kadar kapanmadı. I. Mahmud devrine sarktı."}], "legends": ["Lale Devri adı sonraki edebiyatın etiketidir. TDV dönemi müreffeh ve Batı'ya ilgili bir ara sayar; isyan bu ara dönemi kesti."], "sources": [{"title": "TDV İslâm Ansiklopedisi, III. Ahmed", "url": "https://islamansiklopedisi.org.tr/ahmed-iii"}], "aliases": []}, {"id": "mahmud-i", "name": "I. Mahmud", "title": "Sultan", "claim": false, "birth": 1696, "birthNote": "3 Muharrem 1108 / 2 Ağustos 1696, Edirne. Babası II. Mustafa, annesi Sâliha Sultan. Yirmi yedi yıl kafes hayatı. Kuyumculukla uğraştığı yazılır.", "death": 1754, "deathNote": "27 Safer 1168 / 13 Aralık 1754, cuma namazından dönerken Topkapı Demirkapı'da.", "reign": [1730, 1754], "reignNote": "19 Rebîülevvel 1143 / 2 Ekim 1730 Patrona isyanıyla tahta çıktı. 13 Aralık 1754'te öldü.", "summary": "Patrona artığı isyanı dağıttı. İran savaşları Nadir Şah ile gidip geldi, 1746'da Kasr-ı Şirin sınırına dönüldü. 1736-39'da Avusturya ve Rusya ile savaştı; 1739 Belgrad Antlaşması Pasarofça kayıplarının bir kısmını geri aldı. Ülkeye uzun bir barış bıraktı. Çocuğu olmadı; yerine kardeşi III. Osman geçti.", "traits": ["Kafeste kuyumculuk öğrenmiş, sefere bizzat çıkmayan, sadrazam ve Beşir Ağa dengesiyle idare eden bir padişah. TDV onu haleflerine barış bırakan son parlak dönem hükümdarı diye anar; bu övgü 1739'a göredir, sonrasız bir altın çağ iddiası değildir."], "contribution": "Belgrad'ın 1739'da geri alınması, Nadir Şah savaşının sınır değiştirmeden kapanması, İstanbul suyu (bentler, Tophane çeşmesi), Cağaloğlu Hamamı ve Ayasofya kütüphanesine gelir. Barış yılları mali nefesi genişletti.", "harm": "İran savaşları 1730-46 arasında hazineyi yordu. Nadir'in Caferîliği beşinci mezhep saydırma teklifi ulemâca reddedildi; mezhep düşmanlığı sürdü. Çocuksuzluk hânedanı kardeş koluna mecbur etti. Patrona artıklarının temizliği kanlı oldu.", "wives": [], "children": [], "wars": [{"name": "Patrona artığı", "when": "1730-1731", "foe": "İstanbul isyancıları", "result": "zafer", "note": "İsyan bastırıldı, saltanat kaldı."}, {"name": "Belgrad savaşı ve antlaşması", "when": "1739", "foe": "Avusturya ve Rusya", "result": "antlasma", "note": "Belgrad ve Pasarofça'da kaybedilen bir kısım yer geri geldi. Azak yıkılıp tampon oldu."}, {"name": "Nadir Şah savaşları", "when": "1730-1746", "foe": "İran", "result": "antlasma", "note": "1746'da Kasr-ı Şirin sınırına dönüldü. Kalıcı fetih yok."}], "legends": [], "sources": [{"title": "TDV İslâm Ansiklopedisi, I. Mahmud", "url": "https://islamansiklopedisi.org.tr/mahmud-i"}], "aliases": []}, {"id": "osman-iii", "name": "III. Osman", "title": "Sultan", "claim": false, "birth": 1699, "birthNote": "1 Receb 1110 / 3 Ocak 1699, Edirne Sarayı. Babası II. Mustafa, annesi Şehsuvar Vâlide Sultan.", "death": 1757, "deathNote": "16 Safer 1171 / 30 Ekim 1757.", "reign": [1754, 1757], "reignNote": "13 Aralık 1754'te, elli sekiz yaşında, elli üç yıl kafesten sonra tahta çıktı. 30 Ekim 1757'de öldü.", "summary": "Kısa ve çocuksuz bir saltanat. Kadınların giyimi ve sokağa çıkmasına dair yasaklar sürdü. Sadrazamlar sık değişti. Karaosmanoğlu Hacı Mustafa Ağa idam edildi. Veliaht Mehmed 1756'da öldü; zehir iddiası çağdaş eserlerde Köse Mustafa Paşa'ya bağlanır, TDV iki farklı yorum bulunduğunu söyler. Yerine III. Mustafa geçti.", "traits": ["Tebdilde ulemâ kıyafeti ve 'Edirneli Osman Ağa' diye tanıtılması nakledilir. Piştahta ve çekmece yaptığı kafes yıllarından gelir. Kadınlara karşı mesafe ve yasak siyaseti öne çıkar."], "contribution": "Müstakil bir dış zaferi yoktur. Hânedan geçişini sürdürdü. Nüfuzlu âyan örneği Karaosmanoğlu'nun idamı merkezî iddianın devamıdır, kalıcı çözüm değildir.", "harm": "Kısa saltanat ve sık azil istikrarsızlık getirdi. Kadın dolaşım yasakları sosyal hayatı sıkıştırdı. Çocuksuzluk III. Mustafa'nın şehzadeliğini tehlikeli kıldı.", "wives": [{"name": "Leylâ", "note": "Başkadınefendi. Cülusun ilk aylarından itibaren adı bilinir.", "certainty": "kesin"}, {"name": "Zevki", "note": "Üçüncü kadınefendi.", "certainty": "kesin"}, {"name": "Ferhunde Emine", "note": "Dördüncü kadınefendi.", "certainty": "kesin"}, {"name": "Dördüncü bir kadın ve ikballer", "note": "TDV: adı bilinen üçü olmak üzere dört kadın ve sayısı dörde varan ikbal. Dördüncü kadının adı bu cümlede ayrılmaz.", "certainty": "olasi"}], "children": [], "wars": [], "legends": [], "sources": [{"title": "TDV İslâm Ansiklopedisi, III. Osman", "url": "https://islamansiklopedisi.org.tr/osman-iii"}], "aliases": []}, {"id": "mustafa-iii", "name": "III. Mustafa", "title": "Sultan", "claim": false, "birth": 1717, "birthNote": "14 Safer 1129 / 28 Ocak 1717, Edirne. Babası III. Ahmed, annesi Mihrişah Emine Sultan. Mihrimah yazımı yanlıştır.", "death": 1774, "deathNote": "Oğlu III. Selim'in değil, kardeşi I. Abdülhamid'in cülusu 21 Ocak 1774'tür; III. Mustafa bu tarihte öldü. TDV Abdülhamid maddesi 'III. Mustafa'nın ölümü üzerine' der. Gün, halefin cülus günüyle aynı kaydedilir.", "reign": [1757, 1774], "reignNote": "16 Safer 1171 / 30 Ekim 1757'de tahta çıktı. 21 Ocak 1774'te öldü. Küçük Kaynarca antlaşması ölümünden sonra, 1774 yazında imzalandı.", "summary": "1768'de Rusya ile savaş açıldı. 1770 Çeşme'de donanma yakıldı. Mali birikim ilk yıllarda tükendi; oğlu Selim ve kızı Şah Sultan'dan borç aldığı TDV'de yazar. Topçuluğa meraklıydı, oğlu Selim'i bu işle yetiştirdi. Yerine kardeşi Abdülhamid geçti. Selim'i veliaht vasiyet ettiği söylenir, uygulanmadı.", "traits": ["Müneccimliğe düşkün; oğlu Selim'in 'kıran vakti'nde doğması için müdahale ettirdiği anlatılır. Askerî teknikle şahsen ilgilendi."], "contribution": "Topçu ve istihkâm ilgisi, Selim'in ileride Nizam-ı Cedid'e bağlanacak eğitiminin başlaması. Savaş öncesi birikimi seferin ilk yükünü taşıdı.", "harm": "1768 savaşı Kırım'ın elden çıkışına giden bozgundur. Çeşme donanmayı yok etti. Ölümü antlaşmayı halefine bıraktı. İç ve dış hazine boşaldı.", "wives": [{"name": "Mihrişah Sultan", "note": "III. Selim'in annesi. Gürcü veya Çerkez olduğu söylenir. Şeyhülislâm Veliyyüddin Efendi tarafından III. Mustafa'ya hediye edildiği rivayettir.", "certainty": "olasi"}], "children": [{"name": "Selim", "mother": "Mihrişah", "note": "24 Aralık 1761. Sonraki III. Selim. Kırk yıl aradan sonra doğan erkek şehzade diye kutlandı.", "certainty": "kesin"}, {"name": "Şah Sultan", "mother": null, "note": "Babası savaş masrafı için ondan ve Selim'den borç aldı. III. Osman'ın kızı Şah Sultan ile karıştırılmamalı; bu Şah, III. Mustafa'nın kızıdır.", "certainty": "kesin"}, {"name": "Toplam sekiz kız ve iki erkek", "mother": null, "note": "TDV cümlesi 'toplam sekiz kız ve iki erkek oğlu (III.' diye kesilir. İkinci erkek I. Abdülhamid değildir; o kardeşidir. İkinci oğulun adı bu kesik cümlede tamamlanmadı, uydurulmadı.", "certainty": "olasi"}], "wars": [{"name": "1768 Osmanlı-Rus savaşı", "when": "1768-1774", "foe": "Rusya", "result": "yenilgi", "note": "Onun ölümüne kadar sürdü. Küçük Kaynarca halefinin imzasıdır."}, {"name": "Çeşme", "when": "1770", "foe": "Rus donanması", "result": "yenilgi", "note": "Osmanlı donanması yakıldı."}], "legends": ["Selim'in kıran vaktinde doğması için saat ibresine müdahale edildiği anlatısı müneccim edebiyatıdır."], "sources": [{"title": "TDV İslâm Ansiklopedisi, III. Mustafa", "url": "https://islamansiklopedisi.org.tr/mustafa-iii"}], "aliases": []}, {"id": "abdulhamid-i", "name": "I. Abdülhamid", "title": "Sultan", "claim": false, "birth": 1725, "birthNote": "5 Receb 1137 / 20 Mart 1725, İstanbul. Babası III. Ahmed, annesi Râbia Şermi Sultan.", "death": 1789, "deathNote": "11 Receb 1203 / 7 Nisan 1789. Özü Kalesi'nin düştüğünü bildiren sadrazam kâğıdını okurken felç. Kırk dokuz yaşında 21 Ocak 1774'te tahta çıkmıştı.", "reign": [1774, 1789], "reignNote": "21 Ocak 1774 cülus. 7 Nisan 1789 ölüm. Küçük Kaynarca onun saltanatının başında imzalandı.", "summary": "1774 Küçük Kaynarca Kırım'ı bağımsız hanlık yaptı; bu, 1783 ilhakının eşiğiydi. İlhak 1784'te bir senetle tanındı. 1787'de Avusturya ve Rusya ile savaş başladı. 1789'da Özü haberini alırken öldü. On iki kızı ve yedi oğlu oldu, çoğu küçük yaşta öldü. Padişah olan oğulları IV. Mustafa ve II. Mahmud'dur.", "traits": ["Kırk dokuz yılın çoğunu kafeste geçirmiş, buhran içinde tahta çıkan bir padişah. Savaş haberine dayanamayıp felç geçirmesi TDV'de dramatik biçimde yazılır."], "contribution": "Kırım'ın kaybını hemen yeni bir büyük savaşla büyütmeme ihtiyatı (1787'ye kadar). Emirgân'da cami, çeşme, hamam; Beylerbeyi Camii onarımı. Halifelik sıfatı, Kırım müslümanlarının dinî bağlılığı gerekçesiyle bu dönemde siyasî dile daha çok girdi (TDV Osmanlılar, Beydilli).", "harm": "Küçük Kaynarca: Kırım'ın bağımsızlığı, Karadeniz'in Rus gemilerine açılması, Ortodoks tebaa üzerinde Rus himaye iddiasının dayanağı. 1783 ilhakının tanınması. 1787 savaşı bozgunla sürdü. Özü katliamı ölüm haberinin parçasıdır.", "wives": [{"name": "Nakşidil Sultan", "note": "II. Mahmud'un annesi. Fransız asıllı olduğu iddiası TDV Mahmud maddesinde yanlıştır.", "certainty": "kesin"}, {"name": "Ayşe Sîneperver Sultan", "note": "IV. Mustafa'nın annesi.", "certainty": "kesin"}, {"name": "Hümâşah Sultan", "note": "TDV, 1783'te Emirgân'da eşi Hümâşah ve oğlu Mehmed için çeşme yaptırdığını yazar. Bu Hümâşah, İbrahim'in hasekisi değildir.", "certainty": "olasi"}], "children": [{"name": "Mustafa", "mother": "Ayşe Sîneperver", "note": "8 Eylül 1779. IV. Mustafa.", "certainty": "kesin"}, {"name": "Mahmud", "mother": "Nakşidil", "note": "20 Temmuz 1785. II. Mahmud.", "certainty": "kesin"}, {"name": "Mehmed", "mother": "Hümâşah?", "note": "Çeşme kaydında adı geçer. Padişah olmadı.", "certainty": "olasi"}, {"name": "Diğerleri", "mother": null, "note": "On iki kız ve yedi oğulun çoğu küçük öldü. Adı geçmeyenler yazılmadı.", "certainty": "kesin"}], "wars": [{"name": "Küçük Kaynarca", "when": "1774", "foe": "Rusya", "result": "antlasma", "note": "Savaş III. Mustafa döneminde açıldı. Antlaşma Abdülhamid saltanatındadır. Kırım bağımsız hanlık oldu."}, {"name": "1787-1792 savaşı", "when": "1787-1789", "foe": "Rusya ve Avusturya", "result": "yenilgi", "note": "Onun ölümüne kadar bozgun. Yaş ve Ziştovi antlaşmaları halefi III. Selim döneminde kapandı."}], "legends": ["Nakşidil'in Aimée du Buc de Rivéry olduğu anlatısı popülerdir. TDV Mahmud maddesi Fransız asıllı iddiayı doğru bulmaz."], "sources": [{"title": "TDV İslâm Ansiklopedisi, I. Abdülhamid", "url": "https://islamansiklopedisi.org.tr/abdulhamid-i"}], "aliases": []}, {"id": "selim-iii", "name": "III. Selim", "title": "Sultan", "claim": false, "birth": 1761, "birthNote": "27 Cemâziyelevvel 1175 / 24 Aralık 1761 (Vâsıf). Babası III. Mustafa, annesi Mihrişah. Kırk yıl aradan sonra doğan erkek şehzade.", "death": 1808, "deathNote": "Tahttan indiriliş 29 Mayıs 1807 (Kabakçı). Öldürülüş 28 Temmuz 1808: Alemdar Mustafa Paşa saraya yürüyünce IV. Mustafa'nın emriyle boğuldu. TDV Mustafa IV maddesi.", "reign": [1789, 1807], "reignNote": "11 Receb 1203 / 7 Nisan 1789 cülus. 29 Mayıs 1807 hal'. Öldürülme 28 Temmuz 1808.", "summary": "Nizam-ı Cedid ordusunu ve irad-ı cedidi kurdu. 1791 Ziştovi ve 1792 Yaş antlaşmaları 1787 savaşını kapattı. 1798'de Fransa Mısır'a girdi. Âyanlar (Pazvandoğlu, Tepedelenli) ile yaşamak zorunda kaldı. 1807'de Kabakçı isyanıyla indirildi. Ertesi yıl kurtarılmak istenirken öldürüldü. Tahta çıktıktan sonra doğan Ahmed adlı oğlu yaşamadı.", "traits": ["Bestekâr, Fransız kralıyla yazışacak kadar Avrupa siyasetini izleyen, ıslahatı baba mirası sayan bir padişah. Şehzadeliğinde tahta çıkma özlemini gizlemediği TDV'de yazar."], "contribution": "Nizam-ı Cedid, sürekli elçiliklerin başlaması, ordu ve maliyede yeni usul denemesi. Sonraki II. Mahmud reformlarının zeminidir.", "harm": "Islahat yeniçeri ve ulemâ koalisyonunu isyana götürdü. Mısır'ın Fransız işgali ve Napoléon savaşlarının Osmanlı'yı Rusya-İngiltere ile karşı karşıya bırakması. Âyanlara tahammül merkezî otoriteyi böldü. Öldürülmesi 1808 buhranını kanlı açtı.", "wives": [], "children": [{"name": "Ahmed", "mother": null, "note": "Tahttan sonra doğdu, fazla yaşamadı. Karal, Selim'in hatt-ı hümâyunları. Başka oğlu olmadı; bu yüzden Mustafa ve Mahmud şefkat gördü.", "certainty": "olasi"}], "wars": [{"name": "Yaş ve Ziştovi", "when": "1791-1792", "foe": "Avusturya ve Rusya", "result": "antlasma", "note": "1787 savaşının kapanışı. Kırım geri gelmedi."}, {"name": "Fransa'nın Mısır seferi", "when": "1798-1801", "foe": "Fransa", "result": "zafer", "note": "İşgal oldu, sonra Fransızlar çıktı. Osmanlı açısından ağır sarsıntı, sonunda toprak geri geldi."}, {"name": "Kabakçı isyanı", "when": "1807", "foe": "Yeniçeri ve yamaklar", "result": "yenilgi", "note": "Nizam-ı Cedid dağıtıldı, padişah indirildi."}], "legends": [], "sources": [{"title": "TDV İslâm Ansiklopedisi, III. Selim", "url": "https://islamansiklopedisi.org.tr/selim-iii"}], "aliases": []}, {"id": "mustafa-iv", "name": "IV. Mustafa", "title": "Sultan", "claim": false, "birth": 1779, "birthNote": "26 Şâban 1193 / 8 Eylül 1779. Babası I. Abdülhamid, annesi Ayşe Sîneperver.", "death": 1808, "deathNote": "28 Ramazan 1223 / 17 Kasım 1808. Alemdar'ın öldürülmesi ve isyancıların saraya yürümesi üzerine II. Mahmud'un emriyle, belindeki kuşakla boğuldu.", "reign": [1807, 1808], "reignNote": "29 Mayıs 1807 Kabakçı isyanıyla tahta çıktı. 28 Temmuz 1808'de Alemdar tarafından indirildi, yerine II. Mahmud geçti. Öldürülme 17 Kasım 1808.", "summary": "III. Selim'in indirilmesi üzerine çıktı. Nizam-ı Cedid'i tasfiye etti. Alemdar İstanbul'a gelince Selim'i öldürtüp tahtı kurtarmak istedi; Selim ölünce hânedanın son erkeği Mahmud tahta geçti. Kasım 1808'de kendisi de boğuldu.", "traits": ["Selim'e muhalefetin içindeydi. Kız kardeşi Esmâ Sultan dahil yakınları yeniçeriler arasında taht çalışması yaptı. Kısa saltanatı darbe ve karşı darbeyle doludur."], "contribution": "Kurumsal bir ıslahatı yoktur. Hânedanın Mahmud'da sürmesi, onun Selim'i öldürtmesinin istenmeyen sonucudur.", "harm": "III. Selim'in katli. Nizam-ı Cedid'in dağıtılması. 1808'de İstanbul'un iki darbe arasında harap olması.", "wives": [], "children": [], "wars": [{"name": "1806 Rus ve İngiliz savaşı", "when": "1807-1808", "foe": "Rusya ve İngiltere", "result": "sonucsuz", "note": "Savaş II. Mahmud'a kaldı. Onun kısa saltanatında cephe kapanmadı."}], "legends": [], "sources": [{"title": "TDV İslâm Ansiklopedisi, IV. Mustafa", "url": "https://islamansiklopedisi.org.tr/mustafa-iv"}], "aliases": []}, {"id": "mahmud-ii", "name": "II. Mahmud", "title": "Sultan", "claim": false, "birth": 1785, "birthNote": "13 Ramazan 1199 / 20 Temmuz 1785. Babası I. Abdülhamid, annesi Nakşidil. Fransız asıllı anne iddiası TDV'de yanlıştır. Mahlası Adlî.", "death": 1839, "deathNote": "TDV Mahmud maddesi: 26 Haziran'da oğlu Abdülmecid ve eşi Bezmiâlem ile vedalaştı, 28 Haziran'da öldü (Münch). Abdülmecid maddesi babasının ölümünü 1 Temmuz 1839 diye yazar. İki tarih çatışır; yıl 1839'tur, gün yutulmaz.", "reign": [1808, 1839], "reignNote": "4 Cemâziyelâhir 1223 / 28 Temmuz 1808 cülus. Ölüm Haziran sonu veya 1 Temmuz 1839.", "summary": "Alemdar'ın kısa sadareti ve Sened-i İttifak ile başladı. 1826'da Yeniçeri Ocağı'nı kaldırdı (Vaka-i Hayriye) ve Asakir-i Mansure'yi kurdu. Sırp ve Yunan isyanları, Navarin (1827), 1829 Edirne Antlaşması ve Mısır valisi Mehmed Ali'nin isyanı (Nizip, 1839) saltanatını doldurdu. Ölürken oğluna reformu sürdürmesini vasiyet etti.", "traits": ["Yabancı dil bilmez, çocuklarının bilmesini isterdi. Darbelerle başlayan saltanatı aynı yoğunlukta sürdü. Merkezîleştirici ve ıslahatçı."], "contribution": "Yeniçeri Ocağı'nın kaldırılması modern ordu ve bürokrasinin kapısıdır. Âyanların te'dibi merkezî idareyi kısmen topladı. Bektaşi tekkelerinin kapatılması ve ulemâ üzerinden meşruiyet arayışı 1826'nın parçasıdır. Eğitim ve kıyafet düzenlemeleri Tanzimat'ın eşiğidir.", "harm": "Yunanistan'ın bağımsızlığa giden yolu ve Navarin'de donanmanın yanması. Edirne 1829 ile toprak ve tazminat. Mehmed Ali'ye karşı Nizip bozgunu ve ölüm döşeğinde Kütahya-Londra buhranı. Yeniçeri kıyımı İstanbul'da kanlı bir iç savaştır. Sırp özerkliği genişledi.", "wives": [{"name": "Bezmiâlem Sultan", "note": "Abdülmecid'in annesi. 1839'da yaklaşık otuz dört yaşındaydı. Vâlide sultan oldu.", "certainty": "kesin"}, {"name": "Pertevniyal Vâlide Sultan", "note": "Abdülaziz'in annesi.", "certainty": "kesin"}], "children": [{"name": "Abdülmecid", "mother": "Bezmiâlem", "note": "25 Nisan 1823. Halef.", "certainty": "kesin"}, {"name": "Abdülaziz", "mother": "Pertevniyal", "note": "7-8 Şubat 1830 gecesi. Sonraki sultan.", "certainty": "kesin"}, {"name": "Sâliha", "mother": null, "note": "Ölümünde hayatta olan dört kızdan biri.", "certainty": "kesin"}, {"name": "Atiyye", "mother": null, "note": "Aynı liste.", "certainty": "kesin"}, {"name": "Hatice", "mother": null, "note": "Aynı liste.", "certainty": "kesin"}, {"name": "Âdile", "mother": null, "note": "Aynı liste. TDV: geride iki erkek ve bu dört kız kaldı.", "certainty": "kesin"}], "wars": [{"name": "Navarin", "when": "1827", "foe": "İngiliz, Fransız ve Rus donanmaları", "result": "yenilgi", "note": "Osmanlı-Mısır donanması yakıldı. Yunan isyanının dönüm noktası."}, {"name": "Edirne Antlaşması", "when": "1829", "foe": "Rusya", "result": "antlasma", "note": "1828-29 savaşının kapanışı. Ağır şartlar."}, {"name": "Nizip", "when": "1839", "foe": "Mısır, İbrahim Paşa", "result": "yenilgi", "note": "Ölümünden hemen önce. Ordu dağıldı. Kaptan-ı derya Ahmet Fevzi Paşa'nın donanmayı Mısır'a götürmesi aynı buhrandadır."}], "legends": [], "sources": [{"title": "TDV İslâm Ansiklopedisi, II. Mahmud", "url": "https://islamansiklopedisi.org.tr/mahmud-ii"}], "aliases": []}, {"id": "abdulmecid", "name": "Abdülmecid", "title": "Sultan", "claim": false, "birth": 1823, "birthNote": "25 Nisan 1823, İstanbul. Babası II. Mahmud, annesi Bezmiâlem. Fransızca öğrendi.", "death": 1861, "deathNote": "25 Haziran 1861, otuz dokuz yaşında, Ihlamur Köşkü, tüberküloz. Yavuz Selim Türbesi yanına defnedildi.", "reign": [1839, 1861], "reignNote": "1 Temmuz 1839'da, on yedi yaşında tahta çıktı. 25 Haziran 1861'de öldü.", "summary": "Gülhane Hatt-ı Hümâyunu (1839) ve Islahat Fermanı (1856) onun saltanatındadır. Mısır buhranı Londra mukaveleleriyle durduruldu. Kırım Savaşı'nda (1853-56) İngiltere ve Fransa ile Rusya'ya karşı duruldu, Paris Antlaşması imzalandı. Borç ve sarraf senedi seksen milyon altın lirayı aştı. Dört oğlu sonradan padişah oldu: Murad, Abdülhamid, Reşad, Vahdeddin.", "traits": ["Batı müziği ve yaşayışına hayran, çevresinin ve kadınlarının telkiniyle hareket eden, tecrübesiz başlayıp ıslahatı bürokrasiye bırakan bir padişah. Babası gibi tüberkülozdan öldü."], "contribution": "Tanzimat'ın hukukî çerçevesi: can, mal, ırz güvencesi ve gayrimüslimlere yeni statü iddiası. Kırım Savaşı'nın ittifakla kazanılması imparatorluğun Avrupa dengesine bir süre daha girmesini sağladı. Bezmiâlem Gureba Hastanesi, Galata Köprüsü, Dolmabahçe'nin yükselişi bu devirdedir.", "harm": "Dış borç ve sarraf senedi mali bağımlılığı büyüttü. Islahat Fermanı büyük devlet müdahalesine kapı araladı. Lübnan-Şam olaylarında (1860) konsolosların öldürülmesi dış baskıyı arttırdı. Saray harcaması borçla birlikte anılır.", "wives": [{"name": "Şevkefza (Şevkiefser) Kadın", "note": "V. Murad'ın annesi. TDV Murad V: Şevkiefser Kadıefendi.", "certainty": "kesin"}, {"name": "Tirimüjgan Kadın", "note": "II. Abdülhamid'in annesi. Oğlu on bir yaşındayken öldü.", "certainty": "kesin"}, {"name": "Gülcemal Kadın", "note": "V. Mehmed Reşad'ın annesi.", "certainty": "kesin"}, {"name": "Gülistü Kadın", "note": "VI. Mehmed'in annesi. Yazımı Gülistü / Gülüstü değişir. TDV Mehmed VI: Gülistü Kadınefendi.", "certainty": "kesin"}, {"name": "Şâyeste Hanım", "note": "Vahdeddin'in üvey annesi. Öz anne dört yaşında ölünce onu büyüttü. Eş statüsü kadınefendi olarak anılır.", "certainty": "olasi"}], "children": [{"name": "Murad", "mother": "Şevkefza", "note": "22 Eylül 1840. V. Murad.", "certainty": "kesin"}, {"name": "Abdülhamid", "mother": "Tirimüjgan", "note": "21 Eylül 1842. II. Abdülhamid.", "certainty": "kesin"}, {"name": "Mehmed Reşad", "mother": "Gülcemal", "note": "2 Kasım 1844. V. Mehmed.", "certainty": "kesin"}, {"name": "Mehmed Vahdeddin", "mother": "Gülistü", "note": "4 Ocak 1861. VI. Mehmed. Babası altı aylıkken öldü.", "certainty": "kesin"}, {"name": "Diğer çocuklar", "mother": null, "note": "TDV Abdülmecid maddesi padişah olan dört oğlu sayar. Kızlar ve diğer şehzadeler bu okumada tek tek dökülmedi.", "certainty": "tartismali"}], "wars": [{"name": "Londra Mukavelesi / Mısır", "when": "1840-1841", "foe": "Mısır, Mehmed Ali", "result": "antlasma", "note": "Mısır Osmanlı'ya bağlı hidivliğe çekildi. Suriye geri geldi."}, {"name": "Kırım Savaşı", "when": "1853-1856", "foe": "Rusya", "result": "zafer", "note": "İngiltere, Fransa ve Piyemonte ile. Paris Antlaşması 1856. Karadeniz tarafsızlığı geçiciydi."}], "legends": [], "sources": [{"title": "TDV İslâm Ansiklopedisi, Abdülmecid", "url": "https://islamansiklopedisi.org.tr/abdulmecid"}], "aliases": []}, {"id": "abdulaziz", "name": "Abdülaziz", "title": "Sultan", "claim": false, "birth": 1830, "birthNote": "7-8 Şubat 1830 gecesi. Babası II. Mahmud, annesi Pertevniyal.", "death": 1876, "deathNote": "30 Mayıs 1876'da hal' edildi, Fer'iye'ye nakledildi. 4 Haziran 1876'da odasında bilek damarları kesilmiş bulundu. Resmî ilan intihar (Ceride-i Havadis, 6 Haziran 1876). 1881 Yıldız mahkemesi cinayet kanaatine vardı. TDV meseleyi günümüze kadar süren bir tartışma diye yazar: intihar mı, öldürülme mi tek hükümle kapanmış değildir.", "reign": [1861, 1876], "reignNote": "25 Haziran 1861'de tahta çıktı. 30 Mayıs 1876'da hal'. Ölüm 4 Haziran 1876.", "summary": "İlk yıllar Âlî ve Fuad paşalarla Tanzimat çizgisini sürdürdü. Donanma ve eğitim (Galatasaray, Darüşşafaka, ıslahhaneler) genişledi. 1867'de Avrupa'ya giden ilk padişahtır. 1875 mali iflas, Hersek ve Bulgar isyanları, 1876 medrese gösterileri hal' ile bitti. Yerine yeğeni V. Murad çıkarıldı.", "traits": ["Şehzadeliğinde içki ve sefahatten uzak, güreş, av ve cirit meraklısı diye sevildi. TDV saltanatında istibdad ve israfa meylettiğini, ilk dönemde Âlî ve Fuad'ın bunu frenlediğini yazar. Ney ve musiki dersi almıştı."], "contribution": "Donanmanın büyütülmesi, rüşdiye ve Galatasaray, Darüşşafaka, ıslahhaneler, demiryolu ve bayındırlık hamlesi. Avrupa seyahati diplomatik görünürlük sağladı.", "harm": "Borç ve 1875 iflası. Hersek-Bulgar isyanlarının bastırılmasındaki şiddet Avrupa müdahalesini hızlandırdı. Hal' ve şüpheli ölüm meşrutiyet darbesinin kanlı eşiğidir. İstibdad eğilimi meşvereti daralttı.", "wives": [], "children": [{"name": "Yusuf İzzeddin", "mother": null, "note": "Veliaht şehzade. 1 Şubat 1916'da intihar ettiği TDV Mehmed VI maddesinde geçer. Annesinin adı bu okumada Abdülaziz maddesinden çıkarılmadı.", "certainty": "kesin"}, {"name": "Diğer çocuklar", "mother": null, "note": "Abdülaziz maddesinin okunan kısmı çocuk listesini tamamlamaz. Ad uydurulmadı.", "certainty": "tartismali"}], "wars": [{"name": "Hersek ve Bulgar isyanları", "when": "1875-1876", "foe": "İsyancı gruplar, büyük devlet diplomasisi", "result": "sonucsuz", "note": "1876'da Bulgaristan'a sıçradı. Selânik'te iki konsolosun öldürülmesi Berlin Memorandumu hazırlığına yol açtı. Savaş hali hal' ile iç siyasete döndü."}], "legends": ["İntihar ile cinayet tartışması kapanmamıştır. 1876 resmî ilan intihar, 1881 mahkemesi katil dedi. TDV ikisini de hükme bağlamaz."], "sources": [{"title": "TDV İslâm Ansiklopedisi, Abdülaziz", "url": "https://islamansiklopedisi.org.tr/abdulaziz"}], "aliases": []}, {"id": "murad-v", "name": "V. Murad", "title": "Sultan", "claim": false, "birth": 1840, "birthNote": "25 Receb 1256 / 22 Eylül 1840. Asıl adı Mehmed. Babası Abdülmecid, annesi Şevkiefser Kadınefendi.", "death": 1904, "deathNote": "29 Ağustos 1904, şeker hastalığı. Çırağan'da uzun mahpusluktan sonra. Yenicami Cedid Havatin Türbesi'nde annesinin yanına defnedildi.", "reign": [1876, 1876], "reignNote": "30 Mayıs 1876'da amcasının hal'iyle tahta çıktı. 31 Ağustos 1876'da hal' edildi, yerine kardeşi II. Abdülhamid geçti. Saltanat yaklaşık doksan üç gündür. Ölüm 1904.", "summary": "Yeni Osmanlılar ve Namık Kemal çevresiyle teması vardı. Tahta çıkınca sinir buhranı geçirdi, cülus töreni alışılmış altın taht usulüyle tamamlanamadı. 31 Ağustos 1876'da akıl sağlığı gerekçesiyle indirildi. Çırağan'da Ali Suavi'nin 1878 kaçırma teşebbüsü ve başka planlar başarısız kaldı.", "traits": ["Yumuşak tabiatlı, piyano ve Batı müziği öğrenmiş, meşrutiyetçi çevreyle konuşmuş bir şehzade. Tahtta en kısa kalan padişahlardandır. Hal' sonrası teşhis siyasîdir; TDV buhranı anlatır, tek klinik etiket koymaz."], "contribution": "Meşrutiyet fikrinin saray içine sızmış ilk padişah adayı olması. Fiilî reform yapacak süresi olmadı.", "harm": "Hal' süreci Kanun-ı Esasî'yi II. Abdülhamid'in pazarlığına bıraktı. Kaçırma teşebbüsleri Çırağan'ı sürekli kriz odağı yaptı.", "wives": [], "children": [], "wars": [], "legends": ["Mason locasıyla ilişkisi ve tahta masonlarca çıkarılacağı iddiası dönem dedikodusudur. TDV, Cleanti Scalieri-Aziz Bey komitesinin 1876 sonrası kaçırma planını anar."], "sources": [{"title": "TDV İslâm Ansiklopedisi, V. Murad", "url": "https://islamansiklopedisi.org.tr/murad-v"}], "aliases": []}, {"id": "abdulhamid-ii", "name": "II. Abdülhamid", "title": "Sultan", "claim": false, "birth": 1842, "birthNote": "21 Eylül 1842. Babası Abdülmecid, annesi Tirimüjgan. Annesi on bir yaşındayken öldü. Piristû Kadın analık etti. Pertevniyal'in yardımıyla Abdülaziz'e yaklaşabildi.", "death": 1918, "deathNote": "10 Şubat 1918 Pazar. Topkapı'da techiz. Beylerbeyi'nde göz hapsinden sonra. Saltanatı 1909'da bitti.", "reign": [1876, 1909], "reignNote": "31 Ağustos 1876 cülus. 27 Nisan 1909'da 31 Mart Vakası ardından Meclis-i Umumi tarafından hal'. Ölüm 10 Şubat 1918.", "summary": "1876 Kanun-ı Esasî ve I. Meşrutiyet, 1877-78 Osmanlı-Rus savaşı, Ayastefanos ve Berlin antlaşmalarıyla geniş Balkan ve Kafkas kaybı. 1878'de meclisi tatil etti. 1908'de II. Meşrutiyet ilan edildi. 31 Mart 1909'da indirildi. Eğitim, demiryolu (Hicaz) ve merkezî istihbarat bu uzun saltanatın araçlarıdır. 'Kızıl Sultan' yaftası muhalif edebiyattır; TDV hem istibdadı hem modernleştirici yüzü anlatır.", "traits": ["Çocukluğundan yalnız, kuşkucu, kurnaza karşı kurnaz hareket edeceğini kendisi söyleyen bir padişah. Çalışkan, teferruata boğulan, merkezî."], "contribution": "Mülkî idare, maarif, telgraf, Hicaz demiryolu, Ziraat Bankası ve aşiret mektebi gibi kurumlar. 1878 sonrası büyük bir dağılmayı yavaşlattı. Meşrutiyeti 1908'de, baskı altında da olsa, yeniden açtı.", "harm": "1877-78 savaşının toprak kaybı ve muhacir dalgası. 1878 meclis tatili ve sürgünler (Midhat Paşa dahil) siyaseti kapattı. Ermeni olayları ve dış basındaki katliam anlatıları meşruiyeti yıprattı; ayrıntılı yargı bu kartın okuduğu pasajda tek cümleyle kapanmaz. 31 Mart'ın bastırılması ve hal', meşrutiyetçi subayların fiilî iktidarını başlattı.", "wives": [], "children": [], "wars": [{"name": "1877-78 Osmanlı-Rus savaşı", "when": "1877-1878", "foe": "Rusya", "result": "yenilgi", "note": "Ayastefanos ardından Berlin Antlaşması. Balkanlar'da büyük kayıp, Kars-Ardahan elden çıktı."}, {"name": "31 Mart Vakası", "when": "1909-04", "foe": "İstanbul ayaklanması / Hareket Ordusu", "result": "yenilgi", "note": "Hareket Ordusu bastırdı. 27 Nisan 1909 hal'."}], "legends": ["Ermeni kökenli olduğu veya sarayda gizli bir ikinci hayatı olduğu iddiaları siyasî karalamadır. TDV soyunu Abdülmecid ve Tirimüjgan diye verir."], "sources": [{"title": "TDV İslâm Ansiklopedisi, II. Abdülhamid", "url": "https://islamansiklopedisi.org.tr/abdulhamid-ii"}], "aliases": []}, {"id": "mehmed-v", "name": "V. Mehmed Reşad", "title": "Sultan", "claim": false, "birth": 1844, "birthNote": "2 Kasım 1844, Çırağan Sarayı. Babası Abdülmecid, annesi Gülcemal Kadınefendi.", "death": 1918, "deathNote": "3 Temmuz 1918. Mondros'u göremeden öldü. Eyüp'te sağlığında yaptırdığı türbeye defnedildi.", "reign": [1909, 1918], "reignNote": "27 Nisan 1909 cülus. Beşinci Mehmed unvanı, halk arasında Sultan Reşad. Ölüm 3 Temmuz 1918. Fiilî iktidar İttihat ve Terakki'dedir.", "summary": "31 Mart sonrası çıkarıldı. Trablusgarp (1911), Balkan savaşları (1912-13) ve I. Dünya Savaşı onun adına yürütüldü. Çanakkale savunması bu saltanattadır. Kendisi halim, yaşlı ve siyaseten zayıftı; sadrazamlar ve İttihatçı liderler karar verdi. 1918'de öldü, yerine kardeşi Vahdeddin geçti.", "traits": ["TDV: halim selim, merhametli, dindar, nazik. Abdülhamid döneminde göz hapsi onu korkulu ve çekingen kılmıştı. Son yıllarda evrakı yatağında imzaladı."], "contribution": "Çanakkale'nin tutulması başkentin düşmesini önledi. Meşrutiyet kurumları kâğıt üzerinde sürdü. Kişisel bir ıslahat liderliği yoktur.", "harm": "Balkan savaşlarında Rumeli'nin büyük kısmı kaybedildi. I. Dünya Savaşı'na giriş milyonlarca insanın ölümü, açlık ve imparatorluğun dağılmasıyla bitti. Padişah bu kararların sembolik sorumlusudur; operasyonel karar Enver, Talat ve Cemal çevresindedir. Ermeni tehciri bu savaşın içindedir; TDV Mehmed V maddesinin okunan kısmı tehciri ayrıca hükme bağlamaz, savaşın buhranı kayıtlıdır.", "wives": [], "children": [], "wars": [{"name": "Trablusgarp", "when": "1911-1912", "foe": "İtalya", "result": "yenilgi", "note": "Kuzey Afrika fiilen elden çıktı. Uşi/Lozan 1912."}, {"name": "Balkan savaşları", "when": "1912-1913", "foe": "Balkan ittifakı", "result": "yenilgi", "note": "Edirne 1913'te geri alındı, Makedonya ve Arnavutluk hattı gitti."}, {"name": "I. Dünya Savaşı", "when": "1914-1918", "foe": "İtilaf devletleri", "result": "yenilgi", "note": "Çanakkale tutuldu (1915). Genel sonuç 1918 bozgunudur. Mondros padişahın ölümünden sonradır."}, {"name": "Çanakkale", "when": "1915", "foe": "İngiliz ve Fransız donanma ve orduları", "result": "zafer", "note": "Boğaz geçilemedi."}], "legends": [], "sources": [{"title": "TDV İslâm Ansiklopedisi, V. Mehmed Reşad", "url": "https://islamansiklopedisi.org.tr/mehmed-v"}], "aliases": []}, {"id": "mehmed-vi", "name": "VI. Mehmed Vahdeddin", "title": "Son Osmanlı padişahı", "claim": false, "birth": 1861, "birthNote": "4 Ocak 1861, Dolmabahçe. Babası Abdülmecid, annesi Gülistü Kadınefendi. Gülüstü yazılışı da kullanılır; TDV Gülistü yazar. Altı aylıkken babası, dört yaşında annesi öldü. Üvey annesi Şâyeste Hanım büyüttü.", "death": 1926, "deathNote": "16 Mayıs 1926, San Remo, Villa Magnolia / Mamolya. Borç ve haciz yüzünden cenaze alıkondu. 15 Haziran'da Trieste'ye, oradan Beyrut ve Şam'a götürüldü, 3 Temmuz 1926'da defnedildi. Şam Süleymaniye/Selimiye külliyesi haziresi.", "reign": [1918, 1922], "reignNote": "Reşad 3 Temmuz 1918'de öldü. TDV, VI. Mehmed'in bunun üzerine tahta çıkarıldığını yazar, cümlede '4 Temmuz' gününü ayrıca söylemez. Yaygın kayıt cülusu 4 Temmuz 1918 diye verir; gün, ölümün ertesi günüdür. Saltanat 1 Kasım 1922'de kaldırıldı. İstanbul'dan ayrılış 17 Kasım 1922 Cuma, Malaya gemisi. Hilâfet iddiasını bırakmadığını Malta'da ve sonrasında tekrarladı. TBMM 19 Kasım 1922'de Abdülmecid Efendi'yi halife seçti.", "summary": "Veliaht Yusuf İzzeddin'in 1 Şubat 1916 intiharından sonra veliaht oldu. 1918'de tahta çıktı, Mondros ve Sevr sürecinde Damad Ferid hükümetleriyle İstanbul'un işgaline (16 Mart 1920) tanık oldu. Millî Mücadele'ye mesafeli ve zaman zaman karşı durdu; hilâfet ve saltanatı İngiliz desteğiyle koruyacağını sandı. 1 Kasım 1922'de saltanat kalkınca saltanatsız hilâfeti reddetti. 16 Kasım 1922'de General Harington'a sığınma mektubu yazdı, 17 Kasım'da ayrıldı. 16 Mayıs 1926'da San Remo'da öldü.", "traits": ["TDV, yakınlarının tanıklığıyla: iyimser, sabırlı, sarayda müşfik; törenlerde soğuk ve çatık kaşlı. Dinî geleneğe önem verir, saray dedikodusundan hoşlanmaz. İleri derecede edebiyat, musiki ve hat. Besteleri vatan hasretini anlatır. Hattı: Allah, Muhammed, Ali, Fatıma, Hasan, Hüseyin müsenna."], "contribution": "Mukaddes emanetleri götürmeyi reddedip Türk milletine ecdat armağanı sayması. Çanakkale sonrası dağılmış devlette hilâfet makamını 1922'ye kadar hukuken ayakta tutması. Şahsî musiki ve hat. Siyasî kurtuluş onun eseri değildir.", "harm": "Damad Ferid hükümetlerinin Kuva-yı Milliye aleyhine tutumu, Sevr'i görüşmeye razı saltanat şûrası (22 Temmuz 1920), Mustafa Kemal'in âsi ilanına giden hükümet kararları (Temmuz 1919). İngiliz savaş gemisiyle ayrılışı saltanatı fiilen boşalttı. TBMM onu vatan haini saydı. TDV, kaçmadığını hicret saydığını kendi hâtıratı üzerinden aktarır; bu, meclisin hükmünü değiştirmez.", "wives": [{"name": "Emine Nazikeda Kadın", "note": "Başkadın. Abhaz, Emine Marşania. 1885'te evlendiği, yirmi yıl tek eşi olduğu ve Ulviye ile Sabiha'nın annesi olduğu Uluçay ve Sakaoğlu'na dayanan soy kütüğü literatüründe ortaktır; İngilizce Vikipedi bu kitapları kaynak gösterir (Uluçay 2011, Sakaoğlu 2015). TDV Mehmed VI maddesi adını anmaz. Çapraz kabul.", "certainty": "kesin"}, {"name": "İnşirah Hanım", "note": "1905 evlilik, 1909 boşanma. Çocuğu yok. Tahttan önce ayrıldığı için saltanat kadını sayılmayabilir. Aynı soy kütüğü literatürü. TDV maddesinde adı geçmez.", "certainty": "kesin"}, {"name": "Müveddet Kadın", "note": "Şadiye Çıhçı. 1911 evlilik. Tek oğul Mehmed Ertuğrul'un annesi. TDV maddesi adı vermez; 'on yaşındaki oğlu' ifadesi 1922-23'te hayatta bir oğul bulunduğunu doğrular, ad vermez.", "certainty": "kesin"}, {"name": "Nevvare Hanım", "note": "1918 evlilik, 1924 boşanma. Çocuğu yok. TDV maddesinde adı geçmez. Soy kütüğü literatürü.", "certainty": "kesin"}, {"name": "Nevzad Hanım", "note": "TDV: saltanatın kaldırılması arefesinde, kimseye haber vermeden, câriyelerden on dokuz yaşındaki Çerkez asıllı Nevzad Hanım'la evlendi. Vikipedi/Uluçay doğum adını Nimet Bargu, evliliği 1921 diye verir. Çocuğu yok. TDV'nin bizzat andığı tek eş odur.", "certainty": "kesin"}], "children": [{"name": "Münire Fenire Sultan (veya Fenire)", "mother": "Nazikeda", "note": "1888'de doğup haftalar içinde öldü. Bazı listeler Münire ve Fenire diye iki bebek ayırır; güncel soy kütüğü çoğu zaman tek bebek (Münire Fenire) sayar. TDV adı vermez. İki ayrı bebek yazılmadı; çatışma not edildi.", "certainty": "tartismali"}, {"name": "Fatma Ulviye Sultan", "mother": "Nazikeda", "note": "1892-1967. İki evlilik. Uluçay/Sakaoğlu çizgisi ve Vikipedi çaprazı. TDV Mehmed VI maddesi adı vermez.", "certainty": "kesin"}, {"name": "Rukiye Sabiha Sultan", "mother": "Nazikeda", "note": "1894-1971. Ömer Faruk Efendi ile evlendi. Neslişah, Hanzade ve Necla'nın annesi. TDV cenaze naklini Şehzade Ömer Faruk'un nezaretinde anlatır; Sabiha'nın adını bu maddede anmaz.", "certainty": "kesin"}, {"name": "Şehzade Mehmed Ertuğrul", "mother": "Müveddet", "note": "1912 doğum, 1944 Kahire'de öldü, evlenmedi. Gün çatışması: 5 Eylül, 5 Ekim veya 5 Kasım 1912 kayıtları vardır; gün uydurulmadı, yıl 1912. TDV 'on yaşındaki oğlu' der, ad koymaz. Tek erkek evlat olduğu soy kütüğünde ortaktır.", "certainty": "kesin"}], "wars": [{"name": "Mondros Mütarekesi", "when": "1918-10-30", "foe": "İtilaf devletleri", "result": "antlasma", "note": "Onun saltanatının başında imzalandı. Fiilen teslimiyet."}, {"name": "İstanbul'un işgali", "when": "1920-03-16", "foe": "İtilaf", "result": "yenilgi", "note": "Meclis basıldı, milliyetçiler Malta'ya sürüldü. Padişah İstanbul'da kaldı."}, {"name": "Sevr", "when": "1920-08-10", "foe": "İtilaf", "result": "antlasma", "note": "Saltanat şûrası 22 Temmuz 1920'de şartları görüştü. Antlaşma Ankara tarafından reddedildi, uygulanmadı."}, {"name": "Millî Mücadele ve saltanatın kaldırılması", "when": "1919-1922", "foe": "TBMM ile İstanbul hükümeti arasında siyasî mücadele", "result": "yenilgi", "note": "1 Kasım 1922 saltanat kalktı. Büyük Taarruz ve Mudanya padişahın seferi değildir."}], "legends": ["İngiliz casusu olduğu yaftası siyasî hükümdür. TDV, İngiliz desteği aradığını ve Millî Mücadele'ye karşı durduğunu belgeler; casusluk kimliği kurmaz.", "Hicret ile kaçış tartışması: kendi hâtıratı hicret der, TBMM firar ve hıyanet der. Olayın tarihi 17 Kasım 1922'dir."], "sources": [{"title": "TDV İslâm Ansiklopedisi, VI. Mehmed Vahdeddin", "url": "https://islamansiklopedisi.org.tr/mehmed-vi"}], "aliases": []}]}, {"id": "germiyan", "name": "Germiyanoğulları Beyliği", "short": "Germiyan", "aliases": ["Germiyan Beyliği", "Yâkub-ili", "Germiyanoğulları"], "region": "anadolu", "start": 1300, "end": 1429, "startNote": "Kerîmüddin Alişîr soyundan I. Yâkub Bey 1300 civarında Kütahya merkezli müstakil beyliğini kurmuştur.", "endNote": "II. Yâkub Bey'in 1429'da erkek vârisi olmadan ölmesi ve topraklarını II. Murad'a vasiyet etmesiyle beylik Osmanlı Devleti'ne ilhak edilmiştir.", "capital": "Kütahya (bir dönem Kula)", "religion": "İslâm", "confidence": "kayit", "confidenceNote": "Beyliğin kitabeleri, taş vakfiyeleri, zengin edebi eserleri ve Osmanlı-Bizans kaynaklarında mevcudiyeti tam olarak belgelidir.", "summary": "Batı Anadolu'nun en güçlü ve teşkilatlı Türkmen beyliklerindendir. Kütahya, Uşak, Simav, Kula ve Denizli çevresine hâkim olan Germiyanlılar; Aydınoğulları, Saruhanoğulları ve Karesioğulları beyliklerinin kuruluşunda hami ve metbû rol oynamıştır. Süleyman Şah döneminde kızını Yıldırım Bayezid ile evlendirerek topraklarının bir kısmını çeyiz olarak Osmanlıya vermiş, II. Yâkub Bey'in vefatıyla da vasiyet yoluyla bütünüyle Osmanlı Devleti'ne intikal etmiştir.", "legacy": "Türk edebiyatının gelişmesinde abidevi bir rol oynamıştır; Şeyhî, Ahmedî, Ahmed-i Dâî ve Şeyhoğlu Mustafa gibi devrin büyük ediplerini yetiştirmiştir. Dokuma sanayii (Denizli bezi) ve Kütahya çinisi mirasının köklerini beslemiştir.", "essay": ["Germiyanoğulları, Hârizmşahlar bakiyesi olup Anadolu Selçuklu Devleti tarafından Malatya'dan Kütahya-Denizli uçlarına yerleştirilen güçlü bir aşiretten doğmuştur. Kerîmüddin Alişîr oğlu I. Yâkub Bey döneminde (1300-1340) beylik Batı Anadolu'nun en kudretli devleti haline gelmiş; Aydın, Saruhan ve Karesi gibi sahil beylikleri başlangıçta Germiyan subaşıları tarafından onun metbûluğunda kurulmuştur.", "I. Yâkub Bey Bizans'ı vergiye bağlamış, Alaşehir'i kuşatmış ve 40.000'i aşkın süvari ordusuyla bölgede hâkimiyet kurmuştur. Oğlu Mehmed Bey ve torunu Süleyman Şah devrinde ise Karamanoğulları baskısı ve büyüyen Osmanlı tehdidi karşısında denge siyaseti izlenmiştir. Süleyman Şah, kızı Devletşah Hatun'u I. Murad'ın oğlu Bayezid'e vererek Kütahya, Tavşanlı, Simav ve Eğrigöz'ü çeyiz olarak Osmanlılara bırakmış, kendisi Kula'ya çekilmiştir.", "II. Yâkub Bey 1389 Kosova Savaşı sonrası çeyiz topraklarını geri almak istemişse de Yıldırım Bayezid tarafından hapsedilmiştir. 1399'da kaçıp Timur'a sığınan Yâkub Bey, 1402 Ankara Savaşı'ndan sonra beyliğine kavuşmuştur. Karamanlıların saldırılarına karşı Osmanlılara yanaşan ve erkek evladı bulunmayan II. Yâkub Bey, 1428'de Edirne'ye bizzat giderek ülkesini II. Murad'a vasiyet etmiş, 1429'da vefatıyla beylik barışçı yolla Osmanlı sancağı olmuştur."], "sources": [{"title": "TDV İslâm Ansiklopedisi, GERMİYANOĞULLARI", "url": "https://islamansiklopedisi.org.tr/germiyanogullari"}, {"title": "Britannica, Germiyanids", "url": "https://en.wikipedia.org/wiki/Germiyanids"}], "rulers": [{"id": "germiyan-i-yakub-bey", "name": "I. Yâkub Bey", "aliases": ["Germiyanlı Yâkub Bey", "Yâkub b. Alişîr"], "title": "bey", "birth": null, "birthNote": "kayıtlarda yok", "death": 1340, "deathNote": "1340 civarında Kütahya'da vefat etti.", "reign": [1300, 1340], "reignNote": "Beyliğin kurucusu ve Batı Anadolu'nun en nüfuzlu ulu beyidir.", "summary": "Germiyanoğulları Beyliği'nin kurucusudur. Batı Anadolu'daki diğer Türkmen beyliklerini kendi nüfuzu altında toplamış, Bizans'ı yıllık 100.000 dinar vergiye bağlamış, İbn Fazlullah el-Ömerî tarafından devrin en büyük Türk emiri olarak vasıflandırılmıştır.", "traits": ["büyük teşkilatçı", "otoriter", "metbû hükümdar"], "contribution": "Kütahya Vâcidiye Medresesi'ni (1314) kurdurdu, Batı Anadolu'nun fethini organize etti.", "harm": "", "wives": [], "children": [{"name": "Mehmed Bey", "mother": "", "note": "Halefi, Çahşadan", "certainty": "kesin"}, {"name": "Mûsâ Bey", "mother": "", "note": "Eğridir civarı emiri", "certainty": "kesin"}], "wars": [{"name": "Alaşehir Kuşatması ve Katalan Çarpışması", "when": "1304-1306", "foe": "Bizans ve Katalan Bölüğü", "result": "belirsiz", "note": "Tripolis ve Simav alındı, Alaşehir cizyeye bağlandı."}], "legends": ["Mevlânâ'nın torunu Ulu Ârif Çelebi ile Kütahya'da görüştüğü ve manevî sohbetlerde bulunduğu Menâkıbü'l-ârifîn'de anlatılır."], "sources": [{"title": "TDV İslâm Ansiklopedisi, GERMİYANOĞULLARI", "url": "https://islamansiklopedisi.org.tr/germiyanogullari"}]}, {"id": "germiyan-mehmed-bey", "name": "Mehmed Bey", "aliases": ["Çahşadan Mehmed Bey"], "title": "bey", "birth": null, "birthNote": "kayıtlarda yok", "death": 1361, "deathNote": "1361 civarında Kütahya'da vefat etti.", "reign": [1340, 1361], "reignNote": "I. Yâkub Bey'in oğludur.", "summary": "I. Yâkub Bey'in halefidir. Katalanların eline geçmiş olan Kula ve Angir'i (Hisarköy) geri almış, beyliğin toprak bütünlüğünü korumuştur.", "traits": ["muharip"], "contribution": "Kula ve Angir kalelerini geri aldı.", "harm": "", "wives": [], "children": [{"name": "Süleyman Şah", "mother": "", "note": "Halefi, Şah Çelebi", "certainty": "kesin"}], "wars": [{"name": "Kula ve Angir Seferi", "when": "1345 civarı", "foe": "Katalan kalıntıları ve yerel Bizans kuvvetleri", "result": "zafer", "note": "Kula ve Angir kaleleri geri alındı."}], "legends": [], "sources": [{"title": "TDV İslâm Ansiklopedisi, GERMİYANOĞULLARI", "url": "https://islamansiklopedisi.org.tr/germiyanogullari"}]}, {"id": "germiyan-suleyman-sah", "name": "Süleyman Şah", "aliases": ["Şah Çelebi"], "title": "şah", "birth": null, "birthNote": "kayıtlarda yok", "death": 1387, "deathNote": "1387'de Kula'da vefat etti.", "reign": [1361, 1387], "reignNote": "Hurşîdnâme bânisidir; 1381'de kızının çeyizi olarak Kütahya'yı Osmanlıya terk edip Kula'ya çekilmiştir.", "summary": "Karamanoğulları baskısına karşı Osmanlılar ile akrabalık kurmuş, kızı Devletşah Hatun'u Şehzade Bayezid'e vererek Kütahya, Simav, Emet ve Tavşanlı'yı çeyiz olarak terk etmiştir. Sanat ve edebiyatı güçlü şekilde himaye etmiştir.", "traits": ["edebiyat hamisi", "uzlaşmacı diplomat"], "contribution": "Şeyhoğlu Mustafa ve Ahmedî gibi müellifleri himaye etti, Hurşîdnâme'nin yazılmasını sağladı.", "harm": "Başkent Kütahya dahil topraklarının en değerli kısmını Osmanlılara bırakmak zorunda kaldı.", "wives": [], "children": [{"name": "II. Yâkub Bey", "mother": "", "note": "Halefi", "certainty": "kesin"}, {"name": "Hızır Bey", "mother": "", "note": "Oğlu", "certainty": "kesin"}, {"name": "İlyas Bey", "mother": "", "note": "Oğlu", "certainty": "kesin"}, {"name": "Devletşah Hatun", "mother": "", "note": "Yıldırım Bayezid ile evlenen kızı", "certainty": "kesin"}], "wars": [{"name": "Hamîdoğulları-Karaman Mücadelesi", "when": "1370 civarı", "foe": "Karamanoğlu Alâeddin Bey", "result": "zafer", "note": "Hamîdoğlu İlyas Bey'i destekleyerek Karamanlılara karşı koydu."}], "legends": ["Kütahya'da yapılan muhteşem düğün ve gönderilen Germiyan atlasları Osmanlı tarihlerinde tafsilatla anlatılır."], "sources": [{"title": "TDV İslâm Ansiklopedisi, GERMİYANOĞULLARI", "url": "https://islamansiklopedisi.org.tr/germiyanogullari"}]}, {"id": "germiyan-ii-yakub-bey", "name": "II. Yâkub Bey", "aliases": ["Yâkub Çelebi"], "title": "çelebi", "birth": null, "birthNote": "kayıtlarda yok", "death": 1429, "deathNote": "1429 yılı başında Kütahya'da vefat etti; kendi yaptırdığı İmaret Külliyesi türbesine defnedildi.", "reign": [1387, 1390], "reignNote": "1387-1390 ilk dönemi; 1402-1411 ikinci dönemi; 1414-1429 üçüncü saltanat dönemidir.", "summary": "Germiyanoğulları'nın son beyidir. Yıldırım Bayezid tarafından İpsala'da hapsedilmiş, 1399'da firar edip Timur'a sığınarak Ankara Savaşı'ndan sonra beyliğine kavuşmuştur. Erkek çocuğu olmadığından ülkesini II. Murad'a vasiyet ederek barışçı yolla Osmanlıya bağlamıştır.", "traits": ["kültür hamisi", "hayırsever", "tecrübeli"], "contribution": "Kütahya'da Yâkub Çelebi Külliyesi ve Taş Vakfiyesi'ni bıraktı; Şeyhî Sinan ve Ahmed-i Dâî'yi himaye etti.", "harm": "1390'da tedbirsizce Osmanlıya başkaldırması esaretine ve ilk ilhaka sebep oldu.", "wives": [], "children": [], "wars": [{"name": "Kosova Meydan Muharebesi", "when": "1389", "foe": "Haçlı İttifakı", "result": "zafer", "note": "I. Murad'a yardımcı kuvvet gönderdi."}, {"name": "Ankara Meydan Muharebesi", "when": "1402", "foe": "Yıldırım Bayezid", "result": "zafer", "note": "Timur ordusunda yer alarak beyliğinin başına geçti."}, {"name": "Karaman Kuşatması ve Kütahya Savunması", "when": "1411", "foe": "Karamanoğlu Mehmed Bey", "result": "yenilgi", "note": "Kütahya Karamanlılarca yakıldı; Yâkub Bey iki buçuk yıl memleketinden uzak kaldı."}], "legends": ["1428'de Edirne sarayında II. Murad tarafından büyük hürmetle karşılandığı ve Şeyhî Sinan'ın kendisine mihmandarlık yaptığı anlatılır."], "sources": [{"title": "TDV İslâm Ansiklopedisi, GERMİYANOĞULLARI", "url": "https://islamansiklopedisi.org.tr/germiyanogullari"}, {"title": "TDV İslâm Ansiklopedisi, YÂKUB BEY", "url": "https://islamansiklopedisi.org.tr/yakub-bey"}]}]}, {"id": "hamid", "name": "Hamîdoğulları Beyliği", "short": "Hamîdoğulları", "aliases": ["Hamid Beyliği", "Hamîd-ili", "Hamidoğulları"], "region": "anadolu", "start": 1300, "end": 1391, "startNote": "Hamîd Bey'in 1297'de Uluborlu merkezli bağımsızlığı ve 1300 civarında sikke bastırması beyliğin başlangıcı sayılır.", "endNote": "1381-1382'de Akşehir, Beyşehir ve Seydişehir hattı 80.000 altın karşılığı Osmanlıya satılmış; kalan topraklar 1391'de Yıldırım Bayezid tarafından ilhak edilmiştir.", "capital": "Uluborlu (daha sonra Eğridir / Felekâbâd)", "religion": "İslâm", "confidence": "kayit", "confidenceNote": "Beyliğin kitabeleri, Dündar Bey Medresesi, sikkeleri, vakfiyeleri ve İbn Battûta seyahatnamesinde tam kayıtlıdır.", "summary": "Göller Yöresi'nde (Isparta, Burdur, Eğridir, Uluborlu, Yalvaç) kurulan Türkmen beyliğidir. Kurucusu Hamîd Bey ve torunu Feleküddin Dündar Bey zamanında gelişmiş, Dündar Bey hükümet merkezini Eğridir'e (Felekâbâd) taşımış ve kardeşi Yûnus Bey'i Antalya'ya göndererek Tekeoğulları kolunu kurmuştur. Karaman tehdidine karşı topraklarının kuzey kısmını Osmanlılara satmış, geri kalanı 1391'de Osmanlı idaresine geçmiştir.", "legacy": "Göller bölgesinin iskânını ve Türkleşmesini tamamlamış, Burdur Ulucamii, Eğridir Dündar Bey Medresesi ve Hızır Bey camileri gibi önemli Selçuklu-Beylik devri eserleri bırakmıştır.", "essay": ["Hamîdoğulları, Anadolu Selçuklu Sultanı II. Gıyâseddin Keyhusrev devrinde Kuzey Suriye'den getirilerek Isparta-Burdur uç bölgesine yerleştirilen Hamîd Bey'in aşiretinden doğmuştur. Selçuklu Devleti'nin dağılması üzerine Hamîd Bey Uluborlu merkezli bağımsızlığını ilan etmiştir.", "Beyliğin en parlak devri Feleküddin Dündar Bey zamanıdır (1307-1326). Dündar Bey başkenti Eğridir'e nakledip Felekâbâd adını vermiş, Antalya'yı fethederek kardeşi Yûnus Bey'e bırakmıştır. Ancak İlhanlı genel valisi Timurtaş'ın baskısıyla Antalya'ya kaçmış ve 1326'da orada katledilmiştir.", "Demirtaş'ın kaçışından sonra İshak Bey ve Hızır Bey beyliği yeniden toparlamış, Eşrefoğulları topraklarının bir kısmını sınırlarına katmıştır. Son dönemde Karamanoğulları'nın istila tehdidi karşısında Kemâleddin Hüseyin Bey, I. Murad'a başvurarak Akşehir, Beyşehir, Seydişehir, Yalvaç ve Şarkîkaraağaç'ı 80.000 altın karşılığı satmıştır. Kalan Eğridir-Isparta çekirdeği ise 1391'de Yıldırım Bayezid tarafından Osmanlı sancağı yapılmıştır."], "sources": [{"title": "TDV İslâm Ansiklopedisi, HAMÎDOĞULLARI", "url": "https://islamansiklopedisi.org.tr/hamidogullari"}, {"title": "Britannica, Hamid Dynasty", "url": "https://www.britannica.com/topic/Hamid-dynasty"}], "rulers": [{"id": "hamid-hamid-bey", "name": "Hamîd Bey", "aliases": ["Seyfeddin Hamîd"], "title": "bey", "birth": null, "birthNote": "kayıtlarda yok", "death": 1303, "deathNote": "1303 civarında Uluborlu'da vefat etti.", "reign": [1300, 1303], "reignNote": "Uluborlu'da 'es-Sultân Hamîd' unvanıyla zikredilen kurucu ulu beydir.", "summary": "Hamîdoğulları Beyliği'nin isim babası ve kurucusudur. 1297'de Uluborlu'yu merkez yaparak bağımsızlığını ilan etmiş, III. Alâeddin Keykubad ve Gāzân Han adına sikkeler kestirmiştir.", "traits": ["kurucu", "teşkilatçı"], "contribution": "Isparta ve Burdur bölgesinde beyliğin temellerini atmıştır.", "harm": "", "wives": [], "children": [{"name": "İlyas Bey", "mother": "", "note": "Halefi", "certainty": "kesin"}], "wars": [{"name": "Uç Türkmen İsyanları", "when": "1291-1297", "foe": "İlhanlı Geyhatu ve Selçuklu merkezi", "result": "belirsiz", "note": "Davras dağlarına çekilerek varlığını korudu ve Uluborlu'da istiklâl kazandı."}], "legends": [], "sources": [{"title": "TDV İslâm Ansiklopedisi, HAMÎDOĞULLARI", "url": "https://islamansiklopedisi.org.tr/hamidogullari"}]}, {"id": "hamid-ilyas-bey", "name": "İlyas Bey", "aliases": ["İlyas b. Hamîd"], "title": "bey", "birth": null, "birthNote": "kayıtlarda yok", "death": 1307, "deathNote": "1307 civarında Uluborlu'da vefat etti.", "reign": [1303, 1307], "reignNote": "Hamîd Bey'in ardından Uluborlu'da beyliğin idaresini yürütmüştür.", "summary": "Hamîd Bey'in oğludur. Gönen ve Keçiborlu bölgesindeki vakıf ve iskân faaliyetlerini yürütmüş, beyliğin idaresini oğlu Dündar Bey'e devretmiştir.", "traits": [], "contribution": "Bölgede derviş zâviyeleri açarak iskânı pekiştirdi.", "harm": "", "wives": [], "children": [{"name": "Feleküddin Dündar Bey", "mother": "", "note": "Halefi, ulu bey", "certainty": "kesin"}, {"name": "Yûnus Bey", "mother": "", "note": "Antalya emiri, Teke kolu kurucusu", "certainty": "kesin"}, {"name": "Ferhad Bey", "mother": "", "note": "Uluborlu emiri", "certainty": "kesin"}], "wars": [], "legends": [], "sources": [{"title": "TDV İslâm Ansiklopedisi, HAMÎDOĞULLARI", "url": "https://islamansiklopedisi.org.tr/hamidogullari"}]}, {"id": "hamid-felekuddin-dundar-bey", "name": "Feleküddin Dündar Bey", "aliases": ["Dündar Bey"], "title": "sultan", "birth": null, "birthNote": "kayıtlarda yok", "death": 1326, "deathNote": "1326'da Antalya'da İlhanlı valisi Demirtaş'ın eline geçerek katledildi.", "reign": [1307, 1326], "reignNote": "Başkenti Eğridir'e (Felekâbâd) taşımış, sultan unvanını kullanmıştır.", "summary": "Hamîdoğulları'nın en kudretli beyidir. Başkenti Eğridir'e nakledip Felekâbâd adını vermiş, Burdur Ulucamii ve Dündar Bey Medresesi'ni yaptırmıştır. Antalya'yı fethederek kardeşi Yûnus'a vermiş, 1326'da Moğol valisi Demirtaş tarafından öldürülmüştür.", "traits": ["fatih", "büyük imar hamisi", "cesur"], "contribution": "Burdur Ulucamii (1300) ve Eğridir Taşmedrese'yi (1301) yaptırdı; Antalya'yı Türk topraklarına kattı.", "harm": "Demirtaş karşısında tutunamayarak öldürülmesi beylikte geçici dağılmaya yol açtı.", "wives": [], "children": [{"name": "Mübârizüddin İshak Bey", "mother": "", "note": "Halefi", "certainty": "kesin"}, {"name": "Çelebi Mehmed Bey", "mother": "", "note": "Gölhisar emiri", "certainty": "kesin"}], "wars": [{"name": "Antalya'nın Zaptı", "when": "1316-1320", "foe": "Yerel Rum hâkimi ve Latinler", "result": "zafer", "note": "Antalya fethedildi ve kardeşi Yûnus Bey'e bırakıldı."}, {"name": "Demirtaş İstilası", "when": "1326", "foe": "İlhanlı genel valisi Demirtaş Noyan", "result": "yenilgi", "note": "Eğridir işgal edildi, Dündar Bey Antalya'ya kaçtı ve öldürüldü."}], "legends": [], "sources": [{"title": "TDV İslâm Ansiklopedisi, HAMÎDOĞULLARI", "url": "https://islamansiklopedisi.org.tr/hamidogullari"}, {"title": "TDV İslâm Ansiklopedisi, FELEKÜDDİN DÜNDAR BEY", "url": "https://islamansiklopedisi.org.tr/felekuddin-dundar-bey"}]}, {"id": "hamid-ishak-bey", "name": "Mübârizüddin İshak Bey", "aliases": ["Ebû İshak Bey"], "title": "sultan", "birth": null, "birthNote": "kayıtlarda yok", "death": 1344, "deathNote": "1344 civarında Eğridir'de vefat etti.", "reign": [1328, 1344], "reignNote": "Demirtaş'ın katlinden sonra Mısır'dan dönerek idareyi devralmıştır; İbn Battûta 1333'te onu ziyaret etmiştir.", "summary": "Dündar Bey'in oğludur. Babasının intikamını almak için Mısır'a gitmiş, Memlük sultanının Demirtaş'ı idam etmesinden sonra Eğridir'e dönerek beyliğin başına geçmiştir. İbn Battûta seyahatnamesinde onun dindarlığını ve misafirperverliğini anlatır.", "traits": ["dindar", "âlimperver"], "contribution": "Beyliği Moğol tahribatından sonra yeniden toparladı.", "harm": "", "wives": [], "children": [{"name": "Bedreddin Hızır Bey", "mother": "", "note": "Oğlu ve halefi", "certainty": "kesin"}], "wars": [], "legends": [], "sources": [{"title": "TDV İslâm Ansiklopedisi, HAMÎDOĞULLARI", "url": "https://islamansiklopedisi.org.tr/hamidogullari"}]}, {"id": "hamid-bedreddin-hizir-bey", "name": "Bedreddin Hızır Bey", "aliases": ["Hızır Bey b. İshak"], "title": "bey", "birth": null, "birthNote": "kayıtlarda yok", "death": 1358, "deathNote": "1358 civarında tahttan çekilmiş, 1364'te hacca gitmiştir.", "reign": [1344, 1358], "reignNote": "1326-1328 arası naiblik yapmış, 1344-1358 arası ulu bey olarak hüküm sürmüştür.", "summary": "İshak Bey'in oğludur. Demirtaş'ın çekilmesinin ardından Eşrefoğulları'na ait Beyşehir ve Seydişehir'i beylik sınırlarına katmıştır. Isparta ve Eğridir'de kendi adıyla anılan ulu camiler inşa ettirmiştir.", "traits": ["âdil", "dindar", "faziletli"], "contribution": "Isparta Hızır Bey Camii ile Eğridir Hızır Bey Camii'ni (Büyük Cami) inşa ettirdi.", "harm": "", "wives": [], "children": [], "wars": [{"name": "Eşrefoğlu Topraklarının İlhâkı", "when": "1327-1328", "foe": "Eşrefoğlu bakiyesi kuvvetler", "result": "zafer", "note": "Beyşehir, Seydişehir, Akşehir ve Doğanhisar Hamîd topraklarına katıldı."}], "legends": ["Adına Türkçe Kur'an tefsirleri (Mülk, İhlâs, Yâsin) yazılmıştır."], "sources": [{"title": "TDV İslâm Ansiklopedisi, HAMÎDOĞULLARI", "url": "https://islamansiklopedisi.org.tr/hamidogullari"}]}, {"id": "hamid-husameddin-ilyas-bey", "name": "Hüsâmeddin İlyas Bey", "aliases": ["İlyas Bey"], "title": "bey", "birth": null, "birthNote": "kayıtlarda yok", "death": 1375, "deathNote": "1375'ten önce vefat etti.", "reign": [1358, 1375], "reignNote": "Mustafa Bey'in oğludur; Hızır Bey'in tahttan çekilmesiyle idareyi almıştır.", "summary": "Kıbrıs Krallığı'nın Antalya işgaline karşı Tekeoğulları'na yardım etmiş, 1367 Gorigos seferine katılmıştır. Karamanoğlu Alâeddin Bey'in saldırısı üzerine Eğridir'den kaçıp Germiyan ve Osmanlı'ya sığınmış, I. Murad'ın yardımıyla tahtını geri almıştır.", "traits": ["muharip", "ittifakçı"], "contribution": "Kendi adına 'Hüsâmî' ibareli sikkeler darbettirdi.", "harm": "Karamanlılar Eğridir'i tahrip etti ve beylik iki yıl işgal altında kaldı.", "wives": [], "children": [{"name": "Kemâleddin Hüseyin Bey", "mother": "", "note": "Halefi, ulu bey", "certainty": "kesin"}], "wars": [{"name": "Gorigos Seferi", "when": "1367", "foe": "Kıbrıs Krallığı ordusu", "result": "sonucsuz", "note": "Birleşik Türkmen ordusu kaleyi kuşattıysa da Kıbrıs donanmasının yetişmesiyle geri çekilindi."}, {"name": "Felekâbâd Savaşı ve Karaman İstilası", "when": "1370 civarı", "foe": "Karamanoğlu Alâeddin Ali Bey", "result": "yenilgi", "note": "Eğridir düştü; İlyas Bey Germiyan ve Osmanlı yardımıyla iki yıl sonra geri aldı."}], "legends": [], "sources": [{"title": "TDV İslâm Ansiklopedisi, HAMÎDOĞULLARI", "url": "https://islamansiklopedisi.org.tr/hamidogullari"}]}, {"id": "hamid-kemaleddin-huseyin-bey", "name": "Kemâleddin Hüseyin Bey", "aliases": ["Hüseyin Bey"], "title": "bey", "birth": null, "birthNote": "kayıtlarda yok", "death": 1391, "deathNote": "1391 civarında vefat ettiği kabul edilir.", "reign": [1375, 1391], "reignNote": "Hamîdoğulları'nın son müstakil ulu beyidir.", "summary": "Karamanoğulları tehdidi karşısında I. Murad'a yanaşmış, 1381-1382'de Akşehir, Beyşehir, Seydişehir, Yalvaç ve Şarkîkaraağaç'ı 80.000 altın karşılığında Osmanlı Devleti'ne satmıştır. 1389 Kosova Savaşı'na 2000 kişilik okçu birliği yollamış, 1391'de Yıldırım Bayezid'in kalan toprakları ilhakıyla beylik sona ermiştir.", "traits": ["tedbirli diplomat"], "contribution": "Kosova Savaşı'na gönderdiği okçular Osmanlı zaferinde kritik rol oynamıştır.", "harm": "Topraklarının büyük kısmını satarak beyliği zayıflatmış, geriye kalan yurt da Osmanlıya ilhak edilmiştir.", "wives": [], "children": [{"name": "Mustafa Çelebi", "mother": "", "note": "Kosova'ya birlik götüren oğlu, sonra Osmanlı hizmetine girdi", "certainty": "kesin"}], "wars": [{"name": "Kosova Meydan Muharebesi", "when": "1389", "foe": "Haçlı İttifakı (Sırp Despotluğu ve müttefikleri)", "result": "zafer", "note": "Oğlu kumandasında gönderdiği 2000 okçu Osmanlı ordusunda savaştı."}], "legends": [], "sources": [{"title": "TDV İslâm Ansiklopedisi, HAMÎDOĞULLARI", "url": "https://islamansiklopedisi.org.tr/hamidogullari"}, {"title": "Britannica, Hamid Dynasty", "url": "https://www.britannica.com/topic/Hamid-dynasty"}]}]}, {"id": "saruhan", "name": "Saruhanoğulları Beyliği", "short": "Saruhan", "aliases": ["Saruhan Beyliği", "Saruhanoğulları"], "region": "anadolu", "start": 1300, "end": 1410, "startNote": "Saruhan Bey 1300'lerin başında Gediz havzasında faaliyete başlamış, 1313 civarında Manisa'yı fethederek başkent yapmıştır.", "endNote": "1390'da Yıldırım Bayezid ilk ilhakı gerçekleştirdi; 1402 Ankara Savaşı sonrası yeniden ihya edilen beylik, Çelebi Mehmed'in 1406-1410 seferleriyle kesin olarak Osmanlı yönetimine bağlandı.", "capital": "Manisa", "religion": "İslâm", "confidence": "kayit", "confidenceNote": "Beyliğin varlığı, sikkeleri, vakfiyeleri ve çağdaş Bizans ile Osmanlı kaynaklarında etraflıca belgelenmiştir.", "summary": "Gediz vadisi ve Manisa çevresinde kurulan denizci Türkmen beyliğidir. Ege Denizi'nde Aydınoğulları ile ittifak kurarak donanmasıyla Trakya, Eğriboz ve Mora kıyılarına gazalar düzenlemiş, Foça Cenevizlilerini haraca bağlamıştır. Muzafferüddin İshak Çelebi döneminde Manisa'da zengin mimari eserler bırakmış, Fetret Devri sonrasında Osmanlı Devleti'ne bağlanmıştır.", "legacy": "Manisa ve Gediz havzasını mamur bir Türk yurdu haline getirmiştir. Manisa Ulucamii ve Mevlevîhânesi Türk mimarisinin özgün Beylikler dönemi başyapıtları arasında yer alır.", "essay": ["Saruhanoğulları Beyliği, XIII. yüzyıl sonunda Anadolu Selçuklu uç beyi Saruhan Bey tarafından Manisa merkezli olarak kurulmuştur. Gediz ovasını süratle fetheden Saruhan Bey, 1313 civarında Manisa Kalesi'ni ele geçirmiş ve Ege Denizi'ne açılarak denizci bir devlet hüviyeti kazanmıştır.", "Saruhanoğulları, komşuları Aydınoğulları ile birlikte hareket ederek Bizans taht kavgalarına müdahil olmuş, Mora ve Trakya seferlerine donanmayla katılmıştır. Foça'daki Ceneviz kolonisi Saruhan Bey'e vergi ödemek zorunda kalmıştır. Beylik en parlak devrini imar faaliyetlerinin ve kültür hayatının zirveye çıktığı İshak Çelebi devrinde yaşamıştır.", "1390 kışında Yıldırım Bayezid'in Batı Anadolu seferi sırasında Hızır Şah şehri teslim etmiş, beylik Osmanlı idaresine geçmiştir. 1402 Ankara Savaşı'nın ardından Timur tarafından Orhan Bey'e iade edilen beylik, Fetret Devri'ndeki şehzade mücadelelerinin ardından Çelebi Mehmed tarafından kesin olarak ilhak edilmiştir."], "sources": [{"title": "TDV İslâm Ansiklopedisi, SARUHANOĞULLARI", "url": "https://islamansiklopedisi.org.tr/saruhanogullari"}, {"title": "Britannica, Anatolia", "url": "https://www.britannica.com/place/Anatolia"}], "rulers": [{"id": "saruhan-saruhan-bey", "name": "Saruhan Bey", "aliases": ["Saruhan Gazi"], "title": "bey", "birth": null, "birthNote": "kayıtlarda yok", "death": 1346, "deathNote": "1346 yılında Manisa'da vefat etti ve kendi türbesine defnedildi.", "reign": [1300, 1346], "reignNote": "Yaklaşık kırk yılı aşkın süre beyliği yönetmiştir.", "summary": "Saruhanoğulları Beyliği'nin kurucusudur. Katalanlarla mücadele etmiş, Manisa'yı fethederek başkent yapmış, Ege'de donanma kurup Foça Cenevizlilerini haraca bağlamıştır.", "traits": ["teşkilatçı", "denizci", "gazi"], "contribution": "Manisa ve Gediz vadisini fethederek güçlü bir sahil Türkmen devleti meydana getirmiştir.", "harm": "", "wives": [], "children": [{"name": "Fahreddin İlyas Bey", "mother": "", "note": "Halefi ve ulu bey", "certainty": "kesin"}, {"name": "Süleyman Bey", "mother": "", "note": "Donanma komutanı; 1345'te Trakya seferinde hummadan öldü", "certainty": "kesin"}, {"name": "Timur Bey", "mother": "", "note": "Babasının sağlığında vefat etti", "certainty": "kesin"}, {"name": "Orhan Bey", "mother": "", "note": "Kaynaklarda adı geçen oğul", "certainty": "kesin"}, {"name": "Devlet Han", "mother": "", "note": "Demirci kolu atası", "certainty": "kesin"}], "wars": [{"name": "Katalan Mücadelesi ve Manisa Kuşatması", "when": "1303-1313", "foe": "Bizans İmparatorluğu ve Katalan Bölüğü", "result": "zafer", "note": "Manisa Kalesi fethedildi."}, {"name": "Mora ve Adalar Seferleri", "when": "1332-1335", "foe": "Latin Düklükleri ve Bizans", "result": "zafer", "note": "Aydınoğulları ile birlikte Semadirek, Eğriboz ve Mora sahilleri vuruldu, Foça haraca bağlandı."}], "legends": ["Manisa fethi esnasında keçilerin boynuzlarına mum dikilerek gece yürüyüşü yapıldığı ve kalenin böyle düşürüldüğü halk rivayetidir."], "sources": [{"title": "TDV İslâm Ansiklopedisi, SARUHANOĞULLARI", "url": "https://islamansiklopedisi.org.tr/saruhanogullari"}]}, {"id": "saruhan-fahreddin-ilyas-bey", "name": "Fahreddin İlyas Bey", "aliases": ["İlyas Bey"], "title": "bey", "birth": null, "birthNote": "kayıtlarda yok", "death": 1362, "deathNote": "1358 veya 1362-1363 civarında vefat etmiş ya da tahttan feragat etmiştir.", "reign": [1346, 1362], "reignNote": "1362-1363 tarihli sikkesi mevcuttur; tahttan oğlu lehine çekilmiş olması da muhtemeldir.", "summary": "Saruhan Bey'in halefidir. Bizans taht kavgalarında donanmasıyla yer almış, Osmanlı şehzadesi Halil'in korsanlarca esir edilmesi hadisesinde Foça Kuşatması'na katılmıştır.", "traits": ["tedbirli"], "contribution": "Beyliğin Ege'deki deniz mevcudiyetini korumuştur.", "harm": "Foça Kuşatması sırasında Bizans imparatorunun tuzağına düşerek esir edilmiş, ağır fidye karşılığı kurtulabilmiştir.", "wives": [], "children": [{"name": "Muzafferüddin İshak Bey", "mother": "", "note": "Halefi, ulu bey", "certainty": "kesin"}], "wars": [{"name": "Foça Kuşatması", "when": "1355", "foe": "Foçalı Ceneviz korsanları ve Bizans", "result": "belirsiz", "note": "Şehzade Halil kurtarılmış fakat İlyas Bey Bizans tarafından rehin alınmıştır."}], "legends": [], "sources": [{"title": "TDV İslâm Ansiklopedisi, SARUHANOĞULLARI", "url": "https://islamansiklopedisi.org.tr/saruhanogullari"}]}, {"id": "saruhan-muzafferuddin-ishak-bey", "name": "Muzafferüddin İshak Bey", "aliases": ["İshak Çelebi"], "title": "çelebi", "birth": null, "birthNote": "kayıtlarda yok", "death": 1378, "deathNote": "1378-1379'da Manisa'da vefat etti ve yaptırdığı türbeye defnedildi.", "reign": [1362, 1378], "reignNote": "Saruhan Beyliği'nin en parlak imar ve kültür devridir.", "summary": "Saruhan Beyliği'nin en meşhur hükümdarıdır. Mevlevîliği benimsemiş, Osmanlılar ve Karamanoğulları ile dengeli münasebetler kurmuştur. Manisa Ulucamii ve Külliyesi ile Manisa Mevlevîhânesi'ni inşa ettirmiştir.", "traits": ["dindar", "sanatsever", "Mevlevî"], "contribution": "Manisa Ulucamii, medrese ve mevlevîhânesini yaptırarak şehri önemli bir kültür merkezi haline getirmiştir.", "harm": "", "wives": [{"name": "Gülgün Hatun", "note": "Dere Mescidi ve Yedi Kızlar Türbesi bânisi", "certainty": "kesin"}], "children": [{"name": "Orhan Bey", "mother": "", "note": "Halefi", "certainty": "kesin"}, {"name": "Hızır Şah", "mother": "", "note": "Taht mücadelesine girişen oğlu", "certainty": "kesin"}, {"name": "Saruhan b. İshak", "mother": "", "note": "1411 tarihli sikkesi bulunan oğlu", "certainty": "kesin"}], "wars": [{"name": "Gorigos Seferi", "when": "1367", "foe": "Kıbrıs Krallığı", "result": "sonucsuz", "note": "Karamanoğlu Alâeddin Ali Bey liderliğindeki Türkmen ordusuna destek birliği göndermiştir."}], "legends": [], "sources": [{"title": "TDV İslâm Ansiklopedisi, SARUHANOĞULLARI", "url": "https://islamansiklopedisi.org.tr/saruhanogullari"}]}, {"id": "saruhan-orhan-bey", "name": "Orhan Bey", "aliases": ["Orhan b. İshak"], "title": "bey", "birth": null, "birthNote": "kayıtlarda yok", "death": 1404, "deathNote": "1404 civarında kardeşi Hızır Şah ile mücadelede bertaraf edildi.", "reign": [1378, 1389], "reignNote": "1378-1389 ilk saltanatı; 1402-1404 Timur desteğinde ikinci saltanatı.", "summary": "İshak Bey'in oğludur. Kardeşi Hızır Şah ile taht kavgası yaşamış, 1389'da Kosova Savaşı'na Osmanlı vasalı olarak kuvvet yollamıştır. 1402 Ankara Savaşı sonrası Timur'dan beyliğini geri almış, 1404'te Hızır Şah tarafından indirilmiştir.", "traits": ["mücadeleci"], "contribution": "Timur devrinde beyliğin istiklâlini kısa süre yeniden canlandırmıştır.", "harm": "Kardeşiyle bitmek bilmeyen çekişmeleri beyliğin siyasî birliğini parçalamıştır.", "wives": [], "children": [], "wars": [{"name": "Kosova Meydan Muharebesi", "when": "1389", "foe": "Haçlı İttifakı (Sırplar ve müttefikleri)", "result": "zafer", "note": "Osmanlı ordusuna vasal olarak yardımcı kuvvet gönderdi."}], "legends": [], "sources": [{"title": "TDV İslâm Ansiklopedisi, SARUHANOĞULLARI", "url": "https://islamansiklopedisi.org.tr/saruhanogullari"}]}, {"id": "saruhan-hizir-sah", "name": "Hızır Şah", "aliases": ["Hızır Bey", "Hızır Paşa"], "title": "bey", "birth": null, "birthNote": "kayıtlarda yok", "death": 1406, "deathNote": "1405-1406 kışında Çelebi Mehmed tarafından Manisa'da yakalatılarak idam edildi.", "reign": [1389, 1390], "reignNote": "1389-1390 ilk dönemi; 1404-1406 ikinci beylik dönemidir.", "summary": "1390 kışında Manisa'yı Yıldırım Bayezid'e teslim ederek Osmanlı hâkimiyetini kabul etmiştir. 1404'te tekrar beyliğin başına geçmiş, Fetret Devri'nde Süleyman Çelebi'yi destekleyince Çelebi Mehmed tarafından bertaraf edilmiştir.", "traits": ["Osmanlı yanlısı politika izleyen"], "contribution": "Adala ve Kemaliye'de cami, medrese ve imaret inşa ettirmiştir.", "harm": "Fetret devrindeki yanlış taraf tercihi canına mal olmuş ve Manisa kolunu sona erdirmiştir.", "wives": [], "children": [], "wars": [{"name": "Manisa Müdafaası", "when": "1405-1406", "foe": "Çelebi Mehmed kuvvetleri", "result": "yenilgi", "note": "Çelebi Mehmed şehri zaptetti, Hızır Şah öldürüldü."}], "legends": [], "sources": [{"title": "TDV İslâm Ansiklopedisi, SARUHANOĞULLARI", "url": "https://islamansiklopedisi.org.tr/saruhanogullari"}]}, {"id": "saruhan-saruhan-b-ishak", "name": "Saruhan b. İshak", "aliases": ["II. Saruhan"], "title": "bey", "birth": null, "birthNote": "kayıtlarda yok", "death": 1412, "deathNote": "1412 civarında kayıtlardan çekilmiştir; ölüm tarihi belirsizdir.", "reign": [1410, 1412], "reignNote": "1411 (Hicrî 814) tarihli Manisa basımlı bakır sikkesi mevcuttur.", "summary": "Süleyman Çelebi'nin Rumeli'ye çekilişinden sonra Manisa'da kısa süre istiklâl alâmeti olarak adına sikke bastıran son Saruhan beyidir. Çelebi Mehmed'in bölgeyi kesin kontrolüyle hâkimiyeti sona ermiştir.", "traits": ["kısa süreli hükümdar"], "contribution": "", "harm": "", "wives": [], "children": [], "wars": [], "legends": [], "sources": [{"title": "TDV İslâm Ansiklopedisi, SARUHANOĞULLARI", "url": "https://islamansiklopedisi.org.tr/saruhanogullari"}]}]}, {"id": "aydin", "name": "Aydınoğulları Beyliği", "short": "Aydınoğulları", "aliases": ["Aydın Beyliği", "Aydın-ili", "Aydınoğlu Beyliği"], "region": "anadolu", "start": 1308, "end": 1426, "startNote": "Germiyanoğulları subaşısı Mehmed Bey 1308'de Sasa Bey'i tasfiye ederek Birgi merkezli bağımsız beyliğini kurmuştur.", "endNote": "1390'da Yıldırım Bayezid'e bağlandı; 1402 sonrası ihya edilen beylik, İzmiroğlu Cüneyd Bey'in 1426'da II. Murad tarafından idam edilmesiyle tamamen Osmanlıya katıldı.", "capital": "Birgi (daha sonra Ayasuluk ve İzmir)", "religion": "İslâm", "confidence": "kayit", "confidenceNote": "Düstûrnâme-i Enverî, çağdaş Bizans ve Latin vekayinameleri ile Osmanlı kaynaklarında en ince ayrıntısına kadar kaydedilmiştir.", "summary": "Batı Anadolu'da Küçük Menderes havzası ile Ege kıyılarında kurulan, Türk denizcilik tarihinin en kudretli beyliklerindendir. Kurucusu Mehmed Bey ve bilhassa oğlu Gazi Umur Bey döneminde yüzlerce gemilik donanmasıyla Ege, Akdeniz, Karadeniz ve Mora sahillerine akınlar düzenlemiş, Latin ve Haçlı ittifaklarını dize getirmiştir. Birgi ve Selçuk'taki anıtsal mimari eserleri ve ilim himayesiyle tanınır.", "legacy": "Gazi Umur Bey'in denizcilik destanı Türk bahriyesinin altın sayfalarındandır. Gemileri karadan yürüterek Korint Kıstağı'nı aşması strateji tarihine geçmiştir. Selçuk Îsâ Bey Camii ve Birgi Ulucamii Türk-İslâm sanatının şaheserleridir.", "essay": ["Aydınoğulları Beyliği, Germiyan subaşısı Mübârizüddin Mehmed Bey tarafından 1308 yılında Birgi merkezli olarak kurulmuştur. Mehmed Bey kısa sürede İzmir, Ayasuluk (Selçuk), Sultanhisar ve Tire'yi fethederek Küçük Menderes havzasına bütünüyle hâkim olmuş ve güçlü bir donanma inşa etmiştir.", "Beyliğin en parlak devri Gazi Umur Bey zamanıdır (1334-1348). Ege adalarını, Mora'yı, Atina Düklüğü'nü haraca bağlayan, Bizans taht kavgalarında Kantakuzenos'un en büyük müttefiki olan Umur Bey, Karadeniz'e dahi donanma sevk etmiştir. Umur Bey'in akınlarını durdurmak için Papa VI. Clement öncülüğünde kurulan Haçlı donanması 1344'te sahil İzmir'ini işgal etmiş, Umur Bey 1348'de kaleyi geri almak isterken surlar önünde şehit düşmüştür.", "Umur Bey'in ardından Hızır Bey ve Îsâ Bey dönemlerinde Venedik ve Ceneviz ile ticari dengeler gözetilmiş, 1390'da Yıldırım Bayezid'e teslim olunmuştur. Ankara Savaşı'ndan sonra beylik canlanmış, özellikle İzmiroğlu Cüneyd Bey'in Osmanlı Fetret Devri'ndeki taht mücadelelerine yön veren cüretkâr siyaseti damga vurmuştur. Nihayet 1426'da Cüneyd Bey'in tasfiyesiyle Aydın ili kesin olarak Osmanlı sancağı haline gelmiştir."], "sources": [{"title": "TDV İslâm Ansiklopedisi, AYDINOĞULLARI", "url": "https://islamansiklopedisi.org.tr/aydinogullari"}, {"title": "TDV İslâm Ansiklopedisi, UMUR BEY", "url": "https://islamansiklopedisi.org.tr/umur-bey"}, {"title": "Britannica, Aydın Dynasty", "url": "https://www.britannica.com/topic/Aydin-dynasty"}], "rulers": [{"id": "aydin-mehmed-bey", "name": "Mübârizüddin Gazi Mehmed Bey", "aliases": ["Aydınoğlu Mehmed Bey"], "title": "bey", "birth": null, "birthNote": "kayıtlarda yok", "death": 1334, "deathNote": "1334 başında Birgi'de vefat etti ve yaptırdığı türbesine defnedildi.", "reign": [1308, 1334], "reignNote": "Beyliğin kurucusu ve ilk ulu beyidir.", "summary": "Germiyan ordusunda subaşı iken Aydın-ilini Bizans'tan fethedip Birgi merkezli beyliği kurmuştur. Ayasuluk'ta donanma kurup Sakız ve İzmir'i ele geçirmiş, beyliği oğulları arasında paylaştırmıştır.", "traits": ["teşkilatçı", "fatih", "âdil"], "contribution": "Aydınoğulları Beyliği'ni kurdu, Birgi Ulucamii ve Külliyesi'ni (1312) inşa ettirdi.", "harm": "", "wives": [], "children": [{"name": "Hızır Bey", "mother": "", "note": "Ayasuluk hâkimi, daha sonra ulu bey", "certainty": "kesin"}, {"name": "Gazi Umur Bey", "mother": "", "note": "İzmir hâkimi, ikinci ulu bey", "certainty": "kesin"}, {"name": "İbrâhim Bahadır Bey", "mother": "", "note": "Bodamya hâkimi", "certainty": "kesin"}, {"name": "Süleyman Bey", "mother": "", "note": "Tire hâkimi", "certainty": "kesin"}, {"name": "Îsâ Bey", "mother": "", "note": "Küçük oğlu, dördüncü ulu bey", "certainty": "kesin"}], "wars": [{"name": "Birgi ve Aydın-ili Fetihleri", "when": "1308", "foe": "Bizans İmparatorluğu ve Sasa Bey", "result": "zafer", "note": "Birgi, Tire, Ayasuluk ve Sultanhisar fethedildi."}, {"name": "İzmir Limanı Kuşatması", "when": "1328-1329", "foe": "Martino Zaccaria (Ceneviz)", "result": "zafer", "note": "İzmir sahil hisarı iki buçuk yıllık kuşatmayla alındı."}], "legends": [], "sources": [{"title": "TDV İslâm Ansiklopedisi, AYDINOĞULLARI", "url": "https://islamansiklopedisi.org.tr/aydinogullari"}]}, {"id": "aydin-umur-bey", "name": "Gazi Umur Bey", "aliases": ["Umur Paşa", "Aydınoğlu Umur Bey", "Bahaüddin Umur"], "title": "paşa", "birth": 1309, "birthNote": "Düstûrnâme'ye göre 709 (1309-10) Birgi doğumludur.", "death": 1348, "deathNote": "1348 ilkbaharında İzmir sahil kalesini Haçlılardan geri almak için savaşırken surlar önünde okla şehit düştü.", "reign": [1334, 1348], "reignNote": "Aydınoğulları'nın en meşhur hükümdarı ve deniz gazisidir.", "summary": "Türk denizcilik tarihinin en efsanevî amiral ve devlet adamlarındandır. Yüzlerce gemilik donanmasıyla Ege adaları, Mora, Atina, Trakya ve Karadeniz'e seferler düzenlemiş, Korint Kıstağı'nda gemileri karadan yürütmüştür. 1344'te İzmir'e yerleşen Haçlı İttifakı'na karşı kaleyi kuşatırken şehit olmuştur.", "traits": ["büyük amiral", "korkusuz", "gaza aşığı", "askerî deha"], "contribution": "Ege Denizi'ni bir Türk gölü haline getirmiş, Batı Anadolu Türk denizciliğini zirveye taşımıştır.", "harm": "1344'te Latin Haçlı İttifakı'nın İzmir Liman Kalesi'ni işgal etmesine engel olunamamıştır.", "wives": [], "children": [{"name": "Hundi Melek Hatun", "mother": "", "note": "Kızı", "certainty": "olasi"}, {"name": "Azize Melek Hatun", "mother": "", "note": "Kızı", "certainty": "olasi"}, {"name": "Gürcü Melek Hatun", "mother": "", "note": "Kızı", "certainty": "olasi"}], "wars": [{"name": "Mora ve Adalar Seferi", "when": "1335", "foe": "Latin Düklükleri ve Venedik", "result": "zafer", "note": "Eğriboz ve Mora vuruldu, Naksos dükü haraca bağlandı."}, {"name": "Karadeniz ve Tuna Seferi", "when": "1339-1340", "foe": "Bizans ve Eflak beyleri", "result": "zafer", "note": "Donanmayı Korint Kıstağı'ndan karadan aşırarak Karadeniz ve Tuna ağzına (Kili) indi."}, {"name": "Haçlı Seferi ve İzmir Savunması", "when": "1344-1345", "foe": "Haçlı İttifakı (Papalık, Venedik, Rodos Şövalyeleri, Kıbrıs)", "result": "yenilgi", "note": "Haçlılar sahil hisarını aldı; yukarı kaleyi savunan Umur Bey Haçlı ordusunu 1345'te mağlup etti."}, {"name": "İzmir Kuşatması ve Şahadeti", "when": "1348", "foe": "Rodos Şövalyeleri ve Latin müttefikleri", "result": "belirsiz", "note": "Kalenin fethi sırasında surlara tırmanırken şehit oldu."}], "legends": ["Gemileri karadan yürüten ilk Türk hükümdarı olarak Düstûrnâme-i Enverî'de menkıbeleşmiştir.", "Bizans imparatoru Kantakuzenos ile dostluğu ve imparatoriçenin ona saygısı vekayinamelerde geniş yer tutar."], "sources": [{"title": "TDV İslâm Ansiklopedisi, UMUR BEY", "url": "https://islamansiklopedisi.org.tr/umur-bey"}, {"title": "Britannica, Aydın Dynasty", "url": "https://www.britannica.com/topic/Aydin-dynasty"}]}, {"id": "aydin-hizir-bey", "name": "Hızır Bey", "aliases": ["Aydınoğlu Hızır Bey"], "title": "bey", "birth": null, "birthNote": "kayıtlarda yok", "death": 1360, "deathNote": "1360 civarında Ayasuluk'ta vefat etti.", "reign": [1348, 1360], "reignNote": "Umur Bey'in şehadeti üzerine büyük ağabeyi olarak tahta geçti.", "summary": "Umur Bey'in şehadetinin ardından beyliğin başına geçmiş, Latinlerle ağır şartlar içeren 1348 barışını imzalamak zorunda kalmıştır. Ancak kısa sürede toparlanarak Venedik ve Cenova rekabetinden istifadeyle 1353'te üstün şartlarda yeni antlaşmalar akdetmiştir.", "traits": ["diplomat", "sabırlı"], "contribution": "Haçlı baskısını diplomatik antlaşmalar ve ticaret tavizleriyle savuşturarak beyliği toparlamıştır.", "harm": "1348 antlaşmasıyla liman gelirlerinin yarısı geçici olarak Latinlere terk edilmiştir.", "wives": [], "children": [], "wars": [{"name": "Girit ve Ege Deniz Seferi", "when": "1350", "foe": "Venedik Cumhuriyeti", "result": "zafer", "note": "Venedik 1353'te Aydın şartlarını kabule mecbur kaldı."}], "legends": [], "sources": [{"title": "TDV İslâm Ansiklopedisi, AYDINOĞULLARI", "url": "https://islamansiklopedisi.org.tr/aydinogullari"}]}, {"id": "aydin-isa-bey", "name": "Îsâ Bey", "aliases": ["Aydınoğlu Îsâ Bey"], "title": "bey", "birth": null, "birthNote": "kayıtlarda yok", "death": 1390, "deathNote": "1390'da Tire'de Osmanlı gözetiminde inzivaya çekildi ve kısa süre sonra vefat etti.", "reign": [1360, 1390], "reignNote": "Otuz yıla yakın hüküm sürmüş, 1390'da Yıldırım Bayezid'e itaat arz etmiştir.", "summary": "Aydınoğulları'nın ilim ve sanat hamisi hükümdarıdır. Selçuk'taki meşhur Îsâ Bey Camii'ni yaptırmıştır. Osmanlılarla dostane geçinmiş, 1389 Kosova Savaşı'na asker göndermiş, 1390'da Yıldırım Bayezid'e tâbi olarak Tire'de ikamete çekilmiştir.", "traits": ["âlimperver", "edip", "mütevazı"], "contribution": "Selçuk Îsâ Bey Camii'ni (1375) inşa ettirdi; Hacı Paşa gibi tıp âlimlerini ve ediplerini sarayında himaye etti.", "harm": "1390'da beyliğin bağımsızlığı sona erdi ve topraklar Osmanlı idaresine girdi.", "wives": [], "children": [{"name": "Mûsâ Bey", "mother": "", "note": "1402'de beyliği devralan oğlu", "certainty": "kesin"}, {"name": "II. Umur Bey", "mother": "", "note": "Mûsâ'dan sonra tahta geçen oğlu", "certainty": "kesin"}, {"name": "Hafsa Hatun", "mother": "", "note": "Yıldırım Bayezid ile evlenen kızı", "certainty": "kesin"}], "wars": [{"name": "Kosova Meydan Muharebesi", "when": "1389", "foe": "Haçlı İttifakı", "result": "zafer", "note": "I. Murad ordusuna vasal olarak yardımcı birlik gönderdi."}], "legends": [], "sources": [{"title": "TDV İslâm Ansiklopedisi, AYDINOĞULLARI", "url": "https://islamansiklopedisi.org.tr/aydinogullari"}]}, {"id": "aydin-musa-bey", "name": "Mûsâ Bey", "aliases": ["Aydınoğlu Mûsâ"], "title": "bey", "birth": null, "birthNote": "kayıtlarda yok", "death": 1403, "deathNote": "1403'te kısa bir saltanattan sonra eceliyle vefat etti.", "reign": [1402, 1403], "reignNote": "Ankara Savaşı sonrası Timur tarafından beyliğin başına getirildi.", "summary": "Timur'un Ankara zaferinin ardından Aydın beyliğine tayin ettiği şehzadedir. Çok kısa süre hüküm sürdükten sonra vefat etmiştir.", "traits": [], "contribution": "Timur döneminde beyliğin yeniden ihyasına öncülük etti.", "harm": "", "wives": [], "children": [], "wars": [], "legends": [], "sources": [{"title": "TDV İslâm Ansiklopedisi, AYDINOĞULLARI", "url": "https://islamansiklopedisi.org.tr/aydinogullari"}]}, {"id": "aydin-ii-umur-bey", "name": "II. Umur Bey", "aliases": ["Umur b. Îsâ"], "title": "bey", "birth": null, "birthNote": "kayıtlarda yok", "death": 1405, "deathNote": "1405'te vefat etti.", "reign": [1403, 1405], "reignNote": "Kardeşi Mûsâ Bey'in ölümüyle tahta geçti.", "summary": "Mûsâ Bey'in ardından beyliğin başına geçen II. Umur Bey, akrabası Cüneyd Bey'in nüfuz kazanması üzerine onunla anlaşmak zorunda kalmış, 1405'te ölümüyle idare tamamen Cüneyd Bey'e intikal etmiştir.", "traits": ["tedbirli"], "contribution": "", "harm": "", "wives": [], "children": [], "wars": [{"name": "Ayasuluk Mücadelesi", "when": "1404", "foe": "Cüneyd Bey ve kardeşi Hasan", "result": "antlasma", "note": "Ayasuluk ve İzmir idaresi paylaşıldı."}], "legends": [], "sources": [{"title": "TDV İslâm Ansiklopedisi, AYDINOĞULLARI", "url": "https://islamansiklopedisi.org.tr/aydinogullari"}]}, {"id": "aydin-cuneyd-bey", "name": "Cüneyd Bey", "aliases": ["İzmiroğlu Cüneyd Bey"], "title": "bey", "birth": null, "birthNote": "kayıtlarda yok", "death": 1426, "deathNote": "1425-1426 kışında Sığacık Kalesi'nde teslim alındıktan sonra II. Murad'ın emriyle idam edildi.", "reign": [1405, 1426], "reignNote": "Fetret Devri ve sonrasında Osmanlı şehzadeleri arasında defalarca taraf değiştirerek bağımsızlığını korumaya çalıştı.", "summary": "İbrâhim Bahadır Bey'in oğludur. Fetret Devri'nde Süleyman Çelebi, Îsâ Çelebi, Mûsâ Çelebi, Çelebi Mehmed ve Düzmece Mustafa ile ittifak ve mücadeleler içinde beyliğini idare etmiş dâhi bir sergüzeştçidir. 1426'da II. Murad tarafından bertaraf edilerek Aydınoğulları Beyliği'ne kesin son verilmiştir.", "traits": ["cüretkâr", "fırsatçı", "askerî manevra ustası", "enerjik"], "contribution": "Aydınoğulları topraklarını genişletmiş, Alaşehir ve Salihli'yi beylik sınırlarına katmıştır.", "harm": "Devamlı isyanları ve taht kavgalarına müdahaleleri Batı Anadolu'da uzun süreli kargaşaya sebep oldu.", "wives": [], "children": [], "wars": [{"name": "Fetret Devri Şehzade Savaşları", "when": "1405-1415", "foe": "Süleyman Çelebi ve Çelebi Mehmed", "result": "antlasma", "note": "İzmir kuşatıldıktan sonra Rumeli'ye sancak beyi olarak tayin edildi."}, {"name": "Düzmece Mustafa İsyanı", "when": "1421-1422", "foe": "II. Murad kuvvetleri", "result": "antlasma", "note": "Mustafa Çelebi'nin vezirliğini yaptı, sonra II. Murad ile anlaşıp Aydın'a döndü."}, {"name": "Sığacık Kuşatması ve Sonu", "when": "1425-1426", "foe": "Osmanlı Beylerbeyi Hamza Bey", "result": "yenilgi", "note": "Kalede teslim oldu ve ailesiyle birlikte idam edildi."}], "legends": ["Tarihçi Dukas, Cüneyd Bey'in inanılmaz manevra ve kaçış maharetlerini hayranlıkla nakleder."], "sources": [{"title": "TDV İslâm Ansiklopedisi, AYDINOĞULLARI", "url": "https://islamansiklopedisi.org.tr/aydinogullari"}, {"title": "Britannica, Aydın Dynasty", "url": "https://www.britannica.com/topic/Aydin-dynasty"}]}]}, {"id": "teke", "name": "Tekeoğulları Beyliği", "short": "Teke", "aliases": ["Teke Beyliği", "Teke-ili", "Tekeoğulları"], "region": "anadolu", "start": 1321, "end": 1424, "startNote": "Hamîdoğlu Feleküddin Dündar Bey'in Antalya'yı kardeşi Yûnus Bey'e vermesi ve 1321 civarında bağımsız Teke kolunun kurulması esas alınır.", "endNote": "1391 civarında Yıldırım Bayezid Antalya'yı almış; 1402 sonrası İstanoz'da süren beylik 1423'te Osman Çelebi'nin Hamza Bey tarafından öldürülmesiyle tamamen Osmanlıya intikal etmiştir.", "capital": "Antalya (ayrıca İstanoz / Korkuteli)", "religion": "İslâm", "confidence": "kayit", "confidenceNote": "Korkuteli Sinâneddin Medresesi kitabeleri, Antalya Yivli Minare kitabeleri (1373), Memlük ve Kıbrıs Latin vekayinamelerinde kayıtlıdır.", "summary": "Antalya ve Teke yarımadasında Hamîdoğulları'nın bir kolu olarak kurulan denizci Türkmen beyliğidir. Merkezi Antalya ve yaylası İstanoz (Korkuteli) olan beylik, Doğu Akdeniz'de Kıbrıs Krallığı (Lusignanlar) ve Latin korsanlarıyla şiddetli deniz savaşları vermiştir. 1361'de Kıbrıslıların işgal ettiği Antalya'yı 1373'te Mübârizüddin Mehmed Bey (Zincirkıran) geri almıştır. II. Murad devrinde Teke Sancağı olarak Osmanlıya bağlanmıştır.", "legacy": "Antalya Yivli Minare Külliyesi'ni ihya etmiş, Zincirkıran Türbesi ve Korkuteli Sinâneddin Medresesi gibi anıtlar bırakmıştır. 'Teke Yarımadası' coğrafi adı bu beylikten kalmadır.", "essay": ["Tekeoğulları, Hamîdoğulları hânedanından Feleküddin Dündar Bey'in Antalya'yı fethedip kardeşi Yûnus Bey'e tevcih etmesiyle teşekkül eden denizci bir güney sahil beyliğidir. Antalya şehri beyliğin limanı ve kışlığı, İstanoz (Korkuteli) ise yayla merkezi olmuştur.", "Beyliğin tarihindeki en kritik hadise Kıbrıs Krallığı ile yapılan Akdeniz mücadeleleridir. Kıbrıs Kralı I. Pierre de Lusignan 1361'de ani bir baskınla zengin liman kenti Antalya'yı işgal ve yağma etmiştir. Sürgündeki Teke emiri Mübârizüddin Mehmed Bey, diğer Türkmen beylikleriyle birleşerek Kıbrıs sahillerine misilleme akınları yapmış ve nihayet 14 Mayıs 1373'te liman zincirini kırarak Antalya'yı kurtarmış, bu sebeple 'Zincirkıran' unvanını almıştır.", "Yıldırım Bayezid devrinde 1391'de Osmanlı idaresine giren Antalya, 1402 Ankara Savaşı'ndan sonra Karamanoğulları desteğinde Osman Çelebi tarafından İstanoz merkezli olarak yaşatılmaya çalışılmıştır. 1423'te Antalya'yı yeniden zaptetmek isteyen hasta Osman Çelebi, Osmanlı valisi Hamza Bey'in gece baskınında çadırında öldürülmüş ve Teke ili ebediyen Osmanlı hâkimiyetine girmiştir."], "sources": [{"title": "TDV İslâm Ansiklopedisi, TEKEOĞULLARI", "url": "https://islamansiklopedisi.org.tr/tekeogullari"}, {"title": "Britannica, Hamid Dynasty", "url": "https://www.britannica.com/topic/Hamid-dynasty"}], "rulers": [{"id": "teke-yunus-bey", "name": "Yûnus Bey", "aliases": ["Yûnus b. İlyas"], "title": "bey", "birth": null, "birthNote": "kayıtlarda yok", "death": 1324, "deathNote": "1324 civarında Antalya'da vefat etti.", "reign": [1321, 1324], "reignNote": "Ağabeyi Dündar Bey'in Antalya'yı teslim etmesiyle Tekeoğulları kolunu kurmuştur.", "summary": "Tekeoğulları Beyliği'nin kurucusudur. Hamîdoğlu İlyas Bey'in oğlu olup ağabeyi Dündar Bey tarafından Antalya emiri tayin edilmiş ve Teke kolunun temellerini atmıştır.", "traits": ["kurucu", "teşkilatçı"], "contribution": "Antalya ve Korkuteli yöresinde müstakil Teke idaresini tesis etti.", "harm": "", "wives": [], "children": [{"name": "Mahmud Bey", "mother": "", "note": "Halefi", "certainty": "kesin"}, {"name": "Sinânüddin Hızır Bey", "mother": "", "note": "İstanoz emiri, sonra ulu bey", "certainty": "kesin"}], "wars": [{"name": "Antalya'nın Fethi", "when": "1316-1321", "foe": "Bizans ve yerel Latinler", "result": "zafer", "note": "Antalya zaptedilerek hükümet merkezi yapıldı."}], "legends": [], "sources": [{"title": "TDV İslâm Ansiklopedisi, TEKEOĞULLARI", "url": "https://islamansiklopedisi.org.tr/tekeogullari"}]}, {"id": "teke-mahmud-bey", "name": "Mahmud Bey", "aliases": ["Mahmud b. Yûnus"], "title": "bey", "birth": null, "birthNote": "kayıtlarda yok", "death": 1327, "deathNote": "1327 civarında Mısır'da vefat etti.", "reign": [1324, 1327], "reignNote": "Babası Yûnus Bey'in ardından Antalya tahtına geçti.", "summary": "İlhanlı valisi Timurtaş'ın Antalya Kuşatması karşısında amcası Dündar Bey'i teslim etmek zorunda kalmış, ardından Timurtaş ile birlikte Memlükler'e sığınmıştır.", "traits": [], "contribution": "", "harm": "Amcası Dündar Bey'i Moğol valisine teslim etmesi aile içinde derin yara açtı.", "wives": [], "children": [{"name": "Mübârizüddin Mehmed Bey", "mother": "", "note": "Zincirkıran Mehmed Bey", "certainty": "kesin"}], "wars": [{"name": "Antalya Kuşatması", "when": "1326", "foe": "İlhanlı valisi Timurtaş Noyan", "result": "yenilgi", "note": "Timurtaş şehri kuşattı; Mahmud Bey amcasını teslim edip Mısır'a sığındı."}], "legends": [], "sources": [{"title": "TDV İslâm Ansiklopedisi, TEKEOĞULLARI", "url": "https://islamansiklopedisi.org.tr/tekeogullari"}]}, {"id": "teke-sinanuddin-hizir-bey", "name": "Sinânüddin Hızır Bey", "aliases": ["Hızır b. Yûnus"], "title": "bey", "birth": null, "birthNote": "kayıtlarda yok", "death": 1360, "deathNote": "1360 civarında vefat etti.", "reign": [1327, 1360], "reignNote": "Korkuteli'de 1319 tarihli Sinâneddin Medresesi kitâbesi mevcuttur; ağabeyinden sonra ulu bey oldu.", "summary": "Korkuteli'de Sinâneddin Medresesi'ni inşa ettiren, Memlük mektuplarında 'el-meclisü's-sâmî' unvanıyla anılan hükümdardır. İbn Fazlullah el-Ömerî onun 12 şehir ve 25 kaleye sahip olduğunu yazar.", "traits": ["imarperver", "saygın"], "contribution": "Korkuteli Sinâneddin Medresesi'ni (1319) yaptırdı; beyliği Moğol krizinden sonra toparladı.", "harm": "", "wives": [], "children": [], "wars": [], "legends": [], "sources": [{"title": "TDV İslâm Ansiklopedisi, TEKEOĞULLARI", "url": "https://islamansiklopedisi.org.tr/tekeogullari"}]}, {"id": "teke-dadi-bey", "name": "Dadı Bey", "aliases": ["Dadı Beg"], "title": "bey", "birth": null, "birthNote": "kayıtlarda yok", "death": 1361, "deathNote": "1361 civarında vefat etti.", "reign": [1360, 1361], "reignNote": "Kalkaşendî ve münşeat mecmualarına göre Hızır Bey'in ardından kısa süre tahtta kaldı.", "summary": "Hızır Bey'den sonra emirliğin başına geçen ve kısa süre hüküm süren Teke beyidir.", "traits": [], "contribution": "", "harm": "", "wives": [], "children": [], "wars": [], "legends": [], "sources": [{"title": "TDV İslâm Ansiklopedisi, TEKEOĞULLARI", "url": "https://islamansiklopedisi.org.tr/tekeogullari"}]}, {"id": "teke-mubarizuddin-mehmed-bey", "name": "Mübârizüddin Mehmed Bey", "aliases": ["Zincirkıran Mehmed Bey", "Kacuk Mehmed"], "title": "sultânü's-sevâhil", "birth": null, "birthNote": "kayıtlarda yok", "death": 1377, "deathNote": "1377 civarında vefat etti; oğlu Ali Bey için yaptırdığı Zincirkıran Türbesi'ne defnedildi.", "reign": [1361, 1377], "reignNote": "Latin kaynaklarında 'il Turco' diye geçer; 1373'te Antalya'yı Kıbrıslılardan geri almıştır.", "summary": "Tekeoğulları'nın en büyük hükümdarı ve deniz gazisidir. 1361'de Kıbrıs Kralı I. Pierre'in işgal ettiği Antalya'yı kurtarmak için 12 yıl mücadele etmiş, Kıbrıs sahillerine akınlar düzenlemiş ve 14 Mayıs 1373'te liman zincirini kırarak şehri geri almıştır.", "traits": ["büyük denizci", "azimkâr", "korkusuz gazi"], "contribution": "Antalya'yı Haçlı-Kıbrıs işgalinden kurtardı; Yivli Minare Camii'ni (Alâeddin Camii) tamir ettirdi, Zincirkıran Türbesi'ni (1377) inşa ettirdi.", "harm": "1361'de Antalya'nın düşüşünü engelleyemedi ve şehir büyük tahribat gördü.", "wives": [], "children": [{"name": "Ali Bey", "mother": "", "note": "Babasından önce 1377'de vefat eden şehzadesi", "certainty": "kesin"}, {"name": "Osman Çelebi", "mother": "", "note": "Halefi", "certainty": "kesin"}], "wars": [{"name": "Antalya'nın Kıbrıs Tarafından İşgali", "when": "1361", "foe": "Kıbrıs Kralı I. Pierre de Lusignan", "result": "yenilgi", "note": "Kıbrıs donanması şehri işgal ve talan etti; Mehmed Bey Korkuteli'ne çekildi."}, {"name": "Kıbrıs Seferi", "when": "1363", "foe": "Kıbrıs Krallığı", "result": "zafer", "note": "Pentaglia, Karpas ve Girne yöresi yağmalanarak esir ve ganimetle dönüldü."}, {"name": "Antalya'nın Geri Alınması", "when": "1373", "foe": "Kıbrıs garnizonu ve Latinler", "result": "zafer", "note": "Liman zinciri kırılarak kale fethedildi, cami yeniden ibadete açıldı."}], "legends": ["Liman kuleleri arasına gerilen kalın zinciri harp gemisiyle kırıp kaleye girdiği için 'Zincirkıran' namıyla anılmıştır."], "sources": [{"title": "TDV İslâm Ansiklopedisi, TEKEOĞULLARI", "url": "https://islamansiklopedisi.org.tr/tekeogullari"}]}, {"id": "teke-osman-celebi", "name": "Osman Çelebi", "aliases": ["Tekeoğlu Osman Bey"], "title": "çelebi", "birth": null, "birthNote": "kayıtlarda yok", "death": 1423, "deathNote": "1423 yılı başında İstanoz'daki ordugâh çadırında Osmanlı valisi Hamza Bey'in gece baskınında öldürüldü.", "reign": [1377, 1391], "reignNote": "1377-1391 ilk dönemi; 1402-1423 İstanoz'da Karamanoğulları himayesindeki ikinci beylik devridir.", "summary": "Tekeoğulları'nın son beyidir. Yıldırım Bayezid devrinde Antalya'yı kaybetmiş, Ankara Savaşı'ndan sonra İstanoz'a dönmüştür. 1423'te Antalya'yı geri almak için asker toplarken Osmanlı sancak beyi Hamza Bey'in ani gece baskınında katledilmiş ve beylik tarihe karışmıştır.", "traits": ["inatçı"], "contribution": "", "harm": "Antalya'yı geri alma hülyasıyla hayatını kaybetti ve beylik Osmanlı topraklarına ilhak oldu.", "wives": [], "children": [], "wars": [{"name": "Antalya Baskını", "when": "1423", "foe": "Osmanlı Sancak Beyi Hamza Bey", "result": "yenilgi", "note": "Çadırında baskına uğrayarak öldürüldü, Teke ili Osmanlı sancağı yapıldı."}], "legends": [], "sources": [{"title": "TDV İslâm Ansiklopedisi, TEKEOĞULLARI", "url": "https://islamansiklopedisi.org.tr/tekeogullari"}, {"title": "Britannica, Hamid Dynasty", "url": "https://www.britannica.com/topic/Hamid-dynasty"}]}]}, {"id": "eretna", "name": "Eretna Devleti", "short": "Eretna Devleti", "aliases": ["Âl-i Eretna", "Kadı Burhaneddin Devleti"], "region": "anadolu", "start": 1335, "end": 1398, "startNote": "Uygur asıllı İlhanlı emiri Alâeddin Eretna'nın Sivas ve Kayseri'de sultanlığını ilan etmesiyle kuruldu.", "endNote": "1398 yılında Kadı Burhaneddin'in Akkoyunlu Kara Yülük Osman Bey tarafından öldürülmesi ve Sivas'ın Osmanlı'ya teslimiyle bitti.", "capital": "Sivas ve Kayseri", "religion": "İslamiyet (Sünnî-Hanefî)", "confidence": "kayit", "confidenceNote": "Azîz b. Erdeşîr-i Esterâbâdî'nin Bezm ü Rezm eseri ve İbn Battûta seyahatnamesiyle sabittir.", "summary": "İlhanlıların Anadolu genel valisi Uygur Türkü Alâeddin Eretna tarafından Orta ve Doğu Anadolu'da (Sivas, Kayseri, Amasya, Tokat, Niğde, Erzincan) kurulan sultanlık. Eretna Bey adil yönetimi dolayısıyla halk arasında 'Köse Peygamber' lakabıyla anıldı. Devletin zayıflaması üzerine veziri ve kadısı olan büyük şair Kadı Burhaneddin Ahmed 1381'de iktidarı ele geçirerek kendi devletini kurdu ve Azerbaycan Türkçesiyle yazdığı divanıyla edebiyata damga vurdu.", "legacy": "Kadı Burhaneddin Divanı ile klasik Türk edebiyatının kurucu şaheserini armağan etti; Sivas ve Kayseri'de köşkler ve medreseler bıraktı.", "essay": ["Eretna Devleti, İlhanlı hükümdarı Ebû Said Bahadır Han'ın 1335'te vefatı üzerine Anadolu genel valisi Çobanlı Emîr Hasan-ı Küçük'ün naibi olan Uygur asıllı Alâeddin Eretna tarafından kuruldu. Eretna, 1343'te Karanbük Muharebesi'nde Moğol Çobanlı ordusunu hezimete uğratarak tam bağımsızlığını ilan etti.", "Eretna Bey'in 1352'de ölümüyle oğulları Mehmed ve Ali beyler devrinde devlet karışıklıklara sürüklendi. Bu sırada beyliğin kadısı ve veziri olan Kadı Burhaneddin Ahmed, devlet otoritesini eline alarak 1381'de Sivas'ta sultanlığını ilan etti.", "Kadı Burhaneddin, 17 yıl boyunca hem Osmanlılara (Yıldırım Bayezid), hem Karamanoğullarına hem de Akkoyunlulara karşı fırtınalı bir askeri ve siyasi mücadele yürüttü. Aynı zamanda Türk edebiyatının tuyuğ nazım şeklini zirveye taşıyan büyük bir divan şairiydi. 1398'de Akkoyunlu Kara Yülük Osman Bey tarafından pusuya düşürülüp öldürülünce Sivas halkı şehri Yıldırım Bayezid'e teslim etti."], "sources": [{"title": "TDV İslâm Ansiklopedisi, ERETNAOĞULLARI", "url": "https://islamansiklopedisi.org.tr/eretnaogullari"}, {"title": "TDV İslâm Ansiklopedisi, KADI BURHÂNEDDİN", "url": "https://islamansiklopedisi.org.tr/kadi-burhaneddin"}], "rulers": [{"id": "eretna-alaeddin", "name": "Alâeddin Eretna", "aliases": ["Eretna Bey", "Köse Peygamber"], "title": "Sultan / Alâeddin", "birth": null, "birthNote": "Kayıtlarda yok", "death": 1352, "deathNote": "Kayseri'de vefat etti, Köşk Medrese'deki türbesindedir", "reign": [1335, 1352], "reignNote": "17 yıl adaletle hüküm sürdü.", "summary": "Uygur kökenli kurucu sultan. Moğol istilasından sonra Orta Anadolu'da can ve mal emniyetini yeniden sağladı. Aşırı adil ve müşfik tabiatı sebebiyle tebaası ona 'Köse Peygamber' lakabını taktı. Kayseri'de Köşk Medrese'yi inşa ettirdi.", "traits": ["Uygur asıllı dirayetli devlet adamı", "Adalet timsali", "Halk dostu"], "contribution": "Orta Anadolu'da Moğol anarşisini bitirip barış ve zenginlik ortamı kurdu.", "harm": "Ölümünden sonra yerine yetersiz şehzadelerin kalması devleti vezirlerin eline düşürdü.", "wives": [{"name": "Tuğa Hatun", "note": "Eşi", "certainty": "kesin"}], "children": [{"name": "Gıyâseddin Mehmed", "mother": "", "note": "İkinci sultan", "certainty": "kesin"}, {"name": "Cafer", "mother": "", "note": "Şehzade", "certainty": "kesin"}], "wars": [{"name": "Karanbük Muharebesi", "when": "1343", "foe": "Çobanlı Moğol Ordusu (Şeyh Hasan)", "result": "zafer", "note": "Moğol ordusu imha edildi, Eretna tam bağımsız sultanlığını ilan etti."}], "legends": ["İbn Battûta seyahatnamesinde onun alicenaplığını, misafirperverliğini ve halkına olan şefkatini övgüyle anlatır."], "sources": [{"title": "TDV İslâm Ansiklopedisi, ERETNAOĞULLARI", "url": "https://islamansiklopedisi.org.tr/eretnaogullari"}]}, {"id": "eretna-kadi-burhaneddin", "name": "Kadı Burhaneddin", "aliases": ["Kadı Burhâneddin Ahmed"], "title": "Sultan / Kadı / Şair", "birth": 1345, "birthNote": "1345'te Kayseri'de doğdu", "death": 1398, "deathNote": "Akkoyunlu Kara Yülük Osman Bey tarafından pusuya düşürülüp şehit edildi", "reign": [1381, 1398], "reignNote": "17 yıllık kılıç ve divan saltanatı.", "summary": "Kayseri kadısı iken Eretna tahtını devralıp Sivas merkezli devlet kuran büyük şair-hükümdar. Gündüz at sırtında kılıç sallayıp gece çadırında aşk ve tasavvuf şiirleri yazdı; Türk edebiyatında tuyuğ nazım şeklinin kurucusu oldu. Yıldırım Bayezid ve Timur'a boyun eğmedi.", "traits": ["Cengaver şair", "Âlim kadı", "Yılmaz savaşçı"], "contribution": "Türk divan edebiyatına muazzam bir Divan hediye etti; Anadolu'da bağımsızlık timsali oldu.", "harm": "Sürekli savaş hali devletini ekonomik olarak yıprattı.", "wives": [], "children": [{"name": "Zeynelâbidîn", "mother": "", "note": "Kısa süre sultan ilan edildi", "certainty": "kesin"}], "wars": [{"name": "Kırkdilim Muharebesi", "when": "1392", "foe": "Osmanlı Ordusu (Şehzade Ertuğrul)", "result": "zafer", "note": "Çorum yakınlarında Osmanlı ordusu mağlup edildi, Şehzade Ertuğrul şehit düştü."}], "legends": ["'Hak yoluna can vermeyen er sayılmaz' mısrasıyla hem kılıcın hem kalemin sultanı olduğunu ispatlamıştır."], "sources": [{"title": "TDV İslâm Ansiklopedisi, KADI BURHÂNEDDİN", "url": "https://islamansiklopedisi.org.tr/kadi-burhaneddin"}]}]}, {"id": "dulkadir", "name": "Dulkadiroğulları Beyliği", "short": "Dulkadiroğulları", "aliases": ["Dulkadır Beyliği", "Zülkadir Devleti"], "region": "anadolu", "start": 1337, "end": 1522, "startNote": "Zeyneddin Karaca Bey'in Memlük Sultanı Nâsır Muhammed tarafından Elbistan Türkmen emiri tanınmasıyla kuruldu.", "endNote": "1515 Turnadağ Zaferi ve 1522'de Şehsuvaroğlu Ali Bey'in katliyle Osmanlı'ya bağlandı.", "capital": "Elbistan ve Maraş", "religion": "İslamiyet (Sünnî-Hanefî)", "confidence": "kayit", "confidenceNote": "Memlük kronikleri (Makrîzî, İbn Hacer) ve Osmanlı kaynaklarıyla sabittir.", "summary": "Oğuzların Bozok koluna mensup Türkmenler tarafından Elbistan, Maraş, Malatya, Harput ve Antep sahasında kurulan stratejik beylik. Osmanlı ile Memlük süper güçleri arasında tampon devlet rolü oynadılar. Osmanlı hanedanına çok sayıda gelin verdiler (Emine Hatun, Sitti Mükrime Hatun, Gülbahar Hatun). 1515'te Yavuz Sultan Selim'in Turnadağ Muharebesi'nde Alâüddevle Bozkurt Bey'i yenmesiyle Osmanlı hakimiyetine girdi.", "legacy": "Osmanlı padişahlarına valide sultanlar veren köklü hanedan bağı kurdu; Çukurova ve Güneydoğu Anadolu yaylalarında zengin konargöçer Türkmen kültürünü yaşattı.", "essay": ["Dulkadiroğulları, İlhanlıların Anadolu'daki hakimiyetinin çökmesi üzerine Maraş-Elbistan sahasındaki Bozok Türkmenlerini birleştiren Zeyneddin Karaca Bey tarafından 1337'de kuruldu. Memlük Devleti başlangıçta beyliği sınır muhafızı olarak tanıdı.", "Halil Bey ve Sevli Bey devirlerinde Memlüklerle çetin savaşlar yaşandı. Nasreddin Mehmed Bey döneminde Osmanlılarla akrabalık kurularak kızı Emine Hatun Çelebi Mehmed ile evlendirildi (II. Murad'ın annesi). Fatih Sultan Mehmed de Dulkadirli Süleyman Bey'in kızı Sitti Mükrime Hatun ile evlendi; Yavuz Sultan Selim'in annesi Ayşe Gülbahar Hatun da Alâüddevle'nin kızıdır.", "Son kudretli hükümdar Alâüddevle Bozkurt Bey (1480-1515), Yavuz Sultan Selim'in Çaldıran Seferi sırasında Osmanlı ikmal kollarını vurdu ve sefere katılmayı reddetti. Yavuz, Çaldıran dönüşünde 12 Haziran 1515'te Turnadağ Muharebesi'nde Alâüddevle'yi mağlup ederek öldürttü; beylik 1522'de resmen Osmanlı beylerbeyliği oldu."], "sources": [{"title": "TDV İslâm Ansiklopedisi, DULKADIROĞULLARI", "url": "https://islamansiklopedisi.org.tr/dulkadirogullari"}], "rulers": [{"id": "dulkadir-karaca-bey", "name": "Zeyneddin Karaca Bey", "aliases": ["Karaca Bey"], "title": "Bey / Emir", "birth": null, "birthNote": "Kayıtlarda yok", "death": 1353, "deathNote": "Kahire'de Memlük Sultanı tarafından idam edildi", "reign": [1337, 1353], "reignNote": "16 yıl hüküm sürdü.", "summary": "Dulkadiroğulları'nın kurucusu. Elbistan ve Maraş'ta Türkmen birliğini kurdu. Memlük ordularına karşı Düldül Dağı eteklerinde büyük zaferler kazandı; Kayseri'de Eretnaoğullarına sığındıysa da Memlüklere teslim edilip Kahire'de katledildi.", "traits": ["Cesur kurucu", "Bozok reisi"], "contribution": "İki asır yaşayacak Dulkadir beyliğinin temellerini attı.", "harm": "Memlük iç çekişmelerine aşırı müdahil olması idamına yol açtı.", "wives": [], "children": [{"name": "Halil Bey", "mother": "", "note": "İkinci bey", "certainty": "kesin"}, {"name": "Sevli Bey", "mother": "", "note": "Üçüncü bey", "certainty": "kesin"}], "wars": [{"name": "Düldül Dağı Muharebesi", "when": "1343", "foe": "Memlük Halep Valisi Yelboğa", "result": "zafer", "note": "Memlük ordusu hezimete uğratıldı."}], "legends": [], "sources": [{"title": "TDV İslâm Ansiklopedisi, DULKADIROĞULLARI", "url": "https://islamansiklopedisi.org.tr/dulkadirogullari"}]}, {"id": "dulkadir-alauddevle", "name": "Alâüddevle Bozkurt Bey", "aliases": ["Alâüddevle Bey", "Bozkurt Bey"], "title": "Bey", "birth": null, "birthNote": "Kayıtlarda yok", "death": 1515, "deathNote": "Turnadağ Meydan Muharebesi'nde savaşarak şehit düştü", "reign": [1480, 1515], "reignNote": "35 yıllık kudretli saltanat.", "summary": "Dulkadiroğullarının en meşhur hükümdarı. Kızı Ayşe Hatun'u II. Bayezid'e verdi (Yavuz Sultan Selim'in dedesidir). Safevi Şahı İsmail'in Diyarbekir ve Maraş akınlarına karşı savaştı. Çaldıran'da Yavuz'a yardım etmeyip lojistiği tazyik edince 1515 Turnadağ Muharebesi'nde dört oğluyla birlikte şehit düştü.", "traits": ["Kudretli hükümdar", "İnatçı diplomat", "Yaşlı kurt"], "contribution": "Maraş Ulu Camii ve külliyelerini inşa ettirdi; beyliğe en geniş sınırlarını yaşattı.", "harm": "Osmanlı ile Safevi arasındaki dünya savaşında tarafsız kalarak beyliğinin sonunu hazırladı.", "wives": [], "children": [{"name": "Ayşe Gülbahar Hatun", "mother": "", "note": "II. Bayezid'in eşi, Yavuz Sultan Selim'in annesi", "certainty": "kesin"}, {"name": "Şahruh", "mother": "", "note": "Şehzade, gözlerine mil çekildi", "certainty": "kesin"}], "wars": [{"name": "Turnadağ Meydan Muharebesi", "when": "1515", "foe": "Osmanlı Ordusu (Hadım Sinan Paşa)", "result": "yenilgi", "note": "Alâüddevle ve dört oğlu öldürüldü, beylik fiilen sona erdi."}], "legends": ["90 yaşına yakın olmasına rağmen Turnadağ'da zırhını kuşanıp bizzat kılıç sallayarak çarpıştığı tarihe geçmiştir."], "sources": [{"title": "TDV İslâm Ansiklopedisi, DULKADIROĞULLARI", "url": "https://islamansiklopedisi.org.tr/dulkadirogullari"}]}]}, {"id": "ramazanoglu", "name": "Ramazanoğulları Beyliği", "short": "Ramazanoğulları", "aliases": ["Ramazan Beyliği", "Âl-i Ramazan"], "region": "anadolu", "start": 1352, "end": 1608, "startNote": "Ramazan Bey'in Memlükler tarafından Çukurova Türkmenleri emirliğine atanmasıyla kuruldu.", "endNote": "1608 yılında son bey Pîrîzâde Ahmed Bey'in vefatıyla beylik doğrudan Osmanlı Adana eyaleti oldu.", "capital": "Adana", "religion": "İslamiyet (Sünnî-Hanefî)", "confidence": "kayit", "confidenceNote": "Evliya Çelebi Seyahatnâmesi, Osmanlı Mühimme Defterleri ve Adana Ulu Cami kitabeleriyle sabittir.", "summary": "Oğuzların Üçok koluna mensup Yüreğir Türkmenleri tarafından Adana, Misis, Tarsus ve Ayas çevresinde kurulan beylik. 250 yılı aşkın süre Çukurova'ya hükmettiler. Osmanlı hakimiyetini Yavuz Sultan Selim devrinde gönüllü kabul ederek yurtluk-ocaklık statüsüyle iç işlerinde serbest kaldılar. Pîrî Mehmed Paşa devrinde Adana Ulu Camii ve Külliyesi gibi abidevi eserler inşa edildi.", "legacy": "Çukurova'nın tamamen Türkleşmesini sağladı; Adana Ulu Camii ve zengin Selçuklu-Memlük-Osmanlı sentezi mimari mirası bıraktı.", "essay": ["Ramazanoğulları, 14. yüzyıl ortalarında Kilikya Ermeni Krallığı'nı yıkan Yüreğir boyu reisi Ramazan Bey tarafından Adana merkezli kuruldu.", "Uzun süre Memlük himayesinde yaşayan beylik, Halil Bey ve İbrahim Bey dönemlerinde Adana'yı imar etti. 1516 yılında Yavuz Sultan Selim Mısır Seferi'ne giderken Ramazanoğlu Mahmud Bey Osmanlı'ya tam bağlılık bildirdi.", "En parlak devrini yaşayan Pîrî Mehmed Paşa (1520-1568), Kanuni Sultan Süleyman'ın yakın dostu oldu ve Adana'yı saraylar, medreseler ve camilerle donattı. 1608'de son bey Ahmed Bey'in ölümüyle beylik doğrudan Adana Beylerbeyliği'ne dönüştürüldü."], "sources": [{"title": "TDV İslâm Ansiklopedisi, RAMAZANOĞULLARI", "url": "https://islamansiklopedisi.org.tr/ramazanogullari"}], "rulers": [{"id": "ramazanoglu-ramazan-bey", "name": "Ramazan Bey", "aliases": ["Emir Ramazan"], "title": "Emir / Bey", "birth": null, "birthNote": "Kayıtlarda yok", "death": 1378, "deathNote": "Adana'da vefat etti", "reign": [1352, 1378], "reignNote": "26 yıllık kurucu beylik.", "summary": "Yüreğir boyu reisi ve beyliğin kurucusu. Çukurova'daki Ermeni krallığına ölümcül darbeler vurarak Adana'yı Türk yurdu yaptı.", "traits": ["Gazi", "Yüreğir reisi"], "contribution": "Çukurova'da 250 yıl sürecek Türk hakimiyetini kurdu.", "harm": "Kayıtlarda belirgin bir zararı geçmez.", "wives": [], "children": [{"name": "İbrâhim Bey", "mother": "", "note": "İkinci bey", "certainty": "kesin"}], "wars": [{"name": "Çukurova Fethi", "when": "1352-1360", "foe": "Kilikya Ermeni Krallığı", "result": "zafer", "note": "Adana ve Tarsus fethedildi."}], "legends": [], "sources": [{"title": "TDV İslâm Ansiklopedisi, RAMAZANOĞULLARI", "url": "https://islamansiklopedisi.org.tr/ramazanogullari"}]}, {"id": "ramazanoglu-piri-mehmed", "name": "Pîrî Mehmed Paşa", "aliases": ["Ramazanoğlu Pîrî Bey"], "title": "Bey / Paşa", "birth": null, "birthNote": "Kayıtlarda yok", "death": 1568, "deathNote": "Adana'da vefat etti, türbesi Adana Ulu Camii haziresindedir", "reign": [1520, 1568], "reignNote": "48 yıllık adalet ve imar çağı.", "summary": "Ramazanoğullarının en büyük hükümdarı. Kanuni Sultan Süleyman'ın takdirini kazanarak vezirlik rütbesi aldı. Adana Ulu Camii, Yağ Camii, medreseler ve imaretler yaptırarak Adana'yı bir medeniyet merkezine çevirdi.", "traits": ["Büyük imar hamisi", "Âlim devlet adamı", "Adil"], "contribution": "Adana Ulu Camii ve Külliyesi'ni inşa ettirdi; 48 yıl boyunca Çukurova'da asayiş ve refahı sağladı.", "harm": "Kayıtlarda belirgin bir zararı geçmez.", "wives": [], "children": [{"name": "İbrahim Bey", "mother": "", "note": "Babasından sonra bey oldu", "certainty": "kesin"}], "wars": [], "legends": ["Kanuni Sultan Süleyman'ın Irak ve İran seferlerinde ordunun Çukurova'dan geçişinde sunduğu muhteşem ziyafetler seyahatnamelerde anlatılır."], "sources": [{"title": "TDV İslâm Ansiklopedisi, RAMAZANOĞULLARI", "url": "https://islamansiklopedisi.org.tr/ramazanogullari"}]}]}, {"id": "eftalit", "name": "Eftalitler (Ak Hunlar)", "short": "Ak Hunlar", "aliases": ["Eftalit Devleti", "Hephthalites", "Hayâtıla", "Sveta Huna"], "region": "diger", "start": 420, "end": 567, "startNote": "5. yüzyıl başlarında Ceyhun nehri havzasında bağımsız krallık olarak tarih sahnesine çıktılar.", "endNote": "557-567 yıllarında Göktürk (İstemi Yabgu) ve Sâsânî (Enûşirvân) ortak harekatıyla yıkıldılar.", "capital": "Balkh (Belh), Kunduz ve Bâmiyân", "religion": "Gök Tanrı inancı, Budizm, Zerdüştlük ve Şamanizm unsurları", "confidence": "tartismali", "confidenceNote": "Etnik kökenleri Türk, Doğu İrani (Hoten-Saka) veya karma bozkır federasyonu olarak akademik dünyada tartışmalıdır.", "summary": "Orta Asya, Afganistan, Horasan ve Kuzeybatı Hindistan'da hüküm süren kudretli bozkır imparatorluğu. Sâsânî İmparatorluğu'nu ağır vergilere bağladılar; 484 Herat Muharebesi'nde Sâsânî Şahı Firuz'u ordusuyla birlikte imha ettiler. Toramana ve oğlu Mihirakula devrinde Hindistan'a inerek Gupta İmparatorluğu'nu çökerttiler. 557-567 yıllarında Göktürk Kağanlığı (İstemi Yabgu) ve Sâsânîlerin ortak askeri kıskacıyla ortadan kaldırıldılar.", "legacy": "Sâsânî İmparatorluğu'nun askeri ve mali sistemini derinden etkiledi; Kuzey Hindistan'daki Gupta hakimiyetini yıkarak bölgenin siyasi ve etnik haritasını dönüştürdü.", "essay": ["Eftalitler (Ak Hunlar), Çin kaynaklarında Yeda, Arap-Fars kaynaklarında Hayâtıla, Bizans kaynaklarında Ephtalitai ve Hint kaynaklarında Huna adıyla geçer. Hun konfederasyonunun güney kolunu teşkil ettikleri kabul edilir.", "Hükümdarları Akşunvar (Khanghil) devrinde Sâsânî İmparatorluğu'na karşı büyük üstünlük sağladılar. 484 Herat Muharebesi'nde kazdıkları gizli hendek taktiğiyle Sâsânî Şahı Firuz'u ve tüm ordusunu yok ettiler; Sâsânîleri yıllık ağır haraçlara bağladılar.", "Toramana ve oğlu Mihirakula devrinde Pencap ve Ganj havzasına inen Ak Hunlar, Hindistan'ın altın çağını yaşayan Gupta İmparatorluğu'nu yıktılar. Ancak 6. yüzyıl ortasında doğudan gelen Göktürk Kağanlığı'nın kurucuları Bumın ve İstemi Yabgu, Sâsânî Şahı Enûşirvân ile anlaşarak Ak Hunları iki taraftan kuşattı ve 567'de devleti tamamen yıktı."], "sources": [{"title": "TDV İslâm Ansiklopedisi, AK HUNLAR", "url": "https://islamansiklopedisi.org.tr/ak-hunlar"}, {"title": "Britannica, Hephthalite", "url": "https://www.britannica.com/topic/Hephthalite"}], "rulers": [{"id": "eftalit-aksunvar", "name": "Akşunvar", "aliases": ["Aksuvar", "Khanghil", "Khushnavaz"], "title": "Tegin / Hükümdar", "birth": null, "birthNote": "Kayıtlarda yok", "death": 490, "deathNote": "Belh civarında vefat etti", "reign": [459, 490], "reignNote": "31 yıl boyunca Sâsânîlere kök söktürdü.", "summary": "Ak Hunların en meşhur hükümdarı. Sâsânî Şahı Firuz'u iki kez esir alıp fidye karşılığı bıraktı; üçüncü seferde 484 Herat Muharebesi'nde Firuz'u öldürüp Sâsânîleri haraca bağladı.", "traits": ["Savaş hilesi ustası", "Stratejist"], "contribution": "Ak Hun devletini Horasan ve Orta Asya'nın tartışmasız tek hakimi yaptı.", "harm": "Kayıtlarda belirgin bir zararı geçmez.", "wives": [], "children": [], "wars": [{"name": "Herat Meydan Muharebesi", "when": "484", "foe": "Sâsânî İmparatorluğu (Şah Firuz)", "result": "zafer", "note": "Kazılan gizli hendeklere düşen Sâsânî ordusu ve Şah Firuz imha edildi."}], "legends": ["Firuz'un cesedinin bulunamadığı ve parmağındaki efsanevi incinin Akşunvar'ın tacına takıldığı anlatılır."], "sources": [{"title": "TDV İslâm Ansiklopedisi, AK HUNLAR", "url": "https://islamansiklopedisi.org.tr/ak-hunlar"}]}, {"id": "eftalit-toramana", "name": "Toramana", "aliases": ["Toramana Huna"], "title": "Maha-Raca / Hükümdar", "birth": null, "birthNote": "Kayıtlarda yok", "death": 515, "deathNote": "Kuzey Hindistan seferinde vefat etti", "reign": [495, 515], "reignNote": "20 yıl boyunca Hindistan içlerine hükmetti.", "summary": "Ak Hunların Hindistan fatihi. Pencap, Racastan, Keşmir ve Gucerat'ı fethederek Gupta İmparatorluğu'nu yıktı; kendi adına madeni paralar bastırdı.", "traits": ["Fatih", "Sert komutan"], "contribution": "Ak Hun sınırlarını Ganj havzasına kadar ulaştırdı.", "harm": "Hint tapınaklarına yönelik sert tutumu yerel direnişi körükledi.", "wives": [], "children": [{"name": "Mihirakula", "mother": "", "note": "Halefi, Budist kaynaklarınca 'Hindistan'ın Attila'sı' sayılır", "certainty": "kesin"}], "wars": [{"name": "Kuzey Hindistan Seferleri", "when": "500-510", "foe": "Gupta İmparatorluğu", "result": "zafer", "note": "Gupta orduları dağıtıldı, orta Hindistan vergiye bağlandı."}], "legends": [], "sources": [{"title": "TDV İslâm Ansiklopedisi, AK HUNLAR", "url": "https://islamansiklopedisi.org.tr/ak-hunlar"}]}]}, {"id": "ilhanli", "name": "İlhanlılar", "short": "İlhanlı", "aliases": ["İlhanlı Devleti", "Hülagû Devleti", "Moğol İlhanlıları"], "region": "diger", "start": 1256, "end": 1335, "startNote": "1253 kurultayında Mengü Han kardeşi Hülagû'yu Batı'ya görevlendirdi; devletin kuruluşu 1256 Alamut ve Tebriz merkezli idareyle başlar. 1295'ten itibaren Gazan Mahmud ile tam bağımsız hale geldi.", "endNote": "Ebu Said Bahadır'ın 1335'te çocuksuz ölümüyle merkezî otorite çöktü. 1335-1357 arasında Arpa Kağan, Satıbey Hatun, Süleyman ve Anuşirvan gibi isimler kâğıt üstünde han kaldı; ülke Celâyirîler, Muzafferîler, Serbedârîler ve diğer yerel hanedanlara bölündü.", "capital": "Tebriz, Meraga, Sultaniye", "religion": "Önce Şamanist-Budist Moğol geleneği; 1295'te Gazan Mahmud ile Sünni İslam devlet dini, 1309'dan sonra Olcaytu Şiiliğe meyletti", "confidence": "kayit", "summary": "Cengiz'in torunu Hülagû'nun İran, Irak, Kafkasya ve Anadolu'yu yönettiği Moğol hanedanıdır. 1258'de Bağdat'ı alıp Abbasi hilafetini yıktı, 1260 Aynicâlût'ta Memlüklere yenildi. Gazan Mahmud döneminde İslamlaştı ve İran'da vergi, para ve yazı reformlarıyla merkezî bir devlet kurdu; 1335'te hızla çözüldü.", "legacy": "İran'da Moğol sonrası idari düzeni, Reşîdüddin Fazlullah'ın Câmiu't-Tevârîh gibi eserleri ve Anadolu'da ağır Moğol tahakkümünü bıraktı. Hanedan Moğol, fakat ordu ve bürokrasisi Türk ve İranlıydı; Kartlılar, Eretna ve Anadolu beylikleri bu çözülmeden doğdu.", "essay": ["İlhanlılar Moğol hanedanıdır; Türk devleti sayılmaz. Hanedanın çekirdek ordusu ve birçok emiri Türk kökenliydi, hanedan ise son yüzyılda Türk ve İran kültürüne iyice karıştı. Bu yüzden atlasta ayrı renkte, ilişkili yapı olarak durur.", "Hülagû 1258'de Bağdat'ı kuşatıp son Abbasi halifesini öldürttü. İki yıl sonra Ketboğa Noyan kumandasındaki Moğol ordusu Aynicâlût'ta Memlük sultanı Kutuz'a yenildi; Moğol yayılması burada durdu. Anadolu ise 1243 Kösedağ'dan sonra zaten vergiye bağlıydı ve İlhanlılar burada valiler ve emirler üzerinden baskı kurdu.", "Gazan Mahmud 1295'te Müslüman oldu ve devletin dinini değiştirdi; Reşîdüddin ile yürüttüğü reformlar ikta, vergi ve haberleşme düzenini yeniden kurdu. Onun ve Olcaytu'nun dönemi İran'da Memlüklerle sınır savaşları, Suriye seferleri ve yoğun imarla geçti.", "1335 sonrası İlhanlı tarihi hanların adı kaldı, gücü kalmadı dönemidir. Bu boşlukta Anadolu'da beylikler, Azerbaycan'da Celâyirîler, batı İran'da Muzafferîler ve Serbedârîler ortaya çıktı."], "sources": [{"title": "TDV İslâm Ansiklopedisi, İLHANLILAR", "url": "https://islamansiklopedisi.org.tr/ilhanlilar"}, {"title": "TDV İslâm Ansiklopedisi, TÜRK", "url": "https://islamansiklopedisi.org.tr/turk"}], "rulers": [{"id": "ilhanli-hulagu", "name": "Hülagû", "aliases": ["Hülegü Han"], "title": "ilhan", "birth": 1217, "birthNote": "Yaklaşık 1217; bazı kaynaklar 1218 der", "death": 1265, "deathNote": "8 Şubat 1265, Meraga yöresinde", "reign": [1256, 1265], "reignNote": "1251-1253 arasında Batı seferine memur edildi; 1256'da Alamut'un alınması ve Tebriz merkezli idare kuruluş sayılır.", "summary": "Cengiz'in torunu, Tuluy'un oğlu. İsmailîleri ve Abbasi hilafetini yıktı. 1256'da Alamut'u, 1258'de Bağdat'ı aldı; Irak, Azerbaycan ve Suriye'yi ele geçirdi. 1260 Aynicâlût yenilgisiyle batıya ilerleme durdu.", "traits": ["Moğol yasasına bağlı", "dinlere görece hoşgörülü", "bilgin ve sanatkârları koruyan saray"], "contribution": "İran merkezli Moğol idaresini kurdu, Meraga rasathanesini destekledi, kendisine bağlı devletler düzeni (Anadolu Selçuklu, Kilikya Ermenileri) oluşturdu.", "harm": "Bağdat'ın yağmalanması ve hilafetin yıkılması İslam dünyasında ağır bir kırılma yarattı. Anadolu'da vergi ve vali baskısı kalıcı hale geldi.", "wives": [{"name": "Dokuz Hatun", "note": "Keraitlerden; saraydaki etkisi kaynaklarda geçer", "certainty": "kesin"}, {"name": "Yesunçin Hatun", "note": "", "certainty": "olasi"}], "children": [{"name": "Abaka", "mother": "Yesunçin Hatun", "note": "Halef", "certainty": "kesin"}, {"name": "Teküder (Ahmed)", "mother": "", "note": "Sonradan İslam'ı kabul etti", "certainty": "kesin"}, {"name": "Mengü Timur", "mother": "", "note": "Küçük kağanlıklarda görev aldı", "certainty": "olasi"}], "wars": [{"name": "Alamut seferi", "when": "1256", "foe": "İsmailîler (Nizârîler)", "result": "zafer", "note": "Alamut Kalesi zapt edildi."}, {"name": "Bağdat kuşatması", "when": "1258", "foe": "Abbasi Hilafeti", "result": "zafer", "note": "Halife Mutasım öldürüldü, hilafet yıkıldı."}, {"name": "Aynicâlût Savaşı", "when": "3 Eylül 1260", "foe": "Memlükler (Kutuz, Baybars)", "result": "yenilgi", "note": "Ketboğa Noyan öldü; Moğol ilerleyişi Suriye'de durdu."}, {"name": "Elbistan Savaşı", "when": "1277", "foe": "Memlükler", "result": "yenilgi", "note": "Hülagû'nun ölümünden sonra Abaka dönemine aittir."}], "legends": ["Bağdat'ta Dicle'nin mürekkeple karardığı anlatısı dolaşır; kaynaklar kütüphanelerin yağmalandığını yazar, nehrin renginin değiştiği bilgisi rivayettir.", "Hülagû'nun Hristiyan ve Budist eğilimli olduğu, Müslümanlara düşmanlık beslediği yönündeki anlatılar dönemin kaynaklarında abartılı ve tektaraflıdır."], "sources": [{"title": "TDV İslâm Ansiklopedisi, İLHANLILAR", "url": "https://islamansiklopedisi.org.tr/ilhanlilar"}]}, {"id": "ilhanli-abaka", "name": "Abaka Han", "title": "ilhan", "birth": 1234, "birthNote": "Yaklaşık", "death": 1282, "deathNote": "Nisan 1282, Hamedan", "reign": [1265, 1282], "summary": "Hülagû'nun oğlu. Memlüklerle Suriye sınırında sürekli savaştı; 1277 Elbistan ve 1281 Hums yenilgileri Anadolu ve Suriye'deki Moğol otoritesini sarstı.", "traits": ["göçebe Moğol düzenine bağlı", "Hristiyan ve Budist çevrelere yakın"], "contribution": "Kafkasya ve Doğu Anadolu hattını korudu, ticaret yollarında düzen sağladı.", "harm": "Elbistan yenilgisi Anadolu'da Moğol prestijini sarstı ve Türkmen beylerinin hareket alanını açtı.", "wives": [{"name": "Maria Palaiologina (Despina Hatun)", "note": "Bizans imparatoru VIII. Mikhail'in kızı; 1265'te evlendi", "certainty": "kesin"}], "children": [{"name": "Argun", "mother": "", "note": "Halef", "certainty": "kesin"}], "wars": [{"name": "Elbistan Savaşı", "when": "1277", "foe": "Memlükler (Baybars)", "result": "yenilgi", "note": "TDV, İlhanlı ordusunun bozguna uğradığını yazar."}, {"name": "Hums Savaşı", "when": "1281", "foe": "Memlükler (Kalavun)", "result": "yenilgi", "note": "Suriye'ye yerleşme girişimi başarısız oldu."}], "legends": [], "sources": [{"title": "TDV İslâm Ansiklopedisi, İLHANLILAR", "url": "https://islamansiklopedisi.org.tr/ilhanlilar"}]}, {"id": "ilhanli-gazan", "name": "Gazan Mahmud", "aliases": ["Mahmud Gazan Han"], "title": "ilhan, sultan", "birth": 1271, "death": 1304, "deathNote": "11 Mayıs 1304", "reign": [1295, 1304], "reignNote": "1295'te Baydu'yu devirerek tahta çıktı; aynı yıl Müslüman oldu.", "summary": "Argun'un oğlu. İslam'ı devlet dini yaptı, Reşîdüddin Fazlullah ile vergi, ikta ve posta düzenini yeniledi. Suriye seferlerinde Memlükleri bir kez yendi, kalıcı başarı sağlayamadı.", "traits": ["islah ve merkezileşme", "yazılı kayıt tutmayı seven idare", "Moğol-Yasa ile İslam hukukunu birleştirme çabası"], "contribution": "İlhanlı Devleti'ni bağımsız bir İran-İslam devletine çevirdi; para, ölçü ve vergi birliği, Câmiu't-Tevârîh gibi tarih yazımı bu döneme bağlıdır.", "harm": "Reformlar emirlerin direnciyle karşılaştı; Memlük savaşları hazineyi tüketti.", "wives": [{"name": "Kökeçin Hatun", "note": "", "certainty": "olasi"}], "children": [], "wars": [{"name": "Vâdilhazindar Savaşı", "when": "1299", "foe": "Memlükler (Nâsır Muhammed)", "result": "zafer", "note": "Şam kısa süre işgal edildi."}, {"name": "Şakhab Savaşı", "when": "1303", "foe": "Memlükler", "result": "yenilgi", "note": "Suriye'ye kesin yerleşme girişimi sona erdi."}], "legends": ["Gazan'ın İslam'ı siyasi hesap için seçtiği iddiası kaynaklarda tartışılır; dindarlığı ve reform programı kendi dönemine ait belgelerle bilinir."], "sources": [{"title": "TDV İslâm Ansiklopedisi, İLHANLILAR", "url": "https://islamansiklopedisi.org.tr/ilhanlilar"}]}, {"id": "ilhanli-olcaytu", "name": "Olcaytu (Muhammed Hudâbende)", "title": "ilhan, sultan", "birth": 1280, "death": 1316, "deathNote": "16 Aralık 1316, Sultaniye", "reign": [1304, 1316], "summary": "Argun'un oğlu, Gazan'ın kardeşi. Sultaniye şehrini kurdurup başkent yaptı. İslam'da önce Sünni, sonra Şii eğilim izledi; mezhep değişikliği kalıcı olmadı.", "traits": ["imar ve şehir kurma", "uyku ve av tutkunu olarak tanımlanır", "vezir Reşîdüddin'in etkisinde"], "contribution": "Sultaniye külliyesi ve idari merkezi kurdu; İlhanlı bürokrasisini korudu.", "harm": "Mezhep değiştirme girişimi kargaşa yarattı; ardında güçlü bir merkez bırakamadı.", "wives": [{"name": "Kurduçin Hatun", "note": "", "certainty": "olasi"}], "children": [{"name": "Ebu Said Bahadır", "mother": "", "note": "Halef", "certainty": "kesin"}], "wars": [{"name": "Suriye seferleri", "when": "1312-1313", "foe": "Memlükler", "result": "sonucsuz", "note": "Sınır akınları ve karşılıklı seferler."}], "legends": [], "sources": [{"title": "TDV İslâm Ansiklopedisi, İLHANLILAR", "url": "https://islamansiklopedisi.org.tr/ilhanlilar"}]}, {"id": "ilhanli-ebusaid", "name": "Ebu Said Bahadır Han", "title": "ilhan, sultan", "birth": 1305, "death": 1335, "deathNote": "30 Kasım 1335; çocuksuz öldü", "reign": [1316, 1335], "summary": "Son güçlü İlhanlı hükümdarı. Tahta çıktığında çocuk yaştaydı; devlet Emir Çoban ve oğullarının eline geçti. Ölümüyle hanedan fiilen dağıldı.", "traits": ["genç yaşta tahta çıkma", "emirlerin gölgesinde hükümdarlık"], "contribution": "Gazan reformlarını kısmen sürdürdü; İran'da kısa bir istikrar dönemi sağladı.", "harm": "Çocuksuz ölümü veraset krizi doğurdu; İlhanlı sonrası parçalanmanın fitili bu dönemde yandı.", "wives": [{"name": "Bağdad Hatun", "note": "Emir Çoban'ın kızı; evlilik ve boşanma olayları kaynaklarda geniş yer tutar", "certainty": "kesin"}], "children": [], "wars": [{"name": "Altın Orda sınır savaşları", "when": "1319-1330", "foe": "Altın Orda", "result": "belirsiz", "note": "Kafkasya sınırında karşılıklı akınlar."}], "legends": [], "sources": [{"title": "TDV İslâm Ansiklopedisi, İLHANLILAR", "url": "https://islamansiklopedisi.org.tr/ilhanlilar"}]}, {"id": "ilhanli-satibey", "name": "Satıbey Hatun", "title": "hatun (naip hükümdar)", "birth": null, "birthNote": "kayıtlarda yok", "death": 1339, "deathNote": "Tahttan indirilip öldürüldüğü yıl", "reign": [1338, 1339], "reignNote": "İlhanlı tahtına çıkan tek kadın olarak anılır; emirler arası çekişmede kısa süre han ilan edildi.", "summary": "Olcaytu'nun kızı. 1335 sonrası emir çekişmelerinde kukla han olarak tahta çıkarıldı; bir yıldan kısa süre kaldı.", "traits": ["kısa ve sembolik saltanat"], "contribution": "Hanedan kadınlarının siyasette ağırlığını gösterir.", "harm": "Dönemin kaosunu çözemedi.", "wives": [], "children": [], "wars": [{"name": "Emirler arası çatışma", "when": "1338-1339", "foe": "İlhanlı emirleri", "result": "belirsiz", "note": "Taht kavgası savaş adıyla anılmaz."}], "legends": [], "sources": [{"title": "TDV İslâm Ansiklopedisi, İLHANLILAR", "url": "https://islamansiklopedisi.org.tr/ilhanlilar"}]}]}, {"id": "celayirli", "name": "Celâyirîler", "short": "Celâyirîler", "aliases": ["Celâyir Devleti", "Âl-i Celâyir", "Jalayirids"], "region": "diger", "start": 1335, "end": 1432, "startNote": "İlhanlıların çöküşüyle Moğol Celâyir boyundan Şeyh Hasan Büzürg'ün Bağdat ve Irak'ta hakimiyet kurmasıyla başladı.", "endNote": "1432 yılında Karakoyunluların son Celâyir sığınağı Hille'yi almasıyla sona erdi.", "capital": "Bağdat ve Tebriz", "religion": "İslamiyet (Sünnî ve Şiî unsurlar)", "confidence": "kayit", "confidenceNote": "Aynî, İbn Hacer, Hâfız-ı Ebrû ve Târîh-i Güzîde ile sabittir.", "summary": "İlhanlılar döneminde Türkleşen Moğol Celâyir boyuna mensup Şeyh Hasan Büzürg tarafından Irak ve Azerbaycan'da kurulan devlet. Sultan Üveys devrinde Tebriz'i başkent yaparak Azerbaycan ve Fars'a hükmettiler; Tebriz'de devasa Devlet-hâne sarayını yaptırdılar. Sultan Ahmed Celâyir devrinde Timur'un amansız seferlerine karşı Yıldırım Bayezid ve Memlüklere sığındılar. 1432'de Karakoyunlular tarafından yıkıldılar.", "legacy": "Bağdat ve Tebriz'de minyatür, tezhip ve şiir sanatını zirveye taşıdı; Sultan Ahmed Celâyir'in Türkçe divanı erken dönem Azerbaycan Türk edebiyatının seçkin anıtı oldu.", "essay": ["Celâyirîler, Moğol istilasıyla batıya gelen ve hızla Türk-İslam kültürünü benimseyen Celâyir boyunun reisi Emîr Hüseyin'in oğlu Şeyh Hasan Büzürg (Büyük Hasan) tarafından 1335'te Bağdat'ta kuruldu.", "Sultan Üveys (1356-1374) devrinde devlet altın çağını yaşadı. Tebriz'i zaptedip başkent yaptı; Şirvan, Diyarbekir ve Musul'u kendine bağladı. Edebiyat, musiki ve mimaride parlak eserler verildi.", "Sultan Ahmed Celâyir dönemi Timur kasırgasının gölgesinde geçti. Bağdat'ı üç kez Timur'a kaptıran Sultan Ahmed, Karakoyunlu Kara Yusuf ile birlikte Osmanlı Sultanı Yıldırım Bayezid'e sığındı (Ankara Savaşı'nın gerekçelerinden biri oldu). 1410'da Tebriz yakınlarında eski dostu Kara Yusuf ile yaptığı Esed Muharebesi'nde yenilip idam edildi; hanedanın kalıntıları 1432'de Karakoyunlularca tamamen tasfiye edildi."], "sources": [{"title": "TDV İslâm Ansiklopedisi, CELÂYİRLİLER", "url": "https://islamansiklopedisi.org.tr/celayirliler"}, {"title": "Britannica, Jalayirid dynasty", "url": "https://www.britannica.com/topic/Jalayirid"}], "rulers": [{"id": "celayirli-hasan-buzurg", "name": "Şeyh Hasan Büzürg", "aliases": ["Büyük Hasan", "Tâceddin Hasan"], "title": "Ulus Emiri / Han", "birth": null, "birthNote": "Kayıtlarda yok", "death": 1356, "deathNote": "Bağdat'ta vefat etti", "reign": [1335, 1356], "reignNote": "21 yıllık kurucu hükümdarlık.", "summary": "Celâyirîler Devleti'nin kurucusu. İlhanlıların dağılması üzerine Bağdat'ı başkent yaparak Irak'ta müstakil bir idare kurdu; Çobanlı Hasan-ı Küçük ile kanlı mücadeleler verdi.", "traits": ["Devlet kurucu emir", "Sabırlı stratejist"], "contribution": "Irak ve Mezopotamya'da Moğol anarşisini durdurup istikrarlı bir devlet kurdu.", "harm": "Çobanlılarla sürekli iç savaş Tebriz'i harabeye çevirdi.", "wives": [{"name": "Dilşad Hatun", "note": "Son İlhanlı Ebu Said'in eşi, Dımaşk Hoca'nın kızı", "certainty": "kesin"}], "children": [{"name": "Sultan Üveys", "mother": "Dilşad Hatun", "note": "Büyük hükümdar", "certainty": "kesin"}], "wars": [{"name": "Bağdat ve Irak Hakimiyeti", "when": "1340", "foe": "Çobanlılar (Hasan-ı Küçük)", "result": "zafer", "note": "Bağdat fethedilip Celâyirî başkenti yapıldı."}], "legends": [], "sources": [{"title": "TDV İslâm Ansiklopedisi, CELÂYİRLİLER", "url": "https://islamansiklopedisi.org.tr/celayirliler"}]}, {"id": "celayirli-sultan-ahmed", "name": "Sultan Ahmed Celâyir", "aliases": ["Gıyâseddin Ahmed"], "title": "Sultan / Şair", "birth": null, "birthNote": "Kayıtlarda yok", "death": 1410, "deathNote": "Tebriz yakınlarında Kara Yusuf tarafından esir alınıp idam edildi", "reign": [1382, 1410], "reignNote": "28 yıllık sürgünler ve taht kavgalarıyla dolu saltanat.", "summary": "Sultan Üveys'in oğlu. Timur'un amansız istilalarına karşı Bağdat'ı kahramanca savundu, defalarca şehri terk edip geri aldı. Türkçe divan yazan ilk hükümdar şairlerdendir. Yıldırım Bayezid'e sığınması Ankara Savaşı'nı tetikledi. Eski dostu Karakoyunlu Kara Yusuf ile taht savaşında öldü.", "traits": ["Musikişinas ve şair", "Yenilmeyen irade", "Gözü pek"], "contribution": "Türkçe ve Farsça Divanıyla erken dönem Türk şiirine şaheserler kazandırdı.", "harm": "Karakoyunlular ile uzlaşmak yerine Tebriz tahtı için savaşa tutuşması devletinin sonunu getirdi.", "wives": [], "children": [], "wars": [{"name": "Bağdat Savunması", "when": "1393 ve 1401", "foe": "Timurlu Ordusu (Timur bizzat)", "result": "yenilgi", "note": "Bağdat düştü, kafa kuleleri dikildi, sultan Memlüklere ve Osmanlı'ya kaçtı."}, {"name": "Esed Muharebesi", "when": "1410", "foe": "Karakoyunlular (Kara Yusuf)", "result": "yenilgi", "note": "Sultan esir alındı ve idam edildi."}], "legends": ["Yıldırım Bayezid'in onu Bursa'da krallar gibi ağırladığı ve Timur'un 'Ahmed ile Yusuf'u bana teslim et' tehditlerine karşı 'Sığınan misafiri teslim etmek töremizde yoktur' diyerek savaşı göze aldığı meşhurdur."], "sources": [{"title": "TDV İslâm Ansiklopedisi, CELÂYİRLİLER", "url": "https://islamansiklopedisi.org.tr/celayirliler"}]}]}]};
